bool joint_cell_less(
    std::int64_t ax, std::int64_t ay, std::int64_t az,
    std::int64_t bx, std::int64_t by, std::int64_t bz) {
    if (ax != bx) {
        return ax < bx;
    }
    if (ay != by) {
        return ay < by;
    }
    return az < bz;
}

bool joint_cell_coordinate(double value, std::int64_t& output) {
    const double coordinate = std::floor(value / HORIZON);
    const double low = static_cast<double>(
        std::numeric_limits<std::int64_t>::min() + 1);
    const double high = static_cast<double>(
        std::numeric_limits<std::int64_t>::max() - 1);
    if (!std::isfinite(coordinate)
        || coordinate < low || coordinate > high) {
        return false;
    }
    output = static_cast<std::int64_t>(coordinate);
    return true;
}

bool canonicalize_joint_points(
    const std::vector<JointPoint>& input,
    std::vector<JointPoint>& output) {
    output = input;
    std::sort(output.begin(), output.end(),
        [](const JointPoint& lhs, const JointPoint& rhs) {
            return lhs.id < rhs.id;
        });
    for (std::size_t i = 0; i < output.size(); ++i) {
        if (!finite(output[i].position)) {
            return false;
        }
        if (i > 0U && output[i - 1U].id == output[i].id) {
            return false;
        }
    }
    return true;
}

bool joint_cell_record_less(
    const JointCellRecord& lhs, const JointCellRecord& rhs) {
    if (joint_cell_less(lhs.x, lhs.y, lhs.z, rhs.x, rhs.y, rhs.z)) {
        return true;
    }
    if (joint_cell_less(rhs.x, rhs.y, rhs.z, lhs.x, lhs.y, lhs.z)) {
        return false;
    }
    return lhs.participant < rhs.participant;
}

bool joint_cell_range_less(
    const JointCellRange& lhs, const JointCellRange& rhs) {
    return joint_cell_less(
        lhs.x, lhs.y, lhs.z, rhs.x, rhs.y, rhs.z);
}

std::string joint_static_support_geometry_hash(
    const std::vector<JointPoint>& support) {
    std::ostringstream material;
    material << std::hex << "joint-static-support-geometry-r0|";
    for (const JointPoint& point : support) {
        material << point.id << ':';
        for (double value : {
                 point.position.x, point.position.y, point.position.z}) {
            std::uint64_t bits = 0U;
            std::memcpy(&bits, &value, sizeof(bits));
            material << bits << ',';
        }
        material << ';';
    }
    return sha256_hex(material.str());
}

std::string joint_static_support_layout_hash(
    const std::vector<JointCellRecord>& records,
    const std::vector<JointCellRange>& ranges) {
    std::ostringstream material;
    material << "joint-static-support-layout-r0|";
    for (const JointCellRecord& record : records) {
        material << record.x << ':' << record.y << ':' << record.z << ':'
                 << record.participant << ';';
    }
    material << '|';
    for (const JointCellRange& range : ranges) {
        material << range.x << ':' << range.y << ':' << range.z << ':'
                 << range.begin << ':' << range.end << ';';
    }
    return sha256_hex(material.str());
}

std::string joint_static_support_identity(
    const JointStaticSupportIndex& value) {
    std::uint64_t horizon_bits = 0U;
    std::memcpy(&horizon_bits, &HORIZON, sizeof(horizon_bits));
    std::ostringstream material;
    material << std::hex
             << "nextengine.nonlocal.immutable-static-support-index|v1|"
             << horizon_bits << '|' << value.support.size() << '|'
             << value.geometry_sha256 << '|' << value.layout_sha256;
    return sha256_hex(material.str());
}

JointStaticSupportIndex build_joint_static_support_index(
    const std::vector<JointPoint>& support_input,
    StaticSupportWorkTrace* work = nullptr) {
    JointStaticSupportIndex result;
    if (work != nullptr) {
        ++work->static_index_builds;
        ++work->support_canonicalizations;
    }
    if (support_input.size() > B4C0_MAX_SUPPORT) {
        result.failure = "JOINT_SUPPORT_CAPACITY";
        return result;
    }
    if (!canonicalize_joint_points(support_input, result.support)) {
        const bool all_finite = std::all_of(
            support_input.begin(), support_input.end(),
            [](const JointPoint& value) {
                return finite(value.position);
            });
        result.failure = all_finite
            ? "JOINT_DUPLICATE_ID" : "JOINT_POSITION_INVALID";
        result.support.clear();
        return result;
    }
    result.records.reserve(result.support.size());
    for (std::size_t participant = 0U;
         participant < result.support.size(); ++participant) {
        const Vec3& position = result.support[participant].position;
        JointCellRecord record;
        record.participant = participant;
        if (!joint_cell_coordinate(position.x, record.x)
            || !joint_cell_coordinate(position.y, record.y)
            || !joint_cell_coordinate(position.z, record.z)) {
            result.failure = "JOINT_POSITION_INVALID";
            result.support.clear();
            result.records.clear();
            return result;
        }
        result.records.push_back(record);
    }
    if (work != nullptr) {
        work->support_records_sorted += result.records.size();
    }
    std::sort(result.records.begin(), result.records.end(),
        joint_cell_record_less);
    result.ranges.reserve(result.records.size());
    for (std::size_t begin = 0U; begin < result.records.size();) {
        std::size_t end = begin + 1U;
        while (end < result.records.size()
            && result.records[end].x == result.records[begin].x
            && result.records[end].y == result.records[begin].y
            && result.records[end].z == result.records[begin].z) {
            ++end;
        }
        result.ranges.push_back({result.records[begin].x,
            result.records[begin].y, result.records[begin].z, begin, end});
        begin = end;
    }
    result.geometry_sha256 = joint_static_support_geometry_hash(
        result.support);
    result.layout_sha256 = joint_static_support_layout_hash(
        result.records, result.ranges);
    result.identity_sha256 = joint_static_support_identity(result);
    if (work != nullptr) {
        work->index_identity_sha256 = result.identity_sha256;
    }
    result.passed = true;
    return result;
}

bool validate_joint_static_support_index(
    const JointStaticSupportIndex& value) {
    if (!value.passed || !value.failure.empty()
        || value.support.size() > B4C0_MAX_SUPPORT
        || value.records.size() != value.support.size()) {
        return false;
    }
    std::vector<bool> seen(value.support.size());
    for (std::size_t i = 0U; i < value.support.size(); ++i) {
        if (!finite(value.support[i].position)
            || (i > 0U && value.support[i - 1U].id
                >= value.support[i].id)) {
            return false;
        }
    }
    for (std::size_t i = 0U; i < value.records.size(); ++i) {
        const JointCellRecord& record = value.records[i];
        if (record.participant >= value.support.size()
            || seen[record.participant]
            || (i > 0U
                && !joint_cell_record_less(
                    value.records[i - 1U], record))) {
            return false;
        }
        std::int64_t x = 0;
        std::int64_t y = 0;
        std::int64_t z = 0;
        const Vec3& position = value.support[record.participant].position;
        if (!joint_cell_coordinate(position.x, x)
            || !joint_cell_coordinate(position.y, y)
            || !joint_cell_coordinate(position.z, z)
            || record.x != x || record.y != y || record.z != z) {
            return false;
        }
        seen[record.participant] = true;
    }
    std::size_t next = 0U;
    for (std::size_t i = 0U; i < value.ranges.size(); ++i) {
        const JointCellRange& range = value.ranges[i];
        if (range.begin != next || range.end <= range.begin
            || range.end > value.records.size()
            || (i > 0U
                && !joint_cell_range_less(value.ranges[i - 1U], range))) {
            return false;
        }
        for (std::size_t slot = range.begin; slot < range.end; ++slot) {
            if (value.records[slot].x != range.x
                || value.records[slot].y != range.y
                || value.records[slot].z != range.z) {
                return false;
            }
        }
        next = range.end;
    }
    return next == value.records.size()
        && value.geometry_sha256
            == joint_static_support_geometry_hash(value.support)
        && value.layout_sha256
            == joint_static_support_layout_hash(
                value.records, value.ranges)
        && value.identity_sha256 == joint_static_support_identity(value);
}

JointStaticSupportBinding bind_joint_static_support_index(
    const JointStaticSupportIndex* index,
    std::string expected_identity_sha256) {
    JointStaticSupportBinding result;
    result.index = index;
    result.expected_identity_sha256 = std::move(expected_identity_sha256);
    if (index == nullptr || !index->passed) {
        result.failure = "STATIC_SUPPORT_INDEX_SOURCE";
        return result;
    }
    if (index->identity_sha256 != result.expected_identity_sha256) {
        result.failure = "STATIC_SUPPORT_INDEX_IDENTITY";
        return result;
    }
    if (!validate_joint_static_support_index(*index)) {
        result.failure = "STATIC_SUPPORT_INDEX_LAYOUT";
        return result;
    }
    result.passed = true;
    return result;
}

const Vec3& joint_position(
    const JointNeighborhood& value, std::size_t participant) {
    if (participant < value.fluid.size()) {
        return value.fluid[participant].position;
    }
    return value.support[participant - value.fluid.size()].position;
}

std::size_t checked_joint_pair_limit(std::size_t fluid) {
    if (fluid > std::numeric_limits<std::size_t>::max()
            / B4C0_MAX_NEIGHBORS) {
        return 0U;
    }
    return fluid * B4C0_MAX_NEIGHBORS;
}

std::size_t joint_pair_participant(
    const JointNeighborhood& neighborhood,
    const JointPair& pair,
    std::size_t center) {
    if (pair.fluid == center) {
        return pair.participant;
    }
    if (pair.participant < neighborhood.fluid.size()
        && pair.participant == center) {
        return pair.fluid;
    }
    return neighborhood.fluid.size() + neighborhood.support.size();
}

bool finalize_joint_adjacency(
    JointNeighborhood& result,
    const std::vector<std::size_t>& degree,
    bool flat_adjacency,
    FlatAdjacencyWorkTrace* adjacency_work) {
    if (adjacency_work != nullptr) {
        ++adjacency_work->workspace_builds;
    }
    if (!flat_adjacency) {
        result.adjacency.resize(result.fluid.size());
        for (std::size_t center = 0U;
             center < result.fluid.size(); ++center) {
            result.adjacency[center].reserve(degree[center]);
        }
        for (const JointPair pair : result.pairs) {
            result.adjacency[pair.fluid].push_back(pair.participant);
            if (pair.participant < result.fluid.size()) {
                result.adjacency[pair.participant].push_back(pair.fluid);
            }
        }
        for (std::vector<std::uint32_t>& row : result.adjacency) {
            std::sort(row.begin(), row.end());
        }
        if (adjacency_work != nullptr) {
            adjacency_work->nested_row_objects += result.fluid.size();
            adjacency_work->nested_row_sorts += result.fluid.size();
            for (const std::vector<std::uint32_t>& row : result.adjacency) {
                adjacency_work->nested_participant_records += row.size();
            }
        }
        return true;
    }

    std::size_t directed = 0U;
    for (std::size_t value : degree) {
        if (value > std::numeric_limits<std::size_t>::max() - directed) {
            result.failure = "JOINT_PAIR_CAPACITY";
            return false;
        }
        directed += value;
    }
    if (directed > std::numeric_limits<std::uint32_t>::max()
        || result.fluid.size() >= std::numeric_limits<std::uint32_t>::max()) {
        result.failure = "JOINT_PAIR_CAPACITY";
        return false;
    }
    result.flat_adjacency = true;
    result.flat_offsets.resize(result.fluid.size() + 1U);
    result.flat_directed_pair_indices.resize(directed);
    std::size_t offset = 0U;
    for (std::size_t center = 0U;
         center < result.fluid.size(); ++center) {
        result.flat_offsets[center] = static_cast<std::uint32_t>(offset);
        offset += degree[center];
    }
    result.flat_offsets[result.fluid.size()] =
        static_cast<std::uint32_t>(offset);
    std::vector<std::size_t> cursor(result.fluid.size());
    for (std::size_t center = 0U;
         center < result.fluid.size(); ++center) {
        cursor[center] = result.flat_offsets[center];
    }
    for (std::size_t pair_index = 0U;
         pair_index < result.pairs.size(); ++pair_index) {
        const JointPair pair = result.pairs[pair_index];
        result.flat_directed_pair_indices[cursor[pair.fluid]++] =
            static_cast<std::uint32_t>(pair_index);
        if (pair.participant < result.fluid.size()) {
            result.flat_directed_pair_indices[cursor[pair.participant]++] =
                static_cast<std::uint32_t>(pair_index);
        }
    }
    for (std::size_t center = 0U;
         center < result.fluid.size(); ++center) {
        const std::size_t begin = result.flat_offsets[center];
        const std::size_t end = result.flat_offsets[center + 1U];
        std::size_t previous = 0U;
        bool have_previous = false;
        for (std::size_t slot = begin; slot < end; ++slot) {
            const std::uint32_t pair_index =
                result.flat_directed_pair_indices[slot];
            if (pair_index >= result.pairs.size()) {
                result.failure = "JOINT_PAIR_CAPACITY";
                return false;
            }
            const std::size_t participant = joint_pair_participant(
                result, result.pairs[pair_index], center);
            if (participant >= result.fluid.size() + result.support.size()
                || participant == center
                || (have_previous && participant <= previous)) {
                result.failure = "JOINT_DUPLICATE_PAIR";
                return false;
            }
            previous = participant;
            have_previous = true;
        }
    }
    if (adjacency_work != nullptr) {
        adjacency_work->flat_offset_records += result.flat_offsets.size();
        adjacency_work->flat_pair_index_records +=
            result.flat_directed_pair_indices.size();
    }
    return true;
}

JointNeighborhood build_joint_neighborhood(
    const std::vector<JointPoint>& fluid_input,
    const std::vector<JointPoint>& support_input,
    bool one_pass = false,
    StaticSupportWorkTrace* work = nullptr,
    bool flat_adjacency = false,
    FlatAdjacencyWorkTrace* adjacency_work = nullptr) {
    JointNeighborhood result;
    if (work != nullptr) {
        ++work->workspace_builds;
        ++work->static_index_builds;
        ++work->support_canonicalizations;
    }
    if (fluid_input.empty() || fluid_input.size() > B4C0_MAX_FLUID) {
        result.failure = "JOINT_FLUID_CAPACITY";
        return result;
    }
    if (support_input.size() > B4C0_MAX_SUPPORT) {
        result.failure = "JOINT_SUPPORT_CAPACITY";
        return result;
    }
    const std::size_t pair_limit = checked_joint_pair_limit(
        fluid_input.size());
    if (pair_limit == 0U) {
        result.failure = "JOINT_PAIR_CAPACITY";
        return result;
    }
    result.pair_payload_capacity_bytes = pair_limit * sizeof(JointPair);
    result.adjacency_payload_capacity_bytes = pair_limit
        * sizeof(std::uint32_t);
    if (!canonicalize_joint_points(fluid_input, result.fluid)
        || !canonicalize_joint_points(support_input, result.support)) {
        bool all_finite = true;
        const auto finite_point = [&](const JointPoint& value) {
            all_finite = all_finite && finite(value.position);
        };
        std::for_each(fluid_input.begin(), fluid_input.end(), finite_point);
        std::for_each(support_input.begin(), support_input.end(), finite_point);
        result.failure = all_finite
            ? "JOINT_DUPLICATE_ID" : "JOINT_POSITION_INVALID";
        result.fluid.clear();
        result.support.clear();
        return result;
    }
    if (work != nullptr && work->capture_fluid_states) {
        work->fluid_states.push_back(result.fluid);
    }
    if (result.fluid.size() > std::numeric_limits<std::size_t>::max()
            - result.support.size()) {
        result.failure = "JOINT_PAIR_CAPACITY";
        result.fluid.clear();
        result.support.clear();
        return result;
    }
    const std::size_t total = result.fluid.size() + result.support.size();
    if (work != nullptr) {
        work->fluid_records_sorted += result.fluid.size();
        work->support_records_sorted += result.support.size();
        work->combined_records_sorted += total;
    }
    std::vector<JointCellRecord> records;
    records.reserve(total);
    for (std::size_t participant = 0; participant < total; ++participant) {
        const Vec3& position = joint_position(result, participant);
        JointCellRecord record;
        record.participant = participant;
        if (!joint_cell_coordinate(position.x, record.x)
            || !joint_cell_coordinate(position.y, record.y)
            || !joint_cell_coordinate(position.z, record.z)) {
            result.failure = "JOINT_POSITION_INVALID";
            result.fluid.clear();
            result.support.clear();
            return result;
        }
        records.push_back(record);
    }
    std::sort(records.begin(), records.end(), joint_cell_record_less);
    std::vector<JointCellRange> ranges;
    ranges.reserve(records.size());
    for (std::size_t begin = 0; begin < records.size();) {
        std::size_t end = begin + 1U;
        while (end < records.size()
            && records[end].x == records[begin].x
            && records[end].y == records[begin].y
            && records[end].z == records[begin].z) {
            ++end;
        }
        ranges.push_back({records[begin].x, records[begin].y,
            records[begin].z, begin, end});
        begin = end;
    }

    const auto visit = [&](const auto& callback,
                           std::size_t& distance_tests) {
        for (std::size_t center = 0; center < result.fluid.size(); ++center) {
            std::int64_t cx = 0;
            std::int64_t cy = 0;
            std::int64_t cz = 0;
            if (!joint_cell_coordinate(result.fluid[center].position.x, cx)
                || !joint_cell_coordinate(result.fluid[center].position.y, cy)
                || !joint_cell_coordinate(result.fluid[center].position.z, cz)) {
                return false;
            }
            for (int dx = -1; dx <= 1; ++dx) {
                for (int dy = -1; dy <= 1; ++dy) {
                    for (int dz = -1; dz <= 1; ++dz) {
                        const std::int64_t qx = cx + dx;
                        const std::int64_t qy = cy + dy;
                        const std::int64_t qz = cz + dz;
                        if (work != nullptr) {
                            ++work->combined_range_lookups;
                        }
                        const auto range = std::lower_bound(
                            ranges.begin(), ranges.end(),
                            JointCellRange{qx, qy, qz, 0U, 0U},
                            joint_cell_range_less);
                        if (range == ranges.end()
                            || range->x != qx || range->y != qy
                            || range->z != qz) {
                            continue;
                        }
                        for (std::size_t slot = range->begin;
                             slot < range->end; ++slot) {
                            const std::size_t participant =
                                records[slot].participant;
                            if (participant < result.fluid.size()
                                && participant <= center) {
                                continue;
                            }
                            ++distance_tests;
                            if (norm(result.fluid[center].position
                                    - joint_position(result, participant))
                                    <= HORIZON
                                && !callback(center, participant)) {
                                return false;
                            }
                        }
                    }
                }
            }
        }
        return true;
    };

    std::vector<std::size_t> degree(result.fluid.size());
    std::size_t pair_count = 0U;
    if (one_pass) {
        result.pairs.reserve(pair_limit);
        const bool filled = visit(
            [&](std::size_t center, std::size_t participant) {
                if (pair_count == pair_limit) {
                    result.failure = "JOINT_PAIR_CAPACITY";
                    return false;
                }
                if (degree[center] == B4C0_MAX_NEIGHBORS
                    || (participant < result.fluid.size()
                        && degree[participant] == B4C0_MAX_NEIGHBORS)) {
                    result.failure = "JOINT_NEIGHBOR_CAPACITY";
                    return false;
                }
                ++pair_count;
                ++degree[center];
                if (participant < result.fluid.size()) {
                    ++degree[participant];
                    ++result.fluid_pairs;
                } else {
                    ++result.support_pairs;
                }
                result.pairs.push_back({
                    static_cast<std::uint32_t>(center),
                    static_cast<std::uint32_t>(participant)});
                return true;
            }, result.distance_tests_per_pass);
        if (!filled) {
            if (result.failure.empty()) {
                result.failure = "JOINT_POSITION_INVALID";
            }
            result.pairs.clear();
            result.fluid.clear();
            result.support.clear();
            return result;
        }
        result.construction_distance_tests =
            result.distance_tests_per_pass;
    } else {
        const bool counted = visit(
            [&](std::size_t center, std::size_t participant) {
                if (pair_count == pair_limit) {
                    result.failure = "JOINT_PAIR_CAPACITY";
                    return false;
                }
                ++pair_count;
                if (++degree[center] > B4C0_MAX_NEIGHBORS) {
                    result.failure = "JOINT_NEIGHBOR_CAPACITY";
                    return false;
                }
                if (participant < result.fluid.size()
                    && ++degree[participant] > B4C0_MAX_NEIGHBORS) {
                    result.failure = "JOINT_NEIGHBOR_CAPACITY";
                    return false;
                }
                return true;
            }, result.distance_tests_per_pass);
        if (!counted) {
            if (result.failure.empty()) {
                result.failure = "JOINT_POSITION_INVALID";
            }
            result.fluid.clear();
            result.support.clear();
            return result;
        }
        result.pairs.reserve(pair_count);
        std::size_t fill_tests = 0U;
        const bool filled = visit(
            [&](std::size_t center, std::size_t participant) {
                result.pairs.push_back({
                    static_cast<std::uint32_t>(center),
                    static_cast<std::uint32_t>(participant)});
                if (participant < result.fluid.size()) {
                    ++result.fluid_pairs;
                } else {
                    ++result.support_pairs;
                }
                return true;
            }, fill_tests);
        if (!filled || result.pairs.size() != pair_count) {
            result.failure = "JOINT_POSITION_INVALID";
            result.pairs.clear();
            result.fluid.clear();
            result.support.clear();
            return result;
        }
        result.construction_distance_tests =
            result.distance_tests_per_pass + fill_tests;
    }
    result.maximum_degree = *std::max_element(degree.begin(), degree.end());
    std::sort(result.pairs.begin(), result.pairs.end(),
        [](const JointPair& lhs, const JointPair& rhs) {
            return lhs.fluid < rhs.fluid
                || (lhs.fluid == rhs.fluid
                    && lhs.participant < rhs.participant);
        });
    if (std::adjacent_find(result.pairs.begin(), result.pairs.end())
        != result.pairs.end()) {
        result.failure = "JOINT_DUPLICATE_PAIR";
        result.pairs.clear();
        result.fluid.clear();
        result.support.clear();
        return result;
    }
    if (!finalize_joint_adjacency(
            result, degree, flat_adjacency, adjacency_work)) {
        result.pairs.clear();
        result.adjacency.clear();
        result.flat_adjacency = false;
        result.flat_offsets.clear();
        result.flat_directed_pair_indices.clear();
        result.fluid.clear();
        result.support.clear();
        return result;
    }
    result.passed = true;
    return result;
}

JointNeighborhood build_joint_neighborhood_with_static_support(
    const std::vector<JointPoint>& fluid_input,
    const JointStaticSupportBinding* binding,
    bool one_pass = false,
    StaticSupportWorkTrace* work = nullptr,
    bool flat_adjacency = false,
    FlatAdjacencyWorkTrace* adjacency_work = nullptr) {
    JointNeighborhood result;
    if (work != nullptr) {
        ++work->workspace_builds;
    }
    if (binding == nullptr || !binding->passed
        || binding->index == nullptr) {
        result.failure = binding != nullptr && !binding->failure.empty()
            ? binding->failure : "STATIC_SUPPORT_INDEX_SOURCE";
        return result;
    }
    const JointStaticSupportIndex& support_index = *binding->index;
    if (support_index.identity_sha256
        != binding->expected_identity_sha256) {
        result.failure = "STATIC_SUPPORT_INDEX_IDENTITY";
        return result;
    }
    if (fluid_input.empty() || fluid_input.size() > B4C0_MAX_FLUID) {
        result.failure = "JOINT_FLUID_CAPACITY";
        return result;
    }
    const std::size_t pair_limit = checked_joint_pair_limit(
        fluid_input.size());
    if (pair_limit == 0U) {
        result.failure = "JOINT_PAIR_CAPACITY";
        return result;
    }
    result.pair_payload_capacity_bytes = pair_limit * sizeof(JointPair);
    result.adjacency_payload_capacity_bytes = pair_limit
        * sizeof(std::uint32_t);
    if (!canonicalize_joint_points(fluid_input, result.fluid)) {
        const bool all_finite = std::all_of(
            fluid_input.begin(), fluid_input.end(),
            [](const JointPoint& value) {
                return finite(value.position);
            });
        result.failure = all_finite
            ? "JOINT_DUPLICATE_ID" : "JOINT_POSITION_INVALID";
        result.fluid.clear();
        return result;
    }
    if (work != nullptr && work->capture_fluid_states) {
        work->fluid_states.push_back(result.fluid);
    }
    result.support = support_index.support;
    if (result.fluid.size() > std::numeric_limits<std::size_t>::max()
            - result.support.size()) {
        result.failure = "JOINT_PAIR_CAPACITY";
        result.fluid.clear();
        result.support.clear();
        return result;
    }
    if (work != nullptr) {
        work->fluid_records_sorted += result.fluid.size();
    }
    std::vector<JointCellRecord> fluid_records;
    fluid_records.reserve(result.fluid.size());
    for (std::size_t participant = 0U;
         participant < result.fluid.size(); ++participant) {
        const Vec3& position = result.fluid[participant].position;
        JointCellRecord record;
        record.participant = participant;
        if (!joint_cell_coordinate(position.x, record.x)
            || !joint_cell_coordinate(position.y, record.y)
            || !joint_cell_coordinate(position.z, record.z)) {
            result.failure = "JOINT_POSITION_INVALID";
            result.fluid.clear();
            result.support.clear();
            return result;
        }
        fluid_records.push_back(record);
    }
    std::sort(fluid_records.begin(), fluid_records.end(),
        joint_cell_record_less);
    std::vector<JointCellRange> fluid_ranges;
    fluid_ranges.reserve(fluid_records.size());
    for (std::size_t begin = 0U; begin < fluid_records.size();) {
        std::size_t end = begin + 1U;
        while (end < fluid_records.size()
            && fluid_records[end].x == fluid_records[begin].x
            && fluid_records[end].y == fluid_records[begin].y
            && fluid_records[end].z == fluid_records[begin].z) {
            ++end;
        }
        fluid_ranges.push_back({fluid_records[begin].x,
            fluid_records[begin].y, fluid_records[begin].z, begin, end});
        begin = end;
    }

    const auto visit = [&](const auto& callback,
                           std::size_t& distance_tests) {
        for (std::size_t center = 0U;
             center < result.fluid.size(); ++center) {
            std::int64_t cx = 0;
            std::int64_t cy = 0;
            std::int64_t cz = 0;
            if (!joint_cell_coordinate(result.fluid[center].position.x, cx)
                || !joint_cell_coordinate(
                    result.fluid[center].position.y, cy)
                || !joint_cell_coordinate(
                    result.fluid[center].position.z, cz)) {
                return false;
            }
            for (int dx = -1; dx <= 1; ++dx) {
                for (int dy = -1; dy <= 1; ++dy) {
                    for (int dz = -1; dz <= 1; ++dz) {
                        const std::int64_t qx = cx + dx;
                        const std::int64_t qy = cy + dy;
                        const std::int64_t qz = cz + dz;
                        if (work != nullptr) {
                            ++work->fluid_range_lookups;
                        }
                        const auto fluid_range = std::lower_bound(
                            fluid_ranges.begin(), fluid_ranges.end(),
                            JointCellRange{qx, qy, qz, 0U, 0U},
                            joint_cell_range_less);
                        if (fluid_range != fluid_ranges.end()
                            && fluid_range->x == qx
                            && fluid_range->y == qy
                            && fluid_range->z == qz) {
                            for (std::size_t slot = fluid_range->begin;
                                 slot < fluid_range->end; ++slot) {
                                const std::size_t participant =
                                    fluid_records[slot].participant;
                                if (participant <= center) {
                                    continue;
                                }
                                ++distance_tests;
                                if (norm(result.fluid[center].position
                                        - result.fluid[participant].position)
                                        <= HORIZON
                                    && !callback(center, participant)) {
                                    return false;
                                }
                            }
                        }
                        if (work != nullptr) {
                            ++work->support_range_lookups;
                        }
                        const auto support_range = std::lower_bound(
                            support_index.ranges.begin(),
                            support_index.ranges.end(),
                            JointCellRange{qx, qy, qz, 0U, 0U},
                            joint_cell_range_less);
                        if (support_range == support_index.ranges.end()
                            || support_range->x != qx
                            || support_range->y != qy
                            || support_range->z != qz) {
                            continue;
                        }
                        for (std::size_t slot = support_range->begin;
                             slot < support_range->end; ++slot) {
                            const std::size_t participant = result.fluid.size()
                                + support_index.records[slot].participant;
                            ++distance_tests;
                            if (norm(result.fluid[center].position
                                    - joint_position(result, participant))
                                    <= HORIZON
                                && !callback(center, participant)) {
                                return false;
                            }
                        }
                    }
                }
            }
        }
        return true;
    };

    std::vector<std::size_t> degree(result.fluid.size());
    std::size_t pair_count = 0U;
    if (one_pass) {
        result.pairs.reserve(pair_limit);
        const bool filled = visit(
            [&](std::size_t center, std::size_t participant) {
                if (pair_count == pair_limit) {
                    result.failure = "JOINT_PAIR_CAPACITY";
                    return false;
                }
                if (degree[center] == B4C0_MAX_NEIGHBORS
                    || (participant < result.fluid.size()
                        && degree[participant] == B4C0_MAX_NEIGHBORS)) {
                    result.failure = "JOINT_NEIGHBOR_CAPACITY";
                    return false;
                }
                ++pair_count;
                ++degree[center];
                if (participant < result.fluid.size()) {
                    ++degree[participant];
                    ++result.fluid_pairs;
                } else {
                    ++result.support_pairs;
                }
                result.pairs.push_back({
                    static_cast<std::uint32_t>(center),
                    static_cast<std::uint32_t>(participant)});
                return true;
            }, result.distance_tests_per_pass);
        if (!filled) {
            if (result.failure.empty()) {
                result.failure = "JOINT_POSITION_INVALID";
            }
            result.pairs.clear();
            result.fluid.clear();
            result.support.clear();
            return result;
        }
        result.construction_distance_tests =
            result.distance_tests_per_pass;
    } else {
        const bool counted = visit(
            [&](std::size_t center, std::size_t participant) {
                if (pair_count == pair_limit) {
                    result.failure = "JOINT_PAIR_CAPACITY";
                    return false;
                }
                ++pair_count;
                if (++degree[center] > B4C0_MAX_NEIGHBORS) {
                    result.failure = "JOINT_NEIGHBOR_CAPACITY";
                    return false;
                }
                if (participant < result.fluid.size()
                    && ++degree[participant] > B4C0_MAX_NEIGHBORS) {
                    result.failure = "JOINT_NEIGHBOR_CAPACITY";
                    return false;
                }
                return true;
            }, result.distance_tests_per_pass);
        if (!counted) {
            if (result.failure.empty()) {
                result.failure = "JOINT_POSITION_INVALID";
            }
            result.fluid.clear();
            result.support.clear();
            return result;
        }
        result.pairs.reserve(pair_count);
        std::size_t fill_tests = 0U;
        const bool filled = visit(
            [&](std::size_t center, std::size_t participant) {
                result.pairs.push_back({
                    static_cast<std::uint32_t>(center),
                    static_cast<std::uint32_t>(participant)});
                if (participant < result.fluid.size()) {
                    ++result.fluid_pairs;
                } else {
                    ++result.support_pairs;
                }
                return true;
            }, fill_tests);
        if (!filled || result.pairs.size() != pair_count) {
            result.failure = "JOINT_POSITION_INVALID";
            result.pairs.clear();
            result.fluid.clear();
            result.support.clear();
            return result;
        }
        result.construction_distance_tests =
            result.distance_tests_per_pass + fill_tests;
    }
    result.maximum_degree = *std::max_element(
        degree.begin(), degree.end());
    std::sort(result.pairs.begin(), result.pairs.end(),
        [](const JointPair& lhs, const JointPair& rhs) {
            return lhs.fluid < rhs.fluid
                || (lhs.fluid == rhs.fluid
                    && lhs.participant < rhs.participant);
        });
    if (std::adjacent_find(result.pairs.begin(), result.pairs.end())
        != result.pairs.end()) {
        result.failure = "JOINT_DUPLICATE_PAIR";
        result.pairs.clear();
        result.fluid.clear();
        result.support.clear();
        return result;
    }
    if (!finalize_joint_adjacency(
            result, degree, flat_adjacency, adjacency_work)) {
        result.pairs.clear();
        result.adjacency.clear();
        result.flat_adjacency = false;
        result.flat_offsets.clear();
        result.flat_directed_pair_indices.clear();
        result.fluid.clear();
        result.support.clear();
        return result;
    }
    result.passed = true;
    return result;
}

std::vector<JointPair> all_joint_pairs(
    const std::vector<JointPoint>& fluid,
    const std::vector<JointPoint>& support) {
    std::vector<JointPair> result;
    for (std::size_t i = 0; i < fluid.size(); ++i) {
        for (std::size_t j = i + 1U; j < fluid.size(); ++j) {
            if (norm(fluid[i].position - fluid[j].position) <= HORIZON) {
                result.push_back({static_cast<std::uint32_t>(i),
                    static_cast<std::uint32_t>(j)});
            }
        }
        for (std::size_t b = 0; b < support.size(); ++b) {
            if (norm(fluid[i].position - support[b].position) <= HORIZON) {
                result.push_back({static_cast<std::uint32_t>(i),
                    static_cast<std::uint32_t>(fluid.size() + b)});
            }
        }
    }
    return result;
}

std::string joint_pair_hash(const JointNeighborhood& value) {
    std::ostringstream material;
    material << "joint-fluid-support-r0|";
    for (const JointPair pair : value.pairs) {
        material << value.fluid[pair.fluid].id << ':';
        if (pair.participant < value.fluid.size()) {
            material << 'F' << ':'
                     << value.fluid[pair.participant].id;
        } else {
            material << 'S' << ':'
                     << value.support[
                            pair.participant - value.fluid.size()].id;
        }
        material << '|';
    }
    return sha256_hex(material.str());
}

template <typename Callback>
void for_each_joint_participant(
    const JointNeighborhood& neighborhood,
    std::size_t center,
    const Callback& callback) {
    if (!neighborhood.flat_adjacency) {
        for (std::uint32_t participant : neighborhood.adjacency[center]) {
            callback(static_cast<std::size_t>(participant));
        }
        return;
    }
    const std::size_t begin = neighborhood.flat_offsets[center];
    const std::size_t end = neighborhood.flat_offsets[center + 1U];
    for (std::size_t slot = begin; slot < end; ++slot) {
        const std::uint32_t pair_index =
            neighborhood.flat_directed_pair_indices[slot];
        callback(joint_pair_participant(
            neighborhood, neighborhood.pairs[pair_index], center));
    }
}

Evaluation evaluate_joint(const JointNeighborhood& neighborhood) {
    Evaluation result;
    const std::size_t fluid_count = neighborhood.fluid.size();
    result.gradient.resize(fluid_count + neighborhood.support.size());
    result.density.assign(fluid_count, MASS * weight(0.0));
    for (const JointPair pair : neighborhood.pairs) {
        const double radius = norm(
            neighborhood.fluid[pair.fluid].position
            - joint_position(neighborhood, pair.participant));
        const double contribution = MASS * weight(radius);
        result.density[pair.fluid] += contribution;
        if (pair.participant < fluid_count) {
            result.density[pair.participant] += contribution;
            ++result.fluid_pairs;
        } else {
            ++result.boundary_pairs;
        }
    }
    for (std::size_t center = 0; center < fluid_count; ++center) {
        const double compression =
            result.density[center] / REST_DENSITY - 1.0;
        result.minimum_branch_margin = std::min(
            result.minimum_branch_margin, std::abs(compression));
        if (compression <= 0.0) {
            continue;
        }
        ++result.active_centers;
        result.energy += 0.5 * KAPPA * compression * compression;
        const double scale = KAPPA * compression
            * MASS / REST_DENSITY;
        for_each_joint_participant(neighborhood, center,
            [&](std::size_t participant) {
            const Vec3 displacement =
                neighborhood.fluid[center].position
                - joint_position(neighborhood, participant);
            const double radius = norm(displacement);
            if (radius <= 1.0e-15 || radius > HORIZON) {
                return;
            }
            const Vec3 pair = scale * weight_gradient(radius)
                * (displacement / radius);
            result.gradient[center] += pair;
            result.gradient[participant] += -pair;
            });
    }
    return result;
}

std::vector<Vec3> apply_joint_hessian(
    const JointNeighborhood& neighborhood,
    const std::vector<Vec3>& direction) {
    const std::size_t fluid_count = neighborhood.fluid.size();
    const std::size_t total = fluid_count + neighborhood.support.size();
    if (direction.size() != total) {
        throw std::invalid_argument("B4C0 HVP direction size mismatch");
    }
    const Evaluation state = evaluate_joint(neighborhood);
    std::vector<Vec3> result(total);
    for (std::size_t center = 0; center < fluid_count; ++center) {
        const double compression =
            state.density[center] / REST_DENSITY - 1.0;
        if (compression <= 0.0) {
            continue;
        }
        double compression_direction = 0.0;
        for_each_joint_participant(neighborhood, center,
            [&](std::size_t participant) {
            const Vec3 displacement =
                neighborhood.fluid[center].position
                - joint_position(neighborhood, participant);
            const double radius = norm(displacement);
            if (radius <= 1.0e-15 || radius > HORIZON) {
                return;
            }
            const Vec3 jacobian = MASS / REST_DENSITY
                * weight_gradient(radius) * (displacement / radius);
            compression_direction += dot(
                jacobian, direction[center] - direction[participant]);
            });
        for_each_joint_participant(neighborhood, center,
            [&](std::size_t participant) {
            const Vec3 displacement =
                neighborhood.fluid[center].position
                - joint_position(neighborhood, participant);
            const double radius = norm(displacement);
            if (radius <= 1.0e-15 || radius > HORIZON) {
                return;
            }
            const Vec3 normal = displacement / radius;
            const Vec3 jacobian = MASS / REST_DENSITY
                * weight_gradient(radius) * normal;
            const Vec3 relative_direction =
                direction[center] - direction[participant];
            const Vec3 curvature = MASS / REST_DENSITY
                * radial_hessian_product(normal,
                    weight_second(radius),
                    weight_gradient(radius) / radius,
                    relative_direction);
            const Vec3 pair = KAPPA
                * (compression_direction * jacobian
                    + compression * curvature);
            result[center] += pair;
            result[participant] += -pair;
            });
    }
    return result;
}

JointPressureTape build_joint_pressure_tape(
    const JointNeighborhood& neighborhood,
    const Evaluation& state,
    std::size_t payload_limit = std::numeric_limits<std::size_t>::max(),
    std::size_t directed_limit =
        std::numeric_limits<std::uint32_t>::max(),
    FlatAdjacencyWorkTrace* adjacency_work = nullptr) {
    JointPressureTape result;
    const std::size_t fluid_count = neighborhood.fluid.size();
    const std::size_t total = fluid_count + neighborhood.support.size();
    if (!neighborhood.passed || neighborhood.adjacency.size() != fluid_count
        || state.density.size() != fluid_count) {
        result.failure = "PRESSURE_TAPE_SOURCE";
        return result;
    }
    if (neighborhood.pairs.size()
            > std::numeric_limits<std::uint32_t>::max()
        || fluid_count >= std::numeric_limits<std::uint32_t>::max()) {
        result.failure = "PRESSURE_TAPE_OFFSET_CAPACITY";
        return result;
    }
    for (const JointPair pair : neighborhood.pairs) {
        if (pair.fluid >= fluid_count || pair.participant >= total
            || (pair.participant < fluid_count
                && pair.fluid >= pair.participant)) {
            result.failure = "PRESSURE_TAPE_PAIR_INDEX";
            return result;
        }
    }
    std::size_t directed = 0U;
    for (std::size_t center = 0; center < fluid_count; ++center) {
        std::uint32_t previous = 0U;
        bool have_previous = false;
        for (std::uint32_t participant : neighborhood.adjacency[center]) {
            if (participant >= total || participant == center
                || (have_previous && participant <= previous)) {
                result.failure = "PRESSURE_TAPE_ADJACENCY";
                return result;
            }
            previous = participant;
            have_previous = true;
        }
        if (neighborhood.adjacency[center].size()
                > std::numeric_limits<std::size_t>::max() - directed) {
            result.failure = "PRESSURE_TAPE_OFFSET_CAPACITY";
            return result;
        }
        directed += neighborhood.adjacency[center].size();
    }
    if (directed > directed_limit
        || directed > std::numeric_limits<std::uint32_t>::max()) {
        result.failure = "PRESSURE_TAPE_OFFSET_CAPACITY";
        return result;
    }
    const std::size_t offsets_bytes = (fluid_count + 1U)
        * sizeof(std::uint32_t);
    const std::size_t indices_bytes = directed * sizeof(std::uint32_t);
    const std::size_t radii_bytes = neighborhood.pairs.size()
        * sizeof(double);
    const std::size_t compression_bytes = fluid_count * sizeof(double);
    if (offsets_bytes > std::numeric_limits<std::size_t>::max()
            - indices_bytes
        || offsets_bytes + indices_bytes
            > std::numeric_limits<std::size_t>::max() - radii_bytes
        || offsets_bytes + indices_bytes + radii_bytes
            > std::numeric_limits<std::size_t>::max() - compression_bytes) {
        result.failure = "PRESSURE_TAPE_CAPACITY";
        return result;
    }
    const std::size_t payload_bytes = offsets_bytes + indices_bytes
        + radii_bytes + compression_bytes;
    if (payload_bytes > payload_limit) {
        result.failure = "PRESSURE_TAPE_CAPACITY";
        return result;
    }

    JointPressureTape candidate;
    candidate.offsets.resize(fluid_count + 1U);
    candidate.directed_pair_indices.resize(directed);
    candidate.radius.resize(neighborhood.pairs.size());
    candidate.compression.resize(fluid_count);
    candidate.payload_bytes = payload_bytes;
    if (adjacency_work != nullptr) {
        adjacency_work->legacy_tape_offset_records += fluid_count + 1U;
        adjacency_work->legacy_tape_pair_index_records += directed;
    }
    std::vector<std::size_t> degree(fluid_count);
    for (const JointPair pair : neighborhood.pairs) {
        ++degree[pair.fluid];
        if (pair.participant < fluid_count) {
            ++degree[pair.participant];
        }
    }
    std::size_t offset = 0U;
    for (std::size_t center = 0; center < fluid_count; ++center) {
        candidate.offsets[center] = static_cast<std::uint32_t>(offset);
        offset += degree[center];
    }
    candidate.offsets[fluid_count] = static_cast<std::uint32_t>(offset);
    if (offset != directed) {
        result.failure = "PRESSURE_TAPE_ADJACENCY";
        return result;
    }
    std::vector<std::size_t> cursor(fluid_count);
    for (std::size_t center = 0; center < fluid_count; ++center) {
        cursor[center] = candidate.offsets[center];
    }
    for (std::size_t pair_index = 0;
         pair_index < neighborhood.pairs.size(); ++pair_index) {
        const JointPair pair = neighborhood.pairs[pair_index];
        candidate.directed_pair_indices[cursor[pair.fluid]++] =
            static_cast<std::uint32_t>(pair_index);
        if (pair.participant < fluid_count) {
            candidate.directed_pair_indices[cursor[pair.participant]++] =
                static_cast<std::uint32_t>(pair_index);
        }
        candidate.radius[pair_index] = norm(
            neighborhood.fluid[pair.fluid].position
            - joint_position(neighborhood, pair.participant));
    }
    for (std::size_t center = 0; center < fluid_count; ++center) {
        const std::size_t begin = candidate.offsets[center];
        const std::size_t end = candidate.offsets[center + 1U];
        std::sort(candidate.directed_pair_indices.begin() + begin,
            candidate.directed_pair_indices.begin() + end,
            [&](std::uint32_t lhs, std::uint32_t rhs) {
                return joint_pair_participant(
                           neighborhood, neighborhood.pairs[lhs], center)
                    < joint_pair_participant(
                           neighborhood, neighborhood.pairs[rhs], center);
            });
        if (adjacency_work != nullptr) {
            ++adjacency_work->legacy_tape_row_sorts;
        }
        if (end - begin != neighborhood.adjacency[center].size()) {
            result.failure = "PRESSURE_TAPE_ADJACENCY";
            return result;
        }
        for (std::size_t slot = begin; slot < end; ++slot) {
            const std::size_t participant = joint_pair_participant(
                neighborhood,
                neighborhood.pairs[candidate.directed_pair_indices[slot]],
                center);
            if (participant
                != neighborhood.adjacency[center][slot - begin]) {
                result.failure = "PRESSURE_TAPE_ADJACENCY";
                return result;
            }
        }
        candidate.compression[center] =
            state.density[center] / REST_DENSITY - 1.0;
        if (candidate.compression[center] > 0.0) {
            ++candidate.active_centers;
            candidate.active_directed += end - begin;
        }
    }
    candidate.passed = true;
    return candidate;
}

JointPressureTape build_joint_pressure_tape_from_flat(
    JointNeighborhood& neighborhood,
    const Evaluation& state,
    std::size_t payload_limit = std::numeric_limits<std::size_t>::max(),
    std::size_t directed_limit =
        std::numeric_limits<std::uint32_t>::max(),
    FlatAdjacencyWorkTrace* adjacency_work = nullptr) {
    JointPressureTape result;
    const std::size_t fluid_count = neighborhood.fluid.size();
    const std::size_t total = fluid_count + neighborhood.support.size();
    if (!neighborhood.passed || !neighborhood.flat_adjacency
        || !neighborhood.adjacency.empty()
        || state.density.size() != fluid_count) {
        result.failure = "PRESSURE_TAPE_SOURCE";
        return result;
    }
    if (neighborhood.pairs.size()
            > std::numeric_limits<std::uint32_t>::max()
        || fluid_count >= std::numeric_limits<std::uint32_t>::max()) {
        result.failure = "PRESSURE_TAPE_OFFSET_CAPACITY";
        return result;
    }
    for (const JointPair pair : neighborhood.pairs) {
        if (pair.fluid >= fluid_count || pair.participant >= total
            || (pair.participant < fluid_count
                && pair.fluid >= pair.participant)) {
            result.failure = "PRESSURE_TAPE_PAIR_INDEX";
            return result;
        }
    }
    if (neighborhood.flat_offsets.size() != fluid_count + 1U
        || neighborhood.flat_offsets.empty()
        || neighborhood.flat_offsets.front() != 0U
        || neighborhood.flat_offsets.back()
            != neighborhood.flat_directed_pair_indices.size()) {
        result.failure = "PRESSURE_TAPE_ADJACENCY";
        return result;
    }
    const std::size_t directed =
        neighborhood.flat_directed_pair_indices.size();
    if (directed > directed_limit
        || directed > std::numeric_limits<std::uint32_t>::max()) {
        result.failure = "PRESSURE_TAPE_OFFSET_CAPACITY";
        return result;
    }
    for (std::size_t center = 0U; center < fluid_count; ++center) {
        const std::size_t begin = neighborhood.flat_offsets[center];
        const std::size_t end = neighborhood.flat_offsets[center + 1U];
        if (end < begin || end > directed) {
            result.failure = "PRESSURE_TAPE_ADJACENCY";
            return result;
        }
        std::size_t previous = 0U;
        bool have_previous = false;
        for (std::size_t slot = begin; slot < end; ++slot) {
            const std::uint32_t pair_index =
                neighborhood.flat_directed_pair_indices[slot];
            if (pair_index >= neighborhood.pairs.size()) {
                result.failure = "PRESSURE_TAPE_ADJACENCY";
                return result;
            }
            const std::size_t participant = joint_pair_participant(
                neighborhood, neighborhood.pairs[pair_index], center);
            if (participant >= total || participant == center
                || (have_previous && participant <= previous)) {
                result.failure = "PRESSURE_TAPE_ADJACENCY";
                return result;
            }
            previous = participant;
            have_previous = true;
        }
    }

    const std::size_t offsets_bytes = (fluid_count + 1U)
        * sizeof(std::uint32_t);
    const std::size_t indices_bytes = directed * sizeof(std::uint32_t);
    const std::size_t radii_bytes = neighborhood.pairs.size()
        * sizeof(double);
    const std::size_t compression_bytes = fluid_count * sizeof(double);
    if (offsets_bytes > std::numeric_limits<std::size_t>::max()
            - indices_bytes
        || offsets_bytes + indices_bytes
            > std::numeric_limits<std::size_t>::max() - radii_bytes
        || offsets_bytes + indices_bytes + radii_bytes
            > std::numeric_limits<std::size_t>::max() - compression_bytes) {
        result.failure = "PRESSURE_TAPE_CAPACITY";
        return result;
    }
    const std::size_t payload_bytes = offsets_bytes + indices_bytes
        + radii_bytes + compression_bytes;
    if (payload_bytes > payload_limit) {
        result.failure = "PRESSURE_TAPE_CAPACITY";
        return result;
    }

    JointPressureTape candidate;
    candidate.radius.resize(neighborhood.pairs.size());
    candidate.compression.resize(fluid_count);
    candidate.payload_bytes = payload_bytes;
    for (std::size_t pair_index = 0U;
         pair_index < neighborhood.pairs.size(); ++pair_index) {
        const JointPair pair = neighborhood.pairs[pair_index];
        candidate.radius[pair_index] = norm(
            neighborhood.fluid[pair.fluid].position
            - joint_position(neighborhood, pair.participant));
    }
    for (std::size_t center = 0U; center < fluid_count; ++center) {
        const std::size_t begin = neighborhood.flat_offsets[center];
        const std::size_t end = neighborhood.flat_offsets[center + 1U];
        candidate.compression[center] =
            state.density[center] / REST_DENSITY - 1.0;
        if (candidate.compression[center] > 0.0) {
            ++candidate.active_centers;
            candidate.active_directed += end - begin;
        }
    }
    candidate.offsets = std::move(neighborhood.flat_offsets);
    candidate.directed_pair_indices = std::move(
        neighborhood.flat_directed_pair_indices);
    if (adjacency_work != nullptr) {
        ++adjacency_work->csr_ownership_transfers;
    }
    candidate.passed = true;
    return candidate;
}

bool populate_joint_hvp_coefficients(
    JointPressureTape& tape,
    JointQueryTrace& trace) {
    if (!tape.passed || !tape.hvp_gradient.empty()
        || !tape.hvp_second.empty()) {
        ++trace.coefficient_mismatches;
        return false;
    }
    const std::size_t pair_count = tape.radius.size();
    if (pair_count > std::numeric_limits<std::size_t>::max()
            / (2U * sizeof(double))) {
        ++trace.coefficient_mismatches;
        return false;
    }
    const std::size_t payload_bytes =
        pair_count * 2U * sizeof(double);
    if (tape.payload_bytes > std::numeric_limits<std::size_t>::max()
            - payload_bytes) {
        ++trace.coefficient_mismatches;
        return false;
    }
    tape.hvp_gradient.resize(pair_count);
    tape.hvp_second.resize(pair_count);
    for (std::size_t pair_index = 0U;
         pair_index < pair_count; ++pair_index) {
        const double radius = tape.radius[pair_index];
        tape.hvp_gradient[pair_index] = weight_gradient(radius);
        tape.hvp_second[pair_index] = weight_second(radius);
    }
    tape.payload_bytes += payload_bytes;
    ++trace.coefficient_tape_builds;
    trace.coefficient_pairs += pair_count;
    trace.coefficient_kernel_evaluations += 2U * pair_count;
    trace.maximum_coefficient_payload_bytes = std::max(
        trace.maximum_coefficient_payload_bytes, payload_bytes);
    return true;
}

struct JointEvaluationTape {
    bool passed = false;
    std::string failure;
    Evaluation evaluation;
    JointPressureTape tape;
};

bool exact_evaluation_values(
    const Evaluation& lhs, const Evaluation& rhs);

JointOwnerGatherPlan build_joint_owner_gather_plan(
    const JointNeighborhood& neighborhood,
    const std::vector<double>& compression,
    JointOwnerDataflowTrace& trace) {
    JointOwnerGatherPlan plan;
    const std::size_t fluid_count = neighborhood.fluid.size();
    const std::size_t total = fluid_count + neighborhood.support.size();
    const std::size_t directed =
        neighborhood.flat_directed_pair_indices.size();
    if (!neighborhood.passed || !neighborhood.flat_adjacency
        || neighborhood.flat_offsets.size() != fluid_count + 1U
        || compression.size() != fluid_count
        || directed > std::numeric_limits<std::uint32_t>::max()
        || total >= std::numeric_limits<std::uint32_t>::max()) {
        plan.failure = "OWNER_GATHER_SOURCE";
        return plan;
    }
    plan.source_by_slot.resize(directed);
    std::vector<std::size_t> target_degree(total);
    std::size_t active_directed = 0U;
    for (std::size_t center = 0U; center < fluid_count; ++center) {
        const std::size_t begin = neighborhood.flat_offsets[center];
        const std::size_t end = neighborhood.flat_offsets[center + 1U];
        if (end < begin || end > directed) {
            plan.failure = "OWNER_GATHER_ADJACENCY";
            return plan;
        }
        for (std::size_t slot = begin; slot < end; ++slot) {
            plan.source_by_slot[slot] = static_cast<std::uint32_t>(center);
            if (compression[center] <= 0.0) {
                continue;
            }
            const std::size_t pair_index =
                neighborhood.flat_directed_pair_indices[slot];
            if (pair_index >= neighborhood.pairs.size()) {
                plan.failure = "OWNER_GATHER_PAIR";
                return plan;
            }
            const std::size_t participant = joint_pair_participant(
                neighborhood, neighborhood.pairs[pair_index], center);
            if (participant >= total || participant == center) {
                plan.failure = "OWNER_GATHER_TARGET";
                return plan;
            }
            if (active_directed == std::numeric_limits<std::size_t>::max()
                || target_degree[center]
                    == std::numeric_limits<std::size_t>::max()
                || target_degree[participant]
                    == std::numeric_limits<std::size_t>::max()) {
                plan.failure = "OWNER_GATHER_CAPACITY";
                return plan;
            }
            ++active_directed;
            ++target_degree[center];
            ++target_degree[participant];
        }
    }
    if (active_directed
            > std::numeric_limits<std::uint32_t>::max() / 2U) {
        plan.failure = "OWNER_GATHER_CAPACITY";
        return plan;
    }
    const std::size_t target_entries = 2U * active_directed;
    plan.target_offsets.resize(total + 1U);
    plan.target_slots.resize(target_entries);
    std::vector<std::size_t> cursor(total);
    std::size_t offset = 0U;
    for (std::size_t target = 0U; target < total; ++target) {
        plan.target_offsets[target] = static_cast<std::uint32_t>(offset);
        cursor[target] = offset;
        offset += target_degree[target];
    }
    plan.target_offsets[total] = static_cast<std::uint32_t>(offset);
    if (offset != target_entries) {
        ++trace.coverage_mismatches;
        plan.failure = "OWNER_GATHER_COVERAGE";
        return plan;
    }
    for (std::size_t center = 0U; center < fluid_count; ++center) {
        if (compression[center] <= 0.0) {
            continue;
        }
        const std::size_t begin = neighborhood.flat_offsets[center];
        const std::size_t end = neighborhood.flat_offsets[center + 1U];
        for (std::size_t slot = begin; slot < end; ++slot) {
            const std::size_t pair_index =
                neighborhood.flat_directed_pair_indices[slot];
            const std::size_t participant = joint_pair_participant(
                neighborhood, neighborhood.pairs[pair_index], center);
            plan.target_slots[cursor[center]++] =
                static_cast<std::uint32_t>(slot);
            plan.target_slots[cursor[participant]++] =
                static_cast<std::uint32_t>(slot);
        }
    }
    for (std::size_t target = 0U; target < total; ++target) {
        std::size_t previous = 0U;
        bool have_previous = false;
        for (std::size_t entry = plan.target_offsets[target];
             entry < plan.target_offsets[target + 1U]; ++entry) {
            const std::size_t slot = plan.target_slots[entry];
            if (slot >= directed || (have_previous && slot <= previous)) {
                ++trace.order_mismatches;
                plan.failure = "OWNER_GATHER_ORDER";
                return plan;
            }
            const std::size_t source = plan.source_by_slot[slot];
            const std::size_t pair_index =
                neighborhood.flat_directed_pair_indices[slot];
            const std::size_t participant = joint_pair_participant(
                neighborhood, neighborhood.pairs[pair_index], source);
            if (target != source && target != participant) {
                ++trace.coverage_mismatches;
                plan.failure = "OWNER_GATHER_TARGET";
                return plan;
            }
            previous = slot;
            have_previous = true;
        }
    }
    plan.payload_bytes =
        plan.source_by_slot.size() * sizeof(std::uint32_t)
        + plan.target_offsets.size() * sizeof(std::uint32_t)
        + plan.target_slots.size() * sizeof(std::uint32_t);
    ++trace.plan_validations;
    plan.passed = true;
    return plan;
}

JointOwnerGatherPlan b4ep10pd_build_masked_superset_gather_plan(
    const JointNeighborhood& superset,
    const JointOwnerTopologyPlan& topology) {
    JointOwnerGatherPlan plan;
    const std::size_t fluid_count = superset.fluid.size();
    const std::size_t total = fluid_count + superset.support.size();
    const std::size_t directed = topology.pair_indices.size();
    if (!superset.passed || !topology.passed || fluid_count == 0U
        || total >= std::numeric_limits<std::uint32_t>::max()
        || directed > std::numeric_limits<std::uint32_t>::max()
        || topology.offsets.size() != fluid_count + 1U
        || topology.offsets.empty() || topology.offsets.front() != 0U
        || topology.offsets.back() != directed) {
        plan.failure = "MASKED_SUPERSET_PLAN_SOURCE";
        return plan;
    }
    if (directed > std::numeric_limits<std::uint32_t>::max() / 2U) {
        plan.failure = "MASKED_SUPERSET_PLAN_CAPACITY";
        return plan;
    }
    plan.source_by_slot.resize(directed);
    std::vector<std::size_t> target_degree(total);
    for (std::size_t source = 0U; source < fluid_count; ++source) {
        const std::size_t begin = topology.offsets[source];
        const std::size_t end = topology.offsets[source + 1U];
        if (end < begin || end > directed) {
            plan.failure = "MASKED_SUPERSET_PLAN_ROW";
            return plan;
        }
        for (std::size_t slot = begin; slot < end; ++slot) {
            const std::size_t pair_index = topology.pair_indices[slot];
            if (pair_index >= superset.pairs.size()) {
                plan.failure = "MASKED_SUPERSET_PLAN_PAIR";
                return plan;
            }
            const std::size_t participant = joint_pair_participant(
                superset, superset.pairs[pair_index], source);
            if (participant >= total || participant == source
                || target_degree[source]
                    == std::numeric_limits<std::size_t>::max()
                || target_degree[participant]
                    == std::numeric_limits<std::size_t>::max()) {
                plan.failure = "MASKED_SUPERSET_PLAN_TARGET";
                return plan;
            }
            plan.source_by_slot[slot] =
                static_cast<std::uint32_t>(source);
            ++target_degree[source];
            ++target_degree[participant];
        }
    }
    const std::size_t target_entries = 2U * directed;
    plan.target_offsets.resize(total + 1U);
    plan.target_slots.resize(target_entries);
    std::vector<std::size_t> cursor(total);
    std::size_t offset = 0U;
    for (std::size_t target = 0U; target < total; ++target) {
        if (target_degree[target]
                > std::numeric_limits<std::uint32_t>::max() - offset) {
            plan.failure = "MASKED_SUPERSET_PLAN_CAPACITY";
            return plan;
        }
        plan.target_offsets[target] = static_cast<std::uint32_t>(offset);
        cursor[target] = offset;
        offset += target_degree[target];
    }
    plan.target_offsets[total] = static_cast<std::uint32_t>(offset);
    if (offset != target_entries) {
        plan.failure = "MASKED_SUPERSET_PLAN_COVERAGE";
        return plan;
    }
    for (std::size_t source = 0U; source < fluid_count; ++source) {
        for (std::size_t slot = topology.offsets[source];
             slot < topology.offsets[source + 1U]; ++slot) {
            const std::size_t pair_index = topology.pair_indices[slot];
            const std::size_t participant = joint_pair_participant(
                superset, superset.pairs[pair_index], source);
            plan.target_slots[cursor[source]++] =
                static_cast<std::uint32_t>(slot);
            plan.target_slots[cursor[participant]++] =
                static_cast<std::uint32_t>(slot);
        }
    }
    for (std::size_t target = 0U; target < total; ++target) {
        std::size_t previous = 0U;
        bool have_previous = false;
        for (std::size_t entry = plan.target_offsets[target];
             entry < plan.target_offsets[target + 1U]; ++entry) {
            const std::size_t slot = plan.target_slots[entry];
            if (slot >= directed || (have_previous && slot <= previous)) {
                plan.failure = "MASKED_SUPERSET_PLAN_ORDER";
                return plan;
            }
            const std::size_t source = plan.source_by_slot[slot];
            const std::size_t pair_index = topology.pair_indices[slot];
            const std::size_t participant = joint_pair_participant(
                superset, superset.pairs[pair_index], source);
            if (target != source && target != participant) {
                plan.failure = "MASKED_SUPERSET_PLAN_TARGET";
                return plan;
            }
            previous = slot;
            have_previous = true;
        }
    }
    const std::size_t source_bytes = plan.source_by_slot.size()
        * sizeof(std::uint32_t);
    const std::size_t offset_bytes = plan.target_offsets.size()
        * sizeof(std::uint32_t);
    const std::size_t target_bytes = plan.target_slots.size()
        * sizeof(std::uint32_t);
    if (source_bytes > std::numeric_limits<std::size_t>::max()
            - offset_bytes
        || source_bytes + offset_bytes
            > std::numeric_limits<std::size_t>::max() - target_bytes) {
        plan.failure = "MASKED_SUPERSET_PLAN_PAYLOAD";
        return plan;
    }
    plan.payload_bytes = source_bytes + offset_bytes + target_bytes;
    plan.passed = true;
    return plan;
}

struct B4EP10PDSequenceCheck {
    bool passed = false;
    std::string failure;
    std::size_t full_entries_scanned = 0U;
    std::size_t retained_entries = 0U;
};

B4EP10PDSequenceCheck b4ep10pd_check_masked_plan_sequence(
    const JointNeighborhood& neighborhood,
    const std::vector<double>& compression,
    const JointOwnerGatherPlan& active_plan,
    const JointOwnerGatherPlan& fixed_plan) {
    B4EP10PDSequenceCheck result;
    constexpr std::uint32_t missing =
        std::numeric_limits<std::uint32_t>::max();
    const std::size_t fluid_count = neighborhood.fluid.size();
    const std::size_t total = fluid_count + neighborhood.support.size();
    const std::size_t directed =
        neighborhood.flat_directed_pair_indices.size();
    if (!neighborhood.passed || !neighborhood.flat_adjacency
        || compression.size() != fluid_count || !active_plan.passed
        || !fixed_plan.passed
        || neighborhood.flat_offsets.size() != fluid_count + 1U
        || active_plan.source_by_slot.size() != directed
        || active_plan.target_offsets.size() != total + 1U
        || fixed_plan.target_offsets.size() != total + 1U
        || neighborhood.superset_slot_to_current_slot.size()
            != fixed_plan.source_by_slot.size()) {
        result.failure = "MASKED_PLAN_SEQUENCE_SOURCE";
        return result;
    }
    result.full_entries_scanned = fixed_plan.target_slots.size();
    std::size_t positive_directed = 0U;
    for (std::size_t source = 0U; source < fluid_count; ++source) {
        if (compression[source] <= 0.0) {
            continue;
        }
        const std::size_t row = neighborhood.flat_offsets[source + 1U]
            - neighborhood.flat_offsets[source];
        if (row > std::numeric_limits<std::size_t>::max()
                - positive_directed) {
            result.failure = "MASKED_PLAN_SEQUENCE_CAPACITY";
            return result;
        }
        positive_directed += row;
    }
    if (positive_directed
            > std::numeric_limits<std::size_t>::max() / 2U
        || active_plan.target_slots.size() != 2U * positive_directed) {
        result.failure = "MASKED_PLAN_SEQUENCE_COVERAGE";
        return result;
    }
    for (std::size_t target = 0U; target < total; ++target) {
        const std::size_t active_begin = active_plan.target_offsets[target];
        const std::size_t active_end = active_plan.target_offsets[target + 1U];
        const std::size_t fixed_begin = fixed_plan.target_offsets[target];
        const std::size_t fixed_end = fixed_plan.target_offsets[target + 1U];
        if (active_end < active_begin
            || active_end > active_plan.target_slots.size()
            || fixed_end < fixed_begin
            || fixed_end > fixed_plan.target_slots.size()) {
            result.failure = "MASKED_PLAN_SEQUENCE_ROW";
            return result;
        }
        std::size_t active_entry = active_begin;
        for (std::size_t entry = fixed_begin; entry < fixed_end; ++entry) {
            const std::size_t fixed_slot = fixed_plan.target_slots[entry];
            if (fixed_slot >= fixed_plan.source_by_slot.size()) {
                result.failure = "MASKED_PLAN_SEQUENCE_FIXED_SLOT";
                return result;
            }
            const std::uint32_t mapped =
                neighborhood.superset_slot_to_current_slot[fixed_slot];
            if (mapped == missing) {
                continue;
            }
            const std::size_t current_slot = mapped;
            if (current_slot >= directed) {
                result.failure = "MASKED_PLAN_SEQUENCE_MAPPING";
                return result;
            }
            const std::size_t source = fixed_plan.source_by_slot[fixed_slot];
            if (source >= fluid_count) {
                result.failure = "MASKED_PLAN_SEQUENCE_SOURCE_SLOT";
                return result;
            }
            if (compression[source] <= 0.0) {
                continue;
            }
            if (active_entry >= active_end
                || active_plan.target_slots[active_entry] != current_slot
                || active_plan.source_by_slot[current_slot] != source) {
                result.failure = "MASKED_PLAN_SEQUENCE_ORDER";
                return result;
            }
            const std::size_t pair_index =
                neighborhood.flat_directed_pair_indices[current_slot];
            if (pair_index >= neighborhood.pairs.size()) {
                result.failure = "MASKED_PLAN_SEQUENCE_PAIR";
                return result;
            }
            const std::size_t participant = joint_pair_participant(
                neighborhood, neighborhood.pairs[pair_index], source);
            if (target != source && target != participant) {
                result.failure = "MASKED_PLAN_SEQUENCE_TARGET";
                return result;
            }
            ++active_entry;
            ++result.retained_entries;
        }
        if (active_entry != active_end) {
            result.failure = "MASKED_PLAN_SEQUENCE_COVERAGE";
            return result;
        }
    }
    result.passed = result.retained_entries
        == active_plan.target_slots.size();
    if (!result.passed) {
        result.failure = "MASKED_PLAN_SEQUENCE_RETAINED";
    }
    return result;
}

bool b4ep10pd_audit_masked_plan(
    const JointNeighborhood& neighborhood,
    const std::vector<double>& compression,
    const JointOwnerGatherPlan& active_plan,
    JointParallelTrace& parallel) {
    JointMaskedSupersetPlanAuditTrace& audit =
        parallel.masked_plan_audit;
    if (!audit.enabled || audit.fixed_plan == nullptr) {
        ++audit.mapping_mismatches;
        return false;
    }
    const B4EP10PDSequenceCheck check =
        b4ep10pd_check_masked_plan_sequence(
            neighborhood, compression, active_plan, *audit.fixed_plan);
    if (!check.passed
        || check.full_entries_scanned
            > std::numeric_limits<std::size_t>::max()
                - audit.full_entries_scanned
        || check.retained_entries
            > std::numeric_limits<std::size_t>::max()
                - audit.retained_entries) {
        if (check.failure == "MASKED_PLAN_SEQUENCE_ORDER") {
            ++audit.order_mismatches;
        } else if (check.failure == "MASKED_PLAN_SEQUENCE_MAPPING") {
            ++audit.mapping_mismatches;
        } else {
            ++audit.coverage_mismatches;
        }
        return false;
    }
    if (audit.plan_audits == 0U) {
        JointNeighborhood corrupt_mapping = neighborhood;
        auto mapped = std::find_if(
            corrupt_mapping.superset_slot_to_current_slot.begin(),
            corrupt_mapping.superset_slot_to_current_slot.end(),
            [](std::uint32_t value) {
                return value != std::numeric_limits<std::uint32_t>::max();
            });
        if (mapped != corrupt_mapping.superset_slot_to_current_slot.end()) {
            *mapped = static_cast<std::uint32_t>(
                active_plan.source_by_slot.size());
            audit.mapping_negative_rejected =
                !b4ep10pd_check_masked_plan_sequence(
                    corrupt_mapping, compression, active_plan,
                    *audit.fixed_plan).passed;
        }
        JointOwnerGatherPlan corrupt_target = *audit.fixed_plan;
        if (!corrupt_target.target_slots.empty()) {
            corrupt_target.target_slots.front() =
                static_cast<std::uint32_t>(
                    corrupt_target.source_by_slot.size());
            audit.target_negative_rejected =
                !b4ep10pd_check_masked_plan_sequence(
                    neighborhood, compression, active_plan,
                    corrupt_target).passed;
        }
    }
    audit.full_entries_scanned += check.full_entries_scanned;
    audit.retained_entries += check.retained_entries;
    ++audit.plan_audits;
    return true;
}

bool b4ep10ctd_current_plan_sequence_exact(
    const JointOwnerGatherPlan& full,
    const JointOwnerGatherPlan& active,
    const std::vector<double>& compression,
    std::size_t& full_entries,
    std::size_t& retained_entries) {
    full_entries = 0U;
    retained_entries = 0U;
    if (!full.passed || !active.passed
        || full.source_by_slot != active.source_by_slot
        || full.target_offsets.size() != active.target_offsets.size()
        || full.target_offsets.empty() || active.target_offsets.empty()
        || full.target_offsets.front() != 0U
        || active.target_offsets.front() != 0U
        || full.target_offsets.back() != full.target_slots.size()
        || active.target_offsets.back() != active.target_slots.size()) {
        return false;
    }
    for (std::size_t target = 0U;
         target + 1U < full.target_offsets.size(); ++target) {
        const std::size_t full_begin = full.target_offsets[target];
        const std::size_t full_end = full.target_offsets[target + 1U];
        const std::size_t active_begin = active.target_offsets[target];
        const std::size_t active_end = active.target_offsets[target + 1U];
        if (full_end < full_begin || full_end > full.target_slots.size()
            || active_end < active_begin
            || active_end > active.target_slots.size()) {
            return false;
        }
        std::size_t active_entry = active_begin;
        std::size_t previous = 0U;
        bool have_previous = false;
        for (std::size_t entry = full_begin; entry < full_end; ++entry) {
            const std::size_t slot = full.target_slots[entry];
            if (slot >= full.source_by_slot.size()
                || (have_previous && slot <= previous)) {
                return false;
            }
            const std::size_t source = full.source_by_slot[slot];
            if (source >= compression.size()) {
                return false;
            }
            if (compression[source] > 0.0) {
                if (active_entry >= active_end
                    || active.target_slots[active_entry] != slot) {
                    return false;
                }
                ++active_entry;
                ++retained_entries;
            }
            previous = slot;
            have_previous = true;
            ++full_entries;
        }
        if (active_entry != active_end) {
            return false;
        }
    }
    return retained_entries == active.target_slots.size();
}

bool b4ep10ctd_audit_current_topology_plan(
    const JointNeighborhood& neighborhood,
    const std::vector<double>& compression,
    const JointOwnerGatherPlan& active_plan,
    JointOwnerGatherPlan& full_plan,
    JointParallelTrace& parallel) {
    JointCurrentTopologyPlanAuditTrace& audit =
        parallel.current_topology_plan_audit;
    std::vector<double> sentinel(compression.size(), 1.0);
    JointOwnerDataflowTrace plan_trace;
    JointOwnerGatherPlan candidate = build_joint_owner_gather_plan(
        neighborhood, sentinel, plan_trace);
    std::size_t full_entries = 0U;
    std::size_t retained_entries = 0U;
    if (!candidate.passed
        || !b4ep10ctd_current_plan_sequence_exact(
            candidate, active_plan, compression,
            full_entries, retained_entries)) {
        ++audit.order_mismatches;
        return false;
    }
    if (full_entries != candidate.target_slots.size()
        || retained_entries != active_plan.target_slots.size()) {
        ++audit.coverage_mismatches;
        return false;
    }
    if (audit.plan_audits == 0U) {
        JointOwnerGatherPlan wrong_source = candidate;
        if (!wrong_source.source_by_slot.empty()) {
            wrong_source.source_by_slot.front() =
                static_cast<std::uint32_t>(compression.size());
            std::size_t ignored_full = 0U;
            std::size_t ignored_retained = 0U;
            audit.source_negative_rejected =
                !b4ep10ctd_current_plan_sequence_exact(
                    wrong_source, active_plan, compression,
                    ignored_full, ignored_retained);
        }
        JointOwnerGatherPlan wrong_target = candidate;
        if (!wrong_target.target_slots.empty()) {
            wrong_target.target_slots.front() =
                static_cast<std::uint32_t>(
                    wrong_target.source_by_slot.size());
            std::size_t ignored_full = 0U;
            std::size_t ignored_retained = 0U;
            audit.target_negative_rejected =
                !b4ep10ctd_current_plan_sequence_exact(
                    wrong_target, active_plan, compression,
                    ignored_full, ignored_retained);
        }
    }
    ++audit.plan_audits;
    ++audit.evaluation_calls;
    audit.evaluation_full_entries += full_entries;
    audit.evaluation_retained_entries += retained_entries;
    audit.maximum_full_plan_payload_bytes = std::max(
        audit.maximum_full_plan_payload_bytes,
        candidate.payload_bytes);
    full_plan = std::move(candidate);
    return true;
}

bool b4ep10sid_split_sequence_exact(
    const JointNeighborhood& neighborhood,
    const JointOwnerGatherPlan& full,
    const JointOwnerGatherPlan& active,
    const std::vector<double>& compression,
    bool shift_first_own_boundary,
    std::size_t& incoming_full,
    std::size_t& incoming_retained,
    std::size_t& own_retained) {
    incoming_full = 0U;
    incoming_retained = 0U;
    own_retained = 0U;
    const std::size_t fluid_count = neighborhood.fluid.size();
    const std::size_t directed = full.source_by_slot.size();
    if (!full.passed || !active.passed
        || compression.size() != fluid_count
        || neighborhood.flat_offsets.size() != fluid_count + 1U
        || full.source_by_slot != active.source_by_slot
        || full.target_offsets.size() != active.target_offsets.size()
        || full.target_offsets.empty()
        || full.target_offsets.back() != full.target_slots.size()
        || active.target_offsets.back() != active.target_slots.size()) {
        return false;
    }
    bool boundary_shifted = false;
    for (std::size_t target = 0U;
         target + 1U < full.target_offsets.size(); ++target) {
        std::size_t own_begin = directed;
        std::size_t own_end = directed;
        if (target < fluid_count) {
            own_begin = neighborhood.flat_offsets[target];
            own_end = neighborhood.flat_offsets[target + 1U];
            if (shift_first_own_boundary && !boundary_shifted
                && own_begin < own_end) {
                ++own_begin;
                boundary_shifted = true;
            }
        }
        const std::size_t active_begin = active.target_offsets[target];
        const std::size_t active_end = active.target_offsets[target + 1U];
        std::size_t active_entry = active_begin;
        const auto consume = [&](std::size_t slot) {
            if (active_entry >= active_end
                || active.target_slots[active_entry] != slot) {
                return false;
            }
            ++active_entry;
            return true;
        };
        for (std::size_t entry = full.target_offsets[target];
             entry < full.target_offsets[target + 1U]; ++entry) {
            const std::size_t slot = full.target_slots[entry];
            if (slot >= directed) {
                return false;
            }
            const std::size_t source = full.source_by_slot[slot];
            if (source >= fluid_count) {
                return false;
            }
            if (source == target) {
                if (target >= fluid_count
                    || slot < own_begin || slot >= own_end) {
                    return false;
                }
                continue;
            }
            if (slot >= own_begin && slot < own_end) {
                return false;
            }
            ++incoming_full;
            if (compression[source] > 0.0) {
                ++incoming_retained;
                if (slot < own_begin && !consume(slot)) {
                    return false;
                }
            }
        }
        if (target < fluid_count && compression[target] > 0.0) {
            for (std::size_t slot = own_begin; slot < own_end; ++slot) {
                if (slot >= full.source_by_slot.size()
                    || full.source_by_slot[slot] != target
                    || !consume(slot)) {
                    return false;
                }
                ++own_retained;
            }
        }
        for (std::size_t entry = full.target_offsets[target];
             entry < full.target_offsets[target + 1U]; ++entry) {
            const std::size_t slot = full.target_slots[entry];
            if (slot >= directed) {
                return false;
            }
            const std::size_t source = full.source_by_slot[slot];
            if (source != target && source < fluid_count
                && compression[source] > 0.0
                && slot >= own_end && !consume(slot)) {
                return false;
            }
        }
        if (active_entry != active_end) {
            return false;
        }
    }
    return !shift_first_own_boundary || boundary_shifted;
}

bool b4ep10sid_audit_split_incoming_plan(
    const JointNeighborhood& neighborhood,
    const std::vector<double>& compression,
    const JointOwnerGatherPlan& active_plan,
    JointOwnerGatherPlan& full_plan,
    JointParallelTrace& parallel) {
    JointSplitIncomingPlanAuditTrace& audit =
        parallel.split_incoming_plan_audit;
    std::vector<double> sentinel(compression.size(), 1.0);
    JointOwnerDataflowTrace plan_trace;
    JointOwnerGatherPlan candidate = build_joint_owner_gather_plan(
        neighborhood, sentinel, plan_trace);
    std::size_t incoming_full = 0U;
    std::size_t incoming_retained = 0U;
    std::size_t own_retained = 0U;
    if (!candidate.passed
        || !b4ep10sid_split_sequence_exact(
            neighborhood, candidate, active_plan, compression, false,
            incoming_full, incoming_retained, own_retained)) {
        ++audit.order_mismatches;
        return false;
    }
    const std::size_t directed = candidate.source_by_slot.size();
    if (incoming_full != directed
        || incoming_retained != active_plan.target_slots.size() / 2U
        || own_retained != active_plan.target_slots.size() / 2U
        || active_plan.target_slots.size() % 2U != 0U) {
        ++audit.coverage_mismatches;
        return false;
    }
    if (audit.plan_audits == 0U) {
        std::size_t ignored_incoming = 0U;
        std::size_t ignored_retained = 0U;
        std::size_t ignored_own = 0U;
        audit.own_boundary_negative_rejected =
            !b4ep10sid_split_sequence_exact(
                neighborhood, candidate, active_plan, compression, true,
                ignored_incoming, ignored_retained, ignored_own);
        JointOwnerGatherPlan wrong_target = candidate;
        bool corrupted = false;
        for (std::size_t target = 0U;
             !corrupted && target + 1U < wrong_target.target_offsets.size();
             ++target) {
            for (std::size_t entry = wrong_target.target_offsets[target];
                 entry < wrong_target.target_offsets[target + 1U]; ++entry) {
                const std::size_t slot = wrong_target.target_slots[entry];
                if (wrong_target.source_by_slot[slot] != target) {
                    wrong_target.target_slots[entry] =
                        static_cast<std::uint32_t>(directed);
                    corrupted = true;
                    break;
                }
            }
        }
        audit.incoming_target_negative_rejected = corrupted
            && !b4ep10sid_split_sequence_exact(
                neighborhood, wrong_target, active_plan, compression, false,
                ignored_incoming, ignored_retained, ignored_own);
    }
    const std::size_t source_bytes = directed * sizeof(std::uint32_t);
    const std::size_t offset_bytes = candidate.target_offsets.size()
        * sizeof(std::uint32_t);
    const std::size_t incoming_bytes = incoming_full
        * sizeof(std::uint32_t);
    if (source_bytes > std::numeric_limits<std::size_t>::max()
            - offset_bytes
        || source_bytes + offset_bytes
            > std::numeric_limits<std::size_t>::max() - incoming_bytes) {
        ++audit.coverage_mismatches;
        return false;
    }
    ++audit.plan_audits;
    ++audit.evaluation_calls;
    audit.incoming_full_entries += incoming_full;
    audit.incoming_retained_entries += incoming_retained;
    audit.own_retained_entries += own_retained;
    audit.maximum_incoming_plan_payload_bytes = std::max(
        audit.maximum_incoming_plan_payload_bytes,
        source_bytes + offset_bytes + incoming_bytes);
    full_plan = std::move(candidate);
    return true;
}

JointOwnerGatherPlan b4ep10sid_incoming_oracle(
    const JointOwnerGatherPlan& full) {
    JointOwnerGatherPlan result;
    if (!full.passed || full.target_offsets.empty()
        || full.target_offsets.front() != 0U
        || full.target_offsets.back() != full.target_slots.size()) {
        result.failure = "INCOMING_ORACLE_SOURCE";
        return result;
    }
    const std::size_t total = full.target_offsets.size() - 1U;
    result.source_by_slot = full.source_by_slot;
    result.target_offsets.resize(total + 1U);
    std::size_t output = 0U;
    for (std::size_t target = 0U; target < total; ++target) {
        result.target_offsets[target] = static_cast<std::uint32_t>(output);
        for (std::size_t entry = full.target_offsets[target];
             entry < full.target_offsets[target + 1U]; ++entry) {
            const std::size_t slot = full.target_slots[entry];
            if (slot >= full.source_by_slot.size()) {
                result.failure = "INCOMING_ORACLE_SLOT";
                return result;
            }
            if (full.source_by_slot[slot] != target) {
                result.target_slots.push_back(static_cast<std::uint32_t>(slot));
                ++output;
            }
        }
    }
    result.target_offsets[total] = static_cast<std::uint32_t>(output);
    if (output != full.source_by_slot.size()) {
        result.failure = "INCOMING_ORACLE_COVERAGE";
        return result;
    }
    result.payload_bytes = result.source_by_slot.size()
            * sizeof(std::uint32_t)
        + result.target_offsets.size() * sizeof(std::uint32_t)
        + result.target_slots.size() * sizeof(std::uint32_t);
    result.passed = true;
    return result;
}

enum class B4EP10SICDInjection {
    None,
    PairEndpoint,
    SupportCursor,
};

struct B4EP10SICDPlanBuild {
    JointOwnerGatherPlan plan;
    std::size_t directed_slots = 0U;
    std::size_t incoming_entries = 0U;
    std::size_t pair_visits = 0U;
    std::size_t support_csr_records = 0U;
    std::size_t endpoint_writes = 0U;
    std::size_t target_count_visits = 0U;
    std::size_t target_fill_visits = 0U;
    std::size_t scratch_payload_bytes = 0U;
};

B4EP10SICDPlanBuild b4ep10sicd_build_incoming_plan(
    const JointNeighborhood& neighborhood,
    JointParallelTrace& parallel,
    B4EP10SICDInjection injection = B4EP10SICDInjection::None) {
    B4EP10SICDPlanBuild result;
    JointOwnerGatherPlan& plan = result.plan;
    const std::size_t fluid_count = neighborhood.fluid.size();
    if (fluid_count > std::numeric_limits<std::size_t>::max()
            - neighborhood.support.size()) {
        plan.failure = "INCOMING_CONSTRUCTION_CAPACITY";
        return result;
    }
    const std::size_t total = fluid_count + neighborhood.support.size();
    const std::size_t pair_count = neighborhood.pairs.size();
    const std::size_t directed =
        neighborhood.flat_directed_pair_indices.size();
    constexpr std::uint32_t missing =
        std::numeric_limits<std::uint32_t>::max();
    if (!neighborhood.passed || !neighborhood.flat_adjacency
        || neighborhood.flat_offsets.size() != fluid_count + 1U
        || directed > std::numeric_limits<std::uint32_t>::max()
        || pair_count > std::numeric_limits<std::uint32_t>::max()
        || total >= std::numeric_limits<std::uint32_t>::max()) {
        plan.failure = "INCOMING_CONSTRUCTION_SOURCE";
        return result;
    }
    result.directed_slots = directed;
    plan.source_by_slot.resize(directed);
    std::vector<std::uint32_t> pair_source_slot(pair_count, missing);
    std::vector<std::uint32_t> pair_participant_slot(pair_count, missing);
    const auto source_map = [&](std::size_t begin,
                                std::size_t end, int) {
        for (std::size_t source = begin; source < end; ++source) {
            const std::size_t row_begin = neighborhood.flat_offsets[source];
            const std::size_t row_end = neighborhood.flat_offsets[source + 1U];
            if (row_end < row_begin || row_end > directed) {
                return false;
            }
            for (std::size_t slot = row_begin; slot < row_end; ++slot) {
                const std::size_t pair_index =
                    neighborhood.flat_directed_pair_indices[slot];
                if (pair_index >= pair_count) {
                    return false;
                }
                plan.source_by_slot[slot] =
                    static_cast<std::uint32_t>(source);
                const JointPair pair = neighborhood.pairs[pair_index];
                if (pair.fluid == source) {
                    pair_source_slot[pair_index] =
                        static_cast<std::uint32_t>(slot);
                } else if (pair.participant == source
                    && pair.participant < fluid_count) {
                    pair_participant_slot[pair_index] =
                        static_cast<std::uint32_t>(slot);
                } else {
                    return false;
                }
            }
        }
        return true;
    };
    if (!joint_parallel_for(fluid_count, parallel, source_map)) {
        plan.failure = parallel.failure;
        return result;
    }
    result.endpoint_writes = directed;
    if (injection == B4EP10SICDInjection::PairEndpoint
        && !pair_source_slot.empty()) {
        pair_source_slot.front() = static_cast<std::uint32_t>(directed);
    }

    const std::size_t support_count = neighborhood.support.size();
    std::vector<std::uint32_t> support_offsets(support_count + 1U);
    for (const JointPair pair : neighborhood.pairs) {
        ++result.pair_visits;
        if (pair.participant >= fluid_count) {
            const std::size_t support = pair.participant - fluid_count;
            if (support >= support_count
                || support_offsets[support + 1U]
                    == std::numeric_limits<std::uint32_t>::max()) {
                plan.failure = "INCOMING_CONSTRUCTION_SUPPORT";
                return result;
            }
            ++support_offsets[support + 1U];
            ++result.support_csr_records;
        }
    }
    for (std::size_t support = 0U; support < support_count; ++support) {
        if (support_offsets[support]
                > std::numeric_limits<std::uint32_t>::max()
                    - support_offsets[support + 1U]) {
            plan.failure = "INCOMING_CONSTRUCTION_SUPPORT";
            return result;
        }
        support_offsets[support + 1U] += support_offsets[support];
    }
    std::vector<std::uint32_t> support_pair_indices(
        result.support_csr_records);
    std::vector<std::uint32_t> support_cursor = support_offsets;
    for (std::size_t pair_index = 0U; pair_index < pair_count; ++pair_index) {
        ++result.pair_visits;
        const JointPair pair = neighborhood.pairs[pair_index];
        if (pair.participant >= fluid_count) {
            const std::size_t support = pair.participant - fluid_count;
            const std::size_t cursor = support_cursor[support]++;
            if (cursor >= support_pair_indices.size()) {
                plan.failure = "INCOMING_CONSTRUCTION_SUPPORT";
                return result;
            }
            support_pair_indices[cursor] =
                static_cast<std::uint32_t>(pair_index);
        }
    }
    if (injection == B4EP10SICDInjection::SupportCursor
        && !support_pair_indices.empty()) {
        support_pair_indices.front() = static_cast<std::uint32_t>(pair_count);
    }

    std::vector<std::uint32_t> incoming_degree(total);
    const auto target_count = [&](std::size_t begin,
                                  std::size_t end, int) {
        for (std::size_t target = begin; target < end; ++target) {
            std::size_t degree = 0U;
            if (target < fluid_count) {
                for (std::size_t slot = neighborhood.flat_offsets[target];
                     slot < neighborhood.flat_offsets[target + 1U]; ++slot) {
                    const std::size_t pair_index =
                        neighborhood.flat_directed_pair_indices[slot];
                    if (pair_index >= pair_count) {
                        return false;
                    }
                    const std::size_t participant = joint_pair_participant(
                        neighborhood, neighborhood.pairs[pair_index], target);
                    degree += participant < fluid_count ? 1U : 0U;
                }
            } else {
                const std::size_t support = target - fluid_count;
                degree = support_offsets[support + 1U]
                    - support_offsets[support];
            }
            if (degree > std::numeric_limits<std::uint32_t>::max()) {
                return false;
            }
            incoming_degree[target] = static_cast<std::uint32_t>(degree);
        }
        return true;
    };
    if (!joint_parallel_for(total, parallel, target_count)) {
        plan.failure = parallel.failure;
        return result;
    }
    result.target_count_visits = directed + result.support_csr_records;
    plan.target_offsets.resize(total + 1U);
    std::size_t offset = 0U;
    for (std::size_t target = 0U; target < total; ++target) {
        plan.target_offsets[target] = static_cast<std::uint32_t>(offset);
        if (incoming_degree[target]
                > std::numeric_limits<std::uint32_t>::max() - offset) {
            plan.failure = "INCOMING_CONSTRUCTION_CAPACITY";
            return result;
        }
        offset += incoming_degree[target];
    }
    plan.target_offsets[total] = static_cast<std::uint32_t>(offset);
    if (offset != directed) {
        plan.failure = "INCOMING_CONSTRUCTION_COVERAGE";
        return result;
    }
    result.incoming_entries = offset;
    plan.target_slots.resize(offset);
    const auto target_fill = [&](std::size_t begin,
                                 std::size_t end, int) {
        for (std::size_t target = begin; target < end; ++target) {
            std::size_t cursor = plan.target_offsets[target];
            const std::size_t row_end = plan.target_offsets[target + 1U];
            if (target < fluid_count) {
                for (std::size_t slot = neighborhood.flat_offsets[target];
                     slot < neighborhood.flat_offsets[target + 1U]; ++slot) {
                    const std::size_t pair_index =
                        neighborhood.flat_directed_pair_indices[slot];
                    if (pair_index >= pair_count) {
                        return false;
                    }
                    const JointPair pair = neighborhood.pairs[pair_index];
                    if (pair.participant >= fluid_count) {
                        continue;
                    }
                    const std::uint32_t incoming = pair.fluid == target
                        ? pair_participant_slot[pair_index]
                        : pair_source_slot[pair_index];
                    if (incoming == missing || incoming >= directed
                        || cursor >= row_end) {
                        return false;
                    }
                    plan.target_slots[cursor++] = incoming;
                }
            } else {
                const std::size_t support = target - fluid_count;
                for (std::size_t entry = support_offsets[support];
                     entry < support_offsets[support + 1U]; ++entry) {
                    const std::size_t pair_index = support_pair_indices[entry];
                    if (pair_index >= pair_count) {
                        return false;
                    }
                    const std::uint32_t incoming =
                        pair_source_slot[pair_index];
                    if (incoming == missing || incoming >= directed
                        || cursor >= row_end) {
                        return false;
                    }
                    plan.target_slots[cursor++] = incoming;
                }
            }
            if (cursor != row_end) {
                return false;
            }
            std::size_t previous = 0U;
            bool have_previous = false;
            for (std::size_t entry = plan.target_offsets[target];
                 entry < row_end; ++entry) {
                const std::size_t slot = plan.target_slots[entry];
                if (slot >= directed || (have_previous && slot <= previous)
                    || plan.source_by_slot[slot] == target) {
                    return false;
                }
                previous = slot;
                have_previous = true;
            }
        }
        return true;
    };
    if (!joint_parallel_for(total, parallel, target_fill)) {
        plan.failure = injection == B4EP10SICDInjection::PairEndpoint
            ? "INCOMING_CONSTRUCTION_PAIR_ENDPOINT"
            : injection == B4EP10SICDInjection::SupportCursor
                ? "INCOMING_CONSTRUCTION_SUPPORT_CURSOR"
                : parallel.failure;
        return result;
    }
    result.target_fill_visits = directed + result.support_csr_records;
    plan.payload_bytes = plan.source_by_slot.size() * sizeof(std::uint32_t)
        + plan.target_offsets.size() * sizeof(std::uint32_t)
        + plan.target_slots.size() * sizeof(std::uint32_t);
    result.scratch_payload_bytes =
        2U * pair_count * sizeof(std::uint32_t)
        + support_offsets.size() * sizeof(std::uint32_t)
        + support_pair_indices.size() * sizeof(std::uint32_t)
        + support_cursor.size() * sizeof(std::uint32_t)
        + incoming_degree.size() * sizeof(std::uint32_t);
    plan.passed = true;
    return result;
}

bool b4ep10q2_fused_plan_layout_exact(
    const JointNeighborhood& neighborhood,
    const JointOwnerGatherPlan& plan) {
    if (neighborhood.fluid.size()
            > std::numeric_limits<std::size_t>::max()
                - neighborhood.support.size()) {
        return false;
    }
    const std::size_t total = neighborhood.fluid.size()
        + neighborhood.support.size();
    const std::size_t directed =
        neighborhood.flat_directed_pair_indices.size();
    if (!neighborhood.flat_adjacency || !plan.passed
        || neighborhood.flat_offsets.size()
            != neighborhood.fluid.size() + 1U
        || plan.source_by_slot.size() != directed
        || plan.target_offsets.size() != total + 1U
        || plan.target_offsets.empty()
        || plan.target_offsets.front() != 0U
        || plan.target_offsets.back() != plan.target_slots.size()
        || plan.target_slots.size() != directed) {
        return false;
    }
    const std::size_t element_bytes = sizeof(std::uint32_t);
    if (plan.source_by_slot.size()
            > std::numeric_limits<std::size_t>::max() / element_bytes
        || plan.target_offsets.size()
            > std::numeric_limits<std::size_t>::max() / element_bytes
        || plan.target_slots.size()
            > std::numeric_limits<std::size_t>::max() / element_bytes) {
        return false;
    }
    const std::size_t source_bytes =
        plan.source_by_slot.size() * element_bytes;
    const std::size_t offset_bytes =
        plan.target_offsets.size() * element_bytes;
    const std::size_t target_bytes =
        plan.target_slots.size() * element_bytes;
    if (source_bytes > std::numeric_limits<std::size_t>::max()
            - offset_bytes
        || source_bytes + offset_bytes
            > std::numeric_limits<std::size_t>::max() - target_bytes
        || plan.payload_bytes != source_bytes + offset_bytes + target_bytes) {
        return false;
    }
    for (std::size_t source = 0U;
         source < neighborhood.fluid.size(); ++source) {
        const std::size_t begin = neighborhood.flat_offsets[source];
        const std::size_t end = neighborhood.flat_offsets[source + 1U];
        if (end < begin || end > directed) {
            return false;
        }
        for (std::size_t slot = begin; slot < end; ++slot) {
            if (plan.source_by_slot[slot] != source) {
                return false;
            }
        }
    }
    std::vector<std::uint8_t> seen(directed);
    for (std::size_t target = 0U; target < total; ++target) {
        const std::size_t begin = plan.target_offsets[target];
        const std::size_t end = plan.target_offsets[target + 1U];
        if (end < begin || end > directed) {
            return false;
        }
        std::size_t previous = 0U;
        bool have_previous = false;
        for (std::size_t entry = begin; entry < end; ++entry) {
            const std::size_t slot = plan.target_slots[entry];
            if (slot >= directed || seen[slot] != 0U
                || (have_previous && slot <= previous)) {
                return false;
            }
            const std::size_t source = plan.source_by_slot[slot];
            if (source >= neighborhood.fluid.size()) {
                return false;
            }
            const std::size_t pair_index =
                neighborhood.flat_directed_pair_indices[slot];
            if (pair_index >= neighborhood.pairs.size()
                || joint_pair_participant(
                    neighborhood, neighborhood.pairs[pair_index], source)
                    != target) {
                return false;
            }
            seen[slot] = 1U;
            previous = slot;
            have_previous = true;
        }
    }
    return std::all_of(seen.begin(), seen.end(),
        [](std::uint8_t value) { return value == 1U; });
}

bool b4ep10q2_compare_and_release_fused_plan(
    const JointNeighborhood& neighborhood,
    const B4EP10SICDPlanBuild& accepted,
    JointParallelTrace& parallel) {
    JointTopologyIncomingFusionAuditTrace& audit =
        parallel.topology_incoming_fusion_audit;
    bool exact = audit.enabled && audit.live_plans == 1U
        && audit.pending_plan.passed && accepted.plan.passed
        && b4ep10q2_fused_plan_layout_exact(
            neighborhood, audit.pending_plan)
        && audit.pending_plan.source_by_slot
            == accepted.plan.source_by_slot
        && audit.pending_plan.target_offsets
            == accepted.plan.target_offsets
        && audit.pending_plan.target_slots
            == accepted.plan.target_slots
        && audit.pending_plan.payload_bytes == accepted.plan.payload_bytes;
    if (!exact) {
        ++audit.order_mismatches;
    }
    std::size_t negative_payload_bytes = 0U;
    if (audit.comparisons == 0U && exact) {
        negative_payload_bytes = audit.pending_plan.payload_bytes;
        {
            JointOwnerGatherPlan wrong_endpoint = audit.pending_plan;
            if (!wrong_endpoint.target_slots.empty()) {
                wrong_endpoint.target_slots.front() =
                    static_cast<std::uint32_t>(
                        wrong_endpoint.source_by_slot.size());
                audit.endpoint_negative_rejected =
                    !b4ep10q2_fused_plan_layout_exact(
                        neighborhood, wrong_endpoint);
            }
        }
        {
            JointOwnerGatherPlan wrong_order = audit.pending_plan;
            bool swapped = false;
            for (std::size_t target = 0U;
                 !swapped && target + 1U < wrong_order.target_offsets.size();
                 ++target) {
                const std::size_t begin = wrong_order.target_offsets[target];
                const std::size_t end = wrong_order.target_offsets[target + 1U];
                if (end >= begin + 2U) {
                    std::swap(wrong_order.target_slots[begin],
                        wrong_order.target_slots[begin + 1U]);
                    swapped = true;
                }
            }
            audit.target_order_negative_rejected = swapped
                && !b4ep10q2_fused_plan_layout_exact(
                    neighborhood, wrong_order);
        }
    }
    std::size_t combined = audit.pending_plan.payload_bytes;
    const auto checked_add = [&](std::size_t value) {
        if (value > std::numeric_limits<std::size_t>::max() - combined) {
            return false;
        }
        combined += value;
        return true;
    };
    const bool payload_safe = checked_add(
            audit.maximum_scratch_payload_bytes)
        && checked_add(accepted.plan.payload_bytes)
        && checked_add(accepted.scratch_payload_bytes)
        && checked_add(negative_payload_bytes);
    if (!payload_safe) {
        ++audit.coverage_mismatches;
        exact = false;
    } else {
        audit.maximum_combined_payload_bytes = std::max(
            audit.maximum_combined_payload_bytes, combined);
    }
    ++audit.comparisons;
    audit.pending_plan = JointOwnerGatherPlan{};
    if (audit.live_plans != 1U) {
        ++audit.lifetime_failures;
        exact = false;
        audit.live_plans = 0U;
    } else {
        --audit.live_plans;
    }
    ++audit.releases;
    return exact;
}

bool b4ep10sicd_audit_incoming_construction(
    const JointNeighborhood& neighborhood,
    JointParallelTrace& parallel) {
    JointIncomingConstructionAuditTrace& audit =
        parallel.incoming_construction_audit;
    std::vector<double> sentinel(neighborhood.fluid.size(), 1.0);
    JointOwnerDataflowTrace oracle_trace;
    const JointOwnerGatherPlan full = build_joint_owner_gather_plan(
        neighborhood, sentinel, oracle_trace);
    const JointOwnerGatherPlan oracle = b4ep10sid_incoming_oracle(full);
    const std::size_t regions_before = parallel.regions;
    const std::size_t partitions_before = parallel.logical_partitions;
    const B4EP10SICDPlanBuild candidate =
        b4ep10sicd_build_incoming_plan(neighborhood, parallel);
    if (!oracle.passed || !candidate.plan.passed
        || candidate.plan.source_by_slot != oracle.source_by_slot
        || candidate.plan.target_offsets != oracle.target_offsets
        || candidate.plan.target_slots != oracle.target_slots
        || candidate.plan.payload_bytes != oracle.payload_bytes) {
        ++audit.order_mismatches;
        return false;
    }
    if (parallel.regions < regions_before
        || parallel.logical_partitions < partitions_before) {
        ++audit.coverage_mismatches;
        return false;
    }
    if (audit.plan_audits == 0U) {
        JointParallelTrace endpoint_negative;
        endpoint_negative.enabled = true;
        endpoint_negative.requested_workers = parallel.requested_workers;
        const B4EP10SICDPlanBuild wrong_endpoint =
            b4ep10sicd_build_incoming_plan(
                neighborhood, endpoint_negative,
                B4EP10SICDInjection::PairEndpoint);
        audit.pair_endpoint_negative_rejected =
            !wrong_endpoint.plan.passed;
        JointParallelTrace cursor_negative;
        cursor_negative.enabled = true;
        cursor_negative.requested_workers = parallel.requested_workers;
        const B4EP10SICDPlanBuild wrong_cursor =
            b4ep10sicd_build_incoming_plan(
                neighborhood, cursor_negative,
                B4EP10SICDInjection::SupportCursor);
        audit.support_cursor_negative_rejected =
            !wrong_cursor.plan.passed;
    }
    ++audit.plan_audits;
    audit.directed_slots += candidate.directed_slots;
    audit.incoming_entries += candidate.incoming_entries;
    audit.pair_visits += candidate.pair_visits;
    audit.support_csr_records += candidate.support_csr_records;
    audit.endpoint_writes += candidate.endpoint_writes;
    audit.target_count_visits += candidate.target_count_visits;
    audit.target_fill_visits += candidate.target_fill_visits;
    audit.added_regions += parallel.regions - regions_before;
    audit.added_logical_partitions +=
        parallel.logical_partitions - partitions_before;
    audit.maximum_candidate_payload_bytes = std::max(
        audit.maximum_candidate_payload_bytes,
        candidate.plan.payload_bytes);
    audit.maximum_scratch_payload_bytes = std::max(
        audit.maximum_scratch_payload_bytes,
        candidate.scratch_payload_bytes);
    return true;
}

enum class B4EP10PCDInjection {
    None,
    LocalCount,
    PartitionBase,
};

struct B4EP10PCDPlanBuild {
    JointOwnerGatherPlan plan;
    std::size_t directed_slots = 0U;
    std::size_t active_directed_slots = 0U;
    std::size_t target_entries = 0U;
    std::size_t matrix_payload_bytes = 0U;
};

B4EP10PCDPlanBuild b4ep10pcd_build_partitioned_active_plan(
    const JointNeighborhood& neighborhood,
    const std::vector<double>& compression,
    JointParallelTrace& parallel,
    B4EP10PCDInjection injection = B4EP10PCDInjection::None) {
    B4EP10PCDPlanBuild result;
    JointOwnerGatherPlan& plan = result.plan;
    const std::size_t fluid_count = neighborhood.fluid.size();
    if (fluid_count > std::numeric_limits<std::size_t>::max()
            - neighborhood.support.size()) {
        plan.failure = "PARTITIONED_PLAN_CAPACITY";
        return result;
    }
    const std::size_t total = fluid_count + neighborhood.support.size();
    const std::size_t directed =
        neighborhood.flat_directed_pair_indices.size();
    result.directed_slots = directed;
    if (!neighborhood.passed || !neighborhood.flat_adjacency
        || compression.size() != fluid_count || fluid_count == 0U
        || total >= std::numeric_limits<std::uint32_t>::max()
        || directed > std::numeric_limits<std::uint32_t>::max()
        || neighborhood.flat_offsets.size() != fluid_count + 1U
        || neighborhood.flat_offsets.empty()
        || neighborhood.flat_offsets.front() != 0U
        || neighborhood.flat_offsets.back() != directed
        || total > std::numeric_limits<std::size_t>::max()
            / static_cast<std::size_t>(B4EP10_LOGICAL_PARTITIONS)
        || total * static_cast<std::size_t>(B4EP10_LOGICAL_PARTITIONS)
            > std::numeric_limits<std::size_t>::max()
                / sizeof(std::uint32_t)) {
        plan.failure = "PARTITIONED_PLAN_SOURCE";
        return result;
    }
    const std::size_t matrix_records = total
        * static_cast<std::size_t>(B4EP10_LOGICAL_PARTITIONS);
    result.matrix_payload_bytes = matrix_records * sizeof(std::uint32_t);
    std::vector<std::uint32_t> matrix(matrix_records);
    plan.source_by_slot.resize(directed);
    std::array<std::size_t, B4EP10_LOGICAL_PARTITIONS> active_counts{};
    const auto count_sources = [&](std::size_t begin,
                                   std::size_t end, int ordinal) {
        const std::size_t partition = static_cast<std::size_t>(ordinal);
        const std::size_t row = partition * total;
        std::size_t active = 0U;
        for (std::size_t source = begin; source < end; ++source) {
            const std::size_t slot_begin = neighborhood.flat_offsets[source];
            const std::size_t slot_end =
                neighborhood.flat_offsets[source + 1U];
            if (slot_end < slot_begin || slot_end > directed) {
                return false;
            }
            for (std::size_t slot = slot_begin; slot < slot_end; ++slot) {
                plan.source_by_slot[slot] =
                    static_cast<std::uint32_t>(source);
                if (compression[source] <= 0.0) {
                    continue;
                }
                const std::size_t pair_index =
                    neighborhood.flat_directed_pair_indices[slot];
                if (pair_index >= neighborhood.pairs.size()) {
                    return false;
                }
                const std::size_t participant = joint_pair_participant(
                    neighborhood, neighborhood.pairs[pair_index], source);
                if (participant >= total || participant == source
                    || matrix[row + source]
                        == std::numeric_limits<std::uint32_t>::max()
                    || matrix[row + participant]
                        == std::numeric_limits<std::uint32_t>::max()
                    || active == std::numeric_limits<std::size_t>::max()) {
                    return false;
                }
                ++matrix[row + source];
                ++matrix[row + participant];
                ++active;
            }
        }
        active_counts[partition] = active;
        return true;
    };
    if (!joint_parallel_for(fluid_count, parallel, count_sources)) {
        plan.failure = parallel.failure;
        return result;
    }
    result.active_directed_slots = 0U;
    for (const std::size_t value : active_counts) {
        if (value > std::numeric_limits<std::size_t>::max()
                - result.active_directed_slots) {
            plan.failure = "PARTITIONED_PLAN_CAPACITY";
            return result;
        }
        result.active_directed_slots += value;
    }
    if (injection == B4EP10PCDInjection::LocalCount) {
        if (matrix.front() == std::numeric_limits<std::uint32_t>::max()) {
            plan.failure = "PARTITIONED_PLAN_LOCAL_COUNT";
            return result;
        }
        ++matrix.front();
    }

    std::vector<std::uint32_t> target_degree(total);
    const auto total_targets = [&](std::size_t begin,
                                   std::size_t end, int) {
        for (std::size_t target = begin; target < end; ++target) {
            std::size_t degree = 0U;
            for (std::size_t partition = 0U;
                 partition < static_cast<std::size_t>(
                     B4EP10_LOGICAL_PARTITIONS); ++partition) {
                const std::size_t value = matrix[partition * total + target];
                if (degree > std::numeric_limits<std::uint32_t>::max()
                    || value > std::numeric_limits<std::uint32_t>::max()
                        - degree) {
                    return false;
                }
                degree += value;
            }
            target_degree[target] = static_cast<std::uint32_t>(degree);
        }
        return true;
    };
    if (!joint_parallel_for(total, parallel, total_targets)) {
        plan.failure = parallel.failure;
        return result;
    }
    std::size_t target_entries = 0U;
    for (const std::uint32_t degree : target_degree) {
        if (target_entries > std::numeric_limits<std::uint32_t>::max()
                - degree) {
            plan.failure = "PARTITIONED_PLAN_CAPACITY";
            return result;
        }
        target_entries += degree;
    }
    if (result.active_directed_slots
            > std::numeric_limits<std::size_t>::max() / 2U
        || target_entries != 2U * result.active_directed_slots
        || target_entries > std::numeric_limits<std::uint32_t>::max()) {
        plan.failure = injection == B4EP10PCDInjection::LocalCount
            ? "PARTITIONED_PLAN_LOCAL_COUNT"
            : "PARTITIONED_PLAN_COVERAGE";
        return result;
    }
    result.target_entries = target_entries;
    plan.target_offsets.resize(total + 1U);
    plan.target_slots.resize(target_entries);
    std::size_t offset = 0U;
    for (std::size_t target = 0U; target < total; ++target) {
        plan.target_offsets[target] = static_cast<std::uint32_t>(offset);
        offset += target_degree[target];
    }
    plan.target_offsets[total] = static_cast<std::uint32_t>(offset);

    const auto partition_bases = [&](std::size_t begin,
                                     std::size_t end, int) {
        for (std::size_t target = begin; target < end; ++target) {
            std::size_t cursor = plan.target_offsets[target];
            for (std::size_t partition = 0U;
                 partition < static_cast<std::size_t>(
                     B4EP10_LOGICAL_PARTITIONS); ++partition) {
                const std::size_t index = partition * total + target;
                const std::uint32_t count = matrix[index];
                if (injection == B4EP10PCDInjection::PartitionBase
                    && target == 0U && partition == 0U) {
                    return false;
                }
                matrix[index] = static_cast<std::uint32_t>(cursor);
                cursor += count;
            }
            if (cursor != plan.target_offsets[target + 1U]) {
                return false;
            }
        }
        return true;
    };
    if (!joint_parallel_for(total, parallel, partition_bases)) {
        plan.failure = injection == B4EP10PCDInjection::PartitionBase
            ? "PARTITIONED_PLAN_PARTITION_BASE" : parallel.failure;
        return result;
    }

    const auto stable_fill = [&](std::size_t begin,
                                 std::size_t end, int ordinal) {
        const std::size_t partition = static_cast<std::size_t>(ordinal);
        const std::size_t row = partition * total;
        for (std::size_t source = begin; source < end; ++source) {
            if (compression[source] <= 0.0) {
                continue;
            }
            for (std::size_t slot = neighborhood.flat_offsets[source];
                 slot < neighborhood.flat_offsets[source + 1U]; ++slot) {
                const std::size_t pair_index =
                    neighborhood.flat_directed_pair_indices[slot];
                const std::size_t participant = joint_pair_participant(
                    neighborhood, neighborhood.pairs[pair_index], source);
                std::uint32_t& source_cursor = matrix[row + source];
                std::uint32_t& participant_cursor =
                    matrix[row + participant];
                if (source_cursor >= plan.target_offsets[source + 1U]
                    || participant_cursor
                        >= plan.target_offsets[participant + 1U]) {
                    return false;
                }
                plan.target_slots[source_cursor++] =
                    static_cast<std::uint32_t>(slot);
                plan.target_slots[participant_cursor++] =
                    static_cast<std::uint32_t>(slot);
            }
        }
        return true;
    };
    if (!joint_parallel_for(fluid_count, parallel, stable_fill)) {
        plan.failure = parallel.failure;
        return result;
    }

    const auto validate_targets = [&](std::size_t begin,
                                      std::size_t end, int) {
        for (std::size_t target = begin; target < end; ++target) {
            std::size_t previous = 0U;
            bool have_previous = false;
            for (std::size_t entry = plan.target_offsets[target];
                 entry < plan.target_offsets[target + 1U]; ++entry) {
                const std::size_t slot = plan.target_slots[entry];
                if (slot >= directed || (have_previous && slot <= previous)) {
                    return false;
                }
                const std::size_t source = plan.source_by_slot[slot];
                const std::size_t pair_index =
                    neighborhood.flat_directed_pair_indices[slot];
                const std::size_t participant = joint_pair_participant(
                    neighborhood, neighborhood.pairs[pair_index], source);
                if (target != source && target != participant) {
                    return false;
                }
                previous = slot;
                have_previous = true;
            }
        }
        return true;
    };
    if (!joint_parallel_for(total, parallel, validate_targets)) {
        plan.failure = parallel.failure;
        return result;
    }
    const std::size_t source_bytes = plan.source_by_slot.size()
        * sizeof(std::uint32_t);
    const std::size_t offset_bytes = plan.target_offsets.size()
        * sizeof(std::uint32_t);
    const std::size_t target_bytes = plan.target_slots.size()
        * sizeof(std::uint32_t);
    if (source_bytes > std::numeric_limits<std::size_t>::max()
            - offset_bytes
        || source_bytes + offset_bytes
            > std::numeric_limits<std::size_t>::max() - target_bytes) {
        plan.failure = "PARTITIONED_PLAN_PAYLOAD";
        return result;
    }
    plan.payload_bytes = source_bytes + offset_bytes + target_bytes;
    plan.passed = true;
    return result;
}

bool b4ep10pcd_audit_partitioned_active_plan(
    const JointNeighborhood& neighborhood,
    const std::vector<double>& compression,
    const JointOwnerGatherPlan& serial_plan,
    JointParallelTrace& parallel) {
    JointPartitionedActivePlanAuditTrace& audit =
        parallel.partitioned_plan_audit;
    const std::size_t regions_before = parallel.regions;
    const std::size_t partitions_before = parallel.logical_partitions;
    const B4EP10PCDPlanBuild candidate =
        b4ep10pcd_build_partitioned_active_plan(
            neighborhood, compression, parallel);
    if (!candidate.plan.passed
        || candidate.plan.source_by_slot != serial_plan.source_by_slot
        || candidate.plan.target_offsets != serial_plan.target_offsets
        || candidate.plan.target_slots != serial_plan.target_slots
        || candidate.plan.payload_bytes != serial_plan.payload_bytes) {
        ++audit.plan_mismatches;
        return false;
    }
    if (parallel.regions < regions_before
        || parallel.logical_partitions < partitions_before) {
        ++audit.coverage_mismatches;
        return false;
    }
    audit.added_regions += parallel.regions - regions_before;
    audit.added_logical_partitions +=
        parallel.logical_partitions - partitions_before;
    audit.directed_slots += candidate.directed_slots;
    audit.active_directed_slots += candidate.active_directed_slots;
    audit.target_entries += candidate.target_entries;
    audit.maximum_matrix_payload_bytes = std::max(
        audit.maximum_matrix_payload_bytes,
        candidate.matrix_payload_bytes);
    audit.maximum_candidate_plan_payload_bytes = std::max(
        audit.maximum_candidate_plan_payload_bytes,
        candidate.plan.payload_bytes);
    if (candidate.plan.payload_bytes
            > std::numeric_limits<std::size_t>::max()
                - candidate.matrix_payload_bytes
        || serial_plan.payload_bytes
            > std::numeric_limits<std::size_t>::max()
                - candidate.plan.payload_bytes
                - candidate.matrix_payload_bytes) {
        ++audit.coverage_mismatches;
        return false;
    }
    audit.maximum_combined_payload_bytes = std::max(
        audit.maximum_combined_payload_bytes,
        serial_plan.payload_bytes + candidate.plan.payload_bytes
            + candidate.matrix_payload_bytes);
    if (audit.plan_audits == 0U) {
        JointParallelTrace count_negative;
        count_negative.enabled = true;
        count_negative.requested_workers = parallel.requested_workers;
        const B4EP10PCDPlanBuild wrong_count =
            b4ep10pcd_build_partitioned_active_plan(
                neighborhood, compression, count_negative,
                B4EP10PCDInjection::LocalCount);
        audit.local_count_negative_rejected = !wrong_count.plan.passed
            && wrong_count.plan.failure == "PARTITIONED_PLAN_LOCAL_COUNT";
        JointParallelTrace base_negative;
        base_negative.enabled = true;
        base_negative.requested_workers = parallel.requested_workers;
        const B4EP10PCDPlanBuild wrong_base =
            b4ep10pcd_build_partitioned_active_plan(
                neighborhood, compression, base_negative,
                B4EP10PCDInjection::PartitionBase);
        audit.partition_base_negative_rejected = !wrong_base.plan.passed
            && wrong_base.plan.failure
                == "PARTITIONED_PLAN_PARTITION_BASE";
    }
    ++audit.plan_audits;
    return true;
}

struct JointOwnerEvaluation {
    bool passed = false;
    std::string failure;
    Evaluation evaluation;
    std::vector<double> compression;
    JointOwnerGatherPlan plan;
    std::size_t density_gathers = 0U;
    std::size_t directed_values = 0U;
    std::size_t target_gathers = 0U;
    std::size_t scratch_payload_bytes = 0U;
};

JointOwnerEvaluation evaluate_joint_owner_gather(
    const JointNeighborhood& neighborhood,
    const JointPressureTape& oracle_tape,
    JointOwnerDataflowTrace& trace) {
    JointOwnerEvaluation result;
    const std::size_t fluid_count = neighborhood.fluid.size();
    const std::size_t total = fluid_count + neighborhood.support.size();
    const std::size_t directed =
        neighborhood.flat_directed_pair_indices.size();
    if (!neighborhood.passed || !neighborhood.flat_adjacency
        || oracle_tape.radius.size() != neighborhood.pairs.size()
        || oracle_tape.hvp_gradient.size() != neighborhood.pairs.size()) {
        result.failure = "OWNER_EVALUATION_SOURCE";
        return result;
    }
    result.evaluation.gradient.resize(total);
    result.evaluation.density.assign(fluid_count, MASS * weight(0.0));
    std::vector<double> density_contribution(neighborhood.pairs.size());
    for (std::size_t pair_index = 0U;
         pair_index < neighborhood.pairs.size(); ++pair_index) {
        density_contribution[pair_index] =
            MASS * weight(oracle_tape.radius[pair_index]);
        if (neighborhood.pairs[pair_index].participant < fluid_count) {
            ++result.evaluation.fluid_pairs;
        } else {
            ++result.evaluation.boundary_pairs;
        }
    }
    for (std::size_t center = 0U; center < fluid_count; ++center) {
        const std::size_t begin = neighborhood.flat_offsets[center];
        const std::size_t end = neighborhood.flat_offsets[center + 1U];
        for (std::size_t slot = begin; slot < end; ++slot) {
            const std::size_t pair_index =
                neighborhood.flat_directed_pair_indices[slot];
            result.evaluation.density[center] +=
                density_contribution[pair_index];
            ++result.density_gathers;
        }
    }
    result.compression.resize(fluid_count);
    std::vector<double> center_energy(fluid_count);
    for (std::size_t center = 0U; center < fluid_count; ++center) {
        const double compression =
            result.evaluation.density[center] / REST_DENSITY - 1.0;
        result.compression[center] = compression;
        result.evaluation.minimum_branch_margin = std::min(
            result.evaluation.minimum_branch_margin,
            std::abs(compression));
        if (compression > 0.0) {
            ++result.evaluation.active_centers;
            center_energy[center] =
                0.5 * KAPPA * compression * compression;
        }
    }
    for (std::size_t center = 0U; center < fluid_count; ++center) {
        if (result.compression[center] > 0.0) {
            result.evaluation.energy += center_energy[center];
        }
    }
    result.plan = build_joint_owner_gather_plan(
        neighborhood, result.compression, trace);
    if (!result.plan.passed) {
        result.failure = result.plan.failure;
        return result;
    }
    std::vector<Vec3> directed_value(directed);
    for (std::size_t center = 0U; center < fluid_count; ++center) {
        const double compression = result.compression[center];
        if (compression <= 0.0) {
            continue;
        }
        const double scale = KAPPA * compression
            * MASS / REST_DENSITY;
        const std::size_t begin = neighborhood.flat_offsets[center];
        const std::size_t end = neighborhood.flat_offsets[center + 1U];
        for (std::size_t slot = begin; slot < end; ++slot) {
            const std::size_t pair_index =
                neighborhood.flat_directed_pair_indices[slot];
            const JointPair pair = neighborhood.pairs[pair_index];
            const std::size_t participant = joint_pair_participant(
                neighborhood, pair, center);
            const Vec3 displacement = neighborhood.fluid[center].position
                - joint_position(neighborhood, participant);
            const double radius = oracle_tape.radius[pair_index];
            if (radius <= 1.0e-15 || radius > HORIZON) {
                continue;
            }
            directed_value[slot] = scale
                * oracle_tape.hvp_gradient[pair_index]
                * (displacement / radius);
            ++result.directed_values;
        }
    }
    for (std::size_t target = 0U; target < total; ++target) {
        for (std::size_t entry = result.plan.target_offsets[target];
             entry < result.plan.target_offsets[target + 1U]; ++entry) {
            const std::size_t slot = result.plan.target_slots[entry];
            const std::size_t source = result.plan.source_by_slot[slot];
            const Vec3 value = directed_value[slot];
            result.evaluation.gradient[target] +=
                target == source ? value : -value;
            ++result.target_gathers;
        }
    }
    result.scratch_payload_bytes =
        density_contribution.size() * sizeof(double)
        + center_energy.size() * sizeof(double)
        + directed_value.size() * sizeof(Vec3);
    result.passed = result.compression == oracle_tape.compression;
    if (!result.passed) {
        result.failure = "OWNER_EVALUATION_COMPRESSION";
    }
    return result;
}

enum class B4EP10SIRDAInjection {
    None,
    MissingWrite,
    DuplicateRead,
};

struct B4EP10SIRDALiveness {
    bool passed = false;
    std::string failure;
    std::size_t directed_slots = 0U;
    std::size_t active_write_slots = 0U;
    std::size_t target_read_slots = 0U;
    std::size_t assigned_targets = 0U;
    std::size_t payload_bytes = 0U;
};

B4EP10SIRDALiveness b4ep10sirda_audit_liveness(
    const JointNeighborhood& neighborhood,
    const JointPressureTape& tape,
    B4EP10SIRDAInjection injection = B4EP10SIRDAInjection::None) {
    B4EP10SIRDALiveness result;
    const std::size_t fluid_count = neighborhood.fluid.size();
    const std::size_t total = fluid_count + neighborhood.support.size();
    const std::size_t directed = neighborhood.flat_directed_pair_indices.size();
    const JointOwnerGatherPlan& plan = tape.current_topology_gather_plan;
    result.directed_slots = directed;
    if (!plan.passed || tape.compression.size() != fluid_count
        || neighborhood.flat_offsets.size() != fluid_count + 1U
        || plan.source_by_slot.size() != directed
        || plan.target_offsets.size() != total + 1U
        || plan.target_offsets.empty() || plan.target_offsets.front() != 0U
        || plan.target_offsets.back() != plan.target_slots.size()
        || plan.target_slots.size() != directed
        || directed > std::numeric_limits<std::size_t>::max() / 2U) {
        result.failure = "DIRECTED_SCRATCH_SOURCE";
        return result;
    }
    std::vector<std::uint8_t> written(directed);
    std::vector<std::uint8_t> reads(directed);
    result.payload_bytes = 2U * directed;
    std::size_t first_active = directed;
    bool missing_write_injected = false;
    for (std::size_t source = 0U; source < fluid_count; ++source) {
        const std::size_t begin = neighborhood.flat_offsets[source];
        const std::size_t end = neighborhood.flat_offsets[source + 1U];
        if (end < begin || end > directed) {
            result.failure = "DIRECTED_SCRATCH_SOURCE_ROW";
            return result;
        }
        if (tape.compression[source] <= 0.0) {
            continue;
        }
        for (std::size_t slot = begin; slot < end; ++slot) {
            ++result.active_write_slots;
            first_active = std::min(first_active, slot);
            if (injection == B4EP10SIRDAInjection::MissingWrite
                && !missing_write_injected) {
                missing_write_injected = true;
                continue;
            }
            if (written[slot] != 0U) {
                result.failure = "DIRECTED_SCRATCH_WRITE_COVERAGE";
                return result;
            }
            written[slot] = 1U;
        }
    }
    const auto record_read = [&](std::size_t slot) {
        if (slot >= directed || written[slot] != 1U
            || reads[slot] == std::numeric_limits<std::uint8_t>::max()) {
            return false;
        }
        ++reads[slot];
        ++result.target_read_slots;
        return true;
    };
    for (std::size_t target = 0U; target < total; ++target) {
        const std::size_t own_begin = target < fluid_count
            ? neighborhood.flat_offsets[target] : directed;
        const std::size_t own_end = target < fluid_count
            ? neighborhood.flat_offsets[target + 1U] : directed;
        std::size_t entry = plan.target_offsets[target];
        const std::size_t entry_end = plan.target_offsets[target + 1U];
        for (; entry < entry_end; ++entry) {
            const std::size_t slot = plan.target_slots[entry];
            if (slot >= own_begin) {
                break;
            }
            if (slot >= directed) {
                result.failure = "DIRECTED_SCRATCH_TARGET_SLOT";
                return result;
            }
            const std::size_t source = plan.source_by_slot[slot];
            if (source >= fluid_count || source == target) {
                result.failure = "DIRECTED_SCRATCH_TARGET_SOURCE";
                return result;
            }
            if (tape.compression[source] > 0.0 && !record_read(slot)) {
                result.failure = "DIRECTED_SCRATCH_READ_BEFORE_WRITE";
                return result;
            }
        }
        if (target < fluid_count && tape.compression[target] > 0.0) {
            for (std::size_t slot = own_begin; slot < own_end; ++slot) {
                if (!record_read(slot)) {
                    result.failure = "DIRECTED_SCRATCH_READ_BEFORE_WRITE";
                    return result;
                }
            }
        }
        for (; entry < entry_end; ++entry) {
            const std::size_t slot = plan.target_slots[entry];
            if (slot < own_end || slot >= directed) {
                result.failure = "DIRECTED_SCRATCH_TARGET_ORDER";
                return result;
            }
            const std::size_t source = plan.source_by_slot[slot];
            if (source >= fluid_count || source == target) {
                result.failure = "DIRECTED_SCRATCH_TARGET_SOURCE";
                return result;
            }
            if (tape.compression[source] > 0.0 && !record_read(slot)) {
                result.failure = "DIRECTED_SCRATCH_READ_BEFORE_WRITE";
                return result;
            }
        }
        ++result.assigned_targets;
    }
    if (injection == B4EP10SIRDAInjection::DuplicateRead
        && first_active < directed) {
        ++reads[first_active];
        ++result.target_read_slots;
    }
    for (std::size_t slot = 0U; slot < directed; ++slot) {
        if ((written[slot] == 1U && reads[slot] != 2U)
            || (written[slot] == 0U && reads[slot] != 0U)) {
            result.failure = "DIRECTED_SCRATCH_READ_COVERAGE";
            return result;
        }
    }
    if (result.assigned_targets != total
        || result.active_write_slots != tape.active_directed
        || result.target_read_slots != 2U * tape.active_directed) {
        result.failure = "DIRECTED_SCRATCH_ACCOUNTING";
        return result;
    }
    result.passed = true;
    return result;
}

bool b4ep10sirda_record_call(
    JointDirectedScratchAuditTrace& audit,
    std::size_t directed,
    std::size_t active,
    bool hvp) {
    const auto checked_add = [](std::size_t value, std::size_t& total) {
        if (value > std::numeric_limits<std::size_t>::max() - total) {
            return false;
        }
        total += value;
        return true;
    };
    if (active > directed
        || active > std::numeric_limits<std::size_t>::max() / 2U) {
        ++audit.failures;
        return false;
    }
    std::size_t& phase_full = hvp
        ? audit.hvp_full_initialization_slots
        : audit.evaluation_full_initialization_slots;
    const std::size_t growth = directed > audit.high_water_directed_slots
        ? directed - audit.high_water_directed_slots : 0U;
    if (!checked_add(directed, phase_full)
        || !checked_add(directed, audit.full_initialization_slots)
        || !checked_add(active, audit.active_write_slots)
        || !checked_add(2U * active, audit.target_read_slots)
        || !checked_add(growth, audit.high_water_growth_slots)) {
        ++audit.failures;
        return false;
    }
    audit.high_water_directed_slots = std::max(
        audit.high_water_directed_slots, directed);
    audit.eliminated_initialization_slots =
        audit.full_initialization_slots - audit.high_water_growth_slots;
    if (audit.high_water_directed_slots
            > std::numeric_limits<std::size_t>::max() / sizeof(Vec3)) {
        ++audit.failures;
        return false;
    }
    audit.maximum_projected_payload_bytes =
        audit.high_water_directed_slots * sizeof(Vec3);
    if (hvp) {
        ++audit.hvp_calls;
    } else {
        ++audit.evaluation_calls;
    }
    return true;
}

std::vector<Vec3>* b4ep10sirdi_acquire_directed_scratch(
    JointDirectedScratchReuseTrace& reuse,
    std::size_t directed,
    std::size_t active,
    bool hvp) {
    constexpr std::size_t payload_limit = 67108864U;
    const auto checked_add = [](std::size_t value, std::size_t& total) {
        if (value > std::numeric_limits<std::size_t>::max() - total) {
            return false;
        }
        total += value;
        return true;
    };
    if (!reuse.enabled || active > directed
        || directed > payload_limit / sizeof(Vec3)
        || !checked_add(directed, reuse.requested_full_slots)
        || !checked_add(active, reuse.active_write_slots)) {
        ++reuse.failures;
        return nullptr;
    }
    if (directed > reuse.directed_value.size()) {
        const std::size_t growth = directed - reuse.directed_value.size();
        if (!checked_add(growth, reuse.growth_slots)) {
            ++reuse.failures;
            return nullptr;
        }
        reuse.directed_value.resize(directed);
    }
    reuse.maximum_slots = std::max(reuse.maximum_slots, directed);
    reuse.maximum_payload_bytes = std::max(
        reuse.maximum_payload_bytes, directed * sizeof(Vec3));
    if (reuse.live_buffers == 0U) {
        reuse.live_buffers = 1U;
        reuse.maximum_live_buffers = std::max(
            reuse.maximum_live_buffers, reuse.live_buffers);
    }
    ++reuse.calls;
    if (hvp) {
        ++reuse.hvp_calls;
    } else {
        ++reuse.evaluation_calls;
    }
    return &reuse.directed_value;
}

struct B4EP10SIRDIReleaseGuard {
    JointDirectedScratchReuseTrace& reuse;

    ~B4EP10SIRDIReleaseGuard() {
        if (!reuse.enabled) {
            return;
        }
        if (!reuse.directed_value.empty()) {
            std::vector<Vec3>().swap(reuse.directed_value);
            ++reuse.releases;
        }
        reuse.live_buffers = 0U;
    }
};

bool b4ep10sirdirea_add_bytes(
    std::size_t slots, std::size_t element_bytes, std::size_t& total) {
    if (element_bytes != 0U
        && slots > std::numeric_limits<std::size_t>::max() / element_bytes) {
        return false;
    }
    const std::size_t bytes = slots * element_bytes;
    if (bytes > std::numeric_limits<std::size_t>::max() - total) {
        return false;
    }
    total += bytes;
    return true;
}

bool b4ep10sirdirea_update_projected_capacity(
    JointEvaluationBufferAuditTrace& trace) {
    std::size_t capacity_bytes = 0U;
    for (std::size_t lane = 0U;
         lane < trace.workspace_lane_capacity.size(); ++lane) {
        for (std::size_t role = 0U;
             role < JOINT_EVALUATION_RETAINED_BUFFER_COUNT; ++role) {
            if (!b4ep10sirdirea_add_bytes(
                    trace.workspace_lane_capacity[lane][role],
                    JOINT_EVALUATION_BUFFER_ELEMENT_BYTES[role],
                    capacity_bytes)) {
                ++trace.failures;
                return false;
            }
        }
    }
    if (!b4ep10sirdirea_add_bytes(
            trace.ephemeral_capacity, sizeof(double), capacity_bytes)) {
        ++trace.failures;
        return false;
    }
    trace.maximum_projected_capacity_bytes = std::max(
        trace.maximum_projected_capacity_bytes, capacity_bytes);
    return true;
}

bool b4ep10sirdirea_acquire_ephemeral(
    JointEvaluationBufferAuditTrace& trace, std::size_t pair_count) {
    if (!trace.enabled) {
        return true;
    }
    if (trace.ephemeral_live != 0U) {
        ++trace.failures;
        return false;
    }
    ++trace.ephemeral_acquires;
    ++trace.ephemeral_live;
    trace.maximum_ephemeral_live = std::max(
        trace.maximum_ephemeral_live, trace.ephemeral_live);
    if (pair_count > trace.ephemeral_capacity) {
        const std::size_t growth = pair_count - trace.ephemeral_capacity;
        if (!b4ep10sirdirea_add_bytes(
                growth, sizeof(double), trace.projected_growth_bytes)) {
            ++trace.failures;
            return false;
        }
        trace.ephemeral_capacity = pair_count;
    }
    return b4ep10sirdirea_update_projected_capacity(trace);
}

bool b4ep10sirdirea_release_ephemeral(
    JointEvaluationBufferAuditTrace& trace) {
    if (!trace.enabled) {
        return true;
    }
    if (trace.ephemeral_live != 1U) {
        ++trace.unknown_or_duplicate_releases;
        ++trace.failures;
        return false;
    }
    --trace.ephemeral_live;
    ++trace.ephemeral_releases;
    return true;
}

struct B4EP10SIRDIREAEphemeralGuard {
    JointEvaluationBufferAuditTrace& trace;
    bool acquired = false;

    ~B4EP10SIRDIREAEphemeralGuard() {
        if (acquired) {
            static_cast<void>(b4ep10sirdirea_release_ephemeral(trace));
        }
    }
};

struct B4EP10SIRDIREACallAudit {
    JointEvaluationBufferAuditTrace* trace = nullptr;
    std::array<std::vector<std::uint8_t>,
        JOINT_EVALUATION_BUFFER_ROLE_COUNT> written;

    bool begin(
        JointEvaluationBufferAuditTrace& candidate,
        const std::array<std::size_t,
            JOINT_EVALUATION_BUFFER_ROLE_COUNT>& slots) {
        if (!candidate.enabled) {
            return true;
        }
        trace = &candidate;
        std::size_t shadow_payload = 0U;
        for (std::size_t role = 0U; role < slots.size(); ++role) {
            if (slots[role]
                    > std::numeric_limits<std::size_t>::max()
                        - candidate.requested_slots[role]
                || !b4ep10sirdirea_add_bytes(
                    slots[role], JOINT_EVALUATION_BUFFER_ELEMENT_BYTES[role],
                    candidate.repeated_initialization_bytes)
                || slots[role]
                    > std::numeric_limits<std::size_t>::max()
                        - shadow_payload) {
                ++candidate.failures;
                return false;
            }
            candidate.requested_slots[role] += slots[role];
            candidate.maximum_slots[role] = std::max(
                candidate.maximum_slots[role], slots[role]);
            shadow_payload += slots[role];
            written[role].resize(slots[role]);
        }
        candidate.maximum_shadow_payload_bytes = std::max(
            candidate.maximum_shadow_payload_bytes, shadow_payload);
        return true;
    }

    bool record_write(JointEvaluationBufferRole role, std::size_t index) {
        if (trace == nullptr) {
            return true;
        }
        const std::size_t role_index = static_cast<std::size_t>(role);
        if (role_index >= written.size()
            || index >= written[role_index].size()) {
            return false;
        }
        written[role_index][index] = 1U;
        return true;
    }

    bool written_before_read(
        JointEvaluationBufferRole role, std::size_t index) const {
        if (trace == nullptr) {
            return true;
        }
        const std::size_t role_index = static_cast<std::size_t>(role);
        return role_index < written.size()
            && index < written[role_index].size()
            && written[role_index][index] == 1U;
    }

    bool finish(
        std::size_t density_contribution_reads,
        std::size_t density_reads) {
        if (trace == nullptr) {
            return true;
        }
        for (std::size_t role = 0U; role < written.size(); ++role) {
            const std::size_t count = static_cast<std::size_t>(std::count(
                written[role].begin(), written[role].end(),
                static_cast<std::uint8_t>(1U)));
            if (count != written[role].size()
                || count > std::numeric_limits<std::size_t>::max()
                    - trace->written_slots[role]) {
                ++trace->failures;
                return false;
            }
            trace->written_slots[role] += count;
        }
        if (density_contribution_reads
                > std::numeric_limits<std::size_t>::max()
                    - trace->density_contribution_reads
            || density_reads > std::numeric_limits<std::size_t>::max()
                    - trace->density_reads) {
            ++trace->failures;
            return false;
        }
        trace->density_contribution_reads += density_contribution_reads;
        trace->density_reads += density_reads;
        ++trace->calls;
        return true;
    }
};

std::size_t b4ep10sirdirea_acquire_workspace(
    JointEvaluationBufferAuditTrace& trace,
    const std::array<std::size_t,
        JOINT_EVALUATION_RETAINED_BUFFER_COUNT>& slots) {
    if (!trace.enabled) {
        return JOINT_EVALUATION_NO_LANE;
    }
    std::size_t lane = JOINT_EVALUATION_NO_LANE;
    for (std::size_t candidate = 0U;
         candidate < trace.workspace_lane_live.size(); ++candidate) {
        if (!trace.workspace_lane_live[candidate]) {
            lane = candidate;
            break;
        }
    }
    if (lane == JOINT_EVALUATION_NO_LANE) {
        ++trace.failures;
        return lane;
    }
    trace.workspace_lane_live[lane] = true;
    ++trace.workspace_acquires;
    ++trace.workspace_live;
    trace.maximum_workspace_live = std::max(
        trace.maximum_workspace_live, trace.workspace_live);
    for (std::size_t role = 0U; role < slots.size(); ++role) {
        std::size_t& capacity = trace.workspace_lane_capacity[lane][role];
        if (slots[role] > capacity) {
            const std::size_t growth = slots[role] - capacity;
            if (!b4ep10sirdirea_add_bytes(
                    growth, JOINT_EVALUATION_BUFFER_ELEMENT_BYTES[role],
                    trace.projected_growth_bytes)) {
                trace.workspace_lane_live[lane] = false;
                --trace.workspace_live;
                ++trace.failures;
                return JOINT_EVALUATION_NO_LANE;
            }
            capacity = slots[role];
        }
    }
    if (!b4ep10sirdirea_update_projected_capacity(trace)) {
        trace.workspace_lane_live[lane] = false;
        --trace.workspace_live;
        return JOINT_EVALUATION_NO_LANE;
    }
    return lane;
}

bool b4ep10sirdirea_release_workspace(
    JointEvaluationBufferAuditTrace& trace, std::size_t lane) {
    if (!trace.enabled) {
        return true;
    }
    if (lane >= trace.workspace_lane_live.size()
        || !trace.workspace_lane_live[lane]
        || trace.workspace_live == 0U) {
        ++trace.unknown_or_duplicate_releases;
        ++trace.failures;
        return false;
    }
    trace.workspace_lane_live[lane] = false;
    --trace.workspace_live;
    ++trace.workspace_releases;
    return true;
}

bool b4ep10sirdirea_missing_write_negative() {
    std::array<std::uint8_t, 2U> written{1U, 0U};
    return std::count(written.begin(), written.end(),
        static_cast<std::uint8_t>(1U)) != 2;
}

bool b4ep10sirdirea_duplicate_release_negative() {
    JointEvaluationBufferAuditTrace trace;
    trace.enabled = true;
    trace.workspace_lane_live[0] = true;
    trace.workspace_live = 1U;
    return b4ep10sirdirea_release_workspace(trace, 0U)
        && !b4ep10sirdirea_release_workspace(trace, 0U)
        && trace.unknown_or_duplicate_releases == 1U;
}

JointEvaluationTape build_joint_evaluation_tape_owner_parallel_from_flat(
    JointNeighborhood& neighborhood,
    FlatAdjacencyWorkTrace* adjacency_work,
    JointParallelTrace& parallel) {
    JointEvaluationTape result;
    JointParallelTimingStart phase_start = parallel.phase_timing.enabled
        ? joint_parallel_timing_start(parallel.phase_timing)
        : JointParallelTimingStart{};
    JointParallelTimingStart setup_detail_start =
        parallel.phase_timing.evaluation_setup_detail_enabled
        ? joint_parallel_timing_start(parallel.phase_timing)
        : JointParallelTimingStart{};
    const auto finish_phase = [&](JointParallelPhase phase) {
        if (!parallel.phase_timing.enabled) {
            return true;
        }
        const bool recorded = record_joint_parallel_phase(
            parallel.phase_timing, phase, phase_start);
        if (phase != JointParallelPhase::EvaluationFinalize) {
            phase_start = joint_parallel_timing_start(
                parallel.phase_timing);
        }
        if (!recorded) {
            parallel.failed = true;
            parallel.failure = "OWNER_EVALUATION_PHASE_TIMING";
        }
        return recorded;
    };
    const auto finish_setup_detail = [&](std::uint64_t& total_ns,
                                         std::size_t& calls) {
        if (!parallel.phase_timing.evaluation_setup_detail_enabled) {
            return true;
        }
        const bool recorded = add_joint_parallel_duration(
            parallel.phase_timing, setup_detail_start, total_ns, calls);
        setup_detail_start = joint_parallel_timing_start(
            parallel.phase_timing);
        if (!recorded) {
            parallel.failed = true;
            parallel.failure = "OWNER_EVALUATION_SETUP_DETAIL_TIMING";
        }
        return recorded;
    };
    const std::size_t fluid_count = neighborhood.fluid.size();
    const std::size_t total = fluid_count + neighborhood.support.size();
    if (!neighborhood.passed || !neighborhood.flat_adjacency
        || !neighborhood.adjacency.empty()
        || neighborhood.flat_offsets.size() != fluid_count + 1U
        || neighborhood.flat_offsets.empty()
        || neighborhood.flat_offsets.front() != 0U
        || neighborhood.flat_offsets.back()
            != neighborhood.flat_directed_pair_indices.size()
        || neighborhood.pairs.size()
            > std::numeric_limits<std::uint32_t>::max()
        || fluid_count >= std::numeric_limits<std::uint32_t>::max()) {
        result.failure = "OWNER_PARALLEL_EVALUATION_SOURCE";
        return result;
    }
    const std::size_t directed =
        neighborhood.flat_directed_pair_indices.size();
    const std::size_t pair_count = neighborhood.pairs.size();
    if (parallel.evaluation_buffer_audit.enabled
        && (!parallel.incoming_construction_audit.candidate_enabled
            || !parallel.directed_scratch_reuse.enabled
            || parallel.phase_timing.enabled)) {
        ++parallel.evaluation_buffer_audit.failures;
        parallel.failed = true;
        parallel.failure = "EVALUATION_BUFFER_AUDIT_MODE";
        result.failure = parallel.failure;
        return result;
    }
    for (std::size_t center = 0U; center < fluid_count; ++center) {
        const std::size_t begin = neighborhood.flat_offsets[center];
        const std::size_t end = neighborhood.flat_offsets[center + 1U];
        if (end < begin || end > directed) {
            result.failure = "OWNER_PARALLEL_EVALUATION_ADJACENCY";
            return result;
        }
        for (std::size_t slot = begin; slot < end; ++slot) {
            if (neighborhood.flat_directed_pair_indices[slot]
                    >= pair_count) {
                result.failure = "OWNER_PARALLEL_EVALUATION_PAIR";
                return result;
            }
        }
    }
    if (!finish_setup_detail(
            parallel.phase_timing.evaluation_setup_validation_ns,
            parallel.phase_timing.evaluation_setup_validation_calls)) {
        result.failure = parallel.failure;
        return result;
    }
    const std::size_t offsets_bytes = (fluid_count + 1U)
        * sizeof(std::uint32_t);
    const std::size_t indices_bytes = directed * sizeof(std::uint32_t);
    const std::size_t radius_bytes = pair_count * sizeof(double);
    const std::size_t compression_bytes = fluid_count * sizeof(double);
    const std::size_t coefficient_bytes = 2U * radius_bytes;
    if (offsets_bytes > std::numeric_limits<std::size_t>::max()
            - indices_bytes
        || offsets_bytes + indices_bytes
            > std::numeric_limits<std::size_t>::max() - radius_bytes
        || offsets_bytes + indices_bytes + radius_bytes
            > std::numeric_limits<std::size_t>::max() - compression_bytes
        || offsets_bytes + indices_bytes + radius_bytes
                + compression_bytes
            > std::numeric_limits<std::size_t>::max()
                - coefficient_bytes) {
        result.failure = "OWNER_PARALLEL_EVALUATION_CAPACITY";
        return result;
    }
    result.tape.payload_bytes = offsets_bytes + indices_bytes
        + radius_bytes + compression_bytes + coefficient_bytes;
    if (!finish_setup_detail(
            parallel.phase_timing.evaluation_setup_capacity_ns,
            parallel.phase_timing.evaluation_setup_capacity_calls)) {
        result.failure = parallel.failure;
        return result;
    }
    result.evaluation.gradient.resize(total);
    result.evaluation.density.resize(fluid_count);
    result.tape.radius.resize(pair_count);
    result.tape.compression.resize(fluid_count);
    result.tape.hvp_gradient.resize(pair_count);
    result.tape.hvp_second.resize(pair_count);
    std::vector<double> density_contribution(pair_count);
    B4EP10SIRDIREACallAudit buffer_audit;
    B4EP10SIRDIREAEphemeralGuard ephemeral_guard{
        parallel.evaluation_buffer_audit};
    const std::array<std::size_t, JOINT_EVALUATION_BUFFER_ROLE_COUNT>
        buffer_slots{
            total, fluid_count, pair_count, fluid_count,
            pair_count, pair_count, pair_count,
        };
    if (!buffer_audit.begin(
            parallel.evaluation_buffer_audit, buffer_slots)
        || !b4ep10sirdirea_acquire_ephemeral(
            parallel.evaluation_buffer_audit, pair_count)) {
        parallel.failed = true;
        parallel.failure = "EVALUATION_BUFFER_AUDIT_CAPACITY";
        result.failure = parallel.failure;
        return result;
    }
    ephemeral_guard.acquired = parallel.evaluation_buffer_audit.enabled;
    if (!finish_setup_detail(
            parallel.phase_timing.evaluation_setup_buffer_ns,
            parallel.phase_timing.evaluation_setup_buffer_calls)) {
        result.failure = parallel.failure;
        return result;
    }
    if (!finish_phase(JointParallelPhase::EvaluationSetup)) {
        result.failure = parallel.failure;
        return result;
    }
    const auto fill_pairs = [&](std::size_t begin, std::size_t end, int) {
        for (std::size_t pair_index = begin;
             pair_index < end; ++pair_index) {
            const JointPair pair = neighborhood.pairs[pair_index];
            const double radius = norm(
                neighborhood.fluid[pair.fluid].position
                - joint_position(neighborhood, pair.participant));
            result.tape.radius[pair_index] = radius;
            density_contribution[pair_index] = MASS * weight(radius);
            result.tape.hvp_gradient[pair_index] =
                weight_gradient(radius);
            result.tape.hvp_second[pair_index] = weight_second(radius);
            if (!buffer_audit.record_write(
                    JointEvaluationBufferRole::Radius, pair_index)
                || !buffer_audit.record_write(
                    JointEvaluationBufferRole::DensityContribution,
                    pair_index)
                || !buffer_audit.record_write(
                    JointEvaluationBufferRole::HvpGradient, pair_index)
                || !buffer_audit.record_write(
                    JointEvaluationBufferRole::HvpSecond, pair_index)) {
                return false;
            }
        }
        return true;
    };
    if (!joint_parallel_for(pair_count, parallel, fill_pairs)) {
        result.failure = parallel.failure;
        return result;
    }
    if (!finish_phase(JointParallelPhase::EvaluationPair)) {
        result.failure = parallel.failure;
        return result;
    }
    for (const JointPair pair : neighborhood.pairs) {
        if (pair.participant < fluid_count) {
            ++result.evaluation.fluid_pairs;
        } else {
            ++result.evaluation.boundary_pairs;
        }
    }
    if (!finish_phase(JointParallelPhase::EvaluationMetadata)) {
        result.failure = parallel.failure;
        return result;
    }
    const auto fill_density = [&](std::size_t begin, std::size_t end, int) {
        for (std::size_t center = begin; center < end; ++center) {
            double density = MASS * weight(0.0);
            for (std::size_t slot = neighborhood.flat_offsets[center];
                 slot < neighborhood.flat_offsets[center + 1U]; ++slot) {
                const std::size_t pair_index =
                    neighborhood.flat_directed_pair_indices[slot];
                if (!buffer_audit.written_before_read(
                        JointEvaluationBufferRole::DensityContribution,
                        pair_index)) {
                    return false;
                }
                density += density_contribution[pair_index];
            }
            result.evaluation.density[center] = density;
            if (!buffer_audit.record_write(
                    JointEvaluationBufferRole::Density, center)) {
                return false;
            }
        }
        return true;
    };
    if (!joint_parallel_for(fluid_count, parallel, fill_density)) {
        result.failure = parallel.failure;
        return result;
    }
    if (!finish_phase(JointParallelPhase::EvaluationDensity)) {
        result.failure = parallel.failure;
        return result;
    }
    std::vector<double> center_energy(fluid_count);
    const auto fill_centers = [&](std::size_t begin, std::size_t end, int) {
        for (std::size_t center = begin; center < end; ++center) {
            if (!buffer_audit.written_before_read(
                    JointEvaluationBufferRole::Density, center)) {
                return false;
            }
            const double compression =
                result.evaluation.density[center] / REST_DENSITY - 1.0;
            result.tape.compression[center] = compression;
            if (!buffer_audit.record_write(
                    JointEvaluationBufferRole::Compression, center)) {
                return false;
            }
            if (compression > 0.0) {
                center_energy[center] =
                    0.5 * KAPPA * compression * compression;
            }
        }
        return true;
    };
    if (!joint_parallel_for(fluid_count, parallel, fill_centers)) {
        result.failure = parallel.failure;
        return result;
    }
    if (!finish_phase(JointParallelPhase::EvaluationCenter)) {
        result.failure = parallel.failure;
        return result;
    }
    for (std::size_t center = 0U; center < fluid_count; ++center) {
        const double compression = result.tape.compression[center];
        result.evaluation.minimum_branch_margin = std::min(
            result.evaluation.minimum_branch_margin,
            std::abs(compression));
        if (compression > 0.0) {
            ++result.evaluation.active_centers;
            ++result.tape.active_centers;
            result.tape.active_directed +=
                neighborhood.flat_offsets[center + 1U]
                - neighborhood.flat_offsets[center];
            result.evaluation.energy += center_energy[center];
        }
    }
    const bool masked_reuse =
        parallel.masked_plan_audit.reuse_enabled;
    const bool partitioned_candidate =
        parallel.partitioned_plan_audit.candidate_enabled;
    const bool split_incoming_candidate =
        parallel.incoming_construction_audit.candidate_enabled;
    const int plan_modes = static_cast<int>(masked_reuse)
        + static_cast<int>(partitioned_candidate)
        + static_cast<int>(split_incoming_candidate);
    if (plan_modes > 1) {
        parallel.failed = true;
        parallel.failure = "OWNER_PARALLEL_PLAN_MODE";
        result.failure = parallel.failure;
        return result;
    }
    if (masked_reuse) {
        const JointOwnerGatherPlan* fixed =
            parallel.masked_plan_audit.fixed_plan;
        if (fixed == nullptr || !fixed->passed
            || fixed->target_offsets.size() != total + 1U
            || neighborhood.superset_slot_to_current_slot.size()
                != fixed->source_by_slot.size()) {
            ++parallel.masked_plan_audit.reuse_failures;
            parallel.failed = true;
            parallel.failure = "MASKED_SUPERSET_PLAN_SOURCE";
            result.failure = parallel.failure;
            return result;
        }
        result.tape.masked_superset_gather_plan = fixed;
    } else if (partitioned_candidate) {
        JointPartitionedActivePlanAuditTrace& candidate =
            parallel.partitioned_plan_audit;
        const std::size_t regions_before = parallel.regions;
        const std::size_t partitions_before = parallel.logical_partitions;
        B4EP10PCDPlanBuild built =
            b4ep10pcd_build_partitioned_active_plan(
                neighborhood, result.tape.compression, parallel);
        if (!built.plan.passed) {
            parallel.failed = true;
            parallel.failure = "PARTITIONED_ACTIVE_PLAN:"
                + built.plan.failure;
            result.failure = parallel.failure;
            return result;
        }
        if (parallel.regions < regions_before
            || parallel.logical_partitions < partitions_before) {
            ++candidate.coverage_mismatches;
            parallel.failed = true;
            parallel.failure = "PARTITIONED_ACTIVE_PLAN_EXECUTOR";
            result.failure = parallel.failure;
            return result;
        }
        ++candidate.candidate_builds;
        candidate.directed_slots += built.directed_slots;
        candidate.active_directed_slots += built.active_directed_slots;
        candidate.target_entries += built.target_entries;
        candidate.added_regions += parallel.regions - regions_before;
        candidate.added_logical_partitions +=
            parallel.logical_partitions - partitions_before;
        candidate.maximum_matrix_payload_bytes = std::max(
            candidate.maximum_matrix_payload_bytes,
            built.matrix_payload_bytes);
        candidate.maximum_candidate_plan_payload_bytes = std::max(
            candidate.maximum_candidate_plan_payload_bytes,
            built.plan.payload_bytes);
        if (built.plan.payload_bytes
                > std::numeric_limits<std::size_t>::max()
                    - built.matrix_payload_bytes) {
            ++candidate.coverage_mismatches;
            parallel.failed = true;
            parallel.failure = "PARTITIONED_ACTIVE_PLAN_PAYLOAD";
            result.failure = parallel.failure;
            return result;
        }
        candidate.maximum_combined_payload_bytes = std::max(
            candidate.maximum_combined_payload_bytes,
            built.plan.payload_bytes + built.matrix_payload_bytes);
        result.tape.owner_gather_plan = std::move(built.plan);
    } else if (split_incoming_candidate) {
        JointIncomingConstructionAuditTrace& candidate =
            parallel.incoming_construction_audit;
        if (!neighborhood.incoming_plan
            || neighborhood.incoming_source_by_slot.size() != directed
            || neighborhood.incoming_target_offsets.size() != total + 1U
            || neighborhood.incoming_target_offsets.empty()
            || neighborhood.incoming_target_offsets.front() != 0U
            || neighborhood.incoming_target_offsets.back()
                != neighborhood.incoming_target_slots.size()
            || neighborhood.incoming_target_slots.size() != directed) {
            ++candidate.candidate_failures;
            parallel.failed = true;
            parallel.failure = "SPLIT_INCOMING_PLAN_SOURCE";
            result.failure = parallel.failure;
            return result;
        }
        JointOwnerGatherPlan& incoming =
            result.tape.current_topology_gather_plan;
        incoming.source_by_slot = std::move(
            neighborhood.incoming_source_by_slot);
        incoming.target_offsets = std::move(
            neighborhood.incoming_target_offsets);
        incoming.target_slots = std::move(
            neighborhood.incoming_target_slots);
        incoming.payload_bytes = neighborhood.incoming_plan_payload_bytes;
        incoming.passed = true;
        neighborhood.incoming_plan = false;
        neighborhood.incoming_plan_payload_bytes = 0U;
    } else {
        JointOwnerDataflowTrace plan_trace;
        result.tape.owner_gather_plan = build_joint_owner_gather_plan(
            neighborhood, result.tape.compression, plan_trace);
        if (!result.tape.owner_gather_plan.passed) {
            parallel.failed = true;
            parallel.failure = "OWNER_PARALLEL_PLAN:"
                + result.tape.owner_gather_plan.failure;
            result.failure = parallel.failure;
            return result;
        }
        if (parallel.masked_plan_audit.enabled
            && !b4ep10pd_audit_masked_plan(
                neighborhood, result.tape.compression,
                result.tape.owner_gather_plan, parallel)) {
            parallel.failed = true;
            parallel.failure = "MASKED_SUPERSET_PLAN_AUDIT";
            result.failure = parallel.failure;
            return result;
        }
        if (parallel.partitioned_plan_audit.enabled
            && !b4ep10pcd_audit_partitioned_active_plan(
                neighborhood, result.tape.compression,
                result.tape.owner_gather_plan, parallel)) {
            parallel.failed = true;
            parallel.failure = "PARTITIONED_ACTIVE_PLAN_AUDIT";
            result.failure = parallel.failure;
            return result;
        }
        if (parallel.current_topology_plan_audit.enabled
            && !b4ep10ctd_audit_current_topology_plan(
                neighborhood, result.tape.compression,
                result.tape.owner_gather_plan,
                result.tape.current_topology_gather_plan,
                parallel)) {
            parallel.failed = true;
            parallel.failure = "CURRENT_TOPOLOGY_PLAN_AUDIT";
            result.failure = parallel.failure;
            return result;
        }
        if (parallel.split_incoming_plan_audit.enabled
            && !b4ep10sid_audit_split_incoming_plan(
                neighborhood, result.tape.compression,
                result.tape.owner_gather_plan,
                result.tape.current_topology_gather_plan,
                parallel)) {
            parallel.failed = true;
            parallel.failure = "SPLIT_INCOMING_PLAN_AUDIT";
            result.failure = parallel.failure;
            return result;
        }
        if (parallel.incoming_construction_audit.enabled
            && !b4ep10sicd_audit_incoming_construction(
                neighborhood, parallel)) {
            parallel.failed = true;
            parallel.failure = "INCOMING_CONSTRUCTION_AUDIT";
            result.failure = parallel.failure;
            return result;
        }
    }
    if (!finish_phase(JointParallelPhase::EvaluationPlan)) {
        result.failure = parallel.failure;
        return result;
    }
    B4EP10SIRDALiveness directed_scratch_liveness;
    if (parallel.directed_scratch_audit.enabled) {
        JointDirectedScratchAuditTrace& audit =
            parallel.directed_scratch_audit;
        if (!split_incoming_candidate) {
            ++audit.failures;
            parallel.failed = true;
            parallel.failure = "DIRECTED_SCRATCH_PLAN_MODE";
            result.failure = parallel.failure;
            return result;
        }
        if (!audit.missing_write_negative_rejected) {
            const B4EP10SIRDALiveness negative =
                b4ep10sirda_audit_liveness(
                    neighborhood, result.tape,
                    B4EP10SIRDAInjection::MissingWrite);
            audit.missing_write_negative_rejected = !negative.passed
                && negative.failure
                    == "DIRECTED_SCRATCH_READ_BEFORE_WRITE";
        }
        if (!audit.duplicate_read_negative_rejected) {
            const B4EP10SIRDALiveness negative =
                b4ep10sirda_audit_liveness(
                    neighborhood, result.tape,
                    B4EP10SIRDAInjection::DuplicateRead);
            audit.duplicate_read_negative_rejected = !negative.passed
                && negative.failure == "DIRECTED_SCRATCH_READ_COVERAGE";
        }
        directed_scratch_liveness = b4ep10sirda_audit_liveness(
            neighborhood, result.tape);
        if (!audit.missing_write_negative_rejected
            || !audit.duplicate_read_negative_rejected
            || !directed_scratch_liveness.passed) {
            ++audit.failures;
            parallel.failed = true;
            parallel.failure = "DIRECTED_SCRATCH_LIVENESS:"
                + directed_scratch_liveness.failure;
            result.failure = parallel.failure;
            return result;
        }
        ++audit.plan_audits;
        audit.maximum_audit_payload_bytes = std::max(
            audit.maximum_audit_payload_bytes,
            directed_scratch_liveness.payload_bytes);
        result.tape.directed_scratch_liveness_validated = true;
    }
    std::vector<Vec3> owned_directed_value;
    std::vector<Vec3>* directed_value_pointer = nullptr;
    if (parallel.directed_scratch_reuse.enabled) {
        if (!split_incoming_candidate
            || parallel.directed_scratch_audit.enabled) {
            ++parallel.directed_scratch_reuse.failures;
            parallel.failed = true;
            parallel.failure = "DIRECTED_SCRATCH_REUSE_MODE";
            result.failure = parallel.failure;
            return result;
        }
        directed_value_pointer = b4ep10sirdi_acquire_directed_scratch(
            parallel.directed_scratch_reuse, directed,
            result.tape.active_directed, false);
        if (directed_value_pointer == nullptr) {
            parallel.failed = true;
            parallel.failure = "DIRECTED_SCRATCH_REUSE_CAPACITY";
            result.failure = parallel.failure;
            return result;
        }
    } else {
        owned_directed_value.resize(directed);
        directed_value_pointer = &owned_directed_value;
    }
    std::vector<Vec3>& directed_value = *directed_value_pointer;
    const auto fill_directed = [&](std::size_t begin,
                                   std::size_t end, int) {
        for (std::size_t center = begin; center < end; ++center) {
            const double compression = result.tape.compression[center];
            if (compression <= 0.0) {
                continue;
            }
            const double scale = KAPPA * compression
                * MASS / REST_DENSITY;
            for (std::size_t slot = neighborhood.flat_offsets[center];
                 slot < neighborhood.flat_offsets[center + 1U]; ++slot) {
                const std::size_t pair_index =
                    neighborhood.flat_directed_pair_indices[slot];
                const JointPair pair = neighborhood.pairs[pair_index];
                const std::size_t participant = joint_pair_participant(
                    neighborhood, pair, center);
                const Vec3 displacement =
                    neighborhood.fluid[center].position
                    - joint_position(neighborhood, participant);
                const double radius = result.tape.radius[pair_index];
                if (radius <= 1.0e-15 || radius > HORIZON) {
                    continue;
                }
                directed_value[slot] = scale
                    * result.tape.hvp_gradient[pair_index]
                    * (displacement / radius);
            }
        }
        return true;
    };
    if (!joint_parallel_for(fluid_count, parallel, fill_directed)) {
        result.failure = parallel.failure;
        return result;
    }
    if (!finish_phase(JointParallelPhase::EvaluationDirected)) {
        result.failure = parallel.failure;
        return result;
    }
    std::size_t target_full_scan = 0U;
    std::size_t target_retained = 0U;
    std::size_t plan_payload_bytes = 0U;
    if (split_incoming_candidate) {
        const JointOwnerGatherPlan& plan =
            result.tape.current_topology_gather_plan;
        std::array<std::size_t, B4EP10_LOGICAL_PARTITIONS> full_counts{};
        std::array<std::size_t, B4EP10_LOGICAL_PARTITIONS>
            incoming_retained_counts{};
        std::array<std::size_t, B4EP10_LOGICAL_PARTITIONS>
            own_retained_counts{};
        const auto fill_split_targets = [&](std::size_t begin,
                                            std::size_t end,
                                            int ordinal) {
            std::size_t full = 0U;
            std::size_t incoming_retained = 0U;
            std::size_t own_retained = 0U;
            for (std::size_t target = begin; target < end; ++target) {
                Vec3 value;
                const std::size_t own_begin = target < fluid_count
                    ? neighborhood.flat_offsets[target] : directed;
                const std::size_t own_end = target < fluid_count
                    ? neighborhood.flat_offsets[target + 1U] : directed;
                std::size_t entry = plan.target_offsets[target];
                const std::size_t entry_end =
                    plan.target_offsets[target + 1U];
                for (; entry < entry_end; ++entry) {
                    const std::size_t slot = plan.target_slots[entry];
                    if (slot >= own_begin) {
                        break;
                    }
                    if (slot >= directed) {
                        return false;
                    }
                    const std::size_t source = plan.source_by_slot[slot];
                    if (source >= fluid_count || source == target) {
                        return false;
                    }
                    ++full;
                    if (result.tape.compression[source] > 0.0) {
                        value += -directed_value[slot];
                        ++incoming_retained;
                    }
                }
                if (target < fluid_count
                    && result.tape.compression[target] > 0.0) {
                    for (std::size_t slot = own_begin;
                         slot < own_end; ++slot) {
                        value += directed_value[slot];
                        ++own_retained;
                    }
                }
                for (; entry < entry_end; ++entry) {
                    const std::size_t slot = plan.target_slots[entry];
                    if (slot < own_end || slot >= directed) {
                        return false;
                    }
                    const std::size_t source = plan.source_by_slot[slot];
                    if (source >= fluid_count || source == target) {
                        return false;
                    }
                    ++full;
                    if (result.tape.compression[source] > 0.0) {
                        value += -directed_value[slot];
                        ++incoming_retained;
                    }
                }
                result.evaluation.gradient[target] = value;
                if (!buffer_audit.record_write(
                        JointEvaluationBufferRole::Gradient, target)) {
                    return false;
                }
            }
            const std::size_t partition =
                static_cast<std::size_t>(ordinal);
            full_counts[partition] = full;
            incoming_retained_counts[partition] = incoming_retained;
            own_retained_counts[partition] = own_retained;
            return true;
        };
        if (!joint_parallel_for(total, parallel, fill_split_targets)) {
            ++parallel.incoming_construction_audit.candidate_failures;
            result.failure = parallel.failure;
            return result;
        }
        std::size_t incoming_retained = 0U;
        std::size_t own_retained = 0U;
        for (std::size_t partition = 0U;
             partition < full_counts.size(); ++partition) {
            if (full_counts[partition]
                    > std::numeric_limits<std::size_t>::max()
                        - target_full_scan
                || incoming_retained_counts[partition]
                    > std::numeric_limits<std::size_t>::max()
                        - incoming_retained
                || own_retained_counts[partition]
                    > std::numeric_limits<std::size_t>::max()
                        - own_retained) {
                ++parallel.incoming_construction_audit.candidate_failures;
                parallel.failed = true;
                parallel.failure = "SPLIT_INCOMING_PLAN_COUNT";
                result.failure = parallel.failure;
                return result;
            }
            target_full_scan += full_counts[partition];
            incoming_retained += incoming_retained_counts[partition];
            own_retained += own_retained_counts[partition];
        }
        if (target_full_scan != directed
            || incoming_retained != result.tape.active_directed
            || own_retained != result.tape.active_directed
            || incoming_retained
                > std::numeric_limits<std::size_t>::max() - own_retained) {
            ++parallel.incoming_construction_audit.candidate_failures;
            parallel.failed = true;
            parallel.failure = "SPLIT_INCOMING_PLAN_COVERAGE";
            result.failure = parallel.failure;
            return result;
        }
        target_retained = incoming_retained + own_retained;
        JointIncomingConstructionAuditTrace& candidate =
            parallel.incoming_construction_audit;
        if (target_full_scan
                > std::numeric_limits<std::size_t>::max()
                    - candidate.candidate_incoming_full_entries
            || incoming_retained
                > std::numeric_limits<std::size_t>::max()
                    - candidate.candidate_incoming_retained_entries
            || own_retained
                > std::numeric_limits<std::size_t>::max()
                    - candidate.candidate_own_retained_entries) {
            ++candidate.candidate_failures;
            parallel.failed = true;
            parallel.failure = "SPLIT_INCOMING_PLAN_COUNT";
            result.failure = parallel.failure;
            return result;
        }
        ++candidate.candidate_evaluation_calls;
        candidate.candidate_incoming_full_entries += target_full_scan;
        candidate.candidate_incoming_retained_entries += incoming_retained;
        candidate.candidate_own_retained_entries += own_retained;
        plan_payload_bytes = plan.payload_bytes;
    } else if (masked_reuse) {
        constexpr std::uint32_t missing =
            std::numeric_limits<std::uint32_t>::max();
        const JointOwnerGatherPlan& fixed =
            *result.tape.masked_superset_gather_plan;
        std::array<std::size_t, B4EP10_LOGICAL_PARTITIONS> full_counts{};
        std::array<std::size_t, B4EP10_LOGICAL_PARTITIONS> retained_counts{};
        const auto fill_masked_targets = [&](std::size_t begin,
                                             std::size_t end,
                                             int ordinal) {
            std::size_t full = 0U;
            std::size_t retained = 0U;
            for (std::size_t target = begin; target < end; ++target) {
                Vec3 value;
                for (std::size_t entry = fixed.target_offsets[target];
                     entry < fixed.target_offsets[target + 1U]; ++entry) {
                    ++full;
                    const std::size_t fixed_slot =
                        fixed.target_slots[entry];
                    if (fixed_slot >= fixed.source_by_slot.size()) {
                        return false;
                    }
                    const std::uint32_t mapped =
                        neighborhood.superset_slot_to_current_slot[
                            fixed_slot];
                    if (mapped == missing) {
                        continue;
                    }
                    const std::size_t current_slot = mapped;
                    const std::size_t source =
                        fixed.source_by_slot[fixed_slot];
                    if (current_slot >= directed || source >= fluid_count) {
                        return false;
                    }
                    if (result.tape.compression[source] <= 0.0) {
                        continue;
                    }
                    const std::size_t pair_index =
                        neighborhood.flat_directed_pair_indices[
                            current_slot];
                    if (pair_index >= neighborhood.pairs.size()) {
                        return false;
                    }
                    const std::size_t participant = joint_pair_participant(
                        neighborhood, neighborhood.pairs[pair_index],
                        source);
                    if (target != source && target != participant) {
                        return false;
                    }
                    const Vec3 contribution = directed_value[current_slot];
                    value += target == source
                        ? contribution : -contribution;
                    ++retained;
                }
                result.evaluation.gradient[target] = value;
            }
            full_counts[static_cast<std::size_t>(ordinal)] = full;
            retained_counts[static_cast<std::size_t>(ordinal)] = retained;
            return true;
        };
        if (!joint_parallel_for(total, parallel, fill_masked_targets)) {
            ++parallel.masked_plan_audit.reuse_failures;
            result.failure = parallel.failure;
            return result;
        }
        for (std::size_t partition = 0U;
             partition < full_counts.size(); ++partition) {
            if (full_counts[partition]
                    > std::numeric_limits<std::size_t>::max()
                        - target_full_scan
                || retained_counts[partition]
                    > std::numeric_limits<std::size_t>::max()
                        - target_retained) {
                ++parallel.masked_plan_audit.reuse_failures;
                parallel.failed = true;
                parallel.failure = "MASKED_SUPERSET_PLAN_COUNT";
                result.failure = parallel.failure;
                return result;
            }
            target_full_scan += full_counts[partition];
            target_retained += retained_counts[partition];
        }
        if (target_full_scan != fixed.target_slots.size()
            || result.tape.active_directed
                > std::numeric_limits<std::size_t>::max() / 2U
            || target_retained != 2U * result.tape.active_directed) {
            ++parallel.masked_plan_audit.reuse_failures;
            parallel.failed = true;
            parallel.failure = "MASKED_SUPERSET_PLAN_COVERAGE";
            result.failure = parallel.failure;
            return result;
        }
        result.tape.masked_superset_plan_validated = true;
        JointMaskedSupersetPlanAuditTrace& reuse =
            parallel.masked_plan_audit;
        if (target_full_scan
                > std::numeric_limits<std::size_t>::max()
                    - reuse.evaluation_full_entries_scanned
            || target_retained
                > std::numeric_limits<std::size_t>::max()
                    - reuse.evaluation_retained_entries) {
            ++reuse.reuse_failures;
            parallel.failed = true;
            parallel.failure = "MASKED_SUPERSET_PLAN_COUNT";
            result.failure = parallel.failure;
            return result;
        }
        ++reuse.evaluation_reuse_calls;
        reuse.evaluation_full_entries_scanned += target_full_scan;
        reuse.evaluation_retained_entries += target_retained;
        plan_payload_bytes = fixed.payload_bytes;
    } else {
        const JointOwnerGatherPlan& plan = result.tape.owner_gather_plan;
        const auto fill_targets = [&](std::size_t begin,
                                      std::size_t end, int) {
            for (std::size_t target = begin; target < end; ++target) {
                Vec3 value;
                for (std::size_t entry = plan.target_offsets[target];
                     entry < plan.target_offsets[target + 1U]; ++entry) {
                    const std::size_t slot = plan.target_slots[entry];
                    const std::size_t source = plan.source_by_slot[slot];
                    value += target == source
                        ? directed_value[slot] : -directed_value[slot];
                }
                result.evaluation.gradient[target] = value;
            }
            return true;
        };
        if (!joint_parallel_for(total, parallel, fill_targets)) {
            result.failure = parallel.failure;
            return result;
        }
        target_retained = result.tape.owner_gather_plan.target_slots.size();
        plan_payload_bytes = result.tape.owner_gather_plan.payload_bytes;
    }
    if (!finish_phase(JointParallelPhase::EvaluationTarget)) {
        result.failure = parallel.failure;
        return result;
    }
    if (!buffer_audit.finish(directed, fluid_count)) {
        parallel.failed = true;
        parallel.failure = "EVALUATION_BUFFER_AUDIT_COVERAGE";
        result.failure = parallel.failure;
        return result;
    }
    if (parallel.directed_scratch_audit.enabled) {
        JointDirectedScratchAuditTrace& audit =
            parallel.directed_scratch_audit;
        if (!result.tape.directed_scratch_liveness_validated
            || directed_scratch_liveness.directed_slots != directed
            || directed_scratch_liveness.active_write_slots
                != result.tape.active_directed
            || directed_scratch_liveness.target_read_slots
                != 2U * result.tape.active_directed
            || !b4ep10sirda_record_call(
                audit, directed, result.tape.active_directed, false)) {
            ++audit.failures;
            parallel.failed = true;
            parallel.failure = "DIRECTED_SCRATCH_EVALUATION_ACCOUNTING";
            result.failure = parallel.failure;
            return result;
        }
    }
    const std::size_t scratch_payload_bytes =
        density_contribution.size() * sizeof(double)
        + center_energy.size() * sizeof(double)
        + directed * sizeof(Vec3);
    ++parallel.evaluation_calls;
    parallel.evaluation_density_gathers += directed;
    parallel.evaluation_directed_values += result.tape.active_directed;
    parallel.evaluation_target_gathers +=
        2U * result.tape.active_directed;
    if (!masked_reuse) {
        ++parallel.plan_builds;
    }
    const std::size_t mapping_payload_bytes = masked_reuse
        ? neighborhood.superset_slot_to_current_slot.size()
            * sizeof(std::uint32_t)
        : 0U;
    if (plan_payload_bytes > std::numeric_limits<std::size_t>::max()
            - mapping_payload_bytes
        || plan_payload_bytes + mapping_payload_bytes
            > std::numeric_limits<std::size_t>::max()
                - scratch_payload_bytes) {
        if (masked_reuse) {
            ++parallel.masked_plan_audit.reuse_failures;
        }
        parallel.failed = true;
        parallel.failure = "OWNER_PARALLEL_EVALUATION_PAYLOAD";
        result.failure = parallel.failure;
        return result;
    }
    parallel.maximum_added_payload_bytes = std::max(
        parallel.maximum_added_payload_bytes,
        plan_payload_bytes + mapping_payload_bytes
            + scratch_payload_bytes);
    result.tape.offsets = std::move(neighborhood.flat_offsets);
    result.tape.directed_pair_indices = std::move(
        neighborhood.flat_directed_pair_indices);
    if (adjacency_work != nullptr) {
        ++adjacency_work->csr_ownership_transfers;
    }
    result.tape.passed = true;
    result.passed = true;
    if (!finish_phase(JointParallelPhase::EvaluationFinalize)) {
        result.tape.passed = false;
        result.passed = false;
        result.failure = parallel.failure;
    }
    return result;
}

JointEvaluationTape build_joint_evaluation_tape_from_flat(
    JointNeighborhood& neighborhood,
    FlatAdjacencyWorkTrace* adjacency_work = nullptr,
    JointPhaseTimingTrace* phase_timing = nullptr,
    JointOwnerDataflowTrace* owner_dataflow = nullptr) {
    JointEvaluationTape result;
    const JointPhaseClock::time_point setup_start = phase_timing != nullptr
        ? JointPhaseClock::now() : JointPhaseClock::time_point{};
    const std::size_t fluid_count = neighborhood.fluid.size();
    const std::size_t total = fluid_count + neighborhood.support.size();
    if (!neighborhood.passed || !neighborhood.flat_adjacency
        || !neighborhood.adjacency.empty()) {
        result.failure = "FUSED_EVALUATION_TAPE_SOURCE";
        return result;
    }
    if (neighborhood.pairs.size()
            > std::numeric_limits<std::uint32_t>::max()
        || fluid_count >= std::numeric_limits<std::uint32_t>::max()) {
        result.failure = "FUSED_EVALUATION_TAPE_OFFSET_CAPACITY";
        return result;
    }
    for (const JointPair pair : neighborhood.pairs) {
        if (pair.fluid >= fluid_count || pair.participant >= total
            || (pair.participant < fluid_count
                && pair.fluid >= pair.participant)) {
            result.failure = "FUSED_EVALUATION_TAPE_PAIR_INDEX";
            return result;
        }
    }
    if (neighborhood.flat_offsets.size() != fluid_count + 1U
        || neighborhood.flat_offsets.empty()
        || neighborhood.flat_offsets.front() != 0U
        || neighborhood.flat_offsets.back()
            != neighborhood.flat_directed_pair_indices.size()) {
        result.failure = "FUSED_EVALUATION_TAPE_ADJACENCY";
        return result;
    }
    const std::size_t directed =
        neighborhood.flat_directed_pair_indices.size();
    if (directed > std::numeric_limits<std::uint32_t>::max()) {
        result.failure = "FUSED_EVALUATION_TAPE_OFFSET_CAPACITY";
        return result;
    }
    for (std::size_t center = 0U; center < fluid_count; ++center) {
        const std::size_t begin = neighborhood.flat_offsets[center];
        const std::size_t end = neighborhood.flat_offsets[center + 1U];
        if (end < begin || end > directed) {
            result.failure = "FUSED_EVALUATION_TAPE_ADJACENCY";
            return result;
        }
        std::size_t previous = 0U;
        bool have_previous = false;
        for (std::size_t slot = begin; slot < end; ++slot) {
            const std::uint32_t pair_index =
                neighborhood.flat_directed_pair_indices[slot];
            if (pair_index >= neighborhood.pairs.size()) {
                result.failure = "FUSED_EVALUATION_TAPE_ADJACENCY";
                return result;
            }
            const std::size_t participant = joint_pair_participant(
                neighborhood, neighborhood.pairs[pair_index], center);
            if (participant >= total || participant == center
                || (have_previous && participant <= previous)) {
                result.failure = "FUSED_EVALUATION_TAPE_ADJACENCY";
                return result;
            }
            previous = participant;
            have_previous = true;
        }
    }

    const std::size_t pair_count = neighborhood.pairs.size();
    const std::size_t offsets_bytes = (fluid_count + 1U)
        * sizeof(std::uint32_t);
    const std::size_t indices_bytes = directed * sizeof(std::uint32_t);
    const std::size_t radius_bytes = pair_count * sizeof(double);
    const std::size_t compression_bytes = fluid_count * sizeof(double);
    const std::size_t coefficient_bytes = 2U * radius_bytes;
    if (offsets_bytes > std::numeric_limits<std::size_t>::max()
            - indices_bytes
        || offsets_bytes + indices_bytes
            > std::numeric_limits<std::size_t>::max() - radius_bytes
        || offsets_bytes + indices_bytes + radius_bytes
            > std::numeric_limits<std::size_t>::max() - compression_bytes
        || offsets_bytes + indices_bytes + radius_bytes
                + compression_bytes
            > std::numeric_limits<std::size_t>::max()
                - coefficient_bytes) {
        result.failure = "FUSED_EVALUATION_TAPE_CAPACITY";
        return result;
    }
    const std::size_t payload_bytes = offsets_bytes + indices_bytes
        + radius_bytes + compression_bytes + coefficient_bytes;

    result.evaluation.gradient.resize(total);
    result.evaluation.density.assign(fluid_count, MASS * weight(0.0));
    result.tape.radius.resize(pair_count);
    result.tape.compression.resize(fluid_count);
    result.tape.hvp_gradient.resize(pair_count);
    result.tape.hvp_second.resize(pair_count);
    result.tape.payload_bytes = payload_bytes;
    if (phase_timing != nullptr) {
        record_joint_phase_duration(
            *phase_timing, setup_start,
            phase_timing->fused_setup_ns,
            phase_timing->fused_setup_calls);
    }
    const JointPhaseClock::time_point pair_start = phase_timing != nullptr
        ? JointPhaseClock::now() : JointPhaseClock::time_point{};
    for (std::size_t pair_index = 0U;
         pair_index < pair_count; ++pair_index) {
        const JointPair pair = neighborhood.pairs[pair_index];
        const double radius = norm(
            neighborhood.fluid[pair.fluid].position
            - joint_position(neighborhood, pair.participant));
        result.tape.radius[pair_index] = radius;
        const double contribution = MASS * weight(radius);
        result.evaluation.density[pair.fluid] += contribution;
        if (pair.participant < fluid_count) {
            result.evaluation.density[pair.participant] += contribution;
            ++result.evaluation.fluid_pairs;
        } else {
            ++result.evaluation.boundary_pairs;
        }
        result.tape.hvp_gradient[pair_index] = weight_gradient(radius);
        result.tape.hvp_second[pair_index] = weight_second(radius);
    }
    if (phase_timing != nullptr) {
        record_joint_phase_duration(
            *phase_timing, pair_start,
            phase_timing->fused_pair_ns,
            phase_timing->fused_pair_calls);
    }
    const JointPhaseClock::time_point center_start = phase_timing != nullptr
        ? JointPhaseClock::now() : JointPhaseClock::time_point{};
    for (std::size_t center = 0U; center < fluid_count; ++center) {
        const std::size_t begin = neighborhood.flat_offsets[center];
        const std::size_t end = neighborhood.flat_offsets[center + 1U];
        const double compression =
            result.evaluation.density[center] / REST_DENSITY - 1.0;
        result.tape.compression[center] = compression;
        result.evaluation.minimum_branch_margin = std::min(
            result.evaluation.minimum_branch_margin,
            std::abs(compression));
        if (compression <= 0.0) {
            continue;
        }
        ++result.evaluation.active_centers;
        ++result.tape.active_centers;
        result.tape.active_directed += end - begin;
        result.evaluation.energy +=
            0.5 * KAPPA * compression * compression;
        const double scale = KAPPA * compression
            * MASS / REST_DENSITY;
        for (std::size_t slot = begin; slot < end; ++slot) {
            const std::size_t pair_index =
                neighborhood.flat_directed_pair_indices[slot];
            const JointPair pair = neighborhood.pairs[pair_index];
            const std::size_t participant = joint_pair_participant(
                neighborhood, pair, center);
            const Vec3 displacement =
                neighborhood.fluid[center].position
                - joint_position(neighborhood, participant);
            const double radius = result.tape.radius[pair_index];
            if (radius <= 1.0e-15 || radius > HORIZON) {
                continue;
            }
            const Vec3 pair_value = scale
                * result.tape.hvp_gradient[pair_index]
                * (displacement / radius);
            result.evaluation.gradient[center] += pair_value;
            result.evaluation.gradient[participant] += -pair_value;
        }
    }
    if (phase_timing != nullptr) {
        record_joint_phase_duration(
            *phase_timing, center_start,
            phase_timing->fused_center_ns,
            phase_timing->fused_center_calls);
    }
    if (owner_dataflow != nullptr) {
        JointOwnerEvaluation owner = evaluate_joint_owner_gather(
            neighborhood, result.tape, *owner_dataflow);
        ++owner_dataflow->evaluation_audits;
        owner_dataflow->evaluation_density_gathers +=
            owner.density_gathers;
        owner_dataflow->evaluation_directed_values +=
            owner.directed_values;
        owner_dataflow->evaluation_target_gathers +=
            owner.target_gathers;
        owner_dataflow->maximum_owner_payload_bytes = std::max(
            owner_dataflow->maximum_owner_payload_bytes,
            owner.plan.payload_bytes + owner.scratch_payload_bytes);
        if (!owner.passed
            || !exact_evaluation_values(
                owner.evaluation, result.evaluation)) {
            ++owner_dataflow->evaluation_mismatches;
            result.failure = "OWNER_EVALUATION_MISMATCH:"
                + owner.failure;
            return result;
        }
        result.tape.owner_gather_plan = std::move(owner.plan);
    }
    const JointPhaseClock::time_point finalize_start = phase_timing != nullptr
        ? JointPhaseClock::now() : JointPhaseClock::time_point{};
    result.tape.offsets = std::move(neighborhood.flat_offsets);
    result.tape.directed_pair_indices = std::move(
        neighborhood.flat_directed_pair_indices);
    if (adjacency_work != nullptr) {
        ++adjacency_work->csr_ownership_transfers;
    }
    result.tape.passed = true;
    result.passed = true;
    if (phase_timing != nullptr) {
        record_joint_phase_duration(
            *phase_timing, finalize_start,
            phase_timing->fused_finalize_ns,
            phase_timing->fused_finalize_calls);
    }
    return result;
}

std::vector<Vec3> apply_joint_pressure_tape(
    const JointNeighborhood& neighborhood,
    const JointPressureTape& tape,
    const std::vector<Vec3>& direction) {
    const std::size_t fluid_count = neighborhood.fluid.size();
    const std::size_t total = fluid_count + neighborhood.support.size();
    const bool any_cached_coefficient = !tape.hvp_gradient.empty()
        || !tape.hvp_second.empty();
    const bool cached_coefficients =
        tape.hvp_gradient.size() == neighborhood.pairs.size()
        && tape.hvp_second.size() == neighborhood.pairs.size();
    if (!tape.passed || direction.size() != total
        || tape.offsets.size() != fluid_count + 1U
        || tape.radius.size() != neighborhood.pairs.size()
        || tape.compression.size() != fluid_count
        || (any_cached_coefficient && !cached_coefficients)) {
        throw std::invalid_argument("B4C1 pressure tape mismatch");
    }
    std::vector<Vec3> result(total);
    for (std::size_t center = 0; center < fluid_count; ++center) {
        const double compression = tape.compression[center];
        if (compression <= 0.0) {
            continue;
        }
        const std::size_t begin = tape.offsets[center];
        const std::size_t end = tape.offsets[center + 1U];
        double compression_direction = 0.0;
        for (std::size_t slot = begin; slot < end; ++slot) {
            const JointPair pair = neighborhood.pairs[
                tape.directed_pair_indices[slot]];
            const std::size_t participant = joint_pair_participant(
                neighborhood, pair, center);
            const Vec3 displacement = neighborhood.fluid[center].position
                - joint_position(neighborhood, participant);
            const double radius = tape.radius[
                tape.directed_pair_indices[slot]];
            if (radius <= 1.0e-15 || radius > HORIZON) {
                continue;
            }
            const std::size_t pair_index =
                tape.directed_pair_indices[slot];
            const double gradient = cached_coefficients
                ? tape.hvp_gradient[pair_index]
                : weight_gradient(radius);
            const Vec3 jacobian = MASS / REST_DENSITY
                * gradient * (displacement / radius);
            compression_direction += dot(
                jacobian, direction[center] - direction[participant]);
        }
        for (std::size_t slot = begin; slot < end; ++slot) {
            const JointPair pair = neighborhood.pairs[
                tape.directed_pair_indices[slot]];
            const std::size_t participant = joint_pair_participant(
                neighborhood, pair, center);
            const Vec3 displacement = neighborhood.fluid[center].position
                - joint_position(neighborhood, participant);
            const double radius = tape.radius[
                tape.directed_pair_indices[slot]];
            if (radius <= 1.0e-15 || radius > HORIZON) {
                continue;
            }
            const std::size_t pair_index =
                tape.directed_pair_indices[slot];
            const double jacobian_gradient = cached_coefficients
                ? tape.hvp_gradient[pair_index]
                : weight_gradient(radius);
            const double second = cached_coefficients
                ? tape.hvp_second[pair_index]
                : weight_second(radius);
            const double tangential_gradient = cached_coefficients
                ? tape.hvp_gradient[pair_index]
                : weight_gradient(radius);
            const Vec3 normal = displacement / radius;
            const Vec3 jacobian = MASS / REST_DENSITY
                * jacobian_gradient * normal;
            const Vec3 relative_direction =
                direction[center] - direction[participant];
            const Vec3 curvature = MASS / REST_DENSITY
                * radial_hessian_product(normal,
                    second,
                    tangential_gradient / radius,
                    relative_direction);
            const Vec3 pair_value = KAPPA
                * (compression_direction * jacobian
                    + compression * curvature);
            result[center] += pair_value;
            result[participant] += -pair_value;
        }
    }
    return result;
}

std::string joint_pressure_tape_hash(const JointPressureTape& tape) {
    std::ostringstream material;
    material << std::hex << "joint-pressure-radius-tape-csr-r0|";
    for (std::uint32_t value : tape.offsets) {
        material << value << ',';
    }
    material << '|';
    for (std::uint32_t value : tape.directed_pair_indices) {
        material << value << ',';
    }
    material << '|';
    for (double value : tape.radius) {
        std::uint64_t bits = 0U;
        std::memcpy(&bits, &value, sizeof(bits));
        material << bits << ',';
    }
    material << '|';
    for (double value : tape.compression) {
        std::uint64_t bits = 0U;
        std::memcpy(&bits, &value, sizeof(bits));
        material << bits << ',';
    }
    return sha256_hex(material.str());
}

bool exact_vec3_values(
    const std::vector<Vec3>& lhs, const std::vector<Vec3>& rhs) {
    if (lhs.size() != rhs.size()) {
        return false;
    }
    for (std::size_t i = 0; i < lhs.size(); ++i) {
        if (lhs[i].x != rhs[i].x
            || lhs[i].y != rhs[i].y
            || lhs[i].z != rhs[i].z) {
            return false;
        }
    }
    return true;
}

bool exact_evaluation_values(
    const Evaluation& lhs, const Evaluation& rhs) {
    return lhs.energy == rhs.energy
        && lhs.density == rhs.density
        && exact_vec3_values(lhs.gradient, rhs.gradient)
        && lhs.active_centers == rhs.active_centers
        && lhs.fluid_pairs == rhs.fluid_pairs
        && lhs.boundary_pairs == rhs.boundary_pairs
        && lhs.minimum_branch_margin == rhs.minimum_branch_margin;
}

struct JointOwnerHvp {
    bool passed = false;
    std::string failure;
    std::vector<Vec3> value;
    std::size_t directed_values = 0U;
    std::size_t target_gathers = 0U;
    std::size_t scratch_payload_bytes = 0U;
};

struct B4EP10SIRDADepthGuard {
    JointDirectedScratchAuditTrace* audit = nullptr;
    bool valid = true;

    explicit B4EP10SIRDADepthGuard(
        JointDirectedScratchAuditTrace* candidate) : audit(candidate) {
        if (audit == nullptr || !audit->enabled) {
            return;
        }
        if (audit->current_depth
                == std::numeric_limits<std::size_t>::max()) {
            ++audit->failures;
            valid = false;
            return;
        }
        ++audit->current_depth;
        audit->maximum_depth = std::max(
            audit->maximum_depth, audit->current_depth);
        if (audit->current_depth != 1U) {
            ++audit->failures;
            valid = false;
        }
    }

    ~B4EP10SIRDADepthGuard() {
        if (audit != nullptr && audit->enabled
            && audit->current_depth > 0U) {
            --audit->current_depth;
        }
    }
};

JointOwnerHvp apply_joint_pressure_tape_owner_gather(
    const JointNeighborhood& neighborhood,
    const JointPressureTape& tape,
    const std::vector<Vec3>& direction,
    JointParallelTrace* parallel = nullptr) {
    JointOwnerHvp owner;
    const std::size_t fluid_count = neighborhood.fluid.size();
    const std::size_t total = fluid_count + neighborhood.support.size();
    const std::size_t directed = tape.directed_pair_indices.size();
    const bool masked_reuse = parallel != nullptr
        && parallel->masked_plan_audit.reuse_enabled;
    const bool split_incoming_candidate = parallel != nullptr
        && parallel->incoming_construction_audit.candidate_enabled;
    JointDirectedScratchAuditTrace* directed_scratch_audit =
        parallel != nullptr && parallel->directed_scratch_audit.enabled
        ? &parallel->directed_scratch_audit : nullptr;
    B4EP10SIRDADepthGuard directed_scratch_depth(
        directed_scratch_audit);
    const JointOwnerGatherPlan* selected_plan = masked_reuse
        ? tape.masked_superset_gather_plan
        : split_incoming_candidate
            ? &tape.current_topology_gather_plan
            : &tape.owner_gather_plan;
    JointParallelTimingStart phase_start =
        parallel != nullptr && parallel->phase_timing.enabled
        ? joint_parallel_timing_start(parallel->phase_timing)
        : JointParallelTimingStart{};
    const auto finish_phase = [&](JointParallelPhase phase) {
        if (parallel == nullptr || !parallel->phase_timing.enabled) {
            return true;
        }
        const bool recorded = record_joint_parallel_phase(
            parallel->phase_timing, phase, phase_start);
        if (phase != JointParallelPhase::HvpFinalize) {
            phase_start = joint_parallel_timing_start(
                parallel->phase_timing);
        }
        if (!recorded) {
            parallel->failed = true;
            parallel->failure = "OWNER_HVP_PHASE_TIMING";
        }
        return recorded;
    };
    if (masked_reuse && split_incoming_candidate) {
        owner.failure = "OWNER_HVP_PLAN_MODE";
        return owner;
    }
    if (!directed_scratch_depth.valid
        || (directed_scratch_audit != nullptr
            && (!split_incoming_candidate
                || !tape.directed_scratch_liveness_validated))) {
        if (directed_scratch_audit != nullptr) {
            ++directed_scratch_audit->failures;
        }
        owner.failure = "DIRECTED_SCRATCH_HVP_SOURCE";
        return owner;
    }
    if (!tape.passed || selected_plan == nullptr
        || !selected_plan->passed || direction.size() != total
        || tape.offsets.size() != fluid_count + 1U
        || selected_plan->target_offsets.size() != total + 1U
        || tape.hvp_gradient.size() != neighborhood.pairs.size()
        || tape.hvp_second.size() != neighborhood.pairs.size()
        || (!masked_reuse && !split_incoming_candidate
            && selected_plan->source_by_slot.size() != directed)
        || (split_incoming_candidate
            && (selected_plan->source_by_slot.size() != directed
                || selected_plan->target_offsets.empty()
                || selected_plan->target_offsets.front() != 0U
                || selected_plan->target_offsets.back()
                    != selected_plan->target_slots.size()
                || selected_plan->target_slots.size() != directed))
        || (masked_reuse
            && (!tape.masked_superset_plan_validated
                || neighborhood.superset_slot_to_current_slot.size()
                    != selected_plan->source_by_slot.size()))) {
        owner.failure = "OWNER_HVP_SOURCE";
        return owner;
    }
    std::vector<double> compression_direction(fluid_count);
    if (!finish_phase(JointParallelPhase::HvpSetup)) {
        owner.failure = parallel->failure;
        return owner;
    }
    const auto fill_compression = [&](std::size_t begin,
                                      std::size_t end, int) {
        for (std::size_t center = begin; center < end; ++center) {
            if (tape.compression[center] <= 0.0) {
                continue;
            }
            for (std::size_t slot = tape.offsets[center];
                 slot < tape.offsets[center + 1U]; ++slot) {
                const std::size_t pair_index =
                    tape.directed_pair_indices[slot];
                const JointPair pair = neighborhood.pairs[pair_index];
                const std::size_t participant = joint_pair_participant(
                    neighborhood, pair, center);
                const Vec3 displacement =
                    neighborhood.fluid[center].position
                    - joint_position(neighborhood, participant);
                const double radius = tape.radius[pair_index];
                if (radius <= 1.0e-15 || radius > HORIZON) {
                    continue;
                }
                const Vec3 jacobian = MASS / REST_DENSITY
                    * tape.hvp_gradient[pair_index]
                    * (displacement / radius);
                compression_direction[center] += dot(
                    jacobian,
                    direction[center] - direction[participant]);
            }
        }
        return true;
    };
    if (parallel != nullptr) {
        if (!joint_parallel_for(fluid_count, *parallel,
                fill_compression)) {
            owner.failure = parallel->failure;
            return owner;
        }
    } else {
        fill_compression(0U, fluid_count, 0);
    }
    if (!finish_phase(JointParallelPhase::HvpCompression)) {
        owner.failure = parallel->failure;
        return owner;
    }
    std::vector<Vec3> owned_directed_value;
    std::vector<Vec3>* directed_value_pointer = nullptr;
    if (parallel != nullptr
        && parallel->directed_scratch_reuse.enabled) {
        if (!split_incoming_candidate
            || parallel->directed_scratch_audit.enabled) {
            ++parallel->directed_scratch_reuse.failures;
            owner.failure = "DIRECTED_SCRATCH_REUSE_MODE";
            return owner;
        }
        directed_value_pointer = b4ep10sirdi_acquire_directed_scratch(
            parallel->directed_scratch_reuse, directed,
            tape.active_directed, true);
        if (directed_value_pointer == nullptr) {
            owner.failure = "DIRECTED_SCRATCH_REUSE_CAPACITY";
            return owner;
        }
    } else {
        owned_directed_value.resize(directed);
        directed_value_pointer = &owned_directed_value;
    }
    std::vector<Vec3>& directed_value = *directed_value_pointer;
    const auto fill_directed = [&](std::size_t begin,
                                   std::size_t end, int) {
        for (std::size_t center = begin; center < end; ++center) {
            const double compression = tape.compression[center];
            if (compression <= 0.0) {
                continue;
            }
            for (std::size_t slot = tape.offsets[center];
                 slot < tape.offsets[center + 1U]; ++slot) {
                const std::size_t pair_index =
                    tape.directed_pair_indices[slot];
                const JointPair pair = neighborhood.pairs[pair_index];
                const std::size_t participant = joint_pair_participant(
                    neighborhood, pair, center);
                const Vec3 displacement =
                    neighborhood.fluid[center].position
                    - joint_position(neighborhood, participant);
                const double radius = tape.radius[pair_index];
                if (radius <= 1.0e-15 || radius > HORIZON) {
                    continue;
                }
                const Vec3 normal = displacement / radius;
                const Vec3 jacobian = MASS / REST_DENSITY
                    * tape.hvp_gradient[pair_index] * normal;
                const Vec3 relative_direction =
                    direction[center] - direction[participant];
                const Vec3 curvature = MASS / REST_DENSITY
                    * radial_hessian_product(
                        normal,
                        tape.hvp_second[pair_index],
                        tape.hvp_gradient[pair_index] / radius,
                        relative_direction);
                directed_value[slot] = KAPPA
                    * (compression_direction[center] * jacobian
                        + compression * curvature);
            }
        }
        return true;
    };
    if (parallel != nullptr) {
        if (!joint_parallel_for(fluid_count, *parallel,
                fill_directed)) {
            owner.failure = parallel->failure;
            return owner;
        }
    } else {
        fill_directed(0U, fluid_count, 0);
    }
    if (!finish_phase(JointParallelPhase::HvpDirected)) {
        owner.failure = parallel->failure;
        return owner;
    }
    owner.value.resize(total);
    const JointOwnerGatherPlan& plan = *selected_plan;
    std::size_t split_incoming_full = 0U;
    std::size_t split_incoming_retained = 0U;
    std::size_t split_own_retained = 0U;
    if (split_incoming_candidate) {
        std::array<std::size_t, B4EP10_LOGICAL_PARTITIONS> full_counts{};
        std::array<std::size_t, B4EP10_LOGICAL_PARTITIONS>
            incoming_retained_counts{};
        std::array<std::size_t, B4EP10_LOGICAL_PARTITIONS>
            own_retained_counts{};
        const auto fill_split_targets = [&](std::size_t begin,
                                            std::size_t end,
                                            int ordinal) {
            std::size_t full = 0U;
            std::size_t incoming_retained = 0U;
            std::size_t own_retained = 0U;
            for (std::size_t target = begin; target < end; ++target) {
                Vec3 value;
                const std::size_t own_begin = target < fluid_count
                    ? tape.offsets[target] : directed;
                const std::size_t own_end = target < fluid_count
                    ? tape.offsets[target + 1U] : directed;
                std::size_t entry = plan.target_offsets[target];
                const std::size_t entry_end =
                    plan.target_offsets[target + 1U];
                for (; entry < entry_end; ++entry) {
                    const std::size_t slot = plan.target_slots[entry];
                    if (slot >= own_begin) {
                        break;
                    }
                    if (slot >= directed) {
                        return false;
                    }
                    const std::size_t source = plan.source_by_slot[slot];
                    if (source >= fluid_count || source == target) {
                        return false;
                    }
                    ++full;
                    if (tape.compression[source] > 0.0) {
                        value += -directed_value[slot];
                        ++incoming_retained;
                    }
                }
                if (target < fluid_count
                    && tape.compression[target] > 0.0) {
                    for (std::size_t slot = own_begin;
                         slot < own_end; ++slot) {
                        value += directed_value[slot];
                        ++own_retained;
                    }
                }
                for (; entry < entry_end; ++entry) {
                    const std::size_t slot = plan.target_slots[entry];
                    if (slot < own_end || slot >= directed) {
                        return false;
                    }
                    const std::size_t source = plan.source_by_slot[slot];
                    if (source >= fluid_count || source == target) {
                        return false;
                    }
                    ++full;
                    if (tape.compression[source] > 0.0) {
                        value += -directed_value[slot];
                        ++incoming_retained;
                    }
                }
                owner.value[target] = value;
            }
            const std::size_t partition =
                static_cast<std::size_t>(ordinal);
            full_counts[partition] = full;
            incoming_retained_counts[partition] = incoming_retained;
            own_retained_counts[partition] = own_retained;
            return true;
        };
        if (!joint_parallel_for(total, *parallel, fill_split_targets)) {
            ++parallel->incoming_construction_audit.candidate_failures;
            owner.failure = parallel->failure;
            return owner;
        }
        for (std::size_t partition = 0U;
             partition < full_counts.size(); ++partition) {
            if (full_counts[partition]
                    > std::numeric_limits<std::size_t>::max()
                        - split_incoming_full
                || incoming_retained_counts[partition]
                    > std::numeric_limits<std::size_t>::max()
                        - split_incoming_retained
                || own_retained_counts[partition]
                    > std::numeric_limits<std::size_t>::max()
                        - split_own_retained) {
                ++parallel->incoming_construction_audit.candidate_failures;
                parallel->failed = true;
                parallel->failure = "SPLIT_INCOMING_PLAN_COUNT";
                owner.failure = parallel->failure;
                return owner;
            }
            split_incoming_full += full_counts[partition];
            split_incoming_retained +=
                incoming_retained_counts[partition];
            split_own_retained += own_retained_counts[partition];
        }
        if (split_incoming_full != directed
            || split_incoming_retained != tape.active_directed
            || split_own_retained != tape.active_directed) {
            ++parallel->incoming_construction_audit.candidate_failures;
            parallel->failed = true;
            parallel->failure = "SPLIT_INCOMING_PLAN_COVERAGE";
            owner.failure = parallel->failure;
            return owner;
        }
    } else if (masked_reuse) {
        constexpr std::uint32_t missing =
            std::numeric_limits<std::uint32_t>::max();
        const auto fill_masked_targets = [&](std::size_t begin,
                                             std::size_t end, int) {
            for (std::size_t target = begin; target < end; ++target) {
                Vec3 value;
                for (std::size_t entry = plan.target_offsets[target];
                     entry < plan.target_offsets[target + 1U]; ++entry) {
                    const std::size_t fixed_slot = plan.target_slots[entry];
                    const std::uint32_t mapped =
                        neighborhood.superset_slot_to_current_slot[
                            fixed_slot];
                    if (mapped == missing) {
                        continue;
                    }
                    const std::size_t source =
                        plan.source_by_slot[fixed_slot];
                    if (tape.compression[source] <= 0.0) {
                        continue;
                    }
                    const Vec3 contribution = directed_value[mapped];
                    value += target == source
                        ? contribution : -contribution;
                }
                owner.value[target] = value;
            }
            return true;
        };
        if (!joint_parallel_for(total, *parallel, fill_masked_targets)) {
            ++parallel->masked_plan_audit.reuse_failures;
            owner.failure = parallel->failure;
            return owner;
        }
    } else {
        const auto fill_targets = [&](std::size_t begin,
                                      std::size_t end, int) {
            for (std::size_t target = begin; target < end; ++target) {
                Vec3 value;
                for (std::size_t entry = plan.target_offsets[target];
                     entry < plan.target_offsets[target + 1U]; ++entry) {
                    const std::size_t slot = plan.target_slots[entry];
                    const std::size_t source = plan.source_by_slot[slot];
                    value += target == source
                        ? directed_value[slot] : -directed_value[slot];
                }
                owner.value[target] = value;
            }
            return true;
        };
        if (parallel != nullptr) {
            if (!joint_parallel_for(total, *parallel, fill_targets)) {
                owner.failure = parallel->failure;
                return owner;
            }
        } else {
            fill_targets(0U, total, 0);
        }
    }
    if (!finish_phase(JointParallelPhase::HvpTarget)) {
        owner.failure = parallel->failure;
        return owner;
    }
    owner.directed_values = tape.active_directed;
    owner.target_gathers = masked_reuse || split_incoming_candidate
        ? 2U * tape.active_directed : plan.target_slots.size();
    owner.scratch_payload_bytes =
        compression_direction.size() * sizeof(double)
        + directed * sizeof(Vec3);
    if (directed_scratch_audit != nullptr
        && !b4ep10sirda_record_call(
            *directed_scratch_audit, directed,
            tape.active_directed, true)) {
        owner.failure = "DIRECTED_SCRATCH_HVP_ACCOUNTING";
        return owner;
    }
    if (parallel != nullptr) {
        if (masked_reuse) {
            JointMaskedSupersetPlanAuditTrace& reuse =
                parallel->masked_plan_audit;
            if (plan.target_slots.size()
                    > std::numeric_limits<std::size_t>::max()
                        - reuse.hvp_full_entries_scanned
                || owner.target_gathers
                    > std::numeric_limits<std::size_t>::max()
                        - reuse.hvp_retained_entries) {
                ++reuse.reuse_failures;
                parallel->failed = true;
                parallel->failure = "MASKED_SUPERSET_PLAN_COUNT";
                owner.failure = parallel->failure;
                return owner;
            }
            ++reuse.hvp_reuse_calls;
            reuse.hvp_full_entries_scanned += plan.target_slots.size();
            reuse.hvp_retained_entries += owner.target_gathers;
        }
        if (split_incoming_candidate) {
            JointIncomingConstructionAuditTrace& candidate =
                parallel->incoming_construction_audit;
            if (split_incoming_full
                    > std::numeric_limits<std::size_t>::max()
                        - candidate.candidate_incoming_full_entries
                || split_incoming_retained
                    > std::numeric_limits<std::size_t>::max()
                        - candidate.candidate_incoming_retained_entries
                || split_own_retained
                    > std::numeric_limits<std::size_t>::max()
                        - candidate.candidate_own_retained_entries) {
                ++candidate.candidate_failures;
                parallel->failed = true;
                parallel->failure = "SPLIT_INCOMING_PLAN_COUNT";
                owner.failure = parallel->failure;
                return owner;
            }
            ++candidate.candidate_hvp_calls;
            candidate.candidate_incoming_full_entries +=
                split_incoming_full;
            candidate.candidate_incoming_retained_entries +=
                split_incoming_retained;
            candidate.candidate_own_retained_entries +=
                split_own_retained;
        }
        if (parallel->current_topology_plan_audit.enabled) {
            JointCurrentTopologyPlanAuditTrace& audit =
                parallel->current_topology_plan_audit;
            const JointOwnerGatherPlan& full =
                tape.current_topology_gather_plan;
            if (!full.passed
                || full.source_by_slot.size() != directed
                || full.target_offsets.size() != total + 1U
                || full.target_offsets.empty()
                || full.target_offsets.back() != full.target_slots.size()
                || full.target_slots.size()
                    > std::numeric_limits<std::size_t>::max()
                        - audit.hvp_full_entries
                || owner.target_gathers
                    > std::numeric_limits<std::size_t>::max()
                        - audit.hvp_retained_entries) {
                ++audit.coverage_mismatches;
                parallel->failed = true;
                parallel->failure = "CURRENT_TOPOLOGY_PLAN_HVP";
                owner.failure = parallel->failure;
                return owner;
            }
            ++audit.hvp_calls;
            audit.hvp_full_entries += full.target_slots.size();
            audit.hvp_retained_entries += owner.target_gathers;
        }
        if (parallel->split_incoming_plan_audit.enabled) {
            JointSplitIncomingPlanAuditTrace& audit =
                parallel->split_incoming_plan_audit;
            const JointOwnerGatherPlan& full =
                tape.current_topology_gather_plan;
            if (!full.passed
                || full.source_by_slot.size() != directed
                || full.target_offsets.size() != total + 1U
                || full.target_slots.size() != 2U * directed
                || directed > std::numeric_limits<std::size_t>::max()
                    - audit.incoming_full_entries
                || tape.active_directed
                    > std::numeric_limits<std::size_t>::max()
                        - audit.incoming_retained_entries
                || tape.active_directed
                    > std::numeric_limits<std::size_t>::max()
                        - audit.own_retained_entries) {
                ++audit.coverage_mismatches;
                parallel->failed = true;
                parallel->failure = "SPLIT_INCOMING_PLAN_HVP";
                owner.failure = parallel->failure;
                return owner;
            }
            ++audit.hvp_calls;
            audit.incoming_full_entries += directed;
            audit.incoming_retained_entries += tape.active_directed;
            audit.own_retained_entries += tape.active_directed;
        }
        ++parallel->hvp_calls;
        parallel->hvp_directed_values += owner.directed_values;
        parallel->hvp_target_gathers += owner.target_gathers;
        const std::size_t mapping_payload_bytes = masked_reuse
            ? neighborhood.superset_slot_to_current_slot.size()
                * sizeof(std::uint32_t)
            : 0U;
        if (plan.payload_bytes > std::numeric_limits<std::size_t>::max()
                - mapping_payload_bytes
            || plan.payload_bytes + mapping_payload_bytes
                > std::numeric_limits<std::size_t>::max()
                    - owner.scratch_payload_bytes) {
            if (masked_reuse) {
                ++parallel->masked_plan_audit.reuse_failures;
            }
            parallel->failed = true;
            parallel->failure = "OWNER_HVP_PAYLOAD";
            owner.failure = parallel->failure;
            return owner;
        }
        parallel->maximum_added_payload_bytes = std::max(
            parallel->maximum_added_payload_bytes,
            plan.payload_bytes + mapping_payload_bytes
                + owner.scratch_payload_bytes);
    }
    owner.passed = true;
    if (!finish_phase(JointParallelPhase::HvpFinalize)) {
        owner.passed = false;
        owner.failure = parallel->failure;
    }
    return owner;
}

void audit_joint_owner_hvp(
    const JointPressureWorkspace& workspace,
    const std::vector<Vec3>& direction,
    const std::vector<Vec3>& oracle,
    JointQueryTrace& trace) {
    if (!trace.owner_dataflow.enabled) {
        return;
    }
    const JointOwnerHvp owner = apply_joint_pressure_tape_owner_gather(
        workspace.neighborhood, workspace.tape, direction);
    ++trace.owner_dataflow.hvp_audits;
    trace.owner_dataflow.hvp_directed_values += owner.directed_values;
    trace.owner_dataflow.hvp_target_gathers += owner.target_gathers;
    trace.owner_dataflow.maximum_owner_payload_bytes = std::max(
        trace.owner_dataflow.maximum_owner_payload_bytes,
        workspace.tape.owner_gather_plan.payload_bytes
            + owner.scratch_payload_bytes);
    if (!owner.passed || !exact_vec3_values(owner.value, oracle)) {
        ++trace.owner_dataflow.hvp_mismatches;
        trace.exact = false;
    }
}

std::vector<JointPoint> tagged_points(const std::vector<Vec3>& position) {
    std::vector<JointPoint> result(position.size());
    for (std::size_t i = 0; i < position.size(); ++i) {
        result[i] = {static_cast<std::uint32_t>(i), position[i]};
    }
    return result;
}

std::vector<JointPoint> permute_joint_points(
    const std::vector<JointPoint>& input, int mode) {
    if (mode == 0 || input.size() < 2U) {
        return input;
    }
    std::vector<JointPoint> result;
    result.reserve(input.size());
    if (mode == 1) {
        result.assign(input.rbegin(), input.rend());
        return result;
    }
    std::size_t multiplier = 2U;
    while (std::gcd(multiplier, input.size()) != 1U) {
        ++multiplier;
    }
    for (std::size_t slot = 0; slot < input.size(); ++slot) {
        result.push_back(input[
            (multiplier * slot + 1U) % input.size()]);
    }
    return result;
}

std::array<std::vector<Vec3>, 4> joint_tape_directions(
    std::size_t fluid_count, std::size_t support_count) {
    const std::size_t total = fluid_count + support_count;
    std::array<std::vector<Vec3>, 4> result;
    result[0] = deterministic_direction(total);
    result[1] = result[0];
    result[2] = result[0];
    for (std::size_t i = 0; i < total; ++i) {
        const Vec3 value = result[0][i];
        result[1][i] = {value.y, value.z, value.x};
        result[2][i] = {-value.x, value.z, -value.y};
    }
    result[3].resize(total);
    const std::vector<Vec3> fluid_only =
        deterministic_direction(fluid_count);
    std::copy(fluid_only.begin(), fluid_only.end(), result[3].begin());
    return result;
}

bool exact_zero_vec3(const std::vector<Vec3>& values) {
    return std::all_of(values.begin(), values.end(), [](Vec3 value) {
        return value.x == 0.0 && value.y == 0.0 && value.z == 0.0;
    });
}

JointTapeCase run_joint_tape_case(
    std::string name,
    const std::vector<JointPoint>& fluid,
    const std::vector<JointPoint>& support) {
    JointTapeCase result;
    result.name = std::move(name);
    const JointNeighborhood value =
        build_joint_neighborhood(fluid, support, true);
    if (!value.passed) {
        result.failure = value.failure;
        return result;
    }
    const Evaluation state = evaluate_joint(value);
    const JointPressureTape tape = build_joint_pressure_tape(value, state);
    if (!tape.passed) {
        result.failure = tape.failure;
        return result;
    }
    result.fluid_samples = value.fluid.size();
    result.support_samples = value.support.size();
    result.pairs = value.pairs.size();
    result.directed = tape.directed_pair_indices.size();
    result.active_centers = tape.active_centers;
    result.active_directed = tape.active_directed;
    result.payload_bytes = tape.payload_bytes;
    result.tape_sha256 = joint_pressure_tape_hash(tape);
    result.csr_exact = tape.offsets.size() == value.fluid.size() + 1U;
    if (result.csr_exact) {
        for (std::size_t center = 0;
             center < value.fluid.size(); ++center) {
            const std::size_t begin = tape.offsets[center];
            const std::size_t end = tape.offsets[center + 1U];
            if (end < begin || end > tape.directed_pair_indices.size()
                || end - begin != value.adjacency[center].size()) {
                result.csr_exact = false;
                break;
            }
            for (std::size_t slot = begin; slot < end; ++slot) {
                const std::uint32_t pair_index =
                    tape.directed_pair_indices[slot];
                if (pair_index >= value.pairs.size()
                    || joint_pair_participant(
                           value, value.pairs[pair_index], center)
                        != value.adjacency[center][slot - begin]) {
                    result.csr_exact = false;
                    break;
                }
            }
        }
    }
    result.radius_exact = tape.radius.size() == value.pairs.size();
    for (std::size_t pair_index = 0;
         result.radius_exact && pair_index < value.pairs.size();
         ++pair_index) {
        const JointPair pair = value.pairs[pair_index];
        result.radius_exact = tape.radius[pair_index] == norm(
            value.fluid[pair.fluid].position
            - joint_position(value, pair.participant));
    }
    result.compression_exact =
        tape.compression.size() == value.fluid.size();
    for (std::size_t center = 0;
         result.compression_exact && center < value.fluid.size(); ++center) {
        result.compression_exact = tape.compression[center]
            == state.density[center] / REST_DENSITY - 1.0;
    }
    const std::array<std::vector<Vec3>, 4> directions =
        joint_tape_directions(value.fluid.size(), value.support.size());
    result.hvp_exact = true;
    result.inactive_zero = tape.active_centers != 0U;
    std::array<std::vector<Vec3>, 4> taped_hvp;
    for (std::size_t direction = 0;
         direction < directions.size(); ++direction) {
        const std::vector<Vec3> untaped = apply_joint_hessian(
            value, directions[direction]);
        taped_hvp[direction] = apply_joint_pressure_tape(
            value, tape, directions[direction]);
        result.hvp_exact = result.hvp_exact
            && exact_vec3_values(untaped, taped_hvp[direction]);
        if (tape.active_centers == 0U) {
            result.inactive_zero = result.inactive_zero
                || exact_zero_vec3(taped_hvp[direction]);
        }
    }
    if (tape.active_centers == 0U) {
        result.inactive_zero = std::all_of(
            taped_hvp.begin(), taped_hvp.end(),
            [](const std::vector<Vec3>& values) {
                return exact_zero_vec3(values);
            });
    }
    const JointNeighborhood repeated_neighborhood =
        build_joint_neighborhood(fluid, support, true);
    const JointPressureTape repeated = repeated_neighborhood.passed
        ? build_joint_pressure_tape(
            repeated_neighborhood, evaluate_joint(repeated_neighborhood))
        : JointPressureTape{};
    result.repeat_exact = repeated.passed
        && joint_pressure_tape_hash(repeated) == result.tape_sha256
        && repeated.offsets == tape.offsets
        && repeated.directed_pair_indices == tape.directed_pair_indices
        && repeated.radius == tape.radius
        && repeated.compression == tape.compression;
    result.permutation_exact = true;
    for (int mode = 1; mode <= 2; ++mode) {
        const JointNeighborhood permuted = build_joint_neighborhood(
            permute_joint_points(fluid, mode),
            permute_joint_points(support, mode), true);
        const JointPressureTape permuted_tape = permuted.passed
            ? build_joint_pressure_tape(permuted, evaluate_joint(permuted))
            : JointPressureTape{};
        if (!permuted_tape.passed
            || joint_pressure_tape_hash(permuted_tape)
                != result.tape_sha256) {
            result.permutation_exact = false;
            continue;
        }
        for (std::size_t direction = 0;
             direction < directions.size(); ++direction) {
            if (!exact_vec3_values(
                    apply_joint_pressure_tape(
                        permuted, permuted_tape, directions[direction]),
                    taped_hvp[direction])) {
                result.permutation_exact = false;
            }
        }
    }
    result.untaped_radial_work = 3U
        * (result.pairs + 3U * result.active_directed);
    result.taped_radial_work = result.pairs;
    result.work_ratio_applicable = result.active_centers != 0U;
    result.work_gate = !result.work_ratio_applicable
        || 2U * result.taped_radial_work < result.untaped_radial_work;
    result.passed = result.csr_exact && result.radius_exact
        && result.compression_exact && result.hvp_exact
        && result.inactive_zero && result.repeat_exact
        && result.permutation_exact && result.work_gate;
    if (!result.passed) {
        result.failure = "PRESSURE_TAPE_GATE";
    }
    return result;
}

JointTapeNegative joint_tape_negative(
    std::string name, std::string expected,
    const JointPressureTape& value) {
    JointTapeNegative result;
    result.name = std::move(name);
    result.expected = std::move(expected);
    result.observed = value.failure;
    result.partial_offsets = value.offsets.size();
    result.partial_indices = value.directed_pair_indices.size();
    result.partial_radii = value.radius.size();
    result.partial_compression = value.compression.size();
    result.passed = !value.passed && result.observed == result.expected
        && result.partial_offsets == 0U && result.partial_indices == 0U
        && result.partial_radii == 0U
        && result.partial_compression == 0U;
    return result;
}

std::array<JointTapeNegative, 3> run_joint_tape_negatives() {
    std::array<JointTapeNegative, 3> result;
    const SmokeFixture fixture = make_b4b_supported_column_fixture();
    const JointNeighborhood value = build_joint_neighborhood(
        tagged_points(fixture.position), tagged_points(fixture.boundary), true);
    if (!value.passed || value.pairs.empty()) {
        return result;
    }
    const Evaluation state = evaluate_joint(value);
    const JointPressureTape valid = build_joint_pressure_tape(value, state);
    if (!valid.passed || valid.directed_pair_indices.empty()
        || valid.payload_bytes == 0U) {
        return result;
    }
    JointNeighborhood corrupt = value;
    corrupt.pairs.front().participant = static_cast<std::uint32_t>(
        corrupt.fluid.size() + corrupt.support.size());
    result[0] = joint_tape_negative(
        "pair-index", "PRESSURE_TAPE_PAIR_INDEX",
        build_joint_pressure_tape(corrupt, state));
    result[1] = joint_tape_negative(
        "offset-capacity", "PRESSURE_TAPE_OFFSET_CAPACITY",
        build_joint_pressure_tape(value, state,
            std::numeric_limits<std::size_t>::max(),
            valid.directed_pair_indices.size() - 1U));
    result[2] = joint_tape_negative(
        "payload-capacity", "PRESSURE_TAPE_CAPACITY",
        build_joint_pressure_tape(
            value, state, valid.payload_bytes - 1U));
    return result;
}

void append_joint_tape_case(
    std::ostringstream& output, const JointTapeCase& value) {
    output << "{\"name\":\"" << value.name
           << "\",\"status\":\"" << (value.passed ? "PASS" : "FAIL")
           << "\",\"failure\":\"" << value.failure
           << "\",\"fluid_samples\":" << value.fluid_samples
           << ",\"support_samples\":" << value.support_samples
           << ",\"pairs\":" << value.pairs
           << ",\"directed_records\":" << value.directed
           << ",\"active_centers\":" << value.active_centers
           << ",\"active_directed_records\":" << value.active_directed
           << ",\"tape_payload_bytes\":" << value.payload_bytes
           << ",\"untaped_radial_work_k3\":"
           << value.untaped_radial_work
           << ",\"taped_radial_work_k3\":" << value.taped_radial_work
           << ",\"tape_sha256\":\"" << value.tape_sha256
           << "\",\"csr_exact\":"
           << (value.csr_exact ? "true" : "false")
           << ",\"radius_exact\":"
           << (value.radius_exact ? "true" : "false")
           << ",\"compression_exact\":"
           << (value.compression_exact ? "true" : "false")
           << ",\"hvp_exact\":"
           << (value.hvp_exact ? "true" : "false")
           << ",\"inactive_zero\":"
           << (value.inactive_zero ? "true" : "false")
           << ",\"repeat_exact\":"
           << (value.repeat_exact ? "true" : "false")
           << ",\"permutation_exact\":"
           << (value.permutation_exact ? "true" : "false")
           << ",\"work_ratio_applicable\":"
           << (value.work_ratio_applicable ? "true" : "false")
           << ",\"work_gate\":"
           << (value.work_gate ? "true" : "false") << '}';
}

void append_joint_tape_negative(
    std::ostringstream& output, const JointTapeNegative& value) {
    output << "{\"name\":\"" << value.name
           << "\",\"status\":\"" << (value.passed ? "PASS" : "FAIL")
           << "\",\"expected\":\"" << value.expected
           << "\",\"observed\":\"" << value.observed
           << "\",\"partial_offsets\":" << value.partial_offsets
           << ",\"partial_indices\":" << value.partial_indices
           << ",\"partial_radii\":" << value.partial_radii
           << ",\"partial_compression\":"
           << value.partial_compression << '}';
}

std::size_t all_joint_candidate_checks(
    std::size_t fluid, std::size_t support) {
    return fluid * (fluid - 1U) / 2U + fluid * support;
}

std::vector<Vec3> joint_fluid_positions(
    const JointNeighborhood& neighborhood) {
    std::vector<Vec3> result;
    result.reserve(neighborhood.fluid.size());
    for (const JointPoint& point : neighborhood.fluid) {
        result.push_back(point.position);
    }
    return result;
}

std::vector<Vec3> joint_support_positions(
    const JointNeighborhood& neighborhood) {
    std::vector<Vec3> result;
    result.reserve(neighborhood.support.size());
    for (const JointPoint& point : neighborhood.support) {
        result.push_back(point.position);
    }
    return result;
}

std::string joint_workspace_hash(
    const JointNeighborhood& neighborhood,
    const JointPressureTape& tape) {
    std::ostringstream material;
    material << std::hex << "joint-pressure-workspace-r0|";
    const auto append_position = [&](Vec3 value) {
        for (double component_value : {value.x, value.y, value.z}) {
            std::uint64_t bits = 0U;
            std::memcpy(&bits, &component_value, sizeof(bits));
            material << bits << ',';
        }
        material << ';';
    };
    for (const JointPoint& point : neighborhood.fluid) {
        material << 'F' << point.id << ':';
        append_position(point.position);
    }
    for (const JointPoint& point : neighborhood.support) {
        material << 'S' << point.id << ':';
        append_position(point.position);
    }
    material << '|' << joint_pair_hash(neighborhood)
             << '|' << joint_pressure_tape_hash(tape);
    return sha256_hex(material.str());
}

JointNeighborhood b4ep3_cached_topology(
    const std::vector<JointPoint>& fluid,
    const JointStaticSupportBinding* binding,
    JointTopologySupersetCache& cache,
    StaticSupportWorkTrace* static_work,
    bool flat_adjacency,
    FlatAdjacencyWorkTrace* adjacency_work,
    JointOwnerDataflowTrace* owner_dataflow = nullptr,
    JointParallelTrace* owner_parallel = nullptr);

JointPressureWorkspace build_joint_query_workspace(
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& boundary,
    std::string kind,
    bool trial,
    JointQueryTrace& trace,
    bool audit = true,
    const JointStaticSupportBinding* static_support = nullptr,
    StaticSupportWorkTrace* static_work = nullptr,
    bool flat_adjacency = false,
    FlatAdjacencyWorkTrace* adjacency_work = nullptr) {
    JointPressureWorkspace result;
    if (trace.owner_parallel.enabled
        && (trace.owner_dataflow.enabled
            || trace.phase_timing.enabled
            || trace.topology_cache == nullptr
            || !trace.cache_hvp_coefficients
            || !trace.fuse_evaluation_tape
            || !flat_adjacency)) {
        result.failure = "OWNER_PARALLEL_POLICY";
        trace.exact = false;
        return result;
    }
    const std::vector<JointPoint> fluid = tagged_points(position);
    const JointPhaseClock::time_point topology_start =
        trace.phase_timing.enabled
        ? JointPhaseClock::now() : JointPhaseClock::time_point{};
    const JointParallelTimingStart parallel_topology_start =
        trace.owner_parallel.phase_timing.enabled
        ? joint_parallel_timing_start(trace.owner_parallel.phase_timing)
        : JointParallelTimingStart{};
    if (trace.topology_cache != nullptr) {
        result.neighborhood = b4ep3_cached_topology(
            fluid, static_support, *trace.topology_cache,
            static_work, flat_adjacency, adjacency_work,
            trace.owner_dataflow.enabled
                ? &trace.owner_dataflow : nullptr,
            trace.owner_parallel.enabled
                ? &trace.owner_parallel : nullptr);
    } else {
        result.neighborhood = static_support == nullptr
            ? build_joint_neighborhood(
                fluid, tagged_points(boundary), true,
                static_work, flat_adjacency, adjacency_work)
            : build_joint_neighborhood_with_static_support(
                fluid, static_support, true, static_work,
                flat_adjacency, adjacency_work);
    }
    if (trace.phase_timing.enabled) {
        record_joint_phase_duration(
            trace.phase_timing, topology_start,
            trace.phase_timing.topology_ns,
            trace.phase_timing.topology_calls);
    }
    if (trace.owner_parallel.phase_timing.enabled
        && !add_joint_parallel_duration(
            trace.owner_parallel.phase_timing, parallel_topology_start,
            trace.owner_parallel.phase_timing.topology_total_ns,
            trace.owner_parallel.phase_timing.topology_calls,
            &trace.owner_parallel.phase_timing.topology_cpu_ns,
            &trace.owner_parallel.phase_timing.topology_cpu_calls)) {
        result.failure = "OWNER_PARALLEL_TOPOLOGY_TIMING";
        trace.exact = false;
        return result;
    }
    ++trace.neighborhood_builds;
    if (!result.neighborhood.passed) {
        result.failure = result.neighborhood.failure;
        trace.exact = false;
        return result;
    }
    if (trace.fuse_evaluation_tape) {
        if (!flat_adjacency || !trace.cache_hvp_coefficients) {
            ++trace.fusion_mismatches;
            result.failure = "FUSED_EVALUATION_TAPE_POLICY";
            trace.exact = false;
            return result;
        }
        const JointParallelTimingStart parallel_evaluation_start =
            trace.owner_parallel.phase_timing.enabled
            ? joint_parallel_timing_start(trace.owner_parallel.phase_timing)
            : JointParallelTimingStart{};
        JointEvaluationTape fused = trace.owner_parallel.enabled
            ? build_joint_evaluation_tape_owner_parallel_from_flat(
                result.neighborhood, adjacency_work,
                trace.owner_parallel)
            : build_joint_evaluation_tape_from_flat(
                result.neighborhood, adjacency_work,
                trace.phase_timing.enabled
                    ? &trace.phase_timing : nullptr,
                trace.owner_dataflow.enabled
                    ? &trace.owner_dataflow : nullptr);
        if (trace.owner_parallel.phase_timing.enabled
            && !add_joint_parallel_duration(
                trace.owner_parallel.phase_timing,
                parallel_evaluation_start,
                trace.owner_parallel.phase_timing.evaluation_total_ns,
                trace.owner_parallel.phase_timing.evaluation_calls,
                &trace.owner_parallel.phase_timing.evaluation_cpu_ns,
                &trace.owner_parallel.phase_timing.evaluation_cpu_calls)) {
            ++trace.fusion_mismatches;
            result.failure = "OWNER_PARALLEL_EVALUATION_TIMING";
            trace.exact = false;
            return result;
        }
        ++trace.joint_evaluation_queries;
        ++trace.tape_builds;
        if (!fused.passed || !fused.tape.passed) {
            ++trace.fusion_mismatches;
            result.failure = fused.failure;
            trace.exact = false;
            return result;
        }
        result.evaluation = std::move(fused.evaluation);
        result.tape = std::move(fused.tape);
        const std::size_t pair_count = result.tape.radius.size();
        const std::size_t center_count = result.tape.compression.size();
        ++trace.fused_workspace_builds;
        trace.fused_pair_visits += pair_count;
        trace.fused_active_directed_visits +=
            result.tape.active_directed;
        trace.fused_center_visits += center_count;
        trace.fused_radius_evaluations += pair_count;
        trace.fused_gradient_evaluations += pair_count;
        trace.fused_second_evaluations += pair_count;
        trace.fused_compression_evaluations += center_count;
        ++trace.coefficient_tape_builds;
        trace.coefficient_pairs += pair_count;
        trace.coefficient_kernel_evaluations += 2U * pair_count;
        trace.maximum_coefficient_payload_bytes = std::max(
            trace.maximum_coefficient_payload_bytes,
            2U * pair_count * sizeof(double));
    } else {
        result.evaluation = evaluate_joint(result.neighborhood);
        ++trace.joint_evaluation_queries;
        result.tape = flat_adjacency
            ? build_joint_pressure_tape_from_flat(
                result.neighborhood, result.evaluation,
                std::numeric_limits<std::size_t>::max(),
                std::numeric_limits<std::uint32_t>::max(), adjacency_work)
            : build_joint_pressure_tape(
                result.neighborhood, result.evaluation,
                std::numeric_limits<std::size_t>::max(),
                std::numeric_limits<std::uint32_t>::max(), adjacency_work);
        ++trace.tape_builds;
        if (!result.tape.passed) {
            result.failure = result.tape.failure;
            trace.exact = false;
            return result;
        }
        if (trace.cache_hvp_coefficients
            && !populate_joint_hvp_coefficients(result.tape, trace)) {
            result.failure = "HVP_COEFFICIENT_TAPE";
            trace.exact = false;
            return result;
        }
    }
    trace.total_fluid_centers += result.neighborhood.fluid.size();
    trace.total_active_directed += result.tape.active_directed;
    if (audit) {
        const Evaluation oracle = evaluate(position, boundary);
        ++trace.audit_all_pair_evaluations;
        trace.exact = trace.exact
            && exact_evaluation_values(oracle, result.evaluation);
    }
    const bool full_state_evidence = trace.workspace_evidence_policy
        == JointWorkspaceEvidencePolicy::FullState;
    if (full_state_evidence) {
        result.state_sha256 = joint_workspace_hash(
            result.neighborhood, result.tape);
        ++trace.workspace_state_hashes;
    } else {
        ++trace.workspace_state_hashes_skipped;
    }
    JointQueryMetric metric;
    metric.kind = std::move(kind);
    metric.state_sha256 = result.state_sha256;
    metric.pairs = result.neighborhood.pairs.size();
    metric.directed = result.tape.directed_pair_indices.size();
    metric.active_centers = result.tape.active_centers;
    metric.cell_distance_tests =
        result.neighborhood.construction_distance_tests;
    metric.all_pair_candidate_checks = all_joint_candidate_checks(
        position.size(), boundary.size());
    metric.tape_payload_bytes = result.tape.payload_bytes;
    trace.work_reduced = trace.work_reduced
        && metric.cell_distance_tests < metric.all_pair_candidate_checks;
    std::ostringstream chain;
    if (full_state_evidence) {
        chain << trace.query_chain_sha256 << '|' << metric.kind
              << '|' << metric.state_sha256 << '|' << metric.pairs
              << ':' << metric.directed << ':' << metric.active_centers
              << ':' << metric.cell_distance_tests
              << ':' << metric.all_pair_candidate_checks
              << ':' << metric.tape_payload_bytes;
    } else {
        chain << "joint-query-work-chain-r0|"
              << trace.query_chain_sha256 << '|' << metric.kind
              << '|' << metric.pairs << ':' << metric.directed
              << ':' << metric.active_centers
              << ':' << metric.cell_distance_tests
              << ':' << metric.all_pair_candidate_checks
              << ':' << metric.tape_payload_bytes;
    }
    trace.query_chain_sha256 = sha256_hex(chain.str());
    trace.total_pairs += metric.pairs;
    trace.total_directed += metric.directed;
    trace.total_cell_distance_tests += metric.cell_distance_tests;
    trace.total_all_pair_candidate_checks +=
        metric.all_pair_candidate_checks;
    trace.maximum_tape_payload_bytes = std::max(
        trace.maximum_tape_payload_bytes, metric.tape_payload_bytes);
    if (trace.record_queries) {
        trace.queries.push_back(std::move(metric));
    }
    if (trial) {
        ++trace.trial_workspace_builds;
    }
    if (trace.owner_parallel.evaluation_buffer_audit.enabled) {
        const std::array<std::size_t,
            JOINT_EVALUATION_RETAINED_BUFFER_COUNT> buffer_slots{
                result.evaluation.gradient.size(),
                result.evaluation.density.size(),
                result.tape.radius.size(),
                result.tape.compression.size(),
                result.tape.hvp_gradient.size(),
                result.tape.hvp_second.size(),
            };
        result.evaluation_buffer_audit_lane =
            b4ep10sirdirea_acquire_workspace(
                trace.owner_parallel.evaluation_buffer_audit,
                buffer_slots);
        if (result.evaluation_buffer_audit_lane
                == JOINT_EVALUATION_NO_LANE) {
            trace.exact = false;
            result.failure = "EVALUATION_BUFFER_AUDIT_ACQUIRE";
            return result;
        }
    }
    ++trace.live_workspaces;
    trace.maximum_live_workspaces = std::max(
        trace.maximum_live_workspaces, trace.live_workspaces);
    result.passed = trace.exact;
    if (!result.passed) {
        result.failure = "JOINT_QUERY_EVALUATION_MISMATCH";
    }
    return result;
}

void release_joint_query_workspace(
    JointPressureWorkspace& workspace,
    JointQueryTrace& trace) {
    if (workspace.passed) {
        if (trace.owner_parallel.evaluation_buffer_audit.enabled
            && !b4ep10sirdirea_release_workspace(
                trace.owner_parallel.evaluation_buffer_audit,
                workspace.evaluation_buffer_audit_lane)) {
            trace.exact = false;
        }
        --trace.live_workspaces;
    }
    workspace = JointPressureWorkspace{};
}

bool transfer_joint_query_workspace(
    JointPressureWorkspace& workspace,
    JointPressureWorkspace& retained,
    WorkspaceRetentionTrace& retention) {
    if (!workspace.passed || retained.passed) {
        return false;
    }
    retained = std::move(workspace);
    workspace = JointPressureWorkspace{};
    ++retention.transfers;
    ++retention.live_retained;
    retention.maximum_live_retained = std::max(
        retention.maximum_live_retained, retention.live_retained);
    return true;
}

void release_retained_joint_query_workspace(
    JointPressureWorkspace& workspace,
    JointQueryTrace& trace,
    WorkspaceRetentionTrace& retention) {
    if (workspace.passed) {
        ++retention.releases;
        --retention.live_retained;
    }
    release_joint_query_workspace(workspace, trace);
}

SmoothEvaluation smooth_evaluate_joint_workspace(
    const JointPressureWorkspace& workspace,
    const std::vector<Vec3>& displacement,
    const std::vector<Vec3>& predicted_displacement,
    double time_step) {
    const std::size_t fluid_count = workspace.neighborhood.fluid.size();
    if (!workspace.passed || displacement.size() != fluid_count
        || predicted_displacement.size() != fluid_count) {
        throw std::invalid_argument("B4C2Q joint smooth state mismatch");
    }
    SmoothEvaluation result;
    result.support = workspace.evaluation;
    result.total = result.support.energy;
    result.gradient = fluid_part(result.support.gradient, fluid_count);
    const double inertia_scale = MASS / (time_step * time_step);
    for (std::size_t i = 0; i < fluid_count; ++i) {
        const Vec3 error = displacement[i] - predicted_displacement[i];
        result.total += 0.5 * inertia_scale * norm_squared(error);
        result.gradient[i] += inertia_scale * error;
    }
    return result;
}

std::vector<Vec3> smooth_hvp_joint_workspace(
    const JointPressureWorkspace& workspace,
    const std::vector<Vec3>& direction,
    double time_step,
    JointQueryTrace& trace,
    bool audit = true) {
    const std::size_t fluid_count = workspace.neighborhood.fluid.size();
    const std::size_t support_count = workspace.neighborhood.support.size();
    if (direction.size() != fluid_count) {
        throw std::invalid_argument("B4C2Q joint HVP direction mismatch");
    }
    std::vector<Vec3> joint_direction(fluid_count + support_count);
    std::copy(direction.begin(), direction.end(), joint_direction.begin());
    const JointPhaseClock::time_point hvp_start = trace.phase_timing.enabled
        ? JointPhaseClock::now() : JointPhaseClock::time_point{};
    const JointParallelTimingStart parallel_hvp_start =
        trace.owner_parallel.phase_timing.enabled
        ? joint_parallel_timing_start(trace.owner_parallel.phase_timing)
        : JointParallelTimingStart{};
    std::vector<Vec3> taped;
    if (trace.owner_parallel.enabled) {
        JointOwnerHvp owner = apply_joint_pressure_tape_owner_gather(
            workspace.neighborhood, workspace.tape,
            joint_direction, &trace.owner_parallel);
        if (!owner.passed) {
            trace.exact = false;
            return std::vector<Vec3>(fluid_count);
        }
        taped = std::move(owner.value);
    } else {
        taped = apply_joint_pressure_tape(
            workspace.neighborhood, workspace.tape, joint_direction);
    }
    if (trace.phase_timing.enabled) {
        record_joint_phase_duration(
            trace.phase_timing, hvp_start,
            trace.phase_timing.hvp_apply_ns,
            trace.phase_timing.hvp_apply_calls);
    }
    if (trace.owner_parallel.phase_timing.enabled
        && !add_joint_parallel_duration(
            trace.owner_parallel.phase_timing, parallel_hvp_start,
            trace.owner_parallel.phase_timing.hvp_total_ns,
            trace.owner_parallel.phase_timing.hvp_calls,
            &trace.owner_parallel.phase_timing.hvp_cpu_ns,
            &trace.owner_parallel.phase_timing.hvp_cpu_calls)) {
        trace.exact = false;
        return std::vector<Vec3>(fluid_count);
    }
    audit_joint_owner_hvp(
        workspace, joint_direction, taped, trace);
    if (trace.cache_hvp_coefficients) {
        trace.coefficient_hvp_lookups +=
            4U * workspace.tape.active_directed;
    }
    ++trace.joint_hvp_queries;
    if (audit) {
        const std::vector<Vec3> oracle = apply_hessian(
            joint_fluid_positions(workspace.neighborhood),
            joint_support_positions(workspace.neighborhood), joint_direction);
        ++trace.audit_all_pair_hvps;
        trace.exact = trace.exact && exact_vec3_values(taped, oracle);
    }
    std::vector<Vec3> result = fluid_part(taped, fluid_count);
    const double inertia_scale = MASS / (time_step * time_step);
    for (std::size_t i = 0; i < result.size(); ++i) {
        result[i] += inertia_scale * direction[i];
    }
    return result;
}

BoxKktState evaluate_box_kkt_joint_workspace(
    const SmokeFixture& fixture,
    const std::vector<Vec3>& start_position,
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& velocity,
    const std::vector<Vec3>& displacement,
    const std::vector<Vec3>& predicted_displacement,
    double time_step,
    const JointPressureWorkspace& workspace) {
    BoxKktState result;
    result.smooth = smooth_evaluate_joint_workspace(
        workspace, displacement, predicted_displacement, time_step);
    result.projected_gradient = result.smooth.gradient;
    result.active_gradient.resize(position.size());
    result.active_axis.resize(position.size());
    for (std::size_t i = 0; i < position.size(); ++i) {
        for (int axis = 0; axis < 3; ++axis) {
            const double low = component(fixture.contact_low, axis)
                - component(start_position[i], axis);
            const double high = component(fixture.contact_high, axis)
                - component(start_position[i], axis);
            const double value = component(displacement[i], axis);
            const double gradient = component(result.smooth.gradient[i], axis);
            const bool lower = value == low && gradient >= 0.0;
            const bool upper = value == high && gradient <= 0.0;
            if (lower || upper) {
                result.active_axis[i][static_cast<std::size_t>(axis)] = true;
                set_component(result.projected_gradient[i], axis, 0.0);
                set_component(result.active_gradient[i], axis, gradient);
                const double multiplier = lower ? gradient : -gradient;
                const std::size_t face = static_cast<std::size_t>(
                    2 * axis + (upper ? 1 : 0));
                ++result.face_counts[face];
                result.face_multiplier_sum[face] += multiplier;
                result.face_fluid_impulse[face] += time_step * gradient;
                result.minimum_multiplier = std::min(
                    result.minimum_multiplier, multiplier);
                result.complementarity = std::max(result.complementarity,
                    multiplier * std::abs(lower ? value - low : high - value));
                result.lower_axes += lower ? 1 : 0;
                result.upper_axes += upper ? 1 : 0;
                result.lower_y_axes += lower && axis == 1 ? 1 : 0;
                result.lateral_or_upper_axes +=
                    upper || (lower && axis != 1) ? 1 : 0;
            }
            result.maximum_penetration = std::max(
                result.maximum_penetration,
                std::max(low - value, value - high));
        }
        const Vec3 v_star = velocity[i] + time_step * fixture.gravity;
        result.actual_impulse += MASS
            * (displacement[i] / time_step - v_star);
    }
    result.maximum_penetration = std::max(
        result.maximum_penetration, 0.0);
    const Vec3 fluid_gradient = sum_values(
        result.smooth.support.gradient, 0U, position.size());
    const Vec3 boundary_gradient = sum_values(
        result.smooth.support.gradient, position.size(),
        result.smooth.support.gradient.size());
    result.fluid_pressure_impulse = -time_step * fluid_gradient;
    result.support_reaction = -time_step * boundary_gradient;
    result.fluid_contact_impulse = time_step
        * sum_values(result.active_gradient, 0U,
            result.active_gradient.size());
    result.contact_reaction = -result.fluid_contact_impulse;
    result.gravity_impulse = static_cast<double>(position.size())
        * MASS * time_step * fixture.gravity;
    result.projected_impulse_residual = time_step
        * vector_norm(result.projected_gradient);
    const double support_scale = norm(result.fluid_pressure_impulse)
        + norm(result.support_reaction);
    result.support_translation_closure = norm(
        result.fluid_pressure_impulse + result.support_reaction)
        / std::max(support_scale, 1.0e-30);
    result.contact_closure = norm(
        result.fluid_contact_impulse + result.contact_reaction);
    const Vec3 stationarity = result.actual_impulse
        - result.fluid_pressure_impulse - result.fluid_contact_impulse;
    const double impulse_scale = std::max({
        norm(result.actual_impulse)
            + norm(result.fluid_pressure_impulse)
            + norm(result.fluid_contact_impulse),
        static_cast<double>(position.size()) * MASS * time_step
            * norm(fixture.gravity),
        1.0e-12,
    });
    result.reaction_limit = 1.0e-9 * impulse_scale
        + displacement_forward_bound(velocity, fixture.gravity, time_step);
    const Vec3 new_momentum = [&]() {
        Vec3 value;
        for (Vec3 delta : displacement) {
            value += MASS * delta / time_step;
        }
        return value;
    }();
    const Vec3 ledger = new_momentum - momentum(velocity)
        - result.gravity_impulse + result.support_reaction
        + result.contact_reaction;
    const double ledger_scale = norm(new_momentum - momentum(velocity))
        + norm(result.gravity_impulse) + norm(result.support_reaction)
        + norm(result.contact_reaction);
    result.ledger_absolute = norm(ledger);
    result.ledger_residual = result.ledger_absolute
        / std::max(ledger_scale, 1.0e-30);
    if (!std::isfinite(result.minimum_multiplier)) {
        result.minimum_multiplier = 0.0;
    }
    result.finite_values = std::isfinite(result.smooth.total)
        && std::isfinite(result.projected_impulse_residual)
        && std::isfinite(result.reaction_limit)
        && std::isfinite(result.minimum_multiplier)
        && finite(result.actual_impulse)
        && finite(stationarity);
    result.passed = result.finite_values
        && result.maximum_penetration <= 1.0e-12
        && result.minimum_multiplier >= 0.0
        && result.complementarity == 0.0
        && result.projected_impulse_residual <= result.reaction_limit
        && norm(stationarity) <= result.reaction_limit
        && result.support_translation_closure <= 1.0e-10
        && result.contact_closure <= 1.0e-12
        && result.ledger_residual <= 1.0e-9;
    return result;
}

std::vector<Vec3> box_kkt_trust_step_joint_workspace(
    const JointPressureWorkspace& workspace,
    const BoxKktState& state,
    double time_step,
    double radius,
    int& hvp_calls,
    bool& negative_curvature,
    JointQueryTrace& trace,
    bool audit = true) {
    std::vector<Vec3> point(state.projected_gradient.size());
    std::vector<Vec3> residual = state.projected_gradient;
    std::vector<Vec3> direction = residual;
    for (Vec3& value : direction) {
        value = -value;
    }
    double residual_squared = flat_dot(residual, residual);
    const double initial_residual = std::sqrt(residual_squared);
    if (initial_residual == 0.0) {
        return point;
    }
    for (std::size_t iteration = 0;
         iteration < 3U * direction.size(); ++iteration) {
        std::vector<Vec3> image = smooth_hvp_joint_workspace(
            workspace, direction, time_step, trace, audit);
        ++hvp_calls;
        zero_active_components(image, state.active_axis);
        const double curvature = flat_dot(direction, image);
        if (!std::isfinite(curvature) || curvature <= 0.0) {
            negative_curvature = true;
            return add_scaled(point, direction,
                trust_boundary_tau(point, direction, radius));
        }
        const double alpha = residual_squared / curvature;
        const std::vector<Vec3> candidate = add_scaled(
            point, direction, alpha);
        if (vector_norm(candidate) >= radius) {
            return add_scaled(point, direction,
                trust_boundary_tau(point, direction, radius));
        }
        point = candidate;
        std::vector<Vec3> next_residual = residual;
        for (std::size_t i = 0; i < next_residual.size(); ++i) {
            next_residual[i] += alpha * image[i];
        }
        zero_active_components(next_residual, state.active_axis);
        const double next_squared = flat_dot(next_residual, next_residual);
        if (std::sqrt(next_squared)
            <= std::min(0.5, std::sqrt(initial_residual))
                * initial_residual) {
            return point;
        }
        const double beta = next_squared / residual_squared;
        for (std::size_t i = 0; i < direction.size(); ++i) {
            direction[i] = -next_residual[i] + beta * direction[i];
        }
        zero_active_components(direction, state.active_axis);
        residual = std::move(next_residual);
        residual_squared = next_squared;
    }
    return point;
}

BoxKktSolve solve_box_kkt_step_joint_query(
    const SmokeFixture& fixture,
    const std::vector<Vec3>& start_position,
    const std::vector<Vec3>& start_velocity,
    double time_step,
    JointQueryTrace& trace,
    bool audit = true,
    JointPressureWorkspace* retained_workspace = nullptr,
    WorkspaceRetentionTrace* retention = nullptr,
    const JointStaticSupportBinding* static_support = nullptr,
    StaticSupportWorkTrace* static_work = nullptr,
    bool flat_adjacency = false,
    FlatAdjacencyWorkTrace* adjacency_work = nullptr) {
    BoxKktSolve result;
    if ((retained_workspace == nullptr) != (retention == nullptr)
        || (retained_workspace != nullptr && retained_workspace->passed)) {
        result.failure = "RETAINED_WORKSPACE_OWNERSHIP";
        return result;
    }
    std::vector<Vec3> predicted(start_position.size());
    for (std::size_t i = 0; i < predicted.size(); ++i) {
        predicted[i] = time_step
            * (start_velocity[i] + time_step * fixture.gravity);
    }
    result.displacement = clamp_box_displacement(
        fixture, start_position, predicted);
    result.position = materialize_displacement(
        start_position, result.displacement);
    JointPressureWorkspace current = build_joint_query_workspace(
        result.position, fixture.boundary, "CURRENT_0", false, trace, audit,
        static_support, static_work, flat_adjacency, adjacency_work);
    if (!current.passed) {
        result.failure = "CURRENT_WORKSPACE:" + current.failure;
        return result;
    }
    result.state = evaluate_box_kkt_joint_workspace(
        fixture, start_position, result.position, start_velocity,
        result.displacement, predicted, time_step, current);
    result.initial_objective = result.state.smooth.total;
    result.objective_forward_bound = 1024.0
        * std::numeric_limits<double>::epsilon()
        * std::max(std::abs(result.initial_objective), 1.0);
    double trust_radius = 0.25 * SPACING;
    for (int outer = 0; outer < 64; ++outer) {
        result.outer_trials = outer + 1;
        if (result.state.passed) {
            result.velocity.resize(result.displacement.size());
            for (std::size_t i = 0; i < result.velocity.size(); ++i) {
                result.velocity[i] = result.displacement[i] / time_step;
            }
            result.passed = result.state.smooth.total
                <= result.initial_objective + result.objective_forward_bound;
            if (!result.passed) {
                result.failure = "OBJECTIVE_ABOVE_FEASIBLE_PREDICTOR";
            }
            if (result.passed && retained_workspace != nullptr) {
                if (!transfer_joint_query_workspace(
                        current, *retained_workspace, *retention)) {
                    result.passed = false;
                    result.failure = "RETAINED_WORKSPACE_TRANSFER";
                    release_joint_query_workspace(current, trace);
                }
            } else {
                release_joint_query_workspace(current, trace);
            }
            return result;
        }
        bool negative_curvature = false;
        const std::vector<Vec3> raw_step =
            box_kkt_trust_step_joint_workspace(
                current, result.state, time_step, trust_radius,
                result.hvp_calls, negative_curvature, trace, audit);
        result.negative_curvature_exits += negative_curvature ? 1 : 0;
        std::vector<Vec3> trial_displacement = add_scaled(
            result.displacement, raw_step, 1.0);
        trial_displacement = clamp_box_displacement(
            fixture, start_position, trial_displacement);
        ++result.projected_trials;
        std::vector<Vec3> actual_step(trial_displacement.size());
        for (std::size_t i = 0; i < actual_step.size(); ++i) {
            actual_step[i] = trial_displacement[i] - result.displacement[i];
        }
        if (vector_norm(actual_step) == 0.0) {
            result.failure = "ZERO_PROJECTED_STEP";
            release_joint_query_workspace(current, trace);
            return result;
        }
        const std::vector<Vec3> trial_position = materialize_displacement(
            start_position, trial_displacement);
        JointPressureWorkspace trial = build_joint_query_workspace(
            trial_position, fixture.boundary,
            "TRIAL_" + std::to_string(outer), true, trace, audit,
            static_support, static_work, flat_adjacency, adjacency_work);
        if (!trial.passed) {
            result.failure = "TRIAL_WORKSPACE:" + trial.failure;
            release_joint_query_workspace(current, trace);
            return result;
        }
        const BoxKktState trial_state = evaluate_box_kkt_joint_workspace(
            fixture, start_position, trial_position, start_velocity,
            trial_displacement, predicted, time_step, trial);
        const std::vector<Vec3> image = smooth_hvp_joint_workspace(
            current, actual_step, time_step, trace, audit);
        ++result.hvp_calls;
        const double predicted_reduction = -flat_dot(
            result.state.smooth.gradient, actual_step)
            - 0.5 * flat_dot(actual_step, image);
        const double actual_reduction = result.state.smooth.total
            - trial_state.smooth.total;
        const double energy_floor = 1024.0
            * std::numeric_limits<double>::epsilon()
            * std::max(std::abs(result.state.smooth.total), 1.0);
        bool accept = false;
        if (predicted_reduction > energy_floor
            && actual_reduction > 0.0) {
            const double ratio = actual_reduction / predicted_reduction;
            accept = ratio >= 0.1;
            if (ratio < 0.25) {
                trust_radius *= 0.25;
            } else if (ratio > 0.75
                && vector_norm(actual_step) >= 0.9 * trust_radius) {
                trust_radius = std::min(
                    2.0 * trust_radius, 2.0 * SPACING);
            }
        } else if (predicted_reduction > 0.0
            && predicted_reduction <= energy_floor) {
            ++result.floor_merit_trials;
            accept = trial_state.finite_values
                && trial_state.minimum_multiplier >= 0.0
                && trial_state.projected_impulse_residual
                    < result.state.projected_impulse_residual
                && trial_state.ledger_absolute < result.state.ledger_absolute
                && result.floor_merit_accepts < 4;
            if (accept) {
                ++result.floor_merit_accepts;
            }
        }
        if (accept) {
            result.active_set_changes += same_active_set(
                result.state, trial_state) ? 0 : 1;
            result.displacement = std::move(trial_displacement);
            result.position = std::move(trial_position);
            result.state = trial_state;
            release_joint_query_workspace(current, trace);
            current = std::move(trial);
            ++trace.accepted_workspace_promotions;
            ++result.accepted_trials;
        } else {
            ++result.rejected_trials;
            ++trace.rejected_workspace_destructions;
            release_joint_query_workspace(trial, trace);
            trust_radius *= 0.25;
            if (result.rejected_trials > 8) {
                result.failure = "REJECT_LIMIT";
                release_joint_query_workspace(current, trace);
                return result;
            }
        }
        if (trust_radius < 1.0e-14) {
            result.failure = "MINIMUM_TRUST_RADIUS";
            release_joint_query_workspace(current, trace);
            return result;
        }
    }
    result.failure = "OUTER_LIMIT";
    release_joint_query_workspace(current, trace);
    return result;
}

bool exact_box_kkt_state(
    const BoxKktState& lhs, const BoxKktState& rhs) {
    return lhs.smooth.total == rhs.smooth.total
        && exact_evaluation_values(lhs.smooth.support, rhs.smooth.support)
        && exact_vec3_values(lhs.smooth.gradient, rhs.smooth.gradient)
        && exact_vec3_values(lhs.projected_gradient, rhs.projected_gradient)
        && exact_vec3_values(lhs.active_gradient, rhs.active_gradient)
        && lhs.active_axis == rhs.active_axis
        && lhs.lower_axes == rhs.lower_axes
        && lhs.upper_axes == rhs.upper_axes
        && lhs.lower_y_axes == rhs.lower_y_axes
        && lhs.lateral_or_upper_axes == rhs.lateral_or_upper_axes
        && lhs.face_counts == rhs.face_counts
        && lhs.face_multiplier_sum == rhs.face_multiplier_sum
        && lhs.face_fluid_impulse == rhs.face_fluid_impulse
        && lhs.projected_impulse_residual == rhs.projected_impulse_residual
        && lhs.reaction_limit == rhs.reaction_limit
        && lhs.complementarity == rhs.complementarity
        && lhs.minimum_multiplier == rhs.minimum_multiplier
        && lhs.maximum_penetration == rhs.maximum_penetration
        && lhs.support_translation_closure
            == rhs.support_translation_closure
        && lhs.contact_closure == rhs.contact_closure
        && lhs.ledger_absolute == rhs.ledger_absolute
        && lhs.ledger_residual == rhs.ledger_residual
        && lhs.actual_impulse.x == rhs.actual_impulse.x
        && lhs.actual_impulse.y == rhs.actual_impulse.y
        && lhs.actual_impulse.z == rhs.actual_impulse.z
        && lhs.fluid_pressure_impulse.x == rhs.fluid_pressure_impulse.x
        && lhs.fluid_pressure_impulse.y == rhs.fluid_pressure_impulse.y
        && lhs.fluid_pressure_impulse.z == rhs.fluid_pressure_impulse.z
        && lhs.support_reaction.x == rhs.support_reaction.x
        && lhs.support_reaction.y == rhs.support_reaction.y
        && lhs.support_reaction.z == rhs.support_reaction.z
        && lhs.fluid_contact_impulse.x == rhs.fluid_contact_impulse.x
        && lhs.fluid_contact_impulse.y == rhs.fluid_contact_impulse.y
        && lhs.fluid_contact_impulse.z == rhs.fluid_contact_impulse.z
        && lhs.contact_reaction.x == rhs.contact_reaction.x
        && lhs.contact_reaction.y == rhs.contact_reaction.y
        && lhs.contact_reaction.z == rhs.contact_reaction.z
        && lhs.gravity_impulse.x == rhs.gravity_impulse.x
        && lhs.gravity_impulse.y == rhs.gravity_impulse.y
        && lhs.gravity_impulse.z == rhs.gravity_impulse.z
        && lhs.finite_values == rhs.finite_values
        && lhs.passed == rhs.passed;
}

bool exact_box_kkt_solve(
    const BoxKktSolve& lhs, const BoxKktSolve& rhs) {
    return lhs.passed == rhs.passed
        && lhs.failure == rhs.failure
        && exact_vec3_values(lhs.position, rhs.position)
        && exact_vec3_values(lhs.velocity, rhs.velocity)
        && exact_vec3_values(lhs.displacement, rhs.displacement)
        && exact_box_kkt_state(lhs.state, rhs.state)
        && lhs.outer_trials == rhs.outer_trials
        && lhs.accepted_trials == rhs.accepted_trials
        && lhs.rejected_trials == rhs.rejected_trials
        && lhs.hvp_calls == rhs.hvp_calls
        && lhs.negative_curvature_exits == rhs.negative_curvature_exits
        && lhs.projected_trials == rhs.projected_trials
        && lhs.active_set_changes == rhs.active_set_changes
        && lhs.floor_merit_trials == rhs.floor_merit_trials
        && lhs.floor_merit_accepts == rhs.floor_merit_accepts
        && lhs.initial_objective == rhs.initial_objective
        && lhs.objective_forward_bound == rhs.objective_forward_bound;
}

JointQueryCase run_joint_query_case(
    std::string name,
    SmokeFixture fixture,
    const std::vector<Vec3>& start_position,
    const std::vector<Vec3>& start_velocity,
    double time_step) {
    JointQueryCase result;
    result.name = std::move(name);
    result.oracle = solve_box_kkt_step(
        fixture, start_position, start_velocity, time_step);
    result.candidate = solve_box_kkt_step_joint_query(
        fixture, start_position, start_velocity, time_step, result.trace);
    result.solve_exact = exact_box_kkt_solve(
        result.oracle, result.candidate);
    result.active_case = result.trace.joint_hvp_queries > 0;
    result.inactive_case = result.trace.joint_hvp_queries == 0
        && result.candidate.state.smooth.support.active_centers == 0U;
    const bool lifecycle = result.trace.neighborhood_builds
            == result.trace.joint_evaluation_queries
        && result.trace.tape_builds == result.trace.joint_evaluation_queries
        && result.trace.live_workspaces == 0
        && result.trace.maximum_live_workspaces <= 2
        && result.trace.candidate_all_pair_evaluations == 0
        && result.trace.candidate_all_pair_hvps == 0;
    result.passed = result.oracle.passed && result.candidate.passed
        && result.solve_exact && result.trace.exact
        && result.trace.work_reduced && lifecycle;
    if (!result.passed) {
        result.failure = "JOINT_QUERY_SOLVE_GATE";
    }
    return result;
}

std::vector<Vec3> pressure_hvp_joint_workspace(
    const JointPressureWorkspace& workspace,
    const std::vector<Vec3>& direction,
    JointQueryTrace& trace,
    bool audit = true) {
    const std::size_t fluid_count = workspace.neighborhood.fluid.size();
    const std::size_t support_count = workspace.neighborhood.support.size();
    std::vector<Vec3> joint_direction(fluid_count + support_count);
    std::copy(direction.begin(), direction.end(), joint_direction.begin());
    const JointPhaseClock::time_point hvp_start = trace.phase_timing.enabled
        ? JointPhaseClock::now() : JointPhaseClock::time_point{};
    const JointParallelTimingStart parallel_hvp_start =
        trace.owner_parallel.phase_timing.enabled
        ? joint_parallel_timing_start(trace.owner_parallel.phase_timing)
        : JointParallelTimingStart{};
    std::vector<Vec3> taped;
    if (trace.owner_parallel.enabled) {
        JointOwnerHvp owner = apply_joint_pressure_tape_owner_gather(
            workspace.neighborhood, workspace.tape,
            joint_direction, &trace.owner_parallel);
        if (!owner.passed) {
            trace.exact = false;
            return std::vector<Vec3>(fluid_count);
        }
        taped = std::move(owner.value);
    } else {
        taped = apply_joint_pressure_tape(
            workspace.neighborhood, workspace.tape, joint_direction);
    }
    if (trace.phase_timing.enabled) {
        record_joint_phase_duration(
            trace.phase_timing, hvp_start,
            trace.phase_timing.hvp_apply_ns,
            trace.phase_timing.hvp_apply_calls);
    }
    if (trace.owner_parallel.phase_timing.enabled
        && !add_joint_parallel_duration(
            trace.owner_parallel.phase_timing, parallel_hvp_start,
            trace.owner_parallel.phase_timing.hvp_total_ns,
            trace.owner_parallel.phase_timing.hvp_calls,
            &trace.owner_parallel.phase_timing.hvp_cpu_ns,
            &trace.owner_parallel.phase_timing.hvp_cpu_calls)) {
        trace.exact = false;
        return std::vector<Vec3>(fluid_count);
    }
    audit_joint_owner_hvp(
        workspace, joint_direction, taped, trace);
    if (trace.cache_hvp_coefficients) {
        trace.coefficient_hvp_lookups +=
            4U * workspace.tape.active_directed;
    }
    ++trace.joint_hvp_queries;
    if (audit) {
        const std::vector<Vec3> oracle = apply_hessian(
            joint_fluid_positions(workspace.neighborhood),
            joint_support_positions(workspace.neighborhood), joint_direction);
        ++trace.audit_all_pair_hvps;
        trace.exact = trace.exact && exact_vec3_values(taped, oracle);
    }
    return fluid_part(taped, fluid_count);
}

SpectralEstimate boundary_pressure_spectrum_joint_workspace(
    const JointPressureWorkspace& workspace,
    JointQueryTrace& trace,
    bool audit = true) {
    constexpr int iterations = 48;
    SpectralEstimate result;
    const std::size_t fluid_count = workspace.neighborhood.fluid.size();
    std::vector<std::vector<Vec3>> basis;
    basis.reserve(iterations);
    std::vector<Vec3> q = deterministic_direction(fluid_count);
    std::vector<Vec3> previous(fluid_count);
    double previous_beta = 0.0;
    std::vector<double> diagonal;
    std::vector<double> off_diagonal;
    for (int iteration = 0; iteration < iterations; ++iteration) {
        basis.push_back(q);
        std::vector<Vec3> image = pressure_hvp_joint_workspace(
            workspace, q, trace, audit);
        ++result.calls;
        const double alpha = flat_dot(q, image);
        diagonal.push_back(alpha);
        for (std::size_t i = 0; i < image.size(); ++i) {
            image[i] += -alpha * q[i] - previous_beta * previous[i];
        }
        for (const std::vector<Vec3>& vector : basis) {
            const double projection = flat_dot(vector, image);
            for (std::size_t i = 0; i < image.size(); ++i) {
                image[i] += -projection * vector[i];
            }
        }
        const double beta = vector_norm(image);
        if (iteration + 1 < iterations) {
            if (!std::isfinite(beta) || beta <= 1.0e-18) {
                break;
            }
            off_diagonal.push_back(beta);
            previous = q;
            previous_beta = beta;
            q = image;
            for (Vec3& value : q) {
                value = value / beta;
            }
        }
    }
    const std::size_t dimension = diagonal.size();
    std::vector<double> tridiagonal(dimension * dimension);
    for (std::size_t i = 0; i < dimension; ++i) {
        tridiagonal[i * dimension + i] = diagonal[i];
        if (i + 1U < dimension) {
            tridiagonal[i * dimension + i + 1U] = off_diagonal[i];
            tridiagonal[(i + 1U) * dimension + i] = off_diagonal[i];
        }
    }
    result.maximum_eigenvalue =
        symmetric_eigenvalue_bounds(tridiagonal, dimension).second;
    result.passed = result.calls == iterations
        && std::isfinite(result.maximum_eigenvalue)
        && result.maximum_eigenvalue > 0.0;
    return result;
}

JointForecastCase run_joint_forecast_case(
    std::string name, SmokeFixture fixture, bool require_active) {
    JointForecastCase result;
    result.name = std::move(name);
    const std::vector<Vec3> original_position = fixture.position;
    const std::vector<Vec3> original_velocity = fixture.velocity;
    std::vector<Vec3> predicted(fixture.position.size());
    for (std::size_t i = 0; i < predicted.size(); ++i) {
        predicted[i] = SMOKE_FRAME_TIME
            * (fixture.velocity[i]
                + SMOKE_FRAME_TIME * fixture.gravity);
    }
    predicted = clamp_box_displacement(
        fixture, fixture.position, predicted);
    const std::vector<Vec3> projected = materialize_displacement(
        fixture.position, predicted);
    JointPressureWorkspace workspace = build_joint_query_workspace(
        projected, fixture.boundary, "FORECAST", false, result.trace);
    if (!workspace.passed) {
        result.failure = workspace.failure;
        return result;
    }
    result.active_centers = static_cast<int>(
        workspace.evaluation.active_centers);
    result.spectrum_exact = !require_active
        && result.active_centers == 0;
    if (result.active_centers > 0) {
        const SpectralEstimate candidate =
            boundary_pressure_spectrum_joint_workspace(
                workspace, result.trace);
        const SpectralEstimate oracle = boundary_pressure_spectrum(
            projected, fixture.boundary);
        result.trace.audit_all_pair_hvps += oracle.calls;
        result.taped_hvp_calls = candidate.calls;
        result.maximum_eigenvalue = candidate.maximum_eigenvalue;
        result.spectrum_exact = candidate.passed && oracle.passed
            && candidate.calls == oracle.calls
            && candidate.maximum_eigenvalue == oracle.maximum_eigenvalue;
    }
    release_joint_query_workspace(workspace, result.trace);
    result.read_only = exact_vec3_values(
            fixture.position, original_position)
        && exact_vec3_values(fixture.velocity, original_velocity);
    const bool expected_path = require_active
        ? result.active_centers > 0 && result.taped_hvp_calls == 48
        : result.active_centers == 0 && result.taped_hvp_calls == 0;
    result.passed = expected_path && result.spectrum_exact
        && result.read_only && result.trace.exact
        && result.trace.work_reduced
        && result.trace.neighborhood_builds == 1
        && result.trace.tape_builds == 1
        && result.trace.live_workspaces == 0
        && result.trace.maximum_live_workspaces == 1
        && result.trace.candidate_all_pair_evaluations == 0
        && result.trace.candidate_all_pair_hvps == 0;
    if (!result.passed) {
        result.failure = "JOINT_FORECAST_GATE";
    }
    return result;
}

JointRejectCase run_joint_reject_case() {
    JointRejectCase result;
    const SmokeFixture fixture = make_b4b_supported_column_fixture();
    std::vector<Vec3> predicted(fixture.position.size());
    for (std::size_t i = 0; i < predicted.size(); ++i) {
        predicted[i] = SMOKE_FRAME_TIME
            * (fixture.velocity[i]
                + SMOKE_FRAME_TIME * fixture.gravity);
    }
    predicted = clamp_box_displacement(
        fixture, fixture.position, predicted);
    const std::vector<Vec3> current_position = materialize_displacement(
        fixture.position, predicted);
    JointPressureWorkspace current = build_joint_query_workspace(
        current_position, fixture.boundary,
        "REJECT_CURRENT", false, result.trace);
    if (!current.passed) {
        result.failure = current.failure;
        return result;
    }
    result.current_sha256 = current.state_sha256;
    const std::vector<JointPair> current_pairs =
        current.neighborhood.pairs;
    const std::vector<std::uint32_t> current_offsets =
        current.tape.offsets;
    const std::vector<std::uint32_t> current_indices =
        current.tape.directed_pair_indices;
    const std::vector<double> current_radius = current.tape.radius;
    const std::vector<double> current_compression =
        current.tape.compression;
    const Evaluation current_evaluation = current.evaluation;
    std::vector<Vec3> trial_step = deterministic_direction(
        current_position.size());
    for (Vec3& value : trial_step) {
        value = (0.1 * SPACING) * value;
    }
    trial_step = clamp_box_displacement(
        fixture, current_position, trial_step);
    const std::vector<Vec3> trial_position = materialize_displacement(
        current_position, trial_step);
    JointPressureWorkspace trial = build_joint_query_workspace(
        trial_position, fixture.boundary,
        "REJECT_TRIAL", true, result.trace);
    if (!trial.passed) {
        result.failure = trial.failure;
        release_joint_query_workspace(current, result.trace);
        return result;
    }
    result.trial_sha256 = trial.state_sha256;
    result.trial_distinct = result.trial_sha256 != result.current_sha256
        && !exact_vec3_values(trial_position, current_position);
    ++result.trace.rejected_workspace_destructions;
    release_joint_query_workspace(trial, result.trace);
    result.current_exact = current.state_sha256 == result.current_sha256
        && current.neighborhood.pairs == current_pairs
        && current.tape.offsets == current_offsets
        && current.tape.directed_pair_indices == current_indices
        && current.tape.radius == current_radius
        && current.tape.compression == current_compression
        && exact_evaluation_values(
            current.evaluation, current_evaluation);
    release_joint_query_workspace(current, result.trace);
    result.passed = result.trial_distinct && result.current_exact
        && result.trace.exact && result.trace.work_reduced
        && result.trace.trial_workspace_builds == 1
        && result.trace.rejected_workspace_destructions == 1
        && result.trace.accepted_workspace_promotions == 0
        && result.trace.maximum_live_workspaces == 2
        && result.trace.live_workspaces == 0;
    if (!result.passed) {
        result.failure = "JOINT_REJECT_TRANSACTION_GATE";
    }
    return result;
}

void append_joint_query_trace(
    std::ostringstream& output, const JointQueryTrace& trace) {
    output << "{\"exact\":" << (trace.exact ? "true" : "false")
           << ",\"work_reduced\":"
           << (trace.work_reduced ? "true" : "false")
           << ",\"joint_evaluation_queries\":"
           << trace.joint_evaluation_queries
           << ",\"joint_hvp_queries\":" << trace.joint_hvp_queries
           << ",\"candidate_all_pair_evaluations\":"
           << trace.candidate_all_pair_evaluations
           << ",\"candidate_all_pair_hvps\":"
           << trace.candidate_all_pair_hvps
           << ",\"audit_all_pair_evaluations\":"
           << trace.audit_all_pair_evaluations
           << ",\"audit_all_pair_hvps\":"
           << trace.audit_all_pair_hvps
           << ",\"neighborhood_builds\":"
           << trace.neighborhood_builds
           << ",\"tape_builds\":" << trace.tape_builds
           << ",\"trial_workspace_builds\":"
           << trace.trial_workspace_builds
           << ",\"accepted_workspace_promotions\":"
           << trace.accepted_workspace_promotions
           << ",\"rejected_workspace_destructions\":"
           << trace.rejected_workspace_destructions
           << ",\"maximum_live_workspaces\":"
           << trace.maximum_live_workspaces
           << ",\"final_live_workspaces\":" << trace.live_workspaces
           << ",\"queries\":[";
    for (std::size_t i = 0; i < trace.queries.size(); ++i) {
        if (i != 0U) {
            output << ',';
        }
        const JointQueryMetric& value = trace.queries[i];
        output << "{\"kind\":\"" << value.kind
               << "\",\"state_sha256\":\"" << value.state_sha256
               << "\",\"pairs\":" << value.pairs
               << ",\"directed_records\":" << value.directed
               << ",\"active_centers\":" << value.active_centers
               << ",\"cell_distance_tests\":"
               << value.cell_distance_tests
               << ",\"all_pair_candidate_checks\":"
               << value.all_pair_candidate_checks
               << ",\"tape_payload_bytes\":"
               << value.tape_payload_bytes << '}';
    }
    output << "]}";
}

void append_joint_query_case(
    std::ostringstream& output, const JointQueryCase& value) {
    output << "{\"name\":\"" << value.name
           << "\",\"status\":\"" << (value.passed ? "PASS" : "FAIL")
           << "\",\"failure\":\"" << value.failure
           << "\",\"solve_exact\":"
           << (value.solve_exact ? "true" : "false")
           << ",\"active_case\":"
           << (value.active_case ? "true" : "false")
           << ",\"inactive_case\":"
           << (value.inactive_case ? "true" : "false")
           << ",\"solve\":{\"outer_trials\":"
           << value.candidate.outer_trials
           << ",\"accepted_trials\":" << value.candidate.accepted_trials
           << ",\"rejected_trials\":" << value.candidate.rejected_trials
           << ",\"hvp_calls\":" << value.candidate.hvp_calls
           << ",\"projected_trials\":"
           << value.candidate.projected_trials
           << ",\"active_set_changes\":"
           << value.candidate.active_set_changes
           << ",\"active_centers\":"
           << value.candidate.state.smooth.support.active_centers
           << "},\"trace\":";
    append_joint_query_trace(output, value.trace);
    output << '}';
}

void append_joint_forecast_case(
    std::ostringstream& output, const JointForecastCase& value) {
    output << std::setprecision(17)
           << "{\"name\":\"" << value.name
           << "\",\"status\":\"" << (value.passed ? "PASS" : "FAIL")
           << "\",\"failure\":\"" << value.failure
           << "\",\"active_centers\":" << value.active_centers
           << ",\"taped_hvp_calls\":" << value.taped_hvp_calls
           << ",\"maximum_eigenvalue\":" << value.maximum_eigenvalue
           << ",\"spectrum_exact\":"
           << (value.spectrum_exact ? "true" : "false")
           << ",\"read_only\":"
           << (value.read_only ? "true" : "false")
           << ",\"trace\":";
    append_joint_query_trace(output, value.trace);
    output << '}';
}

void append_joint_reject_case(
    std::ostringstream& output, const JointRejectCase& value) {
    output << "{\"status\":\"" << (value.passed ? "PASS" : "FAIL")
           << "\",\"failure\":\"" << value.failure
           << "\",\"current_sha256\":\"" << value.current_sha256
           << "\",\"trial_sha256\":\"" << value.trial_sha256
           << "\",\"trial_distinct\":"
           << (value.trial_distinct ? "true" : "false")
           << ",\"current_exact_after_reject\":"
           << (value.current_exact ? "true" : "false")
           << ",\"trace\":";
    append_joint_query_trace(output, value.trace);
    output << '}';
}

bool joint_physical_diagnostic(
    const SmokeFixture& fixture,
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& velocity,
    std::string kind,
    JointQueryTrace& trace,
    double& mechanical,
    double& maximum_strain,
    const JointStaticSupportBinding* static_support = nullptr,
    StaticSupportWorkTrace* static_work = nullptr,
    bool flat_adjacency = false,
    FlatAdjacencyWorkTrace* adjacency_work = nullptr) {
    JointPressureWorkspace workspace = build_joint_query_workspace(
        position, fixture.boundary, std::move(kind), false, trace, false,
        static_support, static_work, flat_adjacency, adjacency_work);
    if (!workspace.passed) {
        return false;
    }
    double potential = 0.0;
    maximum_strain = 0.0;
    for (std::size_t i = 0; i < position.size(); ++i) {
        potential += MASS * (-fixture.gravity.y) * position[i].y;
        maximum_strain = std::max(maximum_strain,
            workspace.evaluation.density[i] / REST_DENSITY - 1.0);
    }
    mechanical = kinetic_energy(velocity)
        + workspace.evaluation.energy + potential;
    release_joint_query_workspace(workspace, trace);
    return true;
}

bool joint_physical_diagnostic_from_workspace(
    const SmokeFixture& fixture,
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& velocity,
    const JointPressureWorkspace& workspace,
    double& mechanical,
    double& maximum_strain) {
    if (!workspace.passed
        || workspace.neighborhood.fluid.size() != position.size()
        || workspace.neighborhood.support.size() != fixture.boundary.size()
        || workspace.evaluation.density.size() < position.size()) {
        return false;
    }
    for (std::size_t i = 0; i < position.size(); ++i) {
        if (workspace.neighborhood.fluid[i].position.x != position[i].x
            || workspace.neighborhood.fluid[i].position.y != position[i].y
            || workspace.neighborhood.fluid[i].position.z != position[i].z) {
            return false;
        }
    }
    for (std::size_t i = 0; i < fixture.boundary.size(); ++i) {
        if (workspace.neighborhood.support[i].position.x
                != fixture.boundary[i].x
            || workspace.neighborhood.support[i].position.y
                != fixture.boundary[i].y
            || workspace.neighborhood.support[i].position.z
                != fixture.boundary[i].z) {
            return false;
        }
    }
    double potential = 0.0;
    maximum_strain = 0.0;
    for (std::size_t i = 0; i < position.size(); ++i) {
        potential += MASS * (-fixture.gravity.y) * position[i].y;
        maximum_strain = std::max(maximum_strain,
            workspace.evaluation.density[i] / REST_DENSITY - 1.0);
    }
    mechanical = kinetic_energy(velocity)
        + workspace.evaluation.energy + potential;
    return true;
}

std::uint64_t binary64_bits(double value) {
    std::uint64_t bits = 0U;
    std::memcpy(&bits, &value, sizeof(bits));
    return bits;
}

bool consume_retained_joint_physical_diagnostic(
    const SmokeFixture& fixture,
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& velocity,
    JointPressureWorkspace& workspace,
    JointQueryTrace& trace,
    WorkspaceRetentionTrace& retention,
    double& mechanical,
    double& maximum_strain) {
    const bool passed = joint_physical_diagnostic_from_workspace(
        fixture, position, velocity, workspace,
        mechanical, maximum_strain);
    if (passed) {
        std::ostringstream material;
        material << std::hex << retention.receipt_sha256 << '|'
                 << retention.receipt_sequence << '|'
                 << workspace.state_sha256 << '|'
                 << binary64_bits(mechanical) << ':'
                 << binary64_bits(maximum_strain);
        retention.receipt_sha256 = sha256_hex(material.str());
        ++retention.receipt_sequence;
        ++retention.reads;
    }
    release_retained_joint_query_workspace(
        workspace, trace, retention);
    return passed;
}

B4BAggregate b4b_aggregate_joint(
    const SmokeFixture& fixture,
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& velocity,
    std::string kind,
    JointQueryTrace& trace,
    const JointStaticSupportBinding* static_support = nullptr,
    StaticSupportWorkTrace* static_work = nullptr,
    bool flat_adjacency = false,
    FlatAdjacencyWorkTrace* adjacency_work = nullptr) {
    B4BAggregate result;
    JointPressureWorkspace workspace = build_joint_query_workspace(
        position, fixture.boundary, std::move(kind), false, trace, false,
        static_support, static_work, flat_adjacency, adjacency_work);
    if (!workspace.passed) {
        return result;
    }
    result.center = average_values(position);
    result.momentum_value = momentum(velocity);
    result.kinetic = kinetic_energy(velocity);
    result.pressure = workspace.evaluation.energy;
    std::vector<double> heights;
    std::vector<double> fronts;
    heights.reserve(position.size());
    fronts.reserve(position.size());
    for (std::size_t i = 0; i < position.size(); ++i) {
        heights.push_back(position[i].y);
        fronts.push_back(position[i].x);
        result.gravitational += MASS
            * (-fixture.gravity.y) * position[i].y;
        result.maximum_speed_value = std::max(
            result.maximum_speed_value, norm(velocity[i]));
        const double ratio =
            workspace.evaluation.density[i] / REST_DENSITY;
        result.maximum_density_ratio = std::max(
            result.maximum_density_ratio, ratio);
        result.maximum_positive_strain = std::max(
            result.maximum_positive_strain, ratio - 1.0);
    }
    result.q99_height = nearest_rank_q99(std::move(heights));
    result.q99_front = nearest_rank_q99(std::move(fronts));
    result.mechanical = result.kinetic + result.pressure
        + result.gravitational;
    result.finite_values = finite(result.center)
        && finite(result.momentum_value)
        && std::isfinite(result.q99_height)
        && std::isfinite(result.q99_front)
        && std::isfinite(result.kinetic)
        && std::isfinite(result.pressure)
        && std::isfinite(result.gravitational)
        && std::isfinite(result.mechanical)
        && std::isfinite(result.maximum_density_ratio)
        && std::isfinite(result.maximum_speed_value);
    release_joint_query_workspace(workspace, trace);
    return result;
}

B4BFrameComparison compare_b4b_frame_joint(
    int frame,
    const SmokeFixture& fixture,
    const SmokeFrame& candidate,
    const SmokeRun& reference_run,
    const B4BAggregate& reference,
    JointQueryTrace& trace) {
    B4BFrameComparison result;
    result.frame = frame;
    const B4BAggregate candidate_value = b4b_aggregate_joint(
        fixture, candidate.position, candidate.velocity,
        "COMPARE_FRAME_" + std::to_string(frame), trace);
    result.position_dx = rms_difference(
        candidate.position, reference_run.position) / SPACING;
    result.velocity_c = rms_difference(
        candidate.velocity, reference_run.velocity)
        / std::sqrt(KAPPA / MASS);
    result.center_dx = maximum_component_abs(
        candidate_value.center - reference.center) / SPACING;
    result.q99_height_dx = std::abs(
        candidate_value.q99_height - reference.q99_height) / SPACING;
    result.q99_front_dx = std::abs(
        candidate_value.q99_front - reference.q99_front) / SPACING;
    result.kinetic_absolute = std::abs(
        candidate_value.kinetic - reference.kinetic);
    const double kinetic_scale = std::max(
        candidate_value.kinetic, reference.kinetic);
    result.kinetic_floor = gamma_factor(
        32U + 12U * candidate.velocity.size())
        * std::max(kinetic_scale, std::numeric_limits<double>::min());
    result.kinetic_floor_overlap = kinetic_scale <= 1.0e-12
        && result.kinetic_absolute <= result.kinetic_floor;
    if (kinetic_scale > 1.0e-12) {
        result.kinetic_relative = result.kinetic_absolute / kinetic_scale;
    }
    result.passed = candidate_value.finite_values
        && reference.finite_values
        && result.position_dx <= 0.05
        && result.velocity_c <= 0.001
        && result.center_dx <= 0.05
        && result.q99_height_dx <= 0.10
        && result.q99_front_dx <= 0.10
        && (kinetic_scale > 1.0e-12
            ? result.kinetic_relative <= 0.15
            : result.kinetic_floor_overlap);
    return result;
}

SmokeRun run_b4b1_interval_joint(
    const SmokeFixture& fixture,
    const std::vector<Vec3>& start_position,
    const std::vector<Vec3>& start_velocity,
    int substeps,
    double interval_start,
    double interval_duration,
    JointQueryTrace& trace,
    WorkspaceRetentionTrace* retention = nullptr,
    const JointStaticSupportBinding* static_support = nullptr,
    StaticSupportWorkTrace* static_work = nullptr,
    bool flat_adjacency = false,
    FlatAdjacencyWorkTrace* adjacency_work = nullptr) {
    SmokeRun result;
    result.position = start_position;
    result.velocity = start_velocity;
    result.substeps = substeps;
    double initial_mechanical = 0.0;
    double initial_strain = 0.0;
    if (!joint_physical_diagnostic(fixture, result.position, result.velocity,
            "RUN_INITIAL_DIAGNOSTIC", trace,
            initial_mechanical, initial_strain,
            static_support, static_work,
            flat_adjacency, adjacency_work)) {
        result.failure = "RUN_INITIAL_DIAGNOSTIC";
        return result;
    }
    result.maximum_mechanical_energy = initial_mechanical;
    result.maximum_positive_density_strain = initial_strain;
    result.maximum_speed = maximum_speed(result.velocity);
    std::vector<Vec3> expected_position = start_position;
    std::vector<Vec3> expected_velocity = start_velocity;
    bool precontact = true;
    const double time_step = interval_duration / static_cast<double>(substeps);
    for (int substep = 0; substep < substeps; ++substep) {
        JointPressureWorkspace retained_workspace;
        const BoxKktSolve solve = solve_box_kkt_step_joint_query(
            fixture, result.position, result.velocity,
            time_step, trace, false,
            retention != nullptr ? &retained_workspace : nullptr,
            retention, static_support, static_work,
            flat_adjacency, adjacency_work);
        ++result.attempted_substeps;
        result.attempted_outer_trials += solve.outer_trials;
        result.attempted_rejected_trials += solve.rejected_trials;
        result.attempted_hvp_calls += solve.hvp_calls;
        if (!solve.passed) {
            if (retained_workspace.passed && retention != nullptr) {
                release_retained_joint_query_workspace(
                    retained_workspace, trace, *retention);
            }
            result.failure = "SUBSTEP_" + std::to_string(substep)
                + ":KKT_SOLVE:" + solve.failure;
            result.outer_trials = solve.outer_trials;
            result.rejected_trials = solve.rejected_trials;
            result.hvp_calls = solve.hvp_calls;
            result.floor_merit_trials = solve.floor_merit_trials;
            result.floor_merit_accepts = solve.floor_merit_accepts;
            result.projected_trials = solve.projected_trials;
            result.active_set_changes = solve.active_set_changes;
            result.maximum_penetration = solve.state.maximum_penetration;
            result.maximum_ledger_residual = solve.state.ledger_residual;
            result.maximum_support_reaction_closure =
                solve.state.support_translation_closure;
            return result;
        }
        result.position = solve.position;
        result.velocity = solve.velocity;
        result.outer_trials += solve.outer_trials;
        result.rejected_trials += solve.rejected_trials;
        result.hvp_calls += solve.hvp_calls;
        result.negative_curvature_exits += solve.negative_curvature_exits;
        result.floor_merit_trials += solve.floor_merit_trials;
        result.floor_merit_accepts += solve.floor_merit_accepts;
        result.maximum_floor_accepts_per_solve = std::max(
            result.maximum_floor_accepts_per_solve,
            solve.floor_merit_accepts);
        result.projected_trials += solve.projected_trials;
        result.active_set_changes += solve.active_set_changes;
        const bool pressure_active =
            solve.state.smooth.support.active_centers > 0U;
        result.active_steps += pressure_active ? 1 : 0;
        result.inactive_steps += pressure_active ? 0 : 1;
        result.maximum_active_mixed_ratio = std::max(
            result.maximum_active_mixed_ratio,
            solve.state.projected_impulse_residual
                / std::max(solve.state.reaction_limit, 1.0e-300));
        result.maximum_pairs = std::max(result.maximum_pairs,
            solve.state.smooth.support.fluid_pairs
                + solve.state.smooth.support.boundary_pairs);
        result.maximum_penetration = std::max(
            result.maximum_penetration,
            solve.state.maximum_penetration);
        result.maximum_ledger_residual = std::max(
            result.maximum_ledger_residual,
            solve.state.ledger_residual);
        result.maximum_ledger_absolute = std::max(
            result.maximum_ledger_absolute,
            solve.state.ledger_absolute);
        result.maximum_support_reaction_closure = std::max(
            result.maximum_support_reaction_closure,
            solve.state.support_translation_closure);
        result.fluid_support_impulse +=
            solve.state.fluid_pressure_impulse;
        result.support_reaction += solve.state.support_reaction;
        result.fluid_contact_impulse +=
            solve.state.fluid_contact_impulse;
        result.contact_reaction += solve.state.contact_reaction;
        result.gravity_impulse += solve.state.gravity_impulse;
        double mechanical = 0.0;
        double strain = 0.0;
        const bool diagnostic_passed = retention != nullptr
            ? consume_retained_joint_physical_diagnostic(
                fixture, result.position, result.velocity,
                retained_workspace, trace, *retention,
                mechanical, strain)
            : joint_physical_diagnostic(
                fixture, result.position, result.velocity,
                "RUN_SUBSTEP_DIAGNOSTIC_" + std::to_string(substep),
                trace, mechanical, strain,
                static_support, static_work,
                flat_adjacency, adjacency_work);
        if (!diagnostic_passed) {
            result.failure = "RUN_SUBSTEP_DIAGNOSTIC";
            return result;
        }
        result.maximum_mechanical_energy = std::max(
            result.maximum_mechanical_energy, mechanical);
        result.maximum_positive_density_strain = std::max(
            result.maximum_positive_density_strain, strain);
        result.maximum_speed = std::max(
            result.maximum_speed, maximum_speed(result.velocity));

        std::vector<std::pair<std::size_t, int>> contacts;
        for (std::size_t i = 0; i < solve.state.active_axis.size(); ++i) {
            for (int axis = 0; axis < 3; ++axis) {
                if (!solve.state.active_axis[i][static_cast<std::size_t>(axis)]) {
                    continue;
                }
                const double gradient = component(
                    solve.state.active_gradient[i], axis);
                if (gradient != 0.0) {
                    contacts.emplace_back(i,
                        2 * axis + (gradient < 0.0 ? 1 : 0));
                }
            }
        }
        std::sort(contacts.begin(), contacts.end());
        result.contact_events += static_cast<int>(contacts.size());
        result.cache_invalidations += static_cast<int>(contacts.size());
        result.terminal_contacts = contacts;
        for (std::size_t face = 0; face < 6U; ++face) {
            result.face_active_axes[face] += solve.state.face_counts[face];
            result.face_multiplier_sum[face] +=
                solve.state.face_multiplier_sum[face];
            result.face_fluid_impulse[face] +=
                solve.state.face_fluid_impulse[face];
        }
        if (precontact && contacts.empty()) {
            for (std::size_t i = 0; i < expected_position.size(); ++i) {
                expected_velocity[i] += time_step * fixture.gravity;
                expected_position[i] += time_step * expected_velocity[i];
            }
            ++result.precontact_steps;
            result.precontact_pressure_violations += pressure_active ? 1 : 0;
            result.maximum_precontact_support_reaction = std::max(
                result.maximum_precontact_support_reaction,
                norm(solve.state.support_reaction));
            result.maximum_precontact_position_error = std::max(
                result.maximum_precontact_position_error,
                rms_difference(result.position, expected_position));
            result.maximum_precontact_velocity_error = std::max(
                result.maximum_precontact_velocity_error,
                rms_difference(result.velocity, expected_velocity));
            const Vec3 mean_velocity = average_values(result.velocity);
            for (Vec3 value : result.velocity) {
                result.maximum_precontact_velocity_spread = std::max(
                    result.maximum_precontact_velocity_spread,
                    norm(value - mean_velocity));
            }
        }
        if (!contacts.empty()) {
            if (!std::isfinite(result.first_contact_time)) {
                result.first_contact_time = interval_start
                    + static_cast<double>(substep + 1) * time_step;
            }
            precontact = false;
        }
        ++result.completed_substeps;
    }
    const std::size_t maximum_pairs = fixture.maximum_pairs > 0U
        ? fixture.maximum_pairs
        : 80U * (fixture.position.size() + fixture.boundary.size());
    result.passed = result.contact_events == result.cache_invalidations
        && result.maximum_pairs <= maximum_pairs
        && fixture.position.size() + fixture.boundary.size()
            <= fixture.maximum_participants
        && result.maximum_penetration <= 1.0e-12
        && result.maximum_ledger_residual <= 1.0e-9
        && result.maximum_support_reaction_closure <= 1.0e-10;
    if (!result.passed) {
        result.failure = "RUN_KKT_GATE";
    }
    return result;
}

SmokeController run_b4b1_controller_joint(
    const SmokeFixture& fixture,
    bool contact_forecast,
    JointQueryTrace& trace) {
    SmokeController result;
    result.position = fixture.position;
    result.velocity = fixture.velocity;
    bool global_precontact = true;
    for (int frame_index = 0; frame_index < fixture.macro_frames;
         ++frame_index) {
        SmokeFrame frame;
        frame.frame = frame_index;
        JointPressureWorkspace frame_workspace = build_joint_query_workspace(
            result.position, fixture.boundary,
            "FRAME_START_" + std::to_string(frame_index),
            false, trace, false);
        if (!frame_workspace.passed) {
            result.failure = "FRAME_START_WORKSPACE";
            return result;
        }
        frame.active_centers = static_cast<int>(
            frame_workspace.evaluation.active_centers);
        bool spectrum_required = false;
        if (frame.active_centers > 0) {
            frame.spectrum_source = "START_ACTIVE";
            spectrum_required = true;
        } else {
            release_joint_query_workspace(frame_workspace, trace);
            if (contact_forecast) {
                std::vector<Vec3> predicted(result.position.size());
                for (std::size_t i = 0; i < predicted.size(); ++i) {
                    predicted[i] = SMOKE_FRAME_TIME
                        * (result.velocity[i]
                            + SMOKE_FRAME_TIME * fixture.gravity);
                }
                predicted = clamp_box_displacement(
                    fixture, result.position, predicted);
                const std::vector<Vec3> projected = materialize_displacement(
                    result.position, predicted);
                frame_workspace = build_joint_query_workspace(
                    projected, fixture.boundary,
                    "FRAME_FORECAST_" + std::to_string(frame_index),
                    false, trace, false);
                if (!frame_workspace.passed) {
                    result.failure = "FRAME_FORECAST_WORKSPACE";
                    return result;
                }
                if (frame_workspace.evaluation.active_centers > 0U) {
                    frame.spectrum_source = "FORECAST_ACTIVE";
                    spectrum_required = true;
                } else {
                    frame.spectrum_source = "INACTIVE_EXACT";
                }
            } else {
                frame.spectrum_source = "START_INACTIVE";
            }
        }
        if (spectrum_required) {
            const SpectralEstimate spectrum =
                boundary_pressure_spectrum_joint_workspace(
                    frame_workspace, trace, false);
            frame.spectral_hvp_calls = spectrum.calls;
            frame.maximum_eigenvalue = spectrum.maximum_eigenvalue;
            frame.maximum_eigenfrequency = std::sqrt(
                std::max(spectrum.maximum_eigenvalue, 0.0) / MASS);
            if (!spectrum.passed) {
                release_joint_query_workspace(frame_workspace, trace);
                result.failure = "FRAME_SPECTRUM";
                return result;
            }
            frame.initial_substeps = std::max(1,
                static_cast<int>(std::ceil(SMOKE_FRAME_TIME
                    * frame.maximum_eigenfrequency / SPECTRAL_TARGET)));
        } else {
            frame.initial_substeps = 1;
        }
        if (frame_workspace.passed) {
            release_joint_query_workspace(frame_workspace, trace);
        }
        std::vector<SmokeRun> levels;
        for (int level = 0; level < 4; ++level) {
            levels.push_back(run_b4b1_interval_joint(fixture,
                result.position, result.velocity,
                frame.initial_substeps * (1 << level),
                static_cast<double>(frame_index) * SMOKE_FRAME_TIME,
                SMOKE_FRAME_TIME, trace));
            if (!levels.back().passed) {
                result.failure_ledger_absolute =
                    levels.back().maximum_ledger_absolute;
                result.failure_ledger_residual =
                    levels.back().maximum_ledger_residual;
                result.failure_active_centers = levels.back().active_steps;
                result.failure_outer_trials = levels.back().outer_trials;
                result.failure_hvp_calls = levels.back().hvp_calls;
                result.failure_contact_events = levels.back().contact_events;
                result.failure = "FRAME_CANDIDATE:" + levels.back().failure;
                return result;
            }
            if (level > 0) {
                frame.gate = smoke_gate(
                    levels[static_cast<std::size_t>(level - 1)],
                    levels[static_cast<std::size_t>(level)]);
                if (frame.gate.passed) {
                    frame.refinement_depth = level - 1;
                    frame.accepted_substeps =
                        levels[static_cast<std::size_t>(level)].substeps;
                    result.position =
                        levels[static_cast<std::size_t>(level)].position;
                    result.velocity =
                        levels[static_cast<std::size_t>(level)].velocity;
                    break;
                }
            }
        }
        if (frame.refinement_depth < 0) {
            result.failure = "FRAME_ERROR_GATE";
            return result;
        }
        for (int level = 0; level <= frame.refinement_depth + 1; ++level) {
            const SmokeRun& run = levels[static_cast<std::size_t>(level)];
            frame.executed_substeps += run.substeps;
            result.nonlinear_hvp_calls += run.hvp_calls;
            result.outer_trials += run.outer_trials;
            result.rejected_trials += run.rejected_trials;
            result.floor_merit_trials += run.floor_merit_trials;
            result.floor_merit_accepts += run.floor_merit_accepts;
            result.projected_trials += run.projected_trials;
            result.active_set_changes += run.active_set_changes;
            result.active_steps += run.active_steps;
            result.inactive_steps += run.inactive_steps;
        }
        frame.discarded_substeps = frame.executed_substeps
            - frame.accepted_substeps;
        const SmokeRun& accepted = levels[
            static_cast<std::size_t>(frame.refinement_depth + 1)];
        result.accepted_substeps += frame.accepted_substeps;
        result.executed_substeps += frame.executed_substeps;
        result.discarded_substeps += frame.discarded_substeps;
        result.spectral_hvp_calls += frame.spectral_hvp_calls;
        result.contact_events += accepted.contact_events;
        result.accepted_active_steps += accepted.active_steps;
        result.accepted_inactive_steps += accepted.inactive_steps;
        result.maximum_pairs = std::max(
            result.maximum_pairs, accepted.maximum_pairs);
        result.maximum_penetration = std::max(
            result.maximum_penetration, accepted.maximum_penetration);
        result.maximum_ledger_residual = std::max(
            result.maximum_ledger_residual,
            accepted.maximum_ledger_residual);
        result.maximum_support_reaction_closure = std::max(
            result.maximum_support_reaction_closure,
            accepted.maximum_support_reaction_closure);
        result.maximum_active_mixed_ratio = std::max(
            result.maximum_active_mixed_ratio,
            accepted.maximum_active_mixed_ratio);
        result.support_reaction += accepted.support_reaction;
        result.contact_reaction += accepted.contact_reaction;
        result.gravity_impulse += accepted.gravity_impulse;
        result.maximum_mechanical_energy = std::max(
            result.maximum_mechanical_energy,
            accepted.maximum_mechanical_energy);
        result.maximum_positive_density_strain = std::max(
            result.maximum_positive_density_strain,
            accepted.maximum_positive_density_strain);
        result.maximum_speed = std::max(
            result.maximum_speed, accepted.maximum_speed);
        for (std::size_t face = 0; face < 6U; ++face) {
            frame.face_active_axes[face] =
                accepted.face_active_axes[face];
            frame.face_multiplier_sum[face] =
                accepted.face_multiplier_sum[face];
            frame.face_fluid_impulse[face] =
                accepted.face_fluid_impulse[face];
            result.face_active_axes[face] +=
                accepted.face_active_axes[face];
            result.face_multiplier_sum[face] +=
                accepted.face_multiplier_sum[face];
            result.face_fluid_impulse[face] +=
                accepted.face_fluid_impulse[face];
        }
        result.first_contact_time = std::min(
            result.first_contact_time, accepted.first_contact_time);
        result.terminal_contacts = accepted.terminal_contacts;
        if (global_precontact) {
            result.precontact_steps += accepted.precontact_steps;
            result.precontact_pressure_violations +=
                accepted.precontact_pressure_violations;
            result.maximum_precontact_support_reaction = std::max(
                result.maximum_precontact_support_reaction,
                accepted.maximum_precontact_support_reaction);
            result.maximum_precontact_position_error = std::max(
                result.maximum_precontact_position_error,
                accepted.maximum_precontact_position_error);
            result.maximum_precontact_velocity_error = std::max(
                result.maximum_precontact_velocity_error,
                accepted.maximum_precontact_velocity_error);
            result.maximum_precontact_velocity_spread = std::max(
                result.maximum_precontact_velocity_spread,
                accepted.maximum_precontact_velocity_spread);
            global_precontact = !std::isfinite(
                accepted.first_contact_time);
        }
        frame.position = result.position;
        frame.velocity = result.velocity;
        frame.passed = true;
        result.frames.push_back(frame);
    }
    result.passed = result.contact_events > 0
        && result.maximum_penetration <= 1.0e-12
        && result.maximum_ledger_residual <= 1.0e-9
        && result.maximum_support_reaction_closure <= 1.0e-10;
    if (!result.passed) {
        result.failure = "CONTROLLER_PHYSICAL_GATE";
    }
    return result;
}

B4BFixedTrajectory run_b4b1_fixed_trajectory_joint(
    const SmokeFixture& fixture,
    int substeps_per_frame,
    JointQueryTrace& trace) {
    B4BFixedTrajectory result;
    result.substeps_per_frame = substeps_per_frame;
    result.position = fixture.position;
    result.velocity = fixture.velocity;
    for (int frame = 0; frame < fixture.macro_frames; ++frame) {
        SmokeRun run = run_b4b1_interval_joint(fixture,
            result.position, result.velocity, substeps_per_frame,
            static_cast<double>(frame) * SMOKE_FRAME_TIME,
            SMOKE_FRAME_TIME, trace);
        result.runs.push_back(run);
        if (!run.passed) {
            result.failure = "FRAME_" + std::to_string(frame)
                + ':' + run.failure;
            return result;
        }
        result.position = run.position;
        result.velocity = run.velocity;
        result.aggregates.push_back(b4b_aggregate_joint(
            fixture, result.position, result.velocity,
            "REFERENCE_AGGREGATE_" + std::to_string(substeps_per_frame)
                + '_' + std::to_string(frame),
            trace));
        result.active_steps += run.active_steps;
        result.contact_events += run.contact_events;
        result.outer_trials += run.outer_trials;
        result.rejected_trials += run.rejected_trials;
        result.hvp_calls += run.hvp_calls;
        result.floor_merit_accepts += run.floor_merit_accepts;
        result.maximum_pairs = std::max(
            result.maximum_pairs, run.maximum_pairs);
        result.maximum_penetration = std::max(
            result.maximum_penetration, run.maximum_penetration);
        result.maximum_ledger_residual = std::max(
            result.maximum_ledger_residual, run.maximum_ledger_residual);
        result.maximum_support_reaction_closure = std::max(
            result.maximum_support_reaction_closure,
            run.maximum_support_reaction_closure);
        result.maximum_mechanical_energy = std::max(
            result.maximum_mechanical_energy,
            run.maximum_mechanical_energy);
        result.first_contact_time = std::min(
            result.first_contact_time, run.first_contact_time);
        result.terminal_contacts = run.terminal_contacts;
    }
    result.passed = true;
    return result;
}

B4BReference run_b4b1_reference_joint(
    const SmokeFixture& fixture,
    JointQueryTrace& trace) {
    B4BReference result;
    for (std::size_t i = 0; i < B4B_REFERENCE_COUNTS.size(); ++i) {
        result.levels[i] = run_b4b1_fixed_trajectory_joint(
            fixture, B4B_REFERENCE_COUNTS[i], trace);
    }
    B4BConvergence& value = result.convergence;
    for (std::size_t i = 0; i < 2U; ++i) {
        value.position_difference[i] = rms_difference(
            result.levels[i].position, result.levels[i + 1U].position);
        value.velocity_difference[i] = rms_difference(
            result.levels[i].velocity, result.levels[i + 1U].velocity);
        value.position_floor[i] = b4b_rms_floor(
            result.levels[i].position, result.levels[i + 1U].position);
        value.velocity_floor[i] = b4b_rms_floor(
            result.levels[i].velocity, result.levels[i + 1U].velocity);
    }
    value.position_floor_overlap =
        value.position_difference[0] <= value.position_floor[0]
        && value.position_difference[1] <= value.position_floor[1];
    value.velocity_floor_overlap =
        value.velocity_difference[0] <= value.velocity_floor[0]
        && value.velocity_difference[1] <= value.velocity_floor[1];
    if (value.position_difference[1] > 0.0) {
        value.position_ratio = value.position_difference[0]
            / value.position_difference[1];
    }
    if (value.velocity_difference[1] > 0.0) {
        value.velocity_ratio = value.velocity_difference[0]
            / value.velocity_difference[1];
    }
    const bool position_order = value.position_difference[0] > 0.0
        && value.position_difference[1] > 0.0
        && value.position_ratio >= 1.25 && value.position_ratio <= 2.75;
    const bool velocity_order = value.velocity_difference[0] > 0.0
        && value.velocity_difference[1] > 0.0
        && value.velocity_ratio >= 1.25 && value.velocity_ratio <= 2.75;
    value.passed = (position_order || value.position_floor_overlap)
        && (velocity_order || value.velocity_floor_overlap);
    result.passed = std::all_of(result.levels.begin(), result.levels.end(),
            [](const B4BFixedTrajectory& level) { return level.passed; })
        && value.passed;
    return result;
}

B4BCase run_b4b1_case_joint(
    SmokeFixture fixture,
    bool released_block,
    JointQueryTrace& trace) {
    B4BCase result;
    trace.record_queries = false;
    result.fixture = std::move(fixture);
    result.initial = b4b_aggregate_joint(result.fixture,
        result.fixture.position, result.fixture.velocity,
        "CASE_INITIAL", trace);
    result.candidate = run_b4b1_controller_joint(
        result.fixture, true, trace);
    if (!result.candidate.passed) {
        result.failure = "CANDIDATE:" + result.candidate.failure;
        return result;
    }
    result.reference = run_b4b1_reference_joint(
        result.fixture, trace);
    const bool reference_runs_passed = std::all_of(
        result.reference.levels.begin(), result.reference.levels.end(),
        [](const B4BFixedTrajectory& level) { return level.passed; });
    if (!reference_runs_passed) {
        result.failure = "REFERENCE_RUN";
        return result;
    }
    if (!result.reference.convergence.passed) {
        result.failure = "REFERENCE_CONVERGENCE";
        return result;
    }
    const B4BFixedTrajectory& fine = result.reference.levels[2];
    for (std::size_t frame = 0; frame < result.candidate.frames.size();
         ++frame) {
        result.comparisons.push_back(compare_b4b_frame_joint(
            static_cast<int>(frame), result.fixture,
            result.candidate.frames[frame], fine.runs[frame],
            fine.aggregates[frame], trace));
    }
    result.comparison_passed = std::all_of(
        result.comparisons.begin(), result.comparisons.end(),
        [](const B4BFrameComparison& value) { return value.passed; });
    result.final = b4b_aggregate_joint(result.fixture,
        result.candidate.position, result.candidate.velocity,
        "CASE_FINAL", trace);
    result.lateral_drift = std::max(
        std::abs(result.final.center.x - result.initial.center.x),
        std::abs(result.final.center.z - result.initial.center.z));
    result.vertical_center_change = std::abs(
        result.final.center.y - result.initial.center.y);
    result.energy_allowance = 0.01 * std::max({
        std::abs(result.initial.mechanical),
        static_cast<double>(result.fixture.position.size())
            * MASS * (-result.fixture.gravity.y) * SPACING,
        1.0e-12,
    });
    result.energy_creation = std::max(0.0,
        result.candidate.maximum_mechanical_energy
            - result.initial.mechanical);
    result.contact_time_error = event_time_error(
        result.candidate.first_contact_time, fine.first_contact_time);
    result.contact_time_limit = b4b_contact_time_limit(result.candidate);
    result.terminal_contacts_exact = result.candidate.terminal_contacts
        == fine.terminal_contacts;
    const bool common_physical = result.initial.finite_values
        && result.final.finite_values
        && result.lateral_drift <= 1.0e-10
        && result.candidate.contact_events > 0
        && result.candidate.accepted_active_steps > 0
        && result.candidate.maximum_penetration <= 1.0e-12
        && result.candidate.maximum_ledger_residual <= 1.0e-9
        && result.candidate.maximum_support_reaction_closure <= 1.0e-10
        && result.energy_creation <= result.energy_allowance
        && result.terminal_contacts_exact;
    if (released_block) {
        result.physical_passed = common_physical
            && result.fixture.position.size() == 27U
            && result.candidate.precontact_steps > 0
            && result.candidate.precontact_pressure_violations == 0
            && result.candidate.maximum_precontact_support_reaction
                <= 1.0e-12
            && result.candidate.maximum_precontact_velocity_spread
                <= 1.0e-12
            && result.candidate.maximum_precontact_position_error
                <= 1.0e-12
            && result.candidate.maximum_precontact_velocity_error
                <= 1.0e-12
            && result.contact_time_error <= result.contact_time_limit;
    } else {
        result.physical_passed = common_physical
            && result.fixture.position.size() == 48U
            && result.vertical_center_change <= 0.05 * SPACING
            && result.candidate.maximum_positive_density_strain <= 1.0e-3
            && result.candidate.maximum_speed
                <= 0.01 * std::sqrt(KAPPA / MASS);
    }
    result.work_passed = b4b_work_gate(result);
    result.passed = result.comparison_passed
        && result.physical_passed && result.work_passed;
    if (!result.comparison_passed) {
        result.failure = "FRAME_COMPARISON";
    } else if (!result.physical_passed) {
        result.failure = "PHYSICAL_GATE";
    } else if (!result.work_passed) {
        result.failure = "WORK_GATE";
    }
    return result;
}

std::string serialize_b4b_case(const B4BCase& value) {
    std::ostringstream output;
    output << std::setprecision(17);
    append_b4b_case(output, value);
    return output.str();
}

std::string serialize_b4b2_forecast_work(const B4BCase& value) {
    std::ostringstream output;
    output << std::setprecision(17);
    append_b4b2_forecast_work(output, value);
    return output.str();
}

std::string serialize_b4b1_kkt_work(const B4BCase& value) {
    std::ostringstream output;
    output << std::setprecision(17);
    append_b4b1_kkt_work(output, value);
    return output.str();
}

JointControllerCase run_joint_controller_case(
    SmokeFixture fixture,
    bool released_block) {
    JointControllerCase result;
    result.name = fixture.name;
    result.oracle = run_b4b1_case(fixture, released_block, true);
    result.candidate = run_b4b1_case_joint(
        std::move(fixture), released_block, result.trace);
    const std::string oracle_case = serialize_b4b_case(result.oracle);
    const std::string candidate_case = serialize_b4b_case(result.candidate);
    result.case_serialization_exact = candidate_case == oracle_case;
    result.case_sha256 = sha256_hex(candidate_case);
    result.forecast_work_exact = serialize_b4b2_forecast_work(
            result.candidate)
        == serialize_b4b2_forecast_work(result.oracle);
    result.kkt_work_exact = serialize_b4b1_kkt_work(result.candidate)
        == serialize_b4b1_kkt_work(result.oracle);
    result.final_state_exact = exact_vec3_values(
            result.candidate.candidate.position,
            result.oracle.candidate.position)
        && exact_vec3_values(result.candidate.candidate.velocity,
            result.oracle.candidate.velocity);
    result.reference_state_exact = true;
    for (std::size_t level = 0;
         level < result.candidate.reference.levels.size(); ++level) {
        result.reference_state_exact = result.reference_state_exact
            && exact_vec3_values(
                result.candidate.reference.levels[level].position,
                result.oracle.reference.levels[level].position)
            && exact_vec3_values(
                result.candidate.reference.levels[level].velocity,
                result.oracle.reference.levels[level].velocity);
    }
    const bool trace_gate = result.trace.exact
        && result.trace.work_reduced
        && result.trace.neighborhood_builds
            == result.trace.joint_evaluation_queries
        && result.trace.tape_builds
            == result.trace.joint_evaluation_queries
        && result.trace.candidate_all_pair_evaluations == 0
        && result.trace.candidate_all_pair_hvps == 0
        && result.trace.audit_all_pair_evaluations == 0
        && result.trace.audit_all_pair_hvps == 0
        && result.trace.maximum_live_workspaces <= 2
        && result.trace.live_workspaces == 0
        && result.trace.queries.empty();
    result.passed = result.oracle.passed && result.candidate.passed
        && result.case_serialization_exact
        && result.forecast_work_exact && result.kkt_work_exact
        && result.final_state_exact && result.reference_state_exact
        && trace_gate;
    if (!result.passed) {
        result.failure = "JOINT_CONTROLLER_GATE";
    }
    return result;
}

void append_joint_controller_case(
    std::ostringstream& output, const JointControllerCase& value) {
    output << "{\"name\":\"" << value.name
           << "\",\"status\":\"" << (value.passed ? "PASS" : "FAIL")
           << "\",\"failure\":\"" << value.failure
           << "\",\"case_sha256\":\"" << value.case_sha256
           << "\",\"case_serialization_exact\":"
           << (value.case_serialization_exact ? "true" : "false")
           << ",\"forecast_work_exact\":"
           << (value.forecast_work_exact ? "true" : "false")
           << ",\"kkt_work_exact\":"
           << (value.kkt_work_exact ? "true" : "false")
           << ",\"final_state_exact\":"
           << (value.final_state_exact ? "true" : "false")
           << ",\"reference_state_exact\":"
           << (value.reference_state_exact ? "true" : "false")
           << ",\"controller\":{\"accepted_substeps\":"
           << value.candidate.candidate.accepted_substeps
           << ",\"executed_substeps\":"
           << value.candidate.candidate.executed_substeps
           << ",\"discarded_substeps\":"
           << value.candidate.candidate.discarded_substeps
           << ",\"spectral_hvp_calls\":"
           << value.candidate.candidate.spectral_hvp_calls
           << ",\"nonlinear_hvp_calls\":"
           << value.candidate.candidate.nonlinear_hvp_calls
           << ",\"outer_trials\":"
           << value.candidate.candidate.outer_trials
           << ",\"rejected_trials\":"
           << value.candidate.candidate.rejected_trials
           << "},\"trace\":{\"query_chain_sha256\":\""
           << value.trace.query_chain_sha256
           << "\",\"joint_evaluation_queries\":"
           << value.trace.joint_evaluation_queries
           << ",\"joint_hvp_queries\":" << value.trace.joint_hvp_queries
           << ",\"candidate_all_pair_evaluations\":"
           << value.trace.candidate_all_pair_evaluations
           << ",\"candidate_all_pair_hvps\":"
           << value.trace.candidate_all_pair_hvps
           << ",\"audit_all_pair_evaluations\":"
           << value.trace.audit_all_pair_evaluations
           << ",\"audit_all_pair_hvps\":"
           << value.trace.audit_all_pair_hvps
           << ",\"neighborhood_builds\":"
           << value.trace.neighborhood_builds
           << ",\"tape_builds\":" << value.trace.tape_builds
           << ",\"trial_workspace_builds\":"
           << value.trace.trial_workspace_builds
           << ",\"accepted_workspace_promotions\":"
           << value.trace.accepted_workspace_promotions
           << ",\"rejected_workspace_destructions\":"
           << value.trace.rejected_workspace_destructions
           << ",\"maximum_live_workspaces\":"
           << value.trace.maximum_live_workspaces
           << ",\"final_live_workspaces\":"
           << value.trace.live_workspaces
           << ",\"total_pairs\":" << value.trace.total_pairs
           << ",\"total_directed_records\":"
           << value.trace.total_directed
           << ",\"total_cell_distance_tests\":"
           << value.trace.total_cell_distance_tests
           << ",\"total_all_pair_candidate_checks\":"
           << value.trace.total_all_pair_candidate_checks
           << ",\"maximum_tape_payload_bytes\":"
           << value.trace.maximum_tape_payload_bytes << "}}";
}

