SplitBoundaryReport run_nominal_dam_first_output_impl(
    bool reference_binary64) {
    constexpr int worker_count = 8;
    omp_set_dynamic(0);
    omp_set_max_active_levels(1);
    const NominalAlignmentSpec& spec = B4E0_SCENARIOS[1];
    SmokeFixture fixture = make_b4e2d_dam_fixture();
    const std::string scenario_root = b4e0_scenario_root(
        b4e0_nominal_manifest(spec, false));
    const balanced_canonical::PublishResult initial =
        balanced_canonical::publish_frame(
            B4E0_PUBLICATION_SHA256, scenario_root, 0U,
            canonical_float_samples(fixture.position, fixture.velocity, 0));
    const std::string initial_aggregate_root =
        b4e0_initial_aggregate_root(initial.frame);
    fixture.position = decode_canonical_position(initial.frame);
    fixture.velocity = decode_canonical_velocity(initial.frame);
    fixture.geometry_sha256 = geometry_hash(fixture);

    StaticSupportWorkTrace static_work;
    FlatAdjacencyWorkTrace adjacency_work;
    const JointStaticSupportIndex index = build_joint_static_support_index(
        tagged_points(fixture.boundary), &static_work);
    const JointStaticSupportBinding binding = bind_joint_static_support_index(
        &index, index.identity_sha256);
    const JointNeighborhood initial_neighborhood =
        index.passed && binding.passed
        ? build_joint_neighborhood_with_static_support(
            tagged_points(fixture.position), &binding, true, &static_work,
            true, &adjacency_work)
        : JointNeighborhood{};
    const Evaluation initial_evaluation = initial_neighborhood.passed
        ? evaluate_joint(initial_neighborhood) : Evaluation{};
    double initial_mechanical = initial_evaluation.energy;
    for (const Vec3 position : fixture.position) {
        initial_mechanical += MASS * (-fixture.gravity.y) * position.y;
    }
    const std::string initial_pair_root = initial_neighborhood.passed
        ? joint_pair_hash(initial_neighborhood) : std::string{};
    const char* identity_sha256 = reference_binary64
        ? B4E2D3_IDENTITY_SHA256 : B4E2D_IDENTITY_SHA256;
    const char* identity_projection = reference_binary64
        ? B4E2D3_IDENTITY_PROJECTION : B4E2D_IDENTITY_PROJECTION;
    const std::string initial_binary64_root = b4e2d2_frame_zero_root(
        fixture.position, fixture.velocity);
    const bool selected_pair_exact = reference_binary64
        ? initial_pair_root
                == "fb2b8f8b4c0227cf5d8a7a43ce518ed72b2e5d5cda31fb8e8c17a5727c24ba13"
            && initial_neighborhood.pairs.size() == 342502U
            && initial_neighborhood.flat_directed_pair_indices.size()
                == 611520U
            && initial_neighborhood.maximum_degree == 120U
        : initial_pair_root
                == "c330a0aecb913d92e95478dc3325f9bc326d5e8d3057485723dd62eef1493889"
            && initial_neighborhood.pairs.size() == 335814U
            && initial_neighborhood.flat_directed_pair_indices.size()
                == 596256U
            && initial_neighborhood.maximum_degree == 117U;
    const bool identity_exact = sha256_hex(identity_projection)
            == identity_sha256
        && omp_get_dynamic() == 0 && omp_get_max_active_levels() == 1
        && scenario_root == spec.scenario_root
        && initial_aggregate_root
            == "37d83c159ff913afef290b9dc1cc7affe9f6018d726dd7b13ab9308f3bf741d3"
        && index.passed && binding.passed
        && index.identity_sha256
            == "a2d97ab6f26383d826366eba2a3d4392f5ef9610dda87e89509e93bd9daf61e8"
        && initial_neighborhood.passed
        && selected_pair_exact
        && (!reference_binary64 || initial_binary64_root
            == "0d567ba5512ba237a48e5e0b828a670a398f1bf23a35ac269729cad535f374d7")
        && fixture.position.size() == 6000U
        && fixture.boundary.size() == 16384U
        && std::isfinite(initial_mechanical)
        && b4e0_evaluation_finite(initial_evaluation)
        && static_work.static_index_builds == 1U;

    std::string first_failure;
    if (!identity_exact) {
        first_failure = "IDENTITY_ALIGNMENT";
    }
    std::vector<Vec3> position = fixture.position;
    std::vector<Vec3> velocity = fixture.velocity;
    std::vector<canonical::Frame> frames;
    std::vector<CanonicalPublicationLedgerEntry> ledgers;
    std::vector<B4E2DStep> steps;
    int accepted_substeps = 0;
    int attempted_substeps = 0;
    int discarded_substeps = 0;
    int outer_trials = 0;
    int rejected_trials = 0;
    int nonlinear_hvp_calls = 0;
    int spectral_hvp_calls = 0;
    double maximum_positive_strain = 0.0;
    double maximum_penetration = 0.0;
    double maximum_kkt_residual = 0.0;
    double maximum_strict_residual = 0.0;
    double maximum_support_reaction_closure = 0.0;
    double maximum_mechanical = initial_mechanical;
    double cumulative_pressure_delta = 0.0;
    double cumulative_mechanical_delta = 0.0;
    Vec3 cumulative_publication_impulse;
    bool state_handoff_exact = identity_exact;
    bool work_exact = identity_exact;
    bool transaction_physics_exact = identity_exact;

    for (std::uint32_t step = 1U;
         first_failure.empty() && step <= 4U; ++step) {
        const std::vector<Vec3> expected_position = step == 1U
            ? decode_canonical_position(initial.frame)
            : decode_canonical_position(frames.back());
        const std::vector<Vec3> expected_velocity = step == 1U
            ? decode_canonical_velocity(initial.frame)
            : decode_canonical_velocity(frames.back());
        const bool handoff = exact_vec3_values(position, expected_position)
            && exact_vec3_values(velocity, expected_velocity);
        state_handoff_exact = state_handoff_exact && handoff;
        if (!handoff) {
            first_failure = "STEP_" + std::to_string(step)
                + ":STATE_HANDOFF";
            break;
        }

        JointTopologySupersetCache cache;
        MacroAdaptiveTransactionCase transaction =
            run_macro_adaptive_transaction_case(
                "b4e2d-dam-step-" + std::to_string(step), fixture,
                scenario_root, false, true, &position, &velocity,
                static_cast<int>(step - 1U), step, true, true,
                &binding, &static_work, true, &adjacency_work, false,
                &cache, true, true, false, false, worker_count,
                false, false, false, false, false, false, false, false, true,
                false, true, false, false, false, false);
        B4E2DStep step_report;
        step_report.step = step;
        step_report.initial_substeps = transaction.initial_substeps;
        step_report.selected_level = transaction.selected_level;
        step_report.accepted_substeps = transaction.accepted_substeps;
        step_report.attempted_substeps = transaction.attempted_substeps;
        step_report.discarded_substeps = transaction.discarded_substeps;
        step_report.outer_trials = transaction.outer_trials;
        step_report.rejected_trials = transaction.rejected_trials;
        step_report.nonlinear_hvp_calls = transaction.nonlinear_hvp_calls;
        step_report.spectral_hvp_calls = transaction.spectral_hvp_calls;
        step_report.queries = cache.queries;
        step_report.cache_rebuilds = cache.rebuilds;
        step_report.cache_reuses = cache.reuses;
        step_report.cache_certificate_passes = cache.certificate_passes;
        step_report.scratch_calls = transaction.trace.owner_parallel
            .directed_scratch_reuse.calls;
        step_report.scratch_releases = transaction.trace.owner_parallel
            .directed_scratch_reuse.releases;
        step_report.output = b4e2d_output(transaction, step);
        if (transaction.passed && !transaction.committed_ledger.empty()) {
            const SmokeRun& accepted = transaction.accepted_private;
            const CanonicalPublicationLedgerEntry& ledger =
                transaction.committed_ledger.front();
            step_report.maximum_positive_strain = std::max(
                accepted.maximum_positive_density_strain,
                transaction.decoded_aggregate.maximum_positive_strain);
            step_report.maximum_penetration = std::max(
                accepted.maximum_penetration,
                transaction.maximum_decoded_penetration);
            step_report.maximum_kkt_residual = std::max(
                accepted.maximum_ledger_residual,
                ledger.compensated_kkt_residual);
            step_report.strict_residual = ledger.compensated_ledger_residual;
            step_report.support_reaction_closure =
                accepted.maximum_support_reaction_closure;
        }
        const bool cache_exact = b4e2d_cache_exact(cache);
        const bool step_work_exact = b4e2d_work_only_exact(transaction)
            && cache_exact
            && transaction.retention.transfers == transaction.retention.reads
            && transaction.retention.reads == transaction.retention.releases
            && transaction.retention.live_retained == 0
            && transaction.retention.maximum_live_retained <= 1;
        const bool step_physics_exact = transaction.passed
            && step_report.output.passed
            && transaction.fine_only_commit
            && transaction.accepted_substeps <= 192
            && transaction.maximum_attempted_level_substeps <= 768
            && step_report.maximum_positive_strain <= 1.0e-3
            && step_report.maximum_penetration <= 0.0025
            && step_report.maximum_kkt_residual <= 1.0e-9
            && std::isfinite(step_report.strict_residual)
            && step_report.support_reaction_closure <= 1.0e-10;
        step_report.passed = step_work_exact && step_physics_exact;
        if (!transaction.passed) {
            step_report.failure = transaction.failure;
        } else if (!cache_exact) {
            step_report.failure = "TOPOLOGY_CACHE";
        } else if (!step_work_exact) {
            step_report.failure = "WORK_OWNERSHIP";
        } else if (!step_physics_exact) {
            step_report.failure = "STEP_PHYSICS";
        }
        steps.push_back(step_report);
        work_exact = work_exact && step_work_exact;
        transaction_physics_exact = transaction_physics_exact
            && step_physics_exact;
        if (!step_report.passed) {
            first_failure = "STEP_" + std::to_string(step) + ':'
                + step_report.failure;
            break;
        }

        const SmokeRun& accepted = transaction.accepted_private;
        const CanonicalPublicationLedgerEntry& ledger =
            transaction.committed_ledger.front();
        accepted_substeps += transaction.accepted_substeps;
        attempted_substeps += transaction.attempted_substeps;
        discarded_substeps += transaction.discarded_substeps;
        outer_trials += transaction.outer_trials;
        rejected_trials += transaction.rejected_trials;
        nonlinear_hvp_calls += transaction.nonlinear_hvp_calls;
        spectral_hvp_calls += transaction.spectral_hvp_calls;
        maximum_positive_strain = std::max(
            maximum_positive_strain, step_report.maximum_positive_strain);
        maximum_penetration = std::max(
            maximum_penetration, step_report.maximum_penetration);
        maximum_kkt_residual = std::max(
            maximum_kkt_residual, step_report.maximum_kkt_residual);
        maximum_strict_residual = std::max(
            maximum_strict_residual, step_report.strict_residual);
        maximum_support_reaction_closure = std::max(
            maximum_support_reaction_closure,
            step_report.support_reaction_closure);
        maximum_mechanical = std::max({maximum_mechanical,
            accepted.maximum_mechanical_energy,
            transaction.decoded_aggregate.mechanical});
        cumulative_pressure_delta += std::abs(ledger.pressure_delta);
        cumulative_mechanical_delta += std::abs(ledger.mechanical_delta);
        cumulative_publication_impulse += ledger.direct_impulse;
        position = transaction.committed_position;
        velocity = transaction.committed_velocity;
        frames.push_back(transaction.committed_frames.front());
        ledgers.push_back(ledger);
    }

    const bool prefix_complete = frames.size() == 4U
        && ledgers.size() == frames.size() && steps.size() == 4U;
    bool global_steps_exact = prefix_complete;
    for (std::size_t index_value = 0U;
         index_value < frames.size(); ++index_value) {
        global_steps_exact = global_steps_exact
            && frames[index_value].step == index_value + 1U;
    }
    const bool final_decode_exact = prefix_complete
        && exact_vec3_values(position, decode_canonical_position(frames.back()))
        && exact_vec3_values(velocity, decode_canonical_velocity(frames.back()));
    const std::string trajectory_root = frames.empty() ? std::string{}
        : canonical::trajectory_root(
            B4C3P_PROFILE_SHA256, scenario_root,
            canonical_frame_roots(frames));
    const std::string legacy_ledger_root = publication_ledger_hash(ledgers);
    const std::string policy_ledger_root = macro_policy_ledger_hash(ledgers);
    const bool roots_exact = !frames.empty()
        && trajectory_root == canonical::trajectory_root(
            B4C3P_PROFILE_SHA256, scenario_root,
            canonical_frame_roots(frames))
        && legacy_ledger_root == publication_ledger_hash(ledgers)
        && policy_ledger_root == macro_policy_ledger_hash(ledgers);
    const bool accounting_exact = attempted_substeps
        == accepted_substeps + discarded_substeps;
    const double energy_scale = std::max({std::abs(initial_mechanical),
        static_cast<double>(fixture.position.size()) * MASS
            * std::abs(fixture.gravity.y) * SPACING,
        1.0e-12});
    const double energy_creation = std::max(
        0.0, maximum_mechanical - initial_mechanical);
    const double energy_creation_limit =
        0.01 * energy_scale + cumulative_mechanical_delta;
    const double impulse_limit = static_cast<double>(ledgers.size())
            * MASS * std::sqrt(3.0) * 0.5e-6
        + gamma_factor(32U + 3U * ledgers.size())
            * std::max(norm(cumulative_publication_impulse), 1.0e-30);
    const bool cumulative_physics_exact = prefix_complete
        && maximum_positive_strain <= 1.0e-3
        && maximum_penetration <= 0.0025
        && maximum_kkt_residual <= 1.0e-9
        && std::isfinite(maximum_strict_residual)
        && maximum_support_reaction_closure <= 1.0e-10
        && cumulative_pressure_delta <= 0.01 * energy_scale
        && cumulative_mechanical_delta <= 0.01 * energy_scale
        && energy_creation <= energy_creation_limit
        && norm(cumulative_publication_impulse) <= impulse_limit
        && accounting_exact;

    const B4E2DOutput final_output = prefix_complete
        ? steps.back().output : B4E2DOutput{};
    std::vector<double> center_errors;
    std::vector<double> q99_errors;
    if (final_output.passed) {
        constexpr std::array<double, 3> center_denominator{
            6000.0 * 4000000.0,
            6000.0 * 1000000.0,
            6000.0 * 1000000.0};
        for (std::size_t axis = 0U; axis < 3U; ++axis) {
            center_errors.push_back(std::abs(
                static_cast<double>(final_output.position_sum[axis]
                    - B4E2D_REFERENCE_POSITION_SUM[axis]))
                / center_denominator[axis]);
        }
        q99_errors.push_back(std::abs(
            static_cast<double>(final_output.q99[0]
                - B4E2D_REFERENCE_Q99[0])) / 4000000.0);
        q99_errors.push_back(std::abs(
            static_cast<double>(final_output.q99[1]
                - B4E2D_REFERENCE_Q99[1])) / 1000000.0);
    }
    const double center_rmse = center_errors.empty()
        ? std::numeric_limits<double>::infinity()
        : b4e2d_rmse(center_errors);
    const double center_maximum = center_errors.empty()
        ? std::numeric_limits<double>::infinity()
        : b4e2d_maximum(center_errors);
    const double q99_rmse = q99_errors.empty()
        ? std::numeric_limits<double>::infinity()
        : b4e2d_rmse(q99_errors);
    const double q99_maximum = q99_errors.empty()
        ? std::numeric_limits<double>::infinity()
        : b4e2d_maximum(q99_errors);
    const bool reference_exact = final_output.passed
        && center_rmse <= 0.05 && center_maximum <= 0.10
        && q99_rmse <= 0.05 && q99_maximum <= 0.10;
    if (first_failure.empty() && !cumulative_physics_exact) {
        first_failure = "CUMULATIVE_PHYSICS";
    }
    if (first_failure.empty() && !reference_exact) {
        first_failure = "REFERENCE_ENVELOPE";
    }
    const bool passed = first_failure.empty() && identity_exact
        && state_handoff_exact && transaction_physics_exact && work_exact
        && global_steps_exact && final_decode_exact && roots_exact
        && cumulative_physics_exact && reference_exact;

    std::ostringstream semantic;
    semantic << std::setprecision(17)
             << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << identity_sha256 << '|' << scenario_root << '|'
             << initial_pair_root << '|' << initial_aggregate_root << '|'
             << trajectory_root << '|' << legacy_ledger_root << '|'
             << policy_ledger_root << '|';
    for (const B4E2DStep& step : steps) {
        semantic << step.step << ':' << step.passed << ':'
                 << step.initial_substeps << ':' << step.selected_level << ':'
                 << step.accepted_substeps << ':' << step.attempted_substeps
                 << ':' << step.output.frame_root << ':'
                 << step.output.aggregate_root << '|';
    }
    semantic << maximum_positive_strain << ':' << maximum_penetration << ':'
             << maximum_kkt_residual << ':' << maximum_strict_residual << ':'
             << maximum_support_reaction_closure << '|'
             << cumulative_pressure_delta << ':'
             << cumulative_mechanical_delta << ':' << energy_creation << ':'
             << norm(cumulative_publication_impulse) << '|'
             << center_rmse << ':' << center_maximum << ':' << q99_rmse << ':'
             << q99_maximum;

    std::ostringstream report;
    report << std::setprecision(17)
           << "{\"schema\":\"nextengine.nonlocal."
           << (reference_binary64
                ? "nsr3b4e2d3_dam_reference_first_output.v1"
                : "nsr3b4e2d_dam_first_output.v1") << '"'
           << ",\"identity_sha256\":\"" << identity_sha256 << '"'
           << ",\"status\":\"" << (passed ? "PASS" : "FAIL") << '"'
           << ",\"first_failure\":\"" << first_failure << '"'
           << ",\"alignment\":{\"scenario_root\":\"" << scenario_root
           << "\",\"static_index_root\":\"" << index.identity_sha256
           << "\",\"initial_pair_root\":\"" << initial_pair_root
           << "\",\"initial_aggregate_root\":\""
           << initial_aggregate_root
           << "\",\"initial_binary64_root\":\""
           << initial_binary64_root
           << "\",\"fluid_samples\":" << fixture.position.size()
           << ",\"support_samples\":" << fixture.boundary.size()
           << ",\"identity_exact\":"
           << (identity_exact ? "true" : "false") << '}'
           << ",\"steps\":[";
    for (std::size_t index_value = 0U;
         index_value < steps.size(); ++index_value) {
        if (index_value != 0U) {
            report << ',';
        }
        append_b4e2d_step(report, steps[index_value]);
    }
    report << "]"
           << ",\"work\":{\"static_index_builds\":"
           << static_work.static_index_builds
           << ",\"workspace_builds\":" << static_work.workspace_builds
           << ",\"accepted_substeps\":" << accepted_substeps
           << ",\"attempted_substeps\":" << attempted_substeps
           << ",\"discarded_substeps\":" << discarded_substeps
           << ",\"outer_trials\":" << outer_trials
           << ",\"rejected_trials\":" << rejected_trials
           << ",\"nonlinear_hvp_calls\":" << nonlinear_hvp_calls
           << ",\"spectral_hvp_calls\":" << spectral_hvp_calls
           << ",\"exact\":" << (work_exact ? "true" : "false") << '}'
           << ",\"roots\":{\"trajectory\":\"" << trajectory_root
           << "\",\"legacy_ledger\":\"" << legacy_ledger_root
           << "\",\"policy_ledger\":\"" << policy_ledger_root
           << "\",\"exact\":" << (roots_exact ? "true" : "false")
           << '}'
           << ",\"cumulative_physics\":{\"maximum_positive_density_strain\":"
           << maximum_positive_strain
           << ",\"maximum_penetration_m\":" << maximum_penetration
           << ",\"maximum_kkt_residual\":" << maximum_kkt_residual
           << ",\"maximum_strict_residual\":" << maximum_strict_residual
           << ",\"maximum_support_reaction_closure\":"
           << maximum_support_reaction_closure
           << ",\"energy_scale_j\":" << energy_scale
           << ",\"cumulative_absolute_pressure_delta_j\":"
           << cumulative_pressure_delta
           << ",\"cumulative_absolute_mechanical_delta_j\":"
           << cumulative_mechanical_delta
           << ",\"energy_creation_j\":" << energy_creation
           << ",\"energy_creation_limit_j\":" << energy_creation_limit
           << ",\"publication_impulse_norm_kg_m_s\":"
           << norm(cumulative_publication_impulse)
           << ",\"publication_impulse_limit_kg_m_s\":" << impulse_limit
           << ",\"exact\":"
           << (cumulative_physics_exact ? "true" : "false") << '}'
           << ",\"first_output\":{\"step\":4,\"sample_count\":6000,"
              "\"mass_kg\":750,\"candidate_position_sum_um\":["
           << final_output.position_sum[0] << ','
           << final_output.position_sum[1] << ','
           << final_output.position_sum[2]
           << "],\"reference_position_sum_um\":["
           << B4E2D_REFERENCE_POSITION_SUM[0] << ','
           << B4E2D_REFERENCE_POSITION_SUM[1] << ','
           << B4E2D_REFERENCE_POSITION_SUM[2]
           << "],\"candidate_velocity_sum_um_s\":["
           << final_output.velocity_sum[0] << ','
           << final_output.velocity_sum[1] << ','
           << final_output.velocity_sum[2]
           << "],\"reference_velocity_sum_um_s\":["
           << B4E2D_REFERENCE_VELOCITY_SUM[0] << ','
           << B4E2D_REFERENCE_VELOCITY_SUM[1] << ','
           << B4E2D_REFERENCE_VELOCITY_SUM[2]
           << "],\"candidate_q99_position_um\":[" << final_output.q99[0]
           << ',' << final_output.q99[1]
           << "],\"reference_q99_position_um\":["
           << B4E2D_REFERENCE_Q99[0] << ',' << B4E2D_REFERENCE_Q99[1]
           << "],\"center_normalized_rmse\":" << center_rmse
           << ",\"center_normalized_maximum\":" << center_maximum
           << ",\"q99_normalized_rmse\":" << q99_rmse
           << ",\"q99_normalized_maximum\":" << q99_maximum
           << ",\"exact\":" << (reference_exact ? "true" : "false")
           << '}'
           << ",\"state_handoff_exact\":"
           << (state_handoff_exact ? "true" : "false")
           << ",\"global_steps_exact\":"
           << (global_steps_exact ? "true" : "false")
           << ",\"final_decode_exact\":"
           << (final_decode_exact ? "true" : "false")
           << ",\"watchdog_seconds\":900,\"timing_admitted\":false"
           << ",\"speedup_claim\":false"
           << ",\"b4e2h_contract_research_authorized\":"
           << (passed ? "true" : "false")
           << ",\"full_corpus_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << sha256_hex(semantic.str())
           << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport run_nominal_dam_first_output_controls() {
    return run_nominal_dam_first_output_impl(false);
}

SplitBoundaryReport run_nominal_dam_reference_first_output_controls() {
    return run_nominal_dam_first_output_impl(true);
}

SplitBoundaryReport run_nominal_dam_step2_strain_refinement_controls() {
    constexpr int worker_count = 8;
    constexpr double strain_limit = 1.0e-3;
    constexpr double resolved_strain_delta = 5.0e-5;
    omp_set_dynamic(0);
    omp_set_max_active_levels(1);
    const NominalAlignmentSpec& spec = B4E0_SCENARIOS[1];
    SmokeFixture fixture = make_b4e2d_dam_fixture();
    const std::string scenario_root = b4e0_scenario_root(
        b4e0_nominal_manifest(spec, false));
    const balanced_canonical::PublishResult initial =
        balanced_canonical::publish_frame(
            B4E0_PUBLICATION_SHA256, scenario_root, 0U,
            canonical_float_samples(fixture.position, fixture.velocity, 0));
    fixture.position = decode_canonical_position(initial.frame);
    fixture.velocity = decode_canonical_velocity(initial.frame);
    fixture.geometry_sha256 = geometry_hash(fixture);

    StaticSupportWorkTrace static_work;
    FlatAdjacencyWorkTrace adjacency_work;
    const JointStaticSupportIndex index = build_joint_static_support_index(
        tagged_points(fixture.boundary), &static_work);
    const JointStaticSupportBinding binding = bind_joint_static_support_index(
        &index, index.identity_sha256);
    const JointNeighborhood initial_neighborhood =
        index.passed && binding.passed
        ? build_joint_neighborhood_with_static_support(
            tagged_points(fixture.position), &binding, true, &static_work,
            true, &adjacency_work)
        : JointNeighborhood{};
    const std::string initial_pair_root = initial_neighborhood.passed
        ? joint_pair_hash(initial_neighborhood) : std::string{};
    const std::string initial_binary64_root = b4e2d2_frame_zero_root(
        fixture.position, fixture.velocity);
    const bool identity_exact = sha256_hex(B4E2D4_IDENTITY_PROJECTION)
            == B4E2D4_IDENTITY_SHA256
        && omp_get_dynamic() == 0 && omp_get_max_active_levels() == 1
        && scenario_root == spec.scenario_root
        && initial_binary64_root
            == "0d567ba5512ba237a48e5e0b828a670a398f1bf23a35ac269729cad535f374d7"
        && index.passed && binding.passed
        && index.identity_sha256
            == "a2d97ab6f26383d826366eba2a3d4392f5ef9610dda87e89509e93bd9daf61e8"
        && initial_neighborhood.passed
        && initial_pair_root
            == "fb2b8f8b4c0227cf5d8a7a43ce518ed72b2e5d5cda31fb8e8c17a5727c24ba13"
        && initial_neighborhood.pairs.size() == 342502U
        && initial_neighborhood.flat_directed_pair_indices.size() == 611520U
        && initial_neighborhood.maximum_degree == 120U
        && static_work.static_index_builds == 1U;

    const auto run_adaptive = [&](std::string name,
            const std::vector<Vec3>& position,
            const std::vector<Vec3>& velocity,
            int frame_index, std::uint32_t step,
            JointTopologySupersetCache& cache) {
        return run_macro_adaptive_transaction_case(
            std::move(name), fixture, scenario_root, false, true,
            &position, &velocity, frame_index, step, true, true,
            &binding, &static_work, true, &adjacency_work, false,
            &cache, true, true, false, false, worker_count,
            false, false, false, false, false, false, false, false, true,
            false, true, false, false, false, false);
    };

    MacroAdaptiveTransactionCase step1;
    JointTopologySupersetCache step1_cache;
    if (identity_exact) {
        step1 = run_adaptive(
            "b4e2d4-dam-step-1", fixture.position, fixture.velocity,
            0, 1U, step1_cache);
    }
    const B4E2DOutput step1_output = b4e2d_output(step1, 1U);
    const double step1_reported_strain = step1.passed
        ? std::max(step1.accepted_private.maximum_positive_density_strain,
            step1.decoded_aggregate.maximum_positive_strain) : 0.0;
    const bool step1_exact = identity_exact && step1.passed
        && b4e2d_work_only_exact(step1) && b4e2d_cache_exact(step1_cache)
        && step1.initial_substeps == 39 && step1.selected_level == 1
        && step1.accepted_substeps == 78
        && step1.attempted_substeps == 117
        && step1_reported_strain == 0.0004576940766030102
        && step1_output.passed
        && step1_output.frame_root
            == "c9afea4e49863db57b4099e3dee5d56d8d3b6ca9bcb03ba100e5870c46e29477"
        && step1_output.aggregate_root
            == "f1598838ff82272113fd9746683d1d857d81f692997a57a22b82151216efdda4";

    MacroAdaptiveTransactionCase step2;
    JointTopologySupersetCache step2_cache;
    if (step1_exact) {
        step2 = run_adaptive(
            "b4e2d4-dam-step-2", step1.committed_position,
            step1.committed_velocity, 1, 2U, step2_cache);
    }
    const B4E2DOutput step2_output = b4e2d_output(step2, 2U);
    const double private80_strain = step2.passed
        ? step2.accepted_private.maximum_positive_density_strain : 0.0;
    const double decoded80_strain = step2.passed
        ? step2.decoded_aggregate.maximum_positive_strain : 0.0;
    const double step2_reported_strain = std::max(
        private80_strain, decoded80_strain);
    const bool step2_exact = step1_exact && step2.passed
        && b4e2d_work_only_exact(step2) && b4e2d_cache_exact(step2_cache)
        && step2.initial_substeps == 40 && step2.selected_level == 1
        && step2.accepted_substeps == 80
        && step2.attempted_substeps == 120
        && step2_reported_strain == 0.0011747197409319732
        && step2_output.passed
        && step2_output.frame_root
            == "59f17359b06f9d428409399aa7a7acf03f0be56dc2fbdf67ad5f98a8a3e7f2b6"
        && step2_output.aggregate_root
            == "c045627c6abe5ab8bb003fca68796bb06f2b84f14ad8e6be33c4ccdf6ea74c48";

    B4E2D4FixedLane lane160;
    B4E2D4FixedLane lane320;
    if (step2_exact) {
        lane160 = run_b4e2d4_fixed_lane(
            fixture, step1.committed_position, step1.committed_velocity,
            160, binding, static_work, adjacency_work);
    }
    if (lane160.passed) {
        lane320 = run_b4e2d4_fixed_lane(
            fixture, step1.committed_position, step1.committed_velocity,
            320, binding, static_work, adjacency_work);
    }
    const std::string lane80_state_root = step2_exact
        ? b4e2d2_frame_zero_root(
            step2.accepted_private.position, step2.accepted_private.velocity)
        : std::string{};
    const SmokeGate gate80_160 = lane160.passed
        ? smoke_gate(step2.accepted_private, lane160.run) : SmokeGate{};
    const SmokeGate gate160_320 = lane320.passed
        ? smoke_gate(lane160.run, lane320.run) : SmokeGate{};
    const double strain_delta160_320 = lane320.passed
        ? std::abs(lane320.run.maximum_positive_density_strain
            - lane160.run.maximum_positive_density_strain)
        : std::numeric_limits<double>::infinity();
    const bool temporally_resolved = lane320.passed
        && gate160_320.passed
        && strain_delta160_320 <= resolved_strain_delta;
    std::string route;
    if (lane320.passed) {
        if (private80_strain <= strain_limit
            && decoded80_strain > strain_limit) {
            route = "PUBLICATION_STRAIN_ADMISSION_MISSING";
        } else if (temporally_resolved
            && lane320.run.maximum_positive_density_strain <= strain_limit) {
            route = "ADAPTIVE_DENSITY_ADMISSION_MISSING";
        } else if (temporally_resolved) {
            route = "FINITE_PENALTY_COMPRESSIBILITY";
        } else {
            route = "TEMPORAL_UNRESOLVED";
        }
    }

    std::string first_failure;
    if (!identity_exact) {
        first_failure = "IDENTITY_ALIGNMENT";
    } else if (!step1_exact) {
        first_failure = "STEP_1_REPRODUCTION";
    } else if (!step2_exact) {
        first_failure = "STEP_2_REPRODUCTION";
    } else if (!lane160.passed) {
        first_failure = "FIXED_160:" + lane160.failure;
    } else if (!lane320.passed) {
        first_failure = "FIXED_320:" + lane320.failure;
    } else if (route.empty()) {
        first_failure = "CLASSIFICATION";
    }
    const bool passed = first_failure.empty();

    const auto append_gate = [](std::ostringstream& output,
            const SmokeGate& gate) {
        output << std::setprecision(17)
               << "{\"passed\":" << (gate.passed ? "true" : "false")
               << ",\"normalized_position_error\":"
               << gate.normalized_position_error
               << ",\"normalized_velocity_error\":"
               << gate.normalized_velocity_error
               << ",\"relative_kinetic_error\":"
               << gate.relative_kinetic_error
               << ",\"contact_time_error_s\":"
               << gate.contact_time_error << '}';
    };
    const auto append_fixed_lane = [](std::ostringstream& output,
            const B4E2D4FixedLane& lane) {
        output << std::setprecision(17)
               << "{\"substeps\":" << lane.run.substeps
               << ",\"status\":\"" << (lane.passed ? "PASS" : "FAIL")
               << "\",\"failure\":\"" << lane.failure
               << "\",\"state_root\":\"" << lane.state_root
               << "\",\"completed_substeps\":"
               << lane.run.completed_substeps
               << ",\"outer_trials\":" << lane.run.outer_trials
               << ",\"hvp_calls\":" << lane.run.hvp_calls
               << ",\"queries\":" << lane.queries
               << ",\"cache\":{\"rebuilds\":" << lane.cache_rebuilds
               << ",\"reuses\":" << lane.cache_reuses
               << ",\"certificate_passes\":"
               << lane.cache_certificate_passes << "}"
               << ",\"directed_scratch\":{\"calls\":"
               << lane.scratch_calls << ",\"releases\":"
               << lane.scratch_releases << "}"
               << ",\"maximum_private_density_strain\":"
               << lane.run.maximum_positive_density_strain
               << ",\"maximum_penetration_m\":"
               << lane.run.maximum_penetration
               << ",\"maximum_kkt_residual\":"
               << lane.run.maximum_ledger_residual
               << ",\"support_reaction_closure\":"
               << lane.run.maximum_support_reaction_closure
               << ",\"work_exact\":"
               << (lane.work_exact ? "true" : "false")
               << ",\"cache_exact\":"
               << (lane.cache_exact ? "true" : "false") << '}';
    };

    std::ostringstream semantic;
    semantic << std::setprecision(17)
             << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D4_IDENTITY_SHA256 << '|' << scenario_root << '|'
             << initial_binary64_root << ':' << initial_pair_root << '|'
             << step1_output.frame_root << ':' << step1_output.aggregate_root
             << ':' << step1_reported_strain << '|'
             << step2_output.frame_root << ':' << step2_output.aggregate_root
             << ':' << private80_strain << ':' << decoded80_strain << '|'
             << lane80_state_root << ':' << step2.accepted_substeps << ':'
             << step2.accepted_private.outer_trials << ':'
             << step2.accepted_private.hvp_calls << '|'
             << lane160.state_root << ':' << lane160.run.substeps << ':'
             << lane160.run.outer_trials << ':' << lane160.run.hvp_calls << ':'
             << lane160.run.maximum_positive_density_strain << ':'
             << lane160.run.maximum_penetration << ':'
             << lane160.run.maximum_ledger_residual << ':'
             << lane160.run.maximum_support_reaction_closure << '|'
             << lane320.state_root << ':' << lane320.run.substeps << ':'
             << lane320.run.outer_trials << ':' << lane320.run.hvp_calls << ':'
             << lane320.run.maximum_positive_density_strain << ':'
             << lane320.run.maximum_penetration << ':'
             << lane320.run.maximum_ledger_residual << ':'
             << lane320.run.maximum_support_reaction_closure << '|'
             << gate80_160.passed << ':'
             << gate80_160.normalized_position_error << ':'
             << gate80_160.normalized_velocity_error << '|'
             << gate160_320.passed << ':'
             << gate160_320.normalized_position_error << ':'
             << gate160_320.normalized_velocity_error << ':'
             << strain_delta160_320 << ':' << temporally_resolved << '|'
             << route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    std::ostringstream report;
    report << std::setprecision(17)
           << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d4_step2_strain_refinement.v1\""
           << ",\"identity_sha256\":\"" << B4E2D4_IDENTITY_SHA256
           << "\",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure
           << "\",\"alignment\":{\"scenario_root\":\""
           << scenario_root << "\",\"initial_binary64_root\":\""
           << initial_binary64_root << "\",\"initial_pair_root\":\""
           << initial_pair_root << "\",\"identity_exact\":"
           << (identity_exact ? "true" : "false") << '}'
           << ",\"reproduction\":{\"step1_exact\":"
           << (step1_exact ? "true" : "false")
           << ",\"step1_frame_root\":\"" << step1_output.frame_root
           << "\",\"step1_aggregate_root\":\""
           << step1_output.aggregate_root
           << "\",\"step1_reported_strain\":"
           << step1_reported_strain
           << ",\"step2_exact\":" << (step2_exact ? "true" : "false")
           << ",\"step2_frame_root\":\"" << step2_output.frame_root
           << "\",\"step2_aggregate_root\":\""
           << step2_output.aggregate_root
           << "\",\"step2_private_peak_strain\":" << private80_strain
           << ",\"step2_decoded_strain\":" << decoded80_strain
           << ",\"step2_reported_strain\":" << step2_reported_strain
           << "},\"lanes\":[{\"substeps\":80,\"status\":\""
           << (step2_exact ? "PASS" : "FAIL")
           << "\",\"source\":\"adaptive-accepted-private\""
           << ",\"state_root\":\"" << lane80_state_root
           << "\",\"outer_trials\":"
           << step2.accepted_private.outer_trials
           << ",\"hvp_calls\":" << step2.accepted_private.hvp_calls
           << ",\"maximum_private_density_strain\":" << private80_strain
           << ",\"maximum_penetration_m\":"
           << step2.accepted_private.maximum_penetration
           << ",\"maximum_kkt_residual\":"
           << step2.accepted_private.maximum_ledger_residual
           << ",\"support_reaction_closure\":"
           << step2.accepted_private.maximum_support_reaction_closure << "},";
    append_fixed_lane(report, lane160);
    report << ',';
    append_fixed_lane(report, lane320);
    report << "],\"gates\":{\"80_160\":";
    append_gate(report, gate80_160);
    report << ",\"160_320\":";
    append_gate(report, gate160_320);
    report << ",\"strain_delta_160_320\":" << strain_delta160_320
           << ",\"resolved_strain_delta_limit\":"
           << resolved_strain_delta
           << ",\"temporally_resolved\":"
           << (temporally_resolved ? "true" : "false")
           << "},\"route\":\"" << route << '"'
           << ",\"physics_changed\":false,\"kappa_changed\":false"
           << ",\"tolerances_changed\":false,\"timing_admitted\":false"
           << ",\"speedup_claim\":false"
           << ",\"redesign_route_research_authorized\":"
           << (passed ? "true" : "false")
           << ",\"full_corpus_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport run_pressure_state_formulation_controls() {
    constexpr double strain320 = 0.0011739237712489192;
    constexpr double strain_limit = 1.0e-3;
    constexpr double gravity = 9.81;
    constexpr double derivative_step = 1.0e-7;
    constexpr double active_compression = 2.0e-3;
    constexpr double inactive_compression = -2.0e-3;
    const auto penalty = [](double compression, double beta) {
        const double active = std::max(0.0, compression);
        return 0.5 * beta * active * active;
    };
    const auto phr = [](double compression, double multiplier, double beta) {
        const double active = std::max(
            0.0, multiplier + beta * compression);
        return (active * active - multiplier * multiplier) / (2.0 * beta);
    };
    const auto phr_gradient = [](
            double compression, double multiplier, double beta) {
        return std::max(0.0, multiplier + beta * compression);
    };

    const double effective_bulk_modulus = KAPPA * REST_DENSITY / MASS;
    const double pressure320 = effective_bulk_modulus * strain320;
    const double effective_head = pressure320 / (REST_DENSITY * gravity);
    const double penalty_ratio = strain320 / strain_limit;
    const double minimum_kappa = KAPPA * penalty_ratio;
    const double stiffness_factor = std::sqrt(penalty_ratio);
    const std::array<double, 3> heads{1.0, 10.0, 100.0};
    std::array<double, 3> head_kappa{};
    std::array<double, 3> head_stiffness{};
    for (std::size_t index = 0U; index < heads.size(); ++index) {
        head_kappa[index] = MASS * gravity * heads[index] / strain_limit;
        head_stiffness[index] = std::sqrt(head_kappa[index] / KAPPA);
    }

    const double active_penalty = penalty(active_compression, KAPPA);
    const double active_phr_zero = phr(active_compression, 0.0, KAPPA);
    const double inactive_penalty = penalty(inactive_compression, KAPPA);
    const double inactive_phr_zero = phr(inactive_compression, 0.0, KAPPA);
    const double special_case_error = relative_error(
        active_penalty, active_phr_zero);

    const double active_gradient = phr_gradient(
        active_compression, 0.0, KAPPA);
    const double active_gradient_fd = (
        phr(active_compression + derivative_step, 0.0, KAPPA)
        - phr(active_compression - derivative_step, 0.0, KAPPA))
        / (2.0 * derivative_step);
    const double active_derivative_error = relative_error(
        active_gradient, active_gradient_fd);
    const double active_curvature_fd = (
        phr_gradient(active_compression + derivative_step, 0.0, KAPPA)
        - phr_gradient(active_compression - derivative_step, 0.0, KAPPA))
        / (2.0 * derivative_step);
    const double active_curvature_error = relative_error(
        KAPPA, active_curvature_fd);
    const double inactive_gradient = phr_gradient(
        inactive_compression, 0.0, KAPPA);
    const double inactive_gradient_fd = (
        phr(inactive_compression + derivative_step, 0.0, KAPPA)
        - phr(inactive_compression - derivative_step, 0.0, KAPPA))
        / (2.0 * derivative_step);
    const double inactive_curvature_fd = (
        phr_gradient(inactive_compression + derivative_step, 0.0, KAPPA)
        - phr_gradient(inactive_compression - derivative_step, 0.0, KAPPA))
        / (2.0 * derivative_step);

    const double multiplier_star = KAPPA * strain320;
    const double zero_strain_gradient = phr_gradient(
        0.0, multiplier_star, KAPPA);
    const double multiplier_pressure =
        zero_strain_gradient * REST_DENSITY / MASS;
    const double multiplier_next = phr_gradient(
        0.0, multiplier_star, KAPPA);
    const double complementarity = multiplier_star * 0.0;
    const double zero_multiplier_pressure =
        phr_gradient(0.0, 0.0, KAPPA) * REST_DENSITY / MASS;

    const bool identity_exact = sha256_hex(B4E2D5_IDENTITY_PROJECTION)
        == B4E2D5_IDENTITY_SHA256;
    const bool profile_exact = effective_bulk_modulus == 9810000.0
        && relative_error(pressure320, 11516.192195951897) <= 1.0e-15
        && relative_error(effective_head, 1.1739237712489192) <= 1.0e-15
        && relative_error(minimum_kappa, 1439.524024493987) <= 1.0e-15
        && relative_error(stiffness_factor, 1.0834776284025984) <= 1.0e-15;
    const bool scaling_exact = head_kappa[0] == KAPPA
        && head_kappa[1] == 12262.5 && head_kappa[2] == 122625.0
        && head_stiffness[0] == 1.0
        && relative_error(head_stiffness[1], std::sqrt(10.0)) <= 1.0e-15
        && head_stiffness[2] == 10.0;
    const bool special_case_exact = special_case_error <= 1.0e-15
        && inactive_penalty == 0.0 && inactive_phr_zero == 0.0;
    const bool derivative_exact = active_derivative_error <= 1.0e-7
        && active_curvature_error <= 1.0e-7
        && inactive_gradient == 0.0 && inactive_gradient_fd == 0.0
        && inactive_curvature_fd == 0.0;
    const bool pressure_state_exact = multiplier_star > 0.0
        && zero_strain_gradient == multiplier_star
        && multiplier_next == multiplier_star
        && relative_error(multiplier_pressure, pressure320) <= 1.0e-15
        && complementarity == 0.0;
    const bool zero_multiplier_negative = zero_multiplier_pressure == 0.0
        && pressure320 > 0.0 && zero_multiplier_pressure != pressure320;
    const std::array<double, 20> finite_controls{
        effective_bulk_modulus, pressure320, effective_head,
        penalty_ratio, minimum_kappa, stiffness_factor,
        head_kappa[0], head_kappa[1], head_kappa[2],
        head_stiffness[0], head_stiffness[1], head_stiffness[2],
        active_penalty, active_phr_zero, active_gradient,
        active_gradient_fd, active_curvature_fd, multiplier_star,
        multiplier_pressure, zero_multiplier_pressure};
    const bool finite_values = std::all_of(
        finite_controls.begin(), finite_controls.end(),
        [](double value) { return std::isfinite(value); });
    const bool passed = identity_exact && profile_exact && scaling_exact
        && special_case_exact && derivative_exact && pressure_state_exact
        && zero_multiplier_negative && finite_values;
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!profile_exact) first_failure = "PROFILE";
    else if (!scaling_exact) first_failure = "SCALING";
    else if (!special_case_exact) first_failure = "PENALTY_SPECIAL_CASE";
    else if (!derivative_exact) first_failure = "PHR_DERIVATIVE";
    else if (!pressure_state_exact) first_failure = "PRESSURE_STATE";
    else if (!zero_multiplier_negative) first_failure = "ZERO_STATE_NEGATIVE";
    else if (!finite_values) first_failure = "NONFINITE";
    const std::string selection = passed
        ? "AUGMENTED_LAGRANGIAN_PRESSURE_STATE" : std::string{};

    std::ostringstream semantic;
    semantic << std::setprecision(17)
             << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D5_IDENTITY_SHA256 << '|'
             << effective_bulk_modulus << ':' << pressure320 << ':'
             << effective_head << ':' << penalty_ratio << ':'
             << minimum_kappa << ':' << stiffness_factor << '|'
             << head_kappa[0] << ':' << head_kappa[1] << ':'
             << head_kappa[2] << ':' << head_stiffness[0] << ':'
             << head_stiffness[1] << ':' << head_stiffness[2] << '|'
             << active_penalty << ':' << active_phr_zero << ':'
             << inactive_penalty << ':' << inactive_phr_zero << ':'
             << active_derivative_error << ':' << active_curvature_error
             << ':' << inactive_gradient << ':' << inactive_gradient_fd
             << ':' << inactive_curvature_fd << '|'
             << multiplier_star << ':' << zero_strain_gradient << ':'
             << multiplier_pressure << ':' << multiplier_next << ':'
             << complementarity << ':' << zero_multiplier_pressure << '|'
             << selection;
    const std::string result_sha256 = sha256_hex(semantic.str());

    std::ostringstream report;
    report << std::setprecision(17)
           << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d5_pressure_state_formulation.v1\""
           << ",\"identity_sha256\":\"" << B4E2D5_IDENTITY_SHA256
           << "\",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"profile\":{\"kappa_j\":" << KAPPA
           << ",\"rho0_kg_m3\":" << REST_DENSITY
           << ",\"mass_kg\":" << MASS
           << ",\"effective_bulk_modulus_pa\":"
           << effective_bulk_modulus
           << ",\"strain_320\":" << strain320
           << ",\"strain_limit\":" << strain_limit
           << ",\"inferred_pressure_pa\":" << pressure320
           << ",\"effective_head_m\":" << effective_head
           << ",\"minimum_kappa_j\":" << minimum_kappa
           << ",\"penalty_ratio\":" << penalty_ratio
           << ",\"stiffness_factor\":" << stiffness_factor << '}'
           << ",\"head_scaling\":[";
    for (std::size_t index = 0U; index < heads.size(); ++index) {
        if (index != 0U) report << ',';
        report << "{\"head_m\":" << heads[index]
               << ",\"kappa_j\":" << head_kappa[index]
               << ",\"stiffness_factor\":" << head_stiffness[index]
               << '}';
    }
    report << "],\"phr_controls\":{\"penalty_special_case_error\":"
           << special_case_error
           << ",\"active_derivative_error\":" << active_derivative_error
           << ",\"active_curvature_error\":" << active_curvature_error
           << ",\"inactive_gradient\":" << inactive_gradient
           << ",\"inactive_gradient_fd\":" << inactive_gradient_fd
           << ",\"inactive_curvature_fd\":" << inactive_curvature_fd
           << ",\"exact\":" << (derivative_exact ? "true" : "false")
           << "},\"pressure_state\":{\"lambda_star_j\":"
           << multiplier_star
           << ",\"zero_strain_gradient_j\":" << zero_strain_gradient
           << ",\"mapped_pressure_pa\":" << multiplier_pressure
           << ",\"lambda_next_j\":" << multiplier_next
           << ",\"complementarity\":" << complementarity
           << ",\"zero_lambda_pressure_pa\":" << zero_multiplier_pressure
           << ",\"exact\":" << (pressure_state_exact ? "true" : "false")
           << "},\"selection\":\"" << selection << '"'
           << ",\"fallback\":\"SEMISMOOTH_PRIMAL_DUAL_IF_OUTER_STALLS\""
           << ",\"trajectory_steps\":0,\"physics_mutated\":false"
           << ",\"timing_admitted\":false,\"speedup_claim\":false"
           << ",\"tiny_al_oracle_contract_research_authorized\":"
           << (passed ? "true" : "false")
           << ",\"nominal_trajectory_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

namespace {

struct ALPathState {
    bool finite_values = false;
    double q = 0.0;
    std::vector<double> constraint;
    std::vector<double> first;
    std::vector<double> second;
    std::size_t pairs = 0U;
};

struct ALPathInnerState {
    ALPathState path;
    double energy = 0.0;
    double gradient = 0.0;
    double hessian = 0.0;
};

struct ALPathInnerSolve {
    bool passed = false;
    std::string failure;
    int iterations = 0;
    double low_gradient = 0.0;
    double high_gradient = 0.0;
    ALPathInnerState state;
};

struct ALPathOuterRecord {
    int outer = 0;
    int inner_iterations = 0;
    double q = 0.0;
    double inner_gradient = 0.0;
    double primal = 0.0;
    double scaled_dual_change = 0.0;
    double stationarity = 0.0;
    double complementarity = 0.0;
    double minimum_multiplier = 0.0;
    double maximum_multiplier = 0.0;
};

struct ALPathOuterSolve {
    bool passed = false;
    bool inner_exact = true;
    bool primal_monotone = true;
    bool cap_exhausted = false;
    std::string failure;
    double q = 0.0;
    std::vector<double> multiplier;
    ALPathState path;
    std::vector<ALPathOuterRecord> records;
};

ALPathState evaluate_al_path(const Fixture& fixture, double q) {
    ALPathState result;
    result.q = q;
    const std::size_t fluid_count = fixture.fluid.size();
    result.constraint.resize(fluid_count);
    result.first.resize(fluid_count);
    result.second.resize(fluid_count);
    const Vec3 center{
        0.5 * static_cast<double>(fixture.cells[0]) * SPACING,
        0.5 * static_cast<double>(fixture.cells[1]) * SPACING,
        0.5 * static_cast<double>(fixture.cells[2]) * SPACING,
    };
    const std::vector<Vec3> fluid = compressed_fluid(fixture, 1.0 - q);
    const Evaluation topology = evaluate(fluid, fixture.boundary);
    result.pairs = topology.fluid_pairs + topology.boundary_pairs;
    for (std::size_t particle = 0U; particle < fluid_count; ++particle) {
        double density = MASS * weight(0.0);
        double density_first = 0.0;
        double density_second = 0.0;
        const auto accumulate = [&](Vec3 displacement, Vec3 derivative) {
            const double radius = norm(displacement);
            if (radius > HORIZON) {
                return;
            }
            density += MASS * weight(radius);
            if (radius <= 1.0e-15) {
                return;
            }
            const double radius_first = dot(
                displacement, derivative) / radius;
            const double radius_second = (
                norm_squared(derivative)
                    - radius_first * radius_first) / radius;
            density_first += MASS * weight_gradient(radius) * radius_first;
            density_second += MASS * (
                weight_second(radius) * radius_first * radius_first
                + weight_gradient(radius) * radius_second);
        };
        for (std::size_t neighbor = 0U;
             neighbor < fluid_count; ++neighbor) {
            if (neighbor == particle) {
                continue;
            }
            const Vec3 reference =
                fixture.fluid[particle] - fixture.fluid[neighbor];
            accumulate(fluid[particle] - fluid[neighbor], -1.0 * reference);
        }
        const Vec3 particle_direction =
            -1.0 * (fixture.fluid[particle] - center);
        for (Vec3 support : fixture.boundary) {
            accumulate(fluid[particle] - support, particle_direction);
        }
        result.constraint[particle] = density / REST_DENSITY - 1.0;
        result.first[particle] = density_first / REST_DENSITY;
        result.second[particle] = density_second / REST_DENSITY;
    }
    result.finite_values = std::isfinite(q)
        && std::all_of(result.constraint.begin(), result.constraint.end(),
            [](double value) { return std::isfinite(value); })
        && std::all_of(result.first.begin(), result.first.end(),
            [](double value) { return std::isfinite(value); })
        && std::all_of(result.second.begin(), result.second.end(),
            [](double value) { return std::isfinite(value); });
    return result;
}

ALPathInnerState evaluate_al_path_inner(
    const Fixture& fixture,
    double q,
    double q_star,
    const std::vector<double>& multiplier) {
    ALPathInnerState result;
    result.path = evaluate_al_path(fixture, q);
    if (multiplier.size() != result.path.constraint.size()) {
        return result;
    }
    const double base = q - q_star;
    result.energy = 0.5 * base * base;
    result.gradient = base;
    result.hessian = 1.0;
    for (std::size_t center = 0U;
         center < multiplier.size(); ++center) {
        const double shifted = multiplier[center]
            + KAPPA * result.path.constraint[center];
        const double active = std::max(0.0, shifted);
        result.energy += (
            active * active - multiplier[center] * multiplier[center])
            / (2.0 * KAPPA);
        if (active <= 0.0) {
            continue;
        }
        result.gradient += active * result.path.first[center];
        result.hessian += KAPPA * result.path.first[center]
                * result.path.first[center]
            + active * result.path.second[center];
    }
    return result;
}

ALPathInnerSolve solve_al_path_inner(
    const Fixture& fixture,
    double q_star,
    const std::vector<double>& multiplier) {
    constexpr double low_bound = -0.02;
    constexpr double high_bound = 0.02;
    constexpr int maximum_iterations = 128;
    constexpr double gradient_limit = 1.0e-10;
    ALPathInnerSolve result;
    ALPathInnerState low = evaluate_al_path_inner(
        fixture, low_bound, q_star, multiplier);
    ALPathInnerState high = evaluate_al_path_inner(
        fixture, high_bound, q_star, multiplier);
    result.low_gradient = low.gradient;
    result.high_gradient = high.gradient;
    if (!low.path.finite_values || !high.path.finite_values
        || !std::isfinite(low.gradient) || !std::isfinite(high.gradient)
        || low.gradient > 0.0 || high.gradient < 0.0) {
        result.failure = "ROOT_BRACKET";
        return result;
    }
    double low_q = low_bound;
    double high_q = high_bound;
    for (int iteration = 0; iteration < maximum_iterations; ++iteration) {
        const double q = 0.5 * (low_q + high_q);
        result.state = evaluate_al_path_inner(
            fixture, q, q_star, multiplier);
        result.iterations = iteration + 1;
        if (!result.state.path.finite_values
            || !std::isfinite(result.state.energy)
            || !std::isfinite(result.state.gradient)
            || !std::isfinite(result.state.hessian)) {
            result.failure = "NONFINITE";
            return result;
        }
        if (std::abs(result.state.gradient) <= gradient_limit) {
            result.passed = true;
            return result;
        }
        if (result.state.gradient > 0.0) {
            high_q = q;
        } else {
            low_q = q;
        }
    }
    result.failure = "INNER_ITERATION_LIMIT";
    return result;
}

ALPathOuterSolve solve_al_path_outer(
    const Fixture& fixture,
    double q_star,
    std::vector<double> multiplier,
    int maximum_outer) {
    ALPathOuterSolve result;
    result.multiplier = multiplier;
    double previous_primal = std::numeric_limits<double>::infinity();
    for (int outer = 0; outer < maximum_outer; ++outer) {
        const ALPathInnerSolve inner = solve_al_path_inner(
            fixture, q_star, multiplier);
        if (!inner.passed) {
            result.inner_exact = false;
            result.failure = "INNER:" + inner.failure;
            return result;
        }
        std::vector<double> next(multiplier.size());
        ALPathOuterRecord record;
        record.outer = outer;
        record.inner_iterations = inner.iterations;
        record.q = inner.state.path.q;
        record.inner_gradient = std::abs(inner.state.gradient);
        record.minimum_multiplier = std::numeric_limits<double>::infinity();
        for (std::size_t center = 0U;
             center < multiplier.size(); ++center) {
            next[center] = std::max(0.0,
                multiplier[center]
                    + KAPPA * inner.state.path.constraint[center]);
            record.primal = std::max(record.primal,
                std::max(0.0, inner.state.path.constraint[center]));
            record.scaled_dual_change = std::max(
                record.scaled_dual_change,
                std::abs(next[center] - multiplier[center]) / KAPPA);
            record.complementarity = std::max(record.complementarity,
                std::abs(next[center]
                    * inner.state.path.constraint[center]));
            record.minimum_multiplier = std::min(
                record.minimum_multiplier, next[center]);
            record.maximum_multiplier = std::max(
                record.maximum_multiplier, next[center]);
        }
        record.stationarity = record.inner_gradient;
        result.primal_monotone = result.primal_monotone
            && record.primal <= previous_primal;
        previous_primal = record.primal;
        result.records.push_back(record);
        result.q = inner.state.path.q;
        result.path = inner.state.path;
        result.multiplier = next;
        multiplier = std::move(next);
        const bool active_q_exact = q_star <= 0.0
            || std::abs(result.q) <= 1.0e-9;
        if (record.primal <= 1.0e-10
            && record.scaled_dual_change <= 1.0e-10
            && record.stationarity <= 1.0e-10
            && record.complementarity <= 1.0e-10
            && record.minimum_multiplier >= 0.0
            && active_q_exact) {
            result.passed = true;
            return result;
        }
    }
    result.cap_exhausted = result.inner_exact && result.primal_monotone;
    result.failure = "OUTER_ITERATION_LIMIT";
    return result;
}

std::string al_path_state_root(
    const std::string& tag,
    double q,
    const std::vector<double>& multiplier) {
    std::ostringstream material;
    material << "nextengine.nonlocal.nsr3b4e2d6-state|v1|" << tag << '|'
             << binary64_bits(q) << '|' << multiplier.size();
    for (double value : multiplier) {
        material << ':' << binary64_bits(value);
    }
    return sha256_hex(material.str());
}

bool exact_al_multiplier(
    const std::vector<double>& lhs,
    const std::vector<double>& rhs) {
    if (lhs.size() != rhs.size()) {
        return false;
    }
    for (std::size_t index = 0U; index < lhs.size(); ++index) {
        if (binary64_bits(lhs[index]) != binary64_bits(rhs[index])) {
            return false;
        }
    }
    return true;
}

} // namespace

SplitBoundaryReport run_al_path_oracle_controls() {
    constexpr double derivative_step = 2.0e-7;
    const Fixture fixture = make_box_fixture(
        "corner-box-2x2x2", {2, 2, 2}, 2);
    const Evaluation rest = evaluate(fixture.fluid, fixture.boundary);
    const std::vector<Vec3> compressed = compressed_fluid(fixture, 0.99);
    const Evaluation active = evaluate(compressed, fixture.boundary);
    double rest_error = 0.0;
    for (double density : rest.density) {
        rest_error = std::max(rest_error,
            std::abs(density / REST_DENSITY - 1.0));
    }
    const auto active_bounds = std::minmax_element(
        active.density.begin(), active.density.end());
    const double active_minimum =
        *active_bounds.first / REST_DENSITY - 1.0;
    const double active_maximum =
        *active_bounds.second / REST_DENSITY - 1.0;
    const bool identity_exact = sha256_hex(B4E2D6_IDENTITY_PROJECTION)
        == B4E2D6_IDENTITY_SHA256;
    const bool fixture_exact = fixture.fluid.size() == 8U
        && fixture.boundary.size() == 176U
        && active.fluid_pairs + active.boundary_pairs == 828U
        && rest_error <= 3.0e-15 && active.active_centers == 8U
        && active_minimum == 1.0023623750961186 - 1.0
        && active_maximum == 1.002362375096119 - 1.0;

    const ALPathState center = evaluate_al_path(fixture, 0.01);
    const ALPathState plus = evaluate_al_path(
        fixture, 0.01 + derivative_step);
    const ALPathState minus = evaluate_al_path(
        fixture, 0.01 - derivative_step);
    double first_error = 0.0;
    double second_error = 0.0;
    for (std::size_t index = 0U;
         index < center.constraint.size(); ++index) {
        const double first_fd = (
            plus.constraint[index] - minus.constraint[index])
            / (2.0 * derivative_step);
        const double second_fd = (
            plus.first[index] - minus.first[index])
            / (2.0 * derivative_step);
        first_error = std::max(first_error,
            relative_error(center.first[index], first_fd));
        second_error = std::max(second_error,
            relative_error(center.second[index], second_fd));
    }
    const bool derivative_exact = center.finite_values
        && plus.finite_values && minus.finite_values
        && center.pairs == 828U && plus.pairs == center.pairs
        && minus.pairs == center.pairs
        && first_error <= 1.0e-7 && second_error <= 1.0e-7;

    const std::vector<double> zero_multiplier(fixture.fluid.size());
    const ALPathOuterSolve cold = solve_al_path_outer(
        fixture, 0.01, zero_multiplier, 8);
    const ALPathOuterSolve warm = cold.passed
        ? solve_al_path_outer(fixture, 0.01, cold.multiplier, 2)
        : ALPathOuterSolve{};
    double warm_multiplier_difference = 0.0;
    if (cold.multiplier.size() == warm.multiplier.size()) {
        for (std::size_t index = 0U;
             index < cold.multiplier.size(); ++index) {
            warm_multiplier_difference = std::max(
                warm_multiplier_difference,
                std::abs(cold.multiplier[index] - warm.multiplier[index]));
        }
    } else {
        warm_multiplier_difference =
            std::numeric_limits<double>::infinity();
    }
    const bool warm_exact = cold.passed && warm.passed
        && warm.records.size() <= 2U
        && std::abs(cold.q - warm.q) <= 1.0e-9
        && warm_multiplier_difference <= 1.0e-9;

    const ALPathOuterSolve inactive = solve_al_path_outer(
        fixture, -0.01, zero_multiplier, 2);
    const bool inactive_exact = inactive.passed
        && std::abs(inactive.q + 0.01) <= 1.0e-10
        && std::all_of(inactive.path.constraint.begin(),
            inactive.path.constraint.end(),
            [](double value) { return value <= 0.0; })
        && std::all_of(inactive.multiplier.begin(),
            inactive.multiplier.end(),
            [](double value) { return value == 0.0; });

    const ALPathInnerSolve reset = solve_al_path_inner(
        fixture, 0.01, zero_multiplier);
    double reset_primal = 0.0;
    if (reset.passed) {
        for (double value : reset.state.path.constraint) {
            reset_primal = std::max(reset_primal, std::max(0.0, value));
        }
    }
    const bool reset_negative = reset.passed
        && reset.state.path.q > 1.0e-8 && reset_primal > 1.0e-8;

    const ALPathOuterSolve private_forced = solve_al_path_outer(
        fixture, 0.01, zero_multiplier, 1);
    const double public_q = 0.0;
    const std::vector<double> public_multiplier = zero_multiplier;
    const bool rollback_exact = binary64_bits(public_q) == binary64_bits(0.0)
        && exact_al_multiplier(public_multiplier, zero_multiplier)
        && !private_forced.records.empty()
        && (binary64_bits(private_forced.q) != binary64_bits(public_q)
            || !exact_al_multiplier(
                private_forced.multiplier, public_multiplier));

    std::vector<double> mutated_multiplier = cold.passed
        ? cold.multiplier : zero_multiplier;
    if (!mutated_multiplier.empty()) {
        mutated_multiplier.front() = std::nextafter(
            mutated_multiplier.front(),
            std::numeric_limits<double>::infinity());
    }
    const ALPathInnerSolve mutation_control = solve_al_path_inner(
        fixture, 0.01, cold.passed ? cold.multiplier : zero_multiplier);
    const ALPathInnerSolve mutation_inner = solve_al_path_inner(
        fixture, 0.01, mutated_multiplier);
    const std::string cold_root = al_path_state_root(
        "cold", cold.q, cold.multiplier);
    const std::string warm_root = al_path_state_root(
        "warm", warm.q, warm.multiplier);
    const std::string inactive_root = al_path_state_root(
        "inactive", inactive.q, inactive.multiplier);
    const std::string mutation_root = al_path_state_root(
        "mutation", mutation_inner.state.path.q, mutated_multiplier);
    const std::string mutation_control_root = al_path_state_root(
        "mutation", mutation_control.state.path.q,
        cold.passed ? cold.multiplier : zero_multiplier);
    const bool mutation_sensitive = mutation_control.passed
        && mutation_inner.passed
        && mutation_root != mutation_control_root;

    const bool al_path_viable = cold.passed && cold.primal_monotone
        && warm_exact && inactive_exact && reset_negative
        && rollback_exact && mutation_sensitive;
    const bool fallback_selected = !cold.passed && cold.inner_exact
        && cold.primal_monotone && cold.cap_exhausted
        && inactive_exact && reset_negative && rollback_exact
        && mutation_sensitive;
    const std::string route = al_path_viable ? "AL_PATH_VIABLE"
        : (fallback_selected
            ? "SEMISMOOTH_PRIMAL_DUAL_REQUIRED" : std::string{});
    const bool passed = identity_exact && fixture_exact && derivative_exact
        && !route.empty();
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!fixture_exact) first_failure = "FIXTURE";
    else if (!derivative_exact) first_failure = "DERIVATIVE";
    else if (route.empty()) first_failure = "AL_PATH_CONTROLS";

    std::ostringstream semantic;
    semantic << std::setprecision(17)
             << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D6_IDENTITY_SHA256 << '|'
             << fixture.fluid.size() << ':' << fixture.boundary.size() << ':'
             << active.fluid_pairs + active.boundary_pairs << ':'
             << rest.fluid_pairs + rest.boundary_pairs << ':' << rest_error
             << ':' << active_minimum << ':' << active_maximum << '|'
             << first_error << ':' << second_error << '|'
             << cold.passed << ':' << cold.records.size() << ':' << cold.q
             << ':' << cold_root << ':' << cold.primal_monotone << '|'
             << warm.passed << ':' << warm.records.size() << ':' << warm.q
             << ':' << warm_multiplier_difference << ':' << warm_root << '|'
             << inactive.passed << ':' << inactive.q << ':'
             << inactive_root << '|' << reset.passed << ':'
             << reset.state.path.q << ':' << reset_primal << '|'
             << rollback_exact << ':' << mutation_sensitive << ':'
             << mutation_root << '|' << route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    const auto append_outer = [](std::ostringstream& output,
            const ALPathOuterSolve& solve) {
        output << "[";
        for (std::size_t index = 0U; index < solve.records.size(); ++index) {
            if (index != 0U) output << ',';
            const ALPathOuterRecord& record = solve.records[index];
            output << std::setprecision(17)
                   << "{\"outer\":" << record.outer
                   << ",\"inner_iterations\":"
                   << record.inner_iterations
                   << ",\"q\":" << record.q
                   << ",\"inner_gradient\":" << record.inner_gradient
                   << ",\"primal\":" << record.primal
                   << ",\"scaled_dual_change\":"
                   << record.scaled_dual_change
                   << ",\"stationarity\":" << record.stationarity
                   << ",\"complementarity\":"
                   << record.complementarity
                   << ",\"multiplier_range\":["
                   << record.minimum_multiplier << ','
                   << record.maximum_multiplier << "]}";
        }
        output << ']';
    };
    std::ostringstream report;
    report << std::setprecision(17)
           << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d6_al_path_oracle.v1\""
           << ",\"identity_sha256\":\"" << B4E2D6_IDENTITY_SHA256
           << "\",\"solver_identity\":\"nuv-al-pressure-r0\""
           << ",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"fixture\":{\"fluid_samples\":"
           << fixture.fluid.size() << ",\"support_samples\":"
           << fixture.boundary.size() << ",\"q001_pairs\":"
           << active.fluid_pairs + active.boundary_pairs
           << ",\"rest_pairs\":"
           << rest.fluid_pairs + rest.boundary_pairs
           << ",\"rest_error\":" << rest_error
           << ",\"q001_compression_range\":[" << active_minimum << ','
           << active_maximum << "],\"exact\":"
           << (fixture_exact ? "true" : "false") << '}'
           << ",\"derivatives\":{\"first_relative_error\":"
           << first_error << ",\"second_relative_error\":"
           << second_error << ",\"topology_stable\":"
           << (center.pairs == plus.pairs && center.pairs == minus.pairs
                   ? "true" : "false")
           << ",\"exact\":" << (derivative_exact ? "true" : "false")
           << "},\"cold\":{\"status\":\""
           << (cold.passed ? "PASS" : "FAIL")
           << "\",\"failure\":\"" << cold.failure
           << "\",\"q\":" << cold.q << ",\"state_root\":\""
           << cold_root << "\",\"primal_monotone\":"
           << (cold.primal_monotone ? "true" : "false")
           << ",\"outer\":";
    append_outer(report, cold);
    report << "},\"warm\":{\"status\":\""
           << (warm.passed ? "PASS" : "FAIL")
           << "\",\"q\":" << warm.q << ",\"state_root\":\""
           << warm_root << "\",\"multiplier_max_difference\":"
           << warm_multiplier_difference << ",\"exact\":"
           << (warm_exact ? "true" : "false") << ",\"outer\":";
    append_outer(report, warm);
    report << "},\"inactive\":{\"status\":\""
           << (inactive.passed ? "PASS" : "FAIL")
           << "\",\"q\":" << inactive.q << ",\"state_root\":\""
           << inactive_root << "\",\"exact\":"
           << (inactive_exact ? "true" : "false") << '}'
           << ",\"reset_negative\":{\"q\":" << reset.state.path.q
           << ",\"primal\":" << reset_primal << ",\"exact\":"
           << (reset_negative ? "true" : "false") << '}'
           << ",\"rollback_exact\":"
           << (rollback_exact ? "true" : "false")
           << ",\"mutation\":{\"root\":\"" << mutation_root
           << "\",\"control_root\":\"" << mutation_control_root
           << "\",\"sensitive\":"
           << (mutation_sensitive ? "true" : "false") << '}'
           << ",\"route\":\"" << route << '"'
           << ",\"trajectory_steps\":0,\"timing_admitted\":false"
           << ",\"dense_al_oracle_contract_research_authorized\":"
           << (passed ? "true" : "false")
           << ",\"nominal_trajectory_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

namespace {

struct ALVectorSupport {
    bool finite_values = false;
    double energy = 0.0;
    std::vector<double> density;
    std::vector<double> constraint;
    std::vector<double> active_coefficient;
    std::vector<Vec3> gradient;
    std::size_t active_centers = 0U;
    std::size_t fluid_pairs = 0U;
    std::size_t boundary_pairs = 0U;
};

struct ALVectorInnerState {
    ALVectorSupport support;
    double total = 0.0;
    std::vector<Vec3> gradient;
};

struct ALVectorInnerSolve {
    bool passed = false;
    std::string failure;
    std::vector<Vec3> position;
    ALVectorSupport support;
    int outer_trials = 0;
    int accepted_trials = 0;
    int rejected_trials = 0;
    int hvp_calls = 0;
    int negative_curvature_exits = 0;
    double final_scaled_stationarity = 0.0;
    double minimum_accepted_ratio = std::numeric_limits<double>::infinity();
    bool positive_accepted_models = true;
};

struct ALVectorOuterRecord {
    int outer = 0;
    int inner_outer_trials = 0;
    int inner_accepted_trials = 0;
    int inner_rejected_trials = 0;
    int inner_hvp_calls = 0;
    double primal = 0.0;
    double scaled_dual_change = 0.0;
    double stationarity = 0.0;
    double complementarity = 0.0;
    double absolute_dual_change = 0.0;
    double equivalent_pressure_change = 0.0;
    double position_update_dx = 0.0;
    double minimum_multiplier = 0.0;
    double maximum_multiplier = 0.0;
};

struct ALVectorOuterSolve {
    bool passed = false;
    bool inner_exact = true;
    bool primal_monotone = true;
    bool cap_exhausted = false;
    std::string failure;
    std::vector<Vec3> position;
    std::vector<double> multiplier;
    ALVectorSupport support;
    std::vector<ALVectorOuterRecord> records;
};

struct ALVectorStableSolve {
    bool passed = false;
    bool inner_exact = true;
    bool primal_monotone = true;
    bool cap_exhausted = false;
    bool prefix_exact = false;
    std::string failure;
    int provisional_index = -1;
    int confirmation_index = -1;
    std::vector<Vec3> position;
    std::vector<double> multiplier;
    std::vector<Vec3> prefix_position;
    std::vector<double> prefix_multiplier;
    std::vector<Vec3> provisional_position;
    std::vector<double> provisional_multiplier;
    ALVectorSupport support;
    std::vector<ALVectorOuterRecord> records;
};

ALVectorSupport evaluate_al_vector_support(
    const std::vector<Vec3>& fluid,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier,
    double kappa = KAPPA) {
    ALVectorSupport result;
    const std::size_t fluid_count = fluid.size();
    if (multiplier.size() != fluid_count
        || !std::isfinite(kappa) || kappa <= 0.0) {
        return result;
    }
    result.gradient.resize(fluid_count + boundary.size());
    result.density.assign(fluid_count, MASS * weight(0.0));
    for (std::size_t i = 0U; i < fluid_count; ++i) {
        for (std::size_t j = i + 1U; j < fluid_count; ++j) {
            const double radius = norm(fluid[i] - fluid[j]);
            if (radius <= HORIZON) {
                const double contribution = MASS * weight(radius);
                result.density[i] += contribution;
                result.density[j] += contribution;
                ++result.fluid_pairs;
            }
        }
        for (std::size_t support = 0U;
             support < boundary.size(); ++support) {
            const double radius = norm(fluid[i] - boundary[support]);
            if (radius <= HORIZON) {
                result.density[i] += MASS * weight(radius);
                ++result.boundary_pairs;
            }
        }
    }
    result.constraint.resize(fluid_count);
    result.active_coefficient.resize(fluid_count);
    for (std::size_t center = 0U; center < fluid_count; ++center) {
        const double constraint =
            result.density[center] / REST_DENSITY - 1.0;
        const double active = std::max(
            0.0, multiplier[center] + kappa * constraint);
        result.constraint[center] = constraint;
        result.active_coefficient[center] = active;
        result.energy += (
            active * active - multiplier[center] * multiplier[center])
            / (2.0 * kappa);
        if (active <= 0.0) {
            continue;
        }
        ++result.active_centers;
        const double scale = active * MASS / REST_DENSITY;
        const auto accumulate = [&](std::size_t participant,
                                     Vec3 displacement) {
            const double radius = norm(displacement);
            if (radius <= 1.0e-15 || radius > HORIZON) {
                return;
            }
            const Vec3 pair = scale * weight_gradient(radius)
                * (displacement / radius);
            result.gradient[center] += pair;
            result.gradient[participant] += -pair;
        };
        for (std::size_t neighbor = 0U;
             neighbor < fluid_count; ++neighbor) {
            if (neighbor != center) {
                accumulate(neighbor, fluid[center] - fluid[neighbor]);
            }
        }
        for (std::size_t support = 0U;
             support < boundary.size(); ++support) {
            accumulate(fluid_count + support,
                fluid[center] - boundary[support]);
        }
    }
    result.finite_values = std::isfinite(result.energy)
        && std::all_of(result.density.begin(), result.density.end(),
            [](double value) { return std::isfinite(value); })
        && std::all_of(result.constraint.begin(), result.constraint.end(),
            [](double value) { return std::isfinite(value); })
        && std::all_of(result.active_coefficient.begin(),
            result.active_coefficient.end(),
            [](double value) { return std::isfinite(value); })
        && std::all_of(result.gradient.begin(), result.gradient.end(),
            [](Vec3 value) { return finite(value); });
    return result;
}

std::vector<Vec3> apply_al_vector_hessian(
    const std::vector<Vec3>& fluid,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier,
    const std::vector<Vec3>& direction,
    double kappa = KAPPA) {
    const std::size_t fluid_count = fluid.size();
    const std::size_t total_count = fluid_count + boundary.size();
    if (direction.size() != total_count
        || multiplier.size() != fluid_count
        || !std::isfinite(kappa) || kappa <= 0.0) {
        throw std::invalid_argument("AL dense HVP size mismatch");
    }
    const ALVectorSupport state = evaluate_al_vector_support(
        fluid, boundary, multiplier, kappa);
    std::vector<Vec3> result(total_count);
    for (std::size_t center = 0U; center < fluid_count; ++center) {
        const double active = state.active_coefficient[center];
        if (active <= 0.0) {
            continue;
        }
        double constraint_direction = 0.0;
        const auto fold_direction = [&](std::size_t participant,
                                         Vec3 displacement) {
            const double radius = norm(displacement);
            if (radius <= 1.0e-15 || radius > HORIZON) {
                return;
            }
            const Vec3 jacobian = MASS / REST_DENSITY
                * weight_gradient(radius) * (displacement / radius);
            constraint_direction += dot(
                jacobian, direction[center] - direction[participant]);
        };
        for (std::size_t neighbor = 0U;
             neighbor < fluid_count; ++neighbor) {
            if (neighbor != center) {
                fold_direction(
                    neighbor, fluid[center] - fluid[neighbor]);
            }
        }
        for (std::size_t support = 0U;
             support < boundary.size(); ++support) {
            fold_direction(fluid_count + support,
                fluid[center] - boundary[support]);
        }
        const auto accumulate = [&](std::size_t participant,
                                     Vec3 displacement) {
            const double radius = norm(displacement);
            if (radius <= 1.0e-15 || radius > HORIZON) {
                return;
            }
            const Vec3 normal = displacement / radius;
            const Vec3 jacobian = MASS / REST_DENSITY
                * weight_gradient(radius) * normal;
            const Vec3 relative =
                direction[center] - direction[participant];
            const Vec3 curvature = MASS / REST_DENSITY
                * radial_hessian_product(normal,
                    weight_second(radius),
                    weight_gradient(radius) / radius, relative);
            const Vec3 pair = kappa * constraint_direction * jacobian
                + active * curvature;
            result[center] += pair;
            result[participant] += -pair;
        };
        for (std::size_t neighbor = 0U;
             neighbor < fluid_count; ++neighbor) {
            if (neighbor != center) {
                accumulate(neighbor, fluid[center] - fluid[neighbor]);
            }
        }
        for (std::size_t support = 0U;
             support < boundary.size(); ++support) {
            accumulate(fluid_count + support,
                fluid[center] - boundary[support]);
        }
    }
    return result;
}

struct ALSparseWorkTrace {
    std::size_t workspace_builds = 0U;
    std::size_t workspace_releases = 0U;
    std::size_t live_workspaces = 0U;
    std::size_t maximum_live_workspaces = 0U;
    std::size_t pair_visits = 0U;
    std::size_t divided_union_visits = 0U;
    std::size_t current_members = 0U;
    std::size_t trial_members = 0U;
    std::size_t all_pair_candidate_calls = 0U;
    bool lifecycle_underflow = false;
};

struct ALSparseStructuralBudget {
    std::size_t maximum_outer_updates = 0U;
    std::size_t maximum_inner_trials_per_update = 0U;
    std::size_t maximum_hvp_per_trust_step = 0U;
    std::size_t maximum_total_hvp = 0U;
    std::size_t maximum_workspace_builds = 0U;
    std::size_t maximum_precision_audits = 0U;
    std::size_t outer_updates = 0U;
    std::size_t inner_trials_in_update = 0U;
    std::size_t hvp_in_trust_step = 0U;
    std::size_t total_hvp = 0U;
    std::size_t workspace_builds = 0U;
    std::size_t precision_audits = 0U;
    bool exhausted = false;
    std::string failure;
};

bool al_sparse_structural_budget_valid(
    const ALSparseStructuralBudget& budget) {
    return budget.maximum_outer_updates > 0U
        && budget.maximum_inner_trials_per_update > 0U
        && budget.maximum_hvp_per_trust_step > 0U
        && budget.maximum_total_hvp > 0U
        && budget.maximum_workspace_builds > 0U
        && budget.maximum_precision_audits > 0U;
}

bool al_sparse_budget_consume(
    std::size_t maximum,
    std::size_t& consumed,
    const char* failure,
    ALSparseStructuralBudget* budget) {
    if (budget == nullptr) {
        return true;
    }
    if (consumed >= maximum) {
        budget->exhausted = true;
        if (budget->failure.empty()) {
            budget->failure = failure;
        }
        return false;
    }
    ++consumed;
    return true;
}

bool al_sparse_budget_begin_outer_update(
    ALSparseStructuralBudget* budget) {
    if (budget == nullptr) return true;
    budget->inner_trials_in_update = 0U;
    return al_sparse_budget_consume(
        budget->maximum_outer_updates, budget->outer_updates,
        "STRUCTURAL_BUDGET_OUTER_UPDATES", budget);
}

bool al_sparse_budget_begin_inner_trial(
    ALSparseStructuralBudget* budget) {
    if (budget == nullptr) return true;
    budget->hvp_in_trust_step = 0U;
    return al_sparse_budget_consume(
        budget->maximum_inner_trials_per_update,
        budget->inner_trials_in_update,
        "STRUCTURAL_BUDGET_INNER_TRIALS", budget);
}

bool al_sparse_budget_consume_hvp(
    ALSparseStructuralBudget* budget) {
    if (budget == nullptr) return true;
    if (!al_sparse_budget_consume(
            budget->maximum_hvp_per_trust_step,
            budget->hvp_in_trust_step,
            "STRUCTURAL_BUDGET_HVP_PER_STEP", budget)) {
        return false;
    }
    if (!al_sparse_budget_consume(
            budget->maximum_total_hvp, budget->total_hvp,
            "STRUCTURAL_BUDGET_TOTAL_HVP", budget)) {
        --budget->hvp_in_trust_step;
        return false;
    }
    return true;
}

bool al_sparse_budget_consume_workspace(
    ALSparseStructuralBudget* budget) {
    if (budget == nullptr) return true;
    return al_sparse_budget_consume(
        budget->maximum_workspace_builds, budget->workspace_builds,
        "STRUCTURAL_BUDGET_WORKSPACES", budget);
}

bool al_sparse_budget_consume_precision_audit(
    ALSparseStructuralBudget* budget) {
    if (budget == nullptr) return true;
    return al_sparse_budget_consume(
        budget->maximum_precision_audits, budget->precision_audits,
        "STRUCTURAL_BUDGET_PRECISION_AUDITS", budget);
}

double al_sparse_multiplier_update(
    double multiplier, double constraint, double kappa) {
    if (!std::isfinite(multiplier) || !std::isfinite(constraint)
        || !std::isfinite(kappa) || kappa <= 0.0) {
        return std::numeric_limits<double>::quiet_NaN();
    }
    return std::max(0.0, multiplier + kappa * constraint);
}

struct ALSparseWorkspace {
    bool passed = false;
    std::string failure;
    JointNeighborhood neighborhood;
    ALVectorSupport support;
    std::vector<double> radius;
    std::vector<double> weight_first;
    std::vector<double> weight_second_value;
    double kappa = 0.0;
    std::size_t payload_bytes = 0U;
};

ALSparseWorkspace build_al_sparse_workspace_from_neighborhood(
    JointNeighborhood neighborhood,
    const std::vector<double>& multiplier,
    ALSparseWorkTrace* work = nullptr,
    double kappa = KAPPA) {
    ALSparseWorkspace result;
    if (!std::isfinite(kappa) || kappa <= 0.0) {
        result.failure = "AL_SCALE_INVALID";
        return result;
    }
    if (work != nullptr) {
        ++work->workspace_builds;
        ++work->live_workspaces;
        work->maximum_live_workspaces = std::max(
            work->maximum_live_workspaces, work->live_workspaces);
    }
    result.neighborhood = std::move(neighborhood);
    result.kappa = kappa;
    if (!result.neighborhood.passed
        || multiplier.size() != result.neighborhood.fluid.size()) {
        result.failure = result.neighborhood.passed
            ? "AL_SPARSE_MULTIPLIER_SIZE"
            : result.neighborhood.failure;
        return result;
    }
    const std::size_t fluid_count = result.neighborhood.fluid.size();
    const std::size_t total_count = fluid_count
        + result.neighborhood.support.size();
    result.support.gradient.resize(total_count);
    result.support.density.assign(fluid_count, MASS * weight(0.0));
    result.radius.resize(result.neighborhood.pairs.size());
    result.weight_first.resize(result.neighborhood.pairs.size());
    result.weight_second_value.resize(result.neighborhood.pairs.size());
    for (std::size_t pair_index = 0U;
         pair_index < result.neighborhood.pairs.size(); ++pair_index) {
        const JointPair pair = result.neighborhood.pairs[pair_index];
        const double radius = norm(
            result.neighborhood.fluid[pair.fluid].position
            - joint_position(result.neighborhood, pair.participant));
        result.radius[pair_index] = radius;
        result.weight_first[pair_index] = weight_gradient(radius);
        result.weight_second_value[pair_index] = weight_second(radius);
        const double contribution = MASS * weight(radius);
        result.support.density[pair.fluid] += contribution;
        if (pair.participant < fluid_count) {
            result.support.density[pair.participant] += contribution;
            ++result.support.fluid_pairs;
        } else {
            ++result.support.boundary_pairs;
        }
        if (work != nullptr) {
            ++work->pair_visits;
        }
    }
    result.support.constraint.resize(fluid_count);
    result.support.active_coefficient.resize(fluid_count);
    for (std::size_t center = 0U; center < fluid_count; ++center) {
        const double constraint =
            result.support.density[center] / REST_DENSITY - 1.0;
        const double active = std::max(
            0.0, multiplier[center] + kappa * constraint);
        result.support.constraint[center] = constraint;
        result.support.active_coefficient[center] = active;
        result.support.energy += (
            active * active - multiplier[center] * multiplier[center])
            / (2.0 * kappa);
        if (active <= 0.0) {
            continue;
        }
        ++result.support.active_centers;
        const double scale = active * MASS / REST_DENSITY;
        const std::size_t begin = result.neighborhood.flat_offsets[center];
        const std::size_t end =
            result.neighborhood.flat_offsets[center + 1U];
        for (std::size_t slot = begin; slot < end; ++slot) {
            const std::size_t pair_index =
                result.neighborhood.flat_directed_pair_indices[slot];
            const std::size_t participant = joint_pair_participant(
                result.neighborhood,
                result.neighborhood.pairs[pair_index], center);
            const Vec3 displacement =
                result.neighborhood.fluid[center].position
                - joint_position(result.neighborhood, participant);
            const double radius = result.radius[pair_index];
            if (radius <= 1.0e-15 || radius > HORIZON) {
                continue;
            }
            const Vec3 pair = scale * result.weight_first[pair_index]
                * (displacement / radius);
            result.support.gradient[center] += pair;
            result.support.gradient[participant] += -pair;
        }
    }
    result.support.finite_values = std::isfinite(result.support.energy)
        && std::all_of(result.support.density.begin(),
            result.support.density.end(),
            [](double value) { return std::isfinite(value); })
        && std::all_of(result.support.constraint.begin(),
            result.support.constraint.end(),
            [](double value) { return std::isfinite(value); })
        && std::all_of(result.support.active_coefficient.begin(),
            result.support.active_coefficient.end(),
            [](double value) { return std::isfinite(value); })
        && std::all_of(result.support.gradient.begin(),
            result.support.gradient.end(),
            [](Vec3 value) { return finite(value); });
    result.payload_bytes = result.neighborhood.pairs.size()
            * sizeof(JointPair)
        + result.neighborhood.flat_offsets.size()
            * sizeof(std::uint32_t)
        + result.neighborhood.flat_directed_pair_indices.size()
            * sizeof(std::uint32_t)
        + (result.radius.size() + result.weight_first.size()
            + result.weight_second_value.size()) * sizeof(double)
        + (result.support.density.size()
            + result.support.constraint.size()
            + result.support.active_coefficient.size()) * sizeof(double)
        + result.support.gradient.size() * sizeof(Vec3);
    result.passed = result.support.finite_values;
    if (!result.passed) {
        result.failure = "AL_SPARSE_NONFINITE";
    }
    return result;
}

ALSparseWorkspace build_al_sparse_workspace(
    const std::vector<Vec3>& fluid,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier,
    ALSparseWorkTrace* work = nullptr,
    double kappa = KAPPA) {
    if (!std::isfinite(kappa) || kappa <= 0.0) {
        ALSparseWorkspace result;
        result.failure = "AL_SCALE_INVALID";
        return result;
    }
    return build_al_sparse_workspace_from_neighborhood(
        build_joint_neighborhood(
            tagged_points(fluid), tagged_points(boundary), true,
            nullptr, true), multiplier, work, kappa);
}

[[maybe_unused]] ALSparseWorkspace
build_al_sparse_workspace_with_static_support(
    const std::vector<Vec3>& fluid,
    const JointStaticSupportBinding& binding,
    const std::vector<double>& multiplier,
    ALSparseWorkTrace* work = nullptr,
    StaticSupportWorkTrace* static_work = nullptr,
    FlatAdjacencyWorkTrace* adjacency_work = nullptr,
    double kappa = KAPPA) {
    if (!std::isfinite(kappa) || kappa <= 0.0) {
        ALSparseWorkspace result;
        result.failure = "AL_SCALE_INVALID";
        return result;
    }
    return build_al_sparse_workspace_from_neighborhood(
        build_joint_neighborhood_with_static_support(
            tagged_points(fluid), &binding, true, static_work, true,
            adjacency_work), multiplier, work, kappa);
}

void release_al_sparse_workspace(
    ALSparseWorkspace& workspace, ALSparseWorkTrace* work) {
    workspace = ALSparseWorkspace{};
    if (work != nullptr) {
        ++work->workspace_releases;
        if (work->live_workspaces == 0U) {
            work->lifecycle_underflow = true;
        } else {
            --work->live_workspaces;
        }
    }
}

std::vector<Vec3> apply_al_sparse_hessian(
    const ALSparseWorkspace& workspace,
    const std::vector<Vec3>& direction) {
    const JointNeighborhood& neighborhood = workspace.neighborhood;
    const std::size_t fluid_count = neighborhood.fluid.size();
    const std::size_t total_count =
        fluid_count + neighborhood.support.size();
    if (!workspace.passed || direction.size() != total_count) {
        throw std::invalid_argument("AL sparse HVP source mismatch");
    }
    std::vector<Vec3> result(total_count);
    for (std::size_t center = 0U; center < fluid_count; ++center) {
        const double active =
            workspace.support.active_coefficient[center];
        if (active <= 0.0) {
            continue;
        }
        double constraint_direction = 0.0;
        const std::size_t begin = neighborhood.flat_offsets[center];
        const std::size_t end = neighborhood.flat_offsets[center + 1U];
        for (std::size_t slot = begin; slot < end; ++slot) {
            const std::size_t pair_index =
                neighborhood.flat_directed_pair_indices[slot];
            const std::size_t participant = joint_pair_participant(
                neighborhood, neighborhood.pairs[pair_index], center);
            const double radius = workspace.radius[pair_index];
            if (radius <= 1.0e-15 || radius > HORIZON) {
                continue;
            }
            const Vec3 displacement = neighborhood.fluid[center].position
                - joint_position(neighborhood, participant);
            const Vec3 jacobian = MASS / REST_DENSITY
                * workspace.weight_first[pair_index]
                * (displacement / radius);
            constraint_direction += dot(
                jacobian, direction[center] - direction[participant]);
        }
        for (std::size_t slot = begin; slot < end; ++slot) {
            const std::size_t pair_index =
                neighborhood.flat_directed_pair_indices[slot];
            const std::size_t participant = joint_pair_participant(
                neighborhood, neighborhood.pairs[pair_index], center);
            const double radius = workspace.radius[pair_index];
            if (radius <= 1.0e-15 || radius > HORIZON) {
                continue;
            }
            const Vec3 displacement = neighborhood.fluid[center].position
                - joint_position(neighborhood, participant);
            const Vec3 normal = displacement / radius;
            const Vec3 jacobian = MASS / REST_DENSITY
                * workspace.weight_first[pair_index] * normal;
            const Vec3 relative =
                direction[center] - direction[participant];
            const Vec3 curvature = MASS / REST_DENSITY
                * radial_hessian_product(normal,
                    workspace.weight_second_value[pair_index],
                    workspace.weight_first[pair_index] / radius,
                    relative);
            const Vec3 pair = workspace.kappa
                    * constraint_direction * jacobian
                + active * curvature;
            result[center] += pair;
            result[participant] += -pair;
        }
    }
    return result;
}

ALVectorInnerState evaluate_al_vector_inner(
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier,
    double time_step = TIME_STEP,
    double kappa = KAPPA) {
    ALVectorInnerState result;
    if (position.size() != predicted.size()
        || !std::isfinite(time_step) || time_step <= 0.0
        || !std::isfinite(kappa) || kappa <= 0.0) {
        return result;
    }
    result.support = evaluate_al_vector_support(
        position, boundary, multiplier, kappa);
    result.total = result.support.energy;
    result.gradient = fluid_part(
        result.support.gradient, position.size());
    const double inertia_scale = MASS / (time_step * time_step);
    for (std::size_t index = 0U; index < position.size(); ++index) {
        const Vec3 displacement = position[index] - predicted[index];
        result.total += 0.5 * inertia_scale * norm_squared(displacement);
        result.gradient[index] += inertia_scale * displacement;
    }
    return result;
}

std::vector<Vec3> apply_al_vector_inner_hessian(
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier,
    const std::vector<Vec3>& direction,
    double time_step = TIME_STEP,
    double kappa = KAPPA) {
    if (!std::isfinite(time_step) || time_step <= 0.0
        || !std::isfinite(kappa) || kappa <= 0.0) {
        throw std::invalid_argument("AL dense HVP time step");
    }
    std::vector<Vec3> joint(direction.size() + boundary.size());
    std::copy(direction.begin(), direction.end(), joint.begin());
    std::vector<Vec3> result = fluid_part(
        apply_al_vector_hessian(
            position, boundary, multiplier, joint, kappa),
        position.size());
    const double inertia_scale = MASS / (time_step * time_step);
    for (std::size_t index = 0U; index < result.size(); ++index) {
        result[index] += inertia_scale * direction[index];
    }
    return result;
}

struct ALSparseInnerState {
    bool passed = false;
    double total = 0.0;
    std::vector<Vec3> gradient;
    ALSparseWorkspace workspace;
};

ALSparseInnerState evaluate_al_sparse_inner(
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier,
    double time_step,
    ALSparseWorkTrace* work,
    double kappa = KAPPA) {
    ALSparseInnerState result;
    if (position.size() != predicted.size()
        || !std::isfinite(time_step) || time_step <= 0.0
        || !std::isfinite(kappa) || kappa <= 0.0) {
        return result;
    }
    result.workspace = build_al_sparse_workspace(
        position, boundary, multiplier, work, kappa);
    if (!result.workspace.passed) {
        return result;
    }
    result.total = result.workspace.support.energy;
    result.gradient = fluid_part(
        result.workspace.support.gradient, position.size());
    const double inertia_scale = MASS / (time_step * time_step);
    for (std::size_t index = 0U; index < position.size(); ++index) {
        const Vec3 displacement = position[index] - predicted[index];
        result.total += 0.5 * inertia_scale * norm_squared(displacement);
        result.gradient[index] += inertia_scale * displacement;
    }
    result.passed = std::isfinite(result.total)
        && std::all_of(result.gradient.begin(), result.gradient.end(),
            [](Vec3 value) { return finite(value); });
    return result;
}

ALSparseInnerState evaluate_al_sparse_inner_with_static_support(
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& predicted,
    const JointStaticSupportBinding& binding,
    const std::vector<double>& multiplier,
    double time_step,
    ALSparseWorkTrace* work,
    StaticSupportWorkTrace* static_work,
    FlatAdjacencyWorkTrace* adjacency_work,
    double kappa = KAPPA) {
    ALSparseInnerState result;
    if (position.size() != predicted.size()
        || !std::isfinite(time_step) || time_step <= 0.0
        || !std::isfinite(kappa) || kappa <= 0.0) {
        return result;
    }
    result.workspace = build_al_sparse_workspace_with_static_support(
        position, binding, multiplier, work, static_work,
        adjacency_work, kappa);
    if (!result.workspace.passed) {
        return result;
    }
    result.total = result.workspace.support.energy;
    result.gradient = fluid_part(
        result.workspace.support.gradient, position.size());
    const double inertia_scale = MASS / (time_step * time_step);
    for (std::size_t index = 0U; index < position.size(); ++index) {
        const Vec3 displacement = position[index] - predicted[index];
        result.total += 0.5 * inertia_scale * norm_squared(displacement);
        result.gradient[index] += inertia_scale * displacement;
    }
    result.passed = std::isfinite(result.total)
        && std::all_of(result.gradient.begin(), result.gradient.end(),
            [](Vec3 value) { return finite(value); });
    return result;
}

std::vector<Vec3> apply_al_sparse_inner_hessian(
    const ALSparseWorkspace& workspace,
    const std::vector<Vec3>& direction,
    double time_step) {
    if (!std::isfinite(time_step) || time_step <= 0.0
        || !std::isfinite(workspace.kappa) || workspace.kappa <= 0.0) {
        throw std::invalid_argument("AL sparse HVP time step");
    }
    std::vector<Vec3> joint(
        direction.size() + workspace.neighborhood.support.size());
    std::copy(direction.begin(), direction.end(), joint.begin());
    std::vector<Vec3> result = fluid_part(
        apply_al_sparse_hessian(workspace, joint), direction.size());
    const double inertia_scale = MASS / (time_step * time_step);
    for (std::size_t index = 0U; index < result.size(); ++index) {
        result[index] += inertia_scale * direction[index];
    }
    return result;
}

std::vector<Vec3> al_sparse_trust_step(
    const ALSparseWorkspace& workspace,
    const std::vector<Vec3>& gradient,
    double radius,
    double time_step,
    int& hvp_calls,
    bool& negative_curvature,
    ALSparseStructuralBudget* structural_budget = nullptr) {
    std::vector<Vec3> point(gradient.size());
    std::vector<Vec3> residual = gradient;
    std::vector<Vec3> direction = gradient;
    for (Vec3& value : direction) value = -value;
    double residual_squared = flat_dot(residual, residual);
    const double initial_residual = std::sqrt(residual_squared);
    for (std::size_t iteration = 0U;
         iteration < 3U * gradient.size(); ++iteration) {
        if (!al_sparse_budget_consume_hvp(structural_budget)) {
            return {};
        }
        const std::vector<Vec3> image =
            apply_al_sparse_inner_hessian(
                workspace, direction, time_step);
        ++hvp_calls;
        const double curvature = flat_dot(direction, image);
        if (!std::isfinite(curvature) || curvature <= 0.0) {
            negative_curvature = true;
            return add_scaled(point, direction,
                trust_boundary_tau(point, direction, radius));
        }
        const double alpha = residual_squared / curvature;
        const std::vector<Vec3> candidate =
            add_scaled(point, direction, alpha);
        if (vector_norm(candidate) >= radius) {
            return add_scaled(point, direction,
                trust_boundary_tau(point, direction, radius));
        }
        point = candidate;
        std::vector<Vec3> next_residual = residual;
        for (std::size_t index = 0U;
             index < next_residual.size(); ++index) {
            next_residual[index] += alpha * image[index];
        }
        const double next_squared = flat_dot(next_residual, next_residual);
        if (std::sqrt(next_squared)
            <= std::min(0.5, std::sqrt(initial_residual))
                * initial_residual) {
            return point;
        }
        const double beta = next_squared / residual_squared;
        for (std::size_t index = 0U;
             index < direction.size(); ++index) {
            direction[index] = -next_residual[index]
                + beta * direction[index];
        }
        residual = std::move(next_residual);
        residual_squared = next_squared;
    }
    return point;
}

std::vector<Vec3> al_vector_trust_step(
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier,
    const std::vector<Vec3>& gradient,
    double radius,
    int& hvp_calls,
    bool& negative_curvature) {
    std::vector<Vec3> point(gradient.size());
    std::vector<Vec3> residual = gradient;
    std::vector<Vec3> direction = gradient;
    for (Vec3& value : direction) value = -value;
    double residual_squared = flat_dot(residual, residual);
    const double initial_residual = std::sqrt(residual_squared);
    for (std::size_t iteration = 0U;
         iteration < 3U * gradient.size(); ++iteration) {
        const std::vector<Vec3> image = apply_al_vector_inner_hessian(
            position, boundary, multiplier, direction);
        ++hvp_calls;
        const double curvature = flat_dot(direction, image);
        if (!std::isfinite(curvature) || curvature <= 0.0) {
            negative_curvature = true;
            return add_scaled(point, direction,
                trust_boundary_tau(point, direction, radius));
        }
        const double alpha = residual_squared / curvature;
        const std::vector<Vec3> candidate =
            add_scaled(point, direction, alpha);
        if (vector_norm(candidate) >= radius) {
            return add_scaled(point, direction,
                trust_boundary_tau(point, direction, radius));
        }
        point = candidate;
        std::vector<Vec3> next_residual = residual;
        for (std::size_t index = 0U;
             index < next_residual.size(); ++index) {
            next_residual[index] += alpha * image[index];
        }
        const double next_squared = flat_dot(
            next_residual, next_residual);
        if (std::sqrt(next_squared)
            <= std::min(0.5, std::sqrt(initial_residual))
                * initial_residual) {
            return point;
        }
        const double beta = next_squared / residual_squared;
        for (std::size_t index = 0U;
             index < direction.size(); ++index) {
            direction[index] = -next_residual[index]
                + beta * direction[index];
        }
        residual = std::move(next_residual);
        residual_squared = next_squared;
    }
    return point;
}

double al_vector_scaled_stationarity(
    const std::vector<Vec3>& gradient,
    double time_step = TIME_STEP) {
    if (!std::isfinite(time_step) || time_step <= 0.0) {
        return std::numeric_limits<double>::infinity();
    }
    double maximum = 0.0;
    for (Vec3 value : gradient) {
        maximum = std::max(maximum, norm(value));
    }
    return time_step * time_step / MASS * maximum / SPACING;
}

double al_sparse_scaled_stationarity(
    const std::vector<Vec3>& gradient, double time_step) {
    if (!std::isfinite(time_step) || time_step <= 0.0) {
        return std::numeric_limits<double>::infinity();
    }
    double maximum = 0.0;
    for (Vec3 value : gradient) {
        maximum = std::max(maximum, norm(value));
    }
    return time_step * time_step / MASS * maximum / SPACING;
}

ALVectorInnerSolve solve_al_vector_inner(
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& initial,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier) {
    ALVectorInnerSolve result;
    result.position = initial;
    ALVectorInnerState current = evaluate_al_vector_inner(
        result.position, predicted, boundary, multiplier);
    if (!current.support.finite_values) {
        result.failure = "INITIAL_NONFINITE";
        return result;
    }
    double trust_radius = 0.25 * SPACING;
    for (int outer = 0; outer < 64; ++outer) {
        result.outer_trials = outer + 1;
        result.final_scaled_stationarity =
            al_vector_scaled_stationarity(current.gradient);
        if (result.final_scaled_stationarity <= 1.0e-8) {
            result.passed = true;
            result.support = std::move(current.support);
            return result;
        }
        bool negative_curvature = false;
        const std::vector<Vec3> step = al_vector_trust_step(
            result.position, boundary, multiplier, current.gradient,
            trust_radius, result.hvp_calls, negative_curvature);
        if (negative_curvature) ++result.negative_curvature_exits;
        const std::vector<Vec3> image = apply_al_vector_inner_hessian(
            result.position, boundary, multiplier, step);
        ++result.hvp_calls;
        const double predicted_reduction =
            -flat_dot(current.gradient, step)
            - 0.5 * flat_dot(step, image);
        const std::vector<Vec3> trial_position = add_scaled(
            result.position, step, 1.0);
        ALVectorInnerState trial = evaluate_al_vector_inner(
            trial_position, predicted, boundary, multiplier);
        const double actual_reduction = current.total - trial.total;
        const double ratio = predicted_reduction > 0.0
            ? actual_reduction / predicted_reduction
            : -std::numeric_limits<double>::infinity();
        if (ratio < 0.25) {
            trust_radius *= 0.25;
        } else if (ratio > 0.75
            && vector_norm(step) >= 0.9 * trust_radius) {
            trust_radius = std::min(
                2.0 * trust_radius, 2.0 * SPACING);
        }
        if (trial.support.finite_values
            && predicted_reduction > 0.0
            && actual_reduction > 0.0 && ratio >= 0.1) {
            ++result.accepted_trials;
            result.minimum_accepted_ratio = std::min(
                result.minimum_accepted_ratio, ratio);
            result.positive_accepted_models =
                result.positive_accepted_models
                && predicted_reduction > 0.0 && actual_reduction > 0.0;
            result.position = trial_position;
            current = std::move(trial);
        } else {
            ++result.rejected_trials;
            if (result.rejected_trials > 8) {
                result.failure = "REJECT_LIMIT";
                return result;
            }
        }
        if (trust_radius < 1.0e-14) {
            result.failure = "MINIMUM_TRUST_RADIUS";
            return result;
        }
    }
    result.failure = "OUTER_LIMIT";
    return result;
}

ALVectorOuterSolve solve_al_vector_outer(
    const Fixture& fixture,
    const std::vector<Vec3>& predicted,
    std::vector<Vec3> position,
    std::vector<double> multiplier,
    int maximum_outer) {
    ALVectorOuterSolve result;
    result.position = position;
    result.multiplier = multiplier;
    double previous_primal = std::numeric_limits<double>::infinity();
    for (int outer = 0; outer < maximum_outer; ++outer) {
        const ALVectorInnerSolve inner = solve_al_vector_inner(
            predicted, position, fixture.boundary, multiplier);
        if (!inner.passed || !inner.positive_accepted_models) {
            result.inner_exact = false;
            result.failure = "INNER:" + inner.failure;
            return result;
        }
        std::vector<double> next(multiplier.size());
        ALVectorOuterRecord record;
        record.outer = outer;
        record.inner_outer_trials = inner.outer_trials;
        record.inner_accepted_trials = inner.accepted_trials;
        record.inner_rejected_trials = inner.rejected_trials;
        record.inner_hvp_calls = inner.hvp_calls;
        record.minimum_multiplier = std::numeric_limits<double>::infinity();
        for (std::size_t center = 0U;
             center < multiplier.size(); ++center) {
            next[center] = std::max(0.0,
                multiplier[center]
                    + KAPPA * inner.support.constraint[center]);
            record.primal = std::max(record.primal,
                std::max(0.0, inner.support.constraint[center]));
            record.scaled_dual_change = std::max(
                record.scaled_dual_change,
                std::abs(next[center] - multiplier[center]) / KAPPA);
            record.complementarity = std::max(record.complementarity,
                std::abs(next[center] * inner.support.constraint[center]));
            record.minimum_multiplier = std::min(
                record.minimum_multiplier, next[center]);
            record.maximum_multiplier = std::max(
                record.maximum_multiplier, next[center]);
        }
        record.stationarity = inner.final_scaled_stationarity;
        result.primal_monotone = result.primal_monotone
            && record.primal <= previous_primal;
        previous_primal = record.primal;
        result.records.push_back(record);
        result.position = inner.position;
        result.multiplier = next;
        result.support = inner.support;
        position = inner.position;
        multiplier = std::move(next);
        if (record.primal <= 1.0e-8
            && record.scaled_dual_change <= 1.0e-8
            && record.stationarity <= 1.0e-8
            && record.complementarity <= 1.0e-9
            && record.minimum_multiplier >= 0.0) {
            result.passed = true;
            return result;
        }
    }
    result.cap_exhausted = result.inner_exact && result.primal_monotone;
    result.failure = "OUTER_ITERATION_LIMIT";
    return result;
}

ALVectorStableSolve solve_al_vector_stable(
    const Fixture& fixture,
    const std::vector<Vec3>& predicted,
    std::vector<Vec3> position,
    std::vector<double> multiplier) {
    constexpr int maximum_outer = 14;
    constexpr double absolute_dual_limit = 1.0e-8;
    constexpr double equivalent_pressure_limit = 8.0e-5;
    constexpr double position_update_limit = 1.0e-8;
    ALVectorStableSolve result;
    result.position = position;
    result.multiplier = multiplier;
    double previous_primal = std::numeric_limits<double>::infinity();
    bool previous_admissible = false;
    for (int outer = 0; outer < maximum_outer; ++outer) {
        const ALVectorInnerSolve inner = solve_al_vector_inner(
            predicted, position, fixture.boundary, multiplier);
        if (!inner.passed || !inner.positive_accepted_models) {
            result.inner_exact = false;
            result.failure = "INNER:" + inner.failure;
            return result;
        }
        std::vector<double> next(multiplier.size());
        ALVectorOuterRecord record;
        record.outer = outer;
        record.inner_outer_trials = inner.outer_trials;
        record.inner_accepted_trials = inner.accepted_trials;
        record.inner_rejected_trials = inner.rejected_trials;
        record.inner_hvp_calls = inner.hvp_calls;
        record.minimum_multiplier = std::numeric_limits<double>::infinity();
        record.position_update_dx =
            rms_difference(position, inner.position) / SPACING;
        for (std::size_t center = 0U;
             center < multiplier.size(); ++center) {
            next[center] = std::max(0.0,
                multiplier[center]
                    + KAPPA * inner.support.constraint[center]);
            const double absolute_change =
                std::abs(next[center] - multiplier[center]);
            record.primal = std::max(record.primal,
                std::max(0.0, inner.support.constraint[center]));
            record.scaled_dual_change = std::max(
                record.scaled_dual_change, absolute_change / KAPPA);
            record.absolute_dual_change = std::max(
                record.absolute_dual_change, absolute_change);
            record.equivalent_pressure_change = std::max(
                record.equivalent_pressure_change,
                absolute_change * REST_DENSITY / MASS);
            record.complementarity = std::max(record.complementarity,
                std::abs(next[center] * inner.support.constraint[center]));
            record.minimum_multiplier = std::min(
                record.minimum_multiplier, next[center]);
            record.maximum_multiplier = std::max(
                record.maximum_multiplier, next[center]);
        }
        record.stationarity = inner.final_scaled_stationarity;
        result.primal_monotone = result.primal_monotone
            && record.primal <= previous_primal;
        previous_primal = record.primal;
        result.records.push_back(record);
        result.position = inner.position;
        result.multiplier = next;
        result.support = inner.support;
        position = inner.position;
        multiplier = std::move(next);
        if (outer == 7) {
            result.prefix_position = result.position;
            result.prefix_multiplier = result.multiplier;
        }
        const bool admissible = record.primal <= 1.0e-8
            && record.stationarity <= 1.0e-8
            && record.complementarity <= 1.0e-9
            && record.minimum_multiplier >= 0.0
            && record.absolute_dual_change <= absolute_dual_limit
            && record.equivalent_pressure_change
                <= equivalent_pressure_limit
            && record.position_update_dx <= position_update_limit;
        if (admissible && previous_admissible
            && result.provisional_index == outer - 1) {
            result.confirmation_index = outer;
            result.passed = true;
            return result;
        }
        if (admissible) {
            result.provisional_index = outer;
            result.provisional_position = result.position;
            result.provisional_multiplier = result.multiplier;
        } else {
            result.provisional_index = -1;
            result.provisional_position.clear();
            result.provisional_multiplier.clear();
        }
        previous_admissible = admissible;
    }
    result.cap_exhausted = result.inner_exact && result.primal_monotone;
    result.failure = "OUTER_ITERATION_LIMIT";
    return result;
}

std::string al_vector_legacy_outer_json(
    const std::vector<ALVectorOuterRecord>& records,
    std::size_t count) {
    std::ostringstream output;
    output << '[';
    const std::size_t limit = std::min(count, records.size());
    for (std::size_t index = 0U; index < limit; ++index) {
        if (index != 0U) output << ',';
        const ALVectorOuterRecord& record = records[index];
        output << std::setprecision(17)
               << "{\"outer\":" << record.outer
               << ",\"inner_outer_trials\":"
               << record.inner_outer_trials
               << ",\"inner_accepted_trials\":"
               << record.inner_accepted_trials
               << ",\"inner_rejected_trials\":"
               << record.inner_rejected_trials
               << ",\"inner_hvp_calls\":" << record.inner_hvp_calls
               << ",\"primal\":" << record.primal
               << ",\"scaled_dual_change\":"
               << record.scaled_dual_change
               << ",\"stationarity\":" << record.stationarity
               << ",\"complementarity\":"
               << record.complementarity
               << ",\"multiplier_range\":["
               << record.minimum_multiplier << ','
               << record.maximum_multiplier << "]}";
    }
    output << ']';
    return output.str();
}

std::string al_vector_state_root(
    const std::string& tag,
    const std::vector<Vec3>& position,
    const std::vector<double>& multiplier) {
    std::ostringstream material;
    material << "nextengine.nonlocal.nsr3b4e2d7-state|v1|" << tag << '|'
             << position.size() << ':' << multiplier.size();
    for (Vec3 value : position) {
        material << ':' << binary64_bits(value.x)
                 << ':' << binary64_bits(value.y)
                 << ':' << binary64_bits(value.z);
    }
    for (double value : multiplier) {
        material << ':' << binary64_bits(value);
    }
    return sha256_hex(material.str());
}

std::string al_vector_stable_state_root(
    const std::string& tag,
    const std::vector<Vec3>& position,
    const std::vector<double>& multiplier) {
    std::ostringstream material;
    material << "nextengine.nonlocal.nsr3b4e2d7r-state|v1|" << tag << '|'
             << position.size() << ':' << multiplier.size();
    for (Vec3 value : position) {
        material << ':' << binary64_bits(value.x)
                 << ':' << binary64_bits(value.y)
                 << ':' << binary64_bits(value.z);
    }
    for (double value : multiplier) {
        material << ':' << binary64_bits(value);
    }
    return sha256_hex(material.str());
}

struct ALVectorInnerFloorTrial {
    int trial = 0;
    int hvp_calls = 0;
    bool negative_curvature = false;
    bool finite_values = false;
    bool topology_exact = false;
    bool model_positive = false;
    bool direct_descent = false;
    bool would_accept = false;
    double trust_radius_before = 0.0;
    double trust_radius_after = 0.0;
    double step_norm_dx = 0.0;
    double predicted_reduction = 0.0;
    double raw_actual_reduction = 0.0;
    double direct_actual_reduction = 0.0;
    double raw_ratio = 0.0;
    double current_energy_ulp = 0.0;
    double predicted_ulp_ratio = 0.0;
};

struct ALVectorInnerFloorTrace {
    bool passed = false;
    bool all_topology_exact = true;
    bool all_model_positive = true;
    bool all_direct_descent = true;
    bool all_raw_hidden = true;
    bool all_raw_admit = true;
    int accepted_trials = 0;
    int rejected_trials = 0;
    double initial_total = 0.0;
    double initial_support = 0.0;
    double initial_inertia = 0.0;
    double initial_gradient_norm = 0.0;
    double initial_stationarity = 0.0;
    double minimum_constraint = std::numeric_limits<double>::infinity();
    double maximum_constraint = -std::numeric_limits<double>::infinity();
    double minimum_multiplier = std::numeric_limits<double>::infinity();
    double maximum_multiplier = -std::numeric_limits<double>::infinity();
    std::vector<ALVectorInnerFloorTrial> trials;
};

double al_vector_direct_actual_reduction_dt(
    const std::vector<Vec3>& current_position,
    const std::vector<Vec3>& trial_position,
    const std::vector<Vec3>& predicted,
    const ALVectorSupport& current_support,
    const ALVectorSupport& trial_support,
    double time_step,
    double kappa = KAPPA) {
    if (current_position.size() != trial_position.size()
        || current_position.size() != predicted.size()
        || current_support.active_coefficient.size()
            != trial_support.active_coefficient.size()
        || !std::isfinite(time_step) || time_step <= 0.0
        || !std::isfinite(kappa) || kappa <= 0.0) {
        return std::numeric_limits<double>::quiet_NaN();
    }
    double delta = 0.0;
    const double inertia_scale = MASS / (2.0 * time_step * time_step);
    for (std::size_t index = 0U;
         index < current_position.size(); ++index) {
        const Vec3 step = trial_position[index] - current_position[index];
        const Vec3 sum = trial_position[index] + current_position[index]
            - 2.0 * predicted[index];
        delta += inertia_scale * dot(step, sum);
    }
    for (std::size_t center = 0U;
         center < current_support.active_coefficient.size(); ++center) {
        const double current =
            current_support.active_coefficient[center];
        const double trial = trial_support.active_coefficient[center];
        delta += (trial - current) * (trial + current) / (2.0 * kappa);
    }
    return -delta;
}

double al_vector_direct_actual_reduction(
    const std::vector<Vec3>& current_position,
    const std::vector<Vec3>& trial_position,
    const std::vector<Vec3>& predicted,
    const ALVectorSupport& current_support,
    const ALVectorSupport& trial_support) {
    return al_vector_direct_actual_reduction_dt(
        current_position, trial_position, predicted,
        current_support, trial_support, TIME_STEP);
}

ALVectorInnerFloorTrace trace_al_vector_inner_floor(
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier) {
    ALVectorInnerFloorTrace result;
    const ALVectorInnerState current = evaluate_al_vector_inner(
        position, predicted, boundary, multiplier);
    result.initial_total = current.total;
    result.initial_support = current.support.energy;
    result.initial_inertia = current.total - current.support.energy;
    result.initial_gradient_norm = vector_norm(current.gradient);
    result.initial_stationarity =
        al_vector_scaled_stationarity(current.gradient);
    for (double constraint : current.support.constraint) {
        result.minimum_constraint = std::min(
            result.minimum_constraint, constraint);
        result.maximum_constraint = std::max(
            result.maximum_constraint, constraint);
    }
    for (double value : multiplier) {
        result.minimum_multiplier = std::min(
            result.minimum_multiplier, value);
        result.maximum_multiplier = std::max(
            result.maximum_multiplier, value);
    }
    double trust_radius = 0.25 * SPACING;
    for (int trial_index = 0; trial_index < 9; ++trial_index) {
        ALVectorInnerFloorTrial record;
        record.trial = trial_index;
        record.trust_radius_before = trust_radius;
        int hvp_calls = 0;
        bool negative_curvature = false;
        const std::vector<Vec3> step = al_vector_trust_step(
            position, boundary, multiplier, current.gradient,
            trust_radius, hvp_calls, negative_curvature);
        const std::vector<Vec3> image = apply_al_vector_inner_hessian(
            position, boundary, multiplier, step);
        ++hvp_calls;
        const std::vector<Vec3> trial_position = add_scaled(
            position, step, 1.0);
        const ALVectorInnerState trial = evaluate_al_vector_inner(
            trial_position, predicted, boundary, multiplier);
        record.hvp_calls = hvp_calls;
        record.negative_curvature = negative_curvature;
        record.step_norm_dx = vector_norm(step) / SPACING;
        record.predicted_reduction = -flat_dot(current.gradient, step)
            - 0.5 * flat_dot(step, image);
        record.raw_actual_reduction = current.total - trial.total;
        record.direct_actual_reduction =
            al_vector_direct_actual_reduction(
                position, trial_position, predicted,
                current.support, trial.support);
        record.raw_ratio = record.predicted_reduction > 0.0
            ? record.raw_actual_reduction / record.predicted_reduction
            : -std::numeric_limits<double>::infinity();
        record.current_energy_ulp = std::nextafter(
                current.total, std::numeric_limits<double>::infinity())
            - current.total;
        record.predicted_ulp_ratio = record.current_energy_ulp > 0.0
            ? record.predicted_reduction / record.current_energy_ulp
            : std::numeric_limits<double>::infinity();
        record.topology_exact = current.support.active_centers
                == trial.support.active_centers
            && current.support.fluid_pairs == trial.support.fluid_pairs
            && current.support.boundary_pairs == trial.support.boundary_pairs;
        record.model_positive = record.predicted_reduction > 0.0;
        record.direct_descent = record.direct_actual_reduction > 0.0;
        record.finite_values = trial.support.finite_values
            && std::isfinite(record.step_norm_dx)
            && std::isfinite(record.predicted_reduction)
            && std::isfinite(record.raw_actual_reduction)
            && std::isfinite(record.direct_actual_reduction)
            && std::isfinite(record.raw_ratio)
            && std::isfinite(record.current_energy_ulp)
            && std::isfinite(record.predicted_ulp_ratio);
        record.would_accept = trial.support.finite_values
            && record.predicted_reduction > 0.0
            && record.raw_actual_reduction > 0.0
            && record.raw_ratio >= 0.1;
        result.all_topology_exact = result.all_topology_exact
            && record.topology_exact;
        result.all_model_positive = result.all_model_positive
            && record.model_positive;
        result.all_direct_descent = result.all_direct_descent
            && record.direct_descent;
        result.all_raw_hidden = result.all_raw_hidden
            && !record.would_accept
            && (record.raw_actual_reduction <= 0.0
                || record.raw_ratio < 0.1);
        result.all_raw_admit = result.all_raw_admit
            && record.would_accept
            && (record.raw_actual_reduction > 0.0)
                == (record.direct_actual_reduction > 0.0);
        if (record.raw_ratio < 0.25) {
            trust_radius *= 0.25;
        } else if (record.raw_ratio > 0.75
            && vector_norm(step) >= 0.9 * trust_radius) {
            trust_radius = std::min(
                2.0 * trust_radius, 2.0 * SPACING);
        }
        record.trust_radius_after = trust_radius;
        if (record.would_accept) {
            ++result.accepted_trials;
        } else {
            ++result.rejected_trials;
        }
        result.trials.push_back(record);
    }
    result.passed = current.support.finite_values
        && result.initial_stationarity > 1.0e-8
        && result.trials.size() == 9U
        && result.accepted_trials == 0
        && result.rejected_trials == 9
        && std::all_of(result.trials.begin(), result.trials.end(),
            [](const ALVectorInnerFloorTrial& trial) {
                return trial.finite_values;
            });
    return result;
}

struct ALTopologyPair {
    char kind = 'F';
    std::size_t center = 0U;
    std::size_t participant = 0U;
};

bool operator<(const ALTopologyPair& lhs, const ALTopologyPair& rhs) {
    if (lhs.kind != rhs.kind) return lhs.kind < rhs.kind;
    if (lhs.center != rhs.center) return lhs.center < rhs.center;
    return lhs.participant < rhs.participant;
}

struct ALTopologySets {
    std::vector<std::size_t> active;
    std::vector<ALTopologyPair> fluid;
    std::vector<ALTopologyPair> boundary;
    std::string active_root;
    std::string fluid_root;
    std::string boundary_root;
};

std::string al_active_set_root(const std::vector<std::size_t>& values) {
    std::ostringstream material;
    material << "nextengine.nonlocal.nsr3b4e2d7r2-active-set|v1|"
             << values.size();
    for (std::size_t value : values) material << ':' << value;
    return sha256_hex(material.str());
}

std::string al_pair_set_root(
    const char* tag, const std::vector<ALTopologyPair>& values) {
    std::ostringstream material;
    material << "nextengine.nonlocal.nsr3b4e2d7r2-pair-set|v1|"
             << tag << '|' << values.size();
    for (const ALTopologyPair& value : values) {
        material << ':' << value.kind << ':' << value.center
                 << ':' << value.participant;
    }
    return sha256_hex(material.str());
}

ALTopologySets al_topology_sets(
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& boundary,
    const ALVectorSupport& support) {
    ALTopologySets result;
    for (std::size_t center = 0U;
         center < support.active_coefficient.size(); ++center) {
        if (support.active_coefficient[center] > 0.0) {
            result.active.push_back(center);
        }
    }
    for (std::size_t i = 0U; i < position.size(); ++i) {
        for (std::size_t j = i + 1U; j < position.size(); ++j) {
            if (norm(position[i] - position[j]) <= HORIZON) {
                result.fluid.push_back({'F', i, j});
            }
        }
        for (std::size_t support_index = 0U;
             support_index < boundary.size(); ++support_index) {
            if (norm(position[i] - boundary[support_index]) <= HORIZON) {
                result.boundary.push_back({'B', i, support_index});
            }
        }
    }
    result.active_root = al_active_set_root(result.active);
    result.fluid_root = al_pair_set_root("fluid", result.fluid);
    result.boundary_root = al_pair_set_root("boundary", result.boundary);
    return result;
}

template <typename Value>
std::vector<Value> sorted_difference(
    const std::vector<Value>& lhs, const std::vector<Value>& rhs) {
    std::vector<Value> result;
    std::set_difference(lhs.begin(), lhs.end(), rhs.begin(), rhs.end(),
        std::back_inserter(result));
    return result;
}

double al_current_radial_branch_weight(
    double current_radius, double trial_radius) {
    if (current_radius > HORIZON) return 0.0;
    const double q = 2.0 * trial_radius / HORIZON;
    const double alpha =
        3.0 / (2.0 * PI * HORIZON * HORIZON * HORIZON);
    double raw = 0.0;
    if (2.0 * current_radius / HORIZON >= 1.0) {
        const double delta = 2.0 - q;
        raw = alpha * delta * delta * delta / 6.0;
    } else {
        raw = alpha * (2.0 / 3.0 - q * q + 0.5 * q * q * q);
    }
    return kernel_scale() * raw;
}

ALVectorSupport evaluate_al_vector_current_branch_support(
    const std::vector<Vec3>& current_position,
    const std::vector<Vec3>& trial_position,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier,
    const ALVectorSupport& current_support) {
    ALVectorSupport result;
    const std::size_t fluid_count = current_position.size();
    if (trial_position.size() != fluid_count
        || multiplier.size() != fluid_count
        || current_support.active_coefficient.size() != fluid_count) {
        return result;
    }
    result.density.assign(fluid_count, MASS * weight(0.0));
    for (std::size_t i = 0U; i < fluid_count; ++i) {
        for (std::size_t j = i + 1U; j < fluid_count; ++j) {
            const double current_radius = norm(
                current_position[i] - current_position[j]);
            const double trial_radius = norm(
                trial_position[i] - trial_position[j]);
            const double contribution = MASS
                * al_current_radial_branch_weight(
                    current_radius, trial_radius);
            result.density[i] += contribution;
            result.density[j] += contribution;
        }
        for (std::size_t support_index = 0U;
             support_index < boundary.size(); ++support_index) {
            const double current_radius = norm(
                current_position[i] - boundary[support_index]);
            const double trial_radius = norm(
                trial_position[i] - boundary[support_index]);
            result.density[i] += MASS
                * al_current_radial_branch_weight(
                    current_radius, trial_radius);
        }
    }
    result.constraint.resize(fluid_count);
    result.active_coefficient.resize(fluid_count);
    for (std::size_t center = 0U; center < fluid_count; ++center) {
        result.constraint[center] =
            result.density[center] / REST_DENSITY - 1.0;
        const double shifted = multiplier[center]
            + KAPPA * result.constraint[center];
        const bool current_active =
            current_support.active_coefficient[center] > 0.0;
        const double active = current_active ? shifted : 0.0;
        result.active_coefficient[center] = active;
        result.energy += (
            active * active - multiplier[center] * multiplier[center])
            / (2.0 * KAPPA);
        if (current_active) ++result.active_centers;
    }
    result.finite_values = std::isfinite(result.energy)
        && std::all_of(result.density.begin(), result.density.end(),
            [](double value) { return std::isfinite(value); })
        && std::all_of(result.constraint.begin(), result.constraint.end(),
            [](double value) { return std::isfinite(value); })
        && std::all_of(result.active_coefficient.begin(),
            result.active_coefficient.end(),
            [](double value) { return std::isfinite(value); });
    return result;
}

struct ALTopologyPairDetail {
    ALTopologyPair pair;
    bool added = false;
    double current_radius = 0.0;
    double trial_radius = 0.0;
    double current_margin = 0.0;
    double trial_margin = 0.0;
    double current_margin_epsilon = 0.0;
    double trial_margin_epsilon = 0.0;
    double current_weight = 0.0;
    double trial_weight = 0.0;
    double current_first = 0.0;
    double trial_first = 0.0;
    double current_second = 0.0;
    double trial_second = 0.0;
};

double al_topology_pair_radius(
    const ALTopologyPair& pair,
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& boundary) {
    const Vec3 participant = pair.kind == 'F'
        ? position[pair.participant] : boundary[pair.participant];
    return norm(position[pair.center] - participant);
}

ALTopologyPairDetail al_topology_pair_detail(
    const ALTopologyPair& pair,
    bool added,
    const std::vector<Vec3>& current_position,
    const std::vector<Vec3>& trial_position,
    const std::vector<Vec3>& boundary) {
    ALTopologyPairDetail result;
    result.pair = pair;
    result.added = added;
    result.current_radius = al_topology_pair_radius(
        pair, current_position, boundary);
    result.trial_radius = al_topology_pair_radius(
        pair, trial_position, boundary);
    result.current_margin = HORIZON - result.current_radius;
    result.trial_margin = HORIZON - result.trial_radius;
    const double epsilon_h =
        std::numeric_limits<double>::epsilon() * HORIZON;
    result.current_margin_epsilon = result.current_margin / epsilon_h;
    result.trial_margin_epsilon = result.trial_margin / epsilon_h;
    result.current_weight = weight(result.current_radius);
    result.trial_weight = weight(result.trial_radius);
    result.current_first = weight_gradient(result.current_radius);
    result.trial_first = weight_gradient(result.trial_radius);
    result.current_second = weight_second(result.current_radius);
    result.trial_second = weight_second(result.trial_radius);
    return result;
}

bool finite_al_topology_pair_detail(const ALTopologyPairDetail& value) {
    return std::isfinite(value.current_radius)
        && std::isfinite(value.trial_radius)
        && std::isfinite(value.current_margin)
        && std::isfinite(value.trial_margin)
        && std::isfinite(value.current_margin_epsilon)
        && std::isfinite(value.trial_margin_epsilon)
        && std::isfinite(value.current_weight)
        && std::isfinite(value.trial_weight)
        && std::isfinite(value.current_first)
        && std::isfinite(value.trial_first)
        && std::isfinite(value.current_second)
        && std::isfinite(value.trial_second);
}

struct ALTopologyAlphaRow {
    int exponent = 0;
    double alpha = 0.0;
    bool coordinate_moved = false;
    bool finite_values = false;
    double rounded_step_norm_m = 0.0;
    double rounded_step_norm_dx = 0.0;
    double predicted_reduction = 0.0;
    double raw_actual_reduction = 0.0;
    double direct_actual_reduction = 0.0;
    double direct_ratio = 0.0;
    double branch_actual_reduction = 0.0;
    double branch_ratio = 0.0;
    ALTopologySets topology;
    std::size_t active_added = 0U;
    std::size_t active_removed = 0U;
    std::size_t fluid_added = 0U;
    std::size_t fluid_removed = 0U;
    std::size_t boundary_added = 0U;
    std::size_t boundary_removed = 0U;
};

struct ALTopologyStepTrace {
    bool passed = false;
    bool full_reproduction_exact = false;
    bool kernel_horizon_exact = false;
    bool kernel_horizon_numerical_zero = false;
    bool set_accounting_exact = false;
    bool all_finite = true;
    bool ladder_exact = false;
    bool any_coordinate_moved = false;
    bool directional_descent = false;
    bool rollback_exact = false;
    int hvp_calls = 0;
    bool negative_curvature = false;
    int binding_shrinks = 0;
    int missing_shrinks_after_cap = 0;
    double step_norm_m = 0.0;
    double step_norm_dx = 0.0;
    double directional_reduction = 0.0;
    ALTopologySets current_topology;
    std::vector<std::size_t> active_added;
    std::vector<std::size_t> active_removed;
    std::vector<ALTopologyPair> fluid_added;
    std::vector<ALTopologyPair> fluid_removed;
    std::vector<ALTopologyPair> boundary_added;
    std::vector<ALTopologyPair> boundary_removed;
    std::vector<ALTopologyPairDetail> changed_pairs;
    std::vector<ALTopologyAlphaRow> rows;
    std::string candidate_route;
    std::string selected_route;
};

ALTopologyStepTrace trace_al_topology_step(
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier) {
    ALTopologyStepTrace result;
    const ALVectorInnerState current = evaluate_al_vector_inner(
        position, predicted, boundary, multiplier);
    result.current_topology = al_topology_sets(
        position, boundary, current.support);
    int trust_hvp_calls = 0;
    const std::vector<Vec3> step = al_vector_trust_step(
        position, boundary, multiplier, current.gradient,
        0.25 * SPACING, trust_hvp_calls, result.negative_curvature);
    const std::vector<Vec3> image = apply_al_vector_inner_hessian(
        position, boundary, multiplier, step);
    result.hvp_calls = trust_hvp_calls + 1;
    result.step_norm_m = vector_norm(step);
    result.step_norm_dx = result.step_norm_m / SPACING;
    const double gradient_step = flat_dot(current.gradient, step);
    const double step_image = flat_dot(step, image);
    result.directional_reduction = -gradient_step;
    result.directional_descent = result.directional_reduction > 0.0;
    double binding_radius = 0.25 * SPACING;
    while (binding_radius > result.step_norm_m
        && result.binding_shrinks < 128) {
        binding_radius *= 0.25;
        ++result.binding_shrinks;
    }
    result.missing_shrinks_after_cap = std::max(
        0, result.binding_shrinks - 9);

    for (int exponent = 0; exponent <= 20; ++exponent) {
        ALTopologyAlphaRow row;
        row.exponent = exponent;
        row.alpha = std::ldexp(1.0, -exponent);
        const std::vector<Vec3> trial_position = add_scaled(
            position, step, row.alpha);
        row.coordinate_moved = !exact_vec3_values(
            trial_position, position);
        row.rounded_step_norm_m = vector_difference_norm(
            trial_position, position);
        row.rounded_step_norm_dx = row.rounded_step_norm_m / SPACING;
        const ALVectorInnerState trial = evaluate_al_vector_inner(
            trial_position, predicted, boundary, multiplier);
        const ALVectorSupport branch =
            evaluate_al_vector_current_branch_support(
                position, trial_position, boundary, multiplier,
                current.support);
        row.topology = al_topology_sets(
            trial_position, boundary, trial.support);
        row.active_added = sorted_difference(
            row.topology.active, result.current_topology.active).size();
        row.active_removed = sorted_difference(
            result.current_topology.active, row.topology.active).size();
        row.fluid_added = sorted_difference(
            row.topology.fluid, result.current_topology.fluid).size();
        row.fluid_removed = sorted_difference(
            result.current_topology.fluid, row.topology.fluid).size();
        row.boundary_added = sorted_difference(
            row.topology.boundary,
            result.current_topology.boundary).size();
        row.boundary_removed = sorted_difference(
            result.current_topology.boundary,
            row.topology.boundary).size();
        row.predicted_reduction = -row.alpha * gradient_step
            - 0.5 * row.alpha * row.alpha * step_image;
        row.raw_actual_reduction = current.total - trial.total;
        row.direct_actual_reduction = al_vector_direct_actual_reduction(
            position, trial_position, predicted,
            current.support, trial.support);
        row.branch_actual_reduction = al_vector_direct_actual_reduction(
            position, trial_position, predicted,
            current.support, branch);
        row.direct_ratio = row.predicted_reduction > 0.0
            ? row.direct_actual_reduction / row.predicted_reduction
            : -std::numeric_limits<double>::infinity();
        row.branch_ratio = row.predicted_reduction > 0.0
            ? row.branch_actual_reduction / row.predicted_reduction
            : -std::numeric_limits<double>::infinity();
        row.finite_values = trial.support.finite_values
            && branch.finite_values
            && std::isfinite(row.alpha)
            && std::isfinite(row.rounded_step_norm_m)
            && std::isfinite(row.rounded_step_norm_dx)
            && std::isfinite(row.predicted_reduction)
            && std::isfinite(row.raw_actual_reduction)
            && std::isfinite(row.direct_actual_reduction)
            && std::isfinite(row.direct_ratio)
            && std::isfinite(row.branch_actual_reduction)
            && std::isfinite(row.branch_ratio);
        result.all_finite = result.all_finite && row.finite_values;
        result.any_coordinate_moved = result.any_coordinate_moved
            || row.coordinate_moved;
        result.rows.push_back(std::move(row));
    }

    const ALTopologyAlphaRow& full = result.rows.front();
    result.active_added = sorted_difference(
        full.topology.active, result.current_topology.active);
    result.active_removed = sorted_difference(
        result.current_topology.active, full.topology.active);
    result.fluid_added = sorted_difference(
        full.topology.fluid, result.current_topology.fluid);
    result.fluid_removed = sorted_difference(
        result.current_topology.fluid, full.topology.fluid);
    result.boundary_added = sorted_difference(
        full.topology.boundary, result.current_topology.boundary);
    result.boundary_removed = sorted_difference(
        result.current_topology.boundary, full.topology.boundary);
    for (const ALTopologyPair& pair : result.fluid_added) {
        result.changed_pairs.push_back(al_topology_pair_detail(
            pair, true, position, add_scaled(position, step, 1.0), boundary));
    }
    for (const ALTopologyPair& pair : result.fluid_removed) {
        result.changed_pairs.push_back(al_topology_pair_detail(
            pair, false, position, add_scaled(position, step, 1.0), boundary));
    }
    for (const ALTopologyPair& pair : result.boundary_added) {
        result.changed_pairs.push_back(al_topology_pair_detail(
            pair, true, position, add_scaled(position, step, 1.0), boundary));
    }
    for (const ALTopologyPair& pair : result.boundary_removed) {
        result.changed_pairs.push_back(al_topology_pair_detail(
            pair, false, position, add_scaled(position, step, 1.0), boundary));
    }
    std::sort(result.changed_pairs.begin(), result.changed_pairs.end(),
        [](const ALTopologyPairDetail& lhs,
           const ALTopologyPairDetail& rhs) {
            if (lhs.pair < rhs.pair) return true;
            if (rhs.pair < lhs.pair) return false;
            return lhs.added < rhs.added;
        });
    result.set_accounting_exact =
        result.current_topology.active.size() - result.active_removed.size()
                + result.active_added.size() == full.topology.active.size()
        && result.current_topology.fluid.size() - result.fluid_removed.size()
                + result.fluid_added.size() == full.topology.fluid.size()
        && result.current_topology.boundary.size()
                - result.boundary_removed.size()
                + result.boundary_added.size()
            == full.topology.boundary.size()
        && result.changed_pairs.size() == result.fluid_added.size()
                + result.fluid_removed.size()
                + result.boundary_added.size()
                + result.boundary_removed.size()
        && result.changed_pairs.size() <= 2048U;
    result.all_finite = result.all_finite
        && std::all_of(result.changed_pairs.begin(),
            result.changed_pairs.end(), finite_al_topology_pair_detail);
    result.kernel_horizon_exact = binary64_bits(weight(HORIZON)) == 0U
        && binary64_bits(weight_gradient(HORIZON)) == 0U
        && binary64_bits(weight_second(HORIZON)) == 0U;
    result.kernel_horizon_numerical_zero = weight(HORIZON) == 0.0
        && weight_gradient(HORIZON) == 0.0
        && weight_second(HORIZON) == 0.0;
    result.ladder_exact = result.rows.size() == 21U;
    for (std::size_t index = 0U; index < result.rows.size(); ++index) {
        result.ladder_exact = result.ladder_exact
            && result.rows[index].exponent == static_cast<int>(index)
            && binary64_bits(result.rows[index].alpha)
                == binary64_bits(std::ldexp(
                    1.0, -static_cast<int>(index)));
    }
    result.full_reproduction_exact = result.hvp_calls == 2
        && !result.negative_curvature
        && result.step_norm_dx == 4.9587280227513481e-9
        && full.predicted_reduction == 1.3230255447006828e-15
        && full.raw_actual_reduction == -4.5363018896793506e-16
        && full.direct_actual_reduction == -4.528143341123291e-16;

    bool active_branch = false;
    bool horizon_branch = false;
    bool smaller_live_admissible = false;
    for (const ALTopologyAlphaRow& row : result.rows) {
        if (!row.coordinate_moved) continue;
        active_branch = active_branch || row.active_added > 0U
            || row.active_removed > 0U;
        horizon_branch = horizon_branch
            || (row.predicted_reduction > 0.0
                && row.branch_actual_reduction > 0.0
                && row.branch_ratio >= 0.1
                && (row.direct_actual_reduction <= 0.0
                    || row.direct_ratio < 0.1));
        smaller_live_admissible = smaller_live_admissible
            || (row.exponent > 0 && row.predicted_reduction > 0.0
                && row.direct_actual_reduction > 0.0
                && row.direct_ratio >= 0.1);
    }
    const std::string candidate_route = active_branch
        ? "ACTIVE_CONSTRAINT_BRANCH_RESEARCH_REQUIRED"
        : (horizon_branch
            ? "HORIZON_TOPOLOGY_DERIVATIVE_RECLOSURE_REQUIRED"
            : (smaller_live_admissible
                ? "TRUST_REJECT_POLICY_RECLOSURE_REQUIRED"
                : "AL_HESSIAN_MODEL_RESEARCH_REQUIRED"));
    result.candidate_route = candidate_route;
    const std::vector<Vec3> public_position = predicted;
    const std::vector<double> public_multiplier(multiplier.size(), 0.0);
    result.rollback_exact = exact_vec3_values(public_position, predicted)
        && std::all_of(public_multiplier.begin(), public_multiplier.end(),
            [](double value) { return binary64_bits(value) == 0U; });
    result.passed = current.support.finite_values
        && result.full_reproduction_exact && result.kernel_horizon_exact
        && result.set_accounting_exact && result.all_finite
        && result.ladder_exact && result.any_coordinate_moved
        && result.directional_descent && result.rollback_exact;
    if (result.passed) result.selected_route = candidate_route;
    return result;
}

struct ALGlobalizationProposal {
    bool finite_values = false;
    bool negative_curvature = false;
    bool boundary_limited = false;
    bool topology_exact = false;
    bool admitted = false;
    int hvp_calls = 0;
    double radius = 0.0;
    double step_norm = 0.0;
    double predicted_reduction = 0.0;
    double raw_actual_reduction = 0.0;
    double direct_actual_reduction = 0.0;
    double direct_ratio = 0.0;
    ALTopologySets topology;
};

ALGlobalizationProposal evaluate_al_globalization_proposal(
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier,
    const ALVectorInnerState& current,
    const ALTopologySets& current_topology,
    double radius) {
    ALGlobalizationProposal result;
    result.radius = radius;
    int hvp_calls = 0;
    const std::vector<Vec3> step = al_vector_trust_step(
        position, boundary, multiplier, current.gradient,
        radius, hvp_calls, result.negative_curvature);
    const std::vector<Vec3> image = apply_al_vector_inner_hessian(
        position, boundary, multiplier, step);
    result.hvp_calls = hvp_calls + 1;
    result.step_norm = vector_norm(step);
    result.boundary_limited = std::abs(result.step_norm - radius)
        / std::max(radius, 1.0e-30) <= 1.0e-12;
    const std::vector<Vec3> trial_position = add_scaled(
        position, step, 1.0);
    const ALVectorInnerState trial = evaluate_al_vector_inner(
        trial_position, predicted, boundary, multiplier);
    result.topology = al_topology_sets(
        trial_position, boundary, trial.support);
    result.topology_exact = result.topology.active_root
            == current_topology.active_root
        && result.topology.fluid_root == current_topology.fluid_root
        && result.topology.boundary_root == current_topology.boundary_root;
    result.predicted_reduction = -flat_dot(current.gradient, step)
        - 0.5 * flat_dot(step, image);
    result.raw_actual_reduction = current.total - trial.total;
    result.direct_actual_reduction = al_vector_direct_actual_reduction(
        position, trial_position, predicted,
        current.support, trial.support);
    result.direct_ratio = result.predicted_reduction > 0.0
        ? result.direct_actual_reduction / result.predicted_reduction
        : -std::numeric_limits<double>::infinity();
    result.finite_values = trial.support.finite_values
        && std::isfinite(result.radius) && std::isfinite(result.step_norm)
        && std::isfinite(result.predicted_reduction)
        && std::isfinite(result.raw_actual_reduction)
        && std::isfinite(result.direct_actual_reduction)
        && std::isfinite(result.direct_ratio);
    result.admitted = result.finite_values && result.topology_exact
        && result.predicted_reduction > 0.0
        && result.direct_actual_reduction > 0.0
        && result.direct_ratio >= 0.1;
    return result;
}

struct ALStepNormInnerTrial {
    int trial = 0;
    int hvp_calls = 0;
    bool negative_curvature = false;
    bool accepted = false;
    bool finite_values = false;
    bool topology_exact = false;
    std::string radius_owner;
    double stationarity_before = 0.0;
    double radius_before = 0.0;
    double radius_after = 0.0;
    double step_norm = 0.0;
    double gradient_step = 0.0;
    double predicted_reduction = 0.0;
    double raw_actual_reduction = 0.0;
    double direct_actual_reduction = 0.0;
    double raw_ratio = 0.0;
    double direct_ratio = 0.0;
    double current_total = 0.0;
    double trial_total = 0.0;
    double current_total_ulp = 0.0;
    double trial_total_ulp = 0.0;
    double raw_ulp_ratio = 0.0;
    double direct_ulp_ratio = 0.0;
    double current_phr_margin = 0.0;
    double trial_phr_margin = 0.0;
    double current_horizon_margin = 0.0;
    double trial_horizon_margin = 0.0;
    std::vector<Vec3> current_position;
    std::vector<Vec3> trial_position;
    ALTopologySets current_topology;
    ALTopologySets topology;
};

struct ALStepNormInnerSolve {
    bool passed = false;
    bool positive_accepted_models = true;
    bool all_finite = true;
    bool invalid_interpolation_owned = false;
    std::string failure;
    int accepted_trials = 0;
    int rejected_trials = 0;
    int hvp_calls = 0;
    int step_norm_updates = 0;
    int quarter_updates = 0;
    double final_stationarity = 0.0;
    std::vector<Vec3> position;
    ALVectorSupport support;
    std::vector<ALStepNormInnerTrial> trials;
};

double al_step_norm_rejected_radius(
    double old_radius,
    double step_norm,
    double gradient_step,
    double direct_actual_reduction,
    bool interior,
    bool& used_step_norm,
    bool& invalid_interpolation) {
    used_step_norm = false;
    invalid_interpolation = false;
    if (interior) {
        const double delta_f = -direct_actual_reduction;
        const double denominator = 2.0 * (delta_f - gradient_step);
        const double alpha = -gradient_step / denominator;
        const double candidate = std::min(
            std::max(alpha, 0.25) * step_norm, 0.5 * old_radius);
        const bool valid = std::isfinite(delta_f)
            && std::isfinite(denominator) && denominator > 0.0
            && std::isfinite(alpha) && alpha > 0.0
            && std::isfinite(candidate) && candidate > 0.0
            && candidate < old_radius;
        if (valid) {
            used_step_norm = true;
            return candidate;
        }
        invalid_interpolation = true;
    }
    return 0.25 * old_radius;
}

double al_minimum_phr_margin(
    const ALVectorSupport& support,
    const std::vector<double>& multiplier) {
    double result = std::numeric_limits<double>::infinity();
    if (support.constraint.size() != multiplier.size()) {
        return std::numeric_limits<double>::quiet_NaN();
    }
    for (std::size_t center = 0U; center < multiplier.size(); ++center) {
        result = std::min(result, std::abs(
            multiplier[center] + KAPPA * support.constraint[center]));
    }
    return result;
}

double al_minimum_horizon_margin(
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& boundary) {
    double result = std::numeric_limits<double>::infinity();
    for (std::size_t i = 0U; i < position.size(); ++i) {
        for (std::size_t j = i + 1U; j < position.size(); ++j) {
            result = std::min(result,
                std::abs(norm(position[i] - position[j]) - HORIZON));
        }
        for (Vec3 support : boundary) {
            result = std::min(result,
                std::abs(norm(position[i] - support) - HORIZON));
        }
    }
    return result;
}

double al_binary64_ulp(double value) {
    return std::nextafter(
            value, std::numeric_limits<double>::infinity())
        - value;
}

ALStepNormInnerSolve solve_al_vector_inner_step_norm_eta(
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& initial,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier,
    double stationarity_limit) {
    ALStepNormInnerSolve result;
    result.position = initial;
    ALVectorInnerState current = evaluate_al_vector_inner(
        result.position, predicted, boundary, multiplier);
    if (!current.support.finite_values) {
        result.failure = "INITIAL_NONFINITE";
        return result;
    }
    double trust_radius = 0.25 * SPACING;
    for (int outer = 0; outer < 64; ++outer) {
        result.final_stationarity =
            al_vector_scaled_stationarity(current.gradient);
        if (result.final_stationarity <= stationarity_limit) {
            result.passed = true;
            result.support = std::move(current.support);
            return result;
        }
        ALStepNormInnerTrial record;
        record.trial = outer;
        record.stationarity_before = result.final_stationarity;
        record.radius_before = trust_radius;
        const ALTopologySets current_topology = al_topology_sets(
            result.position, boundary, current.support);
        record.current_topology = current_topology;
        record.current_position = result.position;
        record.current_total = current.total;
        record.current_total_ulp = al_binary64_ulp(current.total);
        record.current_phr_margin = al_minimum_phr_margin(
            current.support, multiplier);
        record.current_horizon_margin = al_minimum_horizon_margin(
            result.position, boundary);
        int hvp_calls = 0;
        const std::vector<Vec3> step = al_vector_trust_step(
            result.position, boundary, multiplier, current.gradient,
            trust_radius, hvp_calls, record.negative_curvature);
        const std::vector<Vec3> image = apply_al_vector_inner_hessian(
            result.position, boundary, multiplier, step);
        ++hvp_calls;
        record.hvp_calls = hvp_calls;
        result.hvp_calls += hvp_calls;
        record.step_norm = vector_norm(step);
        const double gradient_step = flat_dot(current.gradient, step);
        record.gradient_step = gradient_step;
        record.predicted_reduction = -gradient_step
            - 0.5 * flat_dot(step, image);
        const std::vector<Vec3> trial_position = add_scaled(
            result.position, step, 1.0);
        record.trial_position = trial_position;
        ALVectorInnerState trial = evaluate_al_vector_inner(
            trial_position, predicted, boundary, multiplier);
        record.trial_total = trial.total;
        record.trial_total_ulp = al_binary64_ulp(trial.total);
        record.trial_phr_margin = al_minimum_phr_margin(
            trial.support, multiplier);
        record.trial_horizon_margin = al_minimum_horizon_margin(
            trial_position, boundary);
        record.topology = al_topology_sets(
            trial_position, boundary, trial.support);
        record.topology_exact = record.topology.active_root
                == current_topology.active_root
            && record.topology.fluid_root == current_topology.fluid_root
            && record.topology.boundary_root
                == current_topology.boundary_root;
        record.raw_actual_reduction = current.total - trial.total;
        record.direct_actual_reduction = al_vector_direct_actual_reduction(
            result.position, trial_position, predicted,
            current.support, trial.support);
        record.raw_ratio = record.predicted_reduction > 0.0
            ? record.raw_actual_reduction / record.predicted_reduction
            : -std::numeric_limits<double>::infinity();
        record.direct_ratio = record.predicted_reduction > 0.0
            ? record.direct_actual_reduction / record.predicted_reduction
            : -std::numeric_limits<double>::infinity();
        const double ulp_scale = std::max(
            record.current_total_ulp, record.trial_total_ulp);
        record.raw_ulp_ratio = ulp_scale > 0.0
            ? record.raw_actual_reduction / ulp_scale
            : std::numeric_limits<double>::infinity();
        record.direct_ulp_ratio = ulp_scale > 0.0
            ? record.direct_actual_reduction / ulp_scale
            : std::numeric_limits<double>::infinity();
        record.accepted = trial.support.finite_values
            && record.predicted_reduction > 0.0
            && record.raw_actual_reduction > 0.0
            && record.raw_ratio >= 0.1;
        record.finite_values = trial.support.finite_values
            && std::isfinite(record.stationarity_before)
            && std::isfinite(record.radius_before)
            && std::isfinite(record.step_norm)
            && std::isfinite(record.predicted_reduction)
            && std::isfinite(record.raw_actual_reduction)
            && std::isfinite(record.direct_actual_reduction)
            && std::isfinite(record.raw_ratio)
            && std::isfinite(record.direct_ratio)
            && std::isfinite(record.current_total)
            && std::isfinite(record.trial_total)
            && std::isfinite(record.current_total_ulp)
            && std::isfinite(record.trial_total_ulp)
            && std::isfinite(record.raw_ulp_ratio)
            && std::isfinite(record.direct_ulp_ratio)
            && std::isfinite(record.current_phr_margin)
            && std::isfinite(record.trial_phr_margin)
            && std::isfinite(record.current_horizon_margin)
            && std::isfinite(record.trial_horizon_margin);
        result.all_finite = result.all_finite && record.finite_values;
        if (record.raw_ratio < 0.25) {
            bool used_step_norm = false;
            bool invalid_interpolation = false;
            const bool interior = !record.accepted
                && record.step_norm < 0.9 * trust_radius;
            trust_radius = al_step_norm_rejected_radius(
                trust_radius, record.step_norm, gradient_step,
                record.direct_actual_reduction, interior,
                used_step_norm, invalid_interpolation);
            if (used_step_norm) {
                record.radius_owner = "STEP_NORM";
                ++result.step_norm_updates;
            } else {
                record.radius_owner = "QUARTER";
                ++result.quarter_updates;
            }
            result.invalid_interpolation_owned =
                result.invalid_interpolation_owned
                || (invalid_interpolation && used_step_norm);
        } else if (record.raw_ratio > 0.75
            && record.step_norm >= 0.9 * trust_radius) {
            trust_radius = std::min(
                2.0 * trust_radius, 2.0 * SPACING);
            record.radius_owner = "NONE";
        } else {
            record.radius_owner = "NONE";
        }
        record.radius_after = trust_radius;
        if (record.accepted) {
            ++result.accepted_trials;
            result.positive_accepted_models =
                result.positive_accepted_models
                && record.predicted_reduction > 0.0
                && record.raw_actual_reduction > 0.0
                && record.raw_ratio >= 0.1;
            result.position = trial_position;
            current = std::move(trial);
        } else {
            ++result.rejected_trials;
            if (result.rejected_trials > 8) {
                result.failure = "REJECT_LIMIT";
                result.trials.push_back(std::move(record));
                return result;
            }
        }
        result.trials.push_back(std::move(record));
        if (trust_radius < 1.0e-14) {
            result.failure = "MINIMUM_TRUST_RADIUS";
            return result;
        }
    }
    result.failure = "OUTER_LIMIT";
    return result;
}

ALStepNormInnerSolve solve_al_vector_inner_step_norm(
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& initial,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier) {
    return solve_al_vector_inner_step_norm_eta(
        predicted, initial, boundary, multiplier, 1.0e-8);
}

struct ALStepNormOuterRecord {
    ALVectorOuterRecord state;
    int inner_step_norm_updates = 0;
    int inner_quarter_updates = 0;
    bool finite_values = false;
    bool admissible = false;
};

struct ALStepNormOuterUpdate {
    bool passed = false;
    bool finite_failure = false;
    std::string failure;
    std::vector<Vec3> position;
    std::vector<double> multiplier;
    ALVectorSupport support;
    ALStepNormOuterRecord record;
    std::vector<ALStepNormInnerTrial> failed_inner_trials;
};

struct ALStepNormPrivateOuterSolve {
    bool all_inners_pass = true;
    bool all_finite = true;
    bool primal_monotone = true;
    bool cap_exhausted = false;
    bool confirmed = false;
    bool warm_holdout_attempted = false;
    bool warm_holdout_admissible = false;
    bool finite_inner_failure = false;
    std::string failure;
    int provisional_index = -1;
    int confirmation_index = -1;
    int private_confirmation_count = 0;
    std::vector<Vec3> position;
    std::vector<double> multiplier;
    std::vector<Vec3> prefix_position;
    std::vector<double> prefix_multiplier;
    std::vector<Vec3> confirmed_position;
    std::vector<double> confirmed_multiplier;
    ALVectorSupport support;
    std::vector<ALStepNormOuterRecord> records;
    ALStepNormOuterRecord warm_holdout;
};

bool al_step_norm_outer_record_finite(
    const ALVectorOuterRecord& record) {
    return std::isfinite(record.primal)
        && std::isfinite(record.scaled_dual_change)
        && std::isfinite(record.stationarity)
        && std::isfinite(record.complementarity)
        && std::isfinite(record.absolute_dual_change)
        && std::isfinite(record.equivalent_pressure_change)
        && std::isfinite(record.position_update_dx)
        && std::isfinite(record.minimum_multiplier)
        && std::isfinite(record.maximum_multiplier);
}

bool al_step_norm_outer_record_admissible(
    const ALVectorOuterRecord& record,
    double stationarity_limit) {
    return record.primal <= 1.0e-8
        && record.stationarity <= stationarity_limit
        && record.complementarity <= 1.0e-9
        && record.minimum_multiplier >= 0.0
        && record.absolute_dual_change <= 1.0e-8
        && record.equivalent_pressure_change <= 8.0e-5
        && record.position_update_dx <= 1.0e-8;
}

ALStepNormOuterUpdate al_step_norm_private_outer_update_eta(
    const Fixture& fixture,
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& position,
    const std::vector<double>& multiplier,
    int outer,
    double stationarity_limit) {
    ALStepNormOuterUpdate result;
    const ALStepNormInnerSolve inner = solve_al_vector_inner_step_norm_eta(
        predicted, position, fixture.boundary, multiplier,
        stationarity_limit);
    ALVectorOuterRecord& record = result.record.state;
    record.outer = outer;
    record.inner_outer_trials = static_cast<int>(inner.trials.size()) + 1;
    record.inner_accepted_trials = inner.accepted_trials;
    record.inner_rejected_trials = inner.rejected_trials;
    record.inner_hvp_calls = inner.hvp_calls;
    record.stationarity = inner.final_stationarity;
    result.record.inner_step_norm_updates = inner.step_norm_updates;
    result.record.inner_quarter_updates = inner.quarter_updates;
    result.record.finite_values = inner.all_finite
        && std::isfinite(inner.final_stationarity);
    if (!inner.passed || !inner.positive_accepted_models
        || !inner.all_finite) {
        result.failure = "INNER:" + inner.failure;
        result.finite_failure = inner.all_finite
            && inner.failure != "INITIAL_NONFINITE";
        result.failed_inner_trials = inner.trials;
        return result;
    }
    result.position = inner.position;
    result.multiplier.resize(multiplier.size());
    result.support = inner.support;
    record.minimum_multiplier = std::numeric_limits<double>::infinity();
    record.position_update_dx =
        rms_difference(position, inner.position) / SPACING;
    for (std::size_t center = 0U;
         center < multiplier.size(); ++center) {
        result.multiplier[center] = std::max(0.0,
            multiplier[center]
                + KAPPA * inner.support.constraint[center]);
        const double absolute_change = std::abs(
            result.multiplier[center] - multiplier[center]);
        record.primal = std::max(record.primal,
            std::max(0.0, inner.support.constraint[center]));
        record.scaled_dual_change = std::max(
            record.scaled_dual_change, absolute_change / KAPPA);
        record.absolute_dual_change = std::max(
            record.absolute_dual_change, absolute_change);
        record.equivalent_pressure_change = std::max(
            record.equivalent_pressure_change,
            absolute_change * REST_DENSITY / MASS);
        record.complementarity = std::max(record.complementarity,
            std::abs(result.multiplier[center]
                * inner.support.constraint[center]));
        record.minimum_multiplier = std::min(
            record.minimum_multiplier, result.multiplier[center]);
        record.maximum_multiplier = std::max(
            record.maximum_multiplier, result.multiplier[center]);
    }
    result.record.finite_values = inner.support.finite_values
        && al_step_norm_outer_record_finite(record)
        && std::all_of(result.position.begin(), result.position.end(),
            [](Vec3 value) { return finite(value); })
        && std::all_of(result.multiplier.begin(), result.multiplier.end(),
            [](double value) { return std::isfinite(value); });
    result.record.admissible = result.record.finite_values
        && al_step_norm_outer_record_admissible(
            record, stationarity_limit);
    result.passed = result.record.finite_values;
    if (!result.passed) {
        result.failure = "OUTER_NONFINITE";
    }
    return result;
}

ALStepNormOuterUpdate al_step_norm_private_outer_update(
    const Fixture& fixture,
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& position,
    const std::vector<double>& multiplier,
    int outer) {
    return al_step_norm_private_outer_update_eta(
        fixture, predicted, position, multiplier, outer, 1.0e-8);
}

ALStepNormPrivateOuterSolve solve_al_step_norm_private_outer(
    const Fixture& fixture,
    const std::vector<Vec3>& predicted,
    std::vector<Vec3> position,
    std::vector<double> multiplier) {
    constexpr int maximum_outer = 14;
    ALStepNormPrivateOuterSolve result;
    result.position = position;
    result.multiplier = multiplier;
    double previous_primal = std::numeric_limits<double>::infinity();
    bool previous_admissible = false;
    for (int outer = 0; outer < maximum_outer; ++outer) {
        ALStepNormOuterUpdate update = al_step_norm_private_outer_update(
            fixture, predicted, position, multiplier, outer);
        if (!update.passed) {
            result.all_inners_pass = false;
            result.all_finite = result.all_finite && update.finite_failure;
            result.finite_inner_failure = update.finite_failure;
            result.failure = update.failure;
            return result;
        }
        const bool monotone =
            update.record.state.primal <= previous_primal;
        result.primal_monotone = result.primal_monotone && monotone;
        result.all_finite = result.all_finite
            && update.record.finite_values;
        previous_primal = update.record.state.primal;
        result.records.push_back(update.record);
        result.position = update.position;
        result.multiplier = update.multiplier;
        result.support = update.support;
        position = std::move(update.position);
        multiplier = std::move(update.multiplier);
        if (outer == 7) {
            result.prefix_position = result.position;
            result.prefix_multiplier = result.multiplier;
        }
        const bool admissible = update.record.admissible && monotone;
        if (admissible && previous_admissible
            && result.provisional_index == outer - 1) {
            result.confirmed = true;
            result.confirmation_index = outer;
            ++result.private_confirmation_count;
            result.confirmed_position = result.position;
            result.confirmed_multiplier = result.multiplier;
            break;
        }
        result.provisional_index = admissible ? outer : -1;
        previous_admissible = admissible;
    }
    if (result.confirmed) {
        result.warm_holdout_attempted = true;
        ALStepNormOuterUpdate holdout = al_step_norm_private_outer_update(
            fixture, predicted, result.confirmed_position,
            result.confirmed_multiplier, result.confirmation_index + 1);
        if (holdout.passed) {
            result.warm_holdout = holdout.record;
            result.warm_holdout_admissible = holdout.record.admissible
                && holdout.record.state.primal
                    <= result.records.back().state.primal;
        } else {
            result.all_inners_pass = false;
            result.all_finite = result.all_finite && holdout.finite_failure;
            result.finite_inner_failure = holdout.finite_failure;
            result.failure = "HOLDOUT:" + holdout.failure;
        }
        return result;
    }
    result.cap_exhausted = result.all_inners_pass
        && result.all_finite && result.primal_monotone
        && result.records.size() == static_cast<std::size_t>(maximum_outer);
    if (result.cap_exhausted) {
        result.failure = "OUTER_ITERATION_LIMIT";
    }
    return result;
}

struct ALCapAccuracyLane {
    double stationarity_limit = 0.0;
    bool all_inners_pass = true;
    bool all_finite = true;
    bool primal_monotone = true;
    bool dual_feasible = true;
    bool cap_exhausted = false;
    bool confirmed = false;
    bool warm_holdout_attempted = false;
    bool warm_holdout_admissible = false;
    std::string failure;
    int first_admissible_index = -1;
    int provisional_index = -1;
    int confirmation_index = -1;
    int private_confirmation_count = 0;
    std::vector<Vec3> position;
    std::vector<double> multiplier;
    std::vector<Vec3> position_at_outer13;
    std::vector<double> multiplier_at_outer13;
    std::vector<ALStepNormOuterRecord> records;
    ALStepNormOuterRecord failed_inner_work;
    std::vector<ALStepNormInnerTrial> failed_inner_trials;
    ALStepNormOuterRecord warm_holdout;
};

bool al_step_norm_outer_record_exact(
    const ALStepNormOuterRecord& lhs,
    const ALStepNormOuterRecord& rhs) {
    const ALVectorOuterRecord& a = lhs.state;
    const ALVectorOuterRecord& b = rhs.state;
    return a.outer == b.outer
        && a.inner_outer_trials == b.inner_outer_trials
        && a.inner_accepted_trials == b.inner_accepted_trials
        && a.inner_rejected_trials == b.inner_rejected_trials
        && a.inner_hvp_calls == b.inner_hvp_calls
        && binary64_bits(a.primal) == binary64_bits(b.primal)
        && binary64_bits(a.scaled_dual_change)
            == binary64_bits(b.scaled_dual_change)
        && binary64_bits(a.stationarity) == binary64_bits(b.stationarity)
        && binary64_bits(a.complementarity)
            == binary64_bits(b.complementarity)
        && binary64_bits(a.absolute_dual_change)
            == binary64_bits(b.absolute_dual_change)
        && binary64_bits(a.equivalent_pressure_change)
            == binary64_bits(b.equivalent_pressure_change)
        && binary64_bits(a.position_update_dx)
            == binary64_bits(b.position_update_dx)
        && binary64_bits(a.minimum_multiplier)
            == binary64_bits(b.minimum_multiplier)
        && binary64_bits(a.maximum_multiplier)
            == binary64_bits(b.maximum_multiplier)
        && lhs.inner_step_norm_updates == rhs.inner_step_norm_updates
        && lhs.inner_quarter_updates == rhs.inner_quarter_updates
        && lhs.finite_values == rhs.finite_values
        && lhs.admissible == rhs.admissible;
}

bool al_step_norm_inner_trial_exact(
    const ALStepNormInnerTrial& lhs,
    const ALStepNormInnerTrial& rhs) {
    return lhs.trial == rhs.trial
        && lhs.hvp_calls == rhs.hvp_calls
        && lhs.negative_curvature == rhs.negative_curvature
        && lhs.accepted == rhs.accepted
        && lhs.finite_values == rhs.finite_values
        && lhs.topology_exact == rhs.topology_exact
        && lhs.radius_owner == rhs.radius_owner
        && binary64_bits(lhs.stationarity_before)
            == binary64_bits(rhs.stationarity_before)
        && binary64_bits(lhs.radius_before)
            == binary64_bits(rhs.radius_before)
        && binary64_bits(lhs.radius_after)
            == binary64_bits(rhs.radius_after)
        && binary64_bits(lhs.step_norm) == binary64_bits(rhs.step_norm)
        && binary64_bits(lhs.gradient_step)
            == binary64_bits(rhs.gradient_step)
        && binary64_bits(lhs.predicted_reduction)
            == binary64_bits(rhs.predicted_reduction)
        && binary64_bits(lhs.raw_actual_reduction)
            == binary64_bits(rhs.raw_actual_reduction)
        && binary64_bits(lhs.direct_actual_reduction)
            == binary64_bits(rhs.direct_actual_reduction)
        && binary64_bits(lhs.raw_ratio) == binary64_bits(rhs.raw_ratio)
        && binary64_bits(lhs.direct_ratio)
            == binary64_bits(rhs.direct_ratio)
        && binary64_bits(lhs.current_total)
            == binary64_bits(rhs.current_total)
        && binary64_bits(lhs.trial_total)
            == binary64_bits(rhs.trial_total)
        && binary64_bits(lhs.current_total_ulp)
            == binary64_bits(rhs.current_total_ulp)
        && binary64_bits(lhs.trial_total_ulp)
            == binary64_bits(rhs.trial_total_ulp)
        && binary64_bits(lhs.raw_ulp_ratio)
            == binary64_bits(rhs.raw_ulp_ratio)
        && binary64_bits(lhs.direct_ulp_ratio)
            == binary64_bits(rhs.direct_ulp_ratio)
        && binary64_bits(lhs.current_phr_margin)
            == binary64_bits(rhs.current_phr_margin)
        && binary64_bits(lhs.trial_phr_margin)
            == binary64_bits(rhs.trial_phr_margin)
        && binary64_bits(lhs.current_horizon_margin)
            == binary64_bits(rhs.current_horizon_margin)
        && binary64_bits(lhs.trial_horizon_margin)
            == binary64_bits(rhs.trial_horizon_margin)
        && exact_vec3_values(lhs.current_position, rhs.current_position)
        && exact_vec3_values(lhs.trial_position, rhs.trial_position)
        && lhs.current_topology.active_root
            == rhs.current_topology.active_root
        && lhs.current_topology.fluid_root
            == rhs.current_topology.fluid_root
        && lhs.current_topology.boundary_root
            == rhs.current_topology.boundary_root
        && lhs.topology.active_root == rhs.topology.active_root
        && lhs.topology.fluid_root == rhs.topology.fluid_root
        && lhs.topology.boundary_root == rhs.topology.boundary_root;
}

struct ALInnerFloorMechanismSummary {
    bool all_finite = true;
    bool all_topology_stable = true;
    bool all_pair_topology_stable = true;
    bool any_active_change = false;
    bool any_pair_change = false;
    bool any_model_direct_conflict = false;
    int accepted_trials = 0;
    int rejected_trials = 0;
    int merit_floor_trials = 0;
    double minimum_phr_margin = std::numeric_limits<double>::infinity();
    double minimum_horizon_margin = std::numeric_limits<double>::infinity();
};

ALInnerFloorMechanismSummary al_inner_floor_mechanism_summary(
    const std::vector<ALStepNormInnerTrial>& trials) {
    ALInnerFloorMechanismSummary result;
    for (const ALStepNormInnerTrial& trial : trials) {
        const bool active_stable = trial.current_topology.active_root
            == trial.topology.active_root;
        const bool fluid_stable = trial.current_topology.fluid_root
            == trial.topology.fluid_root;
        const bool boundary_stable = trial.current_topology.boundary_root
            == trial.topology.boundary_root;
        const bool pair_stable = fluid_stable && boundary_stable;
        result.all_finite = result.all_finite && trial.finite_values;
        result.all_topology_stable = result.all_topology_stable
            && active_stable && pair_stable;
        result.all_pair_topology_stable =
            result.all_pair_topology_stable && pair_stable;
        result.any_active_change = result.any_active_change
            || !active_stable;
        result.any_pair_change = result.any_pair_change || !pair_stable;
        result.accepted_trials += trial.accepted ? 1 : 0;
        result.rejected_trials += trial.accepted ? 0 : 1;
        result.minimum_phr_margin = std::min(result.minimum_phr_margin,
            std::min(trial.current_phr_margin, trial.trial_phr_margin));
        result.minimum_horizon_margin = std::min(
            result.minimum_horizon_margin,
            std::min(trial.current_horizon_margin,
                trial.trial_horizon_margin));
        const double merit_floor_bound = 8.0 * std::max(
            trial.current_total_ulp, trial.trial_total_ulp);
        const bool merit_floor = active_stable && pair_stable
            && trial.predicted_reduction > 0.0
            && trial.direct_actual_reduction > 0.0
            && !trial.accepted
            && std::abs(trial.raw_actual_reduction) <= merit_floor_bound
            && std::abs(trial.direct_actual_reduction)
                <= merit_floor_bound;
        result.merit_floor_trials += merit_floor ? 1 : 0;
        const bool model_direct_conflict = active_stable && pair_stable
            && ((trial.predicted_reduction > merit_floor_bound
                    && trial.direct_actual_reduction < -merit_floor_bound)
                || (trial.predicted_reduction < -merit_floor_bound
                    && trial.direct_actual_reduction > merit_floor_bound));
        result.any_model_direct_conflict = result.any_model_direct_conflict
            || model_direct_conflict;
    }
    return result;
}

ALCapAccuracyLane solve_al_cap_accuracy_lane(
    const Fixture& fixture,
    const std::vector<Vec3>& predicted,
    std::vector<Vec3> position,
    std::vector<double> multiplier,
    const ALStepNormOuterRecord& prefix_last,
    double stationarity_limit) {
    constexpr int first_outer = 8;
    constexpr int maximum_outer = 64;
    ALCapAccuracyLane result;
    result.stationarity_limit = stationarity_limit;
    result.position = position;
    result.multiplier = multiplier;
    double previous_primal = prefix_last.state.primal;
    bool previous_admissible = prefix_last.finite_values
        && al_step_norm_outer_record_admissible(
            prefix_last.state, stationarity_limit);
    result.provisional_index = previous_admissible ? 7 : -1;
    for (int outer = first_outer; outer < maximum_outer; ++outer) {
        ALStepNormOuterUpdate update = al_step_norm_private_outer_update_eta(
            fixture, predicted, position, multiplier, outer,
            stationarity_limit);
        if (!update.passed) {
            result.all_inners_pass = false;
            result.all_finite = result.all_finite && update.finite_failure;
            result.failure = update.failure;
            result.failed_inner_work = update.record;
            result.failed_inner_trials = update.failed_inner_trials;
            return result;
        }
        const bool monotone = update.record.state.primal <= previous_primal;
        result.primal_monotone = result.primal_monotone && monotone;
        result.all_finite = result.all_finite
            && update.record.finite_values;
        result.dual_feasible = result.dual_feasible
            && update.record.state.minimum_multiplier >= 0.0;
        previous_primal = update.record.state.primal;
        result.records.push_back(update.record);
        result.position = update.position;
        result.multiplier = update.multiplier;
        position = std::move(update.position);
        multiplier = std::move(update.multiplier);
        if (outer == 13) {
            result.position_at_outer13 = result.position;
            result.multiplier_at_outer13 = result.multiplier;
        }
        const bool admissible = update.record.admissible && monotone;
        if (admissible && result.first_admissible_index < 0) {
            result.first_admissible_index = outer;
        }
        if (admissible && previous_admissible
            && result.provisional_index == outer - 1) {
            result.confirmed = true;
            result.confirmation_index = outer;
            ++result.private_confirmation_count;
            break;
        }
        result.provisional_index = admissible ? outer : -1;
        previous_admissible = admissible;
    }
    if (result.confirmed) {
        if (result.confirmation_index >= maximum_outer - 1) {
            result.failure = "HOLDOUT_OBSERVATION_CAP";
            return result;
        }
        result.warm_holdout_attempted = true;
        ALStepNormOuterUpdate holdout = al_step_norm_private_outer_update_eta(
            fixture, predicted, result.position, result.multiplier,
            result.confirmation_index + 1, stationarity_limit);
        if (!holdout.passed) {
            result.all_inners_pass = false;
            result.all_finite = result.all_finite && holdout.finite_failure;
            result.failure = "HOLDOUT:" + holdout.failure;
            result.failed_inner_work = holdout.record;
            result.failed_inner_trials = holdout.failed_inner_trials;
            return result;
        }
        result.warm_holdout = holdout.record;
        result.all_finite = result.all_finite
            && holdout.record.finite_values;
        result.dual_feasible = result.dual_feasible
            && holdout.record.state.minimum_multiplier >= 0.0;
        result.warm_holdout_admissible = holdout.record.admissible
            && holdout.record.state.primal <= previous_primal;
        return result;
    }
    result.cap_exhausted = result.all_inners_pass && result.all_finite
        && result.primal_monotone && result.dual_feasible
        && result.records.size()
            == static_cast<std::size_t>(maximum_outer - first_outer)
        && result.records.back().state.outer == maximum_outer - 1;
    if (result.cap_exhausted) {
        result.failure = "OUTER_OBSERVATION_LIMIT";
    }
    return result;
}

struct LongDoubleAccumulator {
    long double sum = 0.0L;
    long double correction = 0.0L;

    void add(long double value) {
        const long double adjusted = value - correction;
        const long double next = sum + adjusted;
        correction = (next - sum) - adjusted;
        sum = next;
    }
};

struct LongDoubleVec3 {
    long double x = 0.0L;
    long double y = 0.0L;
    long double z = 0.0L;
};

LongDoubleVec3 al_long_double_vec3(Vec3 value) {
    return {static_cast<long double>(value.x),
        static_cast<long double>(value.y),
        static_cast<long double>(value.z)};
}

LongDoubleVec3 operator-(LongDoubleVec3 lhs, LongDoubleVec3 rhs) {
    return {lhs.x - rhs.x, lhs.y - rhs.y, lhs.z - rhs.z};
}

long double al_long_double_norm(LongDoubleVec3 value) {
    return std::sqrt(
        value.x * value.x + value.y * value.y + value.z * value.z);
}

long double al_long_double_weight(long double radius) {
    const long double horizon = static_cast<long double>(HORIZON);
    const long double q = 2.0L * radius / horizon;
    const long double alpha = 3.0L
        / (2.0L * static_cast<long double>(PI)
            * horizon * horizon * horizon);
    long double raw = 0.0L;
    if (q > 2.0L) {
        raw = 0.0L;
    } else if (q >= 1.0L) {
        const long double delta = 2.0L - q;
        raw = alpha * delta * delta * delta / 6.0L;
    } else {
        raw = alpha * (2.0L / 3.0L - q * q
            + 0.5L * q * q * q);
    }
    return static_cast<long double>(kernel_scale()) * raw;
}

struct LongDoubleEnergyEvaluation {
    bool finite_values = false;
    long double total = 0.0L;
    long double phr = 0.0L;
    long double inertia = 0.0L;
    std::size_t fluid_pairs = 0U;
    std::size_t boundary_pairs = 0U;
    std::size_t membership_mismatches = 0U;
    long double minimum_half_horizon_margin =
        std::numeric_limits<long double>::infinity();
    long double minimum_horizon_margin =
        std::numeric_limits<long double>::infinity();
};

LongDoubleEnergyEvaluation evaluate_al_vector_inner_long_double(
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier,
    bool compensated,
    double time_step = TIME_STEP,
    double penalty = KAPPA) {
    LongDoubleEnergyEvaluation result;
    if (position.size() != predicted.size()
        || position.size() != multiplier.size()
        || !std::isfinite(time_step) || time_step <= 0.0
        || !std::isfinite(penalty) || penalty <= 0.0) {
        return result;
    }
    const std::size_t count = position.size();
    std::vector<LongDoubleVec3> fluid(count);
    std::vector<LongDoubleVec3> predicted_extended(count);
    std::vector<LongDoubleVec3> support(boundary.size());
    std::transform(position.begin(), position.end(), fluid.begin(),
        al_long_double_vec3);
    std::transform(predicted.begin(), predicted.end(),
        predicted_extended.begin(), al_long_double_vec3);
    std::transform(boundary.begin(), boundary.end(), support.begin(),
        al_long_double_vec3);
    const long double mass = static_cast<long double>(MASS);
    const long double rest_density =
        static_cast<long double>(REST_DENSITY);
    const long double kappa = static_cast<long double>(penalty);
    const long double horizon = static_cast<long double>(HORIZON);
    const long double half_horizon = 0.5L * horizon;
    std::vector<long double> density(
        count, mass * al_long_double_weight(0.0L));
    std::vector<long double> density_correction(count, 0.0L);
    const auto add_density = [&](std::size_t center, long double value) {
        if (!compensated) {
            density[center] += value;
            return;
        }
        const long double adjusted = value - density_correction[center];
        const long double next = density[center] + adjusted;
        density_correction[center] =
            (next - density[center]) - adjusted;
        density[center] = next;
    };
    const auto observe_radius = [&](double binary_radius,
                                    long double extended_radius) {
        result.minimum_half_horizon_margin = std::min(
            result.minimum_half_horizon_margin,
            std::abs(extended_radius - half_horizon));
        result.minimum_horizon_margin = std::min(
            result.minimum_horizon_margin,
            std::abs(extended_radius - horizon));
        const bool binary_member = binary_radius <= HORIZON;
        const bool extended_member = extended_radius <= horizon;
        result.membership_mismatches +=
            binary_member == extended_member ? 0U : 1U;
        return extended_member;
    };
    for (std::size_t i = 0U; i < count; ++i) {
        for (std::size_t j = i + 1U; j < count; ++j) {
            const double binary_radius = norm(position[i] - position[j]);
            const long double extended_radius = al_long_double_norm(
                fluid[i] - fluid[j]);
            if (observe_radius(binary_radius, extended_radius)) {
                const long double contribution = mass
                    * al_long_double_weight(extended_radius);
                add_density(i, contribution);
                add_density(j, contribution);
                ++result.fluid_pairs;
            }
        }
        for (std::size_t index = 0U; index < support.size(); ++index) {
            const double binary_radius = norm(
                position[i] - boundary[index]);
            const long double extended_radius = al_long_double_norm(
                fluid[i] - support[index]);
            if (observe_radius(binary_radius, extended_radius)) {
                add_density(i,
                    mass * al_long_double_weight(extended_radius));
                ++result.boundary_pairs;
            }
        }
    }
    LongDoubleAccumulator phr_compensated;
    LongDoubleAccumulator inertia_compensated;
    long double phr_naive = 0.0L;
    long double inertia_naive = 0.0L;
    const long double inertia_scale = mass
        / (static_cast<long double>(time_step)
            * static_cast<long double>(time_step));
    for (std::size_t center = 0U; center < count; ++center) {
        const long double constraint =
            density[center] / rest_density - 1.0L;
        const long double lambda =
            static_cast<long double>(multiplier[center]);
        const long double active = std::max(
            0.0L, lambda + kappa * constraint);
        const long double phr_term =
            (active * active - lambda * lambda) / (2.0L * kappa);
        const LongDoubleVec3 displacement =
            fluid[center] - predicted_extended[center];
        const long double inertia_term = 0.5L * inertia_scale
            * (displacement.x * displacement.x
                + displacement.y * displacement.y
                + displacement.z * displacement.z);
        if (compensated) {
            phr_compensated.add(phr_term);
            inertia_compensated.add(inertia_term);
        } else {
            phr_naive += phr_term;
            inertia_naive += inertia_term;
        }
    }
    result.phr = compensated ? phr_compensated.sum : phr_naive;
    result.inertia = compensated
        ? inertia_compensated.sum : inertia_naive;
    if (compensated) {
        LongDoubleAccumulator total;
        total.add(result.phr);
        total.add(result.inertia);
        result.total = total.sum;
    } else {
        result.total = result.phr + result.inertia;
    }
    result.finite_values = std::isfinite(result.total)
        && std::isfinite(result.phr) && std::isfinite(result.inertia)
        && std::isfinite(result.minimum_half_horizon_margin)
        && std::isfinite(result.minimum_horizon_margin);
    return result;
}

struct LongDoubleTrialEnergyAudit {
    LongDoubleEnergyEvaluation current_naive;
    LongDoubleEnergyEvaluation current_compensated;
    LongDoubleEnergyEvaluation trial_naive;
    LongDoubleEnergyEvaluation trial_compensated;
    long double naive_reduction = 0.0L;
    long double compensated_reduction = 0.0L;
    long double extended_ulp = 0.0L;
    long double naive_ulp_ratio = 0.0L;
    long double compensated_ulp_ratio = 0.0L;
    bool finite_values = false;
    bool sign_agrees = false;
    bool resolved = false;
    bool resolved_positive = false;
    bool resolved_negative = false;
    bool topology_precision_mismatch = false;
};

LongDoubleTrialEnergyAudit audit_al_vector_inner_long_double(
    const ALStepNormInnerTrial& trial,
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier,
    double time_step = TIME_STEP,
    double penalty = KAPPA) {
    LongDoubleTrialEnergyAudit result;
    result.current_naive = evaluate_al_vector_inner_long_double(
        trial.current_position, predicted, boundary, multiplier,
        false, time_step, penalty);
    result.current_compensated = evaluate_al_vector_inner_long_double(
        trial.current_position, predicted, boundary, multiplier,
        true, time_step, penalty);
    result.trial_naive = evaluate_al_vector_inner_long_double(
        trial.trial_position, predicted, boundary, multiplier,
        false, time_step, penalty);
    result.trial_compensated = evaluate_al_vector_inner_long_double(
        trial.trial_position, predicted, boundary, multiplier,
        true, time_step, penalty);
    result.naive_reduction = result.current_naive.total
        - result.trial_naive.total;
    result.compensated_reduction = result.current_compensated.total
        - result.trial_compensated.total;
    result.extended_ulp = std::max(
        std::nextafter(result.current_compensated.total,
            std::numeric_limits<long double>::infinity())
            - result.current_compensated.total,
        std::nextafter(result.trial_compensated.total,
            std::numeric_limits<long double>::infinity())
            - result.trial_compensated.total);
    result.naive_ulp_ratio = result.extended_ulp > 0.0L
        ? result.naive_reduction / result.extended_ulp : 0.0L;
    result.compensated_ulp_ratio = result.extended_ulp > 0.0L
        ? result.compensated_reduction / result.extended_ulp : 0.0L;
    result.sign_agrees =
        (result.naive_reduction > 0.0L
            && result.compensated_reduction > 0.0L)
        || (result.naive_reduction < 0.0L
            && result.compensated_reduction < 0.0L);
    const long double resolution = 1024.0L * result.extended_ulp;
    result.resolved = result.sign_agrees
        && std::abs(result.naive_reduction) >= resolution
        && std::abs(result.compensated_reduction) >= resolution;
    result.resolved_positive = result.resolved
        && result.compensated_reduction > 0.0L;
    result.resolved_negative = result.resolved
        && result.compensated_reduction < 0.0L;
    result.topology_precision_mismatch =
        result.current_naive.membership_mismatches != 0U
        || result.current_compensated.membership_mismatches != 0U
        || result.trial_naive.membership_mismatches != 0U
        || result.trial_compensated.membership_mismatches != 0U;
    result.finite_values = result.current_naive.finite_values
        && result.current_compensated.finite_values
        && result.trial_naive.finite_values
        && result.trial_compensated.finite_values
        && std::isfinite(result.naive_reduction)
        && std::isfinite(result.compensated_reduction)
        && std::isfinite(result.extended_ulp)
        && std::isfinite(result.naive_ulp_ratio)
        && std::isfinite(result.compensated_ulp_ratio);
    return result;
}

bool al_long_double_energy_evaluation_exact(
    const LongDoubleEnergyEvaluation& lhs,
    const LongDoubleEnergyEvaluation& rhs) {
    return lhs.finite_values == rhs.finite_values
        && lhs.total == rhs.total && lhs.phr == rhs.phr
        && lhs.inertia == rhs.inertia
        && lhs.fluid_pairs == rhs.fluid_pairs
        && lhs.boundary_pairs == rhs.boundary_pairs
        && lhs.membership_mismatches == rhs.membership_mismatches
        && lhs.minimum_half_horizon_margin
            == rhs.minimum_half_horizon_margin
        && lhs.minimum_horizon_margin == rhs.minimum_horizon_margin;
}

[[maybe_unused]] bool al_long_double_trial_energy_audit_exact(
    const LongDoubleTrialEnergyAudit& lhs,
    const LongDoubleTrialEnergyAudit& rhs) {
    return al_long_double_energy_evaluation_exact(
            lhs.current_naive, rhs.current_naive)
        && al_long_double_energy_evaluation_exact(
            lhs.current_compensated, rhs.current_compensated)
        && al_long_double_energy_evaluation_exact(
            lhs.trial_naive, rhs.trial_naive)
        && al_long_double_energy_evaluation_exact(
            lhs.trial_compensated, rhs.trial_compensated)
        && lhs.naive_reduction == rhs.naive_reduction
        && lhs.compensated_reduction == rhs.compensated_reduction
        && lhs.extended_ulp == rhs.extended_ulp
        && lhs.naive_ulp_ratio == rhs.naive_ulp_ratio
        && lhs.compensated_ulp_ratio == rhs.compensated_ulp_ratio
        && lhs.finite_values == rhs.finite_values
        && lhs.sign_agrees == rhs.sign_agrees
        && lhs.resolved == rhs.resolved
        && lhs.resolved_positive == rhs.resolved_positive
        && lhs.resolved_negative == rhs.resolved_negative
        && lhs.topology_precision_mismatch
            == rhs.topology_precision_mismatch;
}

struct ALSparsePrecisionWorkTrace {
    std::size_t superset_builds = 0U;
    std::size_t union_candidate_pairs = 0U;
    std::size_t long_double_audits = 0U;
    std::size_t long_double_union_candidate_pairs = 0U;
    std::size_t long_double_evaluation_pair_visits = 0U;
    std::size_t binary128_audits = 0U;
    std::size_t binary128_union_candidate_pairs = 0U;
    std::size_t binary128_evaluation_pair_visits = 0U;
    std::size_t all_pair_candidate_calls = 0U;
};

struct ALSparsePrecisionTransactionContext {
    const JointStaticSupportBinding* binding = nullptr;
    ALSparsePrecisionWorkTrace* precision_work = nullptr;
    StaticSupportWorkTrace* static_work = nullptr;
    FlatAdjacencyWorkTrace* adjacency_work = nullptr;
    std::vector<LongDoubleTrialEnergyAudit>* long_double_audits = nullptr;
    ALSparseStructuralBudget* structural_budget = nullptr;
};

LongDoubleTrialEnergyAudit audit_al_sparse_inner_long_double(
    const ALStepNormInnerTrial& trial,
    const std::vector<Vec3>& predicted,
    const std::vector<double>& multiplier,
    const JointStaticSupportBinding& binding,
    double time_step,
    ALSparsePrecisionWorkTrace* work,
    double penalty = KAPPA);

struct Binary64CompensatedAccumulator {
    double sum = 0.0;
    double correction = 0.0;

    void add(double value) {
        const double next = sum + value;
        correction += std::abs(sum) >= std::abs(value)
            ? (sum - next) + value
            : (value - next) + sum;
        sum = next;
    }

    double value() const {
        return sum + correction;
    }
};

double al_binary64_squared_norm_delta(Vec3 current, Vec3 step) {
    Binary64CompensatedAccumulator result;
    result.add(2.0 * current.x * step.x);
    result.add(step.x * step.x);
    result.add(2.0 * current.y * step.y);
    result.add(step.y * step.y);
    result.add(2.0 * current.z * step.z);
    result.add(step.z * step.z);
    return result.value();
}

int al_binary64_kernel_segment(double radius) {
    if (radius > HORIZON) {
        return 2;
    }
    return radius >= 0.5 * HORIZON ? 1 : 0;
}

double al_binary64_kernel_shape_segment_delta(
    int segment, double q, double delta_q) {
    if (segment == 0) {
        return delta_q * (
            -(2.0 * q + delta_q)
            + 0.5 * (3.0 * q * q + 3.0 * q * delta_q
                + delta_q * delta_q));
    }
    if (segment == 1) {
        const double current = 2.0 - q;
        const double delta = -delta_q;
        return delta * (3.0 * current * current
            + 3.0 * current * delta + delta * delta) / 6.0;
    }
    return 0.0;
}

struct Binary64KernelDelta {
    bool finite_values = false;
    double value = 0.0;
    double radius_delta = 0.0;
    int current_segment = 0;
    int trial_segment = 0;
};

Binary64KernelDelta al_binary64_kernel_delta(
    Vec3 current_displacement,
    Vec3 trial_displacement,
    Vec3 representable_step) {
    Binary64KernelDelta result;
    const double current_radius = norm(current_displacement);
    const double trial_radius = norm(trial_displacement);
    const double squared_delta = al_binary64_squared_norm_delta(
        current_displacement, representable_step);
    const double radius_sum = current_radius + trial_radius;
    result.radius_delta = radius_sum > 0.0
        ? squared_delta / radius_sum : 0.0;
    result.current_segment = al_binary64_kernel_segment(current_radius);
    result.trial_segment = al_binary64_kernel_segment(trial_radius);
    const double current_q = 2.0 * current_radius / HORIZON;
    double remaining = 2.0 * result.radius_delta / HORIZON;
    double q = current_q;
    int segment = result.current_segment;
    double shape_delta = 0.0;
    if (segment == result.trial_segment) {
        shape_delta = al_binary64_kernel_shape_segment_delta(
            segment, q, remaining);
    } else if (remaining > 0.0) {
        while (segment < result.trial_segment) {
            const double knot = segment == 0 ? 1.0 : 2.0;
            const double piece = knot - q;
            shape_delta += al_binary64_kernel_shape_segment_delta(
                segment, q, piece);
            remaining -= piece;
            q = knot;
            ++segment;
        }
        shape_delta += al_binary64_kernel_shape_segment_delta(
            segment, q, remaining);
    } else {
        while (segment > result.trial_segment) {
            const double knot = segment == 2 ? 2.0 : 1.0;
            const double piece = knot - q;
            shape_delta += al_binary64_kernel_shape_segment_delta(
                segment, q, piece);
            remaining -= piece;
            q = knot;
            --segment;
        }
        shape_delta += al_binary64_kernel_shape_segment_delta(
            segment, q, remaining);
    }
    const double alpha = 3.0
        / (2.0 * PI * HORIZON * HORIZON * HORIZON);
    result.value = kernel_scale() * alpha * shape_delta;
    result.finite_values = std::isfinite(current_radius)
        && std::isfinite(trial_radius) && std::isfinite(squared_delta)
        && std::isfinite(result.radius_delta)
        && std::isfinite(result.value);
    return result;
}

struct Binary64CompensatedEnergy {
    bool finite_values = false;
    double total = 0.0;
    double phr = 0.0;
    double inertia = 0.0;
};

Binary64CompensatedEnergy evaluate_al_vector_inner_compensated_binary64(
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier) {
    Binary64CompensatedEnergy result;
    if (position.size() != predicted.size()
        || position.size() != multiplier.size()) {
        return result;
    }
    std::vector<Binary64CompensatedAccumulator> density(position.size());
    for (Binary64CompensatedAccumulator& value : density) {
        value.add(MASS * weight(0.0));
    }
    for (std::size_t i = 0U; i < position.size(); ++i) {
        for (std::size_t j = i + 1U; j < position.size(); ++j) {
            const double radius = norm(position[i] - position[j]);
            if (radius <= HORIZON) {
                const double contribution = MASS * weight(radius);
                density[i].add(contribution);
                density[j].add(contribution);
            }
        }
        for (Vec3 support : boundary) {
            const double radius = norm(position[i] - support);
            if (radius <= HORIZON) {
                density[i].add(MASS * weight(radius));
            }
        }
    }
    Binary64CompensatedAccumulator phr;
    Binary64CompensatedAccumulator inertia;
    const double inertia_scale = MASS / (TIME_STEP * TIME_STEP);
    for (std::size_t center = 0U; center < position.size(); ++center) {
        const double constraint =
            density[center].value() / REST_DENSITY - 1.0;
        const double active = std::max(
            0.0, multiplier[center] + KAPPA * constraint);
        phr.add((active * active
            - multiplier[center] * multiplier[center]) / (2.0 * KAPPA));
        const Vec3 displacement = position[center] - predicted[center];
        inertia.add(0.5 * inertia_scale * norm_squared(displacement));
    }
    result.phr = phr.value();
    result.inertia = inertia.value();
    Binary64CompensatedAccumulator total;
    total.add(result.phr);
    total.add(result.inertia);
    result.total = total.value();
    result.finite_values = std::isfinite(result.total)
        && std::isfinite(result.phr) && std::isfinite(result.inertia)
        && std::all_of(density.begin(), density.end(),
            [](const Binary64CompensatedAccumulator& value) {
                return std::isfinite(value.value());
            });
    return result;
}

struct Binary64DividedDifference {
    bool finite_values = false;
    double reduction = 0.0;
    double phr_reduction = 0.0;
    double inertia_reduction = 0.0;
    std::size_t support_crossings = 0U;
    std::size_t kernel_segment_crossings = 0U;
    std::size_t phr_branch_crossings = 0U;
};

Binary64DividedDifference evaluate_al_vector_inner_divided_difference(
    const std::vector<Vec3>& current_position,
    const std::vector<Vec3>& trial_position,
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier,
    double time_step = TIME_STEP,
    double kappa = KAPPA) {
    Binary64DividedDifference result;
    if (current_position.size() != trial_position.size()
        || current_position.size() != predicted.size()
        || current_position.size() != multiplier.size()
        || !std::isfinite(time_step) || time_step <= 0.0
        || !std::isfinite(kappa) || kappa <= 0.0) {
        return result;
    }
    const std::size_t count = current_position.size();
    std::vector<Vec3> step(count);
    for (std::size_t center = 0U; center < count; ++center) {
        step[center] = trial_position[center] - current_position[center];
    }
    std::vector<Binary64CompensatedAccumulator> current_density(count);
    std::vector<Binary64CompensatedAccumulator> density_delta(count);
    for (Binary64CompensatedAccumulator& value : current_density) {
        value.add(MASS * weight(0.0));
    }
    bool pair_finite = true;
    const auto fold_pair = [&](std::size_t center,
                               std::size_t other,
                               Vec3 current_displacement,
                               Vec3 trial_displacement,
                               Vec3 pair_step,
                               bool symmetric) {
        const double current_radius = norm(current_displacement);
        const double trial_radius = norm(trial_displacement);
        if (current_radius <= HORIZON) {
            current_density[center].add(MASS * weight(current_radius));
            if (symmetric) {
                current_density[other].add(MASS * weight(current_radius));
            }
        }
        const Binary64KernelDelta delta = al_binary64_kernel_delta(
            current_displacement, trial_displacement, pair_step);
        pair_finite = pair_finite && delta.finite_values;
        const double contribution = MASS * delta.value;
        density_delta[center].add(contribution);
        if (symmetric) {
            density_delta[other].add(contribution);
        }
        result.support_crossings +=
            (current_radius <= HORIZON) != (trial_radius <= HORIZON)
            ? 1U : 0U;
        result.kernel_segment_crossings +=
            delta.current_segment != delta.trial_segment ? 1U : 0U;
    };
    for (std::size_t i = 0U; i < count; ++i) {
        for (std::size_t j = i + 1U; j < count; ++j) {
            fold_pair(i, j,
                current_position[i] - current_position[j],
                trial_position[i] - trial_position[j],
                step[i] - step[j], true);
        }
        for (std::size_t support = 0U;
             support < boundary.size(); ++support) {
            fold_pair(i, 0U,
                current_position[i] - boundary[support],
                trial_position[i] - boundary[support],
                step[i], false);
        }
    }
    Binary64CompensatedAccumulator phr_reduction;
    Binary64CompensatedAccumulator inertia_reduction;
    const double inertia_scale = MASS / (time_step * time_step);
    for (std::size_t center = 0U; center < count; ++center) {
        const double current_constraint =
            current_density[center].value() / REST_DENSITY - 1.0;
        const double constraint_delta =
            density_delta[center].value() / REST_DENSITY;
        const double current_unclamped = multiplier[center]
            + kappa * current_constraint;
        const double active_delta = kappa * constraint_delta;
        const double trial_unclamped = current_unclamped + active_delta;
        const bool current_active = current_unclamped > 0.0;
        const bool trial_active = trial_unclamped > 0.0;
        result.phr_branch_crossings +=
            current_active != trial_active ? 1U : 0U;
        double active_square_delta = 0.0;
        if (current_active && trial_active) {
            active_square_delta = active_delta
                * (2.0 * current_unclamped + active_delta);
        } else if (current_active) {
            active_square_delta = -current_unclamped * current_unclamped;
        } else if (trial_active) {
            active_square_delta = trial_unclamped * trial_unclamped;
        }
        phr_reduction.add(-active_square_delta / (2.0 * kappa));
        const Vec3 displacement =
            current_position[center] - predicted[center];
        const double norm_squared_delta =
            al_binary64_squared_norm_delta(displacement, step[center]);
        inertia_reduction.add(-0.5 * inertia_scale * norm_squared_delta);
    }
    result.phr_reduction = phr_reduction.value();
    result.inertia_reduction = inertia_reduction.value();
    Binary64CompensatedAccumulator reduction;
    reduction.add(result.phr_reduction);
    reduction.add(result.inertia_reduction);
    result.reduction = reduction.value();
    result.finite_values = pair_finite
        && std::isfinite(result.reduction)
        && std::isfinite(result.phr_reduction)
        && std::isfinite(result.inertia_reduction)
        && std::all_of(current_density.begin(), current_density.end(),
            [](const Binary64CompensatedAccumulator& value) {
                return std::isfinite(value.value());
            })
        && std::all_of(density_delta.begin(), density_delta.end(),
            [](const Binary64CompensatedAccumulator& value) {
                return std::isfinite(value.value());
            });
    return result;
}

bool al_joint_pair_less(const JointPair& lhs, const JointPair& rhs) {
    return lhs.fluid < rhs.fluid
        || (lhs.fluid == rhs.fluid
            && lhs.participant < rhs.participant);
}

Binary64DividedDifference evaluate_al_sparse_inner_divided_difference(
    const ALSparseWorkspace& current,
    const ALSparseWorkspace& trial,
    const std::vector<Vec3>& predicted,
    const std::vector<double>& multiplier,
    double time_step,
    ALSparseWorkTrace* work = nullptr,
    double kappa = KAPPA) {
    Binary64DividedDifference result;
    const std::size_t count = current.neighborhood.fluid.size();
    if (!current.passed || !trial.passed
        || trial.neighborhood.fluid.size() != count
        || current.neighborhood.support.size()
            != trial.neighborhood.support.size()
        || predicted.size() != count || multiplier.size() != count
        || !std::isfinite(time_step) || time_step <= 0.0
        || !std::isfinite(kappa) || kappa <= 0.0
        || binary64_bits(current.kappa) != binary64_bits(kappa)
        || binary64_bits(trial.kappa) != binary64_bits(kappa)
        || !exact_joint_points(current.neighborhood.support,
            trial.neighborhood.support)) {
        return result;
    }
    std::vector<Vec3> step(count);
    for (std::size_t center = 0U; center < count; ++center) {
        step[center] = trial.neighborhood.fluid[center].position
            - current.neighborhood.fluid[center].position;
    }
    std::vector<Binary64CompensatedAccumulator> current_density(count);
    std::vector<Binary64CompensatedAccumulator> density_delta(count);
    for (Binary64CompensatedAccumulator& value : current_density) {
        value.add(MASS * weight(0.0));
    }
    const std::vector<JointPair>& current_pairs =
        current.neighborhood.pairs;
    const std::vector<JointPair>& trial_pairs = trial.neighborhood.pairs;
    std::size_t current_index = 0U;
    std::size_t trial_index = 0U;
    bool pair_finite = true;
    while (current_index < current_pairs.size()
        || trial_index < trial_pairs.size()) {
        const bool have_current = current_index < current_pairs.size();
        const bool have_trial = trial_index < trial_pairs.size();
        const bool current_before = have_current
            && (!have_trial || al_joint_pair_less(
                current_pairs[current_index], trial_pairs[trial_index]));
        const bool trial_before = have_trial
            && (!have_current || al_joint_pair_less(
                trial_pairs[trial_index], current_pairs[current_index]));
        const bool current_member = have_current && !trial_before;
        const bool trial_member = have_trial && !current_before;
        const JointPair pair = current_before
            ? current_pairs[current_index]
            : trial_pairs[trial_index];
        if (current_member) {
            ++current_index;
        }
        if (trial_member) {
            ++trial_index;
        }
        if (work != nullptr) {
            ++work->divided_union_visits;
            work->current_members += current_member ? 1U : 0U;
            work->trial_members += trial_member ? 1U : 0U;
        }
        const bool symmetric = pair.participant < count;
        const std::size_t other = symmetric ? pair.participant : 0U;
        const std::size_t support_index = symmetric
            ? 0U : pair.participant - count;
        const Vec3 current_other = symmetric
            ? current.neighborhood.fluid[other].position
            : current.neighborhood.support[support_index].position;
        const Vec3 trial_other = symmetric
            ? trial.neighborhood.fluid[other].position
            : trial.neighborhood.support[support_index].position;
        const Vec3 current_displacement =
            current.neighborhood.fluid[pair.fluid].position
            - current_other;
        const Vec3 trial_displacement =
            trial.neighborhood.fluid[pair.fluid].position - trial_other;
        const Vec3 pair_step = symmetric
            ? step[pair.fluid] - step[other] : step[pair.fluid];
        const double current_radius = norm(current_displacement);
        if (current_member) {
            const double contribution = MASS * weight(current_radius);
            current_density[pair.fluid].add(contribution);
            if (symmetric) {
                current_density[other].add(contribution);
            }
        }
        const Binary64KernelDelta delta = al_binary64_kernel_delta(
            current_displacement, trial_displacement, pair_step);
        pair_finite = pair_finite && delta.finite_values;
        const double contribution = MASS * delta.value;
        density_delta[pair.fluid].add(contribution);
        if (symmetric) {
            density_delta[other].add(contribution);
        }
        result.support_crossings += current_member != trial_member ? 1U : 0U;
        result.kernel_segment_crossings +=
            delta.current_segment != delta.trial_segment ? 1U : 0U;
    }
    Binary64CompensatedAccumulator phr_reduction;
    Binary64CompensatedAccumulator inertia_reduction;
    const double inertia_scale = MASS / (time_step * time_step);
    for (std::size_t center = 0U; center < count; ++center) {
        const double current_constraint =
            current_density[center].value() / REST_DENSITY - 1.0;
        const double constraint_delta =
            density_delta[center].value() / REST_DENSITY;
        const double current_unclamped = multiplier[center]
            + kappa * current_constraint;
        const double active_delta = kappa * constraint_delta;
        const double trial_unclamped = current_unclamped + active_delta;
        const bool current_active = current_unclamped > 0.0;
        const bool trial_active = trial_unclamped > 0.0;
        result.phr_branch_crossings +=
            current_active != trial_active ? 1U : 0U;
        double active_square_delta = 0.0;
        if (current_active && trial_active) {
            active_square_delta = active_delta
                * (2.0 * current_unclamped + active_delta);
        } else if (current_active) {
            active_square_delta = -current_unclamped * current_unclamped;
        } else if (trial_active) {
            active_square_delta = trial_unclamped * trial_unclamped;
        }
        phr_reduction.add(-active_square_delta / (2.0 * kappa));
        const Vec3 displacement =
            current.neighborhood.fluid[center].position
            - predicted[center];
        const double norm_squared_delta =
            al_binary64_squared_norm_delta(displacement, step[center]);
        inertia_reduction.add(-0.5 * inertia_scale * norm_squared_delta);
    }
    result.phr_reduction = phr_reduction.value();
    result.inertia_reduction = inertia_reduction.value();
    Binary64CompensatedAccumulator reduction;
    reduction.add(result.phr_reduction);
    reduction.add(result.inertia_reduction);
    result.reduction = reduction.value();
    result.finite_values = pair_finite
        && std::isfinite(result.reduction)
        && std::isfinite(result.phr_reduction)
        && std::isfinite(result.inertia_reduction)
        && std::all_of(current_density.begin(), current_density.end(),
            [](const Binary64CompensatedAccumulator& value) {
                return std::isfinite(value.value());
            })
        && std::all_of(density_delta.begin(), density_delta.end(),
            [](const Binary64CompensatedAccumulator& value) {
                return std::isfinite(value.value());
            });
    return result;
}

bool al_binary64_divided_difference_exact(
    const Binary64DividedDifference& lhs,
    const Binary64DividedDifference& rhs) {
    return lhs.finite_values == rhs.finite_values
        && binary64_bits(lhs.reduction) == binary64_bits(rhs.reduction)
        && binary64_bits(lhs.phr_reduction)
            == binary64_bits(rhs.phr_reduction)
        && binary64_bits(lhs.inertia_reduction)
            == binary64_bits(rhs.inertia_reduction)
        && lhs.support_crossings == rhs.support_crossings
        && lhs.kernel_segment_crossings == rhs.kernel_segment_crossings
        && lhs.phr_branch_crossings == rhs.phr_branch_crossings;
}

struct ALDividedPrivateInnerTrial {
    int trial = 0;
    bool finite_values = false;
    bool divided_repeat_exact = false;
    bool raw_would_accept = false;
    bool candidate_accepted = false;
    bool candidate_effect = false;
    bool negative_curvature = false;
    bool oracle_audited = false;
    bool oracle_resolved = false;
    bool oracle_resolved_positive = false;
    bool oracle_resolved_negative = false;
    int hvp_calls = 0;
    std::string radius_owner;
    double stationarity_before = 0.0;
    double radius_before = 0.0;
    double radius_after = 0.0;
    double step_norm = 0.0;
    double predicted_reduction = 0.0;
    double raw_reduction = 0.0;
    double direct_reduction = 0.0;
    double divided_reduction = 0.0;
    double divided_ratio = 0.0;
    double phr_reduction = 0.0;
    double inertia_reduction = 0.0;
    std::size_t support_crossings = 0U;
    std::size_t kernel_segment_crossings = 0U;
    std::size_t phr_branch_crossings = 0U;
    long double oracle_reduction = 0.0L;
    long double oracle_ulp_ratio = 0.0L;
    std::vector<Vec3> current_position;
    std::vector<Vec3> trial_position;
};

struct ALDividedPrivateInnerSolve {
    bool passed = false;
    bool all_finite = true;
    bool divided_repeat_exact = true;
    bool positive_accepted_models = true;
    bool invalid_interpolation_owned = false;
    bool candidate_effect = false;
    std::string failure;
    int accepted_trials = 0;
    int rejected_trials = 0;
    int hvp_calls = 0;
    int step_norm_updates = 0;
    int quarter_updates = 0;
    int resolved_positive_acceptances = 0;
    int resolved_negative_acceptances = 0;
    int unresolved_acceptances = 0;
    double final_stationarity = 0.0;
    std::vector<Vec3> position;
    std::vector<ALDividedPrivateInnerTrial> trials;
};

ALDividedPrivateInnerSolve solve_al_divided_private_inner(
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& initial,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier,
    double stationarity_limit) {
    ALDividedPrivateInnerSolve result;
    result.position = initial;
    ALVectorInnerState current = evaluate_al_vector_inner(
        result.position, predicted, boundary, multiplier);
    if (!current.support.finite_values) {
        result.all_finite = false;
        result.failure = "INITIAL_NONFINITE";
        return result;
    }
    double trust_radius = 0.25 * SPACING;
    for (int trial_index = 0; trial_index < 64; ++trial_index) {
        result.final_stationarity =
            al_vector_scaled_stationarity(current.gradient);
        if (result.final_stationarity <= stationarity_limit) {
            result.passed = true;
            return result;
        }
        ALDividedPrivateInnerTrial record;
        record.trial = trial_index;
        record.current_position = result.position;
        record.stationarity_before = result.final_stationarity;
        record.radius_before = trust_radius;
        int hvp_calls = 0;
        const std::vector<Vec3> step = al_vector_trust_step(
            result.position, boundary, multiplier, current.gradient,
            trust_radius, hvp_calls, record.negative_curvature);
        const std::vector<Vec3> image = apply_al_vector_inner_hessian(
            result.position, boundary, multiplier, step);
        ++hvp_calls;
        record.hvp_calls = hvp_calls;
        result.hvp_calls += hvp_calls;
        record.step_norm = vector_norm(step);
        const double gradient_step = flat_dot(current.gradient, step);
        record.predicted_reduction = -gradient_step
            - 0.5 * flat_dot(step, image);
        const std::vector<Vec3> trial_position = add_scaled(
            result.position, step, 1.0);
        record.trial_position = trial_position;
        ALVectorInnerState trial = evaluate_al_vector_inner(
            trial_position, predicted, boundary, multiplier);
        record.raw_reduction = current.total - trial.total;
        record.direct_reduction = al_vector_direct_actual_reduction(
            result.position, trial_position, predicted,
            current.support, trial.support);
        const Binary64DividedDifference divided =
            evaluate_al_vector_inner_divided_difference(
                result.position, trial_position, predicted,
                boundary, multiplier);
        const Binary64DividedDifference divided_repeat =
            evaluate_al_vector_inner_divided_difference(
                result.position, trial_position, predicted,
                boundary, multiplier);
        record.divided_repeat_exact =
            al_binary64_divided_difference_exact(divided, divided_repeat);
        result.divided_repeat_exact = result.divided_repeat_exact
            && record.divided_repeat_exact;
        record.divided_reduction = divided.reduction;
        record.phr_reduction = divided.phr_reduction;
        record.inertia_reduction = divided.inertia_reduction;
        record.support_crossings = divided.support_crossings;
        record.kernel_segment_crossings =
            divided.kernel_segment_crossings;
        record.phr_branch_crossings = divided.phr_branch_crossings;
        record.divided_ratio = record.predicted_reduction > 0.0
            ? record.divided_reduction / record.predicted_reduction
            : -std::numeric_limits<double>::infinity();
        const double raw_ratio = record.predicted_reduction > 0.0
            ? record.raw_reduction / record.predicted_reduction
            : -std::numeric_limits<double>::infinity();
        record.raw_would_accept = trial.support.finite_values
            && record.predicted_reduction > 0.0
            && record.raw_reduction > 0.0 && raw_ratio >= 0.1;
        record.candidate_accepted = trial.support.finite_values
            && divided.finite_values && record.divided_repeat_exact
            && record.predicted_reduction > 0.0
            && record.divided_reduction > 0.0
            && record.divided_ratio >= 0.1;
        record.candidate_effect = record.candidate_accepted
            && !record.raw_would_accept;
        result.candidate_effect = result.candidate_effect
            || record.candidate_effect;
        record.finite_values = trial.support.finite_values
            && divided.finite_values
            && std::isfinite(record.stationarity_before)
            && std::isfinite(record.radius_before)
            && std::isfinite(record.step_norm)
            && std::isfinite(record.predicted_reduction)
            && std::isfinite(record.raw_reduction)
            && std::isfinite(record.direct_reduction)
            && std::isfinite(record.divided_reduction)
            && std::isfinite(record.divided_ratio)
            && std::isfinite(record.phr_reduction)
            && std::isfinite(record.inertia_reduction);
        result.all_finite = result.all_finite && record.finite_values;
        if (record.candidate_accepted) {
            ALStepNormInnerTrial oracle_input;
            oracle_input.current_position = result.position;
            oracle_input.trial_position = trial_position;
            const LongDoubleTrialEnergyAudit oracle =
                audit_al_vector_inner_long_double(
                    oracle_input, predicted, boundary, multiplier);
            record.oracle_audited = true;
            record.oracle_resolved = oracle.resolved;
            record.oracle_resolved_positive = oracle.resolved_positive;
            record.oracle_resolved_negative = oracle.resolved_negative;
            record.oracle_reduction = oracle.compensated_reduction;
            record.oracle_ulp_ratio = oracle.compensated_ulp_ratio;
            result.all_finite = result.all_finite && oracle.finite_values;
            if (oracle.resolved_positive) {
                ++result.resolved_positive_acceptances;
            } else if (oracle.resolved_negative) {
                ++result.resolved_negative_acceptances;
            } else {
                ++result.unresolved_acceptances;
            }
        }
        if (record.divided_ratio < 0.25) {
            bool used_step_norm = false;
            bool invalid_interpolation = false;
            const bool interior = !record.candidate_accepted
                && record.step_norm < 0.9 * trust_radius;
            trust_radius = al_step_norm_rejected_radius(
                trust_radius, record.step_norm, gradient_step,
                record.divided_reduction, interior,
                used_step_norm, invalid_interpolation);
            if (used_step_norm) {
                record.radius_owner = "STEP_NORM";
                ++result.step_norm_updates;
            } else {
                record.radius_owner = "QUARTER";
                ++result.quarter_updates;
            }
            result.invalid_interpolation_owned =
                result.invalid_interpolation_owned
                || (invalid_interpolation && used_step_norm);
        } else if (record.divided_ratio > 0.75
            && record.step_norm >= 0.9 * trust_radius) {
            trust_radius = std::min(
                2.0 * trust_radius, 2.0 * SPACING);
            record.radius_owner = "NONE";
        } else {
            record.radius_owner = "NONE";
        }
        record.radius_after = trust_radius;
        if (record.candidate_accepted) {
            ++result.accepted_trials;
            result.positive_accepted_models =
                result.positive_accepted_models
                && record.predicted_reduction > 0.0
                && record.divided_reduction > 0.0
                && record.divided_ratio >= 0.1;
            result.position = trial_position;
            current = std::move(trial);
        } else {
            ++result.rejected_trials;
            if (result.rejected_trials > 8) {
                result.failure = "REJECT_LIMIT";
                result.trials.push_back(std::move(record));
                return result;
            }
        }
        result.trials.push_back(std::move(record));
        if (trust_radius < 1.0e-14) {
            result.failure = "MINIMUM_TRUST_RADIUS";
            return result;
        }
    }
    result.failure = "OUTER_LIMIT";
    return result;
}

ALDividedPrivateInnerSolve solve_al_sparse_divided_private_inner(
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& initial,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier,
    double stationarity_limit,
    double time_step,
    ALSparseWorkTrace* work,
    ALSparsePrecisionTransactionContext* precision_context = nullptr,
    double kappa = KAPPA) {
    ALDividedPrivateInnerSolve result;
    result.position = initial;
    ALSparseStructuralBudget* structural_budget =
        precision_context != nullptr
        ? precision_context->structural_budget : nullptr;
    if (!std::isfinite(time_step) || time_step <= 0.0
        || !std::isfinite(kappa) || kappa <= 0.0) {
        result.all_finite = false;
        result.failure = "AL_SCALE_INVALID";
        return result;
    }
    if (precision_context != nullptr
        && (precision_context->binding == nullptr
            || !precision_context->binding->passed
            || precision_context->binding->index == nullptr
            || precision_context->binding->index->identity_sha256
                != precision_context->binding
                    ->expected_identity_sha256)) {
        result.all_finite = false;
        result.failure = "STATIC_SUPPORT_INDEX_IDENTITY";
        return result;
    }
    if (precision_context != nullptr
        && precision_context->structural_budget != nullptr
        && !al_sparse_structural_budget_valid(
            *precision_context->structural_budget)) {
        precision_context->structural_budget->exhausted = true;
        precision_context->structural_budget->failure =
            "STRUCTURAL_BUDGET_INVALID";
        result.all_finite = false;
        result.failure = "STRUCTURAL_BUDGET_INVALID";
        return result;
    }
    if (!al_sparse_budget_consume_workspace(structural_budget)) {
        result.failure = structural_budget->failure;
        return result;
    }
    const auto evaluate = [&](const std::vector<Vec3>& position) {
        return precision_context != nullptr
            ? evaluate_al_sparse_inner_with_static_support(
                position, predicted, *precision_context->binding,
                multiplier, time_step, work,
                precision_context->static_work,
                precision_context->adjacency_work, kappa)
            : evaluate_al_sparse_inner(
                position, predicted, boundary, multiplier,
                time_step, work, kappa);
    };
    ALSparseInnerState current = evaluate(result.position);
    if (!current.passed) {
        result.all_finite = false;
        result.failure = "INITIAL_NONFINITE";
        release_al_sparse_workspace(current.workspace, work);
        return result;
    }
    double trust_radius = 0.25 * SPACING;
    for (int trial_index = 0; trial_index < 64; ++trial_index) {
        result.final_stationarity =
            al_sparse_scaled_stationarity(current.gradient, time_step);
        if (result.final_stationarity <= stationarity_limit) {
            result.passed = true;
            release_al_sparse_workspace(current.workspace, work);
            return result;
        }
        if (!al_sparse_budget_begin_inner_trial(structural_budget)) {
            result.failure = structural_budget->failure;
            release_al_sparse_workspace(current.workspace, work);
            return result;
        }
        ALDividedPrivateInnerTrial record;
        record.trial = trial_index;
        record.current_position = result.position;
        record.stationarity_before = result.final_stationarity;
        record.radius_before = trust_radius;
        int hvp_calls = 0;
        const std::vector<Vec3> step = al_sparse_trust_step(
            current.workspace, current.gradient, trust_radius,
            time_step, hvp_calls, record.negative_curvature,
            structural_budget);
        if (structural_budget != nullptr
            && structural_budget->exhausted) {
            result.hvp_calls += hvp_calls;
            result.failure = structural_budget->failure;
            release_al_sparse_workspace(current.workspace, work);
            return result;
        }
        if (!al_sparse_budget_consume_hvp(structural_budget)) {
            result.hvp_calls += hvp_calls;
            result.failure = structural_budget->failure;
            release_al_sparse_workspace(current.workspace, work);
            return result;
        }
        const std::vector<Vec3> image = apply_al_sparse_inner_hessian(
            current.workspace, step, time_step);
        ++hvp_calls;
        record.hvp_calls = hvp_calls;
        result.hvp_calls += hvp_calls;
        record.step_norm = vector_norm(step);
        const double gradient_step = flat_dot(current.gradient, step);
        record.predicted_reduction = -gradient_step
            - 0.5 * flat_dot(step, image);
        const std::vector<Vec3> trial_position = add_scaled(
            result.position, step, 1.0);
        record.trial_position = trial_position;
        if (!al_sparse_budget_consume_workspace(structural_budget)) {
            result.failure = structural_budget->failure;
            release_al_sparse_workspace(current.workspace, work);
            return result;
        }
        ALSparseInnerState trial = evaluate(trial_position);
        record.raw_reduction = current.total - trial.total;
        record.direct_reduction = al_vector_direct_actual_reduction_dt(
            result.position, trial_position, predicted,
            current.workspace.support, trial.workspace.support,
            time_step, kappa);
        const Binary64DividedDifference divided =
            evaluate_al_sparse_inner_divided_difference(
                current.workspace, trial.workspace, predicted,
                multiplier, time_step, work, kappa);
        const Binary64DividedDifference divided_repeat =
            evaluate_al_sparse_inner_divided_difference(
                current.workspace, trial.workspace, predicted,
                multiplier, time_step, nullptr, kappa);
        record.divided_repeat_exact =
            al_binary64_divided_difference_exact(divided, divided_repeat);
        result.divided_repeat_exact = result.divided_repeat_exact
            && record.divided_repeat_exact;
        record.divided_reduction = divided.reduction;
        record.phr_reduction = divided.phr_reduction;
        record.inertia_reduction = divided.inertia_reduction;
        record.support_crossings = divided.support_crossings;
        record.kernel_segment_crossings =
            divided.kernel_segment_crossings;
        record.phr_branch_crossings = divided.phr_branch_crossings;
        record.divided_ratio = record.predicted_reduction > 0.0
            ? record.divided_reduction / record.predicted_reduction
            : -std::numeric_limits<double>::infinity();
        const double raw_ratio = record.predicted_reduction > 0.0
            ? record.raw_reduction / record.predicted_reduction
            : -std::numeric_limits<double>::infinity();
        record.raw_would_accept = trial.passed
            && record.predicted_reduction > 0.0
            && record.raw_reduction > 0.0 && raw_ratio >= 0.1;
        record.candidate_accepted = trial.passed
            && divided.finite_values && record.divided_repeat_exact
            && record.predicted_reduction > 0.0
            && record.divided_reduction > 0.0
            && record.divided_ratio >= 0.1;
        record.candidate_effect = record.candidate_accepted
            && !record.raw_would_accept;
        result.candidate_effect = result.candidate_effect
            || record.candidate_effect;
        record.finite_values = trial.passed
            && divided.finite_values
            && std::isfinite(record.stationarity_before)
            && std::isfinite(record.radius_before)
            && std::isfinite(record.step_norm)
            && std::isfinite(record.predicted_reduction)
            && std::isfinite(record.raw_reduction)
            && std::isfinite(record.direct_reduction)
            && std::isfinite(record.divided_reduction)
            && std::isfinite(record.divided_ratio)
            && std::isfinite(record.phr_reduction)
            && std::isfinite(record.inertia_reduction);
        result.all_finite = result.all_finite && record.finite_values;
        if (record.candidate_accepted) {
            if (!al_sparse_budget_consume_precision_audit(
                    structural_budget)) {
                result.failure = structural_budget->failure;
                release_al_sparse_workspace(trial.workspace, work);
                release_al_sparse_workspace(current.workspace, work);
                return result;
            }
            ALStepNormInnerTrial oracle_input;
            oracle_input.current_position = result.position;
            oracle_input.trial_position = trial_position;
            const LongDoubleTrialEnergyAudit oracle =
                precision_context != nullptr
                ? audit_al_sparse_inner_long_double(
                    oracle_input, predicted, multiplier,
                    *precision_context->binding, time_step,
                    precision_context->precision_work, kappa)
                : audit_al_vector_inner_long_double(
                    oracle_input, predicted, boundary, multiplier,
                    time_step, kappa);
            if (precision_context != nullptr
                && precision_context->long_double_audits != nullptr) {
                precision_context->long_double_audits->push_back(oracle);
            }
            record.oracle_audited = true;
            record.oracle_resolved = oracle.resolved;
            record.oracle_resolved_positive = oracle.resolved_positive;
            record.oracle_resolved_negative = oracle.resolved_negative;
            record.oracle_reduction = oracle.compensated_reduction;
            record.oracle_ulp_ratio = oracle.compensated_ulp_ratio;
            result.all_finite = result.all_finite && oracle.finite_values;
            if (oracle.resolved_positive) {
                ++result.resolved_positive_acceptances;
            } else if (oracle.resolved_negative) {
                ++result.resolved_negative_acceptances;
            } else {
                ++result.unresolved_acceptances;
            }
        }
        if (record.divided_ratio < 0.25) {
            bool used_step_norm = false;
            bool invalid_interpolation = false;
            const bool interior = !record.candidate_accepted
                && record.step_norm < 0.9 * trust_radius;
            trust_radius = al_step_norm_rejected_radius(
                trust_radius, record.step_norm, gradient_step,
                record.divided_reduction, interior,
                used_step_norm, invalid_interpolation);
            if (used_step_norm) {
                record.radius_owner = "STEP_NORM";
                ++result.step_norm_updates;
            } else {
                record.radius_owner = "QUARTER";
                ++result.quarter_updates;
            }
            result.invalid_interpolation_owned =
                result.invalid_interpolation_owned
                || (invalid_interpolation && used_step_norm);
        } else if (record.divided_ratio > 0.75
            && record.step_norm >= 0.9 * trust_radius) {
            trust_radius = std::min(
                2.0 * trust_radius, 2.0 * SPACING);
            record.radius_owner = "NONE";
        } else {
            record.radius_owner = "NONE";
        }
        record.radius_after = trust_radius;
        if (record.candidate_accepted) {
            ++result.accepted_trials;
            result.positive_accepted_models =
                result.positive_accepted_models
                && record.predicted_reduction > 0.0
                && record.divided_reduction > 0.0
                && record.divided_ratio >= 0.1;
            result.position = trial_position;
            release_al_sparse_workspace(current.workspace, work);
            current = std::move(trial);
        } else {
            ++result.rejected_trials;
            release_al_sparse_workspace(trial.workspace, work);
            if (result.rejected_trials > 8) {
                result.failure = "REJECT_LIMIT";
                result.trials.push_back(std::move(record));
                release_al_sparse_workspace(current.workspace, work);
                return result;
            }
        }
        result.trials.push_back(std::move(record));
        if (trust_radius < 1.0e-14) {
            result.failure = "MINIMUM_TRUST_RADIUS";
            release_al_sparse_workspace(current.workspace, work);
            return result;
        }
    }
    result.failure = "OUTER_LIMIT";
    release_al_sparse_workspace(current.workspace, work);
    return result;
}

std::string al_divided_private_inner_root(
    const ALDividedPrivateInnerSolve& value) {
    std::ostringstream projection;
    projection << std::setprecision(
                      std::numeric_limits<long double>::max_digits10)
               << value.passed << ':' << value.all_finite << ':'
               << value.divided_repeat_exact << ':'
               << value.positive_accepted_models << ':'
               << value.invalid_interpolation_owned << ':'
               << value.candidate_effect << ':' << value.failure << ':'
               << value.accepted_trials << ':' << value.rejected_trials
               << ':' << value.hvp_calls << ':'
               << value.step_norm_updates << ':' << value.quarter_updates
               << ':' << value.resolved_positive_acceptances << ':'
               << value.resolved_negative_acceptances << ':'
               << value.unresolved_acceptances << ':'
               << value.final_stationarity << '|';
    for (Vec3 position : value.position) {
        projection << position.x << ':' << position.y << ':' << position.z
                   << ';';
    }
    projection << '|';
    for (const ALDividedPrivateInnerTrial& trial : value.trials) {
        projection << trial.trial << ':' << trial.finite_values << ':'
                   << trial.divided_repeat_exact << ':'
                   << trial.raw_would_accept << ':'
                   << trial.candidate_accepted << ':'
                   << trial.candidate_effect << ':'
                   << trial.negative_curvature << ':'
                   << trial.oracle_audited << ':' << trial.oracle_resolved
                   << ':' << trial.oracle_resolved_positive << ':'
                   << trial.oracle_resolved_negative << ':'
                   << trial.hvp_calls << ':' << trial.radius_owner << ':'
                   << trial.stationarity_before << ':' << trial.radius_before
                   << ':' << trial.radius_after << ':' << trial.step_norm
                   << ':' << trial.predicted_reduction << ':'
                   << trial.raw_reduction << ':' << trial.direct_reduction
                   << ':' << trial.divided_reduction << ':'
                   << trial.divided_ratio << ':' << trial.phr_reduction << ':'
                   << trial.inertia_reduction << ':'
                   << trial.support_crossings << ':'
                   << trial.kernel_segment_crossings << ':'
                   << trial.phr_branch_crossings << ':'
                   << trial.oracle_reduction << ':'
                   << trial.oracle_ulp_ratio << ';';
    }
    return sha256_hex(projection.str());
}

__extension__ typedef __float128 Binary128;

struct Binary128Accumulator {
    Binary128 sum = static_cast<Binary128>(0.0);
    Binary128 correction = static_cast<Binary128>(0.0);

    void add(Binary128 value) {
        const Binary128 next = sum + value;
        correction += fabsq(sum) >= fabsq(value)
            ? (sum - next) + value
            : (value - next) + sum;
        sum = next;
    }

    Binary128 value() const {
        return sum + correction;
    }
};

struct Binary128Vec3 {
    Binary128 x = static_cast<Binary128>(0.0);
    Binary128 y = static_cast<Binary128>(0.0);
    Binary128 z = static_cast<Binary128>(0.0);
};

Binary128Vec3 al_binary128_vec3(Vec3 value) {
    return {static_cast<Binary128>(value.x),
        static_cast<Binary128>(value.y),
        static_cast<Binary128>(value.z)};
}

Binary128Vec3 operator-(Binary128Vec3 lhs, Binary128Vec3 rhs) {
    return {lhs.x - rhs.x, lhs.y - rhs.y, lhs.z - rhs.z};
}

Binary128 al_binary128_norm(Binary128Vec3 value) {
    return sqrtq(value.x * value.x + value.y * value.y
        + value.z * value.z);
}

Binary128 al_binary128_weight(Binary128 radius) {
    const Binary128 two = static_cast<Binary128>(2.0);
    const Binary128 horizon = static_cast<Binary128>(HORIZON);
    const Binary128 q = two * radius / horizon;
    const Binary128 alpha = static_cast<Binary128>(3.0)
        / (two * static_cast<Binary128>(PI)
            * horizon * horizon * horizon);
    Binary128 raw = static_cast<Binary128>(0.0);
    if (q > two) {
        raw = static_cast<Binary128>(0.0);
    } else if (q >= static_cast<Binary128>(1.0)) {
        const Binary128 delta = two - q;
        raw = alpha * delta * delta * delta
            / static_cast<Binary128>(6.0);
    } else {
        raw = alpha * (static_cast<Binary128>(2.0)
                / static_cast<Binary128>(3.0)
            - q * q + static_cast<Binary128>(0.5) * q * q * q);
    }
    return static_cast<Binary128>(kernel_scale()) * raw;
}

struct Binary128EnergyEvaluation {
    bool finite_values = false;
    Binary128 total = static_cast<Binary128>(0.0);
    Binary128 phr = static_cast<Binary128>(0.0);
    Binary128 inertia = static_cast<Binary128>(0.0);
    std::size_t fluid_pairs = 0U;
    std::size_t boundary_pairs = 0U;
    std::size_t membership_mismatches = 0U;
};

Binary128EnergyEvaluation evaluate_al_vector_inner_binary128(
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier,
    bool compensated,
    double time_step = TIME_STEP,
    double penalty = KAPPA) {
    Binary128EnergyEvaluation result;
    if (position.size() != predicted.size()
        || position.size() != multiplier.size()
        || !std::isfinite(time_step) || time_step <= 0.0
        || !std::isfinite(penalty) || penalty <= 0.0) {
        return result;
    }
    const std::size_t count = position.size();
    std::vector<Binary128Vec3> fluid(count);
    std::vector<Binary128Vec3> predicted_quad(count);
    std::vector<Binary128Vec3> support(boundary.size());
    std::transform(position.begin(), position.end(), fluid.begin(),
        al_binary128_vec3);
    std::transform(predicted.begin(), predicted.end(),
        predicted_quad.begin(), al_binary128_vec3);
    std::transform(boundary.begin(), boundary.end(), support.begin(),
        al_binary128_vec3);
    const Binary128 mass = static_cast<Binary128>(MASS);
    const Binary128 rest_density = static_cast<Binary128>(REST_DENSITY);
    const Binary128 kappa = static_cast<Binary128>(penalty);
    const Binary128 horizon = static_cast<Binary128>(HORIZON);
    std::vector<Binary128> density(
        count, mass * al_binary128_weight(static_cast<Binary128>(0.0)));
    std::vector<Binary128> density_correction(
        count, static_cast<Binary128>(0.0));
    const auto add_density = [&](std::size_t center, Binary128 value) {
        if (!compensated) {
            density[center] += value;
            return;
        }
        const Binary128 adjusted = value - density_correction[center];
        const Binary128 next = density[center] + adjusted;
        density_correction[center] =
            (next - density[center]) - adjusted;
        density[center] = next;
    };
    const auto member = [&](double binary_radius, Binary128 quad_radius) {
        const bool binary_member = binary_radius <= HORIZON;
        const bool quad_member = quad_radius <= horizon;
        result.membership_mismatches +=
            binary_member == quad_member ? 0U : 1U;
        return quad_member;
    };
    for (std::size_t i = 0U; i < count; ++i) {
        for (std::size_t j = i + 1U; j < count; ++j) {
            const double binary_radius = norm(position[i] - position[j]);
            const Binary128 quad_radius = al_binary128_norm(
                fluid[i] - fluid[j]);
            if (member(binary_radius, quad_radius)) {
                const Binary128 contribution = mass
                    * al_binary128_weight(quad_radius);
                add_density(i, contribution);
                add_density(j, contribution);
                ++result.fluid_pairs;
            }
        }
        for (std::size_t index = 0U; index < support.size(); ++index) {
            const double binary_radius = norm(
                position[i] - boundary[index]);
            const Binary128 quad_radius = al_binary128_norm(
                fluid[i] - support[index]);
            if (member(binary_radius, quad_radius)) {
                add_density(i, mass * al_binary128_weight(quad_radius));
                ++result.boundary_pairs;
            }
        }
    }
    Binary128Accumulator phr_compensated;
    Binary128Accumulator inertia_compensated;
    Binary128 phr_naive = static_cast<Binary128>(0.0);
    Binary128 inertia_naive = static_cast<Binary128>(0.0);
    const Binary128 time_step_quad = static_cast<Binary128>(time_step);
    const Binary128 inertia_scale = mass
        / (time_step_quad * time_step_quad);
    for (std::size_t center = 0U; center < count; ++center) {
        const Binary128 constraint =
            density[center] / rest_density - static_cast<Binary128>(1.0);
        const Binary128 lambda =
            static_cast<Binary128>(multiplier[center]);
        const Binary128 unclamped = lambda + kappa * constraint;
        const Binary128 active = std::max(
            static_cast<Binary128>(0.0), unclamped);
        const Binary128 phr_term =
            (active * active - lambda * lambda)
            / (static_cast<Binary128>(2.0) * kappa);
        const Binary128Vec3 displacement =
            fluid[center] - predicted_quad[center];
        const Binary128 inertia_term = static_cast<Binary128>(0.5)
            * inertia_scale * (displacement.x * displacement.x
                + displacement.y * displacement.y
                + displacement.z * displacement.z);
        if (compensated) {
            phr_compensated.add(phr_term);
            inertia_compensated.add(inertia_term);
        } else {
            phr_naive += phr_term;
            inertia_naive += inertia_term;
        }
    }
    result.phr = compensated ? phr_compensated.value() : phr_naive;
    result.inertia = compensated
        ? inertia_compensated.value() : inertia_naive;
    if (compensated) {
        Binary128Accumulator total;
        total.add(result.phr);
        total.add(result.inertia);
        result.total = total.value();
    } else {
        result.total = result.phr + result.inertia;
    }
    result.finite_values = finiteq(result.total) != 0
        && finiteq(result.phr) != 0 && finiteq(result.inertia) != 0;
    return result;
}

struct Binary128TrialEnergyAudit {
    Binary128EnergyEvaluation current_naive;
    Binary128EnergyEvaluation current_compensated;
    Binary128EnergyEvaluation trial_naive;
    Binary128EnergyEvaluation trial_compensated;
    bool finite_values = false;
    bool sign_agrees = false;
    bool resolved = false;
    bool resolved_positive = false;
    bool resolved_negative = false;
    bool membership_exact = false;
    bool candidate_pass = false;
    Binary128 naive_reduction = static_cast<Binary128>(0.0);
    Binary128 compensated_reduction = static_cast<Binary128>(0.0);
    Binary128 ulp = static_cast<Binary128>(0.0);
    Binary128 naive_ulp_ratio = static_cast<Binary128>(0.0);
    Binary128 compensated_ulp_ratio = static_cast<Binary128>(0.0);
    Binary128 candidate_relative_error = static_cast<Binary128>(0.0);
};

struct ALBinary128PairUnion {
    bool passed = false;
    std::string failure;
    std::size_t fluid_count = 0U;
    std::size_t support_count = 0U;
    std::vector<JointPair> pairs;
};

ALBinary128PairUnion build_al_binary128_pair_union(
    const std::vector<Vec3>& current_position,
    const std::vector<Vec3>& trial_position,
    const JointStaticSupportBinding& binding,
    ALSparsePrecisionWorkTrace* work = nullptr) {
    ALBinary128PairUnion result;
    if (current_position.size() != trial_position.size()
        || !binding.passed || binding.index == nullptr
        || binding.index->identity_sha256
            != binding.expected_identity_sha256) {
        result.failure = "AL_BINARY128_UNION_SOURCE";
        return result;
    }
    const JointNeighborhood current = b4ep3_build_superset(
        tagged_points(current_position), binding);
    const JointNeighborhood trial = b4ep3_build_superset(
        tagged_points(trial_position), binding);
    if (work != nullptr) {
        work->superset_builds += 2U;
    }
    if (!current.passed || !trial.passed
        || current.fluid.size() != trial.fluid.size()
        || current.support.size() != trial.support.size()) {
        result.failure = !current.passed
            ? current.failure
            : (!trial.passed ? trial.failure
                : "AL_BINARY128_UNION_LAYOUT");
        return result;
    }
    for (std::size_t index = 0U; index < current.fluid.size(); ++index) {
        if (current.fluid[index].id != trial.fluid[index].id) {
            result.failure = "AL_BINARY128_UNION_FLUID_IDENTITY";
            return result;
        }
    }
    for (std::size_t index = 0U; index < current.support.size(); ++index) {
        if (current.support[index].id != trial.support[index].id
            || binary64_bits(current.support[index].position.x)
                != binary64_bits(trial.support[index].position.x)
            || binary64_bits(current.support[index].position.y)
                != binary64_bits(trial.support[index].position.y)
            || binary64_bits(current.support[index].position.z)
                != binary64_bits(trial.support[index].position.z)) {
            result.failure = "AL_BINARY128_UNION_SUPPORT_IDENTITY";
            return result;
        }
    }
    result.fluid_count = current.fluid.size();
    result.support_count = current.support.size();
    if (current.pairs.size() > std::numeric_limits<std::size_t>::max()
            - trial.pairs.size()) {
        result.failure = "AL_BINARY128_UNION_CAPACITY";
        return result;
    }
    result.pairs.reserve(current.pairs.size() + trial.pairs.size());
    std::size_t current_index = 0U;
    std::size_t trial_index = 0U;
    while (current_index < current.pairs.size()
        || trial_index < trial.pairs.size()) {
        if (trial_index == trial.pairs.size()
            || (current_index < current.pairs.size()
                && al_joint_pair_less(current.pairs[current_index],
                    trial.pairs[trial_index]))) {
            result.pairs.push_back(current.pairs[current_index++]);
        } else if (current_index == current.pairs.size()
            || al_joint_pair_less(trial.pairs[trial_index],
                current.pairs[current_index])) {
            result.pairs.push_back(trial.pairs[trial_index++]);
        } else {
            result.pairs.push_back(current.pairs[current_index]);
            ++current_index;
            ++trial_index;
        }
    }
    if (!std::is_sorted(result.pairs.begin(), result.pairs.end(),
            al_joint_pair_less)
        || std::adjacent_find(result.pairs.begin(), result.pairs.end())
            != result.pairs.end()) {
        result.failure = "AL_BINARY128_UNION_ORDER";
        return result;
    }
    if (work != nullptr) {
        work->union_candidate_pairs += result.pairs.size();
    }
    result.passed = true;
    return result;
}

LongDoubleEnergyEvaluation evaluate_al_sparse_inner_long_double(
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& predicted,
    const std::vector<double>& multiplier,
    const JointStaticSupportBinding& binding,
    const ALBinary128PairUnion& candidate_union,
    bool compensated,
    double time_step,
    ALSparsePrecisionWorkTrace* work = nullptr,
    double penalty = KAPPA) {
    LongDoubleEnergyEvaluation result;
    if (!candidate_union.passed || !binding.passed
        || binding.index == nullptr
        || binding.index->identity_sha256
            != binding.expected_identity_sha256
        || position.size() != predicted.size()
        || position.size() != multiplier.size()
        || position.size() != candidate_union.fluid_count
        || binding.index->support.size()
            != candidate_union.support_count
        || !std::isfinite(time_step) || time_step <= 0.0
        || !std::isfinite(penalty) || penalty <= 0.0) {
        return result;
    }
    const std::size_t count = position.size();
    std::vector<LongDoubleVec3> fluid(count);
    std::vector<LongDoubleVec3> predicted_extended(count);
    std::vector<LongDoubleVec3> support(binding.index->support.size());
    std::transform(position.begin(), position.end(), fluid.begin(),
        al_long_double_vec3);
    std::transform(predicted.begin(), predicted.end(),
        predicted_extended.begin(), al_long_double_vec3);
    std::transform(binding.index->support.begin(),
        binding.index->support.end(), support.begin(),
        [](const JointPoint& point) {
            return al_long_double_vec3(point.position);
        });
    const long double mass = static_cast<long double>(MASS);
    const long double rest_density =
        static_cast<long double>(REST_DENSITY);
    const long double kappa = static_cast<long double>(penalty);
    const long double horizon = static_cast<long double>(HORIZON);
    const long double half_horizon = 0.5L * horizon;
    std::vector<long double> density(
        count, mass * al_long_double_weight(0.0L));
    std::vector<long double> density_correction(count, 0.0L);
    const auto add_density = [&](std::size_t center, long double value) {
        if (!compensated) {
            density[center] += value;
            return;
        }
        const long double adjusted = value - density_correction[center];
        const long double next = density[center] + adjusted;
        density_correction[center] =
            (next - density[center]) - adjusted;
        density[center] = next;
    };
    for (const JointPair pair : candidate_union.pairs) {
        if (work != nullptr) {
            ++work->long_double_evaluation_pair_visits;
        }
        if (pair.fluid >= count
            || pair.participant >= count + support.size()
            || (pair.participant < count
                && pair.participant <= pair.fluid)) {
            return LongDoubleEnergyEvaluation{};
        }
        const Vec3 participant = pair.participant < count
            ? position[pair.participant]
            : binding.index->support[
                pair.participant - count].position;
        const LongDoubleVec3 participant_extended =
            pair.participant < count
            ? fluid[pair.participant]
            : support[pair.participant - count];
        const double binary_radius = norm(
            position[pair.fluid] - participant);
        const long double extended_radius = al_long_double_norm(
            fluid[pair.fluid] - participant_extended);
        result.minimum_half_horizon_margin = std::min(
            result.minimum_half_horizon_margin,
            std::abs(extended_radius - half_horizon));
        result.minimum_horizon_margin = std::min(
            result.minimum_horizon_margin,
            std::abs(extended_radius - horizon));
        const bool binary_member = binary_radius <= HORIZON;
        const bool extended_member = extended_radius <= horizon;
        result.membership_mismatches +=
            binary_member == extended_member ? 0U : 1U;
        if (!extended_member) {
            continue;
        }
        const long double contribution = mass
            * al_long_double_weight(extended_radius);
        add_density(pair.fluid, contribution);
        if (pair.participant < count) {
            add_density(pair.participant, contribution);
            ++result.fluid_pairs;
        } else {
            ++result.boundary_pairs;
        }
    }
    LongDoubleAccumulator phr_compensated;
    LongDoubleAccumulator inertia_compensated;
    long double phr_naive = 0.0L;
    long double inertia_naive = 0.0L;
    const long double time_step_extended =
        static_cast<long double>(time_step);
    const long double inertia_scale = mass
        / (time_step_extended * time_step_extended);
    for (std::size_t center = 0U; center < count; ++center) {
        const long double constraint =
            density[center] / rest_density - 1.0L;
        const long double lambda =
            static_cast<long double>(multiplier[center]);
        const long double active = std::max(
            0.0L, lambda + kappa * constraint);
        const long double phr_term =
            (active * active - lambda * lambda) / (2.0L * kappa);
        const LongDoubleVec3 displacement =
            fluid[center] - predicted_extended[center];
        const long double inertia_term = 0.5L * inertia_scale
            * (displacement.x * displacement.x
                + displacement.y * displacement.y
                + displacement.z * displacement.z);
        if (compensated) {
            phr_compensated.add(phr_term);
            inertia_compensated.add(inertia_term);
        } else {
            phr_naive += phr_term;
            inertia_naive += inertia_term;
        }
    }
    result.phr = compensated ? phr_compensated.sum : phr_naive;
    result.inertia = compensated
        ? inertia_compensated.sum : inertia_naive;
    if (compensated) {
        LongDoubleAccumulator total;
        total.add(result.phr);
        total.add(result.inertia);
        result.total = total.sum;
    } else {
        result.total = result.phr + result.inertia;
    }
    result.finite_values = std::isfinite(result.total)
        && std::isfinite(result.phr) && std::isfinite(result.inertia)
        && std::isfinite(result.minimum_half_horizon_margin)
        && std::isfinite(result.minimum_horizon_margin);
    return result;
}

LongDoubleTrialEnergyAudit finalize_al_long_double_trial_energy_audit(
    LongDoubleEnergyEvaluation current_naive,
    LongDoubleEnergyEvaluation current_compensated,
    LongDoubleEnergyEvaluation trial_naive,
    LongDoubleEnergyEvaluation trial_compensated) {
    LongDoubleTrialEnergyAudit result;
    result.current_naive = std::move(current_naive);
    result.current_compensated = std::move(current_compensated);
    result.trial_naive = std::move(trial_naive);
    result.trial_compensated = std::move(trial_compensated);
    result.naive_reduction = result.current_naive.total
        - result.trial_naive.total;
    result.compensated_reduction = result.current_compensated.total
        - result.trial_compensated.total;
    result.extended_ulp = std::max(
        std::nextafter(result.current_compensated.total,
            std::numeric_limits<long double>::infinity())
            - result.current_compensated.total,
        std::nextafter(result.trial_compensated.total,
            std::numeric_limits<long double>::infinity())
            - result.trial_compensated.total);
    result.naive_ulp_ratio = result.extended_ulp > 0.0L
        ? result.naive_reduction / result.extended_ulp : 0.0L;
    result.compensated_ulp_ratio = result.extended_ulp > 0.0L
        ? result.compensated_reduction / result.extended_ulp : 0.0L;
    result.sign_agrees =
        (result.naive_reduction > 0.0L
            && result.compensated_reduction > 0.0L)
        || (result.naive_reduction < 0.0L
            && result.compensated_reduction < 0.0L);
    const long double resolution = 1024.0L * result.extended_ulp;
    result.resolved = result.sign_agrees
        && std::abs(result.naive_reduction) >= resolution
        && std::abs(result.compensated_reduction) >= resolution;
    result.resolved_positive = result.resolved
        && result.compensated_reduction > 0.0L;
    result.resolved_negative = result.resolved
        && result.compensated_reduction < 0.0L;
    result.topology_precision_mismatch =
        result.current_naive.membership_mismatches != 0U
        || result.current_compensated.membership_mismatches != 0U
        || result.trial_naive.membership_mismatches != 0U
        || result.trial_compensated.membership_mismatches != 0U;
    result.finite_values = result.current_naive.finite_values
        && result.current_compensated.finite_values
        && result.trial_naive.finite_values
        && result.trial_compensated.finite_values
        && std::isfinite(result.naive_reduction)
        && std::isfinite(result.compensated_reduction)
        && std::isfinite(result.extended_ulp)
        && std::isfinite(result.naive_ulp_ratio)
        && std::isfinite(result.compensated_ulp_ratio);
    return result;
}

LongDoubleTrialEnergyAudit audit_al_sparse_inner_long_double(
    const ALStepNormInnerTrial& trial,
    const std::vector<Vec3>& predicted,
    const std::vector<double>& multiplier,
    const JointStaticSupportBinding& binding,
    double time_step,
    ALSparsePrecisionWorkTrace* work,
    double penalty) {
    if (!std::isfinite(time_step) || time_step <= 0.0
        || !std::isfinite(penalty) || penalty <= 0.0) {
        return {};
    }
    if (work != nullptr) {
        ++work->long_double_audits;
    }
    const ALBinary128PairUnion candidate_union =
        build_al_binary128_pair_union(
            trial.current_position, trial.trial_position, binding, work);
    if (work != nullptr) {
        work->long_double_union_candidate_pairs +=
            candidate_union.pairs.size();
    }
    return finalize_al_long_double_trial_energy_audit(
        evaluate_al_sparse_inner_long_double(
            trial.current_position, predicted, multiplier, binding,
            candidate_union, false, time_step, work, penalty),
        evaluate_al_sparse_inner_long_double(
            trial.current_position, predicted, multiplier, binding,
            candidate_union, true, time_step, work, penalty),
        evaluate_al_sparse_inner_long_double(
            trial.trial_position, predicted, multiplier, binding,
            candidate_union, false, time_step, work, penalty),
        evaluate_al_sparse_inner_long_double(
            trial.trial_position, predicted, multiplier, binding,
            candidate_union, true, time_step, work, penalty));
}

Binary128EnergyEvaluation evaluate_al_sparse_inner_binary128(
    const std::vector<Vec3>& position,
    const std::vector<Vec3>& predicted,
    const std::vector<double>& multiplier,
    const JointStaticSupportBinding& binding,
    const ALBinary128PairUnion& candidate_union,
    bool compensated,
    double time_step,
    ALSparsePrecisionWorkTrace* work = nullptr,
    double penalty = KAPPA) {
    Binary128EnergyEvaluation result;
    if (!candidate_union.passed || !binding.passed
        || binding.index == nullptr
        || binding.index->identity_sha256
            != binding.expected_identity_sha256
        || position.size() != predicted.size()
        || position.size() != multiplier.size()
        || position.size() != candidate_union.fluid_count
        || binding.index->support.size()
            != candidate_union.support_count
        || !std::isfinite(time_step) || time_step <= 0.0
        || !std::isfinite(penalty) || penalty <= 0.0) {
        return result;
    }
    const std::size_t count = position.size();
    std::vector<Binary128Vec3> fluid(count);
    std::vector<Binary128Vec3> predicted_quad(count);
    std::vector<Binary128Vec3> support(binding.index->support.size());
    std::transform(position.begin(), position.end(), fluid.begin(),
        al_binary128_vec3);
    std::transform(predicted.begin(), predicted.end(),
        predicted_quad.begin(), al_binary128_vec3);
    std::transform(binding.index->support.begin(),
        binding.index->support.end(), support.begin(),
        [](const JointPoint& point) {
            return al_binary128_vec3(point.position);
        });
    const Binary128 mass = static_cast<Binary128>(MASS);
    const Binary128 rest_density = static_cast<Binary128>(REST_DENSITY);
    const Binary128 kappa = static_cast<Binary128>(penalty);
    const Binary128 horizon = static_cast<Binary128>(HORIZON);
    std::vector<Binary128> density(
        count, mass * al_binary128_weight(static_cast<Binary128>(0.0)));
    std::vector<Binary128> density_correction(
        count, static_cast<Binary128>(0.0));
    const auto add_density = [&](std::size_t center, Binary128 value) {
        if (!compensated) {
            density[center] += value;
            return;
        }
        const Binary128 adjusted = value - density_correction[center];
        const Binary128 next = density[center] + adjusted;
        density_correction[center] =
            (next - density[center]) - adjusted;
        density[center] = next;
    };
    for (const JointPair pair : candidate_union.pairs) {
        if (work != nullptr) {
            ++work->binary128_evaluation_pair_visits;
        }
        if (pair.fluid >= count
            || pair.participant >= count + support.size()
            || (pair.participant < count
                && pair.participant <= pair.fluid)) {
            return Binary128EnergyEvaluation{};
        }
        const Vec3 participant = pair.participant < count
            ? position[pair.participant]
            : binding.index->support[
                pair.participant - count].position;
        const Binary128Vec3 participant_quad = pair.participant < count
            ? fluid[pair.participant]
            : support[pair.participant - count];
        const double binary_radius = norm(
            position[pair.fluid] - participant);
        const Binary128 quad_radius = al_binary128_norm(
            fluid[pair.fluid] - participant_quad);
        const bool binary_member = binary_radius <= HORIZON;
        const bool quad_member = quad_radius <= horizon;
        result.membership_mismatches +=
            binary_member == quad_member ? 0U : 1U;
        if (!quad_member) {
            continue;
        }
        const Binary128 contribution = mass
            * al_binary128_weight(quad_radius);
        add_density(pair.fluid, contribution);
        if (pair.participant < count) {
            add_density(pair.participant, contribution);
            ++result.fluid_pairs;
        } else {
            ++result.boundary_pairs;
        }
    }
    Binary128Accumulator phr_compensated;
    Binary128Accumulator inertia_compensated;
    Binary128 phr_naive = static_cast<Binary128>(0.0);
    Binary128 inertia_naive = static_cast<Binary128>(0.0);
    const Binary128 time_step_quad = static_cast<Binary128>(time_step);
    const Binary128 inertia_scale = mass
        / (time_step_quad * time_step_quad);
    for (std::size_t center = 0U; center < count; ++center) {
        const Binary128 constraint = density[center] / rest_density
            - static_cast<Binary128>(1.0);
        const Binary128 lambda =
            static_cast<Binary128>(multiplier[center]);
        const Binary128 active = std::max(
            static_cast<Binary128>(0.0),
            lambda + kappa * constraint);
        const Binary128 phr_term =
            (active * active - lambda * lambda)
            / (static_cast<Binary128>(2.0) * kappa);
        const Binary128Vec3 displacement =
            fluid[center] - predicted_quad[center];
        const Binary128 inertia_term = static_cast<Binary128>(0.5)
            * inertia_scale * (displacement.x * displacement.x
                + displacement.y * displacement.y
                + displacement.z * displacement.z);
        if (compensated) {
            phr_compensated.add(phr_term);
            inertia_compensated.add(inertia_term);
        } else {
            phr_naive += phr_term;
            inertia_naive += inertia_term;
        }
    }
    result.phr = compensated ? phr_compensated.value() : phr_naive;
    result.inertia = compensated
        ? inertia_compensated.value() : inertia_naive;
    if (compensated) {
        Binary128Accumulator total;
        total.add(result.phr);
        total.add(result.inertia);
        result.total = total.value();
    } else {
        result.total = result.phr + result.inertia;
    }
    result.finite_values = finiteq(result.total) != 0
        && finiteq(result.phr) != 0 && finiteq(result.inertia) != 0;
    return result;
}

Binary128TrialEnergyAudit finalize_al_binary128_trial_energy_audit(
    Binary128EnergyEvaluation current_naive,
    Binary128EnergyEvaluation current_compensated,
    Binary128EnergyEvaluation trial_naive,
    Binary128EnergyEvaluation trial_compensated,
    double candidate_reduction) {
    Binary128TrialEnergyAudit result;
    result.current_naive = std::move(current_naive);
    result.current_compensated = std::move(current_compensated);
    result.trial_naive = std::move(trial_naive);
    result.trial_compensated = std::move(trial_compensated);
    result.naive_reduction = result.current_naive.total
        - result.trial_naive.total;
    result.compensated_reduction = result.current_compensated.total
        - result.trial_compensated.total;
    const Binary128 upward = static_cast<Binary128>(
        std::numeric_limits<double>::max());
    result.ulp = std::max(
        nextafterq(result.current_compensated.total, upward)
            - result.current_compensated.total,
        nextafterq(result.trial_compensated.total, upward)
            - result.trial_compensated.total);
    result.naive_ulp_ratio = result.ulp > static_cast<Binary128>(0.0)
        ? result.naive_reduction / result.ulp
        : static_cast<Binary128>(0.0);
    result.compensated_ulp_ratio =
        result.ulp > static_cast<Binary128>(0.0)
        ? result.compensated_reduction / result.ulp
        : static_cast<Binary128>(0.0);
    result.sign_agrees =
        (result.naive_reduction > static_cast<Binary128>(0.0)
            && result.compensated_reduction
                > static_cast<Binary128>(0.0))
        || (result.naive_reduction < static_cast<Binary128>(0.0)
            && result.compensated_reduction
                < static_cast<Binary128>(0.0));
    const Binary128 resolution =
        static_cast<Binary128>(4096.0) * result.ulp;
    result.resolved = result.sign_agrees
        && fabsq(result.naive_reduction) >= resolution
        && fabsq(result.compensated_reduction) >= resolution;
    result.resolved_positive = result.resolved
        && result.compensated_reduction > static_cast<Binary128>(0.0);
    result.resolved_negative = result.resolved
        && result.compensated_reduction < static_cast<Binary128>(0.0);
    result.membership_exact =
        result.current_naive.membership_mismatches == 0U
        && result.current_compensated.membership_mismatches == 0U
        && result.trial_naive.membership_mismatches == 0U
        && result.trial_compensated.membership_mismatches == 0U;
    result.candidate_relative_error =
        fabsq(static_cast<Binary128>(candidate_reduction)
            - result.compensated_reduction)
        / fabsq(result.compensated_reduction);
    result.candidate_pass = result.resolved_positive
        && result.candidate_relative_error <= static_cast<Binary128>(0.05);
    result.finite_values = result.current_naive.finite_values
        && result.current_compensated.finite_values
        && result.trial_naive.finite_values
        && result.trial_compensated.finite_values
        && finiteq(result.naive_reduction) != 0
        && finiteq(result.compensated_reduction) != 0
        && finiteq(result.ulp) != 0
        && finiteq(result.naive_ulp_ratio) != 0
        && finiteq(result.compensated_ulp_ratio) != 0
        && finiteq(result.candidate_relative_error) != 0;
    return result;
}

Binary128TrialEnergyAudit audit_al_vector_inner_binary128(
    const std::vector<Vec3>& current_position,
    const std::vector<Vec3>& trial_position,
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& boundary,
    const std::vector<double>& multiplier,
    double candidate_reduction,
    double time_step = TIME_STEP,
    double penalty = KAPPA) {
    Binary128EnergyEvaluation current_naive =
        evaluate_al_vector_inner_binary128(
        current_position, predicted, boundary, multiplier,
        false, time_step, penalty);
    Binary128EnergyEvaluation current_compensated =
        evaluate_al_vector_inner_binary128(
        current_position, predicted, boundary, multiplier,
        true, time_step, penalty);
    Binary128EnergyEvaluation trial_naive =
        evaluate_al_vector_inner_binary128(
        trial_position, predicted, boundary, multiplier,
        false, time_step, penalty);
    Binary128EnergyEvaluation trial_compensated =
        evaluate_al_vector_inner_binary128(
        trial_position, predicted, boundary, multiplier,
        true, time_step, penalty);
    return finalize_al_binary128_trial_energy_audit(
        std::move(current_naive), std::move(current_compensated),
        std::move(trial_naive), std::move(trial_compensated),
        candidate_reduction);
}

[[maybe_unused]] Binary128TrialEnergyAudit
audit_al_sparse_inner_binary128(
    const std::vector<Vec3>& current_position,
    const std::vector<Vec3>& trial_position,
    const std::vector<Vec3>& predicted,
    const std::vector<double>& multiplier,
    const JointStaticSupportBinding& binding,
    double candidate_reduction,
    double time_step,
    ALSparsePrecisionWorkTrace* work = nullptr,
    double penalty = KAPPA) {
    if (!std::isfinite(time_step) || time_step <= 0.0
        || !std::isfinite(penalty) || penalty <= 0.0) {
        return {};
    }
    if (work != nullptr) {
        ++work->binary128_audits;
    }
    const ALBinary128PairUnion candidate_union =
        build_al_binary128_pair_union(
            current_position, trial_position, binding, work);
    if (work != nullptr) {
        work->binary128_union_candidate_pairs +=
            candidate_union.pairs.size();
    }
    Binary128EnergyEvaluation current_naive =
        evaluate_al_sparse_inner_binary128(
            current_position, predicted, multiplier, binding,
            candidate_union, false, time_step, work, penalty);
    Binary128EnergyEvaluation current_compensated =
        evaluate_al_sparse_inner_binary128(
            current_position, predicted, multiplier, binding,
            candidate_union, true, time_step, work, penalty);
    Binary128EnergyEvaluation trial_naive =
        evaluate_al_sparse_inner_binary128(
            trial_position, predicted, multiplier, binding,
            candidate_union, false, time_step, work, penalty);
    Binary128EnergyEvaluation trial_compensated =
        evaluate_al_sparse_inner_binary128(
            trial_position, predicted, multiplier, binding,
            candidate_union, true, time_step, work, penalty);
    return finalize_al_binary128_trial_energy_audit(
        std::move(current_naive), std::move(current_compensated),
        std::move(trial_naive), std::move(trial_compensated),
        candidate_reduction);
}

std::string al_binary128_text(Binary128 value) {
    std::array<char, 128> buffer{};
    const int count = quadmath_snprintf(
        buffer.data(), buffer.size(), "%.36Qe", value);
    if (count < 0 || static_cast<std::size_t>(count) >= buffer.size()) {
        throw std::runtime_error("binary128 formatting failed");
    }
    return std::string(buffer.data(), static_cast<std::size_t>(count));
}

std::string al_binary128_hex(Binary128 value) {
    std::array<char, 128> buffer{};
    const int count = quadmath_snprintf(
        buffer.data(), buffer.size(), "%Qa", value);
    if (count < 0 || static_cast<std::size_t>(count) >= buffer.size()) {
        throw std::runtime_error("binary128 hex formatting failed");
    }
    return std::string(buffer.data(), static_cast<std::size_t>(count));
}

std::string al_binary128_audit_root(
    const Binary128TrialEnergyAudit& value) {
    std::ostringstream projection;
    projection << value.finite_values << ':' << value.sign_agrees << ':'
               << value.resolved << ':' << value.resolved_positive << ':'
               << value.resolved_negative << ':' << value.membership_exact
               << ':' << value.candidate_pass << '|'
               << al_binary128_hex(value.current_naive.total) << ':'
               << al_binary128_hex(value.current_compensated.total) << ':'
               << al_binary128_hex(value.trial_naive.total) << ':'
               << al_binary128_hex(value.trial_compensated.total) << ':'
               << al_binary128_hex(value.naive_reduction) << ':'
               << al_binary128_hex(value.compensated_reduction) << ':'
               << al_binary128_hex(value.ulp) << ':'
               << al_binary128_hex(value.naive_ulp_ratio) << ':'
               << al_binary128_hex(value.compensated_ulp_ratio) << ':'
               << al_binary128_hex(value.candidate_relative_error) << '|'
               << value.current_naive.fluid_pairs << ':'
               << value.current_naive.boundary_pairs << ':'
               << value.current_naive.membership_mismatches << ':'
               << value.current_compensated.fluid_pairs << ':'
               << value.current_compensated.boundary_pairs << ':'
               << value.current_compensated.membership_mismatches << ':'
               << value.trial_naive.fluid_pairs << ':'
               << value.trial_naive.boundary_pairs << ':'
               << value.trial_naive.membership_mismatches << ':'
               << value.trial_compensated.fluid_pairs << ':'
               << value.trial_compensated.boundary_pairs << ':'
               << value.trial_compensated.membership_mismatches;
    return sha256_hex(projection.str());
}

bool al_binary128_roundtrip_exact(const std::vector<Vec3>& values) {
    return std::all_of(values.begin(), values.end(), [](Vec3 value) {
        return binary64_bits(static_cast<double>(
                   static_cast<Binary128>(value.x)))
                == binary64_bits(value.x)
            && binary64_bits(static_cast<double>(
                   static_cast<Binary128>(value.y)))
                == binary64_bits(value.y)
            && binary64_bits(static_cast<double>(
                   static_cast<Binary128>(value.z)))
                == binary64_bits(value.z);
    });
}

bool al_binary128_roundtrip_exact(const std::vector<double>& values) {
    return std::all_of(values.begin(), values.end(), [](double value) {
        return binary64_bits(static_cast<double>(
                   static_cast<Binary128>(value)))
            == binary64_bits(value);
    });
}

struct ALDividedOuterUpdate {
    bool passed = false;
    bool finite_failure = false;
    bool audit_hard_failure = false;
    bool sign_contradiction = false;
    bool oracle_bound_required = false;
    std::string failure;
    std::string inner_root;
    std::vector<Vec3> position;
    std::vector<double> multiplier;
    ALVectorSupport support;
    ALStepNormOuterRecord record;
    std::vector<ALDividedPrivateInnerTrial> trials;
    std::vector<Binary128TrialEnergyAudit> candidate_audits;
    std::vector<std::string> candidate_audit_roots;
};

ALDividedOuterUpdate al_divided_private_outer_update(
    const Fixture& fixture,
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& position,
    const std::vector<double>& multiplier,
    int outer,
    double stationarity_limit) {
    ALDividedOuterUpdate result;
    const ALDividedPrivateInnerSolve inner =
        solve_al_divided_private_inner(
            predicted, position, fixture.boundary, multiplier,
            stationarity_limit);
    result.inner_root = al_divided_private_inner_root(inner);
    result.trials = inner.trials;
    ALVectorOuterRecord& record = result.record.state;
    record.outer = outer;
    record.inner_outer_trials = static_cast<int>(inner.trials.size()) + 1;
    record.inner_accepted_trials = inner.accepted_trials;
    record.inner_rejected_trials = inner.rejected_trials;
    record.inner_hvp_calls = inner.hvp_calls;
    record.stationarity = inner.final_stationarity;
    result.record.inner_step_norm_updates = inner.step_norm_updates;
    result.record.inner_quarter_updates = inner.quarter_updates;
    result.record.finite_values = inner.all_finite
        && std::isfinite(inner.final_stationarity);
    for (const ALDividedPrivateInnerTrial& trial : inner.trials) {
        if (!trial.candidate_effect) {
            continue;
        }
        result.candidate_audits.push_back(
            audit_al_vector_inner_binary128(
                trial.current_position, trial.trial_position,
                predicted, fixture.boundary, multiplier,
                trial.divided_reduction));
        const Binary128TrialEnergyAudit& audit =
            result.candidate_audits.back();
        result.candidate_audit_roots.push_back(
            al_binary128_audit_root(audit));
        result.record.finite_values = result.record.finite_values
            && audit.finite_values;
        result.audit_hard_failure = result.audit_hard_failure
            || !audit.finite_values || !audit.membership_exact;
        result.sign_contradiction = result.sign_contradiction
            || audit.resolved_negative;
        result.oracle_bound_required = result.oracle_bound_required
            || (!audit.resolved_negative
                && (!audit.resolved_positive || !audit.candidate_pass));
    }
    if (result.audit_hard_failure) {
        result.failure = "BINARY128_AUDIT_HARD_FAILURE";
        result.finite_failure = false;
        return result;
    }
    if (result.sign_contradiction) {
        result.failure = "BINARY128_SIGN_CONTRADICTION";
        result.finite_failure = true;
        return result;
    }
    if (result.oracle_bound_required) {
        result.failure = "ORACLE_OR_REDUCTION_BOUND_REQUIRED";
        result.finite_failure = true;
        return result;
    }
    if (!inner.passed || !inner.positive_accepted_models
        || !inner.all_finite) {
        result.failure = "INNER:" + inner.failure;
        result.finite_failure = inner.all_finite
            && inner.failure != "INITIAL_NONFINITE";
        return result;
    }

    const ALVectorInnerState inner_state = evaluate_al_vector_inner(
        inner.position, predicted, fixture.boundary, multiplier);
    result.position = inner.position;
    result.multiplier.resize(multiplier.size());
    result.support = inner_state.support;
    record.minimum_multiplier = std::numeric_limits<double>::infinity();
    record.position_update_dx =
        rms_difference(position, inner.position) / SPACING;
    for (std::size_t center = 0U;
         center < multiplier.size(); ++center) {
        result.multiplier[center] = std::max(0.0,
            multiplier[center]
                + KAPPA * inner_state.support.constraint[center]);
        const double absolute_change = std::abs(
            result.multiplier[center] - multiplier[center]);
        record.primal = std::max(record.primal,
            std::max(0.0, inner_state.support.constraint[center]));
        record.scaled_dual_change = std::max(
            record.scaled_dual_change, absolute_change / KAPPA);
        record.absolute_dual_change = std::max(
            record.absolute_dual_change, absolute_change);
        record.equivalent_pressure_change = std::max(
            record.equivalent_pressure_change,
            absolute_change * REST_DENSITY / MASS);
        record.complementarity = std::max(record.complementarity,
            std::abs(result.multiplier[center]
                * inner_state.support.constraint[center]));
        record.minimum_multiplier = std::min(
            record.minimum_multiplier, result.multiplier[center]);
        record.maximum_multiplier = std::max(
            record.maximum_multiplier, result.multiplier[center]);
    }
    result.record.finite_values = result.record.finite_values
        && inner_state.support.finite_values
        && al_step_norm_outer_record_finite(record)
        && std::all_of(result.position.begin(), result.position.end(),
            [](Vec3 value) { return finite(value); })
        && std::all_of(result.multiplier.begin(), result.multiplier.end(),
            [](double value) { return std::isfinite(value); });
    result.record.admissible = result.record.finite_values
        && al_step_norm_outer_record_admissible(
            record, stationarity_limit);
    result.passed = result.record.finite_values;
    if (!result.passed) {
        result.failure = "OUTER_NONFINITE";
    }
    return result;
}

ALDividedOuterUpdate al_sparse_divided_private_outer_update(
    const Fixture& fixture,
    const std::vector<Vec3>& predicted,
    const std::vector<Vec3>& position,
    const std::vector<double>& multiplier,
    int outer,
    double stationarity_limit,
    double time_step,
    ALSparseWorkTrace* work,
    ALSparsePrecisionTransactionContext* precision_context = nullptr,
    double kappa = KAPPA) {
    ALDividedOuterUpdate result;
    const ALDividedPrivateInnerSolve inner =
        solve_al_sparse_divided_private_inner(
            predicted, position, fixture.boundary, multiplier,
            stationarity_limit, time_step, work, precision_context,
            kappa);
    result.inner_root = al_divided_private_inner_root(inner);
    result.trials = inner.trials;
    ALVectorOuterRecord& record = result.record.state;
    record.outer = outer;
    record.inner_outer_trials = static_cast<int>(inner.trials.size()) + 1;
    record.inner_accepted_trials = inner.accepted_trials;
    record.inner_rejected_trials = inner.rejected_trials;
    record.inner_hvp_calls = inner.hvp_calls;
    record.stationarity = inner.final_stationarity;
    result.record.inner_step_norm_updates = inner.step_norm_updates;
    result.record.inner_quarter_updates = inner.quarter_updates;
    result.record.finite_values = inner.all_finite
        && std::isfinite(inner.final_stationarity);
    for (const ALDividedPrivateInnerTrial& trial : inner.trials) {
        if (!trial.candidate_effect) {
            continue;
        }
        if (precision_context != nullptr
            && !al_sparse_budget_consume_precision_audit(
                precision_context->structural_budget)) {
            result.failure = precision_context
                ->structural_budget->failure;
            result.finite_failure = true;
            return result;
        }
        result.candidate_audits.push_back(
            precision_context != nullptr
            ? audit_al_sparse_inner_binary128(
                trial.current_position, trial.trial_position,
                predicted, multiplier, *precision_context->binding,
                trial.divided_reduction, time_step,
                precision_context->precision_work, kappa)
            : audit_al_vector_inner_binary128(
                trial.current_position, trial.trial_position,
                predicted, fixture.boundary, multiplier,
                trial.divided_reduction, time_step, kappa));
        const Binary128TrialEnergyAudit& audit =
            result.candidate_audits.back();
        result.candidate_audit_roots.push_back(
            al_binary128_audit_root(audit));
        result.record.finite_values = result.record.finite_values
            && audit.finite_values;
        result.audit_hard_failure = result.audit_hard_failure
            || !audit.finite_values || !audit.membership_exact;
        result.sign_contradiction = result.sign_contradiction
            || audit.resolved_negative;
        result.oracle_bound_required = result.oracle_bound_required
            || (!audit.resolved_negative
                && (!audit.resolved_positive || !audit.candidate_pass));
    }
    if (result.audit_hard_failure) {
        result.failure = "BINARY128_AUDIT_HARD_FAILURE";
        result.finite_failure = false;
        return result;
    }
    if (result.sign_contradiction) {
        result.failure = "BINARY128_SIGN_CONTRADICTION";
        result.finite_failure = true;
        return result;
    }
    if (result.oracle_bound_required) {
        result.failure = "ORACLE_OR_REDUCTION_BOUND_REQUIRED";
        result.finite_failure = true;
        return result;
    }
    if (!inner.passed || !inner.positive_accepted_models
        || !inner.all_finite) {
        result.failure = "INNER:" + inner.failure;
        result.finite_failure = inner.all_finite
            && inner.failure != "INITIAL_NONFINITE";
        return result;
    }

    if (precision_context != nullptr
        && !al_sparse_budget_consume_workspace(
            precision_context->structural_budget)) {
        result.failure = precision_context->structural_budget->failure;
        result.finite_failure = true;
        return result;
    }
    ALSparseInnerState inner_state = precision_context != nullptr
        ? evaluate_al_sparse_inner_with_static_support(
            inner.position, predicted, *precision_context->binding,
            multiplier, time_step, work,
            precision_context->static_work,
            precision_context->adjacency_work, kappa)
        : evaluate_al_sparse_inner(
            inner.position, predicted, fixture.boundary, multiplier,
            time_step, work, kappa);
    result.position = inner.position;
    result.multiplier.resize(multiplier.size());
    result.support = inner_state.workspace.support;
    record.minimum_multiplier = std::numeric_limits<double>::infinity();
    record.position_update_dx =
        rms_difference(position, inner.position) / SPACING;
    for (std::size_t center = 0U;
         center < multiplier.size(); ++center) {
        result.multiplier[center] = al_sparse_multiplier_update(
            multiplier[center],
            inner_state.workspace.support.constraint[center], kappa);
        const double absolute_change = std::abs(
            result.multiplier[center] - multiplier[center]);
        record.primal = std::max(record.primal,
            std::max(0.0,
                inner_state.workspace.support.constraint[center]));
        record.scaled_dual_change = std::max(
            record.scaled_dual_change, absolute_change / kappa);
        record.absolute_dual_change = std::max(
            record.absolute_dual_change, absolute_change);
        record.equivalent_pressure_change = std::max(
            record.equivalent_pressure_change,
            absolute_change * REST_DENSITY / MASS);
        record.complementarity = std::max(record.complementarity,
            std::abs(result.multiplier[center]
                * inner_state.workspace.support.constraint[center]));
        record.minimum_multiplier = std::min(
            record.minimum_multiplier, result.multiplier[center]);
        record.maximum_multiplier = std::max(
            record.maximum_multiplier, result.multiplier[center]);
    }
    result.record.finite_values = result.record.finite_values
        && inner_state.passed
        && al_step_norm_outer_record_finite(record)
        && std::all_of(result.position.begin(), result.position.end(),
            [](Vec3 value) { return finite(value); })
        && std::all_of(result.multiplier.begin(), result.multiplier.end(),
            [](double value) { return std::isfinite(value); });
    result.record.admissible = result.record.finite_values
        && al_step_norm_outer_record_admissible(
            record, stationarity_limit);
    result.passed = result.record.finite_values;
    if (!result.passed) {
        result.failure = "OUTER_NONFINITE";
    }
    release_al_sparse_workspace(inner_state.workspace, work);
    return result;
}

struct ALDividedOuterContinuation {
    bool all_inners_pass = true;
    bool all_finite = true;
    bool primal_monotone = true;
    bool dual_feasible = true;
    bool cap_exhausted = false;
    bool confirmed = false;
    bool warm_holdout_attempted = false;
    bool warm_holdout_admissible = false;
    bool audit_hard_failure = false;
    bool sign_contradiction = false;
    bool oracle_bound_required = false;
    std::string failure;
    int provisional_index = -1;
    int confirmation_index = -1;
    int private_confirmation_count = 0;
    int accepted_trials = 0;
    int rejected_trials = 0;
    int hvp_calls = 0;
    int candidate_effect_acceptances = 0;
    int candidate_audits = 0;
    int resolved_positive = 0;
    int resolved_negative = 0;
    int unresolved = 0;
    std::vector<Vec3> position;
    std::vector<double> multiplier;
    std::vector<ALDividedOuterUpdate> updates;
    ALDividedOuterUpdate warm_holdout;
};

void al_divided_outer_observe_update(
    ALDividedOuterContinuation& result,
    const ALDividedOuterUpdate& update) {
    result.all_finite = result.all_finite
        && update.record.finite_values;
    result.audit_hard_failure = result.audit_hard_failure
        || update.audit_hard_failure;
    result.sign_contradiction = result.sign_contradiction
        || update.sign_contradiction;
    result.oracle_bound_required = result.oracle_bound_required
        || update.oracle_bound_required;
    for (const ALDividedPrivateInnerTrial& trial : update.trials) {
        result.accepted_trials += trial.candidate_accepted ? 1 : 0;
        result.rejected_trials += trial.candidate_accepted ? 0 : 1;
        result.hvp_calls += trial.hvp_calls;
        result.candidate_effect_acceptances +=
            trial.candidate_effect ? 1 : 0;
    }
    result.candidate_audits +=
        static_cast<int>(update.candidate_audits.size());
    for (const Binary128TrialEnergyAudit& audit : update.candidate_audits) {
        if (audit.resolved_positive) {
            ++result.resolved_positive;
        } else if (audit.resolved_negative) {
            ++result.resolved_negative;
        } else {
            ++result.unresolved;
        }
    }
}

ALDividedOuterContinuation solve_al_divided_outer_continuation(
    const Fixture& fixture,
    const std::vector<Vec3>& predicted,
    std::vector<Vec3> position,
    std::vector<double> multiplier,
    const ALStepNormOuterRecord& prefix_last) {
    constexpr double stationarity_limit = 1.0e-10;
    constexpr int first_outer = 8;
    constexpr int maximum_outer = 64;
    ALDividedOuterContinuation result;
    result.position = position;
    result.multiplier = multiplier;
    double previous_primal = prefix_last.state.primal;
    bool previous_admissible = prefix_last.finite_values
        && al_step_norm_outer_record_admissible(
            prefix_last.state, stationarity_limit);
    result.provisional_index = previous_admissible ? 7 : -1;
    for (int outer = first_outer; outer < maximum_outer; ++outer) {
        ALDividedOuterUpdate update = al_divided_private_outer_update(
            fixture, predicted, position, multiplier, outer,
            stationarity_limit);
        al_divided_outer_observe_update(result, update);
        if (!update.passed) {
            if (!update.sign_contradiction
                && !update.oracle_bound_required
                && !update.audit_hard_failure) {
                result.all_inners_pass = false;
            }
            result.failure = update.failure;
            result.updates.push_back(std::move(update));
            return result;
        }
        const bool monotone =
            update.record.state.primal <= previous_primal;
        result.primal_monotone = result.primal_monotone && monotone;
        result.dual_feasible = result.dual_feasible
            && update.record.state.minimum_multiplier >= 0.0;
        previous_primal = update.record.state.primal;
        result.position = update.position;
        result.multiplier = update.multiplier;
        position = update.position;
        multiplier = update.multiplier;
        const bool admissible = update.record.admissible && monotone;
        if (admissible && previous_admissible
            && result.provisional_index == outer - 1) {
            result.confirmed = true;
            result.confirmation_index = outer;
            ++result.private_confirmation_count;
        }
        result.updates.push_back(std::move(update));
        if (result.confirmed) {
            break;
        }
        result.provisional_index = admissible ? outer : -1;
        previous_admissible = admissible;
    }
    if (result.confirmed) {
        if (result.confirmation_index >= maximum_outer - 1) {
            result.failure = "HOLDOUT_OBSERVATION_CAP";
            return result;
        }
        result.warm_holdout_attempted = true;
        result.warm_holdout = al_divided_private_outer_update(
            fixture, predicted, result.position, result.multiplier,
            result.confirmation_index + 1, stationarity_limit);
        al_divided_outer_observe_update(result, result.warm_holdout);
        if (!result.warm_holdout.passed) {
            if (!result.warm_holdout.sign_contradiction
                && !result.warm_holdout.oracle_bound_required
                && !result.warm_holdout.audit_hard_failure) {
                result.all_inners_pass = false;
            }
            result.failure = "HOLDOUT:" + result.warm_holdout.failure;
            return result;
        }
        result.all_finite = result.all_finite
            && result.warm_holdout.record.finite_values;
        result.dual_feasible = result.dual_feasible
            && result.warm_holdout.record.state.minimum_multiplier >= 0.0;
        result.warm_holdout_admissible =
            result.warm_holdout.record.admissible
            && result.warm_holdout.record.state.primal <= previous_primal;
        if (!result.warm_holdout_admissible) {
            result.failure = "HOLDOUT_NOT_ADMISSIBLE";
        }
        return result;
    }
    result.cap_exhausted = result.all_inners_pass && result.all_finite
        && result.updates.size()
            == static_cast<std::size_t>(maximum_outer - first_outer)
        && !result.updates.empty()
        && result.updates.back().record.state.outer == maximum_outer - 1;
    if (result.cap_exhausted) {
        result.failure = "OUTER_OBSERVATION_LIMIT";
    }
    return result;
}

ALDividedOuterContinuation solve_al_divided_full_private_transaction(
    const Fixture& fixture,
    const std::vector<Vec3>& predicted,
    std::vector<Vec3> position,
    std::vector<double> multiplier) {
    constexpr double stationarity_limit = 1.0e-10;
    constexpr int maximum_outer = 64;
    ALDividedOuterContinuation result;
    result.position = position;
    result.multiplier = multiplier;
    double previous_primal = std::numeric_limits<double>::infinity();
    bool previous_admissible = false;
    for (int outer = 0; outer < maximum_outer; ++outer) {
        ALDividedOuterUpdate update = al_divided_private_outer_update(
            fixture, predicted, position, multiplier, outer,
            stationarity_limit);
        al_divided_outer_observe_update(result, update);
        if (!update.passed) {
            if (!update.sign_contradiction
                && !update.oracle_bound_required
                && !update.audit_hard_failure) {
                result.all_inners_pass = false;
            }
            result.failure = update.failure;
            result.updates.push_back(std::move(update));
            return result;
        }
        const bool monotone =
            update.record.state.primal <= previous_primal;
        result.primal_monotone = result.primal_monotone && monotone;
        result.dual_feasible = result.dual_feasible
            && update.record.state.minimum_multiplier >= 0.0;
        previous_primal = update.record.state.primal;
        result.position = update.position;
        result.multiplier = update.multiplier;
        position = update.position;
        multiplier = update.multiplier;
        const bool admissible = update.record.admissible && monotone;
        if (admissible && previous_admissible
            && result.provisional_index == outer - 1) {
            result.confirmed = true;
            result.confirmation_index = outer;
            ++result.private_confirmation_count;
        }
        result.updates.push_back(std::move(update));
        if (result.confirmed) {
            break;
        }
        result.provisional_index = admissible ? outer : -1;
        previous_admissible = admissible;
    }
    if (result.confirmed) {
        if (result.confirmation_index >= maximum_outer - 1) {
            result.failure = "HOLDOUT_OBSERVATION_CAP";
            return result;
        }
        result.warm_holdout_attempted = true;
        result.warm_holdout = al_divided_private_outer_update(
            fixture, predicted, result.position, result.multiplier,
            result.confirmation_index + 1, stationarity_limit);
        al_divided_outer_observe_update(result, result.warm_holdout);
        if (!result.warm_holdout.passed) {
            if (!result.warm_holdout.sign_contradiction
                && !result.warm_holdout.oracle_bound_required
                && !result.warm_holdout.audit_hard_failure) {
                result.all_inners_pass = false;
            }
            result.failure = "HOLDOUT:" + result.warm_holdout.failure;
            return result;
        }
        result.all_finite = result.all_finite
            && result.warm_holdout.record.finite_values;
        result.dual_feasible = result.dual_feasible
            && result.warm_holdout.record.state.minimum_multiplier >= 0.0;
        result.warm_holdout_admissible =
            result.warm_holdout.record.admissible
            && result.warm_holdout.record.state.primal <= previous_primal;
        if (!result.warm_holdout_admissible) {
            result.failure = "HOLDOUT_NOT_ADMISSIBLE";
        }
        return result;
    }
    result.cap_exhausted = result.all_inners_pass && result.all_finite
        && result.updates.size() == static_cast<std::size_t>(maximum_outer)
        && !result.updates.empty()
        && result.updates.back().record.state.outer == maximum_outer - 1;
    if (result.cap_exhausted) {
        result.failure = "OUTER_OBSERVATION_LIMIT";
    }
    return result;
}

ALDividedOuterContinuation solve_al_sparse_divided_full_private_transaction(
    const Fixture& fixture,
    const std::vector<Vec3>& predicted,
    std::vector<Vec3> position,
    std::vector<double> multiplier,
    double time_step,
    ALSparseWorkTrace* work,
    ALSparsePrecisionTransactionContext* precision_context = nullptr,
    double kappa = KAPPA) {
    constexpr double stationarity_limit = 1.0e-10;
    constexpr int maximum_outer = 64;
    ALDividedOuterContinuation result;
    result.position = position;
    result.multiplier = multiplier;
    if (!std::isfinite(time_step) || time_step <= 0.0
        || !std::isfinite(kappa) || kappa <= 0.0) {
        result.all_inners_pass = false;
        result.all_finite = false;
        result.failure = "AL_SCALE_INVALID";
        return result;
    }
    if (precision_context != nullptr
        && (precision_context->binding == nullptr
            || !precision_context->binding->passed
            || precision_context->binding->index == nullptr
            || precision_context->binding->index->identity_sha256
                != precision_context->binding
                    ->expected_identity_sha256)) {
        result.all_inners_pass = false;
        result.all_finite = false;
        result.failure = "STATIC_SUPPORT_INDEX_IDENTITY";
        return result;
    }
    if (precision_context != nullptr
        && precision_context->structural_budget != nullptr
        && !al_sparse_structural_budget_valid(
            *precision_context->structural_budget)) {
        precision_context->structural_budget->exhausted = true;
        precision_context->structural_budget->failure =
            "STRUCTURAL_BUDGET_INVALID";
        result.all_inners_pass = false;
        result.all_finite = false;
        result.failure = "STRUCTURAL_BUDGET_INVALID";
        return result;
    }
    double previous_primal = std::numeric_limits<double>::infinity();
    bool previous_admissible = false;
    for (int outer = 0; outer < maximum_outer; ++outer) {
        if (precision_context != nullptr
            && !al_sparse_budget_begin_outer_update(
                precision_context->structural_budget)) {
            result.failure = precision_context
                ->structural_budget->failure;
            return result;
        }
        ALDividedOuterUpdate update =
            al_sparse_divided_private_outer_update(
                fixture, predicted, position, multiplier, outer,
                stationarity_limit, time_step, work,
                precision_context, kappa);
        al_divided_outer_observe_update(result, update);
        if (!update.passed) {
            if (!update.sign_contradiction
                && !update.oracle_bound_required
                && !update.audit_hard_failure) {
                result.all_inners_pass = false;
            }
            result.failure = update.failure;
            result.updates.push_back(std::move(update));
            return result;
        }
        const bool monotone =
            update.record.state.primal <= previous_primal;
        result.primal_monotone = result.primal_monotone && monotone;
        result.dual_feasible = result.dual_feasible
            && update.record.state.minimum_multiplier >= 0.0;
        previous_primal = update.record.state.primal;
        result.position = update.position;
        result.multiplier = update.multiplier;
        position = update.position;
        multiplier = update.multiplier;
        const bool admissible = update.record.admissible && monotone;
        if (admissible && previous_admissible
            && result.provisional_index == outer - 1) {
            result.confirmed = true;
            result.confirmation_index = outer;
            ++result.private_confirmation_count;
        }
        result.updates.push_back(std::move(update));
        if (result.confirmed) {
            break;
        }
        result.provisional_index = admissible ? outer : -1;
        previous_admissible = admissible;
    }
    if (result.confirmed) {
        if (result.confirmation_index >= maximum_outer - 1) {
            result.failure = "HOLDOUT_OBSERVATION_CAP";
            return result;
        }
        result.warm_holdout_attempted = true;
        if (precision_context != nullptr
            && !al_sparse_budget_begin_outer_update(
                precision_context->structural_budget)) {
            result.failure = precision_context
                ->structural_budget->failure;
            return result;
        }
        result.warm_holdout = al_sparse_divided_private_outer_update(
            fixture, predicted, result.position, result.multiplier,
            result.confirmation_index + 1, stationarity_limit,
            time_step, work, precision_context, kappa);
        al_divided_outer_observe_update(result, result.warm_holdout);
        if (!result.warm_holdout.passed) {
            if (!result.warm_holdout.sign_contradiction
                && !result.warm_holdout.oracle_bound_required
                && !result.warm_holdout.audit_hard_failure) {
                result.all_inners_pass = false;
            }
            result.failure = "HOLDOUT:" + result.warm_holdout.failure;
            return result;
        }
        result.all_finite = result.all_finite
            && result.warm_holdout.record.finite_values;
        result.dual_feasible = result.dual_feasible
            && result.warm_holdout.record.state.minimum_multiplier >= 0.0;
        result.warm_holdout_admissible =
            result.warm_holdout.record.admissible
            && result.warm_holdout.record.state.primal <= previous_primal;
        if (!result.warm_holdout_admissible) {
            result.failure = "HOLDOUT_NOT_ADMISSIBLE";
        }
        return result;
    }
    result.cap_exhausted = result.all_inners_pass && result.all_finite
        && result.updates.size() == static_cast<std::size_t>(maximum_outer)
        && !result.updates.empty()
        && result.updates.back().record.state.outer == maximum_outer - 1;
    if (result.cap_exhausted) {
        result.failure = "OUTER_OBSERVATION_LIMIT";
    }
    return result;
}

std::string al_binary64_vec3_root(const std::vector<Vec3>& values) {
    std::ostringstream projection;
    projection << values.size() << '|';
    for (Vec3 value : values) {
        projection << binary64_bits(value.x) << ':'
                   << binary64_bits(value.y) << ':'
                   << binary64_bits(value.z) << ';';
    }
    return sha256_hex(projection.str());
}

void al_divided_outer_record_projection(
    std::ostringstream& projection,
    const ALDividedOuterUpdate& update) {
    const ALVectorOuterRecord& record = update.record.state;
    projection << update.passed << ':' << update.finite_failure << ':'
               << update.audit_hard_failure << ':'
               << update.sign_contradiction << ':'
               << update.oracle_bound_required << ':' << update.failure
               << ':' << update.inner_root << '|'
               << record.outer << ':' << record.inner_outer_trials << ':'
               << record.inner_accepted_trials << ':'
               << record.inner_rejected_trials << ':'
               << record.inner_hvp_calls << ':' << record.primal << ':'
               << record.scaled_dual_change << ':' << record.stationarity
               << ':' << record.complementarity << ':'
               << record.absolute_dual_change << ':'
               << record.equivalent_pressure_change << ':'
               << record.position_update_dx << ':'
               << record.minimum_multiplier << ':'
               << record.maximum_multiplier << ':'
               << update.record.inner_step_norm_updates << ':'
               << update.record.inner_quarter_updates << ':'
               << update.record.finite_values << ':'
               << update.record.admissible << '|';
    for (const ALDividedPrivateInnerTrial& trial : update.trials) {
        projection << trial.trial << ':' << trial.candidate_accepted << ':'
                   << trial.candidate_effect << ':' << trial.hvp_calls << ':'
                   << al_binary64_vec3_root(trial.current_position) << ':'
                   << al_binary64_vec3_root(trial.trial_position) << ';';
    }
    projection << '|';
    for (const std::string& root : update.candidate_audit_roots) {
        projection << root << ';';
    }
}

std::string al_divided_outer_continuation_root(
    const ALDividedOuterContinuation& value) {
    std::ostringstream projection;
    projection << std::setprecision(
                      std::numeric_limits<long double>::max_digits10)
               << value.all_inners_pass << ':' << value.all_finite << ':'
               << value.primal_monotone << ':' << value.dual_feasible << ':'
               << value.cap_exhausted << ':' << value.confirmed << ':'
               << value.warm_holdout_attempted << ':'
               << value.warm_holdout_admissible << ':'
               << value.audit_hard_failure << ':'
               << value.sign_contradiction << ':'
               << value.oracle_bound_required << ':' << value.failure << ':'
               << value.provisional_index << ':' << value.confirmation_index
               << ':' << value.private_confirmation_count << ':'
               << value.accepted_trials << ':' << value.rejected_trials
               << ':' << value.hvp_calls << ':'
               << value.candidate_effect_acceptances << ':'
               << value.candidate_audits << ':' << value.resolved_positive
               << ':' << value.resolved_negative << ':' << value.unresolved
               << '|' << al_binary64_vec3_root(value.position) << ':';
    for (double multiplier : value.multiplier) {
        projection << binary64_bits(multiplier) << ';';
    }
    projection << '|';
    for (const ALDividedOuterUpdate& update : value.updates) {
        al_divided_outer_record_projection(projection, update);
        projection << '#';
    }
    projection << '|';
    if (value.warm_holdout_attempted) {
        al_divided_outer_record_projection(
            projection, value.warm_holdout);
    }
    return sha256_hex(projection.str());
}

} // namespace

SplitBoundaryReport run_al_dense_vector_oracle_controls() {
    const Fixture fixture = make_box_fixture(
        "corner-box-2x2x2", {2, 2, 2}, 2);
    const std::vector<Vec3> boundary_before = fixture.boundary;
    const std::vector<Vec3> active_prediction =
        compressed_fluid(fixture, 0.99);
    const std::vector<Vec3> inactive_prediction =
        compressed_fluid(fixture, 1.01);
    const std::vector<double> zero_multiplier(fixture.fluid.size());
    const bool identity_exact = sha256_hex(B4E2D7_IDENTITY_PROJECTION)
        == B4E2D7_IDENTITY_SHA256;
    const Evaluation rest = evaluate(fixture.fluid, fixture.boundary);
    double rest_error = 0.0;
    for (double density : rest.density) {
        rest_error = std::max(rest_error,
            std::abs(density / REST_DENSITY - 1.0));
    }
    const bool fixture_exact = fixture.fluid.size() == 8U
        && fixture.boundary.size() == 176U && rest_error <= 3.0e-15;

    std::vector<double> derivative_multiplier(
        fixture.fluid.size(), 0.0053516806);
    const ALVectorSupport derivative_state = evaluate_al_vector_support(
        active_prediction, fixture.boundary, derivative_multiplier);
    const std::vector<Vec3> direction = deterministic_direction(
        active_prediction.size());
    constexpr double derivative_epsilon = 2.0e-7;
    const ALVectorSupport plus = evaluate_al_vector_support(
        displace(active_prediction, direction, derivative_epsilon),
        fixture.boundary, derivative_multiplier);
    const ALVectorSupport minus = evaluate_al_vector_support(
        displace(active_prediction, direction, -derivative_epsilon),
        fixture.boundary, derivative_multiplier);
    double analytic_direction = 0.0;
    for (std::size_t index = 0U;
         index < active_prediction.size(); ++index) {
        analytic_direction += dot(
            derivative_state.gradient[index], direction[index]);
    }
    const double finite_direction =
        (plus.energy - minus.energy) / (2.0 * derivative_epsilon);
    const double gradient_error = relative_error(
        analytic_direction, finite_direction);
    std::vector<Vec3> joint_direction(
        active_prediction.size() + fixture.boundary.size());
    std::copy(direction.begin(), direction.end(), joint_direction.begin());
    const std::vector<Vec3> analytic_hvp = fluid_part(
        apply_al_vector_hessian(active_prediction, fixture.boundary,
            derivative_multiplier, joint_direction),
        active_prediction.size());
    std::vector<Vec3> finite_hvp(active_prediction.size());
    for (std::size_t index = 0U;
         index < finite_hvp.size(); ++index) {
        finite_hvp[index] = (plus.gradient[index] - minus.gradient[index])
            / (2.0 * derivative_epsilon);
    }
    const double hvp_error = vector_relative_error(
        analytic_hvp, finite_hvp);
    const std::size_t dimension = 3U * active_prediction.size();
    std::vector<double> dense(dimension * dimension);
    for (std::size_t column = 0U; column < dimension; ++column) {
        std::vector<Vec3> basis(
            active_prediction.size() + fixture.boundary.size());
        set_component(basis[column / 3U],
            static_cast<int>(column % 3U), 1.0);
        const std::vector<double> product = flatten(fluid_part(
            apply_al_vector_hessian(active_prediction, fixture.boundary,
                derivative_multiplier, basis), active_prediction.size()));
        for (std::size_t row = 0U; row < dimension; ++row) {
            dense[row * dimension + column] = product[row];
        }
    }
    double maximum_asymmetry = 0.0;
    double maximum_dense = 0.0;
    for (std::size_t row = 0U; row < dimension; ++row) {
        for (std::size_t column = 0U; column < dimension; ++column) {
            maximum_asymmetry = std::max(maximum_asymmetry,
                std::abs(dense[row * dimension + column]
                    - dense[column * dimension + row]));
            maximum_dense = std::max(maximum_dense,
                std::abs(dense[row * dimension + column]));
        }
    }
    const double dense_symmetry_error = maximum_asymmetry
        / std::max(maximum_dense, 1.0e-30);
    const std::vector<double> flat_direction = flatten(direction);
    std::vector<double> dense_product(dimension);
    for (std::size_t row = 0U; row < dimension; ++row) {
        for (std::size_t column = 0U; column < dimension; ++column) {
            dense_product[row] += dense[row * dimension + column]
                * flat_direction[column];
        }
    }
    const std::vector<double> flat_hvp = flatten(analytic_hvp);
    double product_difference = 0.0;
    double product_scale = 0.0;
    for (std::size_t index = 0U; index < dimension; ++index) {
        product_difference += (dense_product[index] - flat_hvp[index])
            * (dense_product[index] - flat_hvp[index]);
        product_scale = std::max(product_scale,
            std::max(std::abs(dense_product[index]),
                std::abs(flat_hvp[index])));
    }
    const double dense_product_error = std::sqrt(product_difference)
        / std::max(product_scale * std::sqrt(
            static_cast<double>(dimension)), 1.0e-30);
    const Vec3 gradient_sum = sum_values(
        derivative_state.gradient, 0U,
        derivative_state.gradient.size());
    double gradient_scale = 0.0;
    for (Vec3 value : derivative_state.gradient) {
        gradient_scale += norm(value);
    }
    const double reaction_closure = norm(gradient_sum)
        / std::max(gradient_scale, 1.0e-30);
    const bool derivative_exact = derivative_state.finite_values
        && plus.finite_values && minus.finite_values
        && derivative_state.active_centers == plus.active_centers
        && derivative_state.active_centers == minus.active_centers
        && derivative_state.fluid_pairs == plus.fluid_pairs
        && derivative_state.fluid_pairs == minus.fluid_pairs
        && derivative_state.boundary_pairs == plus.boundary_pairs
        && derivative_state.boundary_pairs == minus.boundary_pairs
        && gradient_error <= 1.0e-7 && hvp_error <= 2.0e-6
        && dense_symmetry_error <= 2.0e-12
        && dense_product_error <= 2.0e-12
        && reaction_closure <= 1.0e-12
        && exact_vec3_values(fixture.boundary, boundary_before);

    const ALVectorOuterSolve cold = solve_al_vector_outer(
        fixture, active_prediction, active_prediction,
        zero_multiplier, 8);
    const ALVectorOuterSolve warm = cold.passed
        ? solve_al_vector_outer(fixture, active_prediction,
            cold.position, cold.multiplier, 2)
        : ALVectorOuterSolve{};
    const double warm_position_error = cold.passed && warm.passed
        ? rms_difference(cold.position, warm.position) / SPACING
        : std::numeric_limits<double>::infinity();
    double warm_multiplier_error = 0.0;
    if (cold.multiplier.size() == warm.multiplier.size()) {
        for (std::size_t index = 0U;
             index < cold.multiplier.size(); ++index) {
            warm_multiplier_error = std::max(warm_multiplier_error,
                std::abs(cold.multiplier[index] - warm.multiplier[index]));
        }
    } else {
        warm_multiplier_error = std::numeric_limits<double>::infinity();
    }
    const bool warm_exact = cold.passed && warm.passed
        && warm.records.size() <= 2U
        && warm_position_error <= 1.0e-8
        && warm_multiplier_error <= 1.0e-8;

    const ALVectorOuterSolve inactive = solve_al_vector_outer(
        fixture, inactive_prediction, inactive_prediction,
        zero_multiplier, 2);
    const bool inactive_exact = inactive.passed
        && exact_vec3_values(inactive.position, inactive_prediction)
        && exact_al_multiplier(inactive.multiplier, zero_multiplier)
        && std::all_of(inactive.support.constraint.begin(),
            inactive.support.constraint.end(),
            [](double value) { return value <= 0.0; });

    const ALVectorInnerSolve reset = solve_al_vector_inner(
        active_prediction, active_prediction,
        fixture.boundary, zero_multiplier);
    double reset_primal = 0.0;
    for (double value : reset.support.constraint) {
        reset_primal = std::max(reset_primal, std::max(0.0, value));
    }
    const bool reset_negative = reset.passed && reset_primal > 1.0e-8;

    const ALVectorOuterSolve forced_private = solve_al_vector_outer(
        fixture, active_prediction, active_prediction,
        zero_multiplier, 1);
    const std::vector<Vec3> public_position = active_prediction;
    const std::vector<double> public_multiplier = zero_multiplier;
    const bool rollback_exact =
        exact_vec3_values(public_position, active_prediction)
        && exact_al_multiplier(public_multiplier, zero_multiplier)
        && !forced_private.records.empty()
        && (!exact_vec3_values(forced_private.position, public_position)
            || !exact_al_multiplier(
                forced_private.multiplier, public_multiplier));

    std::vector<double> mutated_multiplier = cold.passed
        ? cold.multiplier : zero_multiplier;
    if (!mutated_multiplier.empty()) {
        mutated_multiplier.front() = std::nextafter(
            mutated_multiplier.front(),
            std::numeric_limits<double>::infinity());
    }
    const ALVectorInnerSolve mutation_control = solve_al_vector_inner(
        active_prediction, cold.passed ? cold.position : active_prediction,
        fixture.boundary, cold.passed ? cold.multiplier : zero_multiplier);
    const ALVectorInnerSolve mutation = solve_al_vector_inner(
        active_prediction, cold.passed ? cold.position : active_prediction,
        fixture.boundary, mutated_multiplier);
    const std::string cold_root = al_vector_state_root(
        "cold", cold.position, cold.multiplier);
    const std::string warm_root = al_vector_state_root(
        "warm", warm.position, warm.multiplier);
    const std::string inactive_root = al_vector_state_root(
        "inactive", inactive.position, inactive.multiplier);
    const std::string mutation_control_root = al_vector_state_root(
        "mutation", mutation_control.position,
        cold.passed ? cold.multiplier : zero_multiplier);
    const std::string mutation_root = al_vector_state_root(
        "mutation", mutation.position, mutated_multiplier);
    const bool mutation_sensitive = mutation_control.passed
        && mutation.passed && mutation_root != mutation_control_root;

    const bool al_dense_viable = cold.passed && cold.primal_monotone
        && warm_exact && inactive_exact && reset_negative
        && rollback_exact && mutation_sensitive;
    const bool fallback_selected = !cold.passed && cold.inner_exact
        && cold.primal_monotone && cold.cap_exhausted
        && inactive_exact && reset_negative && rollback_exact
        && mutation_sensitive;
    const std::string route = al_dense_viable ? "AL_DENSE_VIABLE"
        : (fallback_selected
            ? "SEMISMOOTH_PRIMAL_DUAL_REQUIRED" : std::string{});
    const bool passed = identity_exact && fixture_exact && derivative_exact
        && !route.empty();
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!fixture_exact) first_failure = "FIXTURE";
    else if (!derivative_exact) first_failure = "DERIVATIVE";
    else if (route.empty()) first_failure = "AL_DENSE_CONTROLS";

    const auto append_outer = [](std::ostringstream& output,
            const ALVectorOuterSolve& solve) {
        output << '[';
        for (std::size_t index = 0U; index < solve.records.size(); ++index) {
            if (index != 0U) output << ',';
            const ALVectorOuterRecord& record = solve.records[index];
            output << std::setprecision(17)
                   << "{\"outer\":" << record.outer
                   << ",\"inner_outer_trials\":"
                   << record.inner_outer_trials
                   << ",\"inner_accepted_trials\":"
                   << record.inner_accepted_trials
                   << ",\"inner_rejected_trials\":"
                   << record.inner_rejected_trials
                   << ",\"inner_hvp_calls\":" << record.inner_hvp_calls
                   << ",\"primal\":" << record.primal
                   << ",\"scaled_dual_change\":"
                   << record.scaled_dual_change
                   << ",\"stationarity\":" << record.stationarity
                   << ",\"complementarity\":"
                   << record.complementarity
                   << ",\"multiplier_range\":["
                   << record.minimum_multiplier << ','
                   << record.maximum_multiplier << "]}";
        }
        output << ']';
    };
    std::ostringstream semantic;
    semantic << std::setprecision(17)
             << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D7_IDENTITY_SHA256 << '|'
             << fixture.fluid.size() << ':' << fixture.boundary.size() << ':'
             << rest_error << '|' << gradient_error << ':' << hvp_error << ':'
             << dense_symmetry_error << ':' << dense_product_error << ':'
             << reaction_closure << '|'
             << cold.passed << ':' << cold.records.size() << ':' << cold_root
             << ':' << cold.primal_monotone << '|'
             << warm.passed << ':' << warm.records.size() << ':' << warm_root
             << ':' << warm_position_error << ':' << warm_multiplier_error
             << '|' << inactive.passed << ':' << inactive_root << '|'
             << reset.passed << ':' << reset_primal << ':' << rollback_exact
             << ':' << mutation_sensitive << ':' << mutation_root << '|'
             << route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    std::ostringstream report;
    report << std::setprecision(17)
           << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d7_al_dense_vector.v1\""
           << ",\"identity_sha256\":\"" << B4E2D7_IDENTITY_SHA256
           << "\",\"solver_identity\":\""
              "nuv-al-pressure-r0+dense-vector-v1\""
           << ",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"fixture\":{\"fluid_samples\":"
           << fixture.fluid.size() << ",\"support_samples\":"
           << fixture.boundary.size() << ",\"rest_error\":"
           << rest_error << ",\"exact\":"
           << (fixture_exact ? "true" : "false") << '}'
           << ",\"derivatives\":{\"gradient_error\":"
           << gradient_error << ",\"hvp_error\":" << hvp_error
           << ",\"dense_symmetry_error\":" << dense_symmetry_error
           << ",\"dense_product_error\":" << dense_product_error
           << ",\"reaction_closure\":" << reaction_closure
           << ",\"active_centers\":"
           << derivative_state.active_centers
           << ",\"exact\":" << (derivative_exact ? "true" : "false")
           << "},\"cold\":{\"status\":\""
           << (cold.passed ? "PASS" : "FAIL")
           << "\",\"failure\":\"" << cold.failure
           << "\",\"state_root\":\"" << cold_root
           << "\",\"primal_monotone\":"
           << (cold.primal_monotone ? "true" : "false")
           << ",\"outer\":";
    append_outer(report, cold);
    report << "},\"warm\":{\"status\":\""
           << (warm.passed ? "PASS" : "FAIL")
           << "\",\"state_root\":\"" << warm_root
           << "\",\"position_error_dx\":" << warm_position_error
           << ",\"multiplier_max_difference\":" << warm_multiplier_error
           << ",\"exact\":" << (warm_exact ? "true" : "false")
           << ",\"outer\":";
    append_outer(report, warm);
    report << "},\"inactive\":{\"status\":\""
           << (inactive.passed ? "PASS" : "FAIL")
           << "\",\"state_root\":\"" << inactive_root
           << "\",\"exact\":" << (inactive_exact ? "true" : "false")
           << "},\"reset_negative\":{\"primal\":" << reset_primal
           << ",\"exact\":" << (reset_negative ? "true" : "false")
           << "},\"rollback_exact\":"
           << (rollback_exact ? "true" : "false")
           << ",\"mutation\":{\"root\":\"" << mutation_root
           << "\",\"control_root\":\"" << mutation_control_root
           << "\",\"sensitive\":"
           << (mutation_sensitive ? "true" : "false") << '}'
           << ",\"route\":\"" << route << '"'
           << ",\"trajectory_steps\":0,\"timing_admitted\":false"
           << ",\"tiny_vector_transaction_contract_research_authorized\":"
           << (passed ? "true" : "false")
           << ",\"nominal_trajectory_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport run_al_dense_vector_stable_commit_controls() {
    const Fixture fixture = make_box_fixture(
        "corner-box-2x2x2", {2, 2, 2}, 2);
    const std::vector<Vec3> boundary_before = fixture.boundary;
    const std::vector<Vec3> active_prediction =
        compressed_fluid(fixture, 0.99);
    const std::vector<Vec3> inactive_prediction =
        compressed_fluid(fixture, 1.01);
    const std::vector<double> zero_multiplier(fixture.fluid.size());
    const bool identity_exact = sha256_hex(B4E2D7R_IDENTITY_PROJECTION)
        == B4E2D7R_IDENTITY_SHA256;
    const Evaluation rest = evaluate(fixture.fluid, fixture.boundary);
    double rest_error = 0.0;
    for (double density : rest.density) {
        rest_error = std::max(rest_error,
            std::abs(density / REST_DENSITY - 1.0));
    }
    const bool fixture_exact = fixture.fluid.size() == 8U
        && fixture.boundary.size() == 176U && rest_error <= 3.0e-15;

    std::vector<double> derivative_multiplier(
        fixture.fluid.size(), 0.0053516806);
    const ALVectorSupport derivative_state = evaluate_al_vector_support(
        active_prediction, fixture.boundary, derivative_multiplier);
    const std::vector<Vec3> direction = deterministic_direction(
        active_prediction.size());
    constexpr double derivative_epsilon = 2.0e-7;
    const ALVectorSupport plus = evaluate_al_vector_support(
        displace(active_prediction, direction, derivative_epsilon),
        fixture.boundary, derivative_multiplier);
    const ALVectorSupport minus = evaluate_al_vector_support(
        displace(active_prediction, direction, -derivative_epsilon),
        fixture.boundary, derivative_multiplier);
    double analytic_direction = 0.0;
    for (std::size_t index = 0U;
         index < active_prediction.size(); ++index) {
        analytic_direction += dot(
            derivative_state.gradient[index], direction[index]);
    }
    const double finite_direction =
        (plus.energy - minus.energy) / (2.0 * derivative_epsilon);
    const double gradient_error = relative_error(
        analytic_direction, finite_direction);
    std::vector<Vec3> joint_direction(
        active_prediction.size() + fixture.boundary.size());
    std::copy(direction.begin(), direction.end(), joint_direction.begin());
    const std::vector<Vec3> analytic_hvp = fluid_part(
        apply_al_vector_hessian(active_prediction, fixture.boundary,
            derivative_multiplier, joint_direction),
        active_prediction.size());
    std::vector<Vec3> finite_hvp(active_prediction.size());
    for (std::size_t index = 0U;
         index < finite_hvp.size(); ++index) {
        finite_hvp[index] = (plus.gradient[index] - minus.gradient[index])
            / (2.0 * derivative_epsilon);
    }
    const double hvp_error = vector_relative_error(
        analytic_hvp, finite_hvp);
    const std::size_t dimension = 3U * active_prediction.size();
    std::vector<double> dense(dimension * dimension);
    for (std::size_t column = 0U; column < dimension; ++column) {
        std::vector<Vec3> basis(
            active_prediction.size() + fixture.boundary.size());
        set_component(basis[column / 3U],
            static_cast<int>(column % 3U), 1.0);
        const std::vector<double> product = flatten(fluid_part(
            apply_al_vector_hessian(active_prediction, fixture.boundary,
                derivative_multiplier, basis), active_prediction.size()));
        for (std::size_t row = 0U; row < dimension; ++row) {
            dense[row * dimension + column] = product[row];
        }
    }
    double maximum_asymmetry = 0.0;
    double maximum_dense = 0.0;
    for (std::size_t row = 0U; row < dimension; ++row) {
        for (std::size_t column = 0U; column < dimension; ++column) {
            maximum_asymmetry = std::max(maximum_asymmetry,
                std::abs(dense[row * dimension + column]
                    - dense[column * dimension + row]));
            maximum_dense = std::max(maximum_dense,
                std::abs(dense[row * dimension + column]));
        }
    }
    const double dense_symmetry_error = maximum_asymmetry
        / std::max(maximum_dense, 1.0e-30);
    const std::vector<double> flat_direction = flatten(direction);
    std::vector<double> dense_product(dimension);
    for (std::size_t row = 0U; row < dimension; ++row) {
        for (std::size_t column = 0U; column < dimension; ++column) {
            dense_product[row] += dense[row * dimension + column]
                * flat_direction[column];
        }
    }
    const std::vector<double> flat_hvp = flatten(analytic_hvp);
    double product_difference = 0.0;
    double product_scale = 0.0;
    for (std::size_t index = 0U; index < dimension; ++index) {
        product_difference += (dense_product[index] - flat_hvp[index])
            * (dense_product[index] - flat_hvp[index]);
        product_scale = std::max(product_scale,
            std::max(std::abs(dense_product[index]),
                std::abs(flat_hvp[index])));
    }
    const double dense_product_error = std::sqrt(product_difference)
        / std::max(product_scale * std::sqrt(
            static_cast<double>(dimension)), 1.0e-30);
    const Vec3 gradient_sum = sum_values(
        derivative_state.gradient, 0U,
        derivative_state.gradient.size());
    double gradient_scale = 0.0;
    for (Vec3 value : derivative_state.gradient) {
        gradient_scale += norm(value);
    }
    const double reaction_closure = norm(gradient_sum)
        / std::max(gradient_scale, 1.0e-30);
    const bool derivative_exact = derivative_state.finite_values
        && plus.finite_values && minus.finite_values
        && derivative_state.active_centers == plus.active_centers
        && derivative_state.active_centers == minus.active_centers
        && derivative_state.fluid_pairs == plus.fluid_pairs
        && derivative_state.fluid_pairs == minus.fluid_pairs
        && derivative_state.boundary_pairs == plus.boundary_pairs
        && derivative_state.boundary_pairs == minus.boundary_pairs
        && gradient_error <= 1.0e-7 && hvp_error <= 2.0e-6
        && dense_symmetry_error <= 2.0e-12
        && dense_product_error <= 2.0e-12
        && reaction_closure <= 1.0e-12
        && exact_vec3_values(fixture.boundary, boundary_before);

    const ALVectorStableSolve stable = solve_al_vector_stable(
        fixture, active_prediction, active_prediction, zero_multiplier);
    const std::string prefix_outer_json = al_vector_legacy_outer_json(
        stable.records, 8U);
    const std::string prefix_outer_root = sha256_hex(prefix_outer_json);
    const std::string prefix_state_root = al_vector_state_root(
        "cold", stable.prefix_position, stable.prefix_multiplier);
    const bool prefix_exact = stable.records.size() >= 8U
        && prefix_outer_root
            == "9bffc61a943f50cab449c052bd0a6791c40128e894d98d9a9589b0969dbb82c2"
        && prefix_state_root
            == "04a9c03308662d6102b165d8109b23c1b60a3145314603909b7dbfda8385d95e";

    const bool confirmed_indices = stable.passed
        && stable.provisional_index >= 0
        && stable.confirmation_index == stable.provisional_index + 1
        && static_cast<std::size_t>(stable.confirmation_index)
            < stable.records.size();
    const ALVectorOuterRecord provisional = confirmed_indices
        ? stable.records[static_cast<std::size_t>(stable.provisional_index)]
        : ALVectorOuterRecord{};
    const ALVectorOuterRecord confirmation = confirmed_indices
        ? stable.records[static_cast<std::size_t>(stable.confirmation_index)]
        : ALVectorOuterRecord{};
    const bool provisional_exact = confirmed_indices
        && provisional.primal <= 1.0e-8
        && provisional.stationarity <= 1.0e-8
        && provisional.complementarity <= 1.0e-9
        && provisional.minimum_multiplier >= 0.0
        && provisional.absolute_dual_change <= 1.0e-8
        && provisional.equivalent_pressure_change <= 8.0e-5
        && provisional.position_update_dx <= 1.0e-8;
    const bool confirmation_exact = confirmed_indices
        && confirmation.primal <= 1.0e-8
        && confirmation.stationarity <= 1.0e-8
        && confirmation.complementarity <= 1.0e-9
        && confirmation.minimum_multiplier >= 0.0
        && confirmation.absolute_dual_change <= 1.0e-8
        && confirmation.equivalent_pressure_change <= 8.0e-5
        && confirmation.position_update_dx <= 1.0e-8
        && rms_difference(
            stable.provisional_position, stable.position) / SPACING
                <= 1.0e-8;
    const std::string prior_public_root = al_vector_stable_state_root(
        "public-prior", active_prediction, zero_multiplier);
    const std::vector<Vec3> public_position = active_prediction;
    const std::vector<double> public_multiplier = zero_multiplier;
    const bool public_precommit_exact = exact_vec3_values(
            public_position, active_prediction)
        && exact_al_multiplier(public_multiplier, zero_multiplier);
    const std::string forced_private_root = al_vector_stable_state_root(
        "forced-private", stable.position, stable.multiplier);
    const std::string forced_public_root = al_vector_stable_state_root(
        "public-prior", public_position, public_multiplier);
    const bool forced_private_changed = !stable.records.empty()
        && (!exact_vec3_values(stable.position, public_position)
            || !exact_al_multiplier(
                stable.multiplier, public_multiplier));
    const bool forced_confirmation_rollback_exact = public_precommit_exact
        && forced_public_root == prior_public_root && forced_private_changed;
    const int commit_count = stable.passed && provisional_exact
            && confirmation_exact && public_precommit_exact
        ? 1 : 0;
    const std::string provisional_root = al_vector_stable_state_root(
        "provisional", stable.provisional_position,
        stable.provisional_multiplier);
    const std::string committed_root = al_vector_stable_state_root(
        "committed", stable.position, stable.multiplier);

    const ALVectorOuterSolve inactive = solve_al_vector_outer(
        fixture, inactive_prediction, inactive_prediction,
        zero_multiplier, 2);
    const bool inactive_exact = inactive.passed
        && exact_vec3_values(inactive.position, inactive_prediction)
        && exact_al_multiplier(inactive.multiplier, zero_multiplier)
        && std::all_of(inactive.support.constraint.begin(),
            inactive.support.constraint.end(),
            [](double value) { return value <= 0.0; });
    const ALVectorInnerSolve reset = solve_al_vector_inner(
        active_prediction, active_prediction,
        fixture.boundary, zero_multiplier);
    double reset_primal = 0.0;
    for (double value : reset.support.constraint) {
        reset_primal = std::max(reset_primal, std::max(0.0, value));
    }
    const bool reset_negative = reset.passed && reset_primal > 1.0e-8;
    std::vector<double> mutated_multiplier = stable.passed
        ? stable.multiplier : zero_multiplier;
    if (!mutated_multiplier.empty()) {
        mutated_multiplier.front() = std::nextafter(
            mutated_multiplier.front(),
            std::numeric_limits<double>::infinity());
    }
    const ALVectorInnerSolve mutation_control = solve_al_vector_inner(
        active_prediction,
        stable.passed ? stable.position : active_prediction,
        fixture.boundary,
        stable.passed ? stable.multiplier : zero_multiplier);
    const ALVectorInnerSolve mutation = solve_al_vector_inner(
        active_prediction,
        stable.passed ? stable.position : active_prediction,
        fixture.boundary, mutated_multiplier);
    const std::string mutation_control_root = al_vector_stable_state_root(
        "mutation", mutation_control.position,
        stable.passed ? stable.multiplier : zero_multiplier);
    const std::string mutation_root = al_vector_stable_state_root(
        "mutation", mutation.position, mutated_multiplier);
    const bool mutation_sensitive = mutation_control.passed
        && mutation.passed && mutation_root != mutation_control_root;

    const bool stable_commit = stable.passed && stable.primal_monotone
        && prefix_exact && provisional_exact && confirmation_exact
        && public_precommit_exact && forced_confirmation_rollback_exact
        && commit_count == 1 && inactive_exact && reset_negative
        && mutation_sensitive;
    const bool fallback_selected = !stable.passed && stable.inner_exact
        && stable.primal_monotone && stable.cap_exhausted
        && prefix_exact && inactive_exact && reset_negative
        && forced_confirmation_rollback_exact && mutation_sensitive;
    const std::string route = stable_commit ? "AL_DENSE_STABLE_COMMIT"
        : (fallback_selected
            ? "SEMISMOOTH_PRIMAL_DUAL_REQUIRED" : std::string{});
    const bool passed = identity_exact && fixture_exact && derivative_exact
        && !route.empty();
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!fixture_exact) first_failure = "FIXTURE";
    else if (!derivative_exact) first_failure = "DERIVATIVE";
    else if (!prefix_exact) first_failure = "D7_PREFIX";
    else if (route.empty()) first_failure = "STABLE_COMMIT_CONTROLS";

    const auto append_outer = [](std::ostringstream& output,
            const ALVectorStableSolve& solve) {
        output << '[';
        for (std::size_t index = 0U; index < solve.records.size(); ++index) {
            if (index != 0U) output << ',';
            const ALVectorOuterRecord& record = solve.records[index];
            output << std::setprecision(17)
                   << "{\"outer\":" << record.outer
                   << ",\"inner_outer_trials\":"
                   << record.inner_outer_trials
                   << ",\"inner_accepted_trials\":"
                   << record.inner_accepted_trials
                   << ",\"inner_rejected_trials\":"
                   << record.inner_rejected_trials
                   << ",\"inner_hvp_calls\":" << record.inner_hvp_calls
                   << ",\"primal\":" << record.primal
                   << ",\"scaled_dual_change\":"
                   << record.scaled_dual_change
                   << ",\"absolute_dual_change_j\":"
                   << record.absolute_dual_change
                   << ",\"equivalent_pressure_change_pa\":"
                   << record.equivalent_pressure_change
                   << ",\"position_update_dx\":"
                   << record.position_update_dx
                   << ",\"stationarity\":" << record.stationarity
                   << ",\"complementarity\":"
                   << record.complementarity
                   << ",\"multiplier_range\":["
                   << record.minimum_multiplier << ','
                   << record.maximum_multiplier << "]}";
        }
        output << ']';
    };

    std::ostringstream semantic;
    semantic << std::setprecision(17)
             << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D7R_IDENTITY_SHA256 << '|'
             << fixture.fluid.size() << ':' << fixture.boundary.size() << ':'
             << rest_error << '|' << gradient_error << ':' << hvp_error << ':'
             << dense_symmetry_error << ':' << dense_product_error << ':'
             << reaction_closure << '|' << prefix_outer_root << ':'
             << prefix_state_root << '|' << stable.passed << ':'
             << stable.records.size() << ':' << stable.provisional_index << ':'
             << stable.confirmation_index << ':' << provisional_root << ':'
             << committed_root << ':' << commit_count << '|'
             << inactive_exact << ':' << reset_negative << ':'
             << forced_confirmation_rollback_exact << ':'
             << mutation_sensitive << ':' << mutation_root << '|' << route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    std::ostringstream report;
    report << std::setprecision(17)
           << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d7r_al_stable_commit.v1\""
           << ",\"identity_sha256\":\"" << B4E2D7R_IDENTITY_SHA256
           << "\",\"solver_identity\":\""
              "nuv-al-pressure-r0+dense-vector-stable-commit-v1\""
           << ",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"fixture\":{\"fluid_samples\":"
           << fixture.fluid.size() << ",\"support_samples\":"
           << fixture.boundary.size() << ",\"rest_error\":"
           << rest_error << ",\"exact\":"
           << (fixture_exact ? "true" : "false") << '}'
           << ",\"derivatives\":{\"gradient_error\":"
           << gradient_error << ",\"hvp_error\":" << hvp_error
           << ",\"dense_symmetry_error\":" << dense_symmetry_error
           << ",\"dense_product_error\":" << dense_product_error
           << ",\"reaction_closure\":" << reaction_closure
           << ",\"active_centers\":"
           << derivative_state.active_centers
           << ",\"exact\":" << (derivative_exact ? "true" : "false")
           << "},\"d7_prefix\":{\"record_count\":8"
           << ",\"outer_root\":\"" << prefix_outer_root
           << "\",\"state_root\":\"" << prefix_state_root
           << "\",\"exact\":" << (prefix_exact ? "true" : "false")
           << "},\"stable\":{\"status\":\""
           << (stable.passed ? "PASS" : "FAIL")
           << "\",\"failure\":\"" << stable.failure
           << "\",\"primal_monotone\":"
           << (stable.primal_monotone ? "true" : "false")
           << ",\"provisional_index\":" << stable.provisional_index
           << ",\"confirmation_index\":" << stable.confirmation_index
           << ",\"provisional_root\":\"" << provisional_root
           << "\",\"committed_root\":\"" << committed_root
           << "\",\"provisional_exact\":"
           << (provisional_exact ? "true" : "false")
           << ",\"confirmation_exact\":"
           << (confirmation_exact ? "true" : "false")
           << ",\"outer\":";
    append_outer(report, stable);
    report << "},\"transaction\":{\"prior_public_root\":\""
           << prior_public_root << "\",\"public_precommit_exact\":"
           << (public_precommit_exact ? "true" : "false")
           << ",\"forced_private_root\":\"" << forced_private_root
           << "\",\"forced_public_root\":\"" << forced_public_root
           << "\",\"forced_confirmation_rollback_exact\":"
           << (forced_confirmation_rollback_exact ? "true" : "false")
           << ",\"commit_count\":" << commit_count << '}'
           << ",\"inactive\":{\"status\":\""
           << (inactive.passed ? "PASS" : "FAIL")
           << "\",\"exact\":" << (inactive_exact ? "true" : "false")
           << "},\"reset_negative\":{\"primal\":" << reset_primal
           << ",\"exact\":" << (reset_negative ? "true" : "false")
           << "},\"mutation\":{\"root\":\"" << mutation_root
           << "\",\"control_root\":\"" << mutation_control_root
           << "\",\"sensitive\":"
           << (mutation_sensitive ? "true" : "false") << '}'
           << ",\"route\":\"" << route << '"'
           << ",\"trajectory_steps\":0,\"timing_admitted\":false"
           << ",\"tiny_multistep_al_transaction_contract_research_"
              "authorized\":" << (passed ? "true" : "false")
           << ",\"nominal_trajectory_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport run_al_inner_floor_diagnostic_controls() {
    const Fixture fixture = make_box_fixture(
        "corner-box-2x2x2", {2, 2, 2}, 2);
    const std::vector<Vec3> active_prediction =
        compressed_fluid(fixture, 0.99);
    const std::vector<double> zero_multiplier(fixture.fluid.size());
    const bool identity_exact = sha256_hex(B4E2D7R1_IDENTITY_PROJECTION)
        == B4E2D7R1_IDENTITY_SHA256;

    const ALVectorStableSolve replay = solve_al_vector_stable(
        fixture, active_prediction, active_prediction, zero_multiplier);
    const std::string prefix_outer_root = sha256_hex(
        al_vector_legacy_outer_json(replay.records, 8U));
    const std::string prefix_state_root = al_vector_state_root(
        "cold", replay.prefix_position, replay.prefix_multiplier);
    const std::string failed_state_root = al_vector_stable_state_root(
        "forced-private", replay.position, replay.multiplier);
    const bool reproduction_exact = !replay.passed
        && replay.failure == "INNER:REJECT_LIMIT"
        && replay.records.size() == 10U && replay.primal_monotone
        && prefix_outer_root
            == "9bffc61a943f50cab449c052bd0a6791c40128e894d98d9a9589b0969dbb82c2"
        && prefix_state_root
            == "04a9c03308662d6102b165d8109b23c1b60a3145314603909b7dbfda8385d95e"
        && failed_state_root
            == "31840abd2f10907491360d75d57f6ecbbe6b0cf94672fa1b703bcb5ffa9d5830";

    const std::vector<Vec3> public_position = active_prediction;
    const std::vector<double> public_multiplier = zero_multiplier;
    const bool rollback_exact = exact_vec3_values(
            public_position, active_prediction)
        && exact_al_multiplier(public_multiplier, zero_multiplier)
        && (!exact_vec3_values(replay.position, public_position)
            || !exact_al_multiplier(
                replay.multiplier, public_multiplier));

    const ALVectorInnerFloorTrace trace = trace_al_vector_inner_floor(
        active_prediction, replay.position,
        fixture.boundary, replay.multiplier);
    const bool nested_and_direct = trace.passed
        && trace.all_topology_exact && trace.all_model_positive
        && trace.all_direct_descent && trace.all_raw_hidden;
    const bool accuracy_only = trace.passed
        && trace.all_topology_exact && trace.all_model_positive
        && trace.all_direct_descent && trace.all_raw_admit;
    const std::string route = nested_and_direct
        ? "NESTED_ACCURACY_AND_DIRECT_MERIT_RECLOSURE_REQUIRED"
        : (accuracy_only ? "INNER_ACCURACY_SCHEDULE_ONLY"
            : (trace.passed ? "MODEL_OR_ACTIVE_SET_RESEARCH_REQUIRED"
                : std::string{}));
    const bool passed = identity_exact && reproduction_exact
        && rollback_exact && trace.all_topology_exact && !route.empty();
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!reproduction_exact) first_failure = "D7R_REPRODUCTION";
    else if (!rollback_exact) first_failure = "ROLLBACK";
    else if (!trace.passed) first_failure = "INNER_TRACE";
    else if (!trace.all_topology_exact) first_failure = "TOPOLOGY_GATE";
    else if (route.empty()) first_failure = "ROUTE";

    std::ostringstream semantic;
    semantic << std::setprecision(17)
             << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D7R1_IDENTITY_SHA256 << '|' << prefix_outer_root << ':'
             << prefix_state_root << ':' << failed_state_root << '|'
             << trace.initial_total << ':' << trace.initial_support << ':'
             << trace.initial_inertia << ':' << trace.initial_gradient_norm
             << ':' << trace.initial_stationarity << '|';
    for (const ALVectorInnerFloorTrial& trial : trace.trials) {
        semantic << trial.trial << ':' << trial.hvp_calls << ':'
                 << trial.negative_curvature << ':' << trial.topology_exact
                 << ':' << trial.trust_radius_before << ':'
                 << trial.trust_radius_after << ':' << trial.step_norm_dx
                 << ':' << trial.predicted_reduction << ':'
                 << trial.raw_actual_reduction << ':'
                 << trial.direct_actual_reduction << ':' << trial.raw_ratio
                 << ':' << trial.current_energy_ulp << ':'
                 << trial.predicted_ulp_ratio << ';';
    }
    semantic << '|' << rollback_exact << ':' << route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    std::ostringstream report;
    report << std::setprecision(17)
           << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d7r1_inner_floor_diagnostic.v1\""
           << ",\"identity_sha256\":\"" << B4E2D7R1_IDENTITY_SHA256
           << "\",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"reproduction\":{\"d7_prefix_outer_root\":\""
           << prefix_outer_root << "\",\"d7_prefix_state_root\":\""
           << prefix_state_root << "\",\"failed_state_root\":\""
           << failed_state_root << "\",\"parent_failure\":\""
           << replay.failure << "\",\"parent_outer_records\":"
           << replay.records.size() << ",\"exact\":"
           << (reproduction_exact ? "true" : "false") << '}'
           << ",\"initial\":{\"total_energy\":" << trace.initial_total
           << ",\"total_energy_bits\":"
           << binary64_bits(trace.initial_total)
           << ",\"support_energy\":" << trace.initial_support
           << ",\"support_energy_bits\":"
           << binary64_bits(trace.initial_support)
           << ",\"inertia_energy\":" << trace.initial_inertia
           << ",\"inertia_energy_bits\":"
           << binary64_bits(trace.initial_inertia)
           << ",\"gradient_norm\":" << trace.initial_gradient_norm
           << ",\"scaled_stationarity\":"
           << trace.initial_stationarity
           << ",\"constraint_range\":[" << trace.minimum_constraint
           << ',' << trace.maximum_constraint
           << "],\"multiplier_range\":[" << trace.minimum_multiplier
           << ',' << trace.maximum_multiplier << "]}"
           << ",\"trace\":{\"status\":\""
           << (trace.passed ? "PASS" : "FAIL")
           << "\",\"accepted_trials\":" << trace.accepted_trials
           << ",\"rejected_trials\":" << trace.rejected_trials
           << ",\"all_topology_exact\":"
           << (trace.all_topology_exact ? "true" : "false")
           << ",\"all_model_positive\":"
           << (trace.all_model_positive ? "true" : "false")
           << ",\"all_direct_descent\":"
           << (trace.all_direct_descent ? "true" : "false")
           << ",\"all_raw_hidden\":"
           << (trace.all_raw_hidden ? "true" : "false")
           << ",\"all_raw_admit\":"
           << (trace.all_raw_admit ? "true" : "false")
           << ",\"trials\":[";
    for (std::size_t index = 0U; index < trace.trials.size(); ++index) {
        if (index != 0U) report << ',';
        const ALVectorInnerFloorTrial& trial = trace.trials[index];
        report << std::setprecision(17)
               << "{\"trial\":" << trial.trial
               << ",\"hvp_calls\":" << trial.hvp_calls
               << ",\"negative_curvature\":"
               << (trial.negative_curvature ? "true" : "false")
               << ",\"trust_radius_before\":"
               << trial.trust_radius_before
               << ",\"trust_radius_after\":"
               << trial.trust_radius_after
               << ",\"step_norm_dx\":" << trial.step_norm_dx
               << ",\"predicted_reduction\":"
               << trial.predicted_reduction
               << ",\"raw_actual_reduction\":"
               << trial.raw_actual_reduction
               << ",\"direct_actual_reduction\":"
               << trial.direct_actual_reduction
               << ",\"raw_ratio\":" << trial.raw_ratio
               << ",\"current_energy_ulp\":"
               << trial.current_energy_ulp
               << ",\"predicted_ulp_ratio\":"
               << trial.predicted_ulp_ratio
               << ",\"topology_exact\":"
               << (trial.topology_exact ? "true" : "false")
               << ",\"model_positive\":"
               << (trial.model_positive ? "true" : "false")
               << ",\"direct_descent\":"
               << (trial.direct_descent ? "true" : "false")
               << ",\"would_accept\":"
               << (trial.would_accept ? "true" : "false") << '}';
    }
    report << "]},\"rollback_exact\":"
           << (rollback_exact ? "true" : "false")
           << ",\"route\":\"" << route << '"'
           << ",\"trajectory_steps\":0,\"commit_count\":0"
           << ",\"physics_mutation\":false,\"timing_admitted\":false"
           << ",\"inner_remediation_contract_research_authorized\":"
           << (passed ? "true" : "false")
           << ",\"nominal_trajectory_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport run_al_topology_step_discriminator_controls() {
    const Fixture fixture = make_box_fixture(
        "corner-box-2x2x2", {2, 2, 2}, 2);
    const std::vector<Vec3> active_prediction =
        compressed_fluid(fixture, 0.99);
    const std::vector<double> zero_multiplier(fixture.fluid.size());
    const bool identity_exact = sha256_hex(B4E2D7R2_IDENTITY_PROJECTION)
        == B4E2D7R2_IDENTITY_SHA256;

    const ALVectorStableSolve replay = solve_al_vector_stable(
        fixture, active_prediction, active_prediction, zero_multiplier);
    const std::string prefix_outer_root = sha256_hex(
        al_vector_legacy_outer_json(replay.records, 8U));
    const std::string prefix_state_root = al_vector_state_root(
        "cold", replay.prefix_position, replay.prefix_multiplier);
    const std::string failed_state_root = al_vector_stable_state_root(
        "forced-private", replay.position, replay.multiplier);
    const bool reproduction_exact = !replay.passed
        && replay.failure == "INNER:REJECT_LIMIT"
        && replay.records.size() == 10U && replay.primal_monotone
        && prefix_outer_root
            == "9bffc61a943f50cab449c052bd0a6791c40128e894d98d9a9589b0969dbb82c2"
        && prefix_state_root
            == "04a9c03308662d6102b165d8109b23c1b60a3145314603909b7dbfda8385d95e"
        && failed_state_root
            == "31840abd2f10907491360d75d57f6ecbbe6b0cf94672fa1b703bcb5ffa9d5830";

    const ALTopologyStepTrace trace = trace_al_topology_step(
        active_prediction, replay.position,
        fixture.boundary, replay.multiplier);
    const bool passed = identity_exact && reproduction_exact && trace.passed
        && !trace.selected_route.empty();
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!reproduction_exact) first_failure = "D7R_REPRODUCTION";
    else if (!trace.full_reproduction_exact) first_failure = "D7R1_STEP";
    else if (!trace.kernel_horizon_exact) first_failure = "KERNEL_HORIZON";
    else if (!trace.set_accounting_exact) first_failure = "SET_ACCOUNTING";
    else if (!trace.all_finite) first_failure = "NONFINITE";
    else if (!trace.ladder_exact || !trace.any_coordinate_moved)
        first_failure = "ALPHA_LADDER";
    else if (!trace.directional_descent) first_failure = "DIRECTION";
    else if (!trace.rollback_exact) first_failure = "ROLLBACK";
    else if (trace.selected_route.empty()) first_failure = "ROUTE";

    std::ostringstream semantic;
    semantic << std::setprecision(17)
             << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D7R2_IDENTITY_SHA256 << '|' << prefix_outer_root << ':'
             << prefix_state_root << ':' << failed_state_root << '|'
             << trace.current_topology.active_root << ':'
             << trace.current_topology.fluid_root << ':'
             << trace.current_topology.boundary_root << '|'
             << trace.hvp_calls << ':' << trace.negative_curvature << ':'
             << trace.step_norm_m << ':' << trace.step_norm_dx << ':'
             << trace.directional_reduction << ':' << trace.binding_shrinks
             << ':' << trace.missing_shrinks_after_cap << '|';
    for (const ALTopologyPairDetail& detail : trace.changed_pairs) {
        semantic << detail.pair.kind << ':' << detail.pair.center << ':'
                 << detail.pair.participant << ':' << detail.added << ':'
                 << detail.current_radius << ':' << detail.trial_radius << ':'
                 << detail.current_margin << ':' << detail.trial_margin << ':'
                 << detail.current_weight << ':' << detail.trial_weight << ':'
                 << detail.current_first << ':' << detail.trial_first << ':'
                 << detail.current_second << ':' << detail.trial_second << ';';
    }
    semantic << '|';
    for (const ALTopologyAlphaRow& row : trace.rows) {
        semantic << row.exponent << ':' << row.alpha << ':'
                 << row.coordinate_moved << ':' << row.rounded_step_norm_m
                 << ':' << row.predicted_reduction << ':'
                 << row.raw_actual_reduction << ':'
                 << row.direct_actual_reduction << ':' << row.direct_ratio
                 << ':' << row.branch_actual_reduction << ':'
                 << row.branch_ratio << ':' << row.topology.active_root << ':'
                 << row.topology.fluid_root << ':'
                 << row.topology.boundary_root << ':' << row.active_added
                 << ':' << row.active_removed << ':' << row.fluid_added << ':'
                 << row.fluid_removed << ':' << row.boundary_added << ':'
                 << row.boundary_removed << ';';
    }
    semantic << '|' << trace.rollback_exact << ':' << trace.selected_route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    const auto append_indices = [](std::ostringstream& output,
                                   const std::vector<std::size_t>& values) {
        output << '[';
        for (std::size_t index = 0U; index < values.size(); ++index) {
            if (index != 0U) output << ',';
            output << values[index];
        }
        output << ']';
    };
    const auto append_pair_keys = [](std::ostringstream& output,
                                     const std::vector<ALTopologyPair>& values) {
        output << '[';
        for (std::size_t index = 0U; index < values.size(); ++index) {
            if (index != 0U) output << ',';
            output << "{\"kind\":\"" << values[index].kind
                   << "\",\"center\":" << values[index].center
                   << ",\"participant\":"
                   << values[index].participant << '}';
        }
        output << ']';
    };

    std::ostringstream report;
    report << std::setprecision(17)
           << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d7r2_topology_step_discriminator.v1\""
           << ",\"identity_sha256\":\"" << B4E2D7R2_IDENTITY_SHA256
           << "\",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"reproduction\":{\"d7_prefix_outer_root\":\""
           << prefix_outer_root << "\",\"d7_prefix_state_root\":\""
           << prefix_state_root << "\",\"failed_state_root\":\""
           << failed_state_root << "\",\"parent_failure\":\""
           << replay.failure << "\",\"parent_outer_records\":"
           << replay.records.size() << ",\"exact\":"
           << (reproduction_exact ? "true" : "false") << '}'
           << ",\"kernel_horizon\":{\"radius_m\":" << HORIZON
           << ",\"epsilon_h\":"
           << std::numeric_limits<double>::epsilon() * HORIZON
           << ",\"weight\":" << weight(HORIZON)
           << ",\"first\":" << weight_gradient(HORIZON)
           << ",\"second\":" << weight_second(HORIZON)
           << ",\"positive_zero_exact\":"
           << (trace.kernel_horizon_exact ? "true" : "false") << '}'
           << ",\"step\":{\"hvp_calls\":" << trace.hvp_calls
           << ",\"negative_curvature\":"
           << (trace.negative_curvature ? "true" : "false")
           << ",\"norm_m\":" << trace.step_norm_m
           << ",\"norm_dx\":" << trace.step_norm_dx
           << ",\"directional_reduction\":"
           << trace.directional_reduction
           << ",\"binding_shrinks\":" << trace.binding_shrinks
           << ",\"missing_shrinks_after_cap\":"
           << trace.missing_shrinks_after_cap
           << ",\"full_reproduction_exact\":"
           << (trace.full_reproduction_exact ? "true" : "false") << '}'
           << ",\"current_sets\":{\"active_root\":\""
           << trace.current_topology.active_root
           << "\",\"active_count\":"
           << trace.current_topology.active.size()
           << ",\"fluid_root\":\"" << trace.current_topology.fluid_root
           << "\",\"fluid_count\":"
           << trace.current_topology.fluid.size()
           << ",\"boundary_root\":\""
           << trace.current_topology.boundary_root
           << "\",\"boundary_count\":"
           << trace.current_topology.boundary.size() << '}'
           << ",\"full_set_delta\":{\"active_added\":";
    append_indices(report, trace.active_added);
    report << ",\"active_removed\":";
    append_indices(report, trace.active_removed);
    report << ",\"fluid_added\":";
    append_pair_keys(report, trace.fluid_added);
    report << ",\"fluid_removed\":";
    append_pair_keys(report, trace.fluid_removed);
    report << ",\"boundary_added\":";
    append_pair_keys(report, trace.boundary_added);
    report << ",\"boundary_removed\":";
    append_pair_keys(report, trace.boundary_removed);
    report << ",\"accounting_exact\":"
           << (trace.set_accounting_exact ? "true" : "false") << '}'
           << ",\"changed_pairs\":[";
    for (std::size_t index = 0U;
         index < trace.changed_pairs.size(); ++index) {
        if (index != 0U) report << ',';
        const ALTopologyPairDetail& value = trace.changed_pairs[index];
        report << "{\"kind\":\"" << value.pair.kind
               << "\",\"center\":" << value.pair.center
               << ",\"participant\":" << value.pair.participant
               << ",\"change\":\"" << (value.added ? "ADDED" : "REMOVED")
               << "\",\"current_radius_m\":" << value.current_radius
               << ",\"trial_radius_m\":" << value.trial_radius
               << ",\"current_margin_m\":" << value.current_margin
               << ",\"trial_margin_m\":" << value.trial_margin
               << ",\"current_margin_epsilon_h\":"
               << value.current_margin_epsilon
               << ",\"trial_margin_epsilon_h\":"
               << value.trial_margin_epsilon
               << ",\"current_kernel\":[" << value.current_weight << ','
               << value.current_first << ',' << value.current_second << ']'
               << ",\"trial_kernel\":[" << value.trial_weight << ','
               << value.trial_first << ',' << value.trial_second << "]}";
    }
    report << "],\"ladder\":[";
    for (std::size_t index = 0U; index < trace.rows.size(); ++index) {
        if (index != 0U) report << ',';
        const ALTopologyAlphaRow& row = trace.rows[index];
        report << "{\"exponent\":" << row.exponent
               << ",\"alpha\":" << row.alpha
               << ",\"coordinate_moved\":"
               << (row.coordinate_moved ? "true" : "false")
               << ",\"rounded_step_norm_m\":"
               << row.rounded_step_norm_m
               << ",\"rounded_step_norm_dx\":"
               << row.rounded_step_norm_dx
               << ",\"predicted_reduction\":"
               << row.predicted_reduction
               << ",\"raw_actual_reduction\":"
               << row.raw_actual_reduction
               << ",\"direct_actual_reduction\":"
               << row.direct_actual_reduction
               << ",\"direct_ratio\":" << row.direct_ratio
               << ",\"current_branch_actual_reduction\":"
               << row.branch_actual_reduction
               << ",\"current_branch_ratio\":" << row.branch_ratio
               << ",\"active_root\":\"" << row.topology.active_root
               << "\",\"fluid_root\":\"" << row.topology.fluid_root
               << "\",\"boundary_root\":\""
               << row.topology.boundary_root
               << "\",\"active_delta\":[" << row.active_added << ','
               << row.active_removed << "],\"fluid_delta\":["
               << row.fluid_added << ',' << row.fluid_removed
               << "],\"boundary_delta\":[" << row.boundary_added << ','
               << row.boundary_removed << "]}";
    }
    report << "],\"gates\":{\"all_finite\":"
           << (trace.all_finite ? "true" : "false")
           << ",\"ladder_exact\":"
           << (trace.ladder_exact ? "true" : "false")
           << ",\"any_coordinate_moved\":"
           << (trace.any_coordinate_moved ? "true" : "false")
           << ",\"directional_descent\":"
           << (trace.directional_descent ? "true" : "false")
           << ",\"rollback_exact\":"
           << (trace.rollback_exact ? "true" : "false") << '}'
           << ",\"route\":\"" << trace.selected_route << '"'
           << ",\"trajectory_steps\":0,\"commit_count\":0"
           << ",\"physics_mutation\":false,\"timing_admitted\":false"
           << ",\"selected_remediation_research_authorized\":"
           << (passed ? "true" : "false")
           << ",\"nominal_trajectory_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport
run_al_topology_step_signed_zero_reclosure_controls() {
    const bool identity_exact = sha256_hex(B4E2D7R2R_IDENTITY_PROJECTION)
        == B4E2D7R2R_IDENTITY_SHA256;
    const SplitBoundaryReport parent =
        run_al_topology_step_discriminator_controls();
    const std::string parent_stdout_sha256 = sha256_hex(parent.json + "\n");
    const bool parent_exact = !parent.passed
        && parent_stdout_sha256
            == "f6b18542b1a25a548a11925552f014148152c817c8de557a86f9e97f4c628bcb";

    const Fixture fixture = make_box_fixture(
        "corner-box-2x2x2", {2, 2, 2}, 2);
    const std::vector<Vec3> active_prediction =
        compressed_fluid(fixture, 0.99);
    const std::vector<double> zero_multiplier(fixture.fluid.size());
    const ALVectorStableSolve replay = solve_al_vector_stable(
        fixture, active_prediction, active_prediction, zero_multiplier);
    const ALTopologyStepTrace trace = trace_al_topology_step(
        active_prediction, replay.position,
        fixture.boundary, replay.multiplier);

    const std::uint64_t weight_bits = binary64_bits(weight(HORIZON));
    const std::uint64_t first_bits =
        binary64_bits(weight_gradient(HORIZON));
    const std::uint64_t second_bits = binary64_bits(weight_second(HORIZON));
    const bool signed_zero_exact = trace.kernel_horizon_numerical_zero
        && weight_bits == 0U
        && first_bits == UINT64_C(9223372036854775808)
        && second_bits == 0U;
    const bool prior_gates_exact = trace.full_reproduction_exact
        && trace.set_accounting_exact && trace.all_finite
        && trace.ladder_exact && trace.any_coordinate_moved
        && trace.directional_descent && trace.rollback_exact;
    const bool current_sets_exact =
        trace.current_topology.active.size() == 8U
        && trace.current_topology.fluid.size() == 28U
        && trace.current_topology.boundary.size() == 800U;
    const bool full_delta_exact = trace.active_added.empty()
        && trace.active_removed.empty() && trace.fluid_added.empty()
        && trace.fluid_removed.empty()
        && trace.boundary_added.size() == 72U
        && trace.boundary_removed.size() == 120U;
    const ALTopologyAlphaRow& half = trace.rows.size() > 1U
        ? trace.rows[1] : ALTopologyAlphaRow{};
    const bool half_exact = trace.rows.size() > 1U && half.exponent == 1
        && half.coordinate_moved && half.active_added == 0U
        && half.active_removed == 0U && half.fluid_added == 0U
        && half.fluid_removed == 0U && half.boundary_added == 0U
        && half.boundary_removed == 0U
        && half.predicted_reduction > 0.0
        && half.direct_actual_reduction > 0.0
        && half.direct_ratio >= 0.1;
    const bool route_exact = trace.candidate_route
        == "TRUST_REJECT_POLICY_RECLOSURE_REQUIRED";
    const bool passed = identity_exact && parent_exact && signed_zero_exact
        && prior_gates_exact && current_sets_exact && full_delta_exact
        && half_exact && route_exact;
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!parent_exact) first_failure = "PARENT_REPORT";
    else if (!signed_zero_exact) first_failure = "SIGNED_ZERO";
    else if (!prior_gates_exact) first_failure = "D7R2_TRACE";
    else if (!current_sets_exact) first_failure = "CURRENT_SETS";
    else if (!full_delta_exact) first_failure = "FULL_DELTA";
    else if (!half_exact) first_failure = "HALF_STEP";
    else if (!route_exact) first_failure = "ROUTE";
    const std::string route = passed ? trace.candidate_route : std::string{};

    std::ostringstream semantic;
    semantic << std::setprecision(17)
             << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D7R2R_IDENTITY_SHA256 << '|' << parent_stdout_sha256
             << '|' << weight_bits << ':' << first_bits << ':' << second_bits
             << ':' << trace.kernel_horizon_numerical_zero << '|'
             << trace.current_topology.active.size() << ':'
             << trace.current_topology.fluid.size() << ':'
             << trace.current_topology.boundary.size() << '|'
             << trace.active_added.size() << ':'
             << trace.active_removed.size() << ':'
             << trace.fluid_added.size() << ':'
             << trace.fluid_removed.size() << ':'
             << trace.boundary_added.size() << ':'
             << trace.boundary_removed.size() << '|'
             << half.predicted_reduction << ':'
             << half.raw_actual_reduction << ':'
             << half.direct_actual_reduction << ':' << half.direct_ratio
             << ':' << half.branch_actual_reduction << '|'
             << trace.binding_shrinks << ':'
             << trace.missing_shrinks_after_cap << '|'
             << trace.rollback_exact << ':' << route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    std::ostringstream report;
    report << std::setprecision(17)
           << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d7r2r_signed_zero_reclosure.v1\""
           << ",\"identity_sha256\":\"" << B4E2D7R2R_IDENTITY_SHA256
           << "\",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"parent\":{\"stdout_sha256\":\""
           << parent_stdout_sha256 << "\",\"failed\":"
           << (!parent.passed ? "true" : "false")
           << ",\"exact\":" << (parent_exact ? "true" : "false") << '}'
           << ",\"kernel_horizon\":{\"values\":[" << weight(HORIZON)
           << ',' << weight_gradient(HORIZON) << ',' << weight_second(HORIZON)
           << "],\"bits\":[" << weight_bits << ',' << first_bits << ','
           << second_bits << "],\"signbits\":["
           << (std::signbit(weight(HORIZON)) ? "true" : "false") << ','
           << (std::signbit(weight_gradient(HORIZON)) ? "true" : "false")
           << ',' << (std::signbit(weight_second(HORIZON)) ? "true" : "false")
           << "],\"numerical_zero\":"
           << (trace.kernel_horizon_numerical_zero ? "true" : "false")
           << ",\"exact\":" << (signed_zero_exact ? "true" : "false")
           << '}'
           << ",\"trace\":{\"prior_gates_exact\":"
           << (prior_gates_exact ? "true" : "false")
           << ",\"current_counts\":["
           << trace.current_topology.active.size() << ','
           << trace.current_topology.fluid.size() << ','
           << trace.current_topology.boundary.size()
           << "],\"full_delta\":{\"active\":["
           << trace.active_added.size() << ',' << trace.active_removed.size()
           << "],\"fluid\":[" << trace.fluid_added.size() << ','
           << trace.fluid_removed.size() << "],\"boundary\":["
           << trace.boundary_added.size() << ','
           << trace.boundary_removed.size() << "]}"
           << ",\"binding_shrinks\":" << trace.binding_shrinks
           << ",\"missing_shrinks_after_cap\":"
           << trace.missing_shrinks_after_cap << '}'
           << ",\"half_step\":{\"exponent\":" << half.exponent
           << ",\"coordinate_moved\":"
           << (half.coordinate_moved ? "true" : "false")
           << ",\"predicted_reduction\":" << half.predicted_reduction
           << ",\"raw_actual_reduction\":" << half.raw_actual_reduction
           << ",\"direct_actual_reduction\":"
           << half.direct_actual_reduction
           << ",\"direct_ratio\":" << half.direct_ratio
           << ",\"current_branch_actual_reduction\":"
           << half.branch_actual_reduction
           << ",\"topology_stable\":"
           << (half_exact ? "true" : "false") << '}'
           << ",\"route\":\"" << route << '"'
           << ",\"rollback_exact\":"
           << (trace.rollback_exact ? "true" : "false")
           << ",\"trajectory_steps\":0,\"commit_count\":0"
           << ",\"physics_mutation\":false,\"timing_admitted\":false"
           << ",\"trust_policy_research_authorized\":"
           << (passed ? "true" : "false")
           << ",\"trust_policy_implementation_authorized\":false"
           << ",\"nominal_trajectory_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport run_al_globalization_policy_discriminator_controls() {
    const bool identity_exact = sha256_hex(B4E2D7R3_IDENTITY_PROJECTION)
        == B4E2D7R3_IDENTITY_SHA256;
    const SplitBoundaryReport parent =
        run_al_topology_step_signed_zero_reclosure_controls();
    const std::string parent_stdout_sha256 = sha256_hex(parent.json + "\n");
    const bool parent_exact = parent.passed
        && parent_stdout_sha256
            == "36a6c45b08e595818a4ce86a7bde3d88d3a923f250e0ed9d859973aeb083786e";

    const Fixture fixture = make_box_fixture(
        "corner-box-2x2x2", {2, 2, 2}, 2);
    const std::vector<Vec3> predicted = compressed_fluid(fixture, 0.99);
    const std::vector<double> zero_multiplier(fixture.fluid.size());
    const ALVectorStableSolve replay = solve_al_vector_stable(
        fixture, predicted, predicted, zero_multiplier);
    const std::string failed_state_root = al_vector_stable_state_root(
        "forced-private", replay.position, replay.multiplier);
    const bool replay_exact = !replay.passed
        && replay.failure == "INNER:REJECT_LIMIT"
        && failed_state_root
            == "31840abd2f10907491360d75d57f6ecbbe6b0cf94672fa1b703bcb5ffa9d5830";
    const ALVectorInnerState current = evaluate_al_vector_inner(
        replay.position, predicted, fixture.boundary, replay.multiplier);
    const ALTopologySets current_topology = al_topology_sets(
        replay.position, fixture.boundary, current.support);
    int base_hvp_calls = 0;
    bool base_negative_curvature = false;
    const double old_radius = 0.25 * SPACING;
    const std::vector<Vec3> base_step = al_vector_trust_step(
        replay.position, fixture.boundary, replay.multiplier,
        current.gradient, old_radius, base_hvp_calls,
        base_negative_curvature);
    const std::vector<Vec3> base_image = apply_al_vector_inner_hessian(
        replay.position, fixture.boundary, replay.multiplier, base_step);
    ++base_hvp_calls;
    const std::vector<Vec3> base_trial_position = add_scaled(
        replay.position, base_step, 1.0);
    const ALVectorInnerState base_trial = evaluate_al_vector_inner(
        base_trial_position, predicted, fixture.boundary, replay.multiplier);
    const double gradient_step = flat_dot(current.gradient, base_step);
    const double base_predicted = -gradient_step
        - 0.5 * flat_dot(base_step, base_image);
    const double base_raw = current.total - base_trial.total;
    const double base_direct = al_vector_direct_actual_reduction(
        replay.position, base_trial_position, predicted,
        current.support, base_trial.support);
    const double base_norm = vector_norm(base_step);
    const bool base_exact = base_hvp_calls == 2
        && !base_negative_curvature
        && base_norm / SPACING == 4.9587280227513481e-9
        && base_predicted == 1.3230255447006828e-15
        && base_raw == -4.5363018896793506e-16
        && base_direct == -4.528143341123291e-16;

    const ALTopologyStepTrace ladder = trace_al_topology_step(
        predicted, replay.position, fixture.boundary, replay.multiplier);
    int backtrack_exponent = -1;
    for (std::size_t index = 0U;
         index < ladder.rows.size() && index <= 6U; ++index) {
        const ALTopologyAlphaRow& row = ladder.rows[index];
        const bool topology_exact = row.topology.active_root
                == current_topology.active_root
            && row.topology.fluid_root == current_topology.fluid_root
            && row.topology.boundary_root == current_topology.boundary_root;
        if (backtrack_exponent < 0 && row.coordinate_moved
            && topology_exact && row.predicted_reduction > 0.0
            && row.direct_actual_reduction > 0.0
            && row.direct_ratio >= 0.1) {
            backtrack_exponent = row.exponent;
        }
    }
    const bool backtrack_admitted = backtrack_exponent >= 0;

    const double interpolation_numerator = -gradient_step;
    const double interpolation_denominator = 2.0
        * ((-base_direct) - gradient_step);
    const double alpha_hat = interpolation_numerator
        / interpolation_denominator;
    const double step_radius = std::min(
        std::max(alpha_hat, 0.25) * base_norm, 0.5 * old_radius);
    const ALGlobalizationProposal step_trust =
        evaluate_al_globalization_proposal(
            predicted, replay.position, fixture.boundary,
            replay.multiplier, current, current_topology, step_radius);
    const bool step_trust_selected = std::isfinite(alpha_hat)
        && alpha_hat > 0.0 && step_radius > 0.0
        && step_radius < base_norm && step_trust.boundary_limited
        && step_trust.admitted && step_trust.hvp_calls <= 2;

    double legacy_radius = old_radius;
    int legacy_shrinks = 0;
    while (legacy_radius > base_norm && legacy_shrinks < 128) {
        legacy_radius *= 0.25;
        ++legacy_shrinks;
    }
    const ALGlobalizationProposal legacy =
        evaluate_al_globalization_proposal(
            predicted, replay.position, fixture.boundary,
            replay.multiplier, current, current_topology, legacy_radius);
    const bool legacy_admitted = legacy_shrinks == 13
        && legacy.boundary_limited && legacy.admitted;

    const std::string candidate_route = step_trust_selected
        ? "STEP_NORM_AWARE_TRUST_SELECTED"
        : (backtrack_admitted ? "HYBRID_BACKTRACK_SELECTED"
            : (legacy_admitted ? "LEGACY_BINDING_POLICY_RESEARCH"
                : "STEIHAUG_FALLBACK_RESEARCH"));
    const bool finite_values = current.support.finite_values
        && std::isfinite(interpolation_numerator)
        && std::isfinite(interpolation_denominator)
        && interpolation_denominator > 0.0 && std::isfinite(alpha_hat)
        && std::isfinite(step_radius) && step_trust.finite_values
        && legacy.finite_values;
    const bool rollback_exact = exact_vec3_values(predicted,
            compressed_fluid(fixture, 0.99))
        && std::all_of(zero_multiplier.begin(), zero_multiplier.end(),
            [](double value) { return binary64_bits(value) == 0U; });
    const bool passed = identity_exact && parent_exact && replay_exact
        && base_exact && ladder.ladder_exact && finite_values
        && rollback_exact && !candidate_route.empty();
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!parent_exact) first_failure = "PARENT";
    else if (!replay_exact) first_failure = "REPLAY";
    else if (!base_exact) first_failure = "BASE_STEP";
    else if (!ladder.ladder_exact) first_failure = "BACKTRACK_LADDER";
    else if (!finite_values) first_failure = "NONFINITE";
    else if (!rollback_exact) first_failure = "ROLLBACK";
    const std::string route = passed ? candidate_route : std::string{};

    std::ostringstream semantic;
    semantic << std::setprecision(17)
             << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D7R3_IDENTITY_SHA256 << '|' << parent_stdout_sha256
             << '|' << failed_state_root << '|' << gradient_step << ':'
             << base_norm << ':' << base_predicted << ':' << base_raw << ':'
             << base_direct << '|' << backtrack_exponent << '|'
             << interpolation_numerator << ':' << interpolation_denominator
             << ':' << alpha_hat << ':' << step_radius << '|'
             << step_trust.hvp_calls << ':' << step_trust.step_norm << ':'
             << step_trust.predicted_reduction << ':'
             << step_trust.raw_actual_reduction << ':'
             << step_trust.direct_actual_reduction << ':'
             << step_trust.direct_ratio << ':' << step_trust.boundary_limited
             << ':' << step_trust.topology_exact << '|'
             << legacy_shrinks << ':' << legacy_radius << ':'
             << legacy.hvp_calls << ':' << legacy.step_norm << ':'
             << legacy.predicted_reduction << ':'
             << legacy.direct_actual_reduction << ':' << legacy.direct_ratio
             << ':' << legacy.boundary_limited << ':'
             << legacy.topology_exact << '|' << rollback_exact << ':' << route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    const auto append_proposal = [](std::ostringstream& output,
                                    const ALGlobalizationProposal& value) {
        output << std::setprecision(17)
               << "{\"radius_m\":" << value.radius
               << ",\"step_norm_m\":" << value.step_norm
               << ",\"hvp_calls\":" << value.hvp_calls
               << ",\"negative_curvature\":"
               << (value.negative_curvature ? "true" : "false")
               << ",\"boundary_limited\":"
               << (value.boundary_limited ? "true" : "false")
               << ",\"predicted_reduction\":"
               << value.predicted_reduction
               << ",\"raw_actual_reduction\":"
               << value.raw_actual_reduction
               << ",\"direct_actual_reduction\":"
               << value.direct_actual_reduction
               << ",\"direct_ratio\":" << value.direct_ratio
               << ",\"topology_exact\":"
               << (value.topology_exact ? "true" : "false")
               << ",\"admitted\":"
               << (value.admitted ? "true" : "false") << '}';
    };
    std::ostringstream report;
    report << std::setprecision(17)
           << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d7r3_globalization_policy.v1\""
           << ",\"identity_sha256\":\"" << B4E2D7R3_IDENTITY_SHA256
           << "\",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"parent\":{\"stdout_sha256\":\""
           << parent_stdout_sha256 << "\",\"exact\":"
           << (parent_exact ? "true" : "false") << '}'
           << ",\"base\":{\"state_root\":\"" << failed_state_root
           << "\",\"gradient_step\":" << gradient_step
           << ",\"step_norm_m\":" << base_norm
           << ",\"predicted_reduction\":" << base_predicted
           << ",\"raw_actual_reduction\":" << base_raw
           << ",\"direct_actual_reduction\":" << base_direct
           << ",\"hvp_calls\":" << base_hvp_calls
           << ",\"exact\":" << (base_exact ? "true" : "false") << '}'
           << ",\"backtrack\":{\"first_admitted_exponent\":"
           << backtrack_exponent << ",\"rows\":[";
    for (std::size_t index = 0U;
         index < ladder.rows.size() && index <= 6U; ++index) {
        if (index != 0U) report << ',';
        const ALTopologyAlphaRow& row = ladder.rows[index];
        const bool topology_exact = row.topology.active_root
                == current_topology.active_root
            && row.topology.fluid_root == current_topology.fluid_root
            && row.topology.boundary_root == current_topology.boundary_root;
        report << "{\"exponent\":" << row.exponent
               << ",\"alpha\":" << row.alpha
               << ",\"step_norm_m\":" << row.rounded_step_norm_m
               << ",\"coordinate_moved\":"
               << (row.coordinate_moved ? "true" : "false")
               << ",\"predicted_reduction\":"
               << row.predicted_reduction
               << ",\"raw_actual_reduction\":"
               << row.raw_actual_reduction
               << ",\"direct_actual_reduction\":"
               << row.direct_actual_reduction
               << ",\"direct_ratio\":" << row.direct_ratio
               << ",\"topology_exact\":"
               << (topology_exact ? "true" : "false") << '}';
    }
    report << "]},\"step_norm_trust\":{\"interpolation_numerator\":"
           << interpolation_numerator
           << ",\"interpolation_denominator\":"
           << interpolation_denominator << ",\"alpha_hat\":" << alpha_hat
           << ",\"radius_to_rejected_norm\":"
           << step_radius / base_norm << ",\"proposal\":";
    append_proposal(report, step_trust);
    report << "},\"legacy_first_binding\":{\"shrinks\":"
           << legacy_shrinks << ",\"repeated_proposals_before_binding\":"
           << legacy_shrinks
           << ",\"repeated_hvp_before_binding\":"
           << 2 * legacy_shrinks
           << ",\"repeated_objectives_before_binding\":"
           << legacy_shrinks << ",\"proposal\":";
    append_proposal(report, legacy);
    report << "},\"route\":\"" << route << '"'
           << ",\"rollback_exact\":"
           << (rollback_exact ? "true" : "false")
           << ",\"trajectory_steps\":0,\"commit_count\":0"
           << ",\"physics_mutation\":false,\"timing_admitted\":false"
           << ",\"policy_contract_research_authorized\":"
           << (passed ? "true" : "false")
           << ",\"policy_implementation_authorized\":false"
           << ",\"nominal_trajectory_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport run_al_step_norm_trust_inner_controls() {
    const bool identity_exact = sha256_hex(B4E2D7R4_IDENTITY_PROJECTION)
        == B4E2D7R4_IDENTITY_SHA256;
    const SplitBoundaryReport parent =
        run_al_globalization_policy_discriminator_controls();
    const std::string parent_stdout_sha256 = sha256_hex(parent.json + "\n");
    const bool parent_exact = parent.passed
        && parent_stdout_sha256
            == "b52f9a599f2b0312fbe73ed8686f623a7142a967b497f507345ed7a47bc00f3c";
    const Fixture fixture = make_box_fixture(
        "corner-box-2x2x2", {2, 2, 2}, 2);
    const std::vector<Vec3> predicted = compressed_fluid(fixture, 0.99);
    const std::vector<double> zero_multiplier(fixture.fluid.size());
    const ALVectorStableSolve replay = solve_al_vector_stable(
        fixture, predicted, predicted, zero_multiplier);
    const std::string failed_state_root = al_vector_stable_state_root(
        "forced-private", replay.position, replay.multiplier);
    const bool replay_exact = !replay.passed
        && replay.failure == "INNER:REJECT_LIMIT"
        && failed_state_root
            == "31840abd2f10907491360d75d57f6ecbbe6b0cf94672fa1b703bcb5ffa9d5830";

    const ALStepNormInnerSolve candidate = solve_al_vector_inner_step_norm(
        predicted, replay.position, fixture.boundary, replay.multiplier);
    const bool first_event_exact = candidate.trials.size() >= 2U
        && candidate.trials[0].radius_owner == "STEP_NORM"
        && candidate.trials[0].radius_after == 1.0585364232894624e-10
        && candidate.trials[0].predicted_reduction
            == 1.3230255447006828e-15
        && candidate.trials[0].direct_actual_reduction
            == -4.528143341123291e-16
        && candidate.trials[1].radius_before
            == 1.0585364232894624e-10
        && candidate.trials[1].step_norm
            == 1.0585364232894623e-10
        && candidate.trials[1].predicted_reduction
            == 8.8854492836625599e-16
        && candidate.trials[1].raw_actual_reduction
            == 6.4965394175331426e-16
        && candidate.trials[1].direct_actual_reduction
            == 6.4902965076063732e-16
        && candidate.trials[1].direct_ratio
            == 0.7304410053344077
        && candidate.trials[1].topology_exact
        && candidate.trials[1].accepted;
    bool fallback_used = false;
    bool fallback_invalid = false;
    const double fallback_radius = al_step_norm_rejected_radius(
        4.0, 1.0, -1.0, 2.0, true,
        fallback_used, fallback_invalid);
    const bool fallback_exact = fallback_radius == 1.0
        && !fallback_used && fallback_invalid;
    const bool convergence_exact = candidate.passed
        && candidate.failure.empty() && candidate.all_finite
        && candidate.positive_accepted_models
        && candidate.final_stationarity <= 1.0e-8
        && candidate.rejected_trials <= 8
        && candidate.trials.size() <= 64U
        && candidate.step_norm_updates >= 1
        && !candidate.invalid_interpolation_owned;
    const bool rollback_exact = exact_al_multiplier(
            replay.multiplier, replay.multiplier)
        && exact_vec3_values(predicted, compressed_fluid(fixture, 0.99))
        && !exact_vec3_values(candidate.position, predicted);
    const std::string candidate_state_root = al_vector_stable_state_root(
        "step-norm-inner-private", candidate.position, replay.multiplier);
    const std::string route = identity_exact && parent_exact && replay_exact
            && first_event_exact && fallback_exact && convergence_exact
            && rollback_exact
        ? "STEP_NORM_TRUST_INNER_CANDIDATE" : std::string{};
    const bool passed = !route.empty();
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!parent_exact) first_failure = "PARENT";
    else if (!replay_exact) first_failure = "REPLAY";
    else if (!first_event_exact) first_failure = "FIRST_EVENT";
    else if (!fallback_exact) first_failure = "FALLBACK";
    else if (!convergence_exact) first_failure = "CONVERGENCE";
    else if (!rollback_exact) first_failure = "ROLLBACK";

    std::ostringstream semantic;
    semantic << std::setprecision(17)
             << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D7R4_IDENTITY_SHA256 << '|' << parent_stdout_sha256
             << '|' << failed_state_root << '|' << candidate.passed << ':'
             << candidate.failure << ':' << candidate.trials.size() << ':'
             << candidate.accepted_trials << ':' << candidate.rejected_trials
             << ':' << candidate.hvp_calls << ':'
             << candidate.step_norm_updates << ':' << candidate.quarter_updates
             << ':' << candidate.final_stationarity << '|';
    for (const ALStepNormInnerTrial& trial : candidate.trials) {
        semantic << trial.trial << ':' << trial.hvp_calls << ':'
                 << trial.negative_curvature << ':' << trial.accepted << ':'
                 << trial.radius_owner << ':' << trial.stationarity_before
                 << ':' << trial.radius_before << ':' << trial.radius_after
                 << ':' << trial.step_norm << ':'
                 << trial.predicted_reduction << ':'
                 << trial.raw_actual_reduction << ':'
                 << trial.direct_actual_reduction << ':' << trial.raw_ratio
                 << ':' << trial.direct_ratio << ':' << trial.topology_exact
                 << ':' << trial.topology.active_root << ':'
                 << trial.topology.fluid_root << ':'
                 << trial.topology.boundary_root << ';';
    }
    semantic << '|' << fallback_radius << ':' << fallback_used << ':'
             << fallback_invalid << '|' << candidate_state_root << ':'
             << rollback_exact << ':' << route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    std::ostringstream report;
    report << std::setprecision(17)
           << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d7r4_step_norm_trust_inner.v1\""
           << ",\"identity_sha256\":\"" << B4E2D7R4_IDENTITY_SHA256
           << "\",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"parent\":{\"stdout_sha256\":\""
           << parent_stdout_sha256 << "\",\"exact\":"
           << (parent_exact ? "true" : "false") << '}'
           << ",\"replay\":{\"failed_state_root\":\""
           << failed_state_root << "\",\"exact\":"
           << (replay_exact ? "true" : "false") << '}'
           << ",\"candidate\":{\"passed\":"
           << (candidate.passed ? "true" : "false")
           << ",\"failure\":\"" << candidate.failure
           << "\",\"trials\":" << candidate.trials.size()
           << ",\"accepted\":" << candidate.accepted_trials
           << ",\"rejected\":" << candidate.rejected_trials
           << ",\"hvp_calls\":" << candidate.hvp_calls
           << ",\"step_norm_updates\":" << candidate.step_norm_updates
           << ",\"quarter_updates\":" << candidate.quarter_updates
           << ",\"final_stationarity\":"
           << candidate.final_stationarity
           << ",\"private_state_root\":\"" << candidate_state_root
           << "\",\"trials_detail\":[";
    for (std::size_t index = 0U;
         index < candidate.trials.size(); ++index) {
        if (index != 0U) report << ',';
        const ALStepNormInnerTrial& trial = candidate.trials[index];
        report << "{\"trial\":" << trial.trial
               << ",\"stationarity_before\":"
               << trial.stationarity_before
               << ",\"radius_before\":" << trial.radius_before
               << ",\"radius_after\":" << trial.radius_after
               << ",\"radius_owner\":\"" << trial.radius_owner
               << "\",\"step_norm\":" << trial.step_norm
               << ",\"hvp_calls\":" << trial.hvp_calls
               << ",\"negative_curvature\":"
               << (trial.negative_curvature ? "true" : "false")
               << ",\"predicted_reduction\":"
               << trial.predicted_reduction
               << ",\"raw_actual_reduction\":"
               << trial.raw_actual_reduction
               << ",\"direct_actual_reduction\":"
               << trial.direct_actual_reduction
               << ",\"raw_ratio\":" << trial.raw_ratio
               << ",\"direct_ratio\":" << trial.direct_ratio
               << ",\"topology_exact\":"
               << (trial.topology_exact ? "true" : "false")
               << ",\"accepted\":"
               << (trial.accepted ? "true" : "false") << '}';
    }
    report << "]},\"first_event_exact\":"
           << (first_event_exact ? "true" : "false")
           << ",\"fallback_control\":{\"radius\":" << fallback_radius
           << ",\"used_step_norm\":"
           << (fallback_used ? "true" : "false")
           << ",\"invalid_detected\":"
           << (fallback_invalid ? "true" : "false")
           << ",\"exact\":" << (fallback_exact ? "true" : "false")
           << "},\"route\":\"" << route << '"'
           << ",\"rollback_exact\":"
           << (rollback_exact ? "true" : "false")
           << ",\"outer_updates\":0,\"trajectory_steps\":0"
           << ",\"commit_count\":0,\"physics_mutation\":false"
           << ",\"timing_admitted\":false"
           << ",\"outer_integration_contract_research_authorized\":"
           << (passed ? "true" : "false")
           << ",\"outer_integration_authorized\":false"
           << ",\"nominal_trajectory_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport run_al_step_norm_private_outer_controls() {
    const bool identity_exact = sha256_hex(B4E2D7R5_IDENTITY_PROJECTION)
        == B4E2D7R5_IDENTITY_SHA256;
    const SplitBoundaryReport parent =
        run_al_step_norm_trust_inner_controls();
    const std::string parent_stdout_sha256 = sha256_hex(parent.json + "\n");
    const bool parent_exact = parent.passed
        && parent_stdout_sha256
            == "975da3f5adc13bba6c5fec3cfe08f0bc395f8fac58882b841ba5026774d6e886";

    const Fixture fixture = make_box_fixture(
        "corner-box-2x2x2", {2, 2, 2}, 2);
    const std::vector<Vec3> active_prediction =
        compressed_fluid(fixture, 0.99);
    const std::vector<Vec3> inactive_prediction =
        compressed_fluid(fixture, 1.01);
    const std::vector<double> zero_multiplier(fixture.fluid.size());
    const ALStepNormPrivateOuterSolve candidate =
        solve_al_step_norm_private_outer(
            fixture, active_prediction, active_prediction, zero_multiplier);

    std::vector<ALVectorOuterRecord> legacy_records;
    legacy_records.reserve(candidate.records.size());
    for (const ALStepNormOuterRecord& record : candidate.records) {
        legacy_records.push_back(record.state);
    }
    const std::string prefix_outer_root = sha256_hex(
        al_vector_legacy_outer_json(legacy_records, 8U));
    const std::string prefix_state_root = al_vector_state_root(
        "cold", candidate.prefix_position, candidate.prefix_multiplier);
    const bool prefix_exact = candidate.records.size() >= 8U
        && prefix_outer_root
            == "9bffc61a943f50cab449c052bd0a6791c40128e894d98d9a9589b0969dbb82c2"
        && prefix_state_root
            == "04a9c03308662d6102b165d8109b23c1b60a3145314603909b7dbfda8385d95e";

    const auto record_admissible = [&candidate](int index) {
        return index >= 0
            && static_cast<std::size_t>(index) < candidate.records.size()
            && candidate.records[static_cast<std::size_t>(index)].admissible;
    };
    const bool confirmation_pair_exact = candidate.confirmed
        && candidate.provisional_index >= 0
        && candidate.confirmation_index == candidate.provisional_index + 1
        && record_admissible(candidate.provisional_index)
        && record_admissible(candidate.confirmation_index);
    const bool warm_holdout_exact = candidate.warm_holdout_attempted
        && candidate.warm_holdout.finite_values
        && candidate.warm_holdout.admissible
        && candidate.warm_holdout_admissible;
    bool lambda_feasible = true;
    bool records_finite = true;
    for (const ALStepNormOuterRecord& record : candidate.records) {
        lambda_feasible = lambda_feasible
            && record.state.minimum_multiplier >= 0.0;
        records_finite = records_finite && record.finite_values;
    }
    const bool transaction_exact = candidate.all_finite
        && candidate.primal_monotone && lambda_feasible && records_finite;
    const bool last_three_nonincreasing = candidate.records.size() >= 3U
        && candidate.records[candidate.records.size() - 2U].state.primal
            <= candidate.records[candidate.records.size() - 3U].state.primal
        && candidate.records[candidate.records.size() - 1U].state.primal
            <= candidate.records[candidate.records.size() - 2U].state.primal;

    const ALStepNormPrivateOuterSolve inactive =
        solve_al_step_norm_private_outer(
            fixture, inactive_prediction, inactive_prediction,
            zero_multiplier);
    const bool inactive_exact = inactive.confirmed
        && inactive.warm_holdout_admissible
        && inactive.private_confirmation_count == 1
        && exact_vec3_values(inactive.position, inactive_prediction)
        && exact_al_multiplier(inactive.multiplier, zero_multiplier)
        && std::all_of(inactive.support.constraint.begin(),
            inactive.support.constraint.end(),
            [](double value) { return value <= 0.0; });
    const ALStepNormInnerSolve reset = solve_al_vector_inner_step_norm(
        active_prediction, active_prediction,
        fixture.boundary, zero_multiplier);
    double reset_primal = 0.0;
    for (double value : reset.support.constraint) {
        reset_primal = std::max(reset_primal, std::max(0.0, value));
    }
    const bool reset_exact = reset.passed && reset.all_finite
        && reset.positive_accepted_models && reset_primal > 1.0e-8;
    const std::vector<Vec3> public_position = active_prediction;
    const std::vector<double> public_multiplier = zero_multiplier;
    const std::string prior_public_root = al_vector_stable_state_root(
        "public-prior", public_position, public_multiplier);
    const std::string forced_public_root = al_vector_stable_state_root(
        "public-prior", public_position, public_multiplier);
    const std::string forced_private_root = al_vector_stable_state_root(
        "forced-private", candidate.position, candidate.multiplier);
    const bool forced_private_changed = !candidate.records.empty()
        && (!exact_vec3_values(candidate.position, public_position)
            || !exact_al_multiplier(
                candidate.multiplier, public_multiplier));
    const bool rollback_exact = forced_public_root == prior_public_root
        && exact_vec3_values(public_position, active_prediction)
        && exact_al_multiplier(public_multiplier, zero_multiplier)
        && forced_private_changed;
    const bool controls_exact = inactive_exact && reset_exact
        && rollback_exact;

    const bool confirmation_route = transaction_exact
        && candidate.all_inners_pass && confirmation_pair_exact
        && warm_holdout_exact && candidate.private_confirmation_count == 1;
    const bool cap_route = transaction_exact
        && candidate.all_inners_pass && candidate.cap_exhausted
        && !candidate.confirmed && candidate.private_confirmation_count == 0
        && candidate.records.size() == 14U && last_three_nonincreasing;
    const bool inner_route = transaction_exact
        && !candidate.all_inners_pass && candidate.finite_inner_failure
        && candidate.records.size() >= 8U
        && candidate.private_confirmation_count <= 1;
    std::string route;
    if (identity_exact && parent_exact && prefix_exact && controls_exact) {
        if (confirmation_route) {
            route = "PRESSURE_STATE_CONFIRMATION_CANDIDATE";
        } else if (cap_route) {
            route = "OUTER_CAP_OR_NESTED_ACCURACY_RESEARCH";
        } else if (inner_route) {
            route = "INNER_POLICY_INSUFFICIENT";
        }
    }
    const bool passed = !route.empty();
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!parent_exact) first_failure = "PARENT_BYTES";
    else if (!prefix_exact) first_failure = "D7_PREFIX";
    else if (!controls_exact) first_failure = "CONTROLS";
    else if (!candidate.all_finite || !records_finite)
        first_failure = "NONFINITE";
    else if (!candidate.primal_monotone) first_failure = "PRIMAL_MONOTONICITY";
    else if (!lambda_feasible) first_failure = "DUAL_FEASIBILITY";
    else if (route.empty()) first_failure = "UNCLASSIFIED_OUTER_RESULT";

    std::ostringstream semantic;
    semantic << std::setprecision(17)
             << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D7R5_IDENTITY_SHA256 << '|' << parent_stdout_sha256
             << '|' << prefix_outer_root << ':' << prefix_state_root << '|'
             << candidate.all_inners_pass << ':' << candidate.all_finite << ':'
             << candidate.primal_monotone << ':' << candidate.cap_exhausted
             << ':' << candidate.confirmed << ':'
             << candidate.private_confirmation_count << ':'
             << candidate.provisional_index << ':'
             << candidate.confirmation_index << ':'
             << candidate.failure << '|';
    for (const ALStepNormOuterRecord& value : candidate.records) {
        const ALVectorOuterRecord& record = value.state;
        semantic << record.outer << ':' << record.inner_outer_trials << ':'
                 << record.inner_accepted_trials << ':'
                 << record.inner_rejected_trials << ':'
                 << record.inner_hvp_calls << ':'
                 << value.inner_step_norm_updates << ':'
                 << value.inner_quarter_updates << ':' << record.primal << ':'
                 << record.scaled_dual_change << ':'
                 << record.absolute_dual_change << ':'
                 << record.equivalent_pressure_change << ':'
                 << record.position_update_dx << ':' << record.stationarity
                 << ':' << record.complementarity << ':'
                 << record.minimum_multiplier << ':'
                 << record.maximum_multiplier << ':' << value.admissible
                 << ';';
    }
    semantic << '|' << candidate.warm_holdout_attempted << ':'
             << candidate.warm_holdout_admissible << ':'
             << inactive_exact << ':' << reset_exact << ':' << reset_primal
             << ':' << rollback_exact << ':' << forced_private_root << '|'
             << route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    const auto append_record = [](std::ostringstream& output,
                                  const ALStepNormOuterRecord& value) {
        const ALVectorOuterRecord& record = value.state;
        output << std::setprecision(17)
               << "{\"outer\":" << record.outer
               << ",\"inner_outer_trials\":"
               << record.inner_outer_trials
               << ",\"inner_accepted_trials\":"
               << record.inner_accepted_trials
               << ",\"inner_rejected_trials\":"
               << record.inner_rejected_trials
               << ",\"inner_hvp_calls\":" << record.inner_hvp_calls
               << ",\"inner_step_norm_updates\":"
               << value.inner_step_norm_updates
               << ",\"inner_quarter_updates\":"
               << value.inner_quarter_updates
               << ",\"primal\":" << record.primal
               << ",\"scaled_dual_change\":"
               << record.scaled_dual_change
               << ",\"absolute_dual_change_j\":"
               << record.absolute_dual_change
               << ",\"equivalent_pressure_change_pa\":"
               << record.equivalent_pressure_change
               << ",\"position_update_dx\":"
               << record.position_update_dx
               << ",\"stationarity\":" << record.stationarity
               << ",\"complementarity\":" << record.complementarity
               << ",\"multiplier_range\":["
               << record.minimum_multiplier << ','
               << record.maximum_multiplier << ']'
               << ",\"finite\":"
               << (value.finite_values ? "true" : "false")
               << ",\"admissible\":"
               << (value.admissible ? "true" : "false") << '}';
    };
    std::ostringstream report;
    report << std::setprecision(17)
           << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d7r5_private_outer_al_integration.v1\""
           << ",\"identity_sha256\":\"" << B4E2D7R5_IDENTITY_SHA256
           << "\",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"parent\":{\"stdout_sha256\":\""
           << parent_stdout_sha256 << "\",\"exact\":"
           << (parent_exact ? "true" : "false") << '}'
           << ",\"d7_prefix\":{\"record_count\":8"
           << ",\"outer_root\":\"" << prefix_outer_root
           << "\",\"state_root\":\"" << prefix_state_root
           << "\",\"exact\":" << (prefix_exact ? "true" : "false")
           << "},\"candidate\":{\"failure\":\"" << candidate.failure
           << "\",\"all_inners_pass\":"
           << (candidate.all_inners_pass ? "true" : "false")
           << ",\"all_finite\":"
           << (candidate.all_finite ? "true" : "false")
           << ",\"primal_monotone\":"
           << (candidate.primal_monotone ? "true" : "false")
           << ",\"cap_exhausted\":"
           << (candidate.cap_exhausted ? "true" : "false")
           << ",\"provisional_index\":" << candidate.provisional_index
           << ",\"confirmation_index\":" << candidate.confirmation_index
           << ",\"private_confirmation_count\":"
           << candidate.private_confirmation_count
           << ",\"outer\":[";
    for (std::size_t index = 0U; index < candidate.records.size(); ++index) {
        if (index != 0U) report << ',';
        append_record(report, candidate.records[index]);
    }
    report << "]},\"warm_holdout\":{\"attempted\":"
           << (candidate.warm_holdout_attempted ? "true" : "false")
           << ",\"admissible\":"
           << (candidate.warm_holdout_admissible ? "true" : "false")
           << ",\"record\":";
    if (candidate.warm_holdout_attempted
        && candidate.warm_holdout.finite_values) {
        append_record(report, candidate.warm_holdout);
    } else {
        report << "null";
    }
    report << "},\"controls\":{\"inactive_exact\":"
           << (inactive_exact ? "true" : "false")
           << ",\"reset_primal\":" << reset_primal
           << ",\"reset_exact\":"
           << (reset_exact ? "true" : "false")
           << ",\"prior_public_root\":\"" << prior_public_root
           << "\",\"forced_public_root\":\"" << forced_public_root
           << "\",\"forced_private_root\":\"" << forced_private_root
           << "\",\"rollback_exact\":"
           << (rollback_exact ? "true" : "false") << '}'
           << ",\"last_three_nonincreasing\":"
           << (last_three_nonincreasing ? "true" : "false")
           << ",\"route\":\"" << route << '"'
           << ",\"outer_updates\":" << candidate.records.size()
           << ",\"warm_holdout_updates\":"
           << (candidate.warm_holdout_attempted ? 1 : 0)
           << ",\"trajectory_steps\":0,\"public_commit_count\":0"
           << ",\"physics_mutation\":false,\"timing_admitted\":false"
           << ",\"dense_al_holdout_contract_research_authorized\":"
           << (passed ? "true" : "false")
           << ",\"public_pressure_state_authorized\":false"
           << ",\"nominal_trajectory_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport run_al_cap_accuracy_discriminator_controls() {
    constexpr std::array<double, 5> stationarity_limits{
        1.0e-8, 1.0e-9, 1.0e-10, 1.0e-11, 1.0e-12};
    const bool identity_exact = sha256_hex(B4E2D7R6_IDENTITY_PROJECTION)
        == B4E2D7R6_IDENTITY_SHA256;
    const SplitBoundaryReport parent =
        run_al_step_norm_private_outer_controls();
    const std::string parent_stdout_sha256 = sha256_hex(parent.json + "\n");
    const bool parent_exact = parent.passed
        && parent_stdout_sha256
            == "7ea5489fa90346f385ce8db08dba445f2e2389e65fdf556a13a17e837ba916d7";

    const Fixture fixture = make_box_fixture(
        "corner-box-2x2x2", {2, 2, 2}, 2);
    const std::vector<Vec3> active_prediction =
        compressed_fluid(fixture, 0.99);
    const std::vector<Vec3> inactive_prediction =
        compressed_fluid(fixture, 1.01);
    const std::vector<double> zero_multiplier(fixture.fluid.size());
    const ALStepNormPrivateOuterSolve d7r5 =
        solve_al_step_norm_private_outer(
            fixture, active_prediction, active_prediction, zero_multiplier);

    std::vector<ALVectorOuterRecord> legacy_records;
    legacy_records.reserve(d7r5.records.size());
    for (const ALStepNormOuterRecord& record : d7r5.records) {
        legacy_records.push_back(record.state);
    }
    const std::string prefix_outer_root = sha256_hex(
        al_vector_legacy_outer_json(legacy_records, 8U));
    const std::string prefix_state_root = al_vector_state_root(
        "cold", d7r5.prefix_position, d7r5.prefix_multiplier);
    const bool prefix_exact = d7r5.records.size() == 14U
        && prefix_outer_root
            == "9bffc61a943f50cab449c052bd0a6791c40128e894d98d9a9589b0969dbb82c2"
        && prefix_state_root
            == "04a9c03308662d6102b165d8109b23c1b60a3145314603909b7dbfda8385d95e";

    std::array<ALCapAccuracyLane, stationarity_limits.size()> lanes;
    if (d7r5.records.size() >= 8U) {
        for (std::size_t lane_index = 0U;
             lane_index < lanes.size(); ++lane_index) {
            lanes[lane_index] = solve_al_cap_accuracy_lane(
                fixture, active_prediction, d7r5.prefix_position,
                d7r5.prefix_multiplier, d7r5.records[7],
                stationarity_limits[lane_index]);
            double prior_primal = std::numeric_limits<double>::infinity();
            for (std::size_t index = 0U; index < 8U; ++index) {
                const ALStepNormOuterRecord& record = d7r5.records[index];
                const bool monotone = record.state.primal <= prior_primal;
                const bool admissible = monotone && record.finite_values
                    && al_step_norm_outer_record_admissible(
                        record.state, stationarity_limits[lane_index]);
                if (admissible
                    && (lanes[lane_index].first_admissible_index < 0
                        || static_cast<int>(index)
                            < lanes[lane_index].first_admissible_index)) {
                    lanes[lane_index].first_admissible_index =
                        static_cast<int>(index);
                }
                prior_primal = record.state.primal;
            }
        }
    }

    bool d7r5_records_exact = lanes[0].records.size() >= 6U;
    for (std::size_t index = 0U; index < 6U && d7r5_records_exact; ++index) {
        d7r5_records_exact = al_step_norm_outer_record_exact(
            lanes[0].records[index], d7r5.records[index + 8U]);
    }
    const std::string d7r5_final_state_root =
        lanes[0].position_at_outer13.empty()
        ? std::string{}
        : al_vector_stable_state_root(
            "forced-private", lanes[0].position_at_outer13,
            lanes[0].multiplier_at_outer13);
    const bool d7r5_control_exact = d7r5_records_exact
        && exact_vec3_values(
            lanes[0].position_at_outer13, d7r5.position)
        && exact_al_multiplier(
            lanes[0].multiplier_at_outer13, d7r5.multiplier)
        && d7r5_final_state_root
            == "1fdbcb763dedce34937c399986691469eaab55565024277ddc70f4dbf8c86546";

    const ALStepNormPrivateOuterSolve inactive =
        solve_al_step_norm_private_outer(
            fixture, inactive_prediction, inactive_prediction,
            zero_multiplier);
    const bool inactive_exact = inactive.confirmed
        && inactive.warm_holdout_admissible
        && inactive.private_confirmation_count == 1
        && exact_vec3_values(inactive.position, inactive_prediction)
        && exact_al_multiplier(inactive.multiplier, zero_multiplier)
        && std::all_of(inactive.support.constraint.begin(),
            inactive.support.constraint.end(),
            [](double value) { return value <= 0.0; });
    const ALStepNormInnerSolve reset = solve_al_vector_inner_step_norm_eta(
        active_prediction, active_prediction, fixture.boundary,
        zero_multiplier, stationarity_limits[0]);
    double reset_primal = 0.0;
    for (double value : reset.support.constraint) {
        reset_primal = std::max(reset_primal, std::max(0.0, value));
    }
    const bool reset_exact = reset.passed && reset.all_finite
        && reset.positive_accepted_models && reset_primal > 1.0e-8;
    const std::vector<Vec3> public_position = active_prediction;
    const std::vector<double> public_multiplier = zero_multiplier;
    const std::string prior_public_root = al_vector_stable_state_root(
        "public-prior", public_position, public_multiplier);
    const std::string forced_public_root = al_vector_stable_state_root(
        "public-prior", public_position, public_multiplier);
    bool forced_private_changed = false;
    for (const ALCapAccuracyLane& lane : lanes) {
        forced_private_changed = forced_private_changed
            || (!lane.records.empty()
                && (!exact_vec3_values(lane.position, public_position)
                    || !exact_al_multiplier(
                        lane.multiplier, public_multiplier)));
    }
    const bool rollback_exact = forced_public_root == prior_public_root
        && exact_vec3_values(public_position, active_prediction)
        && exact_al_multiplier(public_multiplier, zero_multiplier)
        && forced_private_changed;
    const bool controls_exact = inactive_exact && reset_exact
        && rollback_exact;

    bool lanes_finite = true;
    bool lanes_monotone = true;
    bool lanes_dual_feasible = true;
    bool lanes_inner_exact = true;
    bool lanes_complete = true;
    for (const ALCapAccuracyLane& lane : lanes) {
        lanes_finite = lanes_finite && lane.all_finite;
        lanes_monotone = lanes_monotone && lane.primal_monotone;
        lanes_dual_feasible = lanes_dual_feasible && lane.dual_feasible;
        lanes_inner_exact = lanes_inner_exact && lane.all_inners_pass;
        lanes_complete = lanes_complete
            && (lane.cap_exhausted
                || (lane.confirmed && lane.warm_holdout_attempted
                    && lane.warm_holdout_admissible));
    }

    const auto confirmation_usable = [](const ALCapAccuracyLane& lane) {
        return lane.confirmed && lane.private_confirmation_count == 1
            && lane.confirmation_index >= 0
            && lane.confirmation_index <= 62
            && lane.warm_holdout_attempted
            && lane.warm_holdout_admissible;
    };
    const bool outer_cap_route = confirmation_usable(lanes[0])
        && lanes[0].confirmation_index > 13;
    int nested_lane = -1;
    int coupled_lane = -1;
    for (std::size_t index = 1U; index < lanes.size(); ++index) {
        if (!confirmation_usable(lanes[index])) {
            continue;
        }
        if (lanes[index].confirmation_index <= 13 && nested_lane < 0) {
            nested_lane = static_cast<int>(index);
        } else if (lanes[index].confirmation_index > 13
            && coupled_lane < 0) {
            coupled_lane = static_cast<int>(index);
        }
    }
    bool all_cap_exhausted = true;
    bool any_confirmation = false;
    for (const ALCapAccuracyLane& lane : lanes) {
        all_cap_exhausted = all_cap_exhausted && lane.cap_exhausted;
        any_confirmation = any_confirmation || lane.confirmed;
    }
    const bool formulation_route = all_cap_exhausted && !any_confirmation;

    std::string route;
    int selected_lane = -1;
    if (identity_exact && parent_exact && prefix_exact
        && d7r5_control_exact && controls_exact && lanes_finite
        && lanes_monotone && lanes_dual_feasible && lanes_inner_exact
        && lanes_complete) {
        if (outer_cap_route) {
            route = "OUTER_CAP_SUFFICIENT";
            selected_lane = 0;
        } else if (nested_lane >= 0) {
            route = "NESTED_ACCURACY_SUFFICIENT";
            selected_lane = nested_lane;
        } else if (coupled_lane >= 0) {
            route = "COUPLED_CAP_AND_ACCURACY_REQUIRED";
            selected_lane = coupled_lane;
        } else if (formulation_route) {
            route = "PRESSURE_STATE_FORMULATION_RESEARCH";
        }
    }
    const bool route_precedence_exact =
        (outer_cap_route && route == "OUTER_CAP_SUFFICIENT")
        || (!outer_cap_route && nested_lane >= 0
            && route == "NESTED_ACCURACY_SUFFICIENT")
        || (!outer_cap_route && nested_lane < 0 && coupled_lane >= 0
            && route == "COUPLED_CAP_AND_ACCURACY_REQUIRED")
        || (!outer_cap_route && nested_lane < 0 && coupled_lane < 0
            && formulation_route
            && route == "PRESSURE_STATE_FORMULATION_RESEARCH");
    const bool passed = !route.empty() && route_precedence_exact;
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!parent_exact) first_failure = "PARENT_BYTES";
    else if (!prefix_exact) first_failure = "D7_PREFIX";
    else if (!d7r5_control_exact) first_failure = "D7R5_CONTROL";
    else if (!controls_exact) first_failure = "CONTROLS";
    else if (!lanes_finite) first_failure = "NONFINITE";
    else if (!lanes_inner_exact) first_failure = "INNER_FAILURE";
    else if (!lanes_dual_feasible) first_failure = "DUAL_FEASIBILITY";
    else if (!lanes_monotone) first_failure = "PRIMAL_MONOTONICITY";
    else if (!lanes_complete) first_failure = "INCOMPLETE_LANE";
    else if (!route_precedence_exact) first_failure = "ROUTE_PRECEDENCE";
    else if (route.empty()) first_failure = "UNCLASSIFIED_RESULT";

    std::ostringstream semantic;
    semantic << std::setprecision(17)
             << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D7R6_IDENTITY_SHA256 << '|' << parent_stdout_sha256
             << '|' << prefix_outer_root << ':' << prefix_state_root << '|'
             << d7r5_records_exact << ':' << d7r5_final_state_root << '|';
    for (const ALCapAccuracyLane& lane : lanes) {
        semantic << lane.stationarity_limit << ':'
                 << lane.all_inners_pass << ':' << lane.all_finite << ':'
                 << lane.primal_monotone << ':' << lane.dual_feasible << ':'
                 << lane.cap_exhausted << ':' << lane.confirmed << ':'
                 << lane.first_admissible_index << ':'
                 << lane.confirmation_index << ':'
                 << lane.warm_holdout_attempted << ':'
                 << lane.warm_holdout_admissible << ':' << lane.failure
                 << '[';
        for (const ALStepNormOuterRecord& value : lane.records) {
            const ALVectorOuterRecord& record = value.state;
            semantic << record.outer << ':' << record.inner_outer_trials
                     << ':' << record.inner_accepted_trials << ':'
                     << record.inner_rejected_trials << ':'
                     << record.inner_hvp_calls << ':'
                     << value.inner_step_norm_updates << ':'
                     << value.inner_quarter_updates << ':' << record.primal
                     << ':' << record.scaled_dual_change << ':'
                     << record.absolute_dual_change << ':'
                     << record.equivalent_pressure_change << ':'
                     << record.position_update_dx << ':'
                     << record.stationarity << ':' << record.complementarity
                     << ':' << record.minimum_multiplier << ':'
                     << record.maximum_multiplier << ':' << value.admissible
                     << ';';
        }
        semantic << "]!" << lane.failed_inner_work.state.outer << ':'
                 << lane.failed_inner_work.state.inner_outer_trials << ':'
                 << lane.failed_inner_work.state.inner_accepted_trials << ':'
                 << lane.failed_inner_work.state.inner_rejected_trials << ':'
                 << lane.failed_inner_work.state.inner_hvp_calls << ':'
                 << lane.failed_inner_work.inner_step_norm_updates << ':'
                 << lane.failed_inner_work.inner_quarter_updates << ':'
                 << lane.failed_inner_work.state.stationarity
                 << "{" << lane.warm_holdout.state.outer << ':'
                 << lane.warm_holdout.state.primal << ':'
                 << lane.warm_holdout.state.stationarity << ':'
                 << lane.warm_holdout.admissible << "}|";
    }
    semantic << inactive_exact << ':' << reset_exact << ':' << reset_primal
             << ':' << rollback_exact << '|' << selected_lane << ':'
             << route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    const auto append_record = [](std::ostringstream& output,
                                  const ALStepNormOuterRecord& value) {
        const ALVectorOuterRecord& record = value.state;
        output << std::setprecision(17)
               << "{\"outer\":" << record.outer
               << ",\"inner_outer_trials\":"
               << record.inner_outer_trials
               << ",\"inner_accepted_trials\":"
               << record.inner_accepted_trials
               << ",\"inner_rejected_trials\":"
               << record.inner_rejected_trials
               << ",\"inner_hvp_calls\":" << record.inner_hvp_calls
               << ",\"inner_step_norm_updates\":"
               << value.inner_step_norm_updates
               << ",\"inner_quarter_updates\":"
               << value.inner_quarter_updates
               << ",\"primal\":" << record.primal
               << ",\"scaled_dual_change\":"
               << record.scaled_dual_change
               << ",\"absolute_dual_change_j\":"
               << record.absolute_dual_change
               << ",\"equivalent_pressure_change_pa\":"
               << record.equivalent_pressure_change
               << ",\"position_update_dx\":"
               << record.position_update_dx
               << ",\"stationarity\":" << record.stationarity
               << ",\"complementarity\":" << record.complementarity
               << ",\"multiplier_range\":["
               << record.minimum_multiplier << ','
               << record.maximum_multiplier << ']'
               << ",\"finite\":"
               << (value.finite_values ? "true" : "false")
               << ",\"admissible\":"
               << (value.admissible ? "true" : "false") << '}';
    };
    std::ostringstream report;
    report << std::setprecision(17)
           << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d7r6_cap_accuracy_discriminator.v1\""
           << ",\"identity_sha256\":\"" << B4E2D7R6_IDENTITY_SHA256
           << "\",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"parent\":{\"stdout_sha256\":\""
           << parent_stdout_sha256 << "\",\"exact\":"
           << (parent_exact ? "true" : "false") << '}'
           << ",\"d7_prefix\":{\"record_count\":8,\"outer_root\":\""
           << prefix_outer_root << "\",\"state_root\":\""
           << prefix_state_root << "\",\"exact\":"
           << (prefix_exact ? "true" : "false") << ",\"outer\":[";
    for (std::size_t index = 0U;
         index < std::min<std::size_t>(8U, d7r5.records.size()); ++index) {
        if (index != 0U) report << ',';
        append_record(report, d7r5.records[index]);
    }
    report << "]},\"d7r5_control\":{\"first14_exact\":"
           << (d7r5_control_exact ? "true" : "false")
           << ",\"final_state_root\":\"" << d7r5_final_state_root
           << "\"},\"lanes\":[";
    for (std::size_t lane_index = 0U;
         lane_index < lanes.size(); ++lane_index) {
        if (lane_index != 0U) report << ',';
        const ALCapAccuracyLane& lane = lanes[lane_index];
        report << "{\"eta\":" << lane.stationarity_limit
               << ",\"failure\":\"" << lane.failure
               << "\",\"all_inners_pass\":"
               << (lane.all_inners_pass ? "true" : "false")
               << ",\"all_finite\":"
               << (lane.all_finite ? "true" : "false")
               << ",\"primal_monotone\":"
               << (lane.primal_monotone ? "true" : "false")
               << ",\"dual_feasible\":"
               << (lane.dual_feasible ? "true" : "false")
               << ",\"cap_exhausted\":"
               << (lane.cap_exhausted ? "true" : "false")
               << ",\"first_admissible_index\":"
               << lane.first_admissible_index
               << ",\"confirmation_index\":"
               << lane.confirmation_index
               << ",\"private_confirmation_count\":"
               << lane.private_confirmation_count << ",\"outer\":[";
        for (std::size_t index = 0U;
             index < lane.records.size(); ++index) {
            if (index != 0U) report << ',';
            append_record(report, lane.records[index]);
        }
        report << "],\"failed_inner_work\":";
        if (!lane.all_inners_pass) {
            append_record(report, lane.failed_inner_work);
        } else {
            report << "null";
        }
        report << ",\"warm_holdout\":{\"attempted\":"
               << (lane.warm_holdout_attempted ? "true" : "false")
               << ",\"admissible\":"
               << (lane.warm_holdout_admissible ? "true" : "false")
               << ",\"record\":";
        if (lane.warm_holdout_attempted
            && lane.warm_holdout.finite_values) {
            append_record(report, lane.warm_holdout);
        } else {
            report << "null";
        }
        report << "}}";
    }
    report << "],\"controls\":{\"inactive_exact\":"
           << (inactive_exact ? "true" : "false")
           << ",\"reset_primal\":" << reset_primal
           << ",\"reset_exact\":"
           << (reset_exact ? "true" : "false")
           << ",\"prior_public_root\":\"" << prior_public_root
           << "\",\"forced_public_root\":\"" << forced_public_root
           << "\",\"rollback_exact\":"
           << (rollback_exact ? "true" : "false") << '}'
           << ",\"route_precedence_exact\":"
           << (route_precedence_exact ? "true" : "false")
           << ",\"selected_lane\":" << selected_lane
           << ",\"route\":\"" << route << '"'
           << ",\"trajectory_steps\":0,\"public_commit_count\":0"
           << ",\"physics_mutation\":false,\"timing_admitted\":false"
           << ",\"accuracy_or_cap_contract_research_authorized\":"
           << (passed ? "true" : "false")
           << ",\"cap_change_authorized\":false"
           << ",\"inner_tolerance_change_authorized\":false"
           << ",\"public_pressure_state_authorized\":false"
           << ",\"nominal_trajectory_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport run_al_inner_floor_mechanism_discriminator_controls() {
    constexpr std::array<double, 5> stationarity_limits{
        1.0e-8, 1.0e-9, 1.0e-10, 1.0e-11, 1.0e-12};
    constexpr std::array<std::size_t, 3> unique_lane_indices{0U, 1U, 2U};
    const bool identity_exact = sha256_hex(B4E2D7R7_IDENTITY_PROJECTION)
        == B4E2D7R7_IDENTITY_SHA256;
    const SplitBoundaryReport parent =
        run_al_cap_accuracy_discriminator_controls();
    const std::string parent_stdout_sha256 = sha256_hex(parent.json + "\n");
    const bool parent_exact = !parent.passed
        && parent_stdout_sha256
            == "6979ebf9f0b88fb57cbcbbaed6721951cb7fa05acb8f7d4b8c39962f257b9f6f";

    const Fixture fixture = make_box_fixture(
        "corner-box-2x2x2", {2, 2, 2}, 2);
    const std::vector<Vec3> active_prediction =
        compressed_fluid(fixture, 0.99);
    const std::vector<Vec3> inactive_prediction =
        compressed_fluid(fixture, 1.01);
    const std::vector<double> zero_multiplier(fixture.fluid.size());
    const ALStepNormPrivateOuterSolve d7r5 =
        solve_al_step_norm_private_outer(
            fixture, active_prediction, active_prediction, zero_multiplier);
    std::array<ALCapAccuracyLane, stationarity_limits.size()> lanes;
    if (d7r5.records.size() >= 8U) {
        for (std::size_t index = 0U; index < lanes.size(); ++index) {
            lanes[index] = solve_al_cap_accuracy_lane(
                fixture, active_prediction, d7r5.prefix_position,
                d7r5.prefix_multiplier, d7r5.records[7],
                stationarity_limits[index]);
        }
    }

    const auto failed_work_exact = [](const ALCapAccuracyLane& lane,
            const char* failure, std::size_t completed, int failed_outer,
            int outer_trials, int accepted, int rejected, int hvp,
            int step_norm_updates, int quarter_updates,
            double stationarity) {
        const ALVectorOuterRecord& work = lane.failed_inner_work.state;
        return !lane.all_inners_pass && lane.all_finite
            && lane.failure == failure && lane.records.size() == completed
            && work.outer == failed_outer
            && work.inner_outer_trials == outer_trials
            && work.inner_accepted_trials == accepted
            && work.inner_rejected_trials == rejected
            && work.inner_hvp_calls == hvp
            && lane.failed_inner_work.inner_step_norm_updates
                == step_norm_updates
            && lane.failed_inner_work.inner_quarter_updates == quarter_updates
            && binary64_bits(work.stationarity)
                == binary64_bits(stationarity)
            && lane.failed_inner_trials.size()
                == static_cast<std::size_t>(accepted + rejected);
    };
    const bool eta1e8_replay_exact = failed_work_exact(
        lanes[0], "INNER:REJECT_LIMIT", 50U, 58, 11, 1, 9, 20, 1, 8,
        1.1975523969668175e-8);
    const bool eta1e9_replay_exact = failed_work_exact(
        lanes[1], "INNER:MINIMUM_TRUST_RADIUS", 5U, 13, 9, 1, 7, 16,
        1, 6, 1.1785409868777534e-9);
    const bool eta1e10_replay_exact = failed_work_exact(
        lanes[2], "INNER:MINIMUM_TRUST_RADIUS", 3U, 11, 6, 0, 5, 10,
        1, 4, 1.534119330122981e-10);
    const bool three_state_reproduction_exact = eta1e8_replay_exact
        && eta1e9_replay_exact && eta1e10_replay_exact;

    const auto lane_exact = [](const ALCapAccuracyLane& lhs,
                               const ALCapAccuracyLane& rhs) {
        if (!exact_vec3_values(lhs.position, rhs.position)
            || !exact_al_multiplier(lhs.multiplier, rhs.multiplier)
            || lhs.failure != rhs.failure
            || lhs.records.size() != rhs.records.size()
            || lhs.failed_inner_trials.size()
                != rhs.failed_inner_trials.size()
            || !al_step_norm_outer_record_exact(
                lhs.failed_inner_work, rhs.failed_inner_work)) {
            return false;
        }
        for (std::size_t index = 0U; index < lhs.records.size(); ++index) {
            if (!al_step_norm_outer_record_exact(
                    lhs.records[index], rhs.records[index])) {
                return false;
            }
        }
        for (std::size_t index = 0U;
             index < lhs.failed_inner_trials.size(); ++index) {
            if (!al_step_norm_inner_trial_exact(
                    lhs.failed_inner_trials[index],
                    rhs.failed_inner_trials[index])) {
                return false;
            }
        }
        return true;
    };
    const bool common_tight_state_exact = lane_exact(lanes[2], lanes[3])
        && lane_exact(lanes[2], lanes[4]);

    std::array<std::string, unique_lane_indices.size()> state_roots;
    std::array<ALInnerFloorMechanismSummary,
        unique_lane_indices.size()> mechanisms;
    bool trace_finite = true;
    bool raw_admission_unchanged = true;
    for (std::size_t unique = 0U;
         unique < unique_lane_indices.size(); ++unique) {
        const ALCapAccuracyLane& lane = lanes[unique_lane_indices[unique]];
        state_roots[unique] = al_vector_stable_state_root(
            unique == 0U ? "d7r7-pre-failure-eta1e-8"
                : (unique == 1U ? "d7r7-pre-failure-eta1e-9"
                    : "d7r7-pre-failure-eta1e-10"),
            lane.position, lane.multiplier);
        mechanisms[unique] = al_inner_floor_mechanism_summary(
            lane.failed_inner_trials);
        trace_finite = trace_finite && mechanisms[unique].all_finite
            && !lane.failed_inner_trials.empty();
        for (const ALStepNormInnerTrial& trial : lane.failed_inner_trials) {
            const bool unchanged_decision = trial.finite_values
                && trial.predicted_reduction > 0.0
                && trial.raw_actual_reduction > 0.0
                && trial.raw_ratio >= 0.1;
            raw_admission_unchanged = raw_admission_unchanged
                && trial.accepted == unchanged_decision;
        }
    }
    const bool state_roots_distinct = state_roots[0] != state_roots[1]
        && state_roots[0] != state_roots[2]
        && state_roots[1] != state_roots[2];

    bool all_phr = true;
    bool all_merit = true;
    bool any_phr = false;
    bool any_merit = false;
    for (const ALInnerFloorMechanismSummary& mechanism : mechanisms) {
        const bool phr = mechanism.any_active_change
            && mechanism.all_pair_topology_stable;
        const bool merit = mechanism.all_topology_stable
            && mechanism.merit_floor_trials > 0;
        all_phr = all_phr && phr;
        all_merit = all_merit && merit;
        any_phr = any_phr || phr;
        any_merit = any_merit || merit;
    }

    const ALStepNormPrivateOuterSolve inactive =
        solve_al_step_norm_private_outer(
            fixture, inactive_prediction, inactive_prediction,
            zero_multiplier);
    const bool inactive_exact = inactive.confirmed
        && inactive.warm_holdout_admissible
        && inactive.private_confirmation_count == 1
        && exact_vec3_values(inactive.position, inactive_prediction)
        && exact_al_multiplier(inactive.multiplier, zero_multiplier);
    const ALStepNormInnerSolve reset = solve_al_vector_inner_step_norm_eta(
        active_prediction, active_prediction, fixture.boundary,
        zero_multiplier, 1.0e-8);
    double reset_primal = 0.0;
    for (double value : reset.support.constraint) {
        reset_primal = std::max(reset_primal, std::max(0.0, value));
    }
    const bool reset_exact = reset.passed && reset.all_finite
        && reset_primal > 1.0e-8;
    const std::vector<Vec3> public_position = active_prediction;
    const std::vector<double> public_multiplier = zero_multiplier;
    const std::string prior_public_root = al_vector_stable_state_root(
        "public-prior", public_position, public_multiplier);
    const std::string forced_public_root = al_vector_stable_state_root(
        "public-prior", public_position, public_multiplier);
    const bool rollback_exact = prior_public_root == forced_public_root
        && exact_vec3_values(public_position, active_prediction)
        && exact_al_multiplier(public_multiplier, zero_multiplier)
        && state_roots_distinct;
    const bool controls_exact = inactive_exact && reset_exact
        && rollback_exact;

    std::string route;
    if (identity_exact && parent_exact && three_state_reproduction_exact
        && common_tight_state_exact && trace_finite
        && raw_admission_unchanged && controls_exact) {
        if (all_phr && !all_merit) {
            route = "COMMON_PHR_KINK_RESEARCH";
        } else if (!all_phr && all_merit) {
            route = "COMMON_BINARY64_MERIT_FLOOR_RESEARCH";
        } else if (any_phr && any_merit) {
            route = "MIXED_ACTIVE_AND_MERIT_RESEARCH";
        } else {
            route = "TRUST_MODEL_OR_DERIVATIVE_RECLOSURE";
        }
    }
    const bool route_precedence_exact =
        (all_phr && !all_merit && route == "COMMON_PHR_KINK_RESEARCH")
        || (!all_phr && all_merit
            && route == "COMMON_BINARY64_MERIT_FLOOR_RESEARCH")
        || (!all_phr && !all_merit && any_phr && any_merit
            && route == "MIXED_ACTIVE_AND_MERIT_RESEARCH")
        || (!all_phr && !all_merit && !(any_phr && any_merit)
            && route == "TRUST_MODEL_OR_DERIVATIVE_RECLOSURE");
    const bool passed = !route.empty() && route_precedence_exact;
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!parent_exact) first_failure = "D7R6_PARENT_BYTES";
    else if (!three_state_reproduction_exact)
        first_failure = "PRE_FAILURE_STATE_REPRODUCTION";
    else if (!common_tight_state_exact)
        first_failure = "COMMON_TIGHT_STATE";
    else if (!trace_finite) first_failure = "NONFINITE_TRACE";
    else if (!raw_admission_unchanged)
        first_failure = "RAW_ADMISSION_CHANGED";
    else if (!controls_exact) first_failure = "CONTROLS";
    else if (!route_precedence_exact) first_failure = "ROUTE_PRECEDENCE";

    std::ostringstream semantic;
    semantic << std::setprecision(17)
             << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D7R7_IDENTITY_SHA256 << '|' << parent_stdout_sha256
             << '|' << common_tight_state_exact << '|';
    for (std::size_t unique = 0U;
         unique < unique_lane_indices.size(); ++unique) {
        const ALCapAccuracyLane& lane = lanes[unique_lane_indices[unique]];
        const ALInnerFloorMechanismSummary& mechanism = mechanisms[unique];
        semantic << stationarity_limits[unique_lane_indices[unique]] << ':'
                 << state_roots[unique] << ':' << lane.failure << ':'
                 << mechanism.all_topology_stable << ':'
                 << mechanism.all_pair_topology_stable << ':'
                 << mechanism.any_active_change << ':'
                 << mechanism.any_pair_change << ':'
                 << mechanism.merit_floor_trials << ':'
                 << mechanism.any_model_direct_conflict << '[';
        for (const ALStepNormInnerTrial& trial : lane.failed_inner_trials) {
            semantic << trial.trial << ':' << trial.hvp_calls << ':'
                     << trial.negative_curvature << ':' << trial.accepted
                     << ':' << trial.radius_owner << ':'
                     << trial.stationarity_before << ':'
                     << trial.radius_before << ':' << trial.radius_after
                     << ':' << trial.step_norm << ':' << trial.gradient_step
                     << ':' << trial.predicted_reduction << ':'
                     << trial.raw_actual_reduction << ':'
                     << trial.direct_actual_reduction << ':'
                     << trial.raw_ratio << ':' << trial.direct_ratio << ':'
                     << trial.current_total_ulp << ':'
                     << trial.trial_total_ulp << ':' << trial.raw_ulp_ratio
                     << ':' << trial.direct_ulp_ratio << ':'
                     << trial.current_topology.active_root << ':'
                     << trial.topology.active_root << ':'
                     << trial.current_topology.fluid_root << ':'
                     << trial.topology.fluid_root << ':'
                     << trial.current_topology.boundary_root << ':'
                     << trial.topology.boundary_root << ':'
                     << trial.current_phr_margin << ':'
                     << trial.trial_phr_margin << ':'
                     << trial.current_horizon_margin << ':'
                     << trial.trial_horizon_margin << ';';
        }
        semantic << "]|";
    }
    semantic << inactive_exact << ':' << reset_exact << ':' << reset_primal
             << ':' << rollback_exact << '|' << route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    const auto append_trial = [](std::ostringstream& output,
                                 const ALStepNormInnerTrial& trial) {
        const double merit_floor_bound = 8.0 * std::max(
            trial.current_total_ulp, trial.trial_total_ulp);
        const bool merit_floor = trial.topology_exact
            && trial.predicted_reduction > 0.0
            && trial.direct_actual_reduction > 0.0
            && !trial.accepted
            && std::abs(trial.raw_actual_reduction) <= merit_floor_bound
            && std::abs(trial.direct_actual_reduction)
                <= merit_floor_bound;
        output << std::setprecision(17)
               << "{\"trial\":" << trial.trial
               << ",\"hvp_calls\":" << trial.hvp_calls
               << ",\"negative_curvature\":"
               << (trial.negative_curvature ? "true" : "false")
               << ",\"stationarity_before\":"
               << trial.stationarity_before
               << ",\"trust_radius_before\":" << trial.radius_before
               << ",\"trust_radius_after\":" << trial.radius_after
               << ",\"step_norm\":" << trial.step_norm
               << ",\"step_norm_dx\":" << trial.step_norm / SPACING
               << ",\"radius_owner\":\"" << trial.radius_owner << '"'
               << ",\"gradient_step\":" << trial.gradient_step
               << ",\"predicted_reduction\":"
               << trial.predicted_reduction
               << ",\"raw_actual_reduction\":"
               << trial.raw_actual_reduction
               << ",\"direct_actual_reduction\":"
               << trial.direct_actual_reduction
               << ",\"raw_ratio\":" << trial.raw_ratio
               << ",\"direct_ratio\":" << trial.direct_ratio
               << ",\"current_total\":" << trial.current_total
               << ",\"trial_total\":" << trial.trial_total
               << ",\"current_total_ulp\":"
               << trial.current_total_ulp
               << ",\"trial_total_ulp\":" << trial.trial_total_ulp
               << ",\"raw_ulp_ratio\":" << trial.raw_ulp_ratio
               << ",\"direct_ulp_ratio\":" << trial.direct_ulp_ratio
               << ",\"merit_floor_bound\":" << merit_floor_bound
               << ",\"merit_floor\":"
               << (merit_floor ? "true" : "false")
               << ",\"topology_exact\":"
               << (trial.topology_exact ? "true" : "false")
               << ",\"topology\":{\"current_active\":\""
               << trial.current_topology.active_root
               << "\",\"trial_active\":\""
               << trial.topology.active_root
               << "\",\"current_fluid\":\""
               << trial.current_topology.fluid_root
               << "\",\"trial_fluid\":\""
               << trial.topology.fluid_root
               << "\",\"current_boundary\":\""
               << trial.current_topology.boundary_root
               << "\",\"trial_boundary\":\""
               << trial.topology.boundary_root << "\"}"
               << ",\"phr_margin\":{\"current\":"
               << trial.current_phr_margin << ",\"trial\":"
               << trial.trial_phr_margin << '}'
               << ",\"horizon_margin\":{\"current\":"
               << trial.current_horizon_margin << ",\"trial\":"
               << trial.trial_horizon_margin << '}'
               << ",\"would_accept\":"
               << (trial.accepted ? "true" : "false") << '}';
    };
    std::ostringstream report;
    report << std::setprecision(17)
           << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d7r7_inner_floor_mechanism_discriminator.v1\""
           << ",\"identity_sha256\":\"" << B4E2D7R7_IDENTITY_SHA256
           << "\",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"parent\":{\"stdout_sha256\":\""
           << parent_stdout_sha256 << "\",\"expected_fail_exact\":"
           << (parent_exact ? "true" : "false") << '}'
           << ",\"common_tight_state_exact\":"
           << (common_tight_state_exact ? "true" : "false")
           << ",\"replays\":[";
    for (std::size_t unique = 0U;
         unique < unique_lane_indices.size(); ++unique) {
        if (unique != 0U) report << ',';
        const std::size_t lane_index = unique_lane_indices[unique];
        const ALCapAccuracyLane& lane = lanes[lane_index];
        const ALInnerFloorMechanismSummary& mechanism = mechanisms[unique];
        report << "{\"eta\":" << stationarity_limits[lane_index]
               << ",\"state_root\":\"" << state_roots[unique]
               << "\",\"failure\":\"" << lane.failure
               << "\",\"failed_outer\":"
               << lane.failed_inner_work.state.outer
               << ",\"reproduction_exact\":"
               << ((unique == 0U ? eta1e8_replay_exact
                    : (unique == 1U ? eta1e9_replay_exact
                        : eta1e10_replay_exact)) ? "true" : "false")
               << ",\"mechanism\":{\"all_topology_stable\":"
               << (mechanism.all_topology_stable ? "true" : "false")
               << ",\"all_pair_topology_stable\":"
               << (mechanism.all_pair_topology_stable ? "true" : "false")
               << ",\"any_active_change\":"
               << (mechanism.any_active_change ? "true" : "false")
               << ",\"any_pair_change\":"
               << (mechanism.any_pair_change ? "true" : "false")
               << ",\"merit_floor_trials\":"
               << mechanism.merit_floor_trials
               << ",\"model_direct_conflict\":"
               << (mechanism.any_model_direct_conflict ? "true" : "false")
               << ",\"minimum_phr_margin\":"
               << mechanism.minimum_phr_margin
               << ",\"minimum_horizon_margin\":"
               << mechanism.minimum_horizon_margin << "},\"trials\":[";
        for (std::size_t index = 0U;
             index < lane.failed_inner_trials.size(); ++index) {
            if (index != 0U) report << ',';
            append_trial(report, lane.failed_inner_trials[index]);
        }
        report << "]}";
    }
    report << "],\"controls\":{\"inactive_exact\":"
           << (inactive_exact ? "true" : "false")
           << ",\"reset_primal\":" << reset_primal
           << ",\"reset_exact\":"
           << (reset_exact ? "true" : "false")
           << ",\"prior_public_root\":\"" << prior_public_root
           << "\",\"forced_public_root\":\"" << forced_public_root
           << "\",\"rollback_exact\":"
           << (rollback_exact ? "true" : "false") << '}'
           << ",\"raw_admission_unchanged\":"
           << (raw_admission_unchanged ? "true" : "false")
           << ",\"route_precedence_exact\":"
           << (route_precedence_exact ? "true" : "false")
           << ",\"route\":\"" << route << '"'
           << ",\"trajectory_steps\":0,\"public_commit_count\":0"
           << ",\"physics_mutation\":false,\"timing_admitted\":false"
           << ",\"failure_mechanism_research_authorized\":"
           << (passed ? "true" : "false")
           << ",\"trial_acceptance_authorized\":false"
           << ",\"cap_or_tolerance_change_authorized\":false"
           << ",\"solver_family_change_authorized\":false"
           << ",\"nominal_trajectory_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport run_al_extended_precision_energy_discriminator_controls() {
    constexpr std::array<double, 5> stationarity_limits{
        1.0e-8, 1.0e-9, 1.0e-10, 1.0e-11, 1.0e-12};
    constexpr std::array<std::size_t, 3> unique_lane_indices{0U, 1U, 2U};
    constexpr std::array<const char*, 3> expected_state_roots{
        "21ad77e22bdba4520ca231bb78d51947a1b67e4263e08dae33af13b0aafabd05",
        "075442656934aeed156642091e9fc1ed41bc739513b5710990cdfb231d8aabc2",
        "299e4ce372a8a3d418ac6f354c70c362fd772acdf278464fb603a3881527901c"};
    const bool identity_exact = sha256_hex(B4E2D7R8_IDENTITY_PROJECTION)
        == B4E2D7R8_IDENTITY_SHA256;
    const SplitBoundaryReport parent =
        run_al_inner_floor_mechanism_discriminator_controls();
    const std::string parent_stdout_sha256 = sha256_hex(parent.json + "\n");
    const bool parent_exact = parent.passed
        && parent_stdout_sha256
            == "3615964074fd477ab384f5710b274d8da4f4d1c77fd3f11ecb08a45eec0039ff";
#if defined(__linux__) && defined(__x86_64__)
    constexpr bool platform_exact = true;
#else
    constexpr bool platform_exact = false;
#endif
    const bool precision_profile_exact = platform_exact && FLT_RADIX == 2
        && sizeof(long double) == 16U && LDBL_MANT_DIG == 64;

    const Fixture fixture = make_box_fixture(
        "corner-box-2x2x2", {2, 2, 2}, 2);
    const std::vector<Vec3> active_prediction =
        compressed_fluid(fixture, 0.99);
    const std::vector<double> zero_multiplier(fixture.fluid.size());
    const ALStepNormPrivateOuterSolve d7r5 =
        solve_al_step_norm_private_outer(
            fixture, active_prediction, active_prediction, zero_multiplier);
    std::array<ALCapAccuracyLane, stationarity_limits.size()> lanes;
    if (d7r5.records.size() >= 8U) {
        for (std::size_t index = 0U; index < lanes.size(); ++index) {
            lanes[index] = solve_al_cap_accuracy_lane(
                fixture, active_prediction, d7r5.prefix_position,
                d7r5.prefix_multiplier, d7r5.records[7],
                stationarity_limits[index]);
        }
    }
    std::array<std::string, unique_lane_indices.size()> state_roots;
    bool state_roots_exact = true;
    for (std::size_t unique = 0U;
         unique < unique_lane_indices.size(); ++unique) {
        const ALCapAccuracyLane& lane = lanes[unique_lane_indices[unique]];
        state_roots[unique] = al_vector_stable_state_root(
            unique == 0U ? "d7r7-pre-failure-eta1e-8"
                : (unique == 1U ? "d7r7-pre-failure-eta1e-9"
                    : "d7r7-pre-failure-eta1e-10"),
            lane.position, lane.multiplier);
        state_roots_exact = state_roots_exact
            && state_roots[unique] == expected_state_roots[unique];
    }
    const auto trial_vectors_exact = [](const ALCapAccuracyLane& lhs,
                                        const ALCapAccuracyLane& rhs) {
        if (!exact_vec3_values(lhs.position, rhs.position)
            || !exact_al_multiplier(lhs.multiplier, rhs.multiplier)
            || lhs.failed_inner_trials.size()
                != rhs.failed_inner_trials.size()) {
            return false;
        }
        for (std::size_t index = 0U;
             index < lhs.failed_inner_trials.size(); ++index) {
            if (!al_step_norm_inner_trial_exact(
                    lhs.failed_inner_trials[index],
                    rhs.failed_inner_trials[index])) {
                return false;
            }
        }
        return true;
    };
    const bool common_tight_state_exact = trial_vectors_exact(
            lanes[2], lanes[3])
        && trial_vectors_exact(lanes[2], lanes[4]);
    const bool formula_input_roundtrip_exact =
        static_cast<double>(static_cast<long double>(PI)) == PI
        && static_cast<double>(static_cast<long double>(REST_DENSITY))
            == REST_DENSITY
        && static_cast<double>(static_cast<long double>(MASS)) == MASS
        && static_cast<double>(static_cast<long double>(KAPPA)) == KAPPA
        && static_cast<double>(static_cast<long double>(HORIZON)) == HORIZON
        && static_cast<double>(static_cast<long double>(TIME_STEP))
            == TIME_STEP
        && static_cast<double>(static_cast<long double>(kernel_scale()))
            == kernel_scale();

    std::array<std::vector<LongDoubleTrialEnergyAudit>,
        unique_lane_indices.size()> audits;
    bool all_extended_finite = true;
    bool work_acceptance_exact = true;
    bool topology_precision_cause = false;
    bool binary64_energy_cause = false;
    bool derivative_cause = false;
    for (std::size_t unique = 0U;
         unique < unique_lane_indices.size(); ++unique) {
        const ALCapAccuracyLane& lane = lanes[unique_lane_indices[unique]];
        audits[unique].reserve(lane.failed_inner_trials.size());
        for (const ALStepNormInnerTrial& trial : lane.failed_inner_trials) {
            const bool unchanged_decision = trial.finite_values
                && trial.predicted_reduction > 0.0
                && trial.raw_actual_reduction > 0.0
                && trial.raw_ratio >= 0.1;
            work_acceptance_exact = work_acceptance_exact
                && trial.accepted == unchanged_decision
                && trial.current_position.size() == active_prediction.size()
                && trial.trial_position.size() == active_prediction.size();
            LongDoubleTrialEnergyAudit audit =
                audit_al_vector_inner_long_double(
                    trial, active_prediction, fixture.boundary,
                    lane.multiplier);
            all_extended_finite = all_extended_finite
                && audit.finite_values;
            const bool causative_parent_trial =
                trial.predicted_reduction > 0.0
                && trial.direct_actual_reduction < 0.0;
            topology_precision_cause = topology_precision_cause
                || (causative_parent_trial
                    && audit.topology_precision_mismatch);
            binary64_energy_cause = binary64_energy_cause
                || (causative_parent_trial
                    && !audit.topology_precision_mismatch
                    && audit.resolved_positive);
            derivative_cause = derivative_cause
                || (causative_parent_trial
                    && !audit.topology_precision_mismatch
                    && audit.resolved_negative);
            audits[unique].push_back(std::move(audit));
        }
    }
    const bool formula_independence_exact = precision_profile_exact
        && formula_input_roundtrip_exact && all_extended_finite
        && std::all_of(audits.begin(), audits.end(),
            [](const std::vector<LongDoubleTrialEnergyAudit>& values) {
                return !values.empty();
            });

    const std::vector<Vec3> public_position = active_prediction;
    const std::vector<double> public_multiplier = zero_multiplier;
    const std::string prior_public_root = al_vector_stable_state_root(
        "public-prior", public_position, public_multiplier);
    const std::string forced_public_root = al_vector_stable_state_root(
        "public-prior", public_position, public_multiplier);
    const bool rollback_exact = prior_public_root == forced_public_root
        && exact_vec3_values(public_position, active_prediction)
        && exact_al_multiplier(public_multiplier, zero_multiplier)
        && state_roots_exact;

    std::string route;
    if (identity_exact && parent_exact && precision_profile_exact
        && state_roots_exact && common_tight_state_exact
        && formula_independence_exact && work_acceptance_exact
        && rollback_exact) {
        if (topology_precision_cause) {
            route = "REPRESENTATION_TOPOLOGY_PRECISION_RESEARCH";
        } else if (binary64_energy_cause) {
            route = "BINARY64_ENERGY_EVALUATION_RESEARCH";
        } else if (derivative_cause) {
            route = "ANALYTIC_GRADIENT_HVP_RECLOSURE";
        } else {
            route = "STRONGER_PRECISION_REQUIRED";
        }
    }
    const bool route_precedence_exact =
        (topology_precision_cause
            && route == "REPRESENTATION_TOPOLOGY_PRECISION_RESEARCH")
        || (!topology_precision_cause && binary64_energy_cause
            && route == "BINARY64_ENERGY_EVALUATION_RESEARCH")
        || (!topology_precision_cause && !binary64_energy_cause
            && derivative_cause
            && route == "ANALYTIC_GRADIENT_HVP_RECLOSURE")
        || (!topology_precision_cause && !binary64_energy_cause
            && !derivative_cause
            && route == "STRONGER_PRECISION_REQUIRED");
    const bool passed = !route.empty() && route_precedence_exact;
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!parent_exact) first_failure = "D7R7_PARENT_BYTES";
    else if (!precision_profile_exact) first_failure = "PRECISION_PROFILE";
    else if (!state_roots_exact) first_failure = "STATE_ROOTS";
    else if (!common_tight_state_exact) first_failure = "COMMON_TIGHT_STATE";
    else if (!formula_input_roundtrip_exact)
        first_failure = "FORMULA_INPUT_PROMOTION";
    else if (!all_extended_finite) first_failure = "NONFINITE_EXTENDED";
    else if (!formula_independence_exact)
        first_failure = "FORMULA_INDEPENDENCE";
    else if (!work_acceptance_exact) first_failure = "WORK_ACCEPTANCE";
    else if (!rollback_exact) first_failure = "ROLLBACK";
    else if (!route_precedence_exact) first_failure = "ROUTE_PRECEDENCE";

    std::ostringstream semantic;
    semantic << std::setprecision(
                    std::numeric_limits<long double>::max_digits10)
             << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D7R8_IDENTITY_SHA256 << '|' << parent_stdout_sha256
             << '|' << precision_profile_exact << ':' << FLT_RADIX << ':'
             << sizeof(long double) << ':' << LDBL_MANT_DIG << '|';
    for (std::size_t unique = 0U;
         unique < unique_lane_indices.size(); ++unique) {
        semantic << stationarity_limits[unique_lane_indices[unique]] << ':'
                 << state_roots[unique] << '[';
        const ALCapAccuracyLane& lane = lanes[unique_lane_indices[unique]];
        for (std::size_t index = 0U; index < audits[unique].size(); ++index) {
            const ALStepNormInnerTrial& trial = lane.failed_inner_trials[index];
            const LongDoubleTrialEnergyAudit& audit = audits[unique][index];
            semantic << trial.trial << ':' << trial.predicted_reduction << ':'
                     << trial.raw_actual_reduction << ':'
                     << trial.direct_actual_reduction << ':'
                     << audit.naive_reduction << ':'
                     << audit.compensated_reduction << ':'
                     << audit.extended_ulp << ':' << audit.naive_ulp_ratio
                     << ':' << audit.compensated_ulp_ratio << ':'
                     << audit.sign_agrees << ':' << audit.resolved << ':'
                     << audit.resolved_positive << ':'
                     << audit.resolved_negative << ':'
                     << audit.topology_precision_mismatch << ':'
                     << audit.current_compensated.fluid_pairs << ':'
                     << audit.current_compensated.boundary_pairs << ':'
                     << audit.trial_compensated.fluid_pairs << ':'
                     << audit.trial_compensated.boundary_pairs << ':'
                     << audit.current_compensated.minimum_half_horizon_margin
                     << ':'
                     << audit.trial_compensated.minimum_half_horizon_margin
                     << ':' << audit.current_compensated.minimum_horizon_margin
                     << ':' << audit.trial_compensated.minimum_horizon_margin
                     << ';';
        }
        semantic << "]|";
    }
    semantic << topology_precision_cause << ':' << binary64_energy_cause
             << ':' << derivative_cause << ':' << rollback_exact << '|'
             << route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    const auto append_evaluation = [](std::ostringstream& output,
            const LongDoubleEnergyEvaluation& value) {
        output << std::setprecision(
                      std::numeric_limits<long double>::max_digits10)
               << "{\"total\":" << value.total
               << ",\"phr\":" << value.phr
               << ",\"inertia\":" << value.inertia
               << ",\"fluid_pairs\":" << value.fluid_pairs
               << ",\"boundary_pairs\":" << value.boundary_pairs
               << ",\"membership_mismatches\":"
               << value.membership_mismatches
               << ",\"minimum_half_horizon_margin\":"
               << value.minimum_half_horizon_margin
               << ",\"minimum_horizon_margin\":"
               << value.minimum_horizon_margin << '}';
    };
    std::ostringstream report;
    report << std::setprecision(
                  std::numeric_limits<long double>::max_digits10)
           << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d7r8_extended_precision_energy_discriminator.v1\""
           << ",\"identity_sha256\":\"" << B4E2D7R8_IDENTITY_SHA256
           << "\",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"parent\":{\"stdout_sha256\":\""
           << parent_stdout_sha256 << "\",\"exact\":"
           << (parent_exact ? "true" : "false") << '}'
           << ",\"profile\":{\"linux_x86_64\":"
           << (platform_exact ? "true" : "false")
           << ",\"flt_radix\":" << FLT_RADIX
           << ",\"sizeof_long_double\":" << sizeof(long double)
           << ",\"ldbl_mant_dig\":" << LDBL_MANT_DIG
           << ",\"exact\":"
           << (precision_profile_exact ? "true" : "false") << '}'
           << ",\"formula_input_roundtrip_exact\":"
           << (formula_input_roundtrip_exact ? "true" : "false")
           << ",\"common_tight_state_exact\":"
           << (common_tight_state_exact ? "true" : "false")
           << ",\"replays\":[";
    for (std::size_t unique = 0U;
         unique < unique_lane_indices.size(); ++unique) {
        if (unique != 0U) report << ',';
        const std::size_t lane_index = unique_lane_indices[unique];
        const ALCapAccuracyLane& lane = lanes[lane_index];
        report << "{\"eta\":" << stationarity_limits[lane_index]
               << ",\"state_root\":\"" << state_roots[unique]
               << "\",\"trials\":[";
        for (std::size_t index = 0U; index < audits[unique].size(); ++index) {
            if (index != 0U) report << ',';
            const ALStepNormInnerTrial& trial = lane.failed_inner_trials[index];
            const LongDoubleTrialEnergyAudit& audit = audits[unique][index];
            report << "{\"trial\":" << trial.trial
                   << ",\"parent\":{\"predicted\":"
                   << trial.predicted_reduction << ",\"raw_actual\":"
                   << trial.raw_actual_reduction
                   << ",\"direct_actual\":"
                   << trial.direct_actual_reduction
                   << ",\"would_accept\":"
                   << (trial.accepted ? "true" : "false") << '}'
                   << ",\"current_naive\":";
            append_evaluation(report, audit.current_naive);
            report << ",\"current_compensated\":";
            append_evaluation(report, audit.current_compensated);
            report << ",\"trial_naive\":";
            append_evaluation(report, audit.trial_naive);
            report << ",\"trial_compensated\":";
            append_evaluation(report, audit.trial_compensated);
            report << ",\"naive_reduction\":" << audit.naive_reduction
                   << ",\"compensated_reduction\":"
                   << audit.compensated_reduction
                   << ",\"extended_ulp\":" << audit.extended_ulp
                   << ",\"naive_ulp_ratio\":" << audit.naive_ulp_ratio
                   << ",\"compensated_ulp_ratio\":"
                   << audit.compensated_ulp_ratio
                   << ",\"sign_agrees\":"
                   << (audit.sign_agrees ? "true" : "false")
                   << ",\"resolved\":"
                   << (audit.resolved ? "true" : "false")
                   << ",\"resolved_positive\":"
                   << (audit.resolved_positive ? "true" : "false")
                   << ",\"resolved_negative\":"
                   << (audit.resolved_negative ? "true" : "false")
                   << ",\"topology_precision_mismatch\":"
                   << (audit.topology_precision_mismatch
                        ? "true" : "false") << '}';
        }
        report << "]}";
    }
    report << "],\"classification\":{\"topology_precision_cause\":"
           << (topology_precision_cause ? "true" : "false")
           << ",\"binary64_energy_cause\":"
           << (binary64_energy_cause ? "true" : "false")
           << ",\"derivative_cause\":"
           << (derivative_cause ? "true" : "false") << '}'
           << ",\"controls\":{\"work_acceptance_exact\":"
           << (work_acceptance_exact ? "true" : "false")
           << ",\"prior_public_root\":\"" << prior_public_root
           << "\",\"forced_public_root\":\"" << forced_public_root
           << "\",\"rollback_exact\":"
           << (rollback_exact ? "true" : "false") << '}'
           << ",\"route_precedence_exact\":"
           << (route_precedence_exact ? "true" : "false")
           << ",\"route\":\"" << route << '"'
           << ",\"trajectory_steps\":0,\"public_commit_count\":0"
           << ",\"trial_acceptance_count\":0"
           << ",\"physics_mutation\":false,\"timing_admitted\":false"
           << ",\"local_numerical_remedy_research_authorized\":"
           << (passed ? "true" : "false")
           << ",\"long_double_production_authorized\":false"
           << ",\"formula_change_authorized\":false"
           << ",\"nominal_trajectory_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport run_al_divided_difference_discriminator_impl(
    bool reclosed_acceptance_ledger) {
    constexpr std::array<double, 5> stationarity_limits{
        1.0e-8, 1.0e-9, 1.0e-10, 1.0e-11, 1.0e-12};
    constexpr std::array<std::size_t, 3> unique_lane_indices{0U, 1U, 2U};
    constexpr std::array<const char*, 3> expected_state_roots{
        "21ad77e22bdba4520ca231bb78d51947a1b67e4263e08dae33af13b0aafabd05",
        "075442656934aeed156642091e9fc1ed41bc739513b5710990cdfb231d8aabc2",
        "299e4ce372a8a3d418ac6f354c70c362fd772acdf278464fb603a3881527901c"};
    const char* identity_projection = reclosed_acceptance_ledger
        ? B4E2D7R9R1_IDENTITY_PROJECTION : B4E2D7R9_IDENTITY_PROJECTION;
    const char* identity_sha256 = reclosed_acceptance_ledger
        ? B4E2D7R9R1_IDENTITY_SHA256 : B4E2D7R9_IDENTITY_SHA256;
    const bool identity_exact = sha256_hex(identity_projection)
        == identity_sha256;
    SplitBoundaryReport failed_contract_parent;
    std::string failed_contract_stdout_sha256;
    bool failed_contract_parent_exact = true;
    if (reclosed_acceptance_ledger) {
        failed_contract_parent =
            run_al_divided_difference_discriminator_impl(false);
        failed_contract_stdout_sha256 = sha256_hex(
            failed_contract_parent.json + "\n");
        failed_contract_parent_exact = !failed_contract_parent.passed
            && failed_contract_stdout_sha256
                == "2c45e93d4153edf714b0f490be3f3d760b14a1ead1e8ed8ae9528d2555ec91f0";
    }
    const SplitBoundaryReport parent =
        run_al_extended_precision_energy_discriminator_controls();
    const std::string parent_stdout_sha256 = sha256_hex(parent.json + "\n");
    const bool parent_exact = parent.passed
        && parent_stdout_sha256
            == "42ce10541b29dd03b589e1e8699436e65cb5a794a45b8644fc040990dd4648b1";
    const bool binary64_profile_exact = sizeof(double) == 8U
        && std::numeric_limits<double>::is_iec559
        && std::numeric_limits<double>::radix == 2
        && std::numeric_limits<double>::digits == 53;

    const Fixture fixture = make_box_fixture(
        "corner-box-2x2x2", {2, 2, 2}, 2);
    const std::vector<Vec3> active_prediction =
        compressed_fluid(fixture, 0.99);
    const std::vector<double> zero_multiplier(fixture.fluid.size());
    const ALStepNormPrivateOuterSolve d7r5 =
        solve_al_step_norm_private_outer(
            fixture, active_prediction, active_prediction, zero_multiplier);
    std::array<ALCapAccuracyLane, stationarity_limits.size()> lanes;
    if (d7r5.records.size() >= 8U) {
        for (std::size_t index = 0U; index < lanes.size(); ++index) {
            lanes[index] = solve_al_cap_accuracy_lane(
                fixture, active_prediction, d7r5.prefix_position,
                d7r5.prefix_multiplier, d7r5.records[7],
                stationarity_limits[index]);
        }
    }
    std::array<std::string, unique_lane_indices.size()> state_roots;
    bool state_roots_exact = true;
    for (std::size_t unique = 0U;
         unique < unique_lane_indices.size(); ++unique) {
        const ALCapAccuracyLane& lane = lanes[unique_lane_indices[unique]];
        state_roots[unique] = al_vector_stable_state_root(
            unique == 0U ? "d7r7-pre-failure-eta1e-8"
                : (unique == 1U ? "d7r7-pre-failure-eta1e-9"
                    : "d7r7-pre-failure-eta1e-10"),
            lane.position, lane.multiplier);
        state_roots_exact = state_roots_exact
            && state_roots[unique] == expected_state_roots[unique];
    }
    const auto lane_exact = [](const ALCapAccuracyLane& lhs,
                               const ALCapAccuracyLane& rhs) {
        if (!exact_vec3_values(lhs.position, rhs.position)
            || !exact_al_multiplier(lhs.multiplier, rhs.multiplier)
            || lhs.failed_inner_trials.size()
                != rhs.failed_inner_trials.size()) {
            return false;
        }
        for (std::size_t index = 0U;
             index < lhs.failed_inner_trials.size(); ++index) {
            if (!al_step_norm_inner_trial_exact(
                    lhs.failed_inner_trials[index],
                    rhs.failed_inner_trials[index])) {
                return false;
            }
        }
        return true;
    };
    const bool common_tight_state_exact = lane_exact(lanes[2], lanes[3])
        && lane_exact(lanes[2], lanes[4]);

    struct TrialAudit {
        LongDoubleTrialEnergyAudit oracle;
        Binary64CompensatedEnergy absolute_current;
        Binary64CompensatedEnergy absolute_trial;
        Binary64DividedDifference divided;
        double absolute_reduction = 0.0;
        long double absolute_relative_error = 0.0L;
        long double divided_relative_error = 0.0L;
        bool scored = false;
        bool absolute_pass = false;
        bool divided_pass = false;
        bool repeat_exact = false;
    };
    std::array<std::vector<TrialAudit>, unique_lane_indices.size()> audits;
    bool all_finite = true;
    bool branch_ledger_exact = true;
    bool work_acceptance_exact = true;
    int accepted_replay_trials = 0;
    bool accepted_eta1e8_trial7 = false;
    bool accepted_eta1e9_trial5 = false;
    bool unexpected_inherited_acceptance = false;
    int resolved_positive = 0;
    int resolved_negative = 0;
    int unresolved = 0;
    int scored = 0;
    bool absolute_all_scored = true;
    bool divided_all_scored = true;
    bool absolute_repaired = false;
    bool divided_repaired = false;
    bool any_divided_mismatch = false;
    bool every_divided_mismatch_crosses_branch = true;
    for (std::size_t unique = 0U;
         unique < unique_lane_indices.size(); ++unique) {
        const ALCapAccuracyLane& lane = lanes[unique_lane_indices[unique]];
        audits[unique].reserve(lane.failed_inner_trials.size());
        for (const ALStepNormInnerTrial& trial : lane.failed_inner_trials) {
            const bool unchanged_decision = trial.finite_values
                && trial.predicted_reduction > 0.0
                && trial.raw_actual_reduction > 0.0
                && trial.raw_ratio >= 0.1;
            work_acceptance_exact = work_acceptance_exact
                && trial.accepted == unchanged_decision
                && trial.current_position.size() == active_prediction.size()
                && trial.trial_position.size() == active_prediction.size();
            if (trial.accepted) {
                ++accepted_replay_trials;
                if (unique == 0U && trial.trial == 7) {
                    accepted_eta1e8_trial7 = true;
                } else if (unique == 1U && trial.trial == 5) {
                    accepted_eta1e9_trial5 = true;
                } else {
                    unexpected_inherited_acceptance = true;
                }
            }

            TrialAudit audit;
            audit.oracle = audit_al_vector_inner_long_double(
                trial, active_prediction, fixture.boundary,
                lane.multiplier);
            audit.absolute_current =
                evaluate_al_vector_inner_compensated_binary64(
                    trial.current_position, active_prediction,
                    fixture.boundary, lane.multiplier);
            audit.absolute_trial =
                evaluate_al_vector_inner_compensated_binary64(
                    trial.trial_position, active_prediction,
                    fixture.boundary, lane.multiplier);
            audit.absolute_reduction = audit.absolute_current.total
                - audit.absolute_trial.total;
            audit.divided = evaluate_al_vector_inner_divided_difference(
                trial.current_position, trial.trial_position,
                active_prediction, fixture.boundary, lane.multiplier);
            const Binary64CompensatedEnergy absolute_current_repeat =
                evaluate_al_vector_inner_compensated_binary64(
                    trial.current_position, active_prediction,
                    fixture.boundary, lane.multiplier);
            const Binary64CompensatedEnergy absolute_trial_repeat =
                evaluate_al_vector_inner_compensated_binary64(
                    trial.trial_position, active_prediction,
                    fixture.boundary, lane.multiplier);
            const Binary64DividedDifference divided_repeat =
                evaluate_al_vector_inner_divided_difference(
                    trial.current_position, trial.trial_position,
                    active_prediction, fixture.boundary, lane.multiplier);
            audit.repeat_exact =
                binary64_bits(audit.absolute_current.total)
                    == binary64_bits(absolute_current_repeat.total)
                && binary64_bits(audit.absolute_current.phr)
                    == binary64_bits(absolute_current_repeat.phr)
                && binary64_bits(audit.absolute_current.inertia)
                    == binary64_bits(absolute_current_repeat.inertia)
                && binary64_bits(audit.absolute_trial.total)
                    == binary64_bits(absolute_trial_repeat.total)
                && binary64_bits(audit.absolute_trial.phr)
                    == binary64_bits(absolute_trial_repeat.phr)
                && binary64_bits(audit.absolute_trial.inertia)
                    == binary64_bits(absolute_trial_repeat.inertia)
                && al_binary64_divided_difference_exact(
                    audit.divided, divided_repeat);
            branch_ledger_exact = branch_ledger_exact && audit.repeat_exact
                && audit.divided.phr_branch_crossings == 0U;
            all_finite = all_finite && audit.oracle.finite_values
                && audit.absolute_current.finite_values
                && audit.absolute_trial.finite_values
                && audit.divided.finite_values
                && std::isfinite(audit.absolute_reduction);

            resolved_positive += audit.oracle.resolved_positive ? 1 : 0;
            resolved_negative += audit.oracle.resolved_negative ? 1 : 0;
            unresolved += audit.oracle.resolved ? 0 : 1;
            audit.scored = audit.oracle.resolved;
            if (audit.scored) {
                ++scored;
                const long double oracle =
                    audit.oracle.compensated_reduction;
                const auto score = [oracle](double candidate,
                                            long double& relative_error) {
                    relative_error = std::abs(
                        static_cast<long double>(candidate) - oracle)
                        / std::abs(oracle);
                    const bool sign_exact =
                        (candidate > 0.0 && oracle > 0.0L)
                        || (candidate < 0.0 && oracle < 0.0L);
                    return sign_exact && relative_error <= 0.5L;
                };
                audit.absolute_pass = score(
                    audit.absolute_reduction,
                    audit.absolute_relative_error);
                audit.divided_pass = score(
                    audit.divided.reduction,
                    audit.divided_relative_error);
                absolute_all_scored = absolute_all_scored
                    && audit.absolute_pass;
                divided_all_scored = divided_all_scored
                    && audit.divided_pass;
                const bool causative = trial.predicted_reduction > 0.0
                    && trial.direct_actual_reduction < 0.0;
                absolute_repaired = absolute_repaired
                    || (causative && audit.absolute_pass);
                divided_repaired = divided_repaired
                    || (causative && audit.divided_pass);
                if (!audit.divided_pass) {
                    any_divided_mismatch = true;
                    every_divided_mismatch_crosses_branch =
                        every_divided_mismatch_crosses_branch
                        && (audit.divided.support_crossings != 0U
                            || audit.divided.kernel_segment_crossings != 0U
                            || audit.divided.phr_branch_crossings != 0U);
                }
            }
            audits[unique].push_back(std::move(audit));
        }
    }
    const bool oracle_ledger_exact = resolved_positive == 11
        && resolved_negative == 0 && unresolved == 12 && scored == 11;
    const bool inherited_acceptance_ledger_exact =
        accepted_replay_trials == 2 && accepted_eta1e8_trial7
        && accepted_eta1e9_trial5 && !unexpected_inherited_acceptance;
    const bool acceptance_control_exact = reclosed_acceptance_ledger
        ? inherited_acceptance_ledger_exact
        : accepted_replay_trials == 0;
    const bool absolute_candidate_pass = oracle_ledger_exact
        && absolute_all_scored && absolute_repaired;
    const bool divided_candidate_pass = oracle_ledger_exact
        && divided_all_scored && divided_repaired;
    const bool branch_reclosure = !absolute_candidate_pass
        && !divided_candidate_pass && any_divided_mismatch
        && every_divided_mismatch_crosses_branch;

    const std::vector<Vec3> public_position = active_prediction;
    const std::vector<double> public_multiplier = zero_multiplier;
    const std::string prior_public_root = al_vector_stable_state_root(
        "public-prior", public_position, public_multiplier);
    const std::string forced_public_root = al_vector_stable_state_root(
        "public-prior", public_position, public_multiplier);
    const bool rollback_exact = prior_public_root == forced_public_root
        && exact_vec3_values(public_position, active_prediction)
        && exact_al_multiplier(public_multiplier, zero_multiplier)
        && state_roots_exact;

    std::string route;
    if (identity_exact && failed_contract_parent_exact
        && parent_exact && binary64_profile_exact
        && state_roots_exact && common_tight_state_exact
        && oracle_ledger_exact && all_finite && branch_ledger_exact
        && work_acceptance_exact && acceptance_control_exact
        && rollback_exact) {
        if (absolute_candidate_pass) {
            route = "COMPENSATED_ABSOLUTE_REDUCTION_CANDIDATE";
        } else if (divided_candidate_pass) {
            route = "DIVIDED_DIFFERENCE_REDUCTION_CANDIDATE";
        } else if (branch_reclosure) {
            route = "BRANCH_RECLOSURE_REQUIRED";
        } else {
            route = "STRONGER_ARITHMETIC_REQUIRED";
        }
    }
    const bool route_precedence_exact =
        (absolute_candidate_pass
            && route == "COMPENSATED_ABSOLUTE_REDUCTION_CANDIDATE")
        || (!absolute_candidate_pass && divided_candidate_pass
            && route == "DIVIDED_DIFFERENCE_REDUCTION_CANDIDATE")
        || (!absolute_candidate_pass && !divided_candidate_pass
            && branch_reclosure && route == "BRANCH_RECLOSURE_REQUIRED")
        || (!absolute_candidate_pass && !divided_candidate_pass
            && !branch_reclosure && route == "STRONGER_ARITHMETIC_REQUIRED");
    const bool passed = !route.empty() && route_precedence_exact;
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!failed_contract_parent_exact)
        first_failure = "D7R9_FAILED_PARENT_BYTES";
    else if (!parent_exact) first_failure = "D7R8_PARENT_BYTES";
    else if (!binary64_profile_exact) first_failure = "BINARY64_PROFILE";
    else if (!state_roots_exact) first_failure = "STATE_ROOTS";
    else if (!common_tight_state_exact)
        first_failure = "COMMON_TIGHT_STATE";
    else if (!oracle_ledger_exact) first_failure = "ORACLE_LEDGER";
    else if (!all_finite) first_failure = "NONFINITE";
    else if (!branch_ledger_exact) first_failure = "BRANCH_LEDGER";
    else if (!work_acceptance_exact) first_failure = "WORK_ACCEPTANCE";
    else if (!acceptance_control_exact) first_failure = "REPLAY_ACCEPTANCE";
    else if (!rollback_exact) first_failure = "ROLLBACK";
    else if (!route_precedence_exact) first_failure = "ROUTE_PRECEDENCE";

    std::ostringstream semantic;
    semantic << std::setprecision(
                    std::numeric_limits<long double>::max_digits10)
             << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << identity_sha256 << '|' << parent_stdout_sha256
             << '|' << binary64_profile_exact << '|';
    if (reclosed_acceptance_ledger) {
        semantic << failed_contract_stdout_sha256 << ':'
                 << inherited_acceptance_ledger_exact << '|';
    }
    for (std::size_t unique = 0U;
         unique < unique_lane_indices.size(); ++unique) {
        semantic << stationarity_limits[unique_lane_indices[unique]] << ':'
                 << state_roots[unique] << '[';
        const ALCapAccuracyLane& lane = lanes[unique_lane_indices[unique]];
        for (std::size_t index = 0U; index < audits[unique].size(); ++index) {
            const ALStepNormInnerTrial& trial = lane.failed_inner_trials[index];
            const TrialAudit& audit = audits[unique][index];
            semantic << trial.trial << ':'
                     << trial.direct_actual_reduction << ':'
                     << audit.oracle.compensated_reduction << ':'
                     << audit.oracle.resolved << ':'
                     << audit.absolute_reduction << ':'
                     << audit.divided.reduction << ':'
                     << audit.divided.phr_reduction << ':'
                     << audit.divided.inertia_reduction << ':'
                     << audit.absolute_relative_error << ':'
                     << audit.divided_relative_error << ':'
                     << audit.absolute_pass << ':' << audit.divided_pass
                     << ':' << audit.divided.support_crossings << ':'
                     << audit.divided.kernel_segment_crossings << ':'
                     << audit.divided.phr_branch_crossings << ':'
                     << audit.repeat_exact << ';';
        }
        semantic << "]|";
    }
    semantic << absolute_candidate_pass << ':' << divided_candidate_pass
             << ':' << branch_reclosure << ':' << rollback_exact << '|'
             << route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    std::ostringstream report;
    const char* schema = reclosed_acceptance_ledger
        ? "nextengine.nonlocal."
          "nsr3b4e2d7r9r1_acceptance_ledger_reclosure.v1"
        : "nextengine.nonlocal."
          "nsr3b4e2d7r9_divided_difference_discriminator.v1";
    report << std::setprecision(
                  std::numeric_limits<long double>::max_digits10)
           << "{\"schema\":\"" << schema << '"'
           << ",\"identity_sha256\":\"" << identity_sha256
           << "\",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"parent\":{\"stdout_sha256\":\""
           << parent_stdout_sha256 << "\",\"exact\":"
           << (parent_exact ? "true" : "false") << '}';
    if (reclosed_acceptance_ledger) {
        report << ",\"failed_contract_parent\":{\"stdout_sha256\":\""
               << failed_contract_stdout_sha256 << "\",\"exact\":"
               << (failed_contract_parent_exact ? "true" : "false")
               << '}';
    }
    report << ",\"binary64_profile_exact\":"
           << (binary64_profile_exact ? "true" : "false")
           << ",\"common_tight_state_exact\":"
           << (common_tight_state_exact ? "true" : "false")
           << ",\"oracle_ledger\":{\"resolved_positive\":"
           << resolved_positive << ",\"resolved_negative\":"
           << resolved_negative << ",\"unresolved\":" << unresolved
           << ",\"scored\":" << scored << ",\"exact\":"
           << (oracle_ledger_exact ? "true" : "false") << '}'
           << ",\"replays\":[";
    for (std::size_t unique = 0U;
         unique < unique_lane_indices.size(); ++unique) {
        if (unique != 0U) report << ',';
        const std::size_t lane_index = unique_lane_indices[unique];
        const ALCapAccuracyLane& lane = lanes[lane_index];
        report << "{\"eta\":" << stationarity_limits[lane_index]
               << ",\"state_root\":\"" << state_roots[unique]
               << "\",\"trials\":[";
        for (std::size_t index = 0U; index < audits[unique].size(); ++index) {
            if (index != 0U) report << ',';
            const ALStepNormInnerTrial& trial = lane.failed_inner_trials[index];
            const TrialAudit& audit = audits[unique][index];
            report << "{\"trial\":" << trial.trial
                   << ",\"parent_direct\":"
                   << trial.direct_actual_reduction
                   << ",\"oracle\":{\"compensated_reduction\":"
                   << audit.oracle.compensated_reduction
                   << ",\"resolved\":"
                   << (audit.oracle.resolved ? "true" : "false") << '}'
                   << ",\"absolute\":{\"current_total\":"
                   << audit.absolute_current.total
                   << ",\"trial_total\":" << audit.absolute_trial.total
                   << ",\"reduction\":" << audit.absolute_reduction
                   << ",\"relative_error\":"
                   << audit.absolute_relative_error << ",\"pass\":"
                   << (audit.absolute_pass ? "true" : "false") << '}'
                   << ",\"divided\":{\"reduction\":"
                   << audit.divided.reduction << ",\"phr_reduction\":"
                   << audit.divided.phr_reduction
                   << ",\"inertia_reduction\":"
                   << audit.divided.inertia_reduction
                   << ",\"relative_error\":"
                   << audit.divided_relative_error
                   << ",\"support_crossings\":"
                   << audit.divided.support_crossings
                   << ",\"kernel_segment_crossings\":"
                   << audit.divided.kernel_segment_crossings
                   << ",\"phr_branch_crossings\":"
                   << audit.divided.phr_branch_crossings
                   << ",\"pass\":"
                   << (audit.divided_pass ? "true" : "false") << '}'
                   << ",\"scored\":"
                   << (audit.scored ? "true" : "false")
                   << ",\"repeat_exact\":"
                   << (audit.repeat_exact ? "true" : "false") << '}';
        }
        report << "]}";
    }
    report << "],\"classification\":{\"absolute_candidate_pass\":"
           << (absolute_candidate_pass ? "true" : "false")
           << ",\"divided_candidate_pass\":"
           << (divided_candidate_pass ? "true" : "false")
           << ",\"branch_reclosure\":"
           << (branch_reclosure ? "true" : "false") << '}'
           << ",\"controls\":{\"branch_ledger_exact\":"
           << (branch_ledger_exact ? "true" : "false")
           << ",\"work_acceptance_exact\":"
           << (work_acceptance_exact ? "true" : "false")
           << ",\"accepted_replay_trials\":" << accepted_replay_trials;
    if (reclosed_acceptance_ledger) {
        report << ",\"inherited_acceptance_ledger_exact\":"
               << (inherited_acceptance_ledger_exact ? "true" : "false")
               << ",\"new_accepted_trials\":0";
    }
    report << ",\"prior_public_root\":\"" << prior_public_root
           << "\",\"forced_public_root\":\"" << forced_public_root
           << "\",\"rollback_exact\":"
           << (rollback_exact ? "true" : "false") << '}'
           << ",\"route_precedence_exact\":"
           << (route_precedence_exact ? "true" : "false")
           << ",\"route\":\"" << route << '"'
           << ",\"trajectory_steps\":0,\"public_commit_count\":0"
           << ",\"trial_acceptance_count\":"
           << (reclosed_acceptance_ledger ? accepted_replay_trials : 0);
    if (reclosed_acceptance_ledger) {
        report << ",\"new_trial_acceptance_count\":0";
    }
    report << ",\"physics_mutation\":false,\"timing_admitted\":false"
           << ",\"binary64_reduction_candidate_authorized\":"
           << (passed ? "true" : "false")
           << ",\"formula_integration_authorized\":false"
           << ",\"nominal_trajectory_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport run_al_divided_difference_discriminator_controls() {
    return run_al_divided_difference_discriminator_impl(false);
}

SplitBoundaryReport run_al_divided_difference_reclosure_controls() {
    return run_al_divided_difference_discriminator_impl(true);
}

SplitBoundaryReport run_al_divided_difference_private_inner_controls() {
    constexpr std::array<double, 5> stationarity_limits{
        1.0e-8, 1.0e-9, 1.0e-10, 1.0e-11, 1.0e-12};
    constexpr std::array<std::size_t, 3> unique_lane_indices{0U, 1U, 2U};
    constexpr std::array<const char*, 3> expected_state_roots{
        "21ad77e22bdba4520ca231bb78d51947a1b67e4263e08dae33af13b0aafabd05",
        "075442656934aeed156642091e9fc1ed41bc739513b5710990cdfb231d8aabc2",
        "299e4ce372a8a3d418ac6f354c70c362fd772acdf278464fb603a3881527901c"};
    const bool identity_exact = sha256_hex(B4E2D7R10_IDENTITY_PROJECTION)
        == B4E2D7R10_IDENTITY_SHA256;
    const SplitBoundaryReport parent =
        run_al_divided_difference_reclosure_controls();
    const std::string parent_stdout_sha256 = sha256_hex(parent.json + "\n");
    const bool parent_exact = parent.passed
        && parent_stdout_sha256
            == "2f9a935e4a8f24bc60b8b146424d73c98b5d8dc47756bcf6a70b367f03f47e64";
    const SplitBoundaryReport failed_parent =
        run_al_divided_difference_discriminator_controls();
    const std::string failed_parent_stdout_sha256 = sha256_hex(
        failed_parent.json + "\n");
    const bool failed_parent_exact = !failed_parent.passed
        && failed_parent_stdout_sha256
            == "2c45e93d4153edf714b0f490be3f3d760b14a1ead1e8ed8ae9528d2555ec91f0";

    const Fixture fixture = make_box_fixture(
        "corner-box-2x2x2", {2, 2, 2}, 2);
    const std::vector<Vec3> active_prediction =
        compressed_fluid(fixture, 0.99);
    const std::vector<double> zero_multiplier(fixture.fluid.size());
    const ALStepNormPrivateOuterSolve d7r5 =
        solve_al_step_norm_private_outer(
            fixture, active_prediction, active_prediction, zero_multiplier);
    std::array<ALCapAccuracyLane, stationarity_limits.size()> lanes;
    if (d7r5.records.size() >= 8U) {
        for (std::size_t index = 0U; index < lanes.size(); ++index) {
            lanes[index] = solve_al_cap_accuracy_lane(
                fixture, active_prediction, d7r5.prefix_position,
                d7r5.prefix_multiplier, d7r5.records[7],
                stationarity_limits[index]);
        }
    }
    std::array<std::string, unique_lane_indices.size()> state_roots;
    bool state_roots_exact = true;
    for (std::size_t unique = 0U;
         unique < unique_lane_indices.size(); ++unique) {
        const ALCapAccuracyLane& lane = lanes[unique_lane_indices[unique]];
        state_roots[unique] = al_vector_stable_state_root(
            unique == 0U ? "d7r7-pre-failure-eta1e-8"
                : (unique == 1U ? "d7r7-pre-failure-eta1e-9"
                    : "d7r7-pre-failure-eta1e-10"),
            lane.position, lane.multiplier);
        state_roots_exact = state_roots_exact
            && state_roots[unique] == expected_state_roots[unique];
    }
    const bool common_tight_state_exact = exact_vec3_values(
            lanes[2].position, lanes[3].position)
        && exact_vec3_values(lanes[2].position, lanes[4].position)
        && exact_al_multiplier(lanes[2].multiplier, lanes[3].multiplier)
        && exact_al_multiplier(lanes[2].multiplier, lanes[4].multiplier)
        && lanes[2].failed_inner_trials.size()
            == lanes[3].failed_inner_trials.size()
        && lanes[2].failed_inner_trials.size()
            == lanes[4].failed_inner_trials.size();

    std::array<ALDividedPrivateInnerSolve, unique_lane_indices.size()> solves;
    std::array<std::string, unique_lane_indices.size()> solve_roots;
    bool repeat_exact = true;
    bool all_finite = true;
    bool policy_exact = true;
    bool candidate_effect = false;
    bool accepted_sign_ledger_exact = true;
    bool all_converged = true;
    int accepted_trials = 0;
    int rejected_trials = 0;
    int hvp_calls = 0;
    int resolved_positive_acceptances = 0;
    int resolved_negative_acceptances = 0;
    int unresolved_acceptances = 0;
    for (std::size_t unique = 0U;
         unique < unique_lane_indices.size(); ++unique) {
        const std::size_t lane_index = unique_lane_indices[unique];
        const ALCapAccuracyLane& lane = lanes[lane_index];
        solves[unique] = solve_al_divided_private_inner(
            active_prediction, lane.position, fixture.boundary,
            lane.multiplier, stationarity_limits[lane_index]);
        const ALDividedPrivateInnerSolve repeat =
            solve_al_divided_private_inner(
                active_prediction, lane.position, fixture.boundary,
                lane.multiplier, stationarity_limits[lane_index]);
        solve_roots[unique] = al_divided_private_inner_root(solves[unique]);
        repeat_exact = repeat_exact
            && solve_roots[unique] == al_divided_private_inner_root(repeat);
        all_finite = all_finite && solves[unique].all_finite;
        policy_exact = policy_exact
            && solves[unique].divided_repeat_exact
            && solves[unique].positive_accepted_models
            && !solves[unique].invalid_interpolation_owned
            && solves[unique].trials.size() <= 64U
            && solves[unique].rejected_trials <= 9;
        candidate_effect = candidate_effect || solves[unique].candidate_effect;
        all_converged = all_converged && solves[unique].passed;
        accepted_trials += solves[unique].accepted_trials;
        rejected_trials += solves[unique].rejected_trials;
        hvp_calls += solves[unique].hvp_calls;
        resolved_positive_acceptances +=
            solves[unique].resolved_positive_acceptances;
        resolved_negative_acceptances +=
            solves[unique].resolved_negative_acceptances;
        unresolved_acceptances += solves[unique].unresolved_acceptances;
        int audited_acceptances = 0;
        for (const ALDividedPrivateInnerTrial& trial : solves[unique].trials) {
            if (trial.candidate_accepted) {
                ++audited_acceptances;
                accepted_sign_ledger_exact = accepted_sign_ledger_exact
                    && trial.oracle_audited
                    && (trial.oracle_resolved_positive
                        || trial.oracle_resolved_negative
                        || !trial.oracle_resolved);
            } else {
                accepted_sign_ledger_exact = accepted_sign_ledger_exact
                    && !trial.oracle_audited;
            }
        }
        accepted_sign_ledger_exact = accepted_sign_ledger_exact
            && audited_acceptances == solves[unique].accepted_trials
            && solves[unique].resolved_positive_acceptances
                + solves[unique].resolved_negative_acceptances
                + solves[unique].unresolved_acceptances
                == solves[unique].accepted_trials;
    }
    const bool model_hvp_radius_policy_exact = policy_exact
        && 0.25 * SPACING > 1.0e-14 && 2.0 * SPACING > 0.25 * SPACING;

    const std::vector<Vec3> public_position = active_prediction;
    const std::vector<double> public_multiplier = zero_multiplier;
    const std::string prior_public_root = al_vector_stable_state_root(
        "public-prior", public_position, public_multiplier);
    const std::string forced_public_root = al_vector_stable_state_root(
        "public-prior", public_position, public_multiplier);
    bool input_states_unchanged = true;
    for (std::size_t unique = 0U;
         unique < unique_lane_indices.size(); ++unique) {
        const ALCapAccuracyLane& lane = lanes[unique_lane_indices[unique]];
        input_states_unchanged = input_states_unchanged
            && al_vector_stable_state_root(
                unique == 0U ? "d7r7-pre-failure-eta1e-8"
                    : (unique == 1U ? "d7r7-pre-failure-eta1e-9"
                        : "d7r7-pre-failure-eta1e-10"),
                lane.position, lane.multiplier) == state_roots[unique];
    }
    const bool rollback_exact = prior_public_root == forced_public_root
        && exact_vec3_values(public_position, active_prediction)
        && exact_al_multiplier(public_multiplier, zero_multiplier)
        && input_states_unchanged;

    std::string route;
    if (identity_exact && parent_exact && failed_parent_exact
        && state_roots_exact && common_tight_state_exact
        && repeat_exact && all_finite && model_hvp_radius_policy_exact
        && candidate_effect && accepted_sign_ledger_exact
        && rollback_exact) {
        if (resolved_negative_acceptances != 0) {
            route = "RESOLVED_SIGN_CONTRADICTION";
        } else if (all_converged && unresolved_acceptances != 0) {
            route = "PRECISION_CERTIFICATE_REQUIRED";
        } else if (all_converged) {
            route = "PRIVATE_INNER_CONVERGENCE_CANDIDATE";
        } else {
            route = "INNER_POLICY_STILL_INSUFFICIENT";
        }
    }
    const bool route_precedence_exact =
        (resolved_negative_acceptances != 0
            && route == "RESOLVED_SIGN_CONTRADICTION")
        || (resolved_negative_acceptances == 0 && all_converged
            && unresolved_acceptances != 0
            && route == "PRECISION_CERTIFICATE_REQUIRED")
        || (resolved_negative_acceptances == 0 && all_converged
            && unresolved_acceptances == 0
            && route == "PRIVATE_INNER_CONVERGENCE_CANDIDATE")
        || (resolved_negative_acceptances == 0 && !all_converged
            && route == "INNER_POLICY_STILL_INSUFFICIENT");
    const bool passed = !route.empty() && route_precedence_exact;
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!parent_exact) first_failure = "D7R9R1_PARENT_BYTES";
    else if (!failed_parent_exact) first_failure = "D7R9_FAIL_BYTES";
    else if (!state_roots_exact) first_failure = "STATE_ROOTS";
    else if (!common_tight_state_exact)
        first_failure = "COMMON_TIGHT_STATE";
    else if (!repeat_exact) first_failure = "PRIVATE_REPEAT";
    else if (!all_finite) first_failure = "NONFINITE";
    else if (!model_hvp_radius_policy_exact)
        first_failure = "MODEL_HVP_RADIUS_POLICY";
    else if (!candidate_effect) first_failure = "CANDIDATE_EFFECT";
    else if (!accepted_sign_ledger_exact)
        first_failure = "ACCEPTED_SIGN_LEDGER";
    else if (!rollback_exact) first_failure = "ROLLBACK";
    else if (!route_precedence_exact) first_failure = "ROUTE_PRECEDENCE";

    std::ostringstream semantic;
    semantic << std::setprecision(
                    std::numeric_limits<long double>::max_digits10)
             << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D7R10_IDENTITY_SHA256 << '|' << parent_stdout_sha256
             << ':' << failed_parent_stdout_sha256 << '|';
    for (std::size_t unique = 0U;
         unique < unique_lane_indices.size(); ++unique) {
        semantic << stationarity_limits[unique_lane_indices[unique]] << ':'
                 << state_roots[unique] << ':' << solve_roots[unique] << '[';
        for (const ALDividedPrivateInnerTrial& trial : solves[unique].trials) {
            semantic << trial.trial << ':' << trial.finite_values << ':'
                     << trial.divided_repeat_exact << ':'
                     << trial.raw_would_accept << ':'
                     << trial.candidate_accepted << ':'
                     << trial.candidate_effect << ':'
                     << trial.negative_curvature << ':'
                     << trial.oracle_audited << ':'
                     << trial.oracle_resolved << ':'
                     << trial.oracle_resolved_positive << ':'
                     << trial.oracle_resolved_negative << ':'
                     << trial.hvp_calls << ':' << trial.radius_owner << ':'
                     << trial.stationarity_before << ':'
                     << trial.radius_before << ':' << trial.radius_after << ':'
                     << trial.step_norm << ':' << trial.predicted_reduction
                     << ':' << trial.raw_reduction << ':'
                     << trial.direct_reduction << ':'
                     << trial.divided_reduction << ':' << trial.divided_ratio
                     << ':' << trial.phr_reduction << ':'
                     << trial.inertia_reduction << ':'
                     << trial.support_crossings << ':'
                     << trial.kernel_segment_crossings << ':'
                     << trial.phr_branch_crossings << ':'
                     << trial.oracle_reduction << ':'
                     << trial.oracle_ulp_ratio << ';';
        }
        semantic << "]|";
    }
    semantic << all_converged << ':' << accepted_trials << ':'
             << rejected_trials << ':' << hvp_calls << ':'
             << resolved_positive_acceptances << ':'
             << resolved_negative_acceptances << ':'
             << unresolved_acceptances << ':' << candidate_effect << ':'
             << rollback_exact << '|' << route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    std::ostringstream report;
    report << std::setprecision(
                  std::numeric_limits<long double>::max_digits10)
           << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d7r10_private_divided_inner.v1\""
           << ",\"identity_sha256\":\"" << B4E2D7R10_IDENTITY_SHA256
           << "\",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"parent\":{\"stdout_sha256\":\""
           << parent_stdout_sha256 << "\",\"exact\":"
           << (parent_exact ? "true" : "false") << '}'
           << ",\"failed_parent\":{\"stdout_sha256\":\""
           << failed_parent_stdout_sha256 << "\",\"exact\":"
           << (failed_parent_exact ? "true" : "false") << '}'
           << ",\"common_tight_state_exact\":"
           << (common_tight_state_exact ? "true" : "false")
           << ",\"lanes\":[";
    for (std::size_t unique = 0U;
         unique < unique_lane_indices.size(); ++unique) {
        if (unique != 0U) report << ',';
        const std::size_t lane_index = unique_lane_indices[unique];
        const ALDividedPrivateInnerSolve& solve = solves[unique];
        report << "{\"eta\":" << stationarity_limits[lane_index]
               << ",\"input_state_root\":\"" << state_roots[unique]
               << "\",\"solve_root\":\"" << solve_roots[unique]
               << "\",\"status\":\"" << (solve.passed ? "PASS" : "FAIL")
               << "\",\"failure\":\"" << solve.failure << '"'
               << ",\"final_stationarity\":" << solve.final_stationarity
               << ",\"accepted\":" << solve.accepted_trials
               << ",\"rejected\":" << solve.rejected_trials
               << ",\"hvp_calls\":" << solve.hvp_calls
               << ",\"resolved_positive_acceptances\":"
               << solve.resolved_positive_acceptances
               << ",\"resolved_negative_acceptances\":"
               << solve.resolved_negative_acceptances
               << ",\"unresolved_acceptances\":"
               << solve.unresolved_acceptances
               << ",\"candidate_effect\":"
               << (solve.candidate_effect ? "true" : "false")
               << ",\"trials\":[";
        for (std::size_t index = 0U; index < solve.trials.size(); ++index) {
            if (index != 0U) report << ',';
            const ALDividedPrivateInnerTrial& trial = solve.trials[index];
            report << "{\"trial\":" << trial.trial
                   << ",\"stationarity_before\":"
                   << trial.stationarity_before
                   << ",\"radius_before\":" << trial.radius_before
                   << ",\"radius_after\":" << trial.radius_after
                   << ",\"radius_owner\":\"" << trial.radius_owner << '"'
                   << ",\"step_norm\":" << trial.step_norm
                   << ",\"predicted\":" << trial.predicted_reduction
                   << ",\"raw\":" << trial.raw_reduction
                   << ",\"direct\":" << trial.direct_reduction
                   << ",\"divided\":" << trial.divided_reduction
                   << ",\"divided_ratio\":" << trial.divided_ratio
                   << ",\"raw_would_accept\":"
                   << (trial.raw_would_accept ? "true" : "false")
                   << ",\"candidate_accepted\":"
                   << (trial.candidate_accepted ? "true" : "false")
                   << ",\"candidate_effect\":"
                   << (trial.candidate_effect ? "true" : "false")
                   << ",\"support_crossings\":"
                   << trial.support_crossings
                   << ",\"kernel_segment_crossings\":"
                   << trial.kernel_segment_crossings
                   << ",\"phr_branch_crossings\":"
                   << trial.phr_branch_crossings
                   << ",\"oracle\":{\"audited\":"
                   << (trial.oracle_audited ? "true" : "false")
                   << ",\"resolved\":"
                   << (trial.oracle_resolved ? "true" : "false")
                   << ",\"resolved_positive\":"
                   << (trial.oracle_resolved_positive ? "true" : "false")
                   << ",\"resolved_negative\":"
                   << (trial.oracle_resolved_negative ? "true" : "false")
                   << ",\"reduction\":" << trial.oracle_reduction
                   << ",\"ulp_ratio\":" << trial.oracle_ulp_ratio << "}}";
        }
        report << "]}";
    }
    report << "],\"summary\":{\"all_converged\":"
           << (all_converged ? "true" : "false")
           << ",\"accepted_trials\":" << accepted_trials
           << ",\"rejected_trials\":" << rejected_trials
           << ",\"hvp_calls\":" << hvp_calls
           << ",\"resolved_positive_acceptances\":"
           << resolved_positive_acceptances
           << ",\"resolved_negative_acceptances\":"
           << resolved_negative_acceptances
           << ",\"unresolved_acceptances\":"
           << unresolved_acceptances
           << ",\"candidate_effect\":"
           << (candidate_effect ? "true" : "false") << '}'
           << ",\"controls\":{\"repeat_exact\":"
           << (repeat_exact ? "true" : "false")
           << ",\"all_finite\":" << (all_finite ? "true" : "false")
           << ",\"model_hvp_radius_policy_exact\":"
           << (model_hvp_radius_policy_exact ? "true" : "false")
           << ",\"accepted_sign_ledger_exact\":"
           << (accepted_sign_ledger_exact ? "true" : "false")
           << ",\"prior_public_root\":\"" << prior_public_root
           << "\",\"forced_public_root\":\"" << forced_public_root
           << "\",\"rollback_exact\":"
           << (rollback_exact ? "true" : "false") << '}'
           << ",\"route_precedence_exact\":"
           << (route_precedence_exact ? "true" : "false")
           << ",\"route\":\"" << route << '"'
           << ",\"outer_update_count\":0,\"trajectory_steps\":0"
           << ",\"public_commit_count\":0,\"physics_mutation\":false"
           << ",\"timing_admitted\":false"
           << ",\"private_inner_integration_authorized\":"
           << (passed ? "true" : "false")
           << ",\"outer_integration_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport run_al_binary128_accepted_sign_oracle_controls() {
    const bool identity_exact = sha256_hex(B4E2D7R11_IDENTITY_PROJECTION)
        == B4E2D7R11_IDENTITY_SHA256;
#if defined(__linux__) && defined(__x86_64__) && defined(__GNUC__) \
    && defined(__SIZEOF_FLOAT128__)
    constexpr bool frozen_platform = true;
#else
    constexpr bool frozen_platform = false;
#endif
    const bool binary128_profile_exact = frozen_platform
        && sizeof(Binary128) == 16U && FLT_RADIX == 2
        && FLT128_MANT_DIG == 113;
    if (!binary128_profile_exact) {
        std::ostringstream report;
        report << "{\"schema\":\"nextengine.nonlocal."
                  "nsr3b4e2d7r11_binary128_accepted_sign_oracle.v1\""
               << ",\"identity_sha256\":\""
               << B4E2D7R11_IDENTITY_SHA256
               << "\",\"status\":\"FAIL\""
               << ",\"first_failure\":\"BINARY128_PROFILE\""
               << ",\"identity_exact\":"
               << (identity_exact ? "true" : "false")
               << ",\"binary128_profile_exact\":false"
               << ",\"route\":\"\",\"trajectory_steps\":0"
               << ",\"outer_update_count\":0"
               << ",\"public_commit_count\":0"
               << ",\"physics_mutation\":false"
               << ",\"timing_admitted\":false"
               << ",\"runtime_binary128_authorized\":false"
               << ",\"outer_integration_authorized\":false"
               << ",\"runtime_authority\":false"
               << ",\"production_authority\":false}";
        return {false, report.str()};
    }

    constexpr std::array<double, 3> stationarity_limits{
        1.0e-8, 1.0e-9, 1.0e-10};
    constexpr std::array<const char*, 3> expected_solve_roots{
        "0fea41f73c2c7260bd0b79d2a03e6b8d2a5a0f658d738e39866a7bdc45866647",
        "aed7362e7135fa622044dec448a0797bacfbd0fcbc4625731c5153a88e4beebb",
        "29d636a21d2c2a71ed6d0114d7d1ea743b2acfbfd3ba6b42746f3118f9d9b5ff"};
    const SplitBoundaryReport parent =
        run_al_divided_difference_private_inner_controls();
    const std::string parent_stdout_sha256 = sha256_hex(parent.json + "\n");
    const bool parent_exact = parent.passed
        && parent_stdout_sha256
            == "ee7b1d4eb0b5eb37334415fa38a1ee2c2a716fa9ab5b628985e7fed06c1c710d";

    const Fixture fixture = make_box_fixture(
        "corner-box-2x2x2", {2, 2, 2}, 2);
    const std::vector<Vec3> active_prediction =
        compressed_fluid(fixture, 0.99);
    const std::vector<double> zero_multiplier(fixture.fluid.size());
    const ALStepNormPrivateOuterSolve d7r5 =
        solve_al_step_norm_private_outer(
            fixture, active_prediction, active_prediction, zero_multiplier);
    std::array<ALCapAccuracyLane, stationarity_limits.size()> lanes;
    if (d7r5.records.size() >= 8U) {
        for (std::size_t index = 0U; index < lanes.size(); ++index) {
            lanes[index] = solve_al_cap_accuracy_lane(
                fixture, active_prediction, d7r5.prefix_position,
                d7r5.prefix_multiplier, d7r5.records[7],
                stationarity_limits[index]);
        }
    }
    std::array<ALDividedPrivateInnerSolve, stationarity_limits.size()> solves;
    std::array<std::string, stationarity_limits.size()> solve_roots;
    std::array<Binary128TrialEnergyAudit, stationarity_limits.size()> audits;
    std::array<std::string, stationarity_limits.size()> audit_roots;
    bool accepted_pair_roots_exact = true;
    bool work_acceptance_exact = true;
    bool formula_inputs_exact = al_binary128_roundtrip_exact(
            active_prediction)
        && al_binary128_roundtrip_exact(fixture.boundary)
        && al_binary128_roundtrip_exact(zero_multiplier)
        && al_binary128_roundtrip_exact(std::vector<double>{
            PI, REST_DENSITY, SPACING, HORIZON, MASS, KAPPA,
            TIME_STEP, kernel_scale()});
    bool audit_repeat_exact = true;
    bool all_finite = true;
    bool pair_membership_exact = true;
    bool candidate_errors_pass = true;
    int resolved_positive = 0;
    int resolved_negative = 0;
    int unresolved = 0;
    for (std::size_t index = 0U; index < solves.size(); ++index) {
        solves[index] = solve_al_divided_private_inner(
            active_prediction, lanes[index].position, fixture.boundary,
            lanes[index].multiplier, stationarity_limits[index]);
        solve_roots[index] = al_divided_private_inner_root(solves[index]);
        accepted_pair_roots_exact = accepted_pair_roots_exact
            && solve_roots[index] == expected_solve_roots[index];
        work_acceptance_exact = work_acceptance_exact
            && solves[index].passed && solves[index].all_finite
            && solves[index].positive_accepted_models
            && solves[index].candidate_effect
            && solves[index].accepted_trials == 1
            && solves[index].rejected_trials == 0
            && solves[index].hvp_calls == 2
            && solves[index].trials.size() == 1U;
        if (solves[index].trials.size() != 1U) {
            all_finite = false;
            pair_membership_exact = false;
            candidate_errors_pass = false;
            continue;
        }
        const ALDividedPrivateInnerTrial& trial = solves[index].trials[0];
        work_acceptance_exact = work_acceptance_exact
            && trial.trial == 0 && trial.candidate_accepted
            && trial.candidate_effect && !trial.raw_would_accept
            && trial.divided_repeat_exact && trial.hvp_calls == 2
            && trial.current_position.size() == active_prediction.size()
            && trial.trial_position.size() == active_prediction.size();
        formula_inputs_exact = formula_inputs_exact
            && al_binary128_roundtrip_exact(lanes[index].multiplier)
            && al_binary128_roundtrip_exact(trial.current_position)
            && al_binary128_roundtrip_exact(trial.trial_position);
        audits[index] = audit_al_vector_inner_binary128(
            trial.current_position, trial.trial_position,
            active_prediction, fixture.boundary, lanes[index].multiplier,
            trial.divided_reduction);
        const Binary128TrialEnergyAudit repeat =
            audit_al_vector_inner_binary128(
                trial.current_position, trial.trial_position,
                active_prediction, fixture.boundary,
                lanes[index].multiplier, trial.divided_reduction);
        audit_roots[index] = al_binary128_audit_root(audits[index]);
        audit_repeat_exact = audit_repeat_exact
            && audit_roots[index] == al_binary128_audit_root(repeat);
        all_finite = all_finite && audits[index].finite_values;
        pair_membership_exact = pair_membership_exact
            && audits[index].membership_exact;
        candidate_errors_pass = candidate_errors_pass
            && audits[index].candidate_pass;
        if (audits[index].resolved_positive) {
            ++resolved_positive;
        } else if (audits[index].resolved_negative) {
            ++resolved_negative;
        } else {
            ++unresolved;
        }
    }
    const bool oracle_formula_independent = true;
    const bool formula_control_exact = formula_inputs_exact
        && oracle_formula_independent;

    const std::vector<Vec3> public_position = active_prediction;
    const std::vector<double> public_multiplier = zero_multiplier;
    const std::string prior_public_root = al_vector_stable_state_root(
        "public-prior", public_position, public_multiplier);
    const std::string forced_public_root = al_vector_stable_state_root(
        "public-prior", public_position, public_multiplier);
    bool lane_inputs_unchanged = true;
    for (std::size_t index = 0U; index < lanes.size(); ++index) {
        lane_inputs_unchanged = lane_inputs_unchanged
            && exact_vec3_values(
                solves[index].trials.empty()
                    ? lanes[index].position
                    : solves[index].trials[0].current_position,
                lanes[index].position);
    }
    const bool rollback_exact = prior_public_root == forced_public_root
        && exact_vec3_values(public_position, active_prediction)
        && exact_al_multiplier(public_multiplier, zero_multiplier)
        && lane_inputs_unchanged;
    const bool hard_controls = identity_exact && parent_exact
        && accepted_pair_roots_exact && work_acceptance_exact
        && formula_control_exact && audit_repeat_exact && all_finite
        && pair_membership_exact && rollback_exact;
    const bool certificate_gate = resolved_positive == 3
        && resolved_negative == 0 && unresolved == 0
        && candidate_errors_pass && pair_membership_exact;

    std::string route;
    if (hard_controls) {
        if (resolved_negative != 0) {
            route = "BINARY128_SIGN_CONTRADICTION";
        } else if (certificate_gate) {
            route = "OFFLINE_ACCEPTED_SIGN_CERTIFICATE";
        } else {
            route = "STRONGER_ORACLE_REQUIRED";
        }
    }
    const bool route_precedence_exact =
        (resolved_negative != 0
            && route == "BINARY128_SIGN_CONTRADICTION")
        || (resolved_negative == 0 && certificate_gate
            && route == "OFFLINE_ACCEPTED_SIGN_CERTIFICATE")
        || (resolved_negative == 0 && !certificate_gate
            && route == "STRONGER_ORACLE_REQUIRED");
    const bool passed = hard_controls && route_precedence_exact;
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!parent_exact) first_failure = "D7R10_PARENT_BYTES";
    else if (!accepted_pair_roots_exact)
        first_failure = "ACCEPTED_PAIR_ROOTS";
    else if (!work_acceptance_exact)
        first_failure = "WORK_ACCEPTANCE";
    else if (!formula_control_exact)
        first_failure = "FORMULA_CONTROL";
    else if (!audit_repeat_exact) first_failure = "ORACLE_REPEAT";
    else if (!all_finite) first_failure = "NONFINITE";
    else if (!pair_membership_exact)
        first_failure = "PAIR_MEMBERSHIP";
    else if (!rollback_exact) first_failure = "ROLLBACK";
    else if (!route_precedence_exact)
        first_failure = "ROUTE_PRECEDENCE";

    std::ostringstream semantic;
    semantic << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D7R11_IDENTITY_SHA256 << '|'
             << parent_stdout_sha256 << '|';
    for (std::size_t index = 0U; index < solves.size(); ++index) {
        semantic << std::setprecision(
                        std::numeric_limits<double>::max_digits10)
                 << stationarity_limits[index] << ':'
                 << solve_roots[index] << ':' << audit_roots[index] << ':'
                 << al_binary128_hex(audits[index].naive_reduction) << ':'
                 << al_binary128_hex(
                        audits[index].compensated_reduction) << ':'
                 << al_binary128_hex(audits[index].ulp) << ':'
                 << al_binary128_hex(
                        audits[index].candidate_relative_error) << ':'
                 << audits[index].resolved_positive << ':'
                 << audits[index].resolved_negative << ':'
                 << audits[index].membership_exact << ';';
    }
    semantic << '|' << binary128_profile_exact << ':'
             << formula_control_exact << ':' << audit_repeat_exact << ':'
             << work_acceptance_exact << ':' << pair_membership_exact << ':'
             << resolved_positive << ':' << resolved_negative << ':'
             << unresolved << ':' << candidate_errors_pass << ':'
             << rollback_exact << '|' << route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    std::ostringstream report;
    report << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d7r11_binary128_accepted_sign_oracle.v1\""
           << ",\"identity_sha256\":\"" << B4E2D7R11_IDENTITY_SHA256
           << "\",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"parent\":{\"stdout_sha256\":\""
           << parent_stdout_sha256 << "\",\"exact\":"
           << (parent_exact ? "true" : "false") << '}'
           << ",\"profile\":{\"platform\":\"linux-x86_64\""
           << ",\"type\":\"gcc-__float128\""
           << ",\"sizeof\":" << sizeof(Binary128)
           << ",\"flt_radix\":" << FLT_RADIX
           << ",\"mantissa_bits\":" << FLT128_MANT_DIG
           << ",\"libquadmath\":true,\"exact\":"
           << (binary128_profile_exact ? "true" : "false") << '}'
           << ",\"accepted_pairs\":[";
    for (std::size_t index = 0U; index < solves.size(); ++index) {
        if (index != 0U) report << ',';
        const ALDividedPrivateInnerTrial* trial =
            solves[index].trials.empty() ? nullptr : &solves[index].trials[0];
        const Binary128TrialEnergyAudit& audit = audits[index];
        report << std::setprecision(
                      std::numeric_limits<double>::max_digits10)
               << "{\"eta\":" << stationarity_limits[index]
               << ",\"trial\":" << (trial == nullptr ? -1 : trial->trial)
               << ",\"solve_root\":\"" << solve_roots[index]
               << "\",\"audit_root\":\"" << audit_roots[index] << '"'
               << ",\"candidate_reduction\":"
               << (trial == nullptr ? 0.0 : trial->divided_reduction)
               << ",\"oracle\":{\"naive_reduction\":\""
               << al_binary128_text(audit.naive_reduction)
               << "\",\"compensated_reduction\":\""
               << al_binary128_text(audit.compensated_reduction)
               << "\",\"total_ulp\":\""
               << al_binary128_text(audit.ulp)
               << "\",\"naive_ulp_ratio\":\""
               << al_binary128_text(audit.naive_ulp_ratio)
               << "\",\"compensated_ulp_ratio\":\""
               << al_binary128_text(audit.compensated_ulp_ratio)
               << "\",\"sign_agrees\":"
               << (audit.sign_agrees ? "true" : "false")
               << ",\"resolved\":"
               << (audit.resolved ? "true" : "false")
               << ",\"resolved_positive\":"
               << (audit.resolved_positive ? "true" : "false")
               << ",\"resolved_negative\":"
               << (audit.resolved_negative ? "true" : "false") << '}'
               << ",\"candidate_relative_error\":\""
               << al_binary128_text(audit.candidate_relative_error)
               << "\",\"candidate_pass\":"
               << (audit.candidate_pass ? "true" : "false")
               << ",\"pair_membership_exact\":"
               << (audit.membership_exact ? "true" : "false")
               << ",\"membership_mismatches\":"
               << audit.current_naive.membership_mismatches
                    + audit.current_compensated.membership_mismatches
                    + audit.trial_naive.membership_mismatches
                    + audit.trial_compensated.membership_mismatches
               << '}';
    }
    report << "],\"summary\":{\"resolved_positive\":"
           << resolved_positive << ",\"resolved_negative\":"
           << resolved_negative << ",\"unresolved\":" << unresolved
           << ",\"candidate_errors_pass\":"
           << (candidate_errors_pass ? "true" : "false")
           << ",\"certificate_gate\":"
           << (certificate_gate ? "true" : "false") << '}'
           << ",\"controls\":{\"accepted_pair_roots_exact\":"
           << (accepted_pair_roots_exact ? "true" : "false")
           << ",\"work_acceptance_exact\":"
           << (work_acceptance_exact ? "true" : "false")
           << ",\"formula_inputs_exact\":"
           << (formula_inputs_exact ? "true" : "false")
           << ",\"oracle_formula_independent\":true"
           << ",\"audit_repeat_exact\":"
           << (audit_repeat_exact ? "true" : "false")
           << ",\"all_finite\":" << (all_finite ? "true" : "false")
           << ",\"pair_membership_exact\":"
           << (pair_membership_exact ? "true" : "false")
           << ",\"prior_public_root\":\"" << prior_public_root
           << "\",\"forced_public_root\":\"" << forced_public_root
           << "\",\"rollback_exact\":"
           << (rollback_exact ? "true" : "false") << '}'
           << ",\"route_precedence_exact\":"
           << (route_precedence_exact ? "true" : "false")
           << ",\"route\":\"" << route << '"'
           << ",\"trajectory_steps\":0,\"outer_update_count\":0"
           << ",\"public_commit_count\":0,\"physics_mutation\":false"
           << ",\"timing_admitted\":false"
           << ",\"runtime_binary128_authorized\":false"
           << ",\"offline_sign_certificate_authorized\":"
           << (passed && route == "OFFLINE_ACCEPTED_SIGN_CERTIFICATE"
                   ? "true" : "false")
           << ",\"outer_integration_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport run_al_divided_private_outer_continuation_controls() {
    constexpr double stationarity_limit = 1.0e-10;
    const bool identity_exact = sha256_hex(B4E2D7R12_IDENTITY_PROJECTION)
        == B4E2D7R12_IDENTITY_SHA256;
#if defined(__linux__) && defined(__x86_64__) && defined(__GNUC__) \
    && defined(__SIZEOF_FLOAT128__)
    constexpr bool frozen_platform = true;
#else
    constexpr bool frozen_platform = false;
#endif
    const bool binary128_profile_exact = frozen_platform
        && sizeof(Binary128) == 16U && FLT_RADIX == 2
        && FLT128_MANT_DIG == 113;
    const SplitBoundaryReport parent =
        run_al_binary128_accepted_sign_oracle_controls();
    const std::string parent_stdout_sha256 = sha256_hex(parent.json + "\n");
    const bool parent_exact = parent.passed
        && parent_stdout_sha256
            == "3178c5cde71e3859fdf763b448c50da4bba98ce73914321ea40b2cf49c7e06b0";
    const SplitBoundaryReport prefix_parent =
        run_al_step_norm_private_outer_controls();
    const std::string prefix_parent_stdout_sha256 = sha256_hex(
        prefix_parent.json + "\n");
    const bool prefix_parent_exact = prefix_parent.passed
        && prefix_parent_stdout_sha256
            == "7ea5489fa90346f385ce8db08dba445f2e2389e65fdf556a13a17e837ba916d7";

    const Fixture fixture = make_box_fixture(
        "corner-box-2x2x2", {2, 2, 2}, 2);
    const std::vector<Vec3> active_prediction =
        compressed_fluid(fixture, 0.99);
    const std::vector<double> zero_multiplier(fixture.fluid.size());
    const ALStepNormPrivateOuterSolve d7r5 =
        solve_al_step_norm_private_outer(
            fixture, active_prediction, active_prediction, zero_multiplier);
    std::vector<ALVectorOuterRecord> legacy_records;
    legacy_records.reserve(d7r5.records.size());
    for (const ALStepNormOuterRecord& record : d7r5.records) {
        legacy_records.push_back(record.state);
    }
    const std::string prefix_outer_root = sha256_hex(
        al_vector_legacy_outer_json(legacy_records, 8U));
    const std::string prefix_state_root = al_vector_state_root(
        "cold", d7r5.prefix_position, d7r5.prefix_multiplier);
    const bool prefix_exact = d7r5.records.size() == 14U
        && prefix_outer_root
            == "9bffc61a943f50cab449c052bd0a6791c40128e894d98d9a9589b0969dbb82c2"
        && prefix_state_root
            == "04a9c03308662d6102b165d8109b23c1b60a3145314603909b7dbfda8385d95e";

    ALDividedOuterContinuation candidate;
    ALDividedOuterContinuation repeat;
    if (d7r5.records.size() >= 8U) {
        candidate = solve_al_divided_outer_continuation(
            fixture, active_prediction, d7r5.prefix_position,
            d7r5.prefix_multiplier, d7r5.records[7]);
        repeat = solve_al_divided_outer_continuation(
            fixture, active_prediction, d7r5.prefix_position,
            d7r5.prefix_multiplier, d7r5.records[7]);
    }
    const std::string candidate_root =
        al_divided_outer_continuation_root(candidate);
    const std::string repeat_root =
        al_divided_outer_continuation_root(repeat);
    const bool repeat_exact = candidate_root == repeat_root;

    int accepted_ledger = 0;
    int rejected_ledger = 0;
    int hvp_ledger = 0;
    int candidate_effect_ledger = 0;
    int audit_ledger = 0;
    int resolved_positive_ledger = 0;
    int resolved_negative_ledger = 0;
    int unresolved_ledger = 0;
    bool work_ledger_exact = true;
    bool pair_membership_exact = true;
    bool formula_inputs_exact = al_binary128_roundtrip_exact(
            active_prediction)
        && al_binary128_roundtrip_exact(fixture.boundary)
        && al_binary128_roundtrip_exact(d7r5.prefix_position)
        && al_binary128_roundtrip_exact(d7r5.prefix_multiplier)
        && al_binary128_roundtrip_exact(std::vector<double>{
            PI, REST_DENSITY, SPACING, HORIZON, MASS, KAPPA,
            TIME_STEP, kernel_scale()});
    const auto observe_update = [&](const ALDividedOuterUpdate& update) {
        int update_accepted = 0;
        int update_rejected = 0;
        int update_hvp = 0;
        int update_effect = 0;
        for (const ALDividedPrivateInnerTrial& trial : update.trials) {
            update_accepted += trial.candidate_accepted ? 1 : 0;
            update_rejected += trial.candidate_accepted ? 0 : 1;
            update_hvp += trial.hvp_calls;
            update_effect += trial.candidate_effect ? 1 : 0;
            formula_inputs_exact = formula_inputs_exact
                && al_binary128_roundtrip_exact(trial.current_position)
                && al_binary128_roundtrip_exact(trial.trial_position);
        }
        work_ledger_exact = work_ledger_exact
            && update.record.state.inner_accepted_trials == update_accepted
            && update.record.state.inner_rejected_trials == update_rejected
            && update.record.state.inner_hvp_calls == update_hvp
            && update.candidate_audits.size()
                == static_cast<std::size_t>(update_effect)
            && update.candidate_audit_roots.size()
                == update.candidate_audits.size()
            && !update.inner_root.empty();
        accepted_ledger += update_accepted;
        rejected_ledger += update_rejected;
        hvp_ledger += update_hvp;
        candidate_effect_ledger += update_effect;
        audit_ledger += static_cast<int>(update.candidate_audits.size());
        formula_inputs_exact = formula_inputs_exact
            && al_binary128_roundtrip_exact(update.position)
            && al_binary128_roundtrip_exact(update.multiplier);
        for (const Binary128TrialEnergyAudit& audit :
             update.candidate_audits) {
            pair_membership_exact = pair_membership_exact
                && audit.membership_exact;
            if (audit.resolved_positive) {
                ++resolved_positive_ledger;
            } else if (audit.resolved_negative) {
                ++resolved_negative_ledger;
            } else {
                ++unresolved_ledger;
            }
        }
    };
    for (const ALDividedOuterUpdate& update : candidate.updates) {
        observe_update(update);
    }
    if (candidate.warm_holdout_attempted) {
        observe_update(candidate.warm_holdout);
    }
    work_ledger_exact = work_ledger_exact
        && accepted_ledger == candidate.accepted_trials
        && rejected_ledger == candidate.rejected_trials
        && hvp_ledger == candidate.hvp_calls
        && candidate_effect_ledger
            == candidate.candidate_effect_acceptances
        && audit_ledger == candidate.candidate_audits
        && resolved_positive_ledger == candidate.resolved_positive
        && resolved_negative_ledger == candidate.resolved_negative
        && unresolved_ledger == candidate.unresolved;
    const bool candidate_effect_exact = candidate_effect_ledger > 0
        && candidate_effect_ledger == audit_ledger;
    const bool oracle_formula_independent = true;
    const bool formula_control_exact = formula_inputs_exact
        && oracle_formula_independent;

    const std::vector<Vec3> public_position = active_prediction;
    const std::vector<double> public_multiplier = zero_multiplier;
    const std::string prior_public_root = al_vector_stable_state_root(
        "public-prior", public_position, public_multiplier);
    const std::string forced_public_root = al_vector_stable_state_root(
        "public-prior", public_position, public_multiplier);
    const bool rollback_exact = prior_public_root == forced_public_root
        && exact_vec3_values(public_position, active_prediction)
        && exact_al_multiplier(public_multiplier, zero_multiplier)
        && (!candidate.updates.empty()
            || candidate.warm_holdout_attempted);
    const bool all_finite = candidate.all_finite
        && !candidate.audit_hard_failure;
    const bool audit_ledger_exact = candidate_effect_exact
        && candidate.resolved_positive + candidate.resolved_negative
                + candidate.unresolved
            == candidate.candidate_audits;
    const bool confirmation_usable = candidate.confirmed
        && candidate.private_confirmation_count == 1
        && candidate.confirmation_index >= 8
        && candidate.confirmation_index <= 62
        && candidate.primal_monotone && candidate.dual_feasible
        && candidate.warm_holdout_attempted
        && candidate.warm_holdout_admissible
        && candidate.all_inners_pass;
    const bool oracle_boundary = candidate.oracle_bound_required
        || candidate.unresolved != 0
        || (candidate.candidate_audits
            != candidate.resolved_positive + candidate.resolved_negative);
    const bool hard_controls = identity_exact && binary128_profile_exact
        && parent_exact && prefix_parent_exact && prefix_exact
        && repeat_exact && work_ledger_exact && formula_control_exact
        && candidate_effect_exact && audit_ledger_exact && all_finite
        && pair_membership_exact && rollback_exact;

    std::string route;
    if (hard_controls) {
        if (candidate.sign_contradiction
            || candidate.resolved_negative != 0) {
            route = "BINARY128_SIGN_CONTRADICTION";
        } else if (oracle_boundary) {
            route = "ORACLE_OR_REDUCTION_BOUND_REQUIRED";
        } else if (confirmation_usable) {
            route = "PRIVATE_PRESSURE_STATE_CONFIRMED";
        } else if (!candidate.all_inners_pass) {
            route = "INNER_POLICY_STILL_INSUFFICIENT";
        } else {
            route = "OUTER_STATE_FORMULATION_REQUIRED";
        }
    }
    const bool route_precedence_exact =
        ((candidate.sign_contradiction
                || candidate.resolved_negative != 0)
            && route == "BINARY128_SIGN_CONTRADICTION")
        || (!candidate.sign_contradiction
            && candidate.resolved_negative == 0 && oracle_boundary
            && route == "ORACLE_OR_REDUCTION_BOUND_REQUIRED")
        || (!candidate.sign_contradiction
            && candidate.resolved_negative == 0 && !oracle_boundary
            && confirmation_usable
            && route == "PRIVATE_PRESSURE_STATE_CONFIRMED")
        || (!candidate.sign_contradiction
            && candidate.resolved_negative == 0 && !oracle_boundary
            && !confirmation_usable && !candidate.all_inners_pass
            && route == "INNER_POLICY_STILL_INSUFFICIENT")
        || (!candidate.sign_contradiction
            && candidate.resolved_negative == 0 && !oracle_boundary
            && !confirmation_usable && candidate.all_inners_pass
            && route == "OUTER_STATE_FORMULATION_REQUIRED");
    const bool passed = hard_controls && route_precedence_exact;
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!binary128_profile_exact)
        first_failure = "BINARY128_PROFILE";
    else if (!parent_exact) first_failure = "D7R11_PARENT_BYTES";
    else if (!prefix_parent_exact)
        first_failure = "D7R5_PARENT_BYTES";
    else if (!prefix_exact) first_failure = "PREFIX_ROOTS";
    else if (!repeat_exact) first_failure = "PRIVATE_REPEAT";
    else if (!work_ledger_exact) first_failure = "WORK_LEDGER";
    else if (!formula_control_exact) first_failure = "FORMULA_CONTROL";
    else if (!candidate_effect_exact)
        first_failure = "CANDIDATE_EFFECT";
    else if (!audit_ledger_exact) first_failure = "AUDIT_LEDGER";
    else if (!all_finite) first_failure = "NONFINITE";
    else if (!pair_membership_exact)
        first_failure = "PAIR_MEMBERSHIP";
    else if (!rollback_exact) first_failure = "ROLLBACK";
    else if (!route_precedence_exact)
        first_failure = "ROUTE_PRECEDENCE";

    std::ostringstream semantic;
    semantic << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D7R12_IDENTITY_SHA256 << '|'
             << parent_stdout_sha256 << ':'
             << prefix_parent_stdout_sha256 << '|'
             << prefix_outer_root << ':' << prefix_state_root << '|'
             << candidate_root << ':' << repeat_root << '|'
             << binary128_profile_exact << ':' << work_ledger_exact << ':'
             << formula_control_exact << ':' << candidate_effect_exact << ':'
             << audit_ledger_exact << ':' << all_finite << ':'
             << pair_membership_exact << ':' << rollback_exact << '|'
             << candidate.accepted_trials << ':'
             << candidate.rejected_trials << ':' << candidate.hvp_calls
             << ':' << candidate.candidate_effect_acceptances << ':'
             << candidate.resolved_positive << ':'
             << candidate.resolved_negative << ':' << candidate.unresolved
             << ':' << candidate.confirmation_index << ':'
             << candidate.warm_holdout_admissible << '|'
             << route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    const auto append_update = [&](std::ostringstream& report,
                                   const ALDividedOuterUpdate& update) {
        const ALVectorOuterRecord& record = update.record.state;
        report << std::setprecision(
                      std::numeric_limits<double>::max_digits10)
               << "{\"outer\":" << record.outer
               << ",\"passed\":" << (update.passed ? "true" : "false")
               << ",\"failure\":\"" << update.failure << '"'
               << ",\"inner_root\":\"" << update.inner_root << '"'
               << ",\"work\":{\"trials\":"
               << update.trials.size() << ",\"accepted\":"
               << record.inner_accepted_trials << ",\"rejected\":"
               << record.inner_rejected_trials << ",\"hvp\":"
               << record.inner_hvp_calls << '}'
               << ",\"state\":{\"primal\":" << record.primal
               << ",\"stationarity\":" << record.stationarity
               << ",\"complementarity\":" << record.complementarity
               << ",\"absolute_dual_change\":"
               << record.absolute_dual_change
               << ",\"equivalent_pressure_change\":"
               << record.equivalent_pressure_change
               << ",\"position_update_dx\":"
               << record.position_update_dx
               << ",\"minimum_multiplier\":"
               << record.minimum_multiplier
               << ",\"admissible\":"
               << (update.record.admissible ? "true" : "false") << '}'
               << ",\"trials\":[";
        std::size_t audit_index = 0U;
        for (std::size_t index = 0U;
             index < update.trials.size(); ++index) {
            if (index != 0U) report << ',';
            const ALDividedPrivateInnerTrial& trial = update.trials[index];
            report << "{\"trial\":" << trial.trial
                   << ",\"accepted\":"
                   << (trial.candidate_accepted ? "true" : "false")
                   << ",\"candidate_effect\":"
                   << (trial.candidate_effect ? "true" : "false")
                   << ",\"predicted\":" << trial.predicted_reduction
                   << ",\"raw\":" << trial.raw_reduction
                   << ",\"divided\":" << trial.divided_reduction
                   << ",\"ratio\":" << trial.divided_ratio
                   << ",\"radius_owner\":\""
                   << trial.radius_owner << '"';
            if (trial.candidate_effect
                && audit_index < update.candidate_audits.size()) {
                const Binary128TrialEnergyAudit& audit =
                    update.candidate_audits[audit_index];
                report << ",\"binary128\":{\"audit_root\":\""
                       << update.candidate_audit_roots[audit_index]
                       << "\",\"reduction\":\""
                       << al_binary128_text(audit.compensated_reduction)
                       << "\",\"ulp_ratio\":\""
                       << al_binary128_text(
                            audit.compensated_ulp_ratio)
                       << "\",\"relative_error\":\""
                       << al_binary128_text(
                            audit.candidate_relative_error)
                       << "\",\"resolved_positive\":"
                       << (audit.resolved_positive ? "true" : "false")
                       << ",\"resolved_negative\":"
                       << (audit.resolved_negative ? "true" : "false")
                       << ",\"pair_membership_exact\":"
                       << (audit.membership_exact ? "true" : "false")
                       << '}';
                ++audit_index;
            }
            report << '}';
        }
        report << "]}";
    };

    std::ostringstream report;
    report << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d7r12_private_divided_outer_continuation.v1\""
           << ",\"identity_sha256\":\"" << B4E2D7R12_IDENTITY_SHA256
           << "\",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"parent\":{\"d7r11_stdout_sha256\":\""
           << parent_stdout_sha256 << "\",\"d7r11_exact\":"
           << (parent_exact ? "true" : "false")
           << ",\"d7r5_stdout_sha256\":\""
           << prefix_parent_stdout_sha256 << "\",\"d7r5_exact\":"
           << (prefix_parent_exact ? "true" : "false") << '}'
           << ",\"prefix\":{\"outer_root\":\"" << prefix_outer_root
           << "\",\"state_root\":\"" << prefix_state_root
           << "\",\"exact\":" << (prefix_exact ? "true" : "false")
           << '}'
           << ",\"candidate_root\":\"" << candidate_root
           << "\",\"repeat_root\":\"" << repeat_root
           << "\",\"repeat_exact\":"
           << (repeat_exact ? "true" : "false")
           << ",\"eta\":" << std::setprecision(
                std::numeric_limits<double>::max_digits10)
           << stationarity_limit << ",\"updates\":[";
    for (std::size_t index = 0U;
         index < candidate.updates.size(); ++index) {
        if (index != 0U) report << ',';
        append_update(report, candidate.updates[index]);
    }
    report << "],\"confirmation\":{\"confirmed\":"
           << (candidate.confirmed ? "true" : "false")
           << ",\"provisional_index\":" << candidate.provisional_index
           << ",\"confirmation_index\":"
           << candidate.confirmation_index
           << ",\"private_confirmation_count\":"
           << candidate.private_confirmation_count
           << ",\"warm_holdout_attempted\":"
           << (candidate.warm_holdout_attempted ? "true" : "false")
           << ",\"warm_holdout_admissible\":"
           << (candidate.warm_holdout_admissible ? "true" : "false");
    if (candidate.warm_holdout_attempted) {
        report << ",\"warm_holdout\":";
        append_update(report, candidate.warm_holdout);
    }
    report << "},\"summary\":{\"failure\":\"" << candidate.failure
           << "\",\"all_inners_pass\":"
           << (candidate.all_inners_pass ? "true" : "false")
           << ",\"all_finite\":"
           << (candidate.all_finite ? "true" : "false")
           << ",\"primal_monotone\":"
           << (candidate.primal_monotone ? "true" : "false")
           << ",\"dual_feasible\":"
           << (candidate.dual_feasible ? "true" : "false")
           << ",\"cap_exhausted\":"
           << (candidate.cap_exhausted ? "true" : "false")
           << ",\"accepted_trials\":" << candidate.accepted_trials
           << ",\"rejected_trials\":" << candidate.rejected_trials
           << ",\"hvp_calls\":" << candidate.hvp_calls
           << ",\"candidate_effect_acceptances\":"
           << candidate.candidate_effect_acceptances
           << ",\"candidate_audits\":" << candidate.candidate_audits
           << ",\"resolved_positive\":"
           << candidate.resolved_positive
           << ",\"resolved_negative\":"
           << candidate.resolved_negative
           << ",\"unresolved\":" << candidate.unresolved << '}'
           << ",\"controls\":{\"binary128_profile_exact\":"
           << (binary128_profile_exact ? "true" : "false")
           << ",\"work_ledger_exact\":"
           << (work_ledger_exact ? "true" : "false")
           << ",\"formula_inputs_exact\":"
           << (formula_inputs_exact ? "true" : "false")
           << ",\"oracle_formula_independent\":true"
           << ",\"candidate_effect_exact\":"
           << (candidate_effect_exact ? "true" : "false")
           << ",\"audit_ledger_exact\":"
           << (audit_ledger_exact ? "true" : "false")
           << ",\"pair_membership_exact\":"
           << (pair_membership_exact ? "true" : "false")
           << ",\"prior_public_root\":\"" << prior_public_root
           << "\",\"forced_public_root\":\"" << forced_public_root
           << "\",\"rollback_exact\":"
           << (rollback_exact ? "true" : "false") << '}'
           << ",\"route_precedence_exact\":"
           << (route_precedence_exact ? "true" : "false")
           << ",\"route\":\"" << route << '"'
           << ",\"trajectory_steps\":0,\"public_commit_count\":0"
           << ",\"physics_mutation\":false,\"timing_admitted\":false"
           << ",\"runtime_binary128_authorized\":false"
           << ",\"private_pressure_state_authorized\":"
           << (passed && route == "PRIVATE_PRESSURE_STATE_CONFIRMED"
                   ? "true" : "false")
           << ",\"nominal_trajectory_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport run_al_divided_full_private_transaction_controls() {
    constexpr double stationarity_limit = 1.0e-10;
    const bool identity_exact = sha256_hex(B4E2D7R13_IDENTITY_PROJECTION)
        == B4E2D7R13_IDENTITY_SHA256;
#if defined(__linux__) && defined(__x86_64__) && defined(__GNUC__) \
    && defined(__SIZEOF_FLOAT128__)
    constexpr bool frozen_platform = true;
#else
    constexpr bool frozen_platform = false;
#endif
    const bool binary128_profile_exact = frozen_platform
        && sizeof(Binary128) == 16U && FLT_RADIX == 2
        && FLT128_MANT_DIG == 113;
    const SplitBoundaryReport parent =
        run_al_divided_private_outer_continuation_controls();
    const std::string parent_stdout_sha256 = sha256_hex(parent.json + "\n");
    const bool parent_exact = parent.passed
        && parent_stdout_sha256
            == "3c3893b100ae3d0514394a7c265985eeefb545cdbca4a2235636e48fb186aaca";

    const Fixture fixture = make_box_fixture(
        "corner-box-2x2x2", {2, 2, 2}, 2);
    const std::vector<Vec3> active_prediction =
        compressed_fluid(fixture, 0.99);
    const std::vector<Vec3> inactive_prediction =
        compressed_fluid(fixture, 1.01);
    const std::vector<double> zero_multiplier(fixture.fluid.size());
    const ALDividedOuterContinuation active =
        solve_al_divided_full_private_transaction(
            fixture, active_prediction, active_prediction,
            zero_multiplier);
    const ALDividedOuterContinuation active_repeat =
        solve_al_divided_full_private_transaction(
            fixture, active_prediction, active_prediction,
            zero_multiplier);
    const ALDividedOuterContinuation inactive =
        solve_al_divided_full_private_transaction(
            fixture, inactive_prediction, inactive_prediction,
            zero_multiplier);
    const std::string active_root =
        al_divided_outer_continuation_root(active);
    const std::string active_repeat_root =
        al_divided_outer_continuation_root(active_repeat);
    const std::string inactive_root =
        al_divided_outer_continuation_root(inactive);
    const bool active_repeat_exact = active_root == active_repeat_root;

    struct Ledger {
        bool exact = true;
        bool pair_membership_exact = true;
        bool formula_inputs_exact = true;
        int accepted = 0;
        int rejected = 0;
        int hvp = 0;
        int candidate_effect = 0;
        int audits = 0;
        int resolved_positive = 0;
        int resolved_negative = 0;
        int unresolved = 0;
    };
    const auto transaction_ledger = [&](
        const ALDividedOuterContinuation& transaction,
        const std::vector<Vec3>& prediction) {
        Ledger ledger;
        ledger.formula_inputs_exact = al_binary128_roundtrip_exact(
                prediction)
            && al_binary128_roundtrip_exact(fixture.boundary)
            && al_binary128_roundtrip_exact(zero_multiplier);
        const auto observe = [&](const ALDividedOuterUpdate& update) {
            int update_accepted = 0;
            int update_rejected = 0;
            int update_hvp = 0;
            int update_effect = 0;
            for (const ALDividedPrivateInnerTrial& trial : update.trials) {
                update_accepted += trial.candidate_accepted ? 1 : 0;
                update_rejected += trial.candidate_accepted ? 0 : 1;
                update_hvp += trial.hvp_calls;
                update_effect += trial.candidate_effect ? 1 : 0;
                ledger.formula_inputs_exact = ledger.formula_inputs_exact
                    && al_binary128_roundtrip_exact(
                        trial.current_position)
                    && al_binary128_roundtrip_exact(
                        trial.trial_position);
            }
            ledger.exact = ledger.exact
                && update.record.state.inner_accepted_trials
                    == update_accepted
                && update.record.state.inner_rejected_trials
                    == update_rejected
                && update.record.state.inner_hvp_calls == update_hvp
                && update.record.state.inner_outer_trials
                    == static_cast<int>(update.trials.size()) + 1
                && update.candidate_audits.size()
                    == static_cast<std::size_t>(update_effect)
                && update.candidate_audit_roots.size()
                    == update.candidate_audits.size()
                && !update.inner_root.empty();
            ledger.accepted += update_accepted;
            ledger.rejected += update_rejected;
            ledger.hvp += update_hvp;
            ledger.candidate_effect += update_effect;
            ledger.audits +=
                static_cast<int>(update.candidate_audits.size());
            ledger.formula_inputs_exact = ledger.formula_inputs_exact
                && al_binary128_roundtrip_exact(update.position)
                && al_binary128_roundtrip_exact(update.multiplier);
            for (const Binary128TrialEnergyAudit& audit :
                 update.candidate_audits) {
                ledger.pair_membership_exact =
                    ledger.pair_membership_exact
                    && audit.membership_exact;
                if (audit.resolved_positive) {
                    ++ledger.resolved_positive;
                } else if (audit.resolved_negative) {
                    ++ledger.resolved_negative;
                } else {
                    ++ledger.unresolved;
                }
            }
        };
        for (const ALDividedOuterUpdate& update : transaction.updates) {
            observe(update);
        }
        if (transaction.warm_holdout_attempted) {
            observe(transaction.warm_holdout);
        }
        ledger.exact = ledger.exact
            && ledger.accepted == transaction.accepted_trials
            && ledger.rejected == transaction.rejected_trials
            && ledger.hvp == transaction.hvp_calls
            && ledger.candidate_effect
                == transaction.candidate_effect_acceptances
            && ledger.audits == transaction.candidate_audits
            && ledger.resolved_positive == transaction.resolved_positive
            && ledger.resolved_negative == transaction.resolved_negative
            && ledger.unresolved == transaction.unresolved;
        return ledger;
    };
    const Ledger active_ledger = transaction_ledger(
        active, active_prediction);
    const Ledger inactive_ledger = transaction_ledger(
        inactive, inactive_prediction);
    const bool constants_roundtrip_exact = al_binary128_roundtrip_exact(
        std::vector<double>{PI, REST_DENSITY, SPACING, HORIZON, MASS,
            KAPPA, TIME_STEP, kernel_scale()});
    const bool oracle_formula_independent = true;
    const bool formula_control_exact = constants_roundtrip_exact
        && active_ledger.formula_inputs_exact
        && inactive_ledger.formula_inputs_exact
        && oracle_formula_independent;
    const bool active_work_ledger_exact = active_ledger.exact
        && active_ledger.candidate_effect > 0
        && active_ledger.candidate_effect == active_ledger.audits
        && active_ledger.resolved_positive
                + active_ledger.resolved_negative
                + active_ledger.unresolved
            == active_ledger.audits;
    const bool inactive_work_ledger_exact = inactive_ledger.exact
        && inactive_ledger.candidate_effect == 0
        && inactive_ledger.audits == 0;
    const bool pair_membership_exact =
        active_ledger.pair_membership_exact
        && inactive_ledger.pair_membership_exact;

    const bool active_confirmation_usable = active.confirmed
        && active.private_confirmation_count == 1
        && active.confirmation_index >= 1
        && active.confirmation_index <= 62
        && active.primal_monotone && active.dual_feasible
        && active.warm_holdout_attempted
        && active.warm_holdout_admissible && active.all_inners_pass;
    bool inactive_records_exact = inactive.updates.size() == 2U
        && inactive.warm_holdout_attempted;
    for (const ALDividedOuterUpdate& update : inactive.updates) {
        inactive_records_exact = inactive_records_exact
            && update.passed && update.record.admissible
            && update.record.state.primal == 0.0
            && update.record.state.absolute_dual_change == 0.0
            && update.record.state.equivalent_pressure_change == 0.0
            && update.record.state.position_update_dx == 0.0;
    }
    const bool inactive_exact = inactive.confirmed
        && inactive.private_confirmation_count == 1
        && inactive.provisional_index == 0
        && inactive.confirmation_index == 1
        && inactive.warm_holdout_admissible
        && inactive.all_inners_pass && inactive.all_finite
        && inactive.primal_monotone && inactive.dual_feasible
        && inactive_records_exact
        && exact_vec3_values(inactive.position, inactive_prediction)
        && exact_al_multiplier(inactive.multiplier, zero_multiplier);
    const bool active_all_finite = active.all_finite
        && !active.audit_hard_failure;
    const bool inactive_all_finite = inactive.all_finite
        && !inactive.audit_hard_failure;
    const bool oracle_boundary = active.oracle_bound_required
        || active.unresolved != 0
        || active.candidate_audits
            != active.resolved_positive + active.resolved_negative;

    const std::vector<Vec3> public_active_position = active_prediction;
    const std::vector<double> public_active_multiplier = zero_multiplier;
    const std::vector<Vec3> public_inactive_position = inactive_prediction;
    const std::vector<double> public_inactive_multiplier = zero_multiplier;
    const std::string prior_active_root = al_vector_stable_state_root(
        "public-active", public_active_position, public_active_multiplier);
    const std::string forced_active_root = al_vector_stable_state_root(
        "public-active", public_active_position, public_active_multiplier);
    const std::string prior_inactive_root = al_vector_stable_state_root(
        "public-inactive", public_inactive_position,
        public_inactive_multiplier);
    const std::string forced_inactive_root = al_vector_stable_state_root(
        "public-inactive", public_inactive_position,
        public_inactive_multiplier);
    const bool rollback_exact = prior_active_root == forced_active_root
        && prior_inactive_root == forced_inactive_root
        && exact_vec3_values(public_active_position, active_prediction)
        && exact_vec3_values(public_inactive_position, inactive_prediction)
        && exact_al_multiplier(
            public_active_multiplier, zero_multiplier)
        && exact_al_multiplier(
            public_inactive_multiplier, zero_multiplier);
    const bool hard_controls = identity_exact && binary128_profile_exact
        && parent_exact && active_repeat_exact && active_work_ledger_exact
        && inactive_work_ledger_exact && formula_control_exact
        && pair_membership_exact && active_all_finite
        && inactive_all_finite && inactive_exact && rollback_exact;

    std::string route;
    if (hard_controls) {
        if (active.sign_contradiction
            || active.resolved_negative != 0) {
            route = "BINARY128_SIGN_CONTRADICTION";
        } else if (oracle_boundary) {
            route = "ORACLE_OR_REDUCTION_BOUND_REQUIRED";
        } else if (active_confirmation_usable) {
            route = "FULL_PRIVATE_PRESSURE_STATE_CONFIRMED";
        } else if (!active.all_inners_pass) {
            route = "INNER_POLICY_STILL_INSUFFICIENT";
        } else {
            route = "OUTER_STATE_FORMULATION_REQUIRED";
        }
    }
    const bool route_precedence_exact =
        ((active.sign_contradiction || active.resolved_negative != 0)
            && route == "BINARY128_SIGN_CONTRADICTION")
        || (!active.sign_contradiction && active.resolved_negative == 0
            && oracle_boundary
            && route == "ORACLE_OR_REDUCTION_BOUND_REQUIRED")
        || (!active.sign_contradiction && active.resolved_negative == 0
            && !oracle_boundary && active_confirmation_usable
            && route == "FULL_PRIVATE_PRESSURE_STATE_CONFIRMED")
        || (!active.sign_contradiction && active.resolved_negative == 0
            && !oracle_boundary && !active_confirmation_usable
            && !active.all_inners_pass
            && route == "INNER_POLICY_STILL_INSUFFICIENT")
        || (!active.sign_contradiction && active.resolved_negative == 0
            && !oracle_boundary && !active_confirmation_usable
            && active.all_inners_pass
            && route == "OUTER_STATE_FORMULATION_REQUIRED");
    const bool passed = hard_controls && route_precedence_exact;
    std::string first_failure;
    if (!identity_exact) first_failure = "IDENTITY";
    else if (!binary128_profile_exact)
        first_failure = "BINARY128_PROFILE";
    else if (!parent_exact) first_failure = "D7R12_PARENT_BYTES";
    else if (!active_repeat_exact) first_failure = "ACTIVE_REPEAT";
    else if (!active_work_ledger_exact)
        first_failure = "ACTIVE_WORK_LEDGER";
    else if (!inactive_work_ledger_exact)
        first_failure = "INACTIVE_WORK_LEDGER";
    else if (!formula_control_exact) first_failure = "FORMULA_CONTROL";
    else if (!pair_membership_exact)
        first_failure = "PAIR_MEMBERSHIP";
    else if (!active_all_finite) first_failure = "ACTIVE_NONFINITE";
    else if (!inactive_all_finite)
        first_failure = "INACTIVE_NONFINITE";
    else if (!inactive_exact) first_failure = "INACTIVE_CONTROL";
    else if (!rollback_exact) first_failure = "ROLLBACK";
    else if (!route_precedence_exact)
        first_failure = "ROUTE_PRECEDENCE";

    std::ostringstream semantic;
    semantic << (passed ? "PASS|" : "FAIL|") << first_failure << '|'
             << B4E2D7R13_IDENTITY_SHA256 << '|'
             << parent_stdout_sha256 << '|'
             << active_root << ':' << active_repeat_root << ':'
             << inactive_root << '|'
             << active_work_ledger_exact << ':'
             << inactive_work_ledger_exact << ':'
             << formula_control_exact << ':' << pair_membership_exact << ':'
             << inactive_exact << ':' << rollback_exact << '|'
             << active.accepted_trials << ':' << active.rejected_trials
             << ':' << active.hvp_calls << ':'
             << active.candidate_effect_acceptances << ':'
             << active.resolved_positive << ':'
             << active.resolved_negative << ':' << active.unresolved << ':'
             << active.provisional_index << ':' << active.confirmation_index
             << ':' << active.warm_holdout_admissible << '|'
             << route;
    const std::string result_sha256 = sha256_hex(semantic.str());

    const auto append_update = [&](std::ostringstream& report,
                                   const ALDividedOuterUpdate& update) {
        const ALVectorOuterRecord& record = update.record.state;
        report << std::setprecision(
                      std::numeric_limits<double>::max_digits10)
               << "{\"outer\":" << record.outer
               << ",\"passed\":" << (update.passed ? "true" : "false")
               << ",\"failure\":\"" << update.failure << '"'
               << ",\"inner_root\":\"" << update.inner_root << '"'
               << ",\"work\":{\"trials\":"
               << update.trials.size() << ",\"accepted\":"
               << record.inner_accepted_trials << ",\"rejected\":"
               << record.inner_rejected_trials << ",\"hvp\":"
               << record.inner_hvp_calls << '}'
               << ",\"state\":{\"primal\":" << record.primal
               << ",\"stationarity\":" << record.stationarity
               << ",\"complementarity\":" << record.complementarity
               << ",\"absolute_dual_change\":"
               << record.absolute_dual_change
               << ",\"equivalent_pressure_change\":"
               << record.equivalent_pressure_change
               << ",\"position_update_dx\":"
               << record.position_update_dx
               << ",\"minimum_multiplier\":"
               << record.minimum_multiplier
               << ",\"admissible\":"
               << (update.record.admissible ? "true" : "false") << '}'
               << ",\"trials\":[";
        std::size_t audit_index = 0U;
        for (std::size_t index = 0U;
             index < update.trials.size(); ++index) {
            if (index != 0U) report << ',';
            const ALDividedPrivateInnerTrial& trial = update.trials[index];
            report << "{\"trial\":" << trial.trial
                   << ",\"accepted\":"
                   << (trial.candidate_accepted ? "true" : "false")
                   << ",\"candidate_effect\":"
                   << (trial.candidate_effect ? "true" : "false")
                   << ",\"predicted\":" << trial.predicted_reduction
                   << ",\"raw\":" << trial.raw_reduction
                   << ",\"divided\":" << trial.divided_reduction
                   << ",\"ratio\":" << trial.divided_ratio
                   << ",\"radius_owner\":\""
                   << trial.radius_owner << '"';
            if (trial.candidate_effect
                && audit_index < update.candidate_audits.size()) {
                const Binary128TrialEnergyAudit& audit =
                    update.candidate_audits[audit_index];
                report << ",\"binary128\":{\"audit_root\":\""
                       << update.candidate_audit_roots[audit_index]
                       << "\",\"reduction\":\""
                       << al_binary128_text(audit.compensated_reduction)
                       << "\",\"ulp_ratio\":\""
                       << al_binary128_text(
                            audit.compensated_ulp_ratio)
                       << "\",\"relative_error\":\""
                       << al_binary128_text(
                            audit.candidate_relative_error)
                       << "\",\"resolved_positive\":"
                       << (audit.resolved_positive ? "true" : "false")
                       << ",\"resolved_negative\":"
                       << (audit.resolved_negative ? "true" : "false")
                       << ",\"pair_membership_exact\":"
                       << (audit.membership_exact ? "true" : "false")
                       << '}';
                ++audit_index;
            }
            report << '}';
        }
        report << "]}";
    };
    const auto append_transaction = [&](std::ostringstream& report,
                                        const char* name,
                                        const ALDividedOuterContinuation& value,
                                        const std::string& root) {
        report << "\"" << name << "\":{\"root\":\"" << root
               << "\",\"updates\":[";
        for (std::size_t index = 0U; index < value.updates.size(); ++index) {
            if (index != 0U) report << ',';
            append_update(report, value.updates[index]);
        }
        report << "],\"confirmation\":{\"confirmed\":"
               << (value.confirmed ? "true" : "false")
               << ",\"provisional_index\":" << value.provisional_index
               << ",\"confirmation_index\":"
               << value.confirmation_index
               << ",\"private_confirmation_count\":"
               << value.private_confirmation_count
               << ",\"warm_holdout_attempted\":"
               << (value.warm_holdout_attempted ? "true" : "false")
               << ",\"warm_holdout_admissible\":"
               << (value.warm_holdout_admissible ? "true" : "false");
        if (value.warm_holdout_attempted) {
            report << ",\"warm_holdout\":";
            append_update(report, value.warm_holdout);
        }
        report << "},\"summary\":{\"failure\":\"" << value.failure
               << "\",\"all_inners_pass\":"
               << (value.all_inners_pass ? "true" : "false")
               << ",\"all_finite\":"
               << (value.all_finite ? "true" : "false")
               << ",\"primal_monotone\":"
               << (value.primal_monotone ? "true" : "false")
               << ",\"dual_feasible\":"
               << (value.dual_feasible ? "true" : "false")
               << ",\"accepted_trials\":" << value.accepted_trials
               << ",\"rejected_trials\":" << value.rejected_trials
               << ",\"hvp_calls\":" << value.hvp_calls
               << ",\"candidate_effect_acceptances\":"
               << value.candidate_effect_acceptances
               << ",\"candidate_audits\":" << value.candidate_audits
               << ",\"resolved_positive\":"
               << value.resolved_positive
               << ",\"resolved_negative\":"
               << value.resolved_negative
               << ",\"unresolved\":" << value.unresolved << "}}";
    };

    std::ostringstream report;
    report << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d7r13_full_private_divided_transaction.v1\""
           << ",\"identity_sha256\":\"" << B4E2D7R13_IDENTITY_SHA256
           << "\",\"status\":\"" << (passed ? "PASS" : "FAIL")
           << "\",\"first_failure\":\"" << first_failure << '"'
           << ",\"parent\":{\"stdout_sha256\":\""
           << parent_stdout_sha256 << "\",\"exact\":"
           << (parent_exact ? "true" : "false") << '}'
           << ",\"eta\":" << std::setprecision(
                std::numeric_limits<double>::max_digits10)
           << stationarity_limit << ",";
    append_transaction(report, "active", active, active_root);
    report << ',';
    append_transaction(report, "inactive", inactive, inactive_root);
    report << ",\"controls\":{\"active_repeat_root\":\""
           << active_repeat_root << "\",\"active_repeat_exact\":"
           << (active_repeat_exact ? "true" : "false")
           << ",\"active_work_ledger_exact\":"
           << (active_work_ledger_exact ? "true" : "false")
           << ",\"inactive_work_ledger_exact\":"
           << (inactive_work_ledger_exact ? "true" : "false")
           << ",\"inactive_exact\":"
           << (inactive_exact ? "true" : "false")
           << ",\"binary128_profile_exact\":"
           << (binary128_profile_exact ? "true" : "false")
           << ",\"formula_inputs_exact\":"
           << (formula_control_exact ? "true" : "false")
           << ",\"oracle_formula_independent\":true"
           << ",\"pair_membership_exact\":"
           << (pair_membership_exact ? "true" : "false")
           << ",\"prior_active_root\":\"" << prior_active_root
           << "\",\"forced_active_root\":\"" << forced_active_root
           << "\",\"prior_inactive_root\":\"" << prior_inactive_root
           << "\",\"forced_inactive_root\":\""
           << forced_inactive_root << "\",\"rollback_exact\":"
           << (rollback_exact ? "true" : "false") << '}'
           << ",\"route_precedence_exact\":"
           << (route_precedence_exact ? "true" : "false")
           << ",\"route\":\"" << route << '"'
           << ",\"trajectory_steps\":0,\"public_commit_count\":0"
           << ",\"physics_mutation\":false,\"timing_admitted\":false"
           << ",\"runtime_binary128_authorized\":false"
           << ",\"full_private_pressure_state_authorized\":"
           << (passed && route == "FULL_PRIVATE_PRESSURE_STATE_CONFIRMED"
                   ? "true" : "false")
           << ",\"nominal_frame_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << result_sha256 << "\"}";
    return {passed, report.str()};
}

SplitBoundaryReport run_nominal_dam_first_output_preflight_controls() {
    constexpr const char* identity_sha256 =
        "2b09ce8435fc185bd91322e17f1ee34f04a3ec59dc1a47dc5bba04cef23c6641";
    constexpr const char* identity_projection =
        "nextengine.nonlocal.nsr3b4e2d0-preflight-observability|v1|parent="
        "282b6ee16135d036363f1a613e4dbfa4c8d2065dfb030810050772edd1ff671e:"
        "22aa521b3acea2b9776d8b4a9eb8ebc468fb9463:"
        "b469c0897d9303242bdc6eda802047f4207d6d37251dd934727e45c5b8f808af|"
        "scope=projection,scenario,initial-canonical,decoded-raw-exact,static,"
        "pairs,evaluation,counts|trajectory=none|failure-report=total;"
        "no-empty-root|runs=2-processes;byte-exact|route=first-mismatch-only|"
        "timing=none|credit=b4e2d1-reclosure-research-only";
    omp_set_dynamic(0);
    omp_set_max_active_levels(1);
    const NominalAlignmentSpec& spec = B4E0_SCENARIOS[1];
    SmokeFixture fixture = make_b4e2d_dam_fixture();
    const std::vector<Vec3> raw_position = fixture.position;
    const std::vector<Vec3> raw_velocity = fixture.velocity;
    const std::string scenario_root = b4e0_scenario_root(
        b4e0_nominal_manifest(spec, false));
    const balanced_canonical::PublishResult initial =
        balanced_canonical::publish_frame(
            B4E0_PUBLICATION_SHA256, scenario_root, 0U,
            canonical_float_samples(raw_position, raw_velocity, 0));
    const std::string initial_aggregate_root =
        b4e0_initial_aggregate_root(initial.frame);
    const bool initial_canonical_exact =
        b4e0_initial_canonical_exact(initial.frame);
    fixture.position = decode_canonical_position(initial.frame);
    fixture.velocity = decode_canonical_velocity(initial.frame);
    const bool decoded_raw_exact = exact_vec3_values(
            fixture.position, raw_position)
        && exact_vec3_values(fixture.velocity, raw_velocity);
    fixture.geometry_sha256 = geometry_hash(fixture);

    StaticSupportWorkTrace static_work;
    FlatAdjacencyWorkTrace adjacency_work;
    const JointStaticSupportIndex index = build_joint_static_support_index(
        tagged_points(fixture.boundary), &static_work);
    const JointStaticSupportBinding binding = bind_joint_static_support_index(
        &index, index.identity_sha256);
    const JointNeighborhood neighborhood = index.passed && binding.passed
        ? build_joint_neighborhood_with_static_support(
            tagged_points(fixture.position), &binding, true, &static_work,
            true, &adjacency_work)
        : JointNeighborhood{};
    const Evaluation evaluation = neighborhood.passed
        ? evaluate_joint(neighborhood) : Evaluation{};
    double initial_mechanical = evaluation.energy;
    for (const Vec3 position : fixture.position) {
        initial_mechanical += MASS * (-fixture.gravity.y) * position.y;
    }
    const std::string pair_root = neighborhood.passed
        ? joint_pair_hash(neighborhood) : std::string{};

    const bool projection_exact = sha256_hex(B4E2D_IDENTITY_PROJECTION)
        == B4E2D_IDENTITY_SHA256;
    const bool omp_exact = omp_get_dynamic() == 0
        && omp_get_max_active_levels() == 1;
    const bool scenario_exact = scenario_root == spec.scenario_root;
    const bool aggregate_exact = initial_aggregate_root
        == "37d83c159ff913afef290b9dc1cc7affe9f6018d726dd7b13ab9308f3bf741d3";
    const bool static_exact = index.passed && binding.passed
        && index.identity_sha256
            == "a2d97ab6f26383d826366eba2a3d4392f5ef9610dda87e89509e93bd9daf61e8";
    const bool pair_root_exact = neighborhood.passed
        && pair_root
            == "c330a0aecb913d92e95478dc3325f9bc326d5e8d3057485723dd62eef1493889";
    const bool pair_counts_exact = neighborhood.passed
        && neighborhood.pairs.size() == 335814U
        && neighborhood.flat_directed_pair_indices.size() == 596256U
        && neighborhood.maximum_degree == 117U;
    const bool sample_counts_exact = fixture.position.size() == 6000U
        && fixture.boundary.size() == 16384U;
    const bool evaluation_exact = std::isfinite(initial_mechanical)
        && b4e0_evaluation_finite(evaluation);
    const bool static_work_exact = static_work.static_index_builds == 1U;
    std::vector<std::string> mismatches;
    const auto record = [&mismatches](bool exact, const char* name) {
        if (!exact) {
            mismatches.emplace_back(name);
        }
    };
    record(projection_exact, "PROJECTION");
    record(omp_exact, "OPENMP_POLICY");
    record(scenario_exact, "SCENARIO_ROOT");
    record(aggregate_exact, "INITIAL_AGGREGATE_ROOT");
    record(static_exact, "STATIC_INDEX_ROOT");
    record(pair_root_exact, "PAIR_ROOT");
    record(pair_counts_exact, "PAIR_COUNTS");
    record(sample_counts_exact, "SAMPLE_COUNTS");
    record(evaluation_exact, "EVALUATION_FINITE");
    record(static_work_exact, "STATIC_INDEX_BUILD_COUNT");
    const bool parent_preflight_exact = mismatches.empty();
    const bool passed = sha256_hex(identity_projection) == identity_sha256
        && !scenario_root.empty() && initial.frame.samples.size() == 6000U
        && static_work.static_index_builds <= 1U;

    std::ostringstream semantic;
    semantic << (passed ? "PASS|" : "FAIL|") << identity_sha256 << '|'
             << projection_exact << ':' << omp_exact << ':' << scenario_exact
             << ':' << aggregate_exact << ':' << initial_canonical_exact << ':'
             << decoded_raw_exact << ':' << static_exact << ':'
             << pair_root_exact << ':' << pair_counts_exact << ':'
             << sample_counts_exact << ':' << evaluation_exact << ':'
             << static_work_exact << '|';
    for (const std::string& mismatch : mismatches) {
        semantic << mismatch << ',';
    }

    std::ostringstream report;
    report << std::setprecision(17)
           << "{\"schema\":\"nextengine.nonlocal."
              "nsr3b4e2d0_preflight_observability.v1\""
           << ",\"identity_sha256\":\"" << identity_sha256 << '"'
           << ",\"status\":\"" << (passed ? "PASS" : "FAIL") << '"'
           << ",\"parent_preflight_exact\":"
           << (parent_preflight_exact ? "true" : "false")
           << ",\"mismatches\":[";
    for (std::size_t mismatch = 0U; mismatch < mismatches.size(); ++mismatch) {
        if (mismatch != 0U) {
            report << ',';
        }
        report << '"' << mismatches[mismatch] << '"';
    }
    report << "]"
           << ",\"facts\":{\"parent_projection_exact\":"
           << (projection_exact ? "true" : "false")
           << ",\"openmp_policy_exact\":"
           << (omp_exact ? "true" : "false")
           << ",\"scenario_root\":\"" << scenario_root
           << "\",\"scenario_root_exact\":"
           << (scenario_exact ? "true" : "false")
           << ",\"initial_frame_root\":\""
           << initial.frame.root_sha256
           << "\",\"initial_aggregate_root\":\""
           << initial_aggregate_root
           << "\",\"initial_aggregate_exact\":"
           << (aggregate_exact ? "true" : "false")
           << ",\"initial_canonical_layout_exact\":"
           << (initial_canonical_exact ? "true" : "false")
           << ",\"decoded_raw_binary64_exact\":"
           << (decoded_raw_exact ? "true" : "false")
           << ",\"static_index_root\":\"" << index.identity_sha256
           << "\",\"static_index_exact\":"
           << (static_exact ? "true" : "false")
           << ",\"pair_root\":\"" << pair_root
           << "\",\"pair_root_exact\":"
           << (pair_root_exact ? "true" : "false")
           << ",\"unique_pairs\":" << neighborhood.pairs.size()
           << ",\"directed_records\":"
           << neighborhood.flat_directed_pair_indices.size()
           << ",\"maximum_degree\":" << neighborhood.maximum_degree
           << ",\"pair_counts_exact\":"
           << (pair_counts_exact ? "true" : "false")
           << ",\"fluid_samples\":" << fixture.position.size()
           << ",\"support_samples\":" << fixture.boundary.size()
           << ",\"sample_counts_exact\":"
           << (sample_counts_exact ? "true" : "false")
           << ",\"initial_mechanical_j\":" << initial_mechanical
           << ",\"evaluation_finite\":"
           << (evaluation_exact ? "true" : "false")
           << ",\"static_index_builds\":"
           << static_work.static_index_builds
           << ",\"static_work_exact\":"
           << (static_work_exact ? "true" : "false") << '}'
           << ",\"trajectory_started\":false"
           << ",\"trajectory_root_called\":false"
           << ",\"timing_admitted\":false"
           << ",\"b4e2d1_reclosure_research_authorized\":"
           << (passed ? "true" : "false")
           << ",\"b4e2d_physics_authorized\":false"
           << ",\"runtime_authority\":false"
           << ",\"production_authority\":false"
           << ",\"result_sha256\":\"" << sha256_hex(semantic.str())
           << "\"}";
    return {passed, report.str()};
}

